export const ARABIC_GUIDES: Record<string, ArabicGuide> = {
 "applying-to-the-islamic-university": {
  "titleAr": "التقديم إلى الجامعة الإسلامية",
  "summaryAr": "نظام ٢٠٢٥ و٢٠٢٦ خطوة بخطوة، من منصة «ادرس في السعودية» والطلب الثاني في «منحتي» إلى الموافقة النهائية والتأشيرة التعليمية والوصول، مع فترات التقديم السابقة، والكليات ومدد البرامج، والمنحة الكاملة والجزئية، وكيف يُرتَّب المتقدمون من الداخل، وما تجهزه الآن.",
  "bodyHtmlAr": "<blockquote><p>مهم: التقديم مجاني وتقوم به بنفسك على <a href=\"https://studyinsaudi.sa/\">studyinsaudi.sa</a>. ليس للجامعة مكاتب ولا وكلاء في الخارج. وكل من يطلب منك مالًا للتقديم أو لتسريع الإجراءات أو لضمان مقعد فليس من الجامعة. لا تدفع له ولا تعطه بيانات دخولك.</p></blockquote>\n<p>روجع في ٩ نوفمبر ٢٠٢٦. منذ ٢٠٢٥ تجري الرحلة كلها عبر منصة وطنية واحدة، ثم طلب ثانٍ على منصة الجامعة نفسها، ثم موافقة نهائية من وزارة التعليم، ثم تأشيرة تعليمية إلكترونية. ويصل الطلاب الجدد بهوية زائر لا بإقامة.</p>\n<h2>متى يفتح التقديم</h2>\n<p>تفتح الجامعة باب التقديم للطلاب الدوليين في مرحلة البكالوريوس مرة في السنة على منصة «ادرس في السعودية»، وتعلن المواعيد في كل موسم. وكانت الفترة الرئيسية في السنوات الأخيرة في الربيع، مع إعادة فتح قصيرة لبعض المتقدمين. والمنصة مغلقة خارج هذه الفترة.</p>\n<table><thead><tr><th>الدورة</th><th>الفترة</th></tr></thead><tbody>\n<tr><td>خريف ٢٠٢٣</td><td>من ٧ سبتمبر إلى ٧ ديسمبر ٢٠٢٣</td></tr>\n<tr><td>٢٠٢٤</td><td>من ٢١ أبريل إلى ٢٨ يوليو ٢٠٢٤</td></tr>\n<tr><td>٢٠٢٥، لعام ١٤٤٧</td><td>من ١ مايو إلى ١٤ يونيو ٢٠٢٥</td></tr>\n<tr><td>٢٠٢٦، لعام ١٤٤٨</td><td>من ١٩ أبريل إلى ٢١ مايو ٢٠٢٦</td></tr>\n<tr><td>٢٠٢٦، دورة إضافية (الدورة الثانية للمنح الكاملة، والثالثة للمنح الجزئية)</td><td>من ١٦ سبتمبر إلى ٦ أكتوبر ٢٠٢٦</td></tr>\n</tbody></table>\n<p>الدورات الإضافية كدورة سبتمبر ٢٠٢٦ قصيرة، وهي مفتوحة أيضًا لمن لم يُقبلوا في وقت سابق من السنة. تابع studyinsaudi.sa وإعلانات الجامعة من شهر مارس، وجهّز كل مستند قبل فتح الباب. فالفترات الأخيرة استمرت خمسة إلى ستة أسابيع، وأيامها الأخيرة هي الأكثر ازدحامًا، فقدّم في أول الفترة لا في يومها الأخير.</p>\n<h2>من يستطيع التقديم</h2>\n<ul>\n<li><strong>العمر:</strong> سبع عشرة سنة على الأقل ولا يزيد على خمس وعشرين.</li>\n<li><strong>الشهادة الثانوية:</strong> الثانوية العامة أو ما يعادلها، ولم يمضِ عليها أكثر من خمس سنوات. والكليات العلمية تشترط المسار العلمي. والشهادة القديمة من أكثر أسباب الرفض شيوعًا.</li>\n<li><strong>محل إقامتك:</strong> المتقدمون للمنحة الكاملة يجب أن يكونوا مقيمين خارج السعودية.</li>\n<li><strong>السجل:</strong> حسن السيرة والسلوك، وألا يكون قد فُصل من جامعة لأسباب تأديبية، وألا يكون على منحة سعودية أخرى.</li>\n<li><strong>الصحة:</strong> اللياقة الطبية، مع تقرير طبي يثبت سلامتك الصحية.</li>\n<li><strong>التزكية:</strong> تزكيتان علميتان شرط من شروط القبول، لا أمر إضافي.</li>\n<li><strong>كلية القرآن الكريم:</strong> حفظ القرآن كاملًا، ويُتحقق منه باختبار شفهي.</li>\n<li><strong>الهندسة والحاسب والعلوم:</strong> هذه الكليات تدرّس بالإنجليزية وتطلب الآيلتس أو التوفل، إلا إن كانت دراستك السابقة بالإنجليزية أو كنت من بلد الإنجليزية فيه لغة رسمية أو رئيسية. والكليات الشرعية والعربية تدرّس بالعربية.</li>\n<li><strong>أنهيت الثانوية في السعودية؟</strong> تُعدّ متقدمًا داخليًا حتى لو قدّمت على منحة خارجية، ويلزمك تقديم نتيجة اختبار القدرات العامة، ومعها الاختبار التحصيلي للكليات العلمية.</li>\n<li><strong>الدراسة في المدينة للإخوة فقط.</strong> وتستطيع الأخوات الدراسة مع الجامعة عن بُعد، والطرق الأخرى في <a href=\"/ar/ask/sisters-study\">أين تدرس الأخوات؟</a></li>\n</ul>\n<h2>البرامج</h2>\n<p>هذه برامج البكالوريوس المتاحة لطلاب المنح لعام ١٤٤٨.</p>\n<table><thead><tr><th>الكلية</th><th>البرامج</th><th>المدة</th><th>لغة التدريس</th></tr></thead><tbody>\n<tr><td>الشريعة</td><td>الشريعة</td><td>٤ سنوات</td><td>العربية</td></tr>\n<tr><td>العقيدة والدعوة</td><td>العقيدة والدعوة</td><td>٤ سنوات</td><td>العربية</td></tr>\n<tr><td>القرآن الكريم</td><td>القرآن الكريم</td><td>٤ سنوات</td><td>العربية</td></tr>\n<tr><td>الحديث</td><td>الحديث</td><td>٤ سنوات</td><td>العربية</td></tr>\n<tr><td>اللغة العربية والعلوم الإنسانية</td><td>اللغة العربية، الإعلام</td><td>٤ سنوات</td><td>العربية</td></tr>\n<tr><td>القانون</td><td>القانون (الأنظمة)</td><td>٤ سنوات</td><td>العربية</td></tr>\n<tr><td>الأعمال</td><td>الاقتصاد</td><td>٤ سنوات</td><td>العربية</td></tr>\n<tr><td>الهندسة</td><td>الكيميائية، المدنية، الكهربائية، الصناعية، الميكانيكية</td><td>٥ سنوات</td><td>الإنجليزية</td></tr>\n<tr><td>الحاسب</td><td>علوم الحاسب، علم البيانات، تقنية المعلومات</td><td>٥ سنوات</td><td>الإنجليزية</td></tr>\n<tr><td>العلوم</td><td>الكيمياء، العلوم البيئية، الرياضيات المالية والاكتوارية، الرياضيات، الفيزياء</td><td>٤ سنوات</td><td>الإنجليزية</td></tr>\n</tbody></table>\n<p>الجديد في ١٤٤٨: صار القانون كلية مستقلة هي كلية القانون، وصار الاقتصاد في كلية الأعمال. وتُعقد محاضرات الاثنين في مباني كلية الشريعة.</p>\n<h3>معهد اللغة العربية (المعهد)</h3>\n<p>يقدم المعهد دبلومين في العربية قبل الكلية: الدبلوم المتوسط، ومدته سنتان، والدبلوم المشارك، ومدته سنة. وأنت لا تختار المعهد، بل تضعك الجامعة فيه إن احتاجت عربيتك إلى ذلك، والطلاب الأقوياء في العربية يبدؤون في كلياتهم مباشرة. وسنوات درجتك تأتي بعد أي مدة تقضيها في المعهد.</p>\n<h3>اختر كليتك بعناية</h3>\n<p>لا يستطيع طالب المنحة الانتقال إلى كلية أخرى بعد القبول، فأنت تدرس البرنامج والكلية اللذين قُبلت فيهما.</p>\n<h2>المنحة الكاملة والمنحة الجزئية</h2>\n<p>تقدم الجامعة لطلاب البكالوريوس الدوليين نوعين من المنح، وكلاهما دراسة بدوام كامل في الحرم الجامعي بالمدينة، ويبيّن عرضك على «ادرس في السعودية» أيهما حصلت عليه.</p>\n<table><thead><tr><th>الموضوع</th><th>الكاملة (منحة خارجية)</th><th>الجزئية (منحة داخلية)</th></tr></thead><tbody>\n<tr><td><strong>لمن</strong></td><td>المتقدمون غير السعوديين المقيمون خارج السعودية</td><td>المتقدمون غير السعوديين المقيمون في السعودية بإقامة نظامية، ويلزمهم الاحتفاظ بها طوال دراستهم</td></tr>\n<tr><td><strong>الرسوم الدراسية</strong></td><td>مجانًا</td><td>مجانًا</td></tr>\n<tr><td><strong>المكافأة الشهرية</strong></td><td>نعم</td><td>لا</td></tr>\n<tr><td><strong>بدل الوصول وبدل التخرج</strong></td><td>نعم: مكافأة شهرين عند الوصول، ومكافأة ثلاثة أشهر عند التخرج</td><td>لا</td></tr>\n<tr><td><strong>تذكرة إلى بلدك كل سنة</strong></td><td>نعم، على الدرجة السياحية المخفضة، ما لم تعطك جهة أخرى تذكرة</td><td>لا</td></tr>\n<tr><td><strong>السكن</strong></td><td>سكن جامعي مجاني</td><td>لا سكن مجاني، وتُعرض غرف مدفوعة في الوحدة ١٣ عند توفر أماكن</td></tr>\n<tr><td><strong>الوجبات المدعومة</strong></td><td>نعم</td><td>لا</td></tr>\n<tr><td><strong>شرط إضافي</strong></td><td>لا يوجد</td><td>إن كنت موظفًا، فموافقة جهة عملك الكتابية على الدراسة</td></tr>\n</tbody></table>\n<p>المزيد في <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة: المكافأة والبدلات والتذاكر</a> و<a href=\"/ar/guides/unit-13-and-paid-university-housing\">الوحدة ١٣ والسكن الجامعي المدفوع</a>.</p>\n<h2>التقديم من داخل السعودية</h2>\n<p>إن كنت مقيمًا في السعودية إقامة نظامية فإنك تقدّم على منحة جزئية (داخلية). وإن أنهيت الثانوية في السعودية عوملت متقدمًا داخليًا في كل شروط القبول، حتى لو قدّمت على منحة كاملة.</p>\n<p>يلزم المتقدمين من الداخل أداء اختبار القدرات العامة، وللهندسة والحاسب والعلوم يلزم أيضًا الاختبار التحصيلي. ولا يُنظر في الطلب دون هذه النتائج. وتُرتَّب المقاعد بنسبة موزونة:</p>\n<table><thead><tr><th>الكليات</th><th>الشهادة الثانوية</th><th>اختبار القدرات العامة</th><th>الاختبار التحصيلي</th></tr></thead><tbody>\n<tr><td>الكليات الشرعية والعربية وكليتا القانون والأعمال</td><td>٥٠٪</td><td>٥٠٪</td><td>لا يُحتسب</td></tr>\n<tr><td>كليات الهندسة والحاسب والعلوم</td><td>٣٠٪</td><td>٣٠٪</td><td>٤٠٪</td></tr>\n</tbody></table>\n<p>ثم يُرتَّب المتقدمون بحسب النسبة وترتيب رغباتهم، ويأخذ كل برنامج من الطلاب بقدر مقاعده. <strong>مثال محسوب:</strong> في الشريعة، شهادة ثانوية بنسبة ٩٠٪ ودرجة قدرات ٨٠ تعطيان نسبة موزونة ٤٥ + ٤٠ = ٨٥.</p>\n<h2>جهّز الآن للفترة القادمة</h2>\n<ol>\n<li><strong>جواز السفر:</strong> ساريًا إلى ما بعد موعد وصولك المتوقع بمدة كافية. وكل نموذج يجب أن يحمل اسمك كما هو مطبوع فيه تمامًا.</li>\n<li><strong>الشهادة الثانوية وكشف الدرجات.</strong> تأكد أنها ستظل دون خمس سنوات حين تقدّم.</li>\n<li><strong>شهادة خلو السوابق</strong> من بلدك. تستغرق في كثير من البلدان أسابيع، فابدأ مبكرًا.</li>\n<li><strong>للمنحة الجزئية:</strong> موافقة جهة عملك.</li>\n<li><strong>تزكيتان علميتان</strong> من جهات أو مؤسسات أو علماء معروفين في بلدك، أو من شخصيات معروفة تعتمدها الجامعة. والاثنتان مطلوبتان.</li>\n<li><strong>تقرير طبي</strong> يثبت سلامتك الصحية ولياقتك للدراسة.</li>\n<li><strong>شهادة الميلاد</strong>، أو شهادة التسنين الرسمية إن لم تكن لديك شهادة ميلاد.</li>\n<li><strong>الآيلتس أو التوفل</strong> للهندسة والحاسب والعلوم، إلا إن كنت معفى.</li>\n<li><strong>الصورة الشخصية:</strong> بمواصفات صورة الجواز، بخلفية بيضاء سادة، وملامح طبيعية، وبغير ثياب بيضاء. والاستوديو يتقنها.</li>\n<li><strong>ترجمة عربية</strong> لكل ما ليس بالعربية، من مترجم معتمد.</li>\n<li><strong>شهادات إضافية</strong> في حفظ القرآن أو اللغة العربية أو المتون أو الإجازات إن كانت عندك، فهي تُحسب لك في الكليات الشرعية.</li>\n<li><strong>مسح ضوئي ملون واضح</strong> لكل شيء. لا تستعمل صور الجوال.</li>\n<li><strong>بريد إلكتروني تفتحه كل يوم،</strong> بما فيه مجلد الرسائل غير المرغوبة. فبريدك المسجل هو قناة الجامعة الرسمية، وإن فقدت الوصول إليه أمكن أن يتوقف قبولك أو تأشيرتك ويُحذف طلبك.</li>\n</ol>\n<p>كل ما تدخله في طلبك يجب أن يسنده مستند. والبيانات التي لا مستند لها لا تُقبل، والتقديم لا يُلزم الجامعة بقبولك.</p>\n<h2>من التقديم إلى الوصول</h2>\n<ol>\n<li><strong>قدّم على «ادرس في السعودية».</strong> أنشئ حسابك، وأدخل بياناتك، وارفع مستنداتك، واختر برامجك. تستطيع اختيار ما يصل إلى ٢٥ برنامجًا في أكثر من عشر جامعات، ويظهر لكل برنامج هل منحته كاملة أو جزئية أو مدفوعة. أرسل الطلب قبل الموعد واحتفظ برقمه.</li>\n<li><strong>أكمل الطلب الثاني على «منحتي».</strong> ترسل إليك الجامعة بالبريد بيانات الدخول إلى <a href=\"https://minhatee2.iu.edu.sa/\">منحتي</a>، منصتها الخاصة، وتطلب بيانات ومستندات إضافية مع ترجمتها العربية. وكثيرًا ما تكون المهلة نحو ٢٤ ساعة فقط، فبادر في اليوم نفسه.</li>\n<li><strong>احضر المقابلة أو اختبار تحديد المستوى إن دُعيت.</strong> المقابلة عن بُعد. واختبار تحديد مستوى اللغة العربية للمتقدمين للمنحة الكاملة الذين تختار الجامعة تقييمهم. وهو ليس نجاحًا ورسوبًا، وإنما يحدد هل تبدأ في المعهد وفي أي مستوى، أو تنتقل مباشرة إلى كليتك، فأجب بصدق. فالمستوى الأعلى من قدرتك يجعل سنتك الأولى أصعب بكثير.</li>\n<li><strong>اقبل عرضك خلال ٥ أيام.</strong> يصلك القبول المبدئي بالبريد ويظهر في المنصة بانتظار تأكيدك. وقبولك يلغي طلباتك إلى الجامعات الأخرى. وإن تجاهلته سقط العرض. وأعد كتابة اسمك الأول واسم عائلتك كما في جوازك تمامًا.</li>\n<li><strong>انتظر القبول النهائي.</strong> «منحتي» تُظهر قبولًا مبدئيًا فقط، وهو مشروط. أما القبول النهائي فيظهر في «ادرس في السعودية»، وهي السجل الرسمي، وهو المرحلة الوحيدة التي تؤدي إلى التأشيرة.</li>\n<li><strong>املأ طلب التأشيرة</strong> حين تطلبه المنصة. ويجب أن تكون خارج السعودية حين ترسله، وإلا رُفض.</li>\n<li><strong>ادفع رسوم التأشيرة التعليمية</strong> عبر الرابط الذي يُرسل إليك.</li>\n<li><strong>سجّل بصماتك</strong> عبر تطبيق وزارة الخارجية <strong>Saudi Visa Bio</strong>، أو في مركز تأشيرات معتمد أو سفارة سعودية إن لم يعمل التطبيق معك. وأكمل أي فحوص طبية تُطلب منك.</li>\n<li><strong>استلم التأشيرة.</strong> تظهر في حسابك على «ادرس في السعودية» وتُرسل بالبريد. وإن سجلت بصماتك بالتطبيق فلا تحتاج إلى زيارة السفارة.</li>\n<li><strong>اطلب تذكرة الوصول على «منحتي»،</strong> واسمك كما في جوازك تمامًا، وانتظر صدورها. فطلاب المنحة الكاملة يصلون بتذكرة الجامعة، فلا تشترِ تذكرة بنفسك.</li>\n<li><strong>احضر في الفصل الذي عُرض عليك.</strong> أسابيعك الأولى في <a href=\"/ar/guides/first-30-days-in-madinah\">أيامك الثلاثون الأولى في المدينة</a>، والحياة بلا إقامة في <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a>.</li>\n</ol>\n<h2>ماذا تعني حالة طلبك</h2>\n<table><thead><tr><th>الحالة</th><th>ما تفعله</th></tr></thead><tbody>\n<tr><td>قيد المراجعة</td><td>لم تقدّم لك أي جامعة عرضًا بعد. تابع بريدك والمنصة.</td></tr>\n<tr><td>معاد للتحديث</td><td>شيء ناقص أو غير واضح. صححه وأعد الإرسال عبر الرابط قبل الموعد.</td></tr>\n<tr><td>مقبول مبدئيًا بانتظار تأكيدك</td><td>لديك عرض. اقبله أو ارفضه خلال ٥ أيام.</td></tr>\n<tr><td>استكمال إجراءات القبول</td><td>قبلت العرض. انتظر الموافقة النهائية من الوزارة، ثم خطوات التأشيرة.</td></tr>\n<tr><td>لا توجد سجلات مطابقة</td><td>لم تقبل أي جامعة هذا الطلب. قدّم مرة أخرى في الفترة القادمة.</td></tr>\n</tbody></table>\n<h2>القبول المبدئي ليس نهائيًا</h2>\n<p>القبول المبدئي يعني أن جامعة رشّحت اسمك، والقبول النهائي يعني أن الوزارة وافقت. فلا تستقل من عملك ولا تترك بيتك ولا تحجز طيرانك على القبول المبدئي وحده. فبعض المقبولين مبدئيًا يُنقلون إلى فصل لاحق، وبعضهم يُعرض عليه عام من دراسة العربية عن بُعد أولًا.</p>\n<p>خطط للوصول في الفصل الذي عُرض عليك. فتحت التأشيرة التعليمية يمكن أن يعيد طلبُ تأخير الوصول طلبَك إلى الوراء. انظر <a href=\"/ar/ask/defer-my-place\">هل أستطيع تأجيل مقعدي؟</a></p>\n<h2>أخطاء شائعة</h2>\n<ul>\n<li>اسم يختلف عن الجواز ولو بحرف واحد، فيمكن أن يعطل التأشيرة لاحقًا.</li>\n<li>صور جوال للمستندات بدل المسح الضوئي الواضح، أو صورة شخصية ليست بمواصفات صورة الجواز على خلفية بيضاء.</li>\n<li>ترك شهادة خلو السوابق إلى الأسابيع الأخيرة.</li>\n<li>تفويت مهلة الأيام الخمسة لتأكيد العرض، أو المهلة القصيرة لطلب «منحتي».</li>\n<li>التقديم على التأشيرة وأنت في زيارة للسعودية.</li>\n<li>الدفع لوسيط. فكل خطوة مجانية وتقوم بها بنفسك.</li>\n</ul>\n<h2>إن لم تُقبل</h2>\n<ul>\n<li>كثير من الطلاب قُبلوا في محاولتهم الثانية أو الثالثة أو بعدها. قدّم مرة أخرى في الفترة القادمة.</li>\n<li>استثمر الوقت فيما ينفعك: حفظ القرآن، ودراسة العربية، والشهادات في المتون التي تتعلمها.</li>\n<li>بعض الجامعات صارت تذكر سبب الرفض. اقرأه وعالج تلك النقطة أولًا.</li>\n</ul>\n<h2>ما تتعهد به</h2>\n<p>يوقّع طالب المنحة إقرارًا يلزمه بالتقيد بأنظمة المملكة ولوائح الجامعة، والانتظام في الحضور والمحافظة على درجاته، وألا ينقل كفالته إلى غير الجامعة، وأن يعود إلى بلده عند التخرج أو الانسحاب أو المغادرة. ولا تستطيع البقاء في المملكة على المنحة بعد انتهاء دراستك.</p>\n<h2>السكن والأسرة</h2>\n<p><strong>السكن:</strong> المنحة الكاملة تشمل السكن الجامعي المجاني. والمنحة الجزئية لا تشمل سكنًا مجانيًا، وتُعرض غرف مدفوعة في الوحدة ١٣ عند توفر أماكن. انظر <a href=\"/ar/ask/is-housing-included\">هل السكن مشمول؟</a> وراجع الدعم المذكور في عرضك. <strong>الأسرة:</strong> استقدام الأسرة عبر الجامعة مغلق منذ ٢٠٢٥، فخطط للمجيء وحدك في البداية. انظر <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a>.</p>\n<blockquote><p>نصيحة: عندك سؤال عن طلبك أنت؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "avoiding-scams-in-madinah": {
  "titleAr": "تجنّب الاحتيال في المدينة: الشقق والعرابين والوظائف والتأشيرات والاحتيال الهاتفي",
  "summaryAr": "الفخاخ التي يقع فيها القادمون الجدد، ولكل منها الطريق الرسمي الآمن: الشقق والعرابين، والعقار الذي يُباع بوعد إقامة، والعمل بتأشيرة زيارة وعروض تحويل التأشيرة، وإدارة نشاط تجاري باسم غيرك، وعروض الحج والعمرة المزيفة، والمكالمات والرسائل التي تنتحل صفة بنكك أو أبشر أو الجامعة، والبضائع المقلدة، وأين تبلّغ عن كل واحد منها.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. أكثر عمليات الاحتيال الموجهة إلى القادمين الجدد تسير على نمط واحد: عرض يتجاوز النظام الرسمي، وطلب مال أو رمز قبل أن يُكتب أي شيء. ولكل فخ أدناه طريق رسمي يحميك، وجهة رسمية تبلّغ إليها.</p>\n<h2>استئجار شقة</h2>\n<ul>\n<li><strong>لا تحوّل عربونًا ولا «رسوم حجز» أبدًا</strong> قبل أن ترى الشقة بنفسك ويكون العقد جاهزًا للتسجيل. والشقة الرخيصة من شخص لا يستطيع مقابلتك هي الطُّعم المعتاد.</li>\n<li><strong>تحقق من الوسيط.</strong> الوسيط العقاري يحتاج إلى رخصة فال من الهيئة العامة للعقار. تحقق من رقم الرخصة في خدمة الاستعلام عن الوسطاء على موقع الهيئة <a href=\"https://rega.gov.sa/\">rega.gov.sa</a> أو في تطبيقها «عقاري». ويحتاج كل إعلان عقاري أيضًا إلى رخصة إعلان خاصة به، تؤكدها خدمة الاستعلام عن تراخيص الإعلانات لدى الهيئة.</li>\n<li><strong>سجّل العقد في إيجار، وادفع الإيجار عبر إيجار فقط.</strong> فالنقد، أو التحويل إلى حساب شخصي لأحدهم، لا يثبت أنك دفعت.</li>\n</ul>\n<p>القائمة الكاملة وعلامات التحذير في <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a>. ولأي مشكلة في عقد مسجل، اتصل بإيجار على <strong>199011</strong>.</p>\n<h2>شراء عقار «مع الإقامة»</h2>\n<p>بموجب النظام النافذ منذ ٢٢ يناير ٢٠٢٦، يستطيع المسلم غير السعودي أن يتملك مسكنًا في المدينة، لكن داخل النطاقات المعتمدة فقط، وعبر المنصة الرسمية للهيئة العامة للعقار «عقارات السعودية» فقط، على <a href=\"https://saudiproperties.rega.gov.sa/\">saudiproperties.rega.gov.sa</a>. وتملّك المسكن لا يمنحك إقامة ولا تأشيرة.</p>\n<ul>\n<li>البائع الذي يعدك بإقامة مع الشقة يبيع ما لا يملك أن يعطيه. والإقامة الوحيدة المرتبطة بالعقار هي منتج مالك العقار في الإقامة المميزة. وتتقدم له أنت بنفسك إلى مركز الإقامة المميزة عبر <a href=\"https://my.gov.sa/en/services/187911\">المنصة الوطنية</a>، وله شروطه الخاصة.</li>\n<li>تحقق من الأرض على خريطة النطاقات في المنصة، واحصل على شهادة الأهلية منها، وادفع إلكترونيًا. ولا تدفع أبدًا نقدًا أو إلى حساب شخصي.</li>\n<li>الربح المضمون، أو الأرض التي «ستدخل النطاقات قريبًا»، علامة تحذير.</li>\n</ul>\n<p>الأحكام والخطوات الخمس في <a href=\"/ar/guides/owning-property-as-a-non-saudi\">تملّك غير السعودي مسكنًا في المدينة: الأحكام والنطاقات وطريقة التقديم</a>.</p>\n<h2>عروض العمل و«تحويل التأشيرة»</h2>\n<p>التأشيرة السياحية الإلكترونية وتأشيرة العمرة ليستا تأشيرتي عمل، ولا يجوز لحامليهما العمل بأجر. ولا تُحوَّل تأشيرة الزيارة إلى إقامة عمل داخل المملكة، مهما طلب أحدهم مقابل ذلك. والعمل «على تأشيرة زيارتك، والأوراق لاحقًا»، أو «التحويل» المدفوع، يجعلك تعمل بصورة مخالفة للنظام.</p>\n<p>الوظيفة الحقيقية تأتي بتأشيرة عمل يطلبها صاحب العمل قبل سفرك. وبعد أن تصبح مقيمًا يُوثَّق عقدك في منصة قوى، وتستطيع قراءته في حسابك الخاص على قوى تحت «عقود العمل». وبموجب نظام العمل يتحمل صاحب العمل رسوم الاستقدام ورسوم الإقامة ورخصة العمل وتجديدها. ومن يطلب منك أن تدفع ثمن «تأشيرتك» أو «إقامتك» لا يعرض عليك عملًا نظاميًا. وبلّغ عن مخالفات العمل إلى وزارة الموارد البشرية على <strong>19911</strong> أو في تطبيقها.</p>\n<h2>إدارة نشاط تجاري باسم غيرك</h2>\n<p>يُعرض على بعض القادمين الجدد محل أو نشاط توصيل أو متجر إلكتروني «باسم سعودي، وأنت تديره فقط». وهذا هو التستر التجاري، وهو جريمة بموجب نظام مكافحة التستر. ومن عقوباته:</p>\n<ul>\n<li>السجن حتى خمس سنوات، وغرامات تصل إلى ٥ ملايين ريال؛</li>\n<li>مصادرة الأموال المتحصلة، وإغلاق النشاط، وشطب سجله التجاري؛</li>\n<li>ترحيل غير السعودي المتورط، مع منعه من العودة للعمل في المملكة.</li>\n</ul>\n<p>الطريق النظامي شركة خاصة بك، مسجلة باسمك. ومن يحمل إقامة الجامعة فعليه أن يخرج من كفالة الجامعة أولًا: انظر <a href=\"/ar/guides/start-a-company-in-saudi\">تأسيس شركتك الخاصة في السعودية</a>. ويُبلَّغ عن التستر إلى وزارة التجارة على <strong>1900</strong> أو في تطبيقها «بلاغ تجاري».</p>\n<h2>عروض الحج والعمرة والروضة</h2>\n<ul>\n<li><strong>الحج:</strong> يحجز المقيمون حج الداخل في نسك فقط، على <a href=\"https://www.nusuk.sa/\">nusuk.sa</a> أو في التطبيق، مع شركة مرخصة مدرجة فيه. و«الحملة» التي تُباع عبر وسائل التواصل أو بالهاتف أو بالكلام خارج نسك لا تعطيك تصريحًا، والحج بلا تصريح عقوبته غرامات كبيرة، والترحيل للمقيمين. انظر <a href=\"/ar/guides/hajj-as-a-student\">الحج من المدينة طالبًا أو مقيمًا</a>.</li>\n<li><strong>العمرة والروضة:</strong> التصاريح في نسك، باسمك أنت، وتصريح الروضة مجاني. ومن يبيع دخولًا مدفوعًا أو مضمونًا فهو محتال. انظر <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء من المدينة</a>.</li>\n</ul>\n<p>بلّغ عن إعلانات الحج المزيفة على <strong>911</strong>. ولأي مشكلة في خدمات الحج أو العمرة، يجيب الرقم الموحد <strong>1966</strong> على مدار الساعة وبعدة لغات.</p>\n<h2>مكالمات ورسائل وروابط تنتحل صفة بنكك أو أبشر أو الجامعة</h2>\n<p>يدّعي المتصل أنه من بنكك أو الشرطة أو أبشر أو الجامعة، أو تقول رسالة إن بطاقتك موقوفة أو إن عليك مخالفة، وتعطيك رابطًا. والهدف دائمًا كلمة مرورك أو بيانات بطاقتك أو الرمز المرسل إلى جوالك.</p>\n<ul>\n<li><strong>لا تشارك رمز التحقق (OTP) أبدًا،</strong> ولا كلمة المرور ولا رقم البطاقة، مع أي أحد، في أي مكالمة أو محادثة، ولو قال إنه من بنكك أو من جهة حكومية.</li>\n<li><strong>نفاذ:</strong> لا توافق على طلب إلا إذا بدأت تسجيل الدخول بنفسك وكان الرقم في التطبيق مطابقًا للرقم على شاشتك. وارفض كل طلب لم تبدأه، ولا تختر أبدًا رقمًا يقرؤه عليك أحد في الهاتف.</li>\n<li><strong>المخالفات والرسوم:</strong> تجاهل الرسائل التي فيها روابط دفع. وتحقق من مخالفاتك بنفسك في أبشر، وادفع عبر تطبيق بنكك: انظر <a href=\"/ar/ask/traffic-fines\">كيف أتحقق من المخالفات المرورية وأدفعها؟</a></li>\n<li><strong>الجامعة:</strong> تنشر حسابات مزيفة روابط في محادثات المقررات على بلاك بورد للاستيلاء على حسابات الطلاب. انظر <a href=\"/ar/ask/blackboard-phishing\">أحدهم نشر رابطًا في محادثة شعبتي في بلاك بورد. هل هو آمن؟</a> و<a href=\"/ar/guides/university-email-and-microsoft-365\">بريدك الجامعي ومايكروسوفت 365</a>.</li>\n<li><strong>المال و«الاستثمارات»:</strong> إذا أرسل إليك غريب مالًا «بالخطأ» وطلب أن تحوّله إلى غيره، فأخبر بنكك ولا تحوّل شيئًا. ولا تضع مالك في عروض «استثمار» تُنشر في المجموعات.</li>\n<li><strong>رسائل الاحتيال:</strong> أعد توجيهها مجانًا إلى <strong>330330</strong>، رقم البلاغات لدى هيئة الاتصالات والفضاء والتقنية.</li>\n</ul>\n<blockquote><p>مهم: إن شاركت بالفعل رمزًا أو بيانات بطاقتك، فاتصل ببنكك فورًا على الرقم الموجود في تطبيقه أو على ظهر بطاقتك، واطلب منه إيقاف البطاقة وإيقاف التحويل. ثم غيّر كلمات المرور، وبلّغ عن الاحتيال في أبشر، ضمن خدمات الأمن العام، في «بلاغات الاحتيال المالي»، أو في تطبيق وزارة الداخلية «كلنا أمن».</p></blockquote>\n<h2>البضائع المقلدة</h2>\n<p>العطور والجوالات والشواحن وقطع الغيار المقلدة لماركات معروفة تُباع في الأسواق وعبر منشورات «راسلني على الخاص». اشترِ الإلكترونيات من محلات تعطيك فاتورة ضريبية، واحتفظ بها للضمان. وبلّغ عن البضائع المقلدة والغش التجاري إلى وزارة التجارة على <strong>1900</strong> أو في تطبيق «بلاغ تجاري».</p>\n<h2>أين تبلّغ</h2>\n<table><thead><tr><th>ما حدث</th><th>أين تبلّغ</th></tr></thead><tbody>\n<tr><td>سُحب مال من بطاقتك أو حسابك</td><td>بنكك أولًا. ثم أبشر، بلاغات الاحتيال المالي، أو تطبيق «كلنا أمن»</td></tr>\n<tr><td>لم يحل بنكك شكواك</td><td>خط حماية العملاء لدى البنك المركزي السعودي، مجانًا على <strong>8001256666</strong></td></tr>\n<tr><td>رسالة نصية احتيالية</td><td>أعد توجيهها إلى <strong>330330</strong></td></tr>\n<tr><td>احتيال أو انتحال شخصية أو ابتزاز أو اختراق حساب</td><td>تطبيق «كلنا أمن». وفي الطوارئ <strong>911</strong></td></tr>\n<tr><td>مشكلة في عقد إيجار مسجل</td><td>إيجار، <strong>199011</strong></td></tr>\n<tr><td>إعلانات حج مزيفة</td><td><strong>911</strong></td></tr>\n<tr><td>خدمات الحج أو العمرة</td><td>الرقم الموحد <strong>1966</strong></td></tr>\n<tr><td>مخالفات العمل</td><td>وزارة الموارد البشرية، <strong>19911</strong> أو تطبيقها</td></tr>\n<tr><td>التستر والبضائع المقلدة والغش التجاري</td><td>وزارة التجارة، <strong>1900</strong> أو تطبيق «بلاغ تجاري»</td></tr>\n<tr><td>الاستيلاء على حسابك الجامعي</td><td><strong>it.care@iu.edu.sa</strong>، وبلّغ عن حسابات بلاك بورد المزيفة إلى <strong>bb@iu.edu.sa</strong></td></tr>\n</tbody></table>\n<p>كل أرقام الطوارئ في <a href=\"/ar/ask/emergency-numbers\">ما أرقام الطوارئ في السعودية؟</a></p>"
 },
 "bringing-parents-to-visit": {
  "titleAr": "استقدام والديك لزيارة المدينة: التأشيرات، والحرم مع الوالدين المسنّين، والعمرة، ومدة البقاء",
  "summaryAr": "أي تأشيرة تناسب والديك، وما ترتبه قبل سفرهما، والمطار، وأين يسكنان، والحرم مع والد كبير في السن، وقباء والزيارة، والعمرة بالقطار، ويوم مريح، والصحة والتأمين، وأحكام مدة البقاء.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. وقلّ ما يُتمّ سنوات الطالب في المدينة مثل أن يصلي إلى جانب والديه في المسجد النبوي. ويغطي هذا الدليل التأشيرة التي تناسبهما، وما ترتبه قبل سفرهما، والمطار، وأين يسكنان، والحرم مع والد كبير في السن، والعمرة، وأحكام مدة البقاء.</p>\n<h2>أي تأشيرة</h2>\n<table><thead><tr><th>التأشيرة</th><th>لمن تناسب</th><th>ما تعرفه</th></tr></thead><tbody>\n<tr><td><strong>التأشيرة السياحية الإلكترونية</strong></td><td>الوالدان من إحدى الدول الـ ٧٢ المؤهلة، وحاملو تأشيرة أمريكية أو بريطانية أو شنغن سارية ومستعملة</td><td>نحو ٥٣٥ ريالًا مع التأمين الإلزامي، ويُقدم عليها عبر visa.visitsaudi.com فقط. صالحة سنة، متعددة الدخول، حتى ٩٠ يومًا في الزيارة. وتشمل العمرة بتصريح من نسك</td></tr>\n<tr><td><strong>تأشيرة العمرة</strong></td><td>الوالدان من الدول الأخرى</td><td>تُرتب عبر منصة نسك عمرة أو وكيل مرخص، مع باقة خدمات: يُحجز الفندق والنقل ويُسجلان في نسك قبل إصدار التأشيرة. ويجب الدخول بها خلال ٣٠ يومًا من إصدارها، وينتهي الموسم في شوال (المواعيد أدناه). والمدينة داخلة في الزيارة</td></tr>\n<tr><td><strong>تأشيرة الزيارة العائلية</strong></td><td>والدا مقيم يحمل إقامة</td><td>يتقدم المقيم عبر منصة التأشيرات في وزارة الخارجية. ٣٠٠ ريال للدخول الواحد أو ٥٠٠ ريال للدخول المتعدد، إضافة إلى التأمين. ثم يُعطي والداك البصمات والصورة في مركز تأشير قبل إصدار التأشيرة. والموافقة بحسب كل حالة، والمضيف مسؤول عن الزائر</td></tr>\n<tr><td><strong>طلاب التأشيرة التعليمية</strong></td><td>حاملو هوية الزائر</td><td>لا تستطيع استضافة زيارة عائلية بلا إقامة. فيأتي والداك بتأشيرة سياحية أو تأشيرة عمرة، أو اسأل عمادة شؤون الطلاب عبر تواصل عن إجراء الجامعة الخاص بزيارة الأسرة</td></tr>\n</tbody></table>\n<p>الأحكام والرسوم الحالية، وما يُحمل إلى مركز التأشيرات، في <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a>، وهي تتغير، فراجع الموقع الرسمي قبل دفع ثمن تذاكر الطيران.</p>\n<h2>القدوم بتأشيرة العمرة: موسم ١٤٤٨</h2>\n<p>إن جاء والداك بتأشيرة عمرة فعليهما الالتزام بمواعيد الموسم:</p>\n<table><thead><tr><th>المرحلة</th><th>بالهجري</th><th>بالميلادي</th></tr></thead><tbody>\n<tr><td>آخر يوم لإصدار تأشيرة العمرة</td><td>١ شوال ١٤٤٨</td><td>٩ مارس ٢٠٢٧</td></tr>\n<tr><td>آخر يوم لدخول السعودية</td><td>١٥ شوال ١٤٤٨</td><td>٢٣ مارس ٢٠٢٧</td></tr>\n<tr><td>آخر يوم لمغادرة السعودية</td><td>٣٠ شوال ١٤٤٨</td><td>٧ أبريل ٢٠٢٧</td></tr>\n</tbody></table>\n<ul>\n<li>تُلغى التأشيرة إن لم يُدخل بها خلال ٣٠ يومًا من إصدارها، فلا تتقدم بها إلا بعد تثبيت الرحلات.</li>\n<li>وبعد دخولهما يحق لوالديك البقاء حتى ٩٠ يومًا، في حدود مواعيد الموسم المذكورة أعلاه.</li>\n<li>يُحجز الفندق والنقل في نسك، أو عبر وكيل مرخص، قبل إصدار التأشيرة.</li>\n<li>لا تحتاج والدتك إلى محرم للحصول على التأشيرة ولا لأداء العمرة.</li>\n<li>تأشيرة العمرة لا تبيح الحج أبدًا، ومن ١ ذي القعدة (٨ أبريل ٢٠٢٧) تتوقف تصاريح العمرة لموسم الحج.</li>\n<li>كل تأشيرة سعودية سارية، ومنها التأشيرة السياحية الإلكترونية وتأشيرة الزيارة العائلية، تتيح أداء العمرة. ولا بد من تصريح نسك في كل الأحوال.</li>\n</ul>\n<h2>قبل سفرهما</h2>\n<ol>\n<li><strong>جوازات صالحة ستة أشهر</strong> من يوم الدخول.</li>\n<li><strong>الأدوية:</strong> كمية شهر في علبها الأصلية مع الوصفة. وكل دواء مراقب، مثل المسكنات القوية أو المنومات، يحتاج إلى تصريح المسافر من الهيئة العامة للغذاء والدواء قبل الرحلة. انظر <a href=\"/ar/ask/bringing-medicine-into-saudi\">هل أستطيع إحضار دوائي المعتاد إلى السعودية؟</a></li>\n<li><strong>الكرسي المتحرك في المطارات:</strong> احجزه مع شركة الطيران حين تحجز الرحلة، لا عند البوابة.</li>\n<li><strong>المال:</strong> بطاقتهما البنكية تعمل في الصرافات هنا، والمحلات تقبل البطاقات في كل مكان. وقليل من النقد بالريال لأول سيارة أجرة وأول تمر.</li>\n<li><strong>شريحة جوال:</strong> اشترِ واحدة في المطار أو في أي محل للمشغلين بجوازهما ورقم الحدود، ليتصلا بك ويفتحا تطبيق نسك. انظر <a href=\"/ar/guides/sim-internet-bank\">شريحة الجوال والإنترنت وبطاقة بنكية سعودية</a>.</li>\n<li><strong>ملابس الموسم:</strong> من نوفمبر إلى فبراير يكون الليل لطيف البرودة، والفجر باردًا أحيانًا. ومن يونيو إلى سبتمبر حار طوال اليوم. انظر <a href=\"/ar/guides/seasons-and-camping\">المدينة في كل فصل</a>.</li>\n</ol>\n<h2>المطار</h2>\n<p>مطار الأمير محمد بن عبدالعزيز الدولي على بعد نحو ٢٠ كم من الحرم، من ٢٠ إلى ٣٠ دقيقة بالسيارة. استقبلهما في صالة الوصول إن استطعت. وإلا فخط المطار ٤٠٠ في حافلات المدينة يعمل على مدار الساعة إلى منطقة الحرم ويقبل البطاقات لا النقد، وتطبيقات التوصيل تكلف نحو ٤٠ إلى ٨٠ ريالًا. انظر <a href=\"/ar/ask/airport-to-haram-and-university\">كيف أصل من مطار المدينة إلى الحرم؟</a></p>\n<h2>أين يسكنان</h2>\n<ul>\n<li><strong>معك،</strong> إن كنت تستأجر شقة. والطلاب العزاب في السكن الجامعي لا يستضيفون، فاحجز فندقًا.</li>\n<li><strong>داخل المنطقة المركزية</strong> حول الحرم، حيث الفندق على بعد دقائق مشيًا من الأبواب ولا حاجة إلى مواصلات لأي صلاة. وكلما اقترب من الأبواب ارتفع السعر، والسعر يتضاعف في رمضان وحول العيد.</li>\n<li><strong>أبعد قليلًا،</strong> في قباء أو على الطرق الرئيسية، حيث الشقق العائلية والفنادق أرخص والحرم مشوار قصير بالحافلة أو سيارة الأجرة. مناسب لإقامة طويلة مع سيارة.</li>\n</ul>\n<p>احجز عبر مواقع الحجز الكبيرة أو مباشرة، واقرأ التقييمات الحديثة، وتحقق من مسافة المشي على الخريطة لا من وصف الفندق لنفسه.</p>\n<h2>الحرم مع والد كبير في السن</h2>\n<ul>\n<li><strong>الكراسي المتحركة</strong> تُعار مجانًا من مكتب إدارة الأبواب عند الباب ٧، ويدفعها المتطوعون. والمصاعد عند الباب ٩ والباب ٣٣ تصل إلى السطح، والساحات مستوية تظللها المظلات.</li>\n<li><strong>العربات</strong> تعمل بين المواقف والأبواب. اتفق على السعر أولًا إن لم تكن مجانية.</li>\n<li><strong>مركزان صحيان</strong> داخل الحرم يعملان على مدار الساعة، عند باب جبريل (٣٥٥) وعند الصافية (٣٠٥)، بأطباء وعلاج مجاني. ولأي أمر خطير اتصل بـ 911.</li>\n<li><strong>والدتك</strong> تصلي في مصليات النساء في الجهتين الشمالية والغربية، ولها أبوابها الخاصة، ومواعيد الروضة للنساء تختلف عن مواعيد الرجال. وكل ما يخصها في <a href=\"/ar/guides/women-at-masjid-an-nabawi\">المسجد النبوي للأخوات والأسر</a>.</li>\n<li><strong>الروضة</strong> تحتاج إلى تصريح مجاني في نسك، يُحجز بالجواز للزائر، والمسار الفوري يعطي موعدًا في اليوم نفسه لمن هو في المسجد. اذهب معهما إلى الباب في وقت التصريح بالضبط. انظر <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء من المدينة</a>.</li>\n<li><strong>الحقائب</strong> غير مسموح بها في الداخل. ومركز حفظ الأمانات المجاني يحفظها حتى ٤ ساعات.</li>\n<li><strong>التوقيت:</strong> بعد الفجر وآخر الصباح هما الساعتان الهادئتان. ويوم الجمعة قبل الصلاة، وكل ليلة في رمضان، تمتلئ الساحات قبل الأذان بساعة.</li>\n</ul>\n<p>زيارتكم الأولى معًا تستحق مشيًا متمهلًا: الأبواب، والمكتبة، والقبة الخضراء من الساحة، والبقيع عبر الطريق. والمخطط كله في <a href=\"/ar/guides/masjid-an-nabawi-first-visit\">زيارة المسجد النبوي: دليل الزيارة الأولى</a>.</p>\n<h2>قباء وأحد والأماكن الأخرى</h2>\n<p>مسجد قباء صباح السبت، وشهداء أحد، ومسجد القبلتين، والمساجد السبعة عند الخندق، كل منها مشوار قصير بسيارة الأجرة، وأيسر ما يكون للوالد الكبير أن يزور واحدًا منها في اليوم في الساعات الباردة. والعربات وسيارات الأجرة تنتظر عند قباء. والقائمة مع المسافات في <a href=\"/ar/guides/historic-sites-and-masjids\">المواقع التاريخية والمساجد في المدينة</a>.</p>\n<h2>العمرة من المدينة</h2>\n<p>قطار الحرمين يصل إلى مكة في نحو ساعتين ونصف، مع مكان للكرسي المتحرك ومصعد في كل محطة، وميقات أهل المدينة ذو الحليفة في طريق الخروج من المدينة. والزوار يحجزون تصريح العمرة في نسك. وامنح الوالد الكبير ليلة في مكة بدل رحلة يوم، وطوفوا بعد العشاء أو قبل الفجر حين يكون المطاف أهدأ. والخطوات والأسعار في <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء من المدينة</a> و<a href=\"/ar/guides/haramain-train-and-city-buses\">قطار الحرمين وحافلات المدينة</a>.</p>\n<h2>يوم مريح</h2>\n<table><thead><tr><th>الوقت</th><th>ماذا</th></tr></thead><tbody>\n<tr><td>الفجر</td><td>الصلاة في الحرم، والجلوس حتى الشروق، والإفطار قريبًا</td></tr>\n<tr><td>الصباح</td><td>راحة، أو زيارة واحدة (قباء، أحد) قبل الحر</td></tr>\n<tr><td>من الظهر إلى العصر</td><td>راحة في الفندق صيفًا. وفي الشتاء مكتبة الحرم أو الساحات</td></tr>\n<tr><td>من العصر إلى العشاء</td><td>الحرم: الدروس بعد المغرب لوالدك، ومصليات النساء لوالدتك، والتمر والسوق بعد العشاء</td></tr>\n</tbody></table>\n<h2>الصحة والتأمين والطوارئ</h2>\n<p>التأشيرة السياحية الإلكترونية وتأشيرة الزيارة العائلية تشملان تأمينًا طبيًا للزيارة، وبطاقة شركة التأمين أو رقمها مدوّن في التأشيرة. وللتحقق من الوثيقة استعمل خدمة الاستعلام عن تأمين الزائرين في مجلس الضمان الصحي برقم الجواز أو التأشيرة أو رقم الحدود: انظر <a href=\"/ar/guides/check-visa-and-iqama-online\">الاستعلام إلكترونيًا عن تأشيرتك ورقم الحدود والتأمين والمخالفات</a>. وللدواء فالصيدليات في كل شارع، وكثير منها يفتح طوال الليل. وفي الطوارئ 997 للإسعاف و911 لكل شيء. والمستشفيات والعيادات في <a href=\"/ar/guides/doctors-hospitals-and-pharmacies\">الأطباء والمستشفيات والصيدليات وأرقام الطوارئ</a>.</p>\n<h2>كم يبقيان</h2>\n<ul>\n<li>بالتأشيرة السياحية الإلكترونية حتى ٩٠ يومًا في الزيارة، تُحسب من يوم الدخول، والتأشيرة نفسها صالحة سنة.</li>\n<li>بتأشيرة الزيارة العائلية يمددها المضيف في أبشر ابتداءً من ٧ أيام قبل انتهائها، بـ ١٠٠ ريال في كل مرة، حتى ١٨٠ يومًا في المجموع. واشترِ التأمين الجديد للمدة الجديدة أولًا، لأن أبشر يرفض التمديد بدونه. والتمديد في الأيام الثلاثة التي تلي الانتهاء تُضاف إليه غرامة ٥٠٠ ريال. والخطوات في <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a>.</li>\n<li>بتأشيرة العمرة يغادران في موعد أقصاه آخر يوم للمغادرة في الموسم، المذكور أعلاه.</li>\n<li>البقاء بعد انتهاء المدة يجلب غرامة ومنعًا من الدخول على الزائر وعقوبات على المضيف. اكتب آخر يوم في تقويمك يوم وصولهما.</li>\n</ul>\n<h2>حين يغادران</h2>\n<p>علبة مغلقة من تمر العجوة أو الصفاوي، وسجادات صلاة من سوق الحرم، وبعض الكتب بالعربية للأحفاد، كلها تُحمل في الحقيبة بلا عناء، وما هو أثقل يذهب بالبريد: انظر <a href=\"/ar/guides/shipping-and-receiving-parcels\">إرسال الطرود واستقبالها في المدينة</a>. واطلب منهما الاحتفاظ بتطبيق نسك، لأن تصاريح الزيارة القادمة تُحجز بالطريقة نفسها.</p>\n<blockquote><p>نصيحة: تخطط لزيارة في رمضان أو في إجازات الجامعة؟ تحقق من التواريخ أولًا، واحجز مبكرًا، وتوقع أن تكون المدينة ممتلئة. عندك سؤال؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "campus-life-islamic-university": {
  "titleAr": "حياة الطالب في الجامعة الإسلامية: الوجبات والحافلات والصحة والسكن",
  "summaryAr": "وجبات المطعم الجامعي المدعومة، والحافلات المجانية إلى الحرم، والمركز الطبي، والمكتبة المركزية، والسكن وأنظمته، وخدمات عمادة شؤون الطلاب، والإنترنت اللاسلكي، والنادي الرياضي، وحساباتك في الجامعة.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. يُكفى طلاب المنحة الكاملة كثيرًا من حاجات الحياة اليومية، وهذه الصفحة تجمع الأساسيات في مكان واحد.</p>\n<h2>الوجبات في المطعم الجامعي</h2>\n<p>يقدم المطعم الجامعي لطلاب المنحة الكاملة ثلاث وجبات مدعومة في اليوم.</p>\n<table><thead><tr><th>الوجبة</th><th>السعر</th></tr></thead><tbody>\n<tr><td>الفطور</td><td>ريال واحد</td></tr>\n<tr><td>الغداء</td><td>ريالان</td></tr>\n<tr><td>العشاء</td><td>ريالان</td></tr>\n</tbody></table>\n<ol>\n<li>ادخل إلى نظام المطعم على <a href=\"https://restaurant.iu.edu.sa/\">restaurant.iu.edu.sa</a> بحسابك الجامعي.</li>\n<li>احجز وجباتك للشهر القادم. يكون الحجز لشهر كامل في كل مرة، فضع تذكيرًا قبل نهاية كل شهر.</li>\n<li>أوقات الوجبات أثناء الفصل الدراسي في عام ١٤٤٧: الفطور من نحو ٦:٠٠ إلى ٨:٠٠ صباحًا، والغداء من ١١:٠٠ صباحًا إلى ٢:٠٠ ظهرًا، والعشاء من نحو ٧:٣٠ إلى ١٠:٣٠ مساءً. ادفع إلكترونيًا عند الحجز، أو عند مكتب الدفع خلف المطعم، وأبرز باركود وجبتك عند الشباك. والمطعم خلف كلية الشريعة.</li>\n<li>استعمل بطاقتك أنت فقط، فأخذ الوجبات ببطاقتين غير مسموح به.</li>\n</ol>\n<h2>الحافلات المجانية</h2>\n<p>تسيّر الجامعة حافلات مجانية بين الحرم الجامعي والمسجد النبوي، لتصلي في الحرم دون أن تدفع أجرة سيارة. وتربط حافلات مجانية أخرى السكن الواقع خارج الحرم الجامعي بالحرم الجامعي. وتتغير نقاط الركوب والمواعيد خلال السنة وفي رمضان وفي أسابيع الاختبارات، فراسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a> لمعرفة المواعيد الحالية.</p>\n<h2>السكن</h2>\n<p>تسكّن الجامعة طلاب المنحة الكاملة مجانًا، إما داخل الجامعة وإما في سكن الربوة. ولكل طالب سرير ومكتب وكرسي وخزانة ملابس. والمنحة الجزئية لا تشمل سكنًا مجانيًا: فإن توفرت أماكن عرضت الجامعة على طلاب المنحة الجزئية غرفة مدفوعة في الوحدة ١٣. انظر <a href=\"/ar/ask/is-housing-included\">هل السكن مشمول؟</a> و<a href=\"/ar/guides/unit-13-and-paid-university-housing\">الوحدة ١٣ والسكن الجامعي المدفوع</a>.</p>\n<p>يُسكَّن الطلاب العزاب. أما الوحدات العائلية فلا تُعرض إلا حين تخلو إحداها، ولذلك يستأجر معظم الطلاب المتزوجين شقة في المدينة. انظر <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a> و<a href=\"/ar/guides/cost-of-living\">كم تكلف المعيشة في المدينة</a>.</p>\n<h3>قواعد في السكن مخالفتها تفقدك مكانك</h3>\n<ul>\n<li><strong>لا ضيوف في غرفتك، ولا تُعِر مفتاحك أبدًا.</strong> استضافة أي أحد أو إدخاله أو إعطاؤه مفتاحك ممنوع، وعقوبته الفصل من الجامعة. ويُفتَّش السكن داخل الحرم الجامعي وخارجه طوال العام.</li>\n<li><strong>لا تترك شيئًا في الغرف الخالية.</strong> تُزال الأغراض المتروكة في غرفة شاغرة أو مسلَّمة، ولا تتحمل الجامعة أي مسؤولية عنها.</li>\n<li><strong>اترك الأثاث في مكانه.</strong> كل ما في الغرفة، ومنه السرير، يبقى فيها ويُفحص عند تسليمك الغرفة.</li>\n<li><strong>غرف الغسيل:</strong> لا تربط حبال الغسيل بالأنابيب أو المحابس، ولا تترك ملابسك فيها. فأي تلف يقطع الماء عن الوحدة كلها حتى يُصلَح.</li>\n<li><strong>السكوترات والدراجات</strong> تحتاج إلى استمارة تسجيل وملصق من الوحدة ٢٢. وأبعدها عن الغرف والممرات. ولا تشحن السكوتر أو الجوال طوال الليل في غرفتك، فقد تسبب ذلك في حرائق.</li>\n</ul>\n<h2>الصحة: المركز الطبي الجامعي</h2>\n<p>المركز الطبي في الحرم الجامعي مجاني لطلاب المنحة. وفيه عيادات للباطنية والأطفال والنساء والولادة والجراحة العامة والجلدية والأنف والأذن والحنجرة والأسنان، مع صيدلية وأشعة سينية وأشعة صوتية ومختبر ووحدة تطعيم.</p>\n<table><thead><tr><th>الأيام</th><th>الساعات</th></tr></thead><tbody>\n<tr><td>الأحد إلى الخميس، العيادات</td><td>٨:٠٠ صباحًا إلى ٣:١٥ عصرًا</td></tr>\n<tr><td>الأحد إلى الخميس، مناوبة الطوارئ</td><td>٣:١٥ عصرًا إلى ١١:٠٠ مساءً</td></tr>\n<tr><td>الجمعة والسبت، مناوبة الطوارئ</td><td>١:٠٠ ظهرًا إلى ٩:٠٠ مساءً</td></tr>\n</tbody></table>\n<p>احجز موعد العيادة على <a href=\"https://vcappointments.iu.edu.sa/\">vcappointments.iu.edu.sa</a> بحسابك الجامعي. وخارج هذه الساعات اذهب إلى قسم الطوارئ في أحد المستشفيات أو اتصل بالرقم 997. انظر <a href=\"/ar/guides/doctors-hospitals-and-pharmacies\">الأطباء والمستشفيات والصيدليات وأرقام الطوارئ</a>.</p>\n<h2>المكتبة المركزية</h2>\n<p>المكتبة المركزية على يمينك وأنت داخل من البوابة الرئيسية. وتفتح أثناء الفصل الدراسي من الأحد إلى الخميس، من ٨:٠٠ صباحًا إلى منتصف الليل، وتبقى مفتوحة ٢٤ ساعة أيام الاختبارات النهائية. وتغلق يومي الجمعة والسبت. وهي مفتوحة للزوار كما هي للطلاب، ومن مقتنياتها المكتبات الخاصة لعدد من العلماء، منها مكتبة الشيخ الألباني. الحواسيب المحمولة مسموح بها والحقائب غير مسموح بها. وتعير المكتبة أيضًا الكتب المقررة مجانًا طوال الفصل: جدد الإعارة كل شهر وأعد الكتب بالحال التي استلمتها بها، وإلا دفعت غرامة يسيرة. انظر <a href=\"/ar/ask/library-bags-laptops\">هل يمكنني إدخال حقيبة أو حاسوب محمول إلى المكتبات؟</a></p>\n<h2>حساباتك في الجامعة</h2>\n<ul>\n<li><strong>الدخول:</strong> الدخول الجامعي على sso.iu.edu.sa يعمل عبر نفاذ، أو برقمك الجامعي وكلمة المرور ورمز التحقق.</li>\n<li><strong>البريد:</strong> يأتي بريدك الجامعي مع تطبيقات Microsoft 365 مجانًا وتخزين سحابي بسعة ١ تيرابايت. وهو القناة الرسمية، فاقرأه كل يوم.</li>\n<li><strong>المحاضرات:</strong> بلاك بورد هو منصة التعلم. وجدولك واختباراتك النهائية في النظام الأكاديمي: انظر <a href=\"/ar/ask/find-my-timetable\">أين أجد جدول محاضراتي؟</a></li>\n<li><strong>إثبات أنك طالب:</strong> خطاب تعريف الطالب المختوم مجاني وفوري في النظام الأكاديمي من «شخصي» ثم «المستندات الرسمية».</li>\n<li><strong>الحضور:</strong> الغياب عن أكثر من ٢٥٪ من ساعات المقرر يحرمك من اختباره النهائي.</li>\n<li><strong>الإنترنت اللاسلكي:</strong> ادخل إلى شبكة الحرم الجامعي برقمك الجامعي وكلمة المرور. ويستطيع كل طالب توصيل <strong>جهازين</strong> على الأكثر. والشبكة مفتوحة، فتجنب المعاملات البنكية عليها، وارفع مشكلات الاتصال إلى عمادة تقنية المعلومات، في المبنى الواقع خلف الوحدة ١٨.</li>\n</ul>\n<h2>خدمات عمادة شؤون الطلاب</h2>\n<p>تتولى عمادة شؤون الطلاب والمكاتب في الوحدة ٢٢ كثيرًا من شؤون الحياة اليومية:</p>\n<ul>\n<li><strong>بطاقة المكافأة:</strong> تُصدر وتُجدد وتُستبدل في الوحدة ٢٢. انظر <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة</a>.</li>\n<li><strong>القروض:</strong> يقرض صندوق الطلاب في الوحدة ٢٢ ما يصل إلى ٢٬٠٠٠ ريال، تُسدَّد من مكافأتك.</li>\n<li><strong>بطاقة الإقامة المطبوعة:</strong> يستطيع حاملو الإقامة طلب بطاقة إقامة بلاستيكية عن طريق شؤون الطلاب بنحو ٥٨ ريالًا. اطبع إقامتك من أبشر، واكتب عليها رقم جوالك، وسلّمها. ثم يتصلون بك لتدفع، وتجهز البطاقة في أسبوعين إلى ثلاثة. أما حاملو هوية الزائر فليست لهم بطاقة تُطبع.</li>\n<li><strong>حافلات المطار:</strong> في نهاية العام الدراسي تسيّر العمادة حافلات مجانية من الجامعة إلى مطار الأمير محمد بن عبدالعزيز. ويُعلن موعد بدئها على حسابها في X، <a href=\"https://x.com/dsa_iu_edu\">@dsa_iu_edu</a>.</li>\n<li><strong>رمضان:</strong> تقدم العمادة إفطارًا يوميًا بجوار الملعب الرياضي للجامعة وتوزع وجبات السحور. وتسير المحاضرات على جدول خاص برمضان.</li>\n<li><strong>رحلات العمرة المجانية:</strong> تنظم العمادة رحلات يومية مجانية بالحافلات إلى مكة لأداء العمرة، في رمضان وفي أوقات أخرى من السنة. ويُعلن عن كل رحلة مع نموذج للتسجيل على حسابات العمادة، وتنطلق الحافلات عادةً من الحرم الجامعي في الصباح الباكر أو بعد صلاة الظهر. وتعود الحافلة في اليوم نفسه، ومن فاتته عاد على نفقته. واحجز تصريح العمرة في نسك قبل أن تذهب: انظر <a href=\"/ar/ask/umrah-from-madinah\">كيف أذهب لأداء العمرة من المدينة؟</a></li>\n<li><strong>الأندية والأنشطة:</strong> تُدار من الدور الأول في العمادة. وتنضم إلى أي نادٍ عن طريق رئيسه أو مجموعته.</li>\n<li><strong>ممثلو الجنسيات:</strong> لكل جنسية ممثل من الطلاب ينقل إعلانات الجامعة ويجمع قوائم التذاكر والتأشيرات. ومكتبهم في العمادة.</li>\n<li><strong>السيارات:</strong> الوقوف بجوار وحدات السكن يحتاج إلى تصريح. وتصدر التصاريح من مكتب التصاريح بعد البوابة الرئيسية مباشرة، وتُمنح في الغالب لطلاب الدراسات العليا ولأصحاب الحاجة الطبية. ويقف غيرهم في المواقف الرئيسية ويكملون سيرًا على الأقدام.</li>\n</ul>\n<h2>المال والطيران</h2>\n<ul>\n<li>مكافأتك الشهرية، وبدل الوصول وبدل التخرج، وكيف تطلع عليها، في <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة: المكافأة والبدلات والتذاكر</a>.</li>\n<li>تذكرتك السنوية إلى بلدك تمر عبر اعتماد. انظر <a href=\"/ar/guides/etimad-account\">تذكرتك من الجامعة: اعتماد وأمر الإركاب والقواعد</a>.</li>\n<li>الطلاب الجدد على التأشيرة التعليمية يحملون هوية زائر لا إقامة، فلا رسوم إقامة عليهم. انظر <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a>.</li>\n</ul>\n<h2>الرياضة</h2>\n<p>يدفع الطلاب أسعارًا مخفضة في نادي الجامعة الإسلامية الرياضي، أقل بكثير من سعر الجمهور، باشتراكات تمتد من شهر إلى سنة، ويمكن تجميد الاشتراكات الطويلة مدة من الزمن. وتجد جدول أسعار الطلاب كاملًا والحصص في المركز الرياضي في <a href=\"/ar/guides/sports-and-activities\">الرياضة وحصص اللياقة</a>.</p>\n<h2>من تسأل</h2>\n<p>رعاية الطلاب: <strong>920022042</strong>، أو البريد <strong>care@iu.edu.sa</strong>. وتجد أي مكتب يتولى أي أمر في <a href=\"/ar/guides/university-offices-and-contacts\">من تسأل في الجامعة الإسلامية</a>.</p>"
 },
 "check-visa-and-iqama-online": {
  "titleAr": "الاستعلام إلكترونيًا عن تأشيرتك ورقم الحدود والتأمين والمخالفات",
  "summaryAr": "الاستعلامات المتاحة بلا تسجيل دخول (رقم الحدود، وصلاحية التأشيرة وتأشيرة الخروج والعودة، والتأمين الصحي، والشرائح المسجلة على إقامتك) والاستعلامات داخل أبشر (المخالفات المرورية، وقيود السفر، وتقارير أبشر، وإقامات أسرتك)، مع قائمة تحقق قبل السفر.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. قبل أن تحجز رحلة أو تدفع رسومًا أو تشتري تأمينًا لزائر، تحقق من المعلومات في المواقع الرسمية. فعدة استعلامات لا تحتاج إلى تسجيل دخول أصلًا: رقم حدودك، وصلاحية التأشيرة أو تأشيرة الخروج والعودة، وتأمينك الصحي، والشرائح المسجلة على إقامتك. وغيرها، كالمخالفات المرورية وقيود السفر، داخل حسابك في أبشر. وهذا الدليل يشمل النوعين، لحاملي الإقامة وحاملي هوية الزائر ومن يستضيفون زوارًا من أسرهم.</p>\n<h2>ما تستطيع الاستعلام عنه، وأين</h2>\n<table><thead><tr><th>الاستعلام</th><th>تسجيل الدخول</th><th>أين</th><th>ما تدخله</th></tr></thead><tbody>\n<tr><td>رقم حدودك</td><td>لا</td><td>أبشر، الخدمات العامة</td><td>رقم التأشيرة وتاريخ إصدارها</td></tr>\n<tr><td>هل التأشيرة صالحة؟</td><td>لا</td><td>الاستعلام عن التأشيرات في مقيم</td><td>رقم الإقامة أو رقم التأشيرة، مع تاريخ الميلاد أو رقم الجواز</td></tr>\n<tr><td>تأشيرة الخروج والعودة</td><td>لا</td><td>الاستعلام عن التأشيرات في مقيم</td><td>رقم الإقامة وتاريخ الميلاد</td></tr>\n<tr><td>التأمين الصحي</td><td>لا</td><td>موقع مجلس الضمان الصحي</td><td>رقم الإقامة؛ وللزائر رقم الجواز أو التأشيرة أو الحدود</td></tr>\n<tr><td>الشرائح المسجلة على إقامتك</td><td>لا</td><td>خدمة «أرقامي» من هيئة الاتصالات والفضاء والتقنية</td><td>رقم الإقامة وتاريخ الميلاد ورمز يُرسل إلى جوالك</td></tr>\n<tr><td>المخالفات المرورية</td><td>نعم</td><td>أبشر، المخالفات المرورية</td><td>لا شيء: تظهر في حسابك</td></tr>\n<tr><td>قيود السفر والخدمات الموقوفة</td><td>نعم</td><td>الصفحة الرئيسية في أبشر</td><td>لا شيء: اضغط «متابعة»</td></tr>\n<tr><td>إقامات أسرتك وتأشيراتهم</td><td>نعم</td><td>أبشر، خدمات أفراد الأسرة</td><td>اختر الشخص</td></tr>\n</tbody></table>\n<h2>رقم حدودك</h2>\n<p>رقم الحدود هو الرقم المكون من ١٠ خانات الذي تعطيك إياه الجوازات حين تدخل المملكة أول مرة بتأشيرة جديدة. وتكتبه الجوازات بخط اليد في جوازك. وتحتاج إليه للتسجيل في أبشر زائرًا أو طالبًا جديدًا، ولشراء شريحة، ولشراء تأمين الزائر أو تجديده، ولدفع رسوم تمديد تأشيرة الزيارة، ولدفع رسوم المولود. ويستعمله طلاب التأشيرة التعليمية لهوية الزائر.</p>\n<ol>\n<li>افتح <a href=\"https://www.absher.sa/\">absher.sa</a>، ولا تسجل الدخول.</li>\n<li>افتح الخدمات العامة واختر «الاستعلام عن رقم الحدود»، ثم «لغير مواطني دول مجلس التعاون».</li>\n<li>أدخل رقم التأشيرة وتاريخ إصدارها، ثم رمز الصورة.</li>\n<li>اضغط «استعلام». فيظهر الاسم ورقم الحدود.</li>\n</ol>\n<p>ويجد المستضيف رقم حدود كل زائر في أبشر أيضًا: سجّل الدخول وافتح الزائر في خدمة تمديد تأشيرة الزيارة.</p>\n<h2>هل التأشيرة صالحة؟</h2>\n<p>الاستعلام العام عن التأشيرات في مقيم على <a href=\"https://vv.muqeem.sa/\">vv.muqeem.sa</a> مجاني ولا يحتاج إلى حساب.</p>\n<ol>\n<li>اختر الاستعلام عن التأشيرة.</li>\n<li>أدخل رقم الإقامة أو رقم التأشيرة، مع تاريخ الميلاد أو رقم الجواز، ورمز الصورة.</li>\n<li>اقرأ النتيجة: نوع التأشيرة، وتاريخ إصدارها، وهل هي صالحة.</li>\n</ol>\n<p>استعمله للتحقق من تأشيرة الزائر قبل التمديد، أو من تأشيرتك أنت بعد التجديد، قبل أن تعتمد عليها في المطار.</p>\n<h2>الاستعلام عن تأشيرة الخروج والعودة</h2>\n<ol>\n<li>في صفحة مقيم نفسها، اختر الاستعلام عن تأشيرة الخروج والعودة.</li>\n<li>أدخل رقم الإقامة وتاريخ الميلاد.</li>\n<li>ترى هل التأشيرة صالحة، ورقمها، ومدتها، والتاريخ الذي يجب أن تعود قبله.</li>\n</ol>\n<p>وبعد تسجيل الدخول إلى أبشر تجد الاستعلام نفسه في «الاستعلامات»، ثم «حالة تأشيرة الخروج والعودة»: أدخل رقم الإقامة مع رقم الجواز أو رقم التأشيرة، فيعرض أبشر هل التأشيرة سارية أو مستعملة أو منتهية أو ملغاة.</p>\n<p>قارن تاريخ «العودة قبل» بتذكرة عودتك. فإن كانت التذكرة بعده فمدد التأشيرة قبل أن تسافر: انظر <a href=\"/ar/guides/iqama-and-exit-reentry-fees\">الإقامة والخروج والعودة والخروج النهائي ورسوم المرافقين</a>. والطلاب الذين تصدر تأشيرتهم من إدارة السفر في الجامعة يتحققون منها بالطريقة نفسها.</p>\n<h2>التأمين الصحي</h2>\n<ul>\n<li><strong>حاملو الإقامة:</strong> الاستعلام في مجلس الضمان الصحي برقم إقامتك يعرض شركة التأمين، ورقم الوثيقة، ونوع التغطية، وهل الوثيقة سارية، والتواريخ. ويعرض أبشر هل التأمين ساري المفعول وتاريخ انتهائه، لك ولزوجتك وأولادك.</li>\n<li><strong>الزوار:</strong> الاستعلام بالتأشيرة في مجلس الضمان الصحي يقبل رقم الجواز أو رقم التأشيرة أو رقم الحدود.</li>\n<li><strong>قبل تمديد تأشيرة الزيارة،</strong> اشترِ وثيقة التأمين الجديدة للزائر أولًا. فمواقع شركات التأمين تجد الزائر برقم التأشيرة ورقم الجواز، ثم تطلب رقم الحدود وتاريخ انتهاء التأشيرة، وكلاهما ظاهر في أبشر.</li>\n</ul>\n<p>وطرق التحقق الأخرى في <a href=\"/ar/ask/check-health-insurance\">كيف أتأكد أن تأميني الصحي ساري المفعول؟</a></p>\n<h2>الشرائح المسجلة على إقامتك</h2>\n<p>خدمة «أرقامي» من هيئة الاتصالات والفضاء والتقنية تعرض الخطوط المسجلة على إقامتك، بلا تسجيل دخول: أدخل رقم إقامتك وتاريخ ميلادك، ثم الرمز المرسل إلى رقمك المسجل. والخط الذي لا تعرفه خطر عليك، فاطلب إلغاءه. والخطوات في <a href=\"/ar/guides/phone-sims-and-absher\">رقم جوالك والتحقق من الشرائح وأبشر</a>.</p>\n<h2>داخل حسابك في أبشر</h2>\n<h3>المخالفات المرورية</h3>\n<p>تظهر مخالفاتك تحت «المخالفات المرورية»، بالتاريخ والمكان والمبلغ، واضغط «مزيد من التفاصيل» بجانب المخالفة لترى على الخريطة مكان رصدها. ويعرضها توكلنا أيضًا، في «المخالفات المرورية» ثم «المخالفات المرورية غير المسددة». والمخالفات غير المسددة تمنع إصدار تأشيرة الخروج والعودة والتجديد وتحديث الجواز، فراجعها كل شهر. والسداد والاعتراض في <a href=\"/ar/ask/traffic-fines\">كيف أتحقق من المخالفات المرورية وأدفعها؟</a></p>\n<h3>قيود السفر والخدمات الموقوفة</h3>\n<p>القضية المنظورة بحقك يمكن أن توقف خدماتك أو تمنعك من السفر. فتحقق قبل أن تحجز رحلة إلى بلدك.</p>\n<ol>\n<li>سجّل الدخول إلى <a href=\"https://www.absher.sa/\">absher.sa</a> بحساب الأفراد.</li>\n<li>في الصفحة الرئيسية، افتح الاستعلام عن الخدمات الموقوفة وقيود السفر.</li>\n<li>اضغط «متابعة». فتظهر على الشاشة أي قضية أو قيد، وتستطيع طباعة الصفحة. وإن لم يكن شيء مسجلًا عليك أخبرك أبشر بذلك.</li>\n</ol>\n<h3>تقارير أبشر</h3>\n<p>يصدر أبشر تقارير رسمية تنزّلها وتطبعها، ومنها تقارير عن أفراد أسرتك، ومركباتك، ومخالفاتك المرورية، وحوادثك المرورية، وسجل سفرك (تواريخ دخولك وخروجك)، وتقرير من مقيم عن إقامتك.</p>\n<ol>\n<li>افتح <strong>الخدمات</strong>، ثم <strong>الخدمات العامة</strong>، ثم <strong>تقارير أبشر</strong>، ثم <strong>طلب تقرير</strong>.</li>\n<li>اختر التقرير واللغة الإنجليزية، واضغط «التالي»، وادفع الرسوم الظاهرة. فرسوم تقرير الحوادث المرورية مثلًا ٢٨٫٧٥ ريال.</li>\n<li>افتح <strong>عرض الطلبات السابقة</strong>، واختر التقرير واضغط «عرض» لتنزيله أو طباعته. ورقمه المرجعي مكتوب عليه.</li>\n</ol>\n<p>أعطاك أحدهم تقريرًا من أبشر وتريد التأكد من صحته؟ افتح «تقارير أبشر»، ثم <strong>الاستعلام عن تقرير</strong>، وأدخل رقمه المرجعي ورقم إقامة من طلبه.</p>\n<h3>إقامات أسرتك وتأشيراتهم</h3>\n<p>بصفتك رب الأسرة، ترى في «خدمات أفراد الأسرة» تاريخ انتهاء إقامة كل فرد، وبيانات جوازه، وتأشيراته. والتجديد وتوصيل البطاقة وتصحيح الاسم في <a href=\"/ar/guides/family-records-on-absher\">إقامات أسرتك وسجلاتها في أبشر</a>.</p>\n<h2>قبل السفر: فحص في خمس دقائق</h2>\n<ol>\n<li>جوازك وجواز كل مسافر معك ساريان ٣ أشهر على الأقل بعد تاريخ «العودة قبل» في التأشيرة.</li>\n<li>مقيم يعرض تأشيرة الخروج والعودة صالحة، وتاريخ «العودة قبل» فيها بعد رحلة عودتك.</li>\n<li>أبشر لا يعرض مخالفات مرورية غير مسددة عليك ولا على أي فرد من أسرتك.</li>\n<li>الاستعلام عن قيود السفر لا يعرض شيئًا مسجلًا.</li>\n<li>إقامة كل مسافر سارية ٧ أيام على الأقل بعد تاريخ «العودة قبل».</li>\n<li>التأشيرة محفوظة في جوالك ومطبوعة، لأن شركات الطيران تطلبها عند إنهاء إجراءات السفر.</li>\n</ol>\n<blockquote><p>نصيحة: ظهر لك خطأ في استعلام أو تاريخ لم تتوقعه؟ التقط صورة للشاشة قبل أي شيء آخر. ثم راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "cost-of-living": {
  "titleAr": "كم تكلف المعيشة في المدينة",
  "summaryAr": "الإيجار والطعام والفواتير والمواصلات وميزانية شهرية واقعية، للطالب الأعزب وللأسرة.",
  "bodyHtmlAr": "<p>المدينة من أرخص المدن الكبرى في المملكة للمعيشة. فشقة بغرفتي نوم هنا تكلف عادة نحو نصف ما تكلفه في جدة أو الرياض. والأرقام أدناه أسعار معتادة لأواخر ٢٠٢٥ و٢٠٢٦. فعدّها نطاقات لا عروض أسعار.</p>\n<h2>الإيجار</h2>\n<table><thead><tr><th>السكن</th><th>لمن يناسب</th><th>شهريًا (ريال)</th></tr></thead><tbody>\n<tr><td>سرير أو غرفة في شقة مشتركة</td><td>طالب أعزب</td><td>٣٠٠ إلى ١٬٠٠٠</td></tr>\n<tr><td>استوديو</td><td>شخص واحد أو زوجان</td><td>١٬٥٠٠ إلى ٢٬٥٠٠</td></tr>\n<tr><td>غرفتا نوم</td><td>أسرة صغيرة</td><td>٢٬٠٠٠ إلى ٣٬٥٠٠</td></tr>\n<tr><td>ثلاث غرف أو أربع</td><td>أسرة مع أطفال</td><td>٣٬٠٠٠ إلى ٤٬٥٠٠</td></tr>\n<tr><td>فيلا أو دور كامل</td><td>الأسر الكبيرة</td><td>من ٥٬٠٠٠</td></tr>\n<tr><td>مجمع سكني</td><td>حراسة وصالة رياضية ومسبح</td><td>من ٦٬٠٠٠</td></tr>\n</tbody></table>\n<p>هذه أسعار المفروش. والشقة الفارغة أرخص عادة بنسبة ٤٠ إلى ٥٠٪، وتأثيثها بنفسك يستحق إن كنت ستبقى سنة أو أكثر.</p>\n<blockquote><p>نصيحة: المالك الذي يؤجر مباشرة يريد عادة ستة أشهر أو اثني عشر شهرًا مقدمًا. والوسطاء يؤجرون شهرًا بشهر، مفروشًا، بسعر أعلى.</p></blockquote>\n<h2>الطعام</h2>\n<table><thead><tr><th>الصنف</th><th>السعر المعتاد (ريال)</th></tr></thead><tbody>\n<tr><td>خبز، الكيس</td><td>٣ إلى ٥</td></tr><tr><td>حليب، لتر</td><td>٦</td></tr>\n<tr><td>دجاج، كيلو</td><td>٢٥ إلى ٣٠</td></tr><tr><td>لحم بقر، كيلو</td><td>٤٠ إلى ٥٠</td></tr>\n<tr><td>أرز، ٥ كيلو</td><td>٥٠</td></tr><tr><td>بيض، ٣٠ بيضة</td><td>٢٥</td></tr>\n<tr><td>ماء شرب، ١٩ لترًا</td><td>٨</td></tr><tr><td>فواكه وخضار، الكيلو</td><td>٤ إلى ١٢</td></tr>\n<tr><td>وجبة في مطعم متوسط</td><td>٢٥ إلى ٤٠</td></tr>\n</tbody></table>\n<p>الطبخ في البيت يكلف نحو ١٠ إلى ١٥ ريالًا للوجبة. وبن داود وكارفور ولولو والعثيم وبنده هي الأسواق الكبرى، ومحلات «أبو خمسة» ممتازة لأساسيات البيت.</p>\n<h2>الفواتير</h2>\n<ul>\n<li><strong>الكهرباء:</strong> ١٠٠ إلى ٣٠٠ ريال شهريًا في الشتاء، و٢٠٠ إلى ٨٠٠ في الصيف بسبب التكييف.</li>\n<li><strong>الماء:</strong> ٣٠ إلى ٧٠ ريالًا.</li>\n<li><strong>إنترنت البيت:</strong> نحو ٢٥٠ إلى ٣٠٠ ريال، لكنه يحتاج إلى إقامة. وشريحة بيانات في جهاز توجيه محمول هي الحل المعتاد.</li>\n<li><strong>الجوال:</strong> ١٠٠ إلى ١٥٠ ريالًا على STC أو موبايلي أو زين.</li>\n</ul>\n<h2>التنقل</h2>\n<p>رحلة حافلة المدينة ٣٫٤٥ ريالات، ورحلة كريم أو أوبر عبر المدينة ١٠ إلى ٣٠ ريالًا، والبنزين ٢٫١٨ ريال للتر من ٩١ و٢٫٣٣ من ٩٥ (نوفمبر ٢٠٢٦). انظر دليل التنقل للتفاصيل.</p>\n<h2>الصحة</h2>\n<p>على تأشيرة الزيارة أو العمل التجاري لا توجد رعاية صحية مجانية. والتأمين المرفق بالتأشيرة يغطي الطوارئ فقط، فالمراجعات العادية تدفعها أنت. زيارة طبيب عام ١٠٠ إلى ٢٠٠ ريال، والاختصاصي ١٥٠ إلى ٣٠٠، وفحص الأسنان وتنظيفها ١٥٠ إلى ٢٥٠، وزيارة الطوارئ ٣٠٠ إلى ٥٠٠. واترك ٥٠٠ إلى ٨٠٠ ريال جانبًا للمفاجآت. وطلاب المنحة يعالَجون مجانًا في المركز الطبي الجامعي، وكثير من العيادات الخاصة تعطي الطلاب والموظفين خصومات كبيرة (انظر خصومات الطلاب).</p>\n<h2>ميزانية شهرية واقعية</h2>\n<table><thead><tr><th>البند</th><th>شخص واحد</th><th>أسرة من ثلاثة أو أربعة</th></tr></thead><tbody>\n<tr><td>الإيجار (غرفة مشتركة أو شقة صغيرة)</td><td>١٬٠٠٠ إلى ٢٬٠٠٠</td><td>٣٬٠٠٠ إلى ٤٬٠٠٠</td></tr>\n<tr><td>المشتريات ولوازم البيت</td><td>١٬٠٠٠</td><td>٢٬٠٠٠</td></tr>\n<tr><td>الفواتير</td><td>٣٠٠ إلى ٦٠٠</td><td>٤٠٠ إلى ٨٠٠</td></tr>\n<tr><td>المواصلات</td><td>٣٠٠ إلى ١٬٠٠٠</td><td>٣٠٠ إلى ١٬٠٠٠</td></tr>\n<tr><td>العلاج</td><td>٠ إلى ٦٠٠</td><td>٠ إلى ١٬٠٠٠</td></tr>\n<tr><td>الدراسة والكتب</td><td>٢٠٠ إلى ١٬٢٠٠</td><td>٢٠٠ إلى ٢٬٠٠٠</td></tr>\n<tr><td>كل ما سوى ذلك</td><td>١٠٠ إلى ٣٠٠</td><td>٤٠٠ إلى ٢٬٠٠٠</td></tr>\n<tr><td><strong>المجموع (ريال)</strong></td><td><strong>نحو ٢٬٩٠٠ إلى ٦٬٧٠٠</strong></td><td><strong>نحو ٦٬٣٠٠ إلى ١٢٬٨٠٠</strong></td></tr>\n</tbody></table>\n<p>ميزانية الأسرة لا تشمل رسوم المدارس. فالروضة وحدها نحو ٤٬٠٠٠ ريال في السنة للطفل (انظر رياض الأطفال والمدارس).</p>\n<blockquote><p>ملاحظة: الطلاب العزاب على منحة الجامعة الكاملة يسكنون في السكن الجامعي ويتقاضون مكافأة شهرية، فتكاليفهم أقل من هذا بكثير.</p></blockquote>\n<h2>توفير المال</h2>\n<ul>\n<li>التخفيضات الكبرى أربع مرات في السنة: عيد الفطر، وعيد الأضحى، واليوم الوطني (٢٣ سبتمبر)، ويوم التأسيس (٢٢ فبراير). والصالات الرياضية والمحلات تخفض أسعارها كثيرًا إلى النصف.</li>\n<li>تطبيق بركة يبيع طعام المطاعم غير المباع في آخر اليوم بخصم ٥٠ إلى ٧٠٪.</li>\n<li>سوق حراج في المدينة يبيع الأثاث والأجهزة الجديدة والمستعملة مع توصيل في اليوم نفسه.</li>\n</ul>"
 },
 "course-descriptions-aqeedah-dawah": {
  "titleAr": "توصيف مقررات كلية العقيدة والدعوة",
  "summaryAr": "توصيف كل مقرر في كلية العقيدة والدعوة، من المستوى الأول إلى الثامن، لتفتحه أو تنزّله.",
  "bodyHtmlAr": "<p>التوصيفات الرسمية للمقررات (توصيف المقررات) في <strong>كلية العقيدة والدعوة</strong>، إصدار عام ١٤٤٤هـ. اضغط على المستوى لترى مقرراته، ثم افتح الملف أو نزّله.</p>\n<p>نزّل الكل في ملف مضغوط: المستويات الثمانية كلها، نحو ٨٠ ميغابايت.</p>\n<p><strong>المستوى الأول (٨ مقررات)</strong>: التجويد (صورة، ٨٦ كيلوبايت)</p>\n<ul>\n<li>السيرة النبوية: «السيرة النبوية» (ملف PDF، ١٫٠ ميغابايت)، و«السيرة النبوية ترخ 3001 بكالوريوس 2023» (ملف PDF، ١٫٣ ميغابايت)</li>\n<li>الفقه 1 (ملف PDF، ٢٫٥ ميغابايت)</li>\n<li>المدخل إلى الحديث النبوي (ملف PDF، ٥١٣ كيلوبايت)</li>\n<li>المدخل إلى دراسة الأنظمة (ملف PDF، ٤٣٣ كيلوبايت)</li>\n<li>المدخل لدراسة الفقه (ملف PDF، ٩٣٢ كيلوبايت)</li>\n<li>المهارات اللغوية (ملف PDF، ٢٫٨ ميغابايت)</li>\n<li>توحيد 1: «توحيد 1 السنة المشتركة محول إلى فصلين» (ملف PDF، ٤٧٩ كيلوبايت)، و«توحيد 1 سنة مشتركة» (ملف PDF، ٥٧٨ كيلوبايت)</li>\n</ul>\n<p><strong>المستوى الثاني (٧ مقررات)</strong>: أصول الدعوة وطرقها (ملف PDF، ١٫٤ ميغابايت)</p>\n<ul>\n<li>الفقه 2 (ملف PDF، ١٫١ ميغابايت)</li>\n<li>المقدمة في مصطلح الحديث (ملف PDF، ٩٣١ كيلوبايت)</li>\n<li>النحو 1: «نحو 1» (ملف PDF، ٢٫٤ ميغابايت)، و«نحو 1 سنة مشتركة» (ملف PDF، ٥٥٠ كيلوبايت)</li>\n<li>توحيد 2: «التوحيد 2» (ملف PDF، ٨٤٣ كيلوبايت)، و«توحيد 2 السنة المشتركة محول إلى فصلين» (ملف PDF، ٤٧٨ كيلوبايت)</li>\n<li>ريادة الأعمال والإبتكار (ملف PDF، ٥٫٢ ميغابايت)</li>\n<li>مدخل إلى تفسير القرآن وعلومه (ملف PDF، ٧٤٦ كيلوبايت)</li>\n</ul>\n<p><strong>المستوى الثالث (٨ مقررات)</strong>: أصول الدعوة 1 (ملف PDF، ٦٢٨ كيلوبايت)</p>\n<ul>\n<li>التفسير1 (ملف PDF، ٥١٢ كيلوبايت)</li>\n<li>الفرق 1 (ملف PDF، ٤٦١ كيلوبايت)</li>\n<li>النحو 2 (ملف PDF، ١٫٥ ميغابايت)</li>\n<li>تاريخ الدعوة 1 (ملف PDF، ٥٨٠ كيلوبايت)</li>\n<li>تطبيقات التقنية الحديثة في الدعوة (ملف PDF، ٦٥٢ كيلوبايت)</li>\n<li>توحيد 3 (ملف PDF، ٤٧٩ كيلوبايت)</li>\n<li>مناهج البحث (ملف PDF، ٢٫٥ ميغابايت)</li>\n</ul>\n<p><strong>المستوى الرابع (٦ مقررات)</strong>: أحاديث الأحكام (معاملات) (ملف PDF، ٥٥٣ كيلوبايت)</p>\n<ul>\n<li>أصول الدعوة 2 (ملف PDF، ٥١٧ كيلوبايت)</li>\n<li>التفسير 2 (ملف PDF، ٥٥٥ كيلوبايت)</li>\n<li>الفرق 2 (ملف PDF، ٤٨٤ كيلوبايت)</li>\n<li>النحو 3 (ملف PDF، ١٫٥ ميغابايت)</li>\n<li>توحيد 4 (ملف PDF، ٤٧١ كيلوبايت)</li>\n</ul>\n<p><strong>المستوى الخامس (٩ مقررات)</strong>: أصول الدعوة 3 (ملف PDF، ١٫٣ ميغابايت)</p>\n<ul>\n<li>الأديان 1 (ملف PDF، ٤٦٧ كيلوبايت)</li>\n<li>التفسير 3 (ملف PDF، ٨٢٤ كيلوبايت)</li>\n<li>الفرق 3 (ملف PDF، ٤٨٨ كيلوبايت)</li>\n<li>المذاهب والتيارات المعاصرة 1 (ملف PDF، ٤٦٢ كيلوبايت)</li>\n<li>توحيد 5 (ملف PDF، ٤٨٥ كيلوبايت)</li>\n<li>حديث تحليلي (ملف PDF، ٨٩٨ كيلوبايت)</li>\n<li>قيم إسلامية (ملف PDF، ٦٥٢ كيلوبايت)</li>\n<li>نصوص الدعوة في القرآن والسنة (ملف PDF، ١٫٨ ميغابايت)</li>\n</ul>\n<p><strong>المستوى السادس (٩ مقررات)</strong>: أصول الدعوة 4 (ملف PDF، ٢٨٩ كيلوبايت)</p>\n<ul>\n<li>أصول الفقه 1 (ملف PDF، ٤٩٦ كيلوبايت)</li>\n<li>الأديان 2 (ملف PDF، ٤٥٩ كيلوبايت)</li>\n<li>التفسير الموضوعي (ملف PDF، ٥٦٩ كيلوبايت)</li>\n<li>الفرق 4 (ملف PDF، ٤٩٣ كيلوبايت)</li>\n<li>المذاهب والتيارات المعاصرة 2 (ملف PDF، ٤٦٢ كيلوبايت)</li>\n<li>تاريخ المملكة (ملف PDF، ٢٣٫٢ ميغابايت)</li>\n<li>توحيد 6 (ملف PDF، ٥٥٨ كيلوبايت)</li>\n<li>فقه الدعوة 1 (ملف PDF، ١٫٢ ميغابايت)</li>\n</ul>\n<p><strong>المستوى السابع (٩ مقررات)</strong>: أصول الفقه 2 (ملف PDF، ١٫١ ميغابايت)</p>\n<ul>\n<li>الأديان 3 (ملف PDF، ٤٧٥ كيلوبايت)</li>\n<li>البحث العلمي في الدعوة (ملف PDF، ١٫٢ ميغابايت)</li>\n<li>التدريب الدعوي (ملف PDF، ٦٠٧ كيلوبايت)</li>\n<li>الجدل والمنطق 1 (ملف PDF، ٤٨٩ كيلوبايت)</li>\n<li>الفرائض (ملف PDF، ٤٧٤ كيلوبايت)</li>\n<li>المذاهب والتيارات المعاصرة 3 (ملف PDF، ٤٦٥ كيلوبايت)</li>\n<li>توحيد 7 (ملف PDF، ٤٧٧ كيلوبايت)</li>\n<li>فقه الدعوة 2 (ملف PDF، ٤٫٩ ميغابايت)</li>\n</ul>\n<p><strong>المستوى الثامن (٥ مقررات)</strong>: اعتقاد الأئمة الأربعة (ملف PDF، ٤٨٠ كيلوبايت)</p>\n<ul>\n<li>البحث العلمي في العقيدة (ملف PDF، ٤٥٢ كيلوبايت)</li>\n<li>الجدل والمنطق 2 (ملف PDF، ٤٩٥ كيلوبايت)</li>\n<li>الجماعات والحركات الإسلامية المعاصرة (ملف PDF، ٤٧٨ كيلوبايت)</li>\n<li>توحيد 8 (ملف PDF، ٤٧٤ كيلوبايت)</li>\n</ul>\n<blockquote>\n<p>نصيحة:</p>\n<p>نزّل توصيف مقررك، وارفعه إلى مشروعك مع كتابك، واكتب <code>توصيف</code> في صانع الخرائط الذهنية لترى بالضبط ما يغطيه المقرر.</p>\n</blockquote>\n<blockquote>\n<p>ملاحظة:</p>\n<p>هذه التوصيفات من عام ١٤٤٤هـ، فراجع كليتك لتتأكد من أحدث نسخة. عندك نسخة أحدث؟ أرسلها إلينا.</p>\n</blockquote>"
 },
 "dates-of-madinah": {
  "titleAr": "تمور المدينة: الأصناف والسوق والموسم وأخذها إلى بلدك",
  "summaryAr": "الأصناف الرئيسية وما يميز كل صنف، والعجوة والسنة، وأين تشتري (سوق التمور المركزي ومحلات الحرم والأسواق الكبرى والمزارع)، والصرام وموسم التمور في الصيف، وكيف تختار التمر وتحفظه، وأخذه معك إلى بلدك.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. نخيل المدينة من أقدم النخيل في جزيرة العرب، والتمر جزء من كل يوم هنا: حبات مع القهوة للضيف، وسبع عجوات في الصباح، وعلبة في يد كل زائر في طريق عودته. وكل سوق يبيع أصنافًا كثيرة، والاختيار يحيّر في البداية. ويغطي هذا الدليل الأصناف التي ستراها، وأين تشتري، وموسم الصرام، وكيف تختار التمر وتحفظه، وكيف تأخذه إلى بلدك.</p>\n<h2>الأصناف</h2>\n<table><thead><tr><th>الصنف</th><th>ما يميزه</th></tr></thead><tbody>\n<tr><td><strong>عجوة</strong></td><td>أشهر الأصناف كلها. أسود تقريبًا، طريّ، فيه شيء من المضغ، وحلاوته عميقة. ولا يكاد يُزرع إلا في منطقة المدينة. وهو تمر السنة في أكل سبع تمرات في الصباح.</td></tr>\n<tr><td><strong>عنبرة</strong></td><td>طويل ممتلئ ذهبي، بنكهة الكراميل والعسل. أغلى الأصناف الشائعة، ومفضل في الهدايا.</td></tr>\n<tr><td><strong>خلاص</strong></td><td>بني فاتح طريّ بحلاوة زبدية. أصله من الأحساء. ويشيع حشوه باللوز أو الجبن الكريمي.</td></tr>\n<tr><td><strong>مبروم</strong></td><td>طويل بني محمر، أصلب وأقل دبسًا. خيار شائع للإفطار.</td></tr>\n<tr><td><strong>صفاوي</strong></td><td>بني داكن إلى أسود كالعجوة لكنه أصغر وأجف وأقل حلاوة. ويُحفظ جيدًا.</td></tr>\n<tr><td><strong>صغاي</strong></td><td>طرفه أصفر وجسمه بني، مقرمش وهو طازج ويلين بالتخزين. تمر العائلة اليومي، وسعره مناسب.</td></tr>\n<tr><td><strong>سكري</strong></td><td>ذهبي بحلاوة العسل، طريّ، غني جدًا. أفضله الطازج في صرام أواخر الصيف، بمقادير صغيرة.</td></tr>\n</tbody></table>\n<h2>العجوة والسنة</h2>\n<p>قال النبي ﷺ إن من تصبّح بسبع تمرات عجوة لم يضره في ذلك اليوم سم ولا سحر (صحيح البخاري ٥٤٤٥).</p>\n<h2>أين تشتري</h2>\n<ul>\n<li><strong>سوق التمور المركزي</strong>، سوق المدينة الجديد للجملة والتجزئة، عند تقاطع طريق الملك خالد (الدائري الثالث) مع طريق علي بن أبي طالب، ضمن مشروع مدينة الغذاء. يبيع فيه المزارعون والتجار جنبًا إلى جنب، فتتذوق وتقارن في زيارة واحدة، وهو أرخص مكان للطلبات الكبيرة.</li>\n<li><strong>المحلات حول الحرم وقباء</strong> تبيع كل الأصناف في علب هدايا مغلفة للسفر. والأسعار أعلى، لكن الراحة حقيقية حين يسافر والداك غدًا.</li>\n<li><strong>الأسواق والمتاجر الكبرى</strong> تبيع العجوة والسكري والصفاوي معبأة بأسعار ثابتة، وتاريخ التعبئة على العلبة. مناسبة للتمر اليومي.</li>\n<li><strong>المزارع</strong> في منطقة عالية المدينة: بعضها يستقبل الزوار في الصرام.</li>\n</ul>\n<h2>الصرام وموسم التمور</h2>\n<p>يبدأ الصرام في أواخر يوليو ويمتد إلى سبتمبر. وفي أسابيعه الأولى يُباع التمر طازجًا رطبًا، طريًا نديًا، يُحفظ في الثلاجة ويؤكل خلال أيام. والتمر الجاف الذي يملأ المحلات طوال السنة من الصرام نفسه. وسوق التمور في أفضل حالاته في أغسطس وسبتمبر.</p>\n<p>وكل صيف تقيم هيئة تطوير منطقة المدينة المنورة «موسم تمور المدينة» في سوق التمور المركزي. وفي ٢٠٢٦ أقيم من ٢٠ يوليو إلى ٢ أغسطس، مع حراج يومي بالجملة للتمور النادرة والمميزة من الساعة ٦ مساءً، وأجنحة لمزارع المدينة ومنتجات النخيل، ومنافذ للأسر المنتجة. وتعلن الهيئة مواعيد كل سنة قبلها بأسابيع.</p>\n<h2>الاختيار الحسن</h2>\n<ul>\n<li><strong>تذوّق قبل أن تشتري.</strong> كل محل في السوق يتيح لك التذوق. جرّب درجتين أو ثلاثًا من الصنف نفسه: فرق السعر فرق في الحجم والقوام ونظافة الثمرة.</li>\n<li><strong>ابدأ بعلبة تذوق.</strong> كثير من المحلات تبيع علبة مشكلة من عدة أصناف. جرّبها أولًا، ثم اشترِ كيلو مما أعجبك.</li>\n<li><strong>تحقق من العجوة.</strong> العجوة الجيدة متماسكة جافة قليلًا بقشرة متجعدة. والحبات الطرية جدًا اللامعة اللزجة كثيرًا ما تكون صنفًا آخر.</li>\n<li><strong>انظر إلى التاريخ على العلبة،</strong> وافتحها إن استطعت. والغبار، وبلورات السكر البيضاء على القشرة، والثقوب الصغيرة علامات على تمر قديم أو سيئ الحفظ.</li>\n<li><strong>اذهب في آخر النهار.</strong> المحلات أبرد وأهدأ، وللبائعين وقت أكثر لك.</li>\n</ul>\n<h2>حفظ التمر</h2>\n<ul>\n<li>التمر الجاف يُحفظ أسابيع في علبة مغلقة في غرفة باردة، وشهورًا في الثلاجة.</li>\n<li>وفي المجمّد يُحفظ سنة أو أكثر ويذوب في دقائق، فاشترِ في الموسم وجمّد ما لن تأكله قريبًا.</li>\n<li>أبقه محكم الإغلاق. فالتمر يأخذ رائحة ما حوله ويجف في هواء المكيف.</li>\n<li>الرطب يدخل الثلاجة مباشرة ويؤكل خلال أيام قليلة.</li>\n</ul>\n<h2>أخذ التمر إلى بلدك</h2>\n<ul>\n<li><strong>اطلب من المحل تغليفه بتفريغ الهواء.</strong> التمر المفرغ من الهواء يسافر جيدًا في الحقيبة المسجلة، ويحبس الرائحة، ويمر من التفتيش بلا مشكلة.</li>\n<li><strong>أفصح عن الطعام عند الوصول</strong> إن طلبت بلدك ذلك. أستراليا ونيوزيلندا تشترطان الإفصاح عن كل طعام، ودول كثيرة تحدد الكمية التي تدخلها لنفسك.</li>\n<li><strong>العلبة الأثقل من حقيبتك</strong> تُرسل بالبريد أو بشركة شحن، والعلبة المغلقة من التمر تسافر جيدًا: انظر <a href=\"/ar/guides/shipping-and-receiving-parcels\">إرسال الطرود واستقبالها في المدينة</a>.</li>\n<li><strong>اشترِ في المدينة.</strong> التمر الجيد هنا أرخص عادةً من بلدك للدرجة نفسها.</li>\n</ul>\n<blockquote><p>نصيحة: لست متأكدًا أي تمر تأخذ هدية؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "day-trips-from-madinah": {
  "titleAr": "رحلات اليوم الواحد وعطلات نهاية الأسبوع خارج المدينة",
  "summaryAr": "بدر وخيبر وينبع والعلا وجدة وغيرها، مع المسافة ومدة القيادة وأفضل أشهر الزيارة.",
  "bodyHtmlAr": "<p>المسافات والمدد بالطريق البري من المدينة. وفي أي وجهة تتجاوز ٣٠٠ كم يكون الطيران أسهل في أغلب الأحيان، وقطار الحرمين يصل إلى جدة ومكة. روجع في نوفمبر ٢٠٢٦.</p>\n<table><thead><tr><th>الوجهة</th><th>المسافة</th><th>مدة القيادة</th><th>ما تناسبه</th></tr></thead><tbody>\n<tr><td>وادي الجن</td><td>نحو ٣٠ كم</td><td>نحو ٤٠ دقيقة</td><td>نزهة نصف يوم إلى الوادي الذي يُخيَّل فيه للناظر أن السيارات تصعد المرتفع من تلقاء نفسها. وتكفي أي سيارة، ولا تحتاج إلى مرشد.</td></tr>\n<tr><td>بدر</td><td>نحو ١٥٠ كم</td><td>ساعة ونصف إلى ساعتين</td><td>موقع غزوة بدر، وفيه مركز للزوار ولوحات بالعربية والإنجليزية. انطلق بعد الفجر وعُد قبل المغرب. وخذ معك الماء والطعام، فالخدمات محدودة.</td></tr>\n<tr><td>خيبر</td><td>نحو ١٧٠ كم</td><td>نحو ساعتين</td><td>الواحة والحصون التي شهدت غزوة خيبر، وبساتين النخيل، والحرات البركانية السوداء. وتفيدك سيارة الدفع الرباعي في الحرات.</td></tr>\n<tr><td>ينبع</td><td>نحو ٢٣٠ كم</td><td>ساعتان ونصف إلى ثلاث ساعات</td><td>شواطئ البحر الأحمر والغوص السطحي والكورنيش. ويقضي فيها كثيرون يومي الجمعة والسبت.</td></tr>\n<tr><td>العلا والحِجر</td><td>نحو ٣٤٠ كم</td><td>ثلاث ساعات ونصف إلى أربع ساعات</td><td>مقابر الحِجر المسجلة في قائمة التراث العالمي لليونسكو، والبلدة القديمة، وتضاريس الصخور الرملية. وخصص لها يومين أو ثلاثة. ولا يُزار الحِجر إلا ضمن جولة بمرشد في موعد محدد، تُحجز عبر Experience AlUla (من نحو ٩٥ ريالًا للشخص، نوفمبر ٢٠٢٦)، ولا يُسمح للسيارات الخاصة بالسير داخله، فاحجز مسبقًا.</td></tr>\n<tr><td>جدة (البلد)</td><td>نحو ٤٢٠ كم</td><td>أربع إلى خمس ساعات</td><td>البلدة القديمة والكورنيش والمأكولات البحرية. وتستغرق الرحلة بقطار الحرمين نحو ساعتين.</td></tr>\n<tr><td>تبوك</td><td>نحو ٧٠٠ كم</td><td>سبع إلى ثماني ساعات</td><td>قلعة تبوك والطريق إلى الساحل الشمالي الغربي. والطيران هو الخيار العملي.</td></tr>\n</tbody></table>\n<blockquote><p>نصيحة: أفضل وقت لكل الرحلات أعلاه من أكتوبر إلى أبريل. وفي الصيف انطلق مع الفجر وتجنب منتصف النهار.</p></blockquote>\n<h2>قبل أن تنطلق</h2>\n<ol>\n<li>املأ خزان الوقود، واحمل في الطرق الصحراوية ١٠ لترات من الماء على الأقل لكل شخص.</li>\n<li>تابع حالة الطقس، فالأمطار الغزيرة في الشتاء يمكن أن تُحدث سيولًا جارفة في الأودية.</li>\n<li>أخبر أحدًا بطريقك، فتغطية الجوال تضعف إذا ابتعدت عن المدينة أكثر من ٣٠ كم.</li>\n<li>احتفظ بإقامتك أو جوازك وأوراق سيارتك معك لإبرازها عند نقاط التفتيش.</li>\n</ol>\n<p>يتطلب استئجار السيارة رخصة قيادة تعترف بها المملكة، ومعها في العادة رخصة القيادة الدولية، وكثير من الشركات تطلب الإقامة. انظر <a href=\"/ar/guides/drivers-license\">القيادة في المدينة: رخصة القيادة السعودية</a> و<a href=\"/ar/guides/getting-around\">التنقل في المدينة، وإلى مكة</a>.</p>"
 },
 "doctors-hospitals-and-pharmacies": {
  "titleAr": "الأطباء والمستشفيات والصيدليات وأرقام الطوارئ",
  "summaryAr": "أرقام الطوارئ، وأين تذهب للعلاج، والمستشفيات الرئيسية وسلاسل الصيدليات، والتطبيقات الصحية.",
  "bodyHtmlAr": "<h2>أرقام الطوارئ</h2>\n<table><thead><tr><th>الرقم</th><th>لماذا</th></tr></thead><tbody>\n<tr><td><strong>997</strong></td><td>الإسعاف (الهلال الأحمر السعودي)</td></tr>\n<tr><td><strong>911</strong></td><td>الرقم الموحد للطوارئ، ويعمل في المدينة أيضًا</td></tr>\n<tr><td><strong>999</strong></td><td>الشرطة</td></tr>\n<tr><td><strong>998</strong></td><td>الدفاع المدني (الحريق)</td></tr>\n<tr><td><strong>937</strong></td><td>خط الاستشارات في وزارة الصحة، على مدار الساعة، بعدة لغات</td></tr>\n</tbody></table>\n<h2>أين تذهب</h2>\n<ul>\n<li><strong>طلاب الجامعة:</strong> ابدأ بالمركز الطبي الجامعي في الحرم الجامعي. وهو مجاني لطلاب المنحة. تعمل العيادات من الأحد إلى الخميس من ٨:٠٠ صباحًا إلى ٣:١٥ ظهرًا. وتليها مناوبة طوارئ حتى ١١:٠٠ مساءً في تلك الأيام، ومن ١:٠٠ ظهرًا إلى ٩:٠٠ مساءً يومي الجمعة والسبت. احجز مواعيد العيادات على <a href=\"https://vcappointments.iu.edu.sa/\">vcappointments.iu.edu.sa</a> بحسابك الجامعي. ويعالج المركز الطبي أفراد الأسرة المسجلين على إقامتك، بعد أن يُفتح لهم ملف حضوريًا في المركز، ثم يحجزون مواعيدهم على الموقع نفسه. وكثير من العيادات الخاصة تعطي الطلاب خصومات كبيرة أيضًا (انظر <a href=\"/ar/discounts\">خصومات الطلاب</a>).</li>\n<li><strong>المرض الخفيف:</strong> العيادة الخاصة أسرع. وزيارة الطبيب العام تكلف عادة ١٠٠ إلى ٢٠٠ ريال (انظر <a href=\"/ar/guides/cost-of-living\">كم تكلف المعيشة في المدينة</a>).</li>\n<li><strong>الطوارئ:</strong> اذهب إلى أقرب قسم طوارئ في مستشفى، أو اتصل بالرقم 997.</li>\n<li><strong>الزائرون:</strong> كل تأشيرة زيارة يأتي معها تأمين طبي إلزامي، لكنه يغطي الطوارئ فقط، حتى ١٠٠٬٠٠٠ ريال، بحدود منخفضة لطوارئ الأسنان والولادة. والمراجعات العادية تدفعها أنت، والمستشفى الخاص يطلب أحيانًا الدفع مقدمًا، فاترك بعض المال جانبًا أو اشترِ تغطية إضافية. وإن مددت تأشيرتك فلا بد من تمديد التأمين أيضًا.</li>\n</ul>\n<h2>المستشفيات الرئيسية</h2>\n<p>مرتبة أبجديًا. وتختلف الأسعار والخدمات، فاسأل قبل الحجز. والأطباء يتكلمون الإنجليزية عادة، وموظفو الاستقبال والتمريض أقل من ذلك.</p>\n<ul>\n<li>مستشفى أحد (حكومي)</li>\n<li>مستشفى الزهراء (خاص)</li>\n<li>مستشفى السعودي الألماني (خاص)</li>\n<li>مستشفى المدينة الوطني (خاص)</li>\n<li>مستشفى الملك فهد (حكومي)</li>\n<li>مستشفى المواساة (خاص)</li>\n<li>مستشفى الولادة والأطفال بالمدينة (حكومي)</li>\n<li>مستشفى حياة الوطني (خاص)</li>\n</ul>\n<p>رسوم الولادة وقواعد الزوج والمرافق والخيار المجاني لزوجات طلاب الجامعة في <a href=\"/ar/guides/having-a-baby-in-madinah\">الولادة في المدينة</a>.</p>\n<h2>الصيدليات</h2>\n<p>الدواء والنهدي هما السلسلتان الكبيرتان، بفروع في أنحاء المدينة وبعضها مفتوح على مدار الساعة. ومعظم الموظفين يتكلمون الإنجليزية. أحضر علبة الدواء الذي تأخذه أو اسمه، ونسخة من الوصفة لأي دواء أقوى من الأساسيات.</p>\n<p>الوصفات من البلدان الأخرى لا تُقبل، ولا يصف الدواء إلا طبيب مرخص في السعودية. وبعض الأدوية خاضعة للرقابة. فإن كنت تأخذ دواءً بانتظام فأحضر خطابًا من طبيبك يذكر الدواء والجرعة والكمية.</p>\n<h2>التطبيقات الصحية</h2>\n<ul>\n<li><strong>الطبي:</strong> استشارات بالفيديو ومكتبة معلومات طبية.</li>\n<li><strong>كيورا:</strong> استشارات بالفيديو مع أطباء في تخصصات كثيرة، مع توصيل الوصفات.</li>\n<li><strong>صحتي:</strong> تطبيق وزارة الصحة للمقيمين، للمواعيد والسجلات.</li>\n</ul>\n<h2>التأمين</h2>\n<p>للتحقق من سريان تأمينك الصحي انظر الجواب عن التحقق من التأمين.</p>"
 },
 "drivers-license": {
  "titleAr": "القيادة في المدينة: رخصة القيادة السعودية ومدرسة القيادة والتأمين والمخالفات وتأجير السيارات",
  "summaryAr": "من يقود بماذا، واستبدال الرخصة الأجنبية في المدرسة النموذجية، وطريق مدرسة القيادة، والتجديد، والتأمين، وما تفعله بعد الحادث، والمخالفات الشائعة وكاميرات ساهر، وتأجير السيارة أو شراؤها، وإبقاء السيارة نظامية في أبشر (الاستمارة والفحص الدوري وتفويض سائق آخر). والاستبدال يحتاج إلى إقامة.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. المدينة مدينة سهلة للقيادة: طرق واسعة، ووقود رخيص، ومواقف عند الحرم لا تمتلئ إلا يوم الجمعة وفي رمضان. وما تحتاجه لتقود يعتمد على ما تحمله.</p>\n<table><thead><tr><th>تحمل</th><th>تستطيع القيادة بـ</th><th>رخصة سعودية</th><th>شراء سيارة</th></tr></thead><tbody>\n<tr><td>تأشيرة زيارة أو سياحية</td><td>رخصة بلدك السارية، مع رخصة قيادة دولية أو ترجمة عربية من مكتب معتمد إن لم تكن بالعربية، لسنة من يوم دخولك أو حتى انتهاء الرخصة، أيهما أسبق</td><td>لا</td><td>لا. استأجر بدلًا من ذلك</td></tr>\n<tr><td>هوية زائر (التأشيرة التعليمية)</td><td>رخصة بلدك السارية ورخصة قيادة دولية، للسنة نفسها من الدخول</td><td>لا. الاستبدال ومدرسة القيادة كلاهما يحتاج إلى إقامة</td><td>لا. استأجر بدلًا من ذلك</td></tr>\n<tr><td>إقامة</td><td>رخصة بلدك لمدة قصيرة بعد صدور الإقامة</td><td>نعم: استبدل رخصتك أو ادخل مدرسة القيادة</td><td>نعم</td></tr>\n</tbody></table>\n<p>احمل دائمًا الرخصة الأصلية لا صورتها، ويجب أن تطابق فئتها السيارة. ورخصة القيادة الدولية ترجمة لرخصتك لا رخصة بذاتها، فلا تصح إلا مع الأصل، والرخص الدولية الصادرة من دول الخليج غير مقبولة هنا.</p>\n<p>تقود النساء في السعودية منذ يونيو ٢٠١٨، بالرخصة نفسها والرسوم نفسها والخطوات نفسها التي للرجال. وفي المدرسة النموذجية بالمدينة قسم نسائي منفصل بمدربات، ولا يُطلب زوج ولا محرم في أي خطوة.</p>\n<h2>كم تكلف</h2>\n<table><thead><tr><th>البند</th><th>التكلفة (ريال)، حتى نوفمبر ٢٠٢٦</th><th>تُدفع إلى</th></tr></thead><tbody>\n<tr><td>رخصة خصوصي، ٤٠ في السنة</td><td>٨٠ لسنتين، و٢٠٠ لخمس سنوات، و٤٠٠ لعشر سنوات</td><td>المدفوعات الحكومية في تطبيق بنكك (سداد)</td></tr>\n<tr><td>الفحص الطبي «إفادة»</td><td>٦٠ إلى ٢٠٠</td><td>العيادة المعتمدة</td></tr>\n<tr><td>ترجمة معتمدة لرخصتك إلى العربية</td><td>٥٠ إلى ١٠٠</td><td>مكتب ترجمة معتمد، وغالبًا عبر الإنترنت</td></tr>\n<tr><td>تدريب مدرسة القيادة، إن احتجته</td><td>نحو ٧٠٠ لأقصر دورة إلى نحو ٢٬٨٠٠ لدورة المبتدئين ذات الثلاثين ساعة</td><td>المدرسة، بعد أن يحدد تقييمها ساعاتك</td></tr>\n</tbody></table>\n<h2>استبدال رخصتك الأجنبية (لحاملي الإقامة)</h2>\n<p>حاملو الرخص من قائمة دول، منها دول الخليج وبريطانيا وأمريكا وكندا وأستراليا ومعظم أوروبا، يستبدلون رخصهم بلا دورة في مدرسة القيادة. وفي الموعد تتحقق المدرسة من الرخصة ويمكن أن تطلب منك تقييمًا قصيرًا في القيادة. وغيرهم يُحالون إلى تدريب المدرسة واختبارها. ويجب أن تكون رخصتك سارية، ورخصة كاملة لا رخصة متعلم أو مؤقتة، وخطط للاستبدال خلال ثلاثة أشهر من صدور إقامتك.</p>\n<ol>\n<li><strong>ترجم رخصتك إلى العربية</strong> في مكتب ترجمة معتمد، إن لم تكن بالعربية أو الإنجليزية. وكثير من المكاتب تعمل عبر الإنترنت كليًا وترسل ملف PDF موقعًا ومختومًا في اليوم نفسه.</li>\n<li><strong>أجرِ الفحص الطبي</strong> في عيادة معتمدة لتقرير «إفادة» الطبي. يفحصون نظرك وفصيلة دمك ولياقتك العامة، وتصل النتيجة إلى أبشر خلال يوم. وحتى نوفمبر ٢٠٢٦ يكلف الفحص ٦٠ إلى ٢٠٠ ريال بحسب العيادة. والمختبر الإقليمي وبنك الدم المركزي، على بُعد رحلة قصيرة بسيارة أجرة من الجامعة، يجريه.</li>\n<li><strong>احجز موعدًا على absher.sa</strong> من الحاسوب لا من التطبيق: مواعيد، ثم المرور، ثم <em>استبدال رخصة القيادة</em>. واختر المدرسة النموذجية لتعليم قيادة السيارات، على طريق المطار في حي العاقول. فالمدارس الأخرى لا تستبدل الرخص الأجنبية.</li>\n<li><strong>ارفع ثلاثة ملفات PDF:</strong> الترجمة، ووجه رخصتك الأصلية وظهرها.</li>\n<li><strong>ادفع رسوم الرخصة في تطبيق بنكك:</strong> المدفوعات، ثم المدفوعات الحكومية، ثم رخصة القيادة، ثم إصدار رخصة. أدخل رقم إقامتك، واختر خصوصي، ثم المدة. والرسوم ٤٠ ريالًا في السنة: سنتان ٨٠ ريالًا، وخمس سنوات ٢٠٠ ريال، وعشر سنوات ٤٠٠ ريال.</li>\n<li><strong>احضر موعدك</strong> برخصتك الأصلية والترجمة وصورة شخصية وإقامتك (البطاقة أو الرقمية في أبشر).</li>\n<li><strong>راجع أبشر بعدها.</strong> تظهر رخصتك السعودية فيه بعد صدورها، ويعرض أبشر توصيل البطاقة إلى عنوانك الوطني.</li>\n</ol>\n<blockquote><p>ملاحظة: أناس قرب مدرسة القيادة يعرضون حجز موعد لك بمبلغ صغير، لكنهم يطلبون كلمة مرور أبشر أو الرمز الذي يصل إلى جوالك. لا تعطِ أيًا منهما أبدًا. واحجز الموعد بنفسك في أبشر.</p></blockquote>\n<blockquote><p>ملاحظة: إن كنت تحمل رخصة سعودية من قبل وعدت بإقامة جديدة فلا تبدأ من جديد. انقلها أو جددها على الإقامة الجديدة عبر أبشر.</p></blockquote>\n<h2>إن لم يكن بلدك في القائمة: مدرسة القيادة</h2>\n<p>تدخل المدرسة نفسها التي يدخلها السائق الجديد، لكن رخصة بلدك تقصّر التدريب.</p>\n<ol>\n<li>أجرِ الفحص الطبي «إفادة» كما سبق.</li>\n<li>في أبشر افتح مواعيد، ثم المرور، ثم <em>إصدار رخصة قيادة</em>، واحجز في مدرسة قيادة. ويجب ألا يقل عمرك عن ١٨ سنة.</li>\n<li>في المدرسة ادفع رسوم التدريب واحضر الدروس النظرية واختبار الحاسوب في إشارات الطريق وقواعده. والاختبار متاح بالإنجليزية.</li>\n<li>أدِّ تقييم القيادة. وهو يحدد كم ساعة تدريب تُعطى، من نحو ست ساعات للسائق المتمكن إلى ثلاثين للمبتدئ.</li>\n<li>انجح في الاختبار العملي، وادفع رسوم الرخصة كما سبق، واستلم الرخصة أو اطلب توصيلها.</li>\n</ol>\n<p>رسوم المدرسة في الجدول أعلاه، مضافة إلى الفحص الطبي ورسوم الرخصة. وعلى الإنترنت اختبارات تدريبية مجانية للاختبار النظري بالإنجليزية.</p>\n<h2>تجديد رخصتك وفقدانها وقراءتها</h2>\n<ul>\n<li>جدد في أبشر تحت الخدمات، ثم المرور، ثم خدمات رخص القيادة، حين تدخل الرخصة أشهرها الأخيرة. وتحتاج تقرير «إفادة» طبيًا جديدًا في النظام، ودفع كل مخالفة مرورية، ورسوم السنوات التي تختارها. ويمكن توصيل البطاقة الجديدة إلى عنوانك الوطني.</li>\n<li>لا تتجاوز الرخصة مدة إقامتك، فالإقامة القصيرة تعطي رخصة قصيرة.</li>\n<li>البطاقة المفقودة أو التالفة تُستبدل في أبشر من القائمة نفسها، برسوم تظهر قبل أن تدفع.</li>\n<li>الرقم المطبوع تحت «القيود» شرط، مثل وجوب لبس النظارة أو العدسات اللاصقة.</li>\n</ul>\n<h2>التأمين والحوادث</h2>\n<ul>\n<li><strong>التأمين ضد الغير هو القانون.</strong> كل سيارة يجب أن يكون لها، ولا يسجل أبشر سيارة باسمك ولا ينقلها بلا وثيقة باسمك. والتأمين الشامل لسيارتك أنت اختياري، والبنك الذي يمول سيارة يشترطه.</li>\n<li><strong>قارن الوثائق عبر الإنترنت.</strong> عدة مواقع مقارنة سعودية تعرض أسعار كل شركة تأمين مرخصة مرة واحدة. وتعتمد الأسعار على السيارة وعمرك وسجلك.</li>\n<li><strong>حادث صغير بلا إصابات:</strong> تنحَّ إلى الجانب إن استطعت، ولا تغادر، وبلّغ عبر تطبيق نجم أو على 920000560. يسجل مندوب نجم الضرر ويحدد المسؤولية ويرسل التقرير إلى شركتي التأمين. وبلّغ خلال ٢٤ ساعة.</li>\n<li><strong>إصابة، أو حريق، أو لا تأمين على أي من السيارتين، أو خلاف:</strong> اتصل بالرقم 911، أو بالمرور على الرقم 993، وانتظرهم.</li>\n</ul>\n<h3>بعد الحادث، خطوة بخطوة</h3>\n<ol>\n<li><strong>بلّغ عنه في تطبيق نجم.</strong> سجّل برقم إقامتك وأكّد التسجيل في نفاذ، واضغط «الإبلاغ عن حادث»، وأضف بيانات السيارة الأخرى، وارفع صور السيارتين. ويعيّن نجم مندوبًا للحادث. وتصلك رسالة نصية من نجم تؤكد تسجيل الحالة، ثم رسالة ثانية من المرور تؤكد تقرير الحادث.</li>\n<li><strong>في السيارة المستأجرة</strong> اتصل بشركة التأجير بعد نجم مباشرة، وهي تتولى الباقي معك.</li>\n<li><strong>قدّر الأضرار</strong> لدى «تقدير» ومعك تقرير نجم. فالتقدير لازم لمطالبة التأمين.</li>\n<li><strong>طالب بالتعويض.</strong> إن كان السائق الآخر هو المخطئ فطالب شركة تأمينه عبر موقعها وارفع التقارير. وإن كنت المخطئ كليًا ولديك تأمين شامل فطالب شركة تأمينك. وتدفع شركة التأمين خلال ١٥ يومًا من اعتماد المطالبة.</li>\n<li><strong>السائق الآخر بلا تأمين؟</strong> احجز موعدًا في إدارة المرور، وخذ معك التقدير، واطلب من الضابط التقرير النهائي. فإن كان تأمينك شاملًا فسلّم ذلك التقرير إلى شركة تأمينك. وإن كان تأمينك ضد الغير فقط فارفع المطالبة في ناجز، فيحيلها إلى منصة تراضي لجلسة صلح إلكترونية، وإن لم يدفع بعد ذلك فاطلب عبر ناجز من محكمة التنفيذ أن تحصّل المبلغ منه.</li>\n<li><strong>استخرج تصريح إصلاح قبل أن تبدأ الورشة العمل في السيارة:</strong> أبشر، ثم المركبات، ثم إدارة المركبات، واختر السيارة، ثم إصدار تصريح إصلاح مركبة. وللحادث المسجل أصدره خلال ٩٠ يومًا من الحادث. وللضرر الذي لا حادث مسجلًا له يعطي أبشر تصريحًا واحدًا لكل سيارة في كل سنة ميلادية، وللتصريح الثاني راجع إدارة المرور. ثم تستلم الورشة التصريح، والتصريح الذي لا تستلمه أي ورشة خلال ٢٤ ساعة ينتهي.</li>\n<li><strong>تحتاج سجلًا بحوادثك؟</strong> أبشر، ثم الخدمات العامة، ثم تقارير أبشر، ثم طلب تقرير، ثم الحوادث المرورية. ويعرض التقرير آخر سنتين، ويكلف ٢٨٫٧٥ ريال.</li>\n</ol>\n<p>لا تغادر موقع حادث بسيارتك أبدًا. فمغادرة الموقع عقوبتها غرامة تصل إلى ١٠٬٠٠٠ ريال والسجن حتى ٣ أشهر. والتسبب في وفاة تصل عقوبته إلى السجن ٤ سنوات وغرامة ٢٠٠٬٠٠٠ ريال، والإصابات التي تزيد مدتها على ١٥ يومًا تصل عقوبتها إلى السجن سنتين و١٠٠٬٠٠٠ ريال. صدم أحدهم سيارتك وهرب؟ سجّل رقم اللوحة، وأبلغ المرور، واستخرج تقدير الأضرار وتصريح الإصلاح، وطالب شركة تأمينك إن كان تأمينك شاملًا.</p>\n<h2>المخالفات والكاميرات والنقاط</h2>\n<p>تحمل طرق المدينة الرئيسية كاميرات ساهر للسرعة والإشارة الحمراء، وتظهر كاميرات متنقلة في مسارات الحافلات. وتصل المخالفات في أبشر بلا ورقة، فراجع مخالفاتك كل شهر، وادفع في تطبيق بنكك تحت المدفوعات الحكومية، واعترض في أبشر خلال ٣٠ يومًا إن كانت المخالفة خطأ. وحتى نوفمبر ٢٠٢٦ المخالفات الشائعة:</p>\n<table><thead><tr><th>المخالفة</th><th>الغرامة (ريال)</th></tr></thead><tbody>\n<tr><td>الجوال في اليد أثناء القيادة</td><td>٥٠٠ إلى ٩٠٠</td></tr>\n<tr><td>عدم ربط حزام الأمان</td><td>١٥٠ إلى ٣٠٠</td></tr>\n<tr><td>قطع الإشارة الحمراء</td><td>٣٬٠٠٠ إلى ٦٬٠٠٠، وتُحجز السيارة عند التكرار</td></tr>\n<tr><td>تجاوز السرعة</td><td>من ٣٠٠ ريال، وترتفع مع السرعة إلى ٢٬٠٠٠ ريال وأكثر</td></tr>\n<tr><td>استمارة منتهية</td><td>١٠٠ إلى ١٥٠</td></tr>\n<tr><td>الوقوف في موقف ذوي الإعاقة</td><td>٥٠٠ إلى ٩٠٠</td></tr>\n</tbody></table>\n<p>وتضيف المخالفات الجسيمة نقاطًا إلى رخصتك، وتكفي النقاط لإيقافها. والمخالفات غير المدفوعة توقف تأشيرة الخروج والعودة، وتعطل تجديد الإقامة، وتمنع بيع السيارة. انظر <a href=\"/ar/ask/traffic-fines\">كيف أتحقق من المخالفات المرورية وأدفعها؟</a></p>\n<h2>تأجير سيارة</h2>\n<p>التأجير هو الحل لمن لا إقامة له، وللأسر التي عندها زائرون. وشركات في المطار وفي أنحاء المدينة تؤجر باليوم والأسبوع والشهر. والشروط المعتادة: أن تكون في الحادية والعشرين أو أكبر، وتحمل رخصة بالإنجليزية أو العربية أو رخصة قيادة دولية معها، وتدفع ببطاقة ائتمانية باسمك. وكل مخالفة كاميرا أثناء التأجير تُحمَّل عليك، مع رسوم الشركة الإدارية فوقها، فقُدها بحرص كأنها سيارتك. والتأجير الشهري لسيارة صغيرة من أرخص الطرق لتكون للأسرة سيارة لموسم.</p>\n<h2>شراء سيارة</h2>\n<p>بالإقامة تستطيع شراء سيارة مستعملة ونقلها إلى اسمك في أبشر. وما تتحقق منه قبل أن تدفع، والخطوات، في <a href=\"/ar/ask/buying-a-used-car\">هل أستطيع شراء سيارة مستعملة وأنا طالب، وماذا أحتاج؟</a>. وحين تغادر المملكة بعها أولًا: فالسيارة باسمك تمنع الخروج النهائي. انظر <a href=\"/ar/guides/graduate-procedures\">مغادرة المدينة نهائيًا</a>.</p>\n<h2>إبقاء سيارتك نظامية: خدمات المركبات في أبشر</h2>\n<p>كل ما يلي في أبشر تحت <strong>المركبات</strong>، ثم <strong>الخدمات</strong>، ثم <strong>إدارة المركبات</strong>، حيث تختار السيارة.</p>\n<h3>تجديد رخصة السير (الاستمارة)</h3>\n<ol>\n<li>جدد متى بقي على الاستمارة أقل من ١٨٠ يومًا. ولا يجدد أبشر إلا مع تأمين سارٍ، وفحص دوري سارٍ، وسداد كل المخالفات المرورية، وسداد أي غرامة تأخير على الاستمارة.</li>\n<li>اختر السيارة، ثم <strong>تجديد رخصة سير مركبة</strong>. ويعرض أبشر الرسوم، وهي تعتمد على سعة المحرك في السيارات المصنوعة سنة ٢٠١٥ أو قبلها، وعلى كفاءة استهلاك الوقود في السيارات الأحدث، من غير رسوم للأعلى كفاءة إلى ١٩٠ ريالًا في السنة. ادفعها في تطبيق بنكك، ثم وافق على الشروط وأكّد في أبشر.</li>\n<li>البطاقة التي لا يُطبع عليها تاريخ انتهاء تبقى سارية، فاحتفظ بها. وإلا فاطلب البطاقة الجديدة بالبريد خلال ٩٠ يومًا من التجديد، أو استلمها من إدارة المرور بموعد لخدمة «طباعة رخصة سير مركبة».</li>\n</ol>\n<h3>الفحص الفني الدوري</h3>\n<ul>\n<li>السيارة الخاصة الجديدة يكون فحصها الأول بعد ثلاث سنوات من أول تسجيل لها، ثم مرة كل سنة. والفحص الساري لازم لتجديد الاستمارة ولبيع السيارة.</li>\n<li>مراكز الفحص لا تستقبل إلا بموعد. احجز في <a href=\"https://vi.vsafety.sa/\">vi.vsafety.sa</a>: أدخل اسمك ورقم جوالك وبريدك الإلكتروني (أو بيانات من ترسله بالسيارة)، واختر مركبة مسجلة، ثم السعودية، ثم رقم لوحتك، ثم مركبة خصوصي، ثم الفحص الدوري، ثم منطقتك والمركز والتاريخ والوقت، وأكّد بالرمز الذي يصل إلى جوالك. واحتفظ بالتأكيد.</li>\n<li>لتعرف تاريخ الفحص افتح السيارة في إدارة المركبات واضغط «تفاصيل أكثر».</li>\n</ul>\n<h3>التأمين</h3>\n<p>افتح السيارة في إدارة المركبات لترى شركة التأمين، وتاريخ بداية الوثيقة، وحالتها، وتاريخ انتهائها. وجددها قبل ذلك التاريخ: فالقيادة بلا تأمين غرامتها ١٥٠ ريالًا، ولا تُجدد الاستمارة بلا وثيقة سارية.</p>\n<h3>السماح لغيرك بقيادة سيارتك</h3>\n<ol>\n<li>افتح السيارة واختر <strong>إصدار تفويض قيادة</strong>، ثم وافق على الشروط.</li>\n<li>أدخل رقم إقامة السائق وتاريخ ميلاده، واختر داخل السعودية أو خارجها، ثم المدة.</li>\n<li>أدخل الرمز الذي يصل إلى جوال السائق المسجل في أبشر، فأبقِ السائق بجانبك، ثم اطبع التأكيد.</li>\n</ol>\n<ul>\n<li>يجب أن تكون استمارة السيارة وتأمينها ساريين. ويجب أن تكون إقامة السائق ورخصته ساريتين، وأن يكون له حساب في أبشر، وألا تكون عليه مخالفات غير مدفوعة.</li>\n<li>داخل المملكة تستطيع تفويض أي حامل إقامة، لأي مدة. أما خارج المملكة فلا تفوّض إلا أفراد أسرتك، ولا يتجاوز التفويض مدة تأشيرة الخروج والعودة التي معهم.</li>\n<li>لكل سيارة سائق مفوَّض واحد في الوقت نفسه. والمخالفات المرورية أثناء التفويض تُسجل على السائق المفوَّض.</li>\n<li>لإنهاء التفويض قبل موعده افتح «عرض أو إلغاء تفويض القيادة». ويستطيع السائق أيضًا إنهاءه من «تفويضات القيادة المستلمة»، برمز يصل إليك.</li>\n</ul>\n<h3>سيارتك ليست حيث أوقفتها</h3>\n<p>قبل أن تبلّغ عن سرقة تحقق هل سحبها المرور: أبشر، ثم المركبات، ثم الاستعلامات، ثم الاستعلام عن المركبات المحجوزة، واختر السيارة. وتعرض الصفحة التاريخ والمكان إن كانت السيارة مسحوبة.</p>\n<h3>البطاقات بالبريد</h3>\n<p>يمكن إرسال رخصة القيادة أو الاستمارة أو الإقامة، الجديدة أو المجددة، بالبريد إلى عنوانك الوطني خلال ٩٠ يومًا من صدورها: أبشر، ثم خدماتي، ثم خدمة التوصيل البريدي، ثم طلب توصيل الوثائق بالبريد. اختر الوثيقة والعنوان ورقم جوالك. ويرسل البريد السعودي رسالة نصية فيها رابط لدفع ١٧٫٢٥ ريال، ثم رسالة ثانية برقم التتبع. وتصل البطاقة في نحو ثلاثة أيام عمل.</p>\n<h2>القيادة الحسنة في المدينة</h2>\n<ul>\n<li>يُباع الوقود باللتر في كل محطة، ٢٫١٨ ريال لبنزين ٩١ و٢٫٣٣ ريال لبنزين ٩٥ حتى نوفمبر ٢٠٢٦، ومعظم المحطات تقبل البطاقات والدفع بالجوال.</li>\n<li>الطرق الدائرية سريعة. وداخل المنطقة المركزية حول الحرم تنخفض حدود السرعة وتكثر الكاميرات.</li>\n<li>الجمعة قبل صلاة الجمعة، وليالي رمضان، وأيام العيد هي الأوقات الوحيدة التي يصعب فيها الوقوف قرب الحرم. والمواقف تحت الساحات تمتلئ أولًا.</li>\n<li>إلى مكة، قطار الحرمين والحافلات أرخص وأهدأ من القيادة: انظر <a href=\"/ar/guides/getting-around\">التنقل في المدينة، وإلى مكة</a>.</li>\n</ul>\n<p>الطلاب على التأشيرة التعليمية: ما يعمل وما لا يعمل بهوية الزائر في <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a>.</p>\n<blockquote><p>نصيحة: لست متأكدًا هل تُستبدل رخصة بلدك بلا اختبار؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "eid-al-adha-and-udhiyah": {
  "titleAr": "عيد الأضحى والأضحية في المدينة",
  "summaryAr": "العشر من ذي الحجة ويوم عرفة في المدينة، والطرق الرسمية لشراء الأضحية وذبحها مع أسعار ٢٠٢٦، وأيام الذبح، وإرسال الأضحية إلى الخارج، وتوزيع اللحم، وما يغلق في إجازة عيد ١٤٤٨.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. في ١٤٤٨ يوافق أول ذي الحجة الجمعة ٧ مايو ٢٠٢٧، ويوم عرفة السبت ١٥ مايو، والعيد الأحد ١٦ مايو، وفق تقويم أم القرى. ويغطي هذا الدليل تلك الأيام، والطرق الرسمية لترتيب أضحيتك وتكلفة كل منها، وما يبقى مفتوحًا في إجازة الجامعة.</p>\n<h2>العشر من ذي الحجة ويوم عرفة وصباح العيد</h2>\n<ul>\n<li><strong>المواعيد:</strong> يُثبت كل تاريخ مساء اليوم السابق، حين يُعلن عن رؤية الهلال.</li>\n<li><strong>المدينة:</strong> كثير من الحجاج يزورون المدينة قبل الحج وكثير منهم بعده، فيمتلئ الحرم في تلك الأسابيع. ومن ٨ ذي الحجة يكون الحجاج في مكة، ويهدأ الحرم.</li>\n<li><strong>يوم عرفة:</strong> يصومه كثير من المقيمين.</li>\n<li><strong>الحافلات:</strong> في ١٤٤٧ توقفت خطوط حافلات المدينة المعتادة ظهر ٩ ذي الحجة، وعادت صباح ثاني أيام العيد. وعملت خطوط ترددية إلى المسجد النبوي وقباء من ظهر يوم عرفة حتى ساعة بعد العشاء، وعمل بعضها حتى الثامنة صباح يوم العيد. وراجع تطبيق حافلات المدينة لمواعيد ١٤٤٨.</li>\n<li><strong>صلاة العيد:</strong> تقام في الحرم، وفي المساجد والمصليات في أنحاء المدينة. وفي صباح العيد يكون الحجاج في منى، فيكون الحرم أقل زحامًا منه في عيد الفطر. والمواعيد والنصائح في <a href=\"/ar/ask/eid-prayer-in-madinah\">أين تُقام صلاة العيد في المدينة، ومتى تبدأ؟</a></li>\n</ul>\n<p>وفي عبادات هذه الأيام، وفيما يلزم من نوى أن يضحي، اسأل أهل العلم. ويجيب العلماء في المسجد النبوي وفي الجامعة عن الأسئلة.</p>\n<h2>طرق ترتيب أضحيتك</h2>\n<table><thead><tr><th>الطريقة</th><th>كيف تعمل</th><th>التكلفة في ١٤٤٧ (مايو ٢٠٢٦)</th></tr></thead><tbody>\n<tr><td>شراء خروف والذبح في مسلخ</td><td>تختار الذبيحة من سوق الأنعام، وتذبحها في مسلخ تشرف عليه الحكومة، وتأخذ اللحم إلى بيتك</td><td>ثمن الذبيحة، ورسم ذبح يبدأ من ٧٥ ريالًا</td></tr>\n<tr><td>صك أضاحي</td><td>مشروع المملكة للإفادة من الهدي والأضاحي «أضاحي» يذبح في مكة تحت إشراف بيطري، ويوزع اللحم على المحتاجين في المملكة وفي أكثر من ٢٥ دولة. ولا تستلم أنت لحمًا</td><td>يظهر في التطبيق أو الموقع عند الشراء</td></tr>\n<tr><td>جمعية خيرية مرخصة في المدينة</td><td>لعدد من الجمعيات في المدينة مشاريع أضاحٍ: تدفع أنت، وتذبح الجمعية وتوزع اللحم على الأسر الفقيرة في المدينة</td><td>تحدده كل جمعية</td></tr>\n<tr><td>جزار أو تاجر مواشٍ</td><td>يبيع عدد منهم في المدينة خروفًا مع الذبح والتقطيع والتوصيل إلى البيت، ويُطلب من تطبيقاتهم أو مواقعهم. واسألهم أي مسلخ يستخدمون</td><td>يحدده كل بائع</td></tr>\n</tbody></table>\n<p>تُباع صكوك أضاحي في تطبيق أضاحي وموقعه، وفي نسك، ومنصة إحسان على <a href=\"https://ehsan.sa/\">ehsan.sa</a>، وتطبيقات البنوك الكبرى، والبريد السعودي. وترسل إحسان رسالة نصية حين تتم الأضحية. ولا يُلغى الطلب ولا يُسترد بعد الدفع، فراجع التفاصيل قبل أن تدفع.</p>\n<h2>شراء خروف والذبح في مسلخ</h2>\n<ol>\n<li><strong>اختر الذبيحة</strong> من سوق الأنعام. ويفحص أطباء بيطريون من وزارة البيئة والمياه والزراعة الأسواق قبل العيد. اختر ذبيحة سليمة، واسأل أهل العلم عن السن والشروط التي تجب في الأضحية.</li>\n<li><strong>احجز موعدًا</strong> في منصة نما التابعة للوزارة على <a href=\"https://naama.sa/\">naama.sa</a>: اختر المسلخ واليوم والوقت والذبيحة. والحجز يختصر عليك الانتظار يوم العيد.</li>\n<li><strong>خذ الذبيحة إلى المسلخ.</strong> في العيد يشرف فرع الوزارة في المدينة على ١٧ مسلخًا في المنطقة، منها ستة مسالخ رئيسية داخل المدينة، وفيها أطباء بيطريون.</li>\n<li><strong>اختر التقطيع وادفع.</strong> كل مسلخ يعرض أسعاره على لوحة ويصدر فاتورة إلكترونية.</li>\n</ol>\n<table><thead><tr><th>خدمة المسلخ، المدينة، عيد ١٤٤٧</th><th>ريال، شاملة ضريبة القيمة المضافة</th></tr></thead><tbody>\n<tr><td>الذبح والسلخ والتنظيف، وتسليم الذبيحة كاملة</td><td>٧٥</td></tr>\n<tr><td>التقطيع أرباعًا</td><td>٨٥</td></tr>\n<tr><td>التقطيع الصغير للتجميد</td><td>١٠٠</td></tr>\n<tr><td>البقرة</td><td>٣٠٠</td></tr>\n</tbody></table>\n<p>متوسط سعر الذبيحة الواحدة في المملكة في مايو ٢٠٢٦، شهر عيد ١٤٤٧:</p>\n<table><thead><tr><th>الذبيحة</th><th>متوسط السعر (ريال)</th></tr></thead><tbody>\n<tr><td>خروف نجدي</td><td>١٬٩٦٦</td></tr>\n<tr><td>خروف نعيمي</td><td>١٬٩٤٥</td></tr>\n<tr><td>خروف حري</td><td>١٬٨١١</td></tr>\n<tr><td>خروف سواكني</td><td>١٬٣٩١</td></tr>\n<tr><td>ماعز محلي</td><td>١٬٢١٨</td></tr>\n<tr><td>خروف بربري</td><td>٧١٧</td></tr>\n</tbody></table>\n<h2>متى يكون الذبح وأين</h2>\n<ul>\n<li><strong>الأيام:</strong> في المملكة تُذبح الأضحية من بعد صلاة العيد في ١٠ ذي الحجة إلى نهاية أيام التشريق في ١٣ ذي الحجة. وفي ١٤٤٨ يوافق ذلك الأحد ١٦ إلى الأربعاء ١٩ مايو ٢٠٢٧. وللعلماء في اليوم الأخير خلاف، فاسأل أهل العلم.</li>\n<li><strong>الزحام:</strong> أول يومين من العيد أشد الأيام زحامًا في الأسواق والمسالخ. فاحجز في نما مبكرًا.</li>\n<li><strong>في مكان مرخص فقط:</strong> ذبح الذبيحة في مكان غير مرخص للذبح، كالشارع أو المواقف، مخالفة بلدية. والغرامة تُفرض عن كل ذبيحة، من ٤٠٠ إلى ٢٬٠٠٠ ريال بحسب المدينة، وتتضاعف عند التكرار.</li>\n</ul>\n<h2>إرسال الأضحية إلى الخارج</h2>\n<ul>\n<li><strong>عبر أسرتك أو جمعية خيرية في بلدك:</strong> أرسل المال قبل العيد بأسبوع أو أكثر، ويرتبونها هناك. انظر <a href=\"/ar/guides/sending-and-receiving-money\">إرسال المال إلى بلدك واستقباله في المدينة</a>.</li>\n<li><strong>عبر أضاحي:</strong> يذهب اللحم إلى المحتاجين في المملكة وخارجها، لكنك لا تختار الأسرة.</li>\n<li><strong>عبر مركز الملك سلمان للإغاثة:</strong> باعت منصة ساهم التابعة لمركز الملك سلمان للإغاثة والأعمال الإنسانية على <a href=\"https://sahem.ksrelief.org/\">sahem.ksrelief.org</a> في ١٤٤٧ أضاحي للأسر المحتاجة في ست دول: بوركينا فاسو ٤١٦ ريالًا، ومالي ٤٩٨، والنيجر ٤٦٥، والسودان ١٬١٧١، وسوريا ٩٤٦، واليمن ٤٨٣.</li>\n</ul>\n<p>وكون أضحيتك في المدينة أو حيث تسكن أسرتك مسألة يُسأل عنها أهل العلم.</p>\n<h2>توزيع اللحم</h2>\n<ul>\n<li>تقسم أسر كثيرة اللحم ثلاثة أقسام: لأهل البيت، وهدية للجيران والأصدقاء، وللمحتاجين. واسأل أهل العلم عن القدر الذي يجب التصدق به.</li>\n<li>أعطِ منه أسرًا محتاجة تعرفها، وحارس عمارتك وعمال النظافة، والطلاب البعيدين عن أهلهم. وللتعرف إلى طلاب وأسر آخرين يتحدثون الإنجليزية في العيد، انظر <a href=\"/ar/ask/join-mesh-group\">كيف أنضم إلى مجموعة MESH على واتساب؟</a></li>\n<li>الخروف كاملًا كثير على مجمد صغير. فاطلب التقطيع الصغير للتجميد، ووزع من اللحم طازجًا في اليوم الأول.</li>\n</ul>\n<h2>في إجازة العيد</h2>\n<ul>\n<li><strong>الجامعة:</strong> اختبارات الفصل الثاني النهائية من ٢٥ أبريل إلى ١٠ مايو ٢٠٢٧. وإجازة عيد الأضحى من الثلاثاء ١١ إلى السبت ٢٢ مايو ٢٠٢٧ (٥ إلى ١٦ ذي الحجة ١٤٤٨)، وتُستأنف الدراسة الأحد ٢٣ مايو. وكل المواعيد في <a href=\"/ar/guides/university-calendar-1448\">التقويم الجامعي</a>.</li>\n<li><strong>مكاتب الجامعة</strong> تغلق في إجازة العيد. فرتب تأشيرات الخروج والعودة والخطابات والتذاكر قبل ١١ مايو. انظر <a href=\"/ar/guides/iqama-and-exit-reentry-fees\">الإقامة والخروج والعودة والخروج النهائي ورسوم المرافقين</a>.</li>\n<li><strong>العمل والخدمات:</strong> تمنح الشركات الخاصة إجازة لا تقل عن أربعة أيام تبدأ من يوم عرفة، وتغلق الجهات الحكومية في إجازة العيد. وفي الطوارئ اتصل على 997 للإسعاف.</li>\n<li><strong>مكة:</strong> تتوقف تصاريح العمرة من ١ ذي القعدة حتى ما بعد الحج، ودخول مكة في هذه الأسابيع يحتاج تصريحًا. انظر <a href=\"/ar/guides/hajj-as-a-student\">الحج من المدينة طالبًا أو مقيمًا</a>.</li>\n</ul>"
 },
 "electricity-water-and-gas-at-home": {
  "titleAr": "الكهرباء والماء والغاز في البيت",
  "summaryAr": "نقل حسابي الكهرباء والماء إلى اسمك، ودفع الفواتير، وتكلفة كل وحدة الآن ومن يناير ٢٠٢٧، وانقطاع الكهرباء والماء، وصيانة المكيفات قبل الصيف، وأسعار غاز الطبخ والسلامة منه، وإغلاق ذلك كله حين تغادر الشقة.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. في المدينة تأتي الكهرباء من شركة السعودية للطاقة (Saudi Energy)، وكان اسمها حتى ٢٠٢٦ الشركة السعودية للكهرباء، ويأتي الماء من شركة المياه الوطنية. أما غاز الطبخ فيأتي في أسطوانات تستبدلها حين تفرغ. يشرح هذا الدليل الحسابات والفواتير وتكلفتها، والانقطاعات والطوارئ، وما تفعله حين تغادر.</p>\n<h2>الحسابات باسمك</h2>\n<p>قبل أن تنتقل إلى الشقة اطلب من المالك رقمي حسابي الكهرباء والماء، وهما مطبوعان على كل فاتورة. أدخل رقم حساب الكهرباء في صفحة «عرض الفاتورة وسدادها» على <a href=\"https://www.se.com.sa/\">se.com.sa</a>، بلا تسجيل دخول، لتعرف هل عليه مبالغ غير مدفوعة. واسأل هل عداد الماء خاص بشقتك أم مشترك للمبنى كله، وكيف تُقسم الفاتورة المشتركة. وقائمة الفحص الكاملة عند معاينة الشقة في <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a>.</p>\n<p>ساكن الشقة هو المسؤول عن عدادها. ومع عقد مسجل في إيجار تنقل خدمة نقل المسؤولية المالية المجانية حسابي الكهرباء والماء إلى اسمك:</p>\n<ol>\n<li>يختار الوسيط النقل حين يسجل العقد، أو تطلبه أنت في إيجار لعقد قائم.</li>\n<li>قدّم رقم حساب العداد من الفاتورة، والقراءة الحالية إن كان العداد قديمًا.</li>\n<li>يوافق الطرفان على الطلب في إيجار، ثم يُحال إلى السعودية للطاقة وشركة المياه الوطنية لإتمامه.</li>\n</ol>\n<p>الفواتير السابقة للنقل ليست عليك، إلا إن كان مالك العداد غير مسجل لدى السعودية للطاقة. وإن كنت بتأشيرة طالب فانظر <a href=\"/ar/ask/rent-on-student-visa\">هل يمكنني تسجيل عقد إيجار وأنا بتأشيرة طالب؟</a> وبلا عقد في إيجار تبقى الحسابات باسم المالك، فاتفق مع المالك كتابةً على من يدفع كل فاتورة واحتفظ بكل إيصال. ويستطيع أي أحد دفع الفاتورة برقم حسابها.</p>\n<blockquote><p>نصيحة: صوّر العدادين يوم انتقالك، والقراءة واضحة فيهما.</p></blockquote>\n<h2>دفع فاتورة الكهرباء وتكلفتها</h2>\n<ul>\n<li><strong>التطبيق:</strong> تطبيق السعودية للطاقة على الآيفون والأندرويد، وكان اسمه «الكهرباء» قبل تغيير الاسم في ٢٠٢٦. لإضافة عدادك افتح «إدارة الحسابات»، واختر «إضافة حساب»، وأدخل بيانات الحساب، واختر نوع المستفيد، ثم وافق على اتفاقية الاستهلاك.</li>\n<li><strong>الدفع:</strong> في التطبيق، أو في صفحة «عرض الفاتورة وسدادها»، أو في أي تطبيق بنكي تحت مدفوعات سداد، باختيار شركة الكهرباء جهةً مفوترة وإدخال رقم الحساب. ادفع كل فاتورة حين تصلك، فالفاتورة غير المدفوعة تنتهي بقطع الكهرباء.</li>\n</ul>\n<table><thead><tr><th>التعرفة السكنية</th><th>حتى ٣١ ديسمبر ٢٠٢٦</th><th>من ١ يناير ٢٠٢٧</th></tr></thead><tbody>\n<tr><td>أول ٦٠٠٠ كيلوواط ساعة في الشهر</td><td>١٨ هللة لكل كيلوواط ساعة</td><td>٢١ هللة لكل كيلوواط ساعة</td></tr>\n<tr><td>ما فوق ٦٠٠٠ كيلوواط ساعة في الشهر</td><td>٣٠ هللة لكل كيلوواط ساعة</td><td>٣٣ هللة لكل كيلوواط ساعة</td></tr>\n<tr><td>الرسوم الشهرية الثابتة</td><td>رسوم قراءة العداد وصيانته وإصدار الفاتورة، تتحدد بسعة القاطع</td><td>٧٠ ريالًا للقاطع الأقل من ١٠٠ أمبير، وأكثر للقواطع الأكبر</td></tr>\n</tbody></table>\n<p>تُضاف ضريبة القيمة المضافة بنسبة ١٥٪. وبتعرفة ٢٠٢٧ يكلف استهلاك ١٠٠٠ كيلوواط ساعة في ٣٠ يومًا على قاطع أقل من ١٠٠ أمبير ٢٨٠ ريالًا قبل الضريبة: ٢١٠ ريالات للكهرباء و٧٠ ريالًا رسومًا ثابتة. والكهرباء المستهلكة قبل ١ يناير ٢٠٢٧ تُحسب بالأسعار القديمة. والفواتير المعتادة في الشتاء والصيف في <a href=\"/ar/guides/cost-of-living\">كم تكلف المعيشة في المدينة</a>.</p>\n<h2>المكيفات قبل الصيف</h2>\n<p>التكييف هو معظم فاتورة الصيف، والمكيف الذي لم يُصن يستهلك كهرباء أكثر ويبرد أقل.</p>\n<ul>\n<li><strong>أجرِ صيانة لكل مكيف في مارس أو أبريل،</strong> قبل الحر. تشمل الصيانة تنظيف الفلاتر والملف الداخلي، وفتح أنبوب التصريف، وفحص غاز التبريد، وتنظيف الوحدة الخارجية.</li>\n<li><strong>اغسل الفلاتر</strong> كل أسبوعين إلى أربعة أسابيع في الصيف.</li>\n<li><strong>اضبط منظم الحرارة على ٢٤ درجة مئوية.</strong> وأغلق الستائر في الجهة المشمسة، وأطفئ المكيفات في الغرف الخالية، وأبعد الصناديق عن الوحدة الخارجية.</li>\n<li>تساقط الماء داخل الغرفة يدل على انسداد التصريف، وضعف التبريد يدل على فلتر متسخ أو نقص في الغاز.</li>\n</ul>\n<p>من يدفع ثمن الإصلاح يحدده عقدك: انظر قسم الإصلاحات في <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a>. ويُحجز الفنيون عبر تطبيقات خدمات المنازل في <a href=\"/ar/guides/everyday-apps-and-services\">التطبيقات والخدمات اليومية</a> أو عبر أي محل مكيفات.</p>\n<h2>انقطاع الكهرباء</h2>\n<ul>\n<li><strong>شرر أو رائحة احتراق أو سلك ساقط:</strong> ابتعد واتصل بالرقم <strong>911</strong>.</li>\n<li><strong>الانقطاع في شقتك وحدها:</strong> افحص لوحة القواطع داخل الشقة وارفع أي قاطع نزل.</li>\n<li><strong>الانقطاع يشمل المبنى أو الشارع:</strong> أبلغ السعودية للطاقة على الرقم <strong>933</strong> على مدار الساعة، مع رقم حسابك ورقم العداد وموقعك، أو أبلغ في التطبيق.</li>\n</ul>\n<p>إن استمر انقطاع غير مجدول أكثر من ٣ ساعات فلصاحب الحساب تعويض قدره ٥٠ ريالًا، و٥٠ ريالًا عن كل ساعة إضافية أو جزء منها. ويُضاف إلى الفاتورة خلال ١٠ أيام عمل، بلا حاجة إلى مطالبة.</p>\n<h2>الماء</h2>\n<p>تطبيق شركة المياه الوطنية «المياه الوطنية» وفرعها الإلكتروني على <a href=\"https://ebranch.nwc.com.sa/\">ebranch.nwc.com.sa</a> للفواتير والدفع والطلبات. وتستطيع الدفع أيضًا في أي تطبيق بنكي تحت سداد برقم حساب الماء. ومركز اتصال الشركة <strong>8004411110</strong>.</p>\n<table><thead><tr><th>الاستهلاك السكني من ١ يناير ٢٠٢٧، لكل متر مكعب</th><th>الماء</th><th>الصرف الصحي</th></tr></thead><tbody>\n<tr><td>حتى ١٥ م³ في الشهر</td><td>١ ريال</td><td>٠٫٥٠ ريال</td></tr>\n<tr><td>من ١٥ إلى ٣٠ م³</td><td>٢ ريال</td><td>١ ريال</td></tr>\n<tr><td>من ٣٠ إلى ٤٥ م³</td><td>٤ ريالات</td><td>٢ ريال</td></tr>\n<tr><td>ما فوق ٤٥ م³</td><td>٦ ريالات</td><td>٣ ريالات</td></tr>\n</tbody></table>\n<p>ومن التاريخ نفسه تُفرض رسوم شهرية ثابتة قدرها ٢٠ ريالًا للماء و١٠ ريالات للصرف الصحي على العداد حتى ٢٠ ملم، وأكثر للعدادات الأكبر، مع ٢٠ ريالًا و١٠ ريالات أخرى عن كل مسكن إضافي على العداد نفسه. وحتى ٣١ ديسمبر ٢٠٢٦ تسري التعرفة القديمة الأقل.</p>\n<ul>\n<li><strong>انقطاع الماء:</strong> أبلغ في التطبيق أو على الرقم 8004411110.</li>\n<li><strong>الماء بالصهريج:</strong> اطلب صهريجًا في التطبيق أو الفرع الإلكتروني واختر حجمه.</li>\n<li><strong>البيارة:</strong> إن لم يكن المبنى متصلًا بشبكة الصرف الصحي فاحجز شفطها عبر خدمة «بيئتي» من شركة المياه الوطنية في التطبيق نفسه.</li>\n</ul>\n<h2>غاز الطبخ</h2>\n<p>استبدل الأسطوانة الفارغة بممتلئة من محل غاز، أو اطلب توصيلها إلى بابك. وفي بعض المباني خزان مركزي يُعبأ باللتر. وأسعار التعبئة موحدة في المملكة كلها، وتشمل ضريبة القيمة المضافة والنقل (من ١ يوليو ٢٠٢٦):</p>\n<table><thead><tr><th>التعبئة</th><th>السعر</th></tr></thead><tbody>\n<tr><td>أسطوانة ١١ كجم، الحجم المعتاد للبيوت</td><td>٣٧ ريالًا</td></tr>\n<tr><td>أسطوانة ٥ كجم</td><td>١٦٫٨٢ ريال</td></tr>\n<tr><td>خزان الغاز المركزي</td><td>١٫٦٩ ريال لكل لتر</td></tr>\n</tbody></table>\n<ul>\n<li>اجعل الأسطوانة قائمة في مكان جيد التهوية، بعيدة عن حرارة الموقد وعن الشمس.</li>\n<li>افحص الخرطوم والمنظم والوصلات باستمرار، واستبدل الخرطوم المتشقق أو المتصلب.</li>\n<li>أغلق صمام الأسطوانة حين تغادر المطبخ وقبل أن تنام، وركّب جهاز كشف تسرب الغاز لتنبيهك مبكرًا.</li>\n</ul>\n<blockquote><p>مهم: إن شممت رائحة غاز فلا تلمس مفتاح إضاءة ولا ولاعة ولا أي شيء يُحدث شررًا. أخرج الجميع، وأغلق صمام الأسطوانة، وافتح الأبواب والنوافذ بهدوء، واتصل بالدفاع المدني على الرقم 998 أو على 911. وأرقام الطوارئ كلها في <a href=\"/ar/ask/emergency-numbers\">ما أرقام الطوارئ في السعودية؟</a></p></blockquote>\n<h2>عند المغادرة، وإنترنت البيت</h2>\n<ul>\n<li><strong>مع عقد في إيجار</strong> ينتهي النقل تلقائيًا بانتهاء العقد. يطلب منك إيجار قراءة أخيرة للعداد، ثم تعود العدادات إلى المالك ولا تصلك فواتير بعدها. وبلا قراءة تُقدَّر الفاتورة تقديرًا، فصوّر العدادين في يومك الأخير.</li>\n<li><strong>بلا عقد في إيجار</strong> تكون الحسابات أصلًا باسم المالك. وإن أضفت نفسك إلى العداد في تطبيق السعودية للطاقة فاحذف نفسك من «إدارة الحسابات»، فتصدر فاتورة أخيرة.</li>\n<li>ادفع آخر فاتورتي كهرباء وماء قبل أن تسلّم المفاتيح. والإشعار بالإخلاء والتسليم والعربون في <a href=\"/ar/guides/graduate-procedures\">مغادرة المدينة نهائيًا</a>.</li>\n<li><strong>إنترنت البيت:</strong> انظر <a href=\"/ar/ask/home-internet-no-iqama\">كيف أحصل على إنترنت منزلي دون إقامة؟</a> و<a href=\"/ar/guides/sim-internet-bank\">شريحة الجوال والإنترنت وبطاقة بنكية سعودية</a>.</li>\n</ul>"
 },
 "etimad-account": {
  "titleAr": "تذكرتك من الجامعة: اعتماد وأمر الإركاب والقواعد",
  "summaryAr": "من يحصل على تذاكر الوصول والسنوية والأخيرة وكيف تُطلب كل منها، وإعداد حسابك في اعتماد لتطابق بياناتك جوازك، وكيف تصل التذاكر الجماعية، وقواعد تذاكر ٢٠٢٦، وتغيير التاريخ إذا تعارض مع اختبار، وما تفعله حين تتعطل تذكرة.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. يتسلم طلاب المنحة الكاملة تذكرة ذهاب وعودة إلى بلدهم على الدرجة السياحية المخفضة في نهاية كل عام دراسي، وتذكرة وصول حين يأتون أول مرة، وتذكرة أخيرة حين يتخرجون. وكلها تذاكر حكومية: تصدر الجامعة أمر إركاب على اعتماد، المنصة الحكومية، وتحجز وكالة سفر الرحلة بموجبه. فلا تذكرة بلا أمر إركاب. ويتناول هذا الدليل الحساب، والتذكرة السنوية من الطلب إلى الصعود إلى الطائرة، والقواعد.</p>\n<h2>من يحصل على تذكرة، ومتى</h2>\n<table><thead><tr><th>التذكرة</th><th>لمن</th><th>كيف تُطلب</th></tr></thead><tbody>\n<tr><td>تذكرة الوصول</td><td>طلاب المنحة الكاملة الجدد</td><td>على منحتي، برفع جوازك وتأشيرتك وكتابة اسمك كما في الجواز تمامًا. تعد إدارة السفر الأمر وتصدر الوكالة التذكرة</td></tr>\n<tr><td>التذكرة السنوية إلى بلدك</td><td>طلاب المنحة الكاملة، في نهاية العام الدراسي، ما لم تكن جهة أخرى توفر لهم تذكرة</td><td>عبر إدارة السفر، التي تجمع قوائم السفر قبل الإجازة الصيفية بأشهر، عن طريق ممثل جنسيتك وعبر اعتماد. ويسافر طلاب البكالوريوس والمعهد بحجوزات جماعية في مواعيد تحددها الجامعة</td></tr>\n<tr><td>التذكرة الأخيرة</td><td>الخريجون، والطلاب الذين انتهت دراستهم</td><td>لا تصدر إلا بعد أن تؤكد إدارة السفر إخلاء طرفك في سجلات الجامعة</td></tr>\n<tr><td>الدراسات العليا</td><td>الطلاب المقبولون في الماجستير أو الدكتوراه</td><td>عبر إدارة السفر عند القبول. ولطلاب الماجستير والدكتوراه تذاكر فردية لا حجوزات جماعية</td></tr>\n</tbody></table>\n<p>المنحة الجزئية (الداخلية) لا تشمل تذاكر. وتذاكر الأسرة على حسابك. ولا تصدر إدارة السفر تذاكر أثناء العام الدراسي: فالسفر في أثناء الفصل، بإذن كليتك، على حسابك. والتذاكر الطلابية غير المستعملة تلغيها إدارة السفر وتعود قيمتها إلى الجامعة، فالتذكرة التي لا تستطيع استعمالها الأفضل أن تُلغى مبكرًا.</p>\n<h2>إعداد حسابك في اعتماد</h2>\n<ol>\n<li>افتح <a href=\"https://portal.etimad.sa/\">portal.etimad.sa</a> واختر تسجيل الدخول.</li>\n<li>اختر <strong>أفراد</strong>، ثم ادخل عبر <strong>نفاذ</strong>.</li>\n<li>أدخل رقم جوالك وبريدك، ووافق على الشروط واحفظ.</li>\n<li>أدخل الرمز الذي يصل إلى جوالك، ثم أكّد الرابط المرسل إلى بريدك.</li>\n<li>عد إلى الموقع وافتح <strong>أوامر الإركاب</strong>، ثم <strong>ملفك الشخصي</strong>.</li>\n<li>اضغط <strong>تعديل الملف</strong> وتحقق أن كل بيان يطابق جوازك تمامًا، ثم احفظ. وظهور رسالة التأكيد يعني أنك انتهيت.</li>\n</ol>\n<blockquote><p>ملاحظة: اختلاف كتابة الاسم بين اعتماد وجوازك أكثر أسباب تعطل التذاكر شيوعًا. فصححه قبل أن تطلب تذكرتك.</p></blockquote>\n<p>سجّل الدخول أول مرة وأنت في السعودية، عبر نفاذ. وبعد ذلك يعمل الحساب من الخارج أيضًا. وأبقِ رقم الجوال المسجل في الحساب فعّالًا، لأن الرموز تصل إليه، واستعمل بريدًا تقرؤه، فتذكرتك الإلكترونية تُرسل إلى البريد المسجل في ملفك على اعتماد.</p>\n<h2>تأكد أن رقم هويتك مسجل في سجلك الجامعي</h2>\n<p>إن لم يكن رقم هوية الزائر أو رقم الإقامة مسجلًا في النظام الأكاديمي فلا تستطيع إدارة السفر إصدار تذاكرك ولا تأشيراتك. وتتحقق منه بإحدى طريقتين:</p>\n<ul>\n<li>في موقع الجامعة افتح «السفر والتأشيرات»، وادخل بحسابك الجامعي، وافتح «المعلومات الأساسية للطلاب» وانظر في خانة «رقم الهوية».</li>\n<li>أو افتح «الخدمات الأكاديمية» ثم «المعلومات الأكاديمية»، وانظر في خانة «رقم الهوية».</li>\n</ul>\n<p>فإن كانت الخانة فارغة أو الرقم خاطئًا فاذهب إلى إدارة السفر بجوازك وهويتك قبل إغلاق قوائم السفر الصيفية.</p>\n<h2>من الطلب إلى بطاقة الصعود</h2>\n<ol>\n<li><strong>راجع ملفك في اعتماد</strong> في أوائل الفصل الدراسي الثاني: الاسم، ورقم الجواز، وتاريخ انتهائه، والجوال، والبريد.</li>\n<li><strong>سجّل حين تطلب الجامعة ذلك.</strong> تجمع إدارة السفر القوائم الصيفية قبلها بأشهر، عن طريق ممثل جنسيتك أو عبر استمارة، وعبر اعتماد. اختر مدينتك من المدن المحددة لبلدك، أو بيّن أنك لا تريد تذكرة. ولا يتسلم التذكرة إلا من كان في القائمة، فإن وجدت اسمك غير مدرج فيها فأخبر ممثلك فورًا. والطلاب المتخرجون ليسوا في هذه القائمة، لأن تذكرتهم الأخيرة مستقلة.</li>\n<li><strong>راقب اعتماد.</strong> يظهر أمر إركابك تحت أوامر الإركاب بعد اعتماده. وفي الحجز الجماعي يكون الأمر باسم قائد المجموعة، فعدم ظهور أمرك أنت هناك أمر طبيعي.</li>\n<li><strong>اعثر على تذكرتك.</strong> تصدر التذاكر على دفعات من منتصف أبريل إلى منتصف مايو. وتصل التذكرة الجماعية ملف PDF واحدًا من الخطوط السعودية، يُرسل بالبريد إلى طالب واحد في المجموعة، وفيه تذاكر الجميع. فابحث في بريدك كله، ومنه مجلدا الرسائل غير المرغوبة والمهملة، عن «Saudia» و«flight confirmation» في رسائل الشهر الماضي. وإن وصلتك تذكرة ليست لك فسلّمها لممثلك. وراجع الاسم والتواريخ والمطارات يوم استلامها.</li>\n<li><strong>استخرج تذكرتك الإلكترونية الخاصة من الحجز الجماعي</strong> إن أردت: في تطبيق الخطوط السعودية افتح «المساعد»، ثم «تغيير الرحلة أو إلغاؤها»، وأدخل رقم الحجز واسم عائلتك وتابع كأنك ستغير (لن يتغير شيء)، ثم اختر «تنزيل التذاكر الإلكترونية» في موقع الخطوط السعودية.</li>\n<li><strong>لا تحجز رحلة العودة بنفسك.</strong> التذكرة ذهاب وعودة، والجامعة تحجز موعد العودة لبداية العام الجديد.</li>\n<li><strong>استخرج تأشيرة الخروج والعودة</strong> إن كنت تحمل إقامة، بتواريخ تغطي الرحلة كلها. انظر <a href=\"/ar/guides/iqama-and-exit-reentry-fees\">الإقامة والخروج والعودة والخروج النهائي ورسوم المرافقين</a>.</li>\n<li><strong>أنهِ إجراءات السفر عبر الإنترنت</strong> واحضر مبكرًا. فالتخلف عن الرحلة يُفقدك التذكرة كلها.</li>\n</ol>\n<h2>قواعد تذاكر الطلاب</h2>\n<p>لا تصدر الجامعة التذكرة إلا بموجب أمر إركاب رسمي على اعتماد، فلا تُصدر تذاكر مفتوحة. وقواعد التذاكر الصادرة من ٢٠٢٦:</p>\n<ol>\n<li><strong>إلى أين:</strong> إلى إحدى المدن التي تحددها الجامعة لكل بلد، في بلدك أو في البلد الذي أصدر التأشيرة التي وصلت بها. ففي صيف ٢٠٢٦ مثلًا اختار الطلاب المسافرون إلى الولايات المتحدة نيويورك (JFK) أو واشنطن العاصمة (IAD). وأي رحلة مواصلة بعد تلك المدينة حجز مستقل على حسابك.</li>\n<li><strong>الصلاحية:</strong> ٣ أشهر من تاريخ السفر الأول. وبعدها لا يمكن أي تغيير.</li>\n<li><strong>الاسم:</strong> لا يُغيَّر اسم المسافر، ولهذا يجب أن يطابق جوازك من البداية.</li>\n<li><strong>المطارات:</strong> لا تُغيَّر الوجهة ولا مطارا المغادرة والوصول في رحلة الذهاب.</li>\n<li><strong>التاريخ والوقت:</strong> يمكن تغييرهما، لكنك تدفع فرق الأجرة وأي رسوم.</li>\n<li><strong>الدرجة:</strong> لا تخفيض للدرجة. وتستطيع الترقية على حسابك.</li>\n<li><strong>الإلغاء:</strong> تعود التذكرة إلى الجامعة، ولا استرداد نقديًا لك.</li>\n<li><strong>التخلف عن الرحلة:</strong> يُفقدك التذكرة كلها.</li>\n<li><strong>قسائم الاسترداد:</strong> بعد أي تغيير لا تُعطى قسيمة للطالب ولا يُضاف شيء إلى محفظة.</li>\n<li><strong>الأمتعة:</strong> حقيبة يد واحدة وحقيبتان مشحونتان، ضمن حدود شركة الطيران.</li>\n</ol>\n<blockquote><p>نصيحة: اختر تاريخك بعناية قبل صدور أمر الإركاب. فتغييره لاحقًا يكلفك مالًا، والتخلف عن الرحلة يكلفك التذكرة.</p></blockquote>\n<h2>مشكلات شائعة</h2>\n<table><thead><tr><th>المشكلة</th><th>ما تفعله</th></tr></thead><tbody>\n<tr><td>نفاذ لا يُدخلك</td><td>فعّل نفاذ أولًا: انظر <a href=\"/ar/ask/absher-nafath-activation\">تفعيل أبشر أو نفاذ يفشل عندي باستمرار</a></td></tr>\n<tr><td>اسمك في التذكرة يختلف عن الجواز</td><td>أخبر إدارة السفر عبر تواصل في اليوم نفسه. فالاسم لا يُغيَّر في التذكرة، ولا بد من تصحيح الأمر قبل الإصدار</td></tr>\n<tr><td>لا أمر إركاب بعد إغلاق القائمة</td><td>أرسل طلبًا عبر تواصل إلى إدارة السفر برقمك الجامعي وتواريخك</td></tr>\n<tr><td>تريد مدينة أخرى</td><td>لا تختار إلا من المدن المحددة لبلدك. والرحلة المواصلة إلى مدينة أخرى على حسابك، فاحجزها حالما تصلك تذكرتك</td></tr>\n<tr><td>لم يصلك بريد التذكرة حتى منتصف مايو</td><td>ابحث في كل المجلدات عن «Saudia»، واسأل طلاب مجموعتك عمن استلم ملف المجموعة، ثم اسأل ممثلك</td></tr>\n<tr><td>جددت جوازك</td><td>حدّث اعتماد وأخبر إدارة السفر قبل صدور الأمر</td></tr>\n<tr><td>موعد تذكرتك يتعارض مع اختبار</td><td>أرسل طلبًا عبر تواصل إلى إدارة السفر تطلب فيه تغيير التاريخ، مع صورة من التذكرة ومن جدول اختباراتك. ثم يُغيَّر التاريخ في مكتب الخطوط السعودية في الحرم الجامعي، على حسابك</td></tr>\n<tr><td>تحتاج إلى موعد آخر في تذكرة جماعية، للحج مثلًا</td><td>لا يتغير إلا التاريخ، أما المسار فلا يتغير أبدًا. اذهب إلى مكتب الخطوط السعودية في الحرم الجامعي وادفع الفرق</td></tr>\n<tr><td>لن تستعمل التذكرة</td><td>ألغها حضوريًا في إدارة السفر حالما تتأكد. ولا تطبيق لذلك. وإن لم تفعل شيئًا فإنك تخسر التذكرة فحسب</td></tr>\n</tbody></table>\n<blockquote><p>ملاحظة: في موسم التذاكر يُفتح مكتب للخطوط السعودية في الحرم الجامعي للطلاب الذين يغيرون مواعيد سفرهم. وفي ٢٠٢٦ فُتح في ١٣ مايو، من ٧:٣٠ صباحًا إلى ٣:٠٠ عصرًا في أيام العمل. فراجع هذا المكتب لا فروع الخطوط السعودية في المدينة.</p></blockquote>\n<p>الخريجون: التذكرة الأخيرة تأتي بعد إنهاء كل شيء آخر، وترتيب الخطوات في <a href=\"/ar/guides/graduate-procedures\">مغادرة المدينة نهائيًا</a>. وما تغطيه التذكرة السنوية إلى جانب مكافأتك في <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة: المكافأة والبدلات والتذاكر</a>.</p>\n<blockquote><p>نصيحة: تذكرتك متعطلة ولا رد عبر تواصل؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "everyday-apps-and-services": {
  "titleAr": "التطبيقات والخدمات اليومية: التطبيقات الحكومية والتنقل والدفع والطعام والصيانة والأسعار",
  "summaryAr": "التطبيقات الحكومية التي يستعملها كل مقيم وفيمَ يُستعمل كل منها، وتطبيقات التوصيل، والدفع بالبطاقة والجوال، والتطبيقات والخدمات للطعام والتسوق والصيانة والتنظيف والمغاسل والصالات الرياضية، مع الأسعار المعتادة.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. الحياة اليومية في المدينة تجري على الجوال: الأوراق الحكومية، وتصريح الروضة، والحافلة، والعشاء، والسباك، كلها في تطبيق. ويذكر هذا الدليل التطبيقات التي يستعملها السكان، وفيمَ يُستعمل كل منها، والأسعار المعتادة، مع روابط إلى الأدلة التي تشرح كل خطوة. والتطبيقات من النوع الواحد مرتبة أبجديًا بأسمائها اللاتينية.</p>\n<h2>التطبيقات الحكومية</h2>\n<table><thead><tr><th>التطبيق</th><th>فيمَ يُستعمل</th><th>الخطوات كاملة</th></tr></thead><tbody>\n<tr><td><strong>أبشر</strong></td><td>سجل إقامتك: الإقامة والتأشيرات وأفراد الأسرة والمخالفات المرورية</td><td><a href=\"/ar/guides/phone-sims-and-absher\">رقم جوالك والتحقق من الشرائح وأبشر</a></td></tr>\n<tr><td><strong>نفاذ</strong></td><td>يوثّق دخولك إلى الخدمات الحكومية والبنكية برقم يظهر على الشاشة</td><td><a href=\"/ar/guides/new-student-steps\">الخطوات الأولى للطلاب الجدد</a></td></tr>\n<tr><td><strong>توكلنا</strong></td><td>نسخ رقمية من مستنداتك، ومنها البطاقة الجامعية</td><td><a href=\"/ar/guides/new-student-steps\">الخطوات الأولى للطلاب الجدد</a></td></tr>\n<tr><td><strong>نسك</strong></td><td>تصاريح الروضة والعمرة</td><td><a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء من المدينة</a></td></tr>\n<tr><td><strong>إيجار</strong></td><td>عقود الإيجار الموثقة</td><td><a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a></td></tr>\n<tr><td><strong>البريد السعودي (سبل)</strong></td><td>عنوانك الوطني وعنوانك المختصر، والطرود</td><td><a href=\"/ar/guides/shipping-and-receiving-parcels\">إرسال الطرود واستقبالها في المدينة</a></td></tr>\n<tr><td><strong>حافلات المدينة</strong></td><td>المسارات والمواعيد المباشرة والأسعار، مع باقات الرحلات</td><td><a href=\"/ar/guides/haramain-train-and-city-buses\">قطار الحرمين وحافلات المدينة</a></td></tr>\n</tbody></table>\n<p>طلاب التأشيرة التعليمية: ما يعمل بهوية الزائر في <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a>.</p>\n<h2>التنقل</h2>\n<p>بولت وكريم وجيني وأوبر كلها تعمل في المدينة، وأسعارها ترتفع بعد التراويح في رمضان. والحافلة وقطار الحرمين وسيارات الأجرة والأسعار في <a href=\"/ar/guides/getting-around\">التنقل في المدينة، وإلى مكة</a>.</p>\n<h2>الدفع</h2>\n<ul>\n<li>البطاقات والجوالات مقبولة في كل مكان تقريبًا، من المخبز إلى المغسلة، والحافلات لا تقبل النقد أصلًا. وبطاقة مدى في Apple Pay أو في محفظة بنكية تكفي لأكثر الأيام.</li>\n<li>احتفظ بقليل من النقد للبسطات الصغيرة.</li>\n<li>إرسال المال إلى بلدك، والمحافظ ورسومها، في <a href=\"/ar/guides/sending-and-receiving-money\">إرسال المال إلى بلدك واستقباله في المدينة</a>.</li>\n</ul>\n<h2>الطعام</h2>\n<ul>\n<li><strong>هنقرستيشن</strong> و<strong>جاهز</strong> و<strong>كيتا</strong> و<strong>مرسول</strong> للتوصيل، وعادةً خلال ٢٠ إلى ٣٠ دقيقة. والأسواق المركزية توصل عبر التطبيقات نفسها.</li>\n<li><strong>بركة</strong> للطعام غير المباع من المطاعم والمخابز والمحلات بخصم ٥٠ إلى ٧٠٪، يُستلم في وقت محدد. وللمحل أن يلغي الطلب حتى ساعة قبل موعد الاستلام.</li>\n</ul>\n<h2>التسوق</h2>\n<ul>\n<li><strong>Amazon.sa</strong> و<strong>نون</strong> يوصلان خلال يوم إلى ثلاثة أيام، ونون منتس خلال ساعة أو ساعتين.</li>\n<li><strong>إكسترا وهوم بوكس وكارفور</strong> للأجهزة مع ضمان. و<strong>سوق حراج</strong> لأرخص الأثاث الجديد والمستعمل مع توصيل في اليوم نفسه.</li>\n<li>الثياب تُفصَّل في كل حي بـ ١٠٠ إلى ٣٠٠ ريال، وتجهز عادةً خلال يومين إلى أربعة أيام.</li>\n</ul>\n<h2>الصيانة والتنظيف</h2>\n<ul>\n<li><strong>داري</strong>: تنظيف وكهربائيون وسباكون وفنيو تكييف وتركيب الأثاث، يُحجز ويُدفع في التطبيق.</li>\n<li><strong>مهارة</strong>: عاملات نظافة ومربيات وطهاة، بالساعة أو بالإقامة في البيت. والعاملة المقيمة تكلف نحو ٢٠٠٠ إلى ٣٥٠٠ ريال في الشهر.</li>\n<li><strong>راحة</strong>: عاملات منزليات بالساعة (زيارة أربع ساعات عادةً) أو بعقود شهرية.</li>\n</ul>\n<h2>المغاسل والحلاقون والصيدليات</h2>\n<ul>\n<li>المغاسل في كل شارع تقريبًا، وتفتح ١٥ إلى ١٦ ساعة في اليوم: نحو ريالين لغسل الثوب أو كيّه، و٥ ريالات للعباءة.</li>\n<li>حلاقة الرجال ١٠ إلى ٥٠ ريالًا. والنساء ٤٠ إلى ٨٠ ريالًا.</li>\n<li>صيدليات الدواء والنهدي لها فروع في أنحاء المدينة كلها، وبعضها يفتح على مدار الساعة، وأكثر موظفيها يتكلمون الإنجليزية.</li>\n</ul>\n<h2>الصالات الرياضية</h2>\n<p>الصالات الرياضية كلها للرجال فقط أو للنساء فقط. صالات الرجال من ١٥٠ إلى ٤٠٠ ريال في الشهر، وصالات النساء من ٢٥٠ إلى ٥٠٠. ونوادي الفنون القتالية من ١٥٠ إلى ٣٠٠ ريال. وفي النادي الرياضي للجامعة الإسلامية داخل الحرم الجامعي يدفع الطالب ١٢٥ ريالًا للشهر، مقابل ٢٥٠ ريالًا لغير الطلاب، والاشتراكات الأطول أقل في الشهر. والأسعار والمرافق والحصص والرحلات في <a href=\"/ar/guides/sports-and-activities\">الرياضة وحصص اللياقة</a>.</p>\n<blockquote><p>نصيحة: تطبيق يرفض هويتك، أو تحتاج إلى خدمة غير مذكورة هنا؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "exams-results-and-attendance": {
  "titleAr": "الاختبارات والنتائج والحضور في الجامعة الإسلامية",
  "summaryAr": "حد الغياب مع أمثلة محسوبة، والإنذارات، وتقديم عذر الغياب إلكترونيًا، وجدول الاختبارات وقواعد يوم الاختبار، وكيف تُحسب الدرجات، والاطلاع على نتائجك، والتخلف عن اختبار نهائي، والتظلم من درجة، والاعتذار عن مقرر، وما يعنيه الرسوب في مقرر.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. هذه قواعد الجامعة لطلاب المرحلة الجامعية. ويطبق المعهد حد الغياب نفسه، فاقرأ قسم الحضور أيًّا كانت دراستك، واسأل مكتب المعهد عن اختباراته الخاصة. ومكان كل شاشة في النظام الأكاديمي مبيّن في <a href=\"/ar/guides/university-student-system\">استعمال نظام الطالب في الجامعة</a>.</p>\n<h2>الحضور</h2>\n<ul>\n<li>يجب أن تحضر <strong>٧٥٪</strong> على الأقل من محاضرات كل مقرر ودروسه العملية.</li>\n<li>إذا <strong>تجاوز غيابك ٢٥٪</strong> من المقرر حُرمت من اختباره النهائي. أما ٢٥٪ تمامًا فلا تحرمك. ويُسجَّل المقرر راسبًا بتقدير <strong>ح</strong> (DN).</li>\n<li>ينذرك النظام كلما زاد غيابك، عند نحو <strong>١٠٪</strong> و<strong>١٥٪</strong> و<strong>٢٠٪</strong>. والإنذار ليس عقوبة، وإنما يبين لك مدى قربك من الحرمان.</li>\n<li>يظهر غيابك في النظام الأكاديمي وتطبيق الجامعة حالما يسجله الأستاذ. افتح <strong>شخصي</strong> ثم <strong>الغياب</strong> لترى لكل مقرر غياباتك وتأخراتك ونسبة غيابك. وهذا هو السجل المعتمد، لا الحضور الظاهر في بلاك بورد.</li>\n<li><strong>السفر:</strong> لا تسافر إلا في الإجازات الرسمية، أو بموافقة كليتك. ولا تعوّل على قبول عذر الغياب للسفر، فالسفر أثناء الفصل بلا إذن يعرّضك للفصل من الجامعة.</li>\n<li><strong>عشرون يومًا متتالية:</strong> الغياب عشرين يومًا متتالية بلا تأجيل ولا اعتذار يؤدي إلى طي قيدك. ويُحسب الفصل عليك. ولا يُعاد فتح القيد المطوي إلا مرة واحدة، خلال أربعة فصول، بعذر مقبول.</li>\n</ul>\n<h3>مثال محسوب</h3>\n<p>كل غياب نسبة من مجموع محاضرات المقرر في الفصل. خذ مقررًا من ساعتين يُدرَّس مرة في الأسبوع مدة ١٥ أسبوعًا:</p>\n<table><thead><tr><th>عدد الغيابات</th><th>نسبتها من المقرر</th><th>ما يحدث</th></tr></thead><tbody>\n<tr><td>١</td><td>٦٫٧٪</td><td>لا شيء بعد</td></tr>\n<tr><td>٢</td><td>١٣٫٣٪</td><td>تجاوزت الإنذار الأول</td></tr>\n<tr><td>٣</td><td>٢٠٪</td><td>إنذارك الأخير</td></tr>\n<tr><td>٤</td><td>٢٦٫٧٪</td><td>حرمان من النهائي، وتقدير ح (DN)</td></tr>\n</tbody></table>\n<p>ففي مقرر كهذا لا تستطيع أن تغيب إلا ثلاث محاضرات على الأكثر، لأي سبب كان. والمقرر الذي يُدرَّس أكثر من ذلك تكون نسبة كل غياب فيه أصغر، لكن القاعدة واحدة: إذا تجاوزت ٢٥٪ حُرمت. فراجع النسبة في شاشة <strong>الغياب</strong> ولا تعتمد على ذاكرتك في العدّ.</p>\n<h3>تقديم عذر الغياب</h3>\n<ol>\n<li>احصل على إثبات لذلك اليوم. وفي المرض يكون الإثبات إجازة مرضية صادرة من صحتي، ويستطيع المركز الطبي الجامعي إصدارها. أما الوصفة الطبية وحدها فليست عذرًا.</li>\n<li>الإجازة المرضية من مستشفى أو مستوصف خاص معتبرة كالإجازة من مستشفى حكومي، ما دامت صادرة في صحتي ومبيّنًا فيها التاريخ. أما الورقة المكتوبة بلا سجل إلكتروني فلا تكفي.</li>\n<li>في النظام الأكاديمي افتح <strong>أكاديمي</strong> ثم <strong>تقديم الأعذار عن غياب المحاضرات</strong>. وحين يُسجَّل غياب يظهر لك أيضًا رابط تنبيه عند تسجيل الدخول.</li>\n<li>ارفع الإثبات لذلك المقرر خلال المهلة التي تبينها الشاشة. وإن أعلنت كليتك نموذجًا خاصًا بها للأعذار فاستعمله أيضًا.</li>\n<li>إن لم يعد المقرر يظهر في الشاشة فقد انتهت المهلة. فأرسل العذر عبر تواصل على <a href=\"https://helpdesk.iu.edu.sa/\">helpdesk.iu.edu.sa</a> إلى كليتك.</li>\n<li>يستغرق الرد من أيام قليلة إلى أسبوعين في أوقات الضغط. وإن لم يصلك شيء فتابع الأمر مع وكيل كليتك.</li>\n</ol>\n<p>العذر المقبول يرفع الحرمان، بشرط أن تكون حضرت نصف المقرر على الأقل.</p>\n<blockquote><p>نصيحة: يسجل الأساتذة الغياب في كل محاضرة، وبعضهم يبدأ من الأسبوع الأول. فاحضر من اليوم الأول، وادّخر ما تبقى لك من غياب للطوارئ الحقيقية.</p></blockquote>\n<h2>قبل الاختبارات</h2>\n<ul>\n<li>جدول اختباراتك النهائية في النظام الأكاديمي تحت <strong>أكاديمي</strong> ثم <strong>الاختبارات النهائية</strong>. ويُنشر قبل فترة الاختبارات بمدة بين أسبوع وشهر. ومواعيد الاختبارات تحددها الجامعة وتختلف عن مواعيد محاضراتك.</li>\n<li>يبين الجدول كل مقرر حُرمت منه بكلمة «محروم»، وكل مقرر اعتذرت عنه بكلمة «معتذر».</li>\n<li>المقررات التي تُدرَّس في شعب كثيرة، ومقررات القرآن، يكون لها في الغالب اختبار نهائي موحد للجامعة كلها.</li>\n<li>اختباران نهائيان في اليوم نفسه وفي الساعة نفسها تعارض. فخذ جدول اختباراتك إلى وكيل كليتك حالما يظهر، فيُنقل أحد الاختبارين أو يؤدى لاحقًا مع الاختبارات البديلة. أما اختباران في اليوم نفسه في وقتين مختلفين، كالساعة ٨:٠٠ والساعة ١٠:٣٠، فليسا تعارضًا.</li>\n<li>اعتمد على النظام الأكاديمي وحده. فالجداول غير الرسمية والتواريخ الخاطئة تنتشر في المجموعات كل فصل.</li>\n<li>املأ <strong>تقييم المقررات</strong> حالما يُفتح قرب نهاية الفصل، فنتائجك تبقى محجوبة حتى تفعل. انظر <strong>أين تظهر النتائج</strong> أدناه.</li>\n<li>في ١٤٤٨ تمتد اختبارات الفصل الأول من ٢٩ نوفمبر إلى ١٤ ديسمبر ٢٠٢٦، واختبارات الفصل الثاني من ٢٥ أبريل إلى ١٠ مايو ٢٠٢٧. وإن طُرح فصل صيفي فاختباراته تبدأ في ٢٧ يوليو ٢٠٢٧. وكل المواعيد في <a href=\"/ar/guides/university-calendar-1448\">التقويم الجامعي</a>.</li>\n</ul>\n<h2>يوم الاختبار</h2>\n<ol>\n<li>كن في القاعة قبل البدء بعشر دقائق على الأقل.</li>\n<li>أحضر بطاقتك الجامعية أو هوية رسمية أخرى، كالإقامة أو هوية زائر في أبشر. وأغلق جوالك وضعه حيث يطلب منك المراقب.</li>\n<li>تستغرق الاختبارات النهائية من ساعة إلى ثلاث ساعات.</li>\n<li>لا يُسمح لأحد بالدخول بعد مضي ثلاثين دقيقة على البدء.</li>\n<li>لا يُسمح لأحد بالخروج في الدقائق الثلاثين الأولى.</li>\n<li>يُعامل الغش وفق لائحة السلوك الطلابي.</li>\n</ol>\n<h2>كيف تُحسب الدرجات</h2>\n<p>كل مقرر من ١٠٠ درجة، ودرجة النجاح ٦٠. وفي معظم المقررات تأتي نحو ٤٠ درجة من أعمال الفصل، كالاختبارات الشهرية التي تُؤدى كثيرًا على بلاك بورد، و٦٠ من الاختبار النهائي. ويبين لك أستاذك التوزيع في بداية المقرر. أما مقررات القرآن فتوزيعها مختلف: لاختبارات التلاوة والحفظ درجات على امتداد الفصل، والاختبار النهائي التحريري، وهو ورقة موحدة من نحو ٢٠ سؤالًا من الاختيار من متعدد، من ٤٠ درجة. ومعدلك من ٥.</p>\n<p>أما برامج الجامعة عن بُعد فتوزيعها مختلف: ٦٠ لأعمال الفصل و٤٠ للنهائي. انظر <a href=\"/ar/guides/studying-online-at-the-islamic-university\">الدراسة عن بُعد في الجامعة الإسلامية</a>.</p>\n<table><thead><tr><th>التقدير</th><th>الدرجة</th><th>النقاط</th></tr></thead><tbody>\n<tr><td>A+</td><td>٩٥ إلى ١٠٠</td><td>٥٫٠٠</td></tr>\n<tr><td>A</td><td>٩٠ إلى ٩٤</td><td>٤٫٧٥</td></tr>\n<tr><td>B+</td><td>٨٥ إلى ٨٩</td><td>٤٫٥٠</td></tr>\n<tr><td>B</td><td>٨٠ إلى ٨٤</td><td>٤٫٠٠</td></tr>\n<tr><td>C+</td><td>٧٥ إلى ٧٩</td><td>٣٫٥٠</td></tr>\n<tr><td>C</td><td>٧٠ إلى ٧٤</td><td>٣٫٠٠</td></tr>\n<tr><td>D+</td><td>٦٥ إلى ٦٩</td><td>٢٫٥٠</td></tr>\n<tr><td>D</td><td>٦٠ إلى ٦٤</td><td>٢٫٠٠</td></tr>\n<tr><td>F</td><td>أقل من ٦٠</td><td>راسب</td></tr>\n</tbody></table>\n<ul>\n<li><strong>DN</strong> (ح) يعني محرومًا بسبب الغياب، ويُحسب رسوبًا.</li>\n<li><strong>W</strong> يعني معتذرًا، بعد اعتذار عن الفصل أو عن مقرر. وليس رسوبًا ولا يمس معدلك.</li>\n<li><strong>مرتبة الشرف:</strong> الأولى تحتاج إلى معدل من ٤٫٧٥ إلى ٥٫٠٠، والثانية من ٤٫٢٥ إلى أقل من ٤٫٧٥. وكلتاهما تشترط ألا ترسب في أي مقرر، وأن تنهي الدرجة في المدة المحددة لمرتبة الشرف، وأن تكون درست ٦٠٪ على الأقل من ساعاتك في هذه الجامعة. والرسوب في أي مقرر، ومنه الحرمان، يمنع مرتبة الشرف حتى بعد نجاحك فيه عند الإعادة.</li>\n</ul>\n<h2>أين تظهر النتائج</h2>\n<ul>\n<li><strong>قيّم مقرراتك أولًا.</strong> درجاتك، ومنها درجات أعمال الفصل، تبقى محجوبة حتى تكمل تقييم كل مقرر: <strong>أكاديمي</strong> ثم <strong>تقييم المقررات</strong>. اضغط رمز كل مقرر وأجب عن كل عبارة. وإجاباتك لا تحمل اسمك. ويُفتح التقييم قرب نهاية الفصل ثم يُغلق، فأنجزه حالما يُفتح.</li>\n<li>تظهر النتائج النهائية بعد اعتماد كليتك لها، تحت <strong>التسجيل الإلكتروني</strong> ثم <strong>نتائج المقررات</strong>. اختر الفصل لترى لكل مقرر درجة الاختبار النهائي، ودرجة أعمال الفصل، والمجموع، والتقدير. وتصدر الدرجات مقررًا بعد مقرر على مدى أيام.</li>\n<li><strong>السجل الأكاديمي</strong>، تحت أكاديمي، يعرض كل مقرر بساعاته ونقاطه وتقديره، ومعدلك الفصلي والتراكمي. وهو للاطلاع الشخصي، لا مستند رسمي.</li>\n<li>المقررات الباقية في خطتك تحت أكاديمي، ثم <strong>المقررات المتبقية في الخطة</strong>.</li>\n<li>السجل الأكاديمي المختوم مجاني تحت <strong>شخصي</strong> ثم <strong>المستندات الرسمية</strong>. ويُفتح في نافذة منبثقة، فاسمح بالنوافذ المنبثقة في متصفحك إن لم يظهر شيء.</li>\n<li>راجع كل نتيجة فور ظهورها، فمهلة التظلم تبدأ من ذلك اليوم.</li>\n</ul>\n<h2>التخلف عن اختبار نهائي</h2>\n<p>إن لم يكن لك عذر مقبول فدرجتك في ذلك الاختبار صفر، وتُحسب درجة المقرر من أعمال الفصل، وهذا يعني الرسوب في معظم المقررات. وإن كان لك عذر مقبول، كتقرير مستشفى، أديت اختبارًا بديلًا، في موعد أقصاه نهاية الأسبوع الثاني من الفصل التالي.</p>\n<ol>\n<li>احصل على الإثبات في اليوم نفسه: تقرير طبي أو إجازة مرضية، أو الورقة الرسمية لما منعك.</li>\n<li>أخبر كليتك فورًا.</li>\n<li>بعد الاختبارات النهائية قدّم في النظام الأكاديمي: <strong>أكاديمي</strong> ثم <strong>تقديم الأعذار عن غياب الاختبار النهائي</strong> ثم <strong>طلب اعتذار عن الاختبارات النهائية</strong>. ولا تُفتح الشاشة إلا أيامًا قليلة بعد النهائيات، فقدّم حالما تُفتح. وإن نشرت كليتك رابطًا خاصًا بها فاستعمله أيضًا.</li>\n<li>تابع طلبك من <strong>إظهار ومتابعة طلبات الاعتذار</strong>.</li>\n<li>في الأسبوع الأول من الفصل التالي تنشر كليتك أسماء المقبولة أعذارهم مع تاريخ كل اختبار بديل ووقته وقاعته. فراجعها مبكرًا، لأن الاختبارات تأتي سريعًا.</li>\n<li>يبقى المقرر في جدولك الجديد حتى تؤدي اختباره. ويضع أستاذك نفسه الاختبار البديل. فأدِّه في الموعد الذي تُعطاه.</li>\n</ol>\n<p>وإن رُفض العذر بقي الصفر. والأسئلة عن الأعذار توجَّه إلى رعاية الطلاب: <strong>920022042</strong> أو <strong>care@iu.edu.sa</strong>.</p>\n<h2>التظلم من درجة</h2>\n<p>الاختبار النهائي يؤدى مرة واحدة. والإعادة الوحيدة هي الاختبار البديل لعذر مقبول، ولا اختبار بديل لمقرر رسبت فيه. فإن رأيت أن اختبارًا نهائيًا صُحح خطأً فلك أن تطلب مراجعته.</p>\n<p>راجع كل درجة يوم ظهورها. فإن رأيت أن الأستاذ أدخلها خطأً فاسأله أولًا: فالأستاذ يستطيع أن يصحح خطأ الإدخال بنفسه حتى يُغلق باب رصد الدرجات. وبعد ذلك لا تتغير الدرجة المعتمدة إلا بالتظلم الرسمي المبيّن أدناه، والتظلم يمكن أن يخفض الدرجة كما يمكن أن يرفعها.</p>\n<ol>\n<li>قدّم طلبك إلى عميد كليتك <strong>خلال ١٥ يومًا</strong> من إعلان النتيجة.</li>\n<li>اذكر اسم المقرر ورمزه، وشعبتك، والأستاذ، والدرجة التي حصلت عليها، وسبب اعتقادك أنها خطأ.</li>\n<li>احتفظ بنسخة من الطلب وتاريخ تسليمه.</li>\n<li>تابعه مع كليتك، وراقب بريدك الجامعي للرد.</li>\n</ol>\n<h2>إن تعثرت في مقرر</h2>\n<p>الاعتذار عن مقرر قبل انتهاء المهلة يعطيك <strong>W</strong> لا رسوبًا، ولا يتأثر معدلك.</p>\n<ol>\n<li>في النظام الأكاديمي افتح <strong>أكاديمي</strong> ثم <strong>الاعتذار عن مقرر</strong> ثم <strong>طلب اعتذار</strong>.</li>\n<li>واظب على حضور المقرر حتى يُبت في الطلب. ويُبت فيه عادةً خلال أسبوع، ولا تلزم موافقة الأستاذ.</li>\n<li>راجع القرار في <strong>إظهار المقررات المعتذر عنها</strong>. وبعد قبوله يُحذف اسمك من قائمة الأستاذ ويخرج المقرر من جدول اختباراتك، وإن بقي ظاهرًا في جدول محاضراتك.</li>\n</ol>\n<p>والحدود:</p>\n<ul>\n<li>مقرران على الأكثر في الفصل الواحد، وستة في برنامجك كله. ولا تعتذر عن المقرر نفسه إلا مرة واحدة.</li>\n<li>لا يجوز أن ينزل عبؤك عن الحد الأدنى، ولا في سنتك الأولى، ولا في فصل تخرجك المتوقع، ولا عن مقرر حُرمت منه.</li>\n<li>في الفترة المحددة في التقويم فقط. وخارجها تبين الشاشة أن العملية لا يمكن إتمامها في هذه الفترة. وفي الفصل الأول من ١٤٤٨ أُغلقت الفترة في أوائل نوفمبر ٢٠٢٦، وفي الفصل الثاني تمتد من ٢٠ ديسمبر ٢٠٢٦ إلى ١٣ مارس ٢٠٢٧.</li>\n</ul>\n<p>أما ترك فصل كامل فهو تأجيل أو اعتذار. انظر <a href=\"/ar/guides/tajeel-and-itithaar\">أخذ فصل إجازة</a>. والانقطاع عن الحضور وحده ليس اعتذارًا: فبعد ٢٠ يومًا يُطوى قيدك.</p>\n<h2>إن رسبت في مقرر</h2>\n<ul>\n<li>يبقى F أو DN في سجلك ويخفض معدلك.</li>\n<li>يجب أن تنجح في كل مقرر في خطتك لتتخرج، فسجّل المقرر الذي رسبت فيه مرة أخرى في فصل لاحق. ولا يُطرح فصل صيفي إلا في السنوات التي تعلن فيها الجامعة ذلك. انظر <a href=\"/ar/ask/summer-semester\">هل يوجد فصل صيفي؟</a></li>\n<li>المقرر الذي يشترط المقرر الراسب متطلبًا سابقًا لا يظهر للتسجيل حتى تنجح فيه. فخطط للإعادة مبكرًا، لا سيما في المقررات المتسلسلة، كالقرآن من ١ إلى ٨.</li>\n<li>ثلاثة فصول متتالية بمعدل تراكمي دون الحد الأدنى للتخرج تؤدي إلى الفصل الأكاديمي. وكذلك تجاوز مدة برنامجك ونصفها.</li>\n<li>يستطيع الطالب المفصول طلب فرصة إضافية واحدة في الفترة المحددة في التقويم. وللفصل الثاني من ١٤٤٨ الفترة من ١١ إلى ١٤ ديسمبر ٢٠٢٦.</li>\n</ul>\n<blockquote><p>نصيحة: قلق من حرمان أو اختبار فاتك أو مقرر رسبت فيه؟ كلّم وكيل كليتك مبكرًا، ما دام في الوقت متسع للتصرف. وإن بقي الأمر عالقًا فراسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "family-records-on-absher": {
  "titleAr": "إقامات أسرتك وسجلاتها في أبشر",
  "summaryAr": "لرب الأسرة الذي يحمل إقامة: تجديد إقامة الزوجة أو الولد (ولو كانا خارج المملكة)، وتوصيل البطاقة إلى البيت، وتصحيح الاسم العربي، والجوازات وتأشيرات الخروج والعودة وشهادات الميلاد، وكلها في «خدمات أفراد الأسرة» في أبشر، إضافة إلى حجز موعد في الجوازات أو الأحوال المدنية أو المرور.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. حين تحمل زوجتك وأولادك إقامات بصفتهم تابعين لك، تتولى سجلات إقامتهم بنفسك في أبشر، تحت <strong>خدمات أفراد الأسرة</strong>. وهذا الدليل لحاملي الإقامة، ومنهم الطلاب الذين يحملون إقامة طلابية، ممن تمر أوراق أسرهم عبر حساباتهم في أبشر. أما بهوية الزائر فلا إقامات للتابعين: انظر <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a>.</p>\n<h2>تجديد إقامة أحد أفراد الأسرة</h2>\n<p>تستطيع تجديد إقامة التابع في أبشر حتى وهو خارج المملكة.</p>\n<ol>\n<li>سجّل الدخول إلى أبشر وافتح <strong>خدمات أفراد الأسرة</strong>، ثم <strong>خدمات هوية مقيم</strong>.</li>\n<li>اختر فرد الأسرة، ثم <strong>تجديد هوية مقيم</strong>.</li>\n<li>اختر مدة التجديد. ويعرض أبشر الرسوم قبل الدفع. ادفعها عبر سداد في تطبيق بنكك، تحت «المدفوعات الحكومية»، برقم إقامة فرد الأسرة.</li>\n<li>عد إلى أبشر وأكمل التجديد. فيظهر تاريخ الانتهاء الجديد في صفحة الشخص، وتحمله الإقامة الرقمية في أبشر وتوكلنا فورًا.</li>\n</ol>\n<p>ولا يجدد أبشر الإقامة إلا إذا:</p>\n<ul>\n<li>كانت رسوم الإقامة للمدة مدفوعة؛</li>\n<li>ولم تكن على ملف ذلك الشخص مخالفات مرورية غير مسددة؛</li>\n<li>وكان جوازه ساريًا، ولكل فرد من الأسرة جواز خاص به؛</li>\n<li>وكانت بصماته وصورته مسجلة، وبصمات كل من تجاوز ٦ سنوات من الأسرة وصورهم؛</li>\n<li>ولم يمضِ على انتهاء الإقامة أكثر من ٦ أشهر.</li>\n</ul>\n<p>جدد قبل تاريخ الانتهاء. فالإقامة التي تُجدد بعد انتهائها بأكثر من ٣ أيام تُفرض عليها غرامة: ٥٠٠ ريال في المرة الأولى، و١٬٠٠٠ ريال في الثانية، والترحيل في الثالثة. والرسوم في <a href=\"/ar/guides/iqama-and-exit-reentry-fees\">الإقامة والخروج والعودة والخروج النهائي ورسوم المرافقين</a>.</p>\n<h2>توصيل بطاقة الإقامة إلى البيت</h2>\n<p>متى جهزت الإقامة الجديدة أو المجددة، يستطيع البريد السعودي توصيل البطاقة إلى بابك بدل أن تستلمها بنفسك.</p>\n<ol>\n<li>في أبشر افتح <strong>خدمات هوية مقيم</strong> واختر خدمة توصيل الإقامة لفرد الأسرة.</li>\n<li>تحقق من العنوان. يجب أن يطابق عنوانك الوطني لدى البريد السعودي. انظر <a href=\"/ar/ask/short-address\">ما العنوان المختصر؟</a></li>\n<li>ادفع رسوم التوصيل: يرسل لك البريد السعودي رسالة نصية فيها رابط دفع بمبلغ ١٧٫٢٥ ريال.</li>\n<li>احتفظ برقم التتبع الذي يصلك في الرسالة الثانية من البريد السعودي، وتابع الشحنة في موقع البريد السعودي أو تطبيقه.</li>\n</ol>\n<p>وتجد الطلب نفسه أيضًا في <strong>خدماتي</strong>، ثم <strong>خدمة التوصيل البريدي</strong>، وفيها كل البطاقات التي يمكن توصيلها بالبريد: الإقامة أو رخصة القيادة أو رخصة سير المركبة، خلال ٩٠ يومًا من إصدارها أو تجديدها. ويجب أن تكون البطاقة معتمدة مسبقًا، والمخالفات غير المسددة تمنع الطلب، فسددها أولًا.</p>\n<h2>تصحيح الاسم العربي</h2>\n<p>إذا كُتب اسم أحد أفراد الأسرة بالعربية خطأً في الإقامة، فصححه مبكرًا، لأن الاسم الذي لا يطابق الجواز تُرفض بسببه الطلبات في البنوك وشركات تحويل الأموال، وفي طلبات التأشيرات العائلية.</p>\n<ol>\n<li>افتح <strong>خدمات أفراد الأسرة</strong>، ثم <strong>خدمات هوية مقيم</strong>.</li>\n<li>اختر فرد الأسرة وخدمة تعديل الاسم العربي، ثم اضغط <strong>بدء الخدمة</strong>.</li>\n<li>أدخل الاسم الأول واسم العائلة بالعربية صحيحين. وطابقهما مع الجواز حرفًا حرفًا، ثم أرسل الطلب.</li>\n<li>تابع الطلب في أبشر حتى يُعتمد.</li>\n</ol>\n<p>والتصحيح مجاني. وإن لم يتح لك أبشر إجراءه إلكترونيًا، فاذهب إلى مكتب الجوازات ومعك الجواز والإقامة ونموذج التصحيح، الذي يعطيك إياه المكتب.</p>\n<ul>\n<li><strong>إن كان الخطأ في إقامتك الطلابية:</strong> يصحح الكفيل الاسم العربي في مقيم، لذا أرسل نسخة من جوازك إلى إدارة السفر في الجامعة عبر تواصل، واطلب «تعديل الاسم المترجم». ثم استلم طبعة جديدة من البطاقة من الجوازات.</li>\n<li><strong>إن كان الخطأ في الاسم الإنجليزي:</strong> تصححه الجوازات ليطابق الجواز تمامًا. خذ الجواز ونسخة منه إلى موعد تحجزه في الجوازات تحت «خدمات المقيمين».</li>\n<li><strong>نماذج الجوازات مجانية.</strong> يعطيك إياها المكتب، وتنشرها وزارة الداخلية في موقعها. وعند بعض المكاتب أشخاص يبيعون النماذج ويعرضون تعبئتها: لا حاجة لك بهم، ولا تسلّم أحدًا أبدًا كلمة مرور أبشر ولا رمزًا يصل إلى جوالك.</li>\n</ul>\n<h2>جواز جديد لأحد أفراد الأسرة</h2>\n<p>حين تحصل زوجتك أو ولدك على جواز جديد، فانقل إقامته إليه في أبشر. ولا يتاح ذلك إلا في آخر ١٢ شهرًا من صلاحية الجواز القديم، وما دام الشخص داخل المملكة، وما دامت لا توجد مخالفات مرورية غير مسددة. وفرد الأسرة الذي في الخارج يعود بالجواز الجديد ويحمل القديم معه، وتحدّث بياناته أنت بعد دخوله. والخطوات، وما تفعله حين يرفض أبشر، في <a href=\"/ar/ask/renew-passport-in-saudi\">جوازي على وشك الانتهاء. كيف أجدده؟</a></p>\n<h2>تأشيرات الخروج والعودة لأسرتك</h2>\n<ul>\n<li>تصدر تأشيرة الخروج والعودة لكل فرد من أسرتك بنفسك في أبشر، وتدفع رسومها برقم إقامته.</li>\n<li>تستطيع تمديدها من أبشر وهم في الخارج، حتى ١٨٠ يومًا في المجموع، ما دام تاريخ العودة الجديد قبل انتهاء إقامتهم بـ٧ أيام على الأقل.</li>\n<li>المخالفة المرورية غير المسددة عليك أو عليهم توقف التأشيرة.</li>\n</ul>\n<p>والرسوم والشروط والخطوات في <a href=\"/ar/guides/iqama-and-exit-reentry-fees\">الإقامة والخروج والعودة والخروج النهائي ورسوم المرافقين</a>.</p>\n<h2>مولود جديد</h2>\n<p>يسجل المستشفى الولادة، وتطبع أنت شهادة الميلاد من أبشر في «خدمات الأحوال المدنية». ثم تضيف المولود إلى إقامتك بطلب في أبشر وتستلم البطاقة من الجوازات. وكل خطوة في <a href=\"/ar/guides/having-a-baby-in-madinah#بعد-الولادة-الأوراق-خطوة-بخطوة\">الولادة في المدينة</a>.</p>\n<h2>حجز موعد في الجوازات أو الأحوال المدنية أو المرور</h2>\n<p>لا تستقبلك الجوازات ولا الأحوال المدنية ولا إدارة المرور إلا بموعد محجوز في أبشر، وتُحجز مواعيد الثلاثة بالطريقة نفسها.</p>\n<ol>\n<li>سجّل الدخول إلى <a href=\"https://www.absher.sa/\">absher.sa</a>، وانزل إلى أسفل الصفحة وافتح <strong>المواعيد</strong>.</li>\n<li>اختر <strong>الجوازات</strong> لموعد في الجوازات، أو <strong>الأحوال المدنية</strong> لتسجيل ولادة، أو <strong>المرور</strong> لموعد في إدارة المرور، ثم اضغط <strong>الانتقال إلى الخدمة</strong> ثم <strong>حجز موعد جديد</strong>.</li>\n<li>اختر الخدمة (انظر الجدول أدناه)، والمنطقة، وعدد المعاملات التي معك، والمكتب.</li>\n<li>اختر التاريخ والوقت: الأوقات الخضراء متاحة والحمراء محجوزة. راجع البيانات، ثم اضغط <strong>تأكيد بيانات الموعد</strong>.</li>\n<li>اطبع الموعد أو احتفظ بصورة للشاشة. وفي مواعيد الأحوال المدنية تعرض الشاشة الأخيرة الأوراق المطلوب إحضارها.</li>\n</ol>\n<table><thead><tr><th>الجهة</th><th>الخدمة التي تختارها</th><th>الغرض</th></tr>\n</thead><tbody><tr><td>الجوازات</td><td>خدمات المقيمين</td><td>كل شيء تقريبًا: إقامة المولود، وتحديث الجواز، وتصحيح الاسم، وإلغاء خروج نهائي منتهي الصلاحية</td></tr>\n<tr><td>الجوازات</td><td>تسجيل السمات الحيوية للوافدين</td><td>بصماتك أنت</td></tr>\n<tr><td>الجوازات</td><td>تسجيل السمات الحيوية لمرافقي الوافدين</td><td>بصمات زوجتك وأولادك</td></tr>\n<tr><td>الجوازات</td><td>الاستعلام عن المعاملات الواردة</td><td>دخول أو خروج لا يظهر في نظام الجوازات</td></tr>\n<tr><td>الأحوال المدنية</td><td>تسجيل واقعة ميلاد</td><td>شهادة ميلاد تعذّر إصدارها إلكترونيًا، في أي مكتب بالمنطقة التي وُلد فيها الطفل</td></tr>\n<tr><td>المرور</td><td>مثل «استبدال رخصة قيادة»، أو «طباعة رخصة سير مركبة»، أو «طباعة إذن إصلاح مركبة»، أو للرخصة المفقودة أو التالفة «إصدار رخصة قيادة بدل تالف / فاقد»</td><td>خدمات الرخصة والسيارة، وتفاصيلها في دليل رخصة القيادة: <a href=\"/ar/guides/drivers-license\">القيادة في المدينة</a></td></tr>\n</tbody></table><p>ولتعديل الموعد أو إلغائه، افتح «المواعيد» والجهة نفسها مرة أخرى، واضغط علامة الزائد (+)، ثم «تعديل» (ثم «تعديل الموعد بالكامل») أو «إلغاء»، وأكّد. وألغِ الموعد الذي لن تحضره ليذهب إلى غيرك.</p>\n<h2>مراجعة كل شيء في مكان واحد</h2>\n<p>صفحة كل شخص في «خدمات أفراد الأسرة» تعرض تاريخ انتهاء إقامته وبيانات جوازه وأي تأشيرة له. راجعها مرة في الشهر، وضع تذكيرًا قبل انتهاء كل إقامة بشهر. والاستعلامات التي لا تحتاج إلى تسجيل دخول في <a href=\"/ar/guides/check-visa-and-iqama-online\">الاستعلام إلكترونيًا عن تأشيرتك ورقم الحدود والتأمين والمخالفات</a>.</p>\n<blockquote><p>نصيحة: تعثرت في خطوة؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "finding-an-apartment": {
  "titleAr": "البحث عن شقة واستئجارها",
  "summaryAr": "أين تبحث، مفروشة أم فارغة، إيجار أم اتفاق خاص، الاستئجار بنفسك (الدفعات والعربون والاستلام من مستأجر سابق والتأجير من الباطن والإصلاحات والفواتير)، وقائمة تحقق قبل التوقيع.",
  "bodyHtmlAr": "<h2>أين تبحث</h2>\n<ul>\n<li><strong>عن طريق الناس:</strong> أوثق الطرق. اسأل في مجموعة MESH وبين الطلاب والإخوة الموجودين هنا.</li>\n<li><strong>مجموعات واتساب وتيليجرام:</strong> إعلانات حديثة واتصال مباشر بالملاك والطلاب المغادرين.</li>\n<li><strong>مواقع العقار وتطبيقاته:</strong> عقار وبيوت وحراج أكبرها. وأسعارها تميل إلى المبالغة، وكثير من الملاك لا يتكلمون إلا العربية.</li>\n<li><strong>الوسطاء:</strong> بعض المكاتب العقارية تعمل بالإنجليزية. استعمل وسيطًا من قائمة إيجار الرسمية للوسطاء المعتمدين، وتحقق من رقم رخصته «فال» في تطبيق فال أو على موقع الهيئة العامة للعقار قبل أن تدفع شيئًا.</li>\n<li><strong>حراس العمائر:</strong> اسأل حارس العمارة التي تعجبك، شخصيًا بعد العصر حين يكون عند الباب. فهو يعرف الشقق التي ستخلو قريبًا.</li>\n<li><strong>استلام شقة من مستأجر:</strong> الطلاب المغادرون يسلّمون شققهم كثيرًا، وأحيانًا مع الأثاث. اطلب رؤية العقد وقابل المالك قبل أن تدفع ثمن الأثاث أو الإيجار المتبقي.</li>\n</ul>\n<blockquote><p>نصيحة: إن كانت هذه أول مرة لك فأقم في فندق أو شقة قصيرة الأجل (بوكينج أو إير بي إن بي أو جاذر) أسبوعًا أو أسبوعين وابحث بنفسك. فسترى المبنى وتجرب التكييف وتفاوض مباشرة.</p></blockquote>\n<h2>مفروشة أم فارغة</h2>\n<p>لمدة ثلاثة إلى ستة أشهر خذ مفروشة. ولسنة أو أكثر فالشقة الفارغة أرخص بنسبة ٤٠ إلى ٥٠٪ وتستطيع تأثيثها برخص من سوق حراج. ومعظم المباني الجيدة الجديدة على بُعد ٨ إلى ١٥ دقيقة بالسيارة من الحرم لا على مسافة مشي. وشقق القبو أقل كلفة في التبريد لكنها رطبة في الشتاء، فافحص الجدران قبل أن تستأجر واحدة منها. وفي سنة ٢٠٢٥ كانت الشقة الفارغة ذات الثلاث أو الأربع غرف تؤجر سنويًا بنحو ٢٣٬٠٠٠ إلى ٢٥٬٠٠٠ ريال، والغرفة بنحو ٦٠٠ ريال في الشهر.</p>\n<h2>العقد</h2>\n<p><strong>إيجار</strong> هو النظام الرسمي للهيئة العامة للعقار، والعقد المسجل يحمي الطرفين قانونًا. ولا تكتب العقد بنفسك: ينشئه على إيجار وسيط معتمد، أو مالك مستوفٍ لشروط إيجار، وتوافق عليه أنت من الرابط الذي يرسله إيجار برسالة نصية. ويعمل هذا بالإقامة، وبهوية الزائر على التأشيرة التعليمية (انظر الجواب عن الاستئجار بتأشيرة طالب). ورسوم التسجيل ١٢٥ ريالًا في السنة، فتحقق في العقد من يدفعها. ومنذ سبتمبر ٢٠٢٥ يلزم الملاك تسجيل عقودهم، ويستطيع المستأجر طلب التسجيل أيضًا. وكثير من الإيجارات في المدينة ما زالت اتفاقات ورقية خاصة لا حماية قانونية فيها. وخط إيجار 199011.</p>\n<h2>الاستئجار بنفسك</h2>\n<p>كل ما يلي ينطبق بالإقامة وبهوية الزائر. وبهوية الزائر يسجل لك وسيط معتمد عقد إيجار.</p>\n<h3>مدة العقد والدفعات</h3>\n<ul>\n<li>الشقق الفارغة تؤجر ستة أشهر أو اثني عشر شهرًا في كل مرة. ويمكن أن يجعل عقد إيجار الأجرة سنوية أو نصف سنوية أو ربع سنوية أو شهرية، لكن معظم الملاك في المدينة يريدون المدة كلها مقدمًا، أو دفعتين في السنة.</li>\n<li>دفع السنة كاملة مرة واحدة كثيرًا ما يخفض السعر، فاسأل عن السعر السنوي وسعر الأقساط قبل أن توافق.</li>\n<li>الشقق المفروشة التي يعرضها الوسطاء تؤجر عادة شهرًا بشهر، بسعر أعلى، وغالبًا بلا عقد باسمك.</li>\n<li>في عقد إيجار المسجل ادفع الأجرة عبر إيجار فقط، بمدى أو سداد من الفاتورة. فالنقد أو التحويل البنكي خارج إيجار لا يُعدّ إثباتًا للدفع.</li>\n<li>العقد المسجل يتجدد تلقائيًا ما لم تُخطر أنت أو المالك قبل انتهائه بستين يومًا على الأقل. فإن كنت تنوي المغادرة فأخبر المالك كتابة قبل ذلك بوقت كافٍ.</li>\n</ul>\n<h3>ما تدفعه في البداية</h3>\n<ul>\n<li>الدفعة الأولى من الأجرة، وهي عادة ستة أشهر أو اثنا عشر شهرًا.</li>\n<li>عمولة الوسيط إن استعنت بوسيط. اتفق على المبلغ قبل أن يبدأ.</li>\n<li>رسوم إيجار، ١٢٥ ريالًا في السنة، إن جعلها العقد عليك.</li>\n<li>العربون إن طلبه المالك. واكتب في العقد مبلغه ومتى وكيف يُرد.</li>\n<li>الأثاث والمكيفات، فالشقة الفارغة تأتي أحيانًا بلا أثاث ولا مكيفات.</li>\n</ul>\n<h3>استلام شقة من طالب مغادر</h3>\n<p>الطلاب المغادرون يسلّمون شققهم كثيرًا ويبيعون أثاثهم برخص. ولا يستطيع المستأجر نقل الشقة أو العقد إلى غيره بلا موافقة المالك، ولذلك:</p>\n<ol>\n<li>قابل المالك أو وكيله قبل أن تدفع شيئًا، وتأكد أنه يوافق على تأجيرك.</li>\n<li>إن كان للطالب المغادر عقد في إيجار فيُنهى ويُسجل عقد جديد باسمك. وإن لم يكن له عقد فاتفق على الأجرة والمدة وأي أشهر مدفوعة مباشرة مع المالك.</li>\n<li>ادفع ثمن الأثاث على حدة، مقابل قائمة مكتوبة بما تشتريه.</li>\n<li>لا تدفع للطالب المغادر أجرة أشهر مقبلة أبدًا إلا إن أكد المالك كتابة أنه استلم المال وأن الأشهر لك.</li>\n</ol>\n<h3>التأجير من الباطن</h3>\n<ul>\n<li>تأجير الشقة أو غرفة منها لغيرك، أو إسكان شركاء يدفعون لك الأجرة، يحتاج إلى إذن المالك. وبدونه تكون مخالفًا للعقد ويستطيع المالك إنهاءه.</li>\n<li>إن استأجرت ممن ليس المالك فلا عقد بينك وبين المالك. فإن غادر المستأجر الأصلي أو توقف عن الدفع فيمكن أن تفقد الشقة. اطلب رؤية عقد المستأجر الأصلي وإذن المالك الكتابي بالتأجير من الباطن.</li>\n<li>حين يتشارك الطلاب شقة فاتفقوا كتابة فيما بينكم على قسمة الأجرة والعربون والفواتير، وعلى ما يحدث حين يغادر أحدكم.</li>\n</ul>\n<h3>الإصلاحات</h3>\n<p>في عقد إيجار يدفع المالك ثمن الإصلاحات التي تبقي الشقة آمنة صالحة للسكن، كالعيوب الإنشائية والأعطال التي تمنعك من العيش فيها. وتدفع أنت ثمن الصيانة اليومية والضرر الناتج عن الاستعمال، ما لم ينص العقد على غير ذلك. والاتفاقات الورقية لا تذكر الإصلاحات غالبًا، فاتفق كتابة قبل التوقيع على من يصلح المكيفات والسخان والسباكة.</p>\n<h3>الفواتير باسمك</h3>\n<ul>\n<li>بعقد إيجار تُنقل حسابات الكهرباء والماء إلى اسمك عبر خدمة نقل المسؤولية المالية في إيجار. يختارها الوسيط حين يسجل العقد، أو تطلبها أنت في إيجار لعقد قائم. وتعود إلى المالك حين ينتهي العقد.</li>\n<li>صوّر قراءة العداد يوم انتقالك.</li>\n<li>بلا عقد تبقى الفواتير باسم المالك. فاتفق على طريقة دفعك واحتفظ بكل إيصال.</li>\n<li>إنترنت البيت: انظر <a href=\"/ar/ask/home-internet-no-iqama\">كيف أحصل على إنترنت منزلي دون إقامة؟</a></li>\n</ul>\n<h3>علامات الخطر قبل أن تدفع</h3>\n<ul>\n<li>لا تستطيع مقابلة المالك، ولا رؤية أوراقه ولا رخصة فال للوسيط.</li>\n<li>يُطلب منك مال لحجز شقة لم ترها، خاصة بالتحويل إلى حساب شخصي.</li>\n<li>الأجرة أقل بكثير من الشقق الأخرى في الحي نفسه.</li>\n<li>يرفض المالك تسجيل العقد في إيجار، أو يطلب الأجرة نقدًا على عقد مسجل.</li>\n<li>يؤجرك أحد من الباطن بلا إذن كتابي من المالك.</li>\n<li>الكهرباء مقطوعة، أو ترك المستأجر السابق فاتورة كبيرة غير مدفوعة.</li>\n</ul>\n<blockquote><p>نصيحة: غير متأكد من عقد أو عرض؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a> قبل أن تدفع.</p></blockquote>\n<h2>قائمة تحقق قبل أن تدفع</h2>\n<ol>\n<li>ابحث عن الرطوبة أو التشققات أو العفن، خاصة في الحمامات.</li>\n<li>شغّل كل مكيف وتأكد أنه يبرد. فأيام الصيف تبلغ نحو ٤٤ درجة، وأكثر في أسوأ الأيام.</li>\n<li>افتح كل صنبور، وتحقق من الضغط والماء الساخن، واسحب السيفون، وابحث عن تسريب أو روائح.</li>\n<li>جرّب كل مصباح ومقبس.</li>\n<li>اطلب رؤية عداد الكهرباء، وتحقق أنه لا فاتورة غير مدفوعة من المستأجر السابق.</li>\n<li>جرّب الثلاجة والطباخ والسخان والغسالة إن كانت مشمولة.</li>\n<li>تحقق أن النوافذ تُغلق بإحكام ضد الرمل، واطلب حواجز للنوافذ إن كان معك أطفال.</li>\n<li>اتفق كتابة على من يدفع الإصلاحات الصغيرة والماء والكهرباء.</li>\n<li>تحقق هل تستأجر من المالك أم من مؤجر من الباطن، وانظر أوراق المالك أو رخصة الوسيط.</li>\n<li>إن كان في المبنى مصعد فتأكد أنه يعمل، خاصة مع الأطفال أو الوالدين المسنين.</li>\n</ol>\n<blockquote><p>ملاحظة: إن ترك المستأجر السابق فاتورة كهرباء غير مدفوعة فيمكن أن تُقطع الكهرباء عنك بعد انتقالك بقليل. وعشر دقائق في فحص العداد توفر أسابيع من المتاعب.</p></blockquote>"
 },
 "first-30-days-in-madinah": {
  "titleAr": "أيامك الثلاثون الأولى في المدينة: قائمة مرتبة",
  "summaryAr": "من الهبوط إلى الاستقرار: الشريحة وأبشر ونفاذ والبنك والسكن والتسجيل في الجامعة والمواصلات والمشتريات والصحة، بالترتيب الذي ينفع.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. هذا هو الترتيب الذي يوفر أكثر الوقت، لأن كل خطوة تفتح التي بعدها. علّم على كل خطوة حين تنجزها. والطلاب على التأشيرة التعليمية يحملون هوية زائر لا إقامة، والخطوات أدناه تشمل الحالتين.</p>\n<h2>قبل أن تسافر</h2>\n<ol>\n<li>تأكد أن الاسم في تذكرتك وتأشيرتك وكل سجلات الجامعة يطابق جوازك حرفًا بحرف.</li>\n<li>احزم شهاداتك الأصلية وصورًا شخصية بخلفية بيضاء، ونسخًا من كل شيء على جوالك.</li>\n<li>أحضر ما يكفيك من النقد لشهريك الأولين، أو بطاقة أجنبية تعمل. أول مكافأة وبطاقتك البنكية تأخذان وقتًا.</li>\n<li>أحضر خطابًا من طبيبك لأي دواء تأخذه بانتظام. الوصفات الطبية من البلدان الأخرى لا تُقبل هنا.</li>\n</ol>\n<h2>اليومان الأول والثاني: الجوال والليلة الأولى</h2>\n<ol>\n<li><strong>اشترِ شريحة سعودية</strong> من المطار أو من أي فرع لشركة اتصالات، بجوازك ورقم الحدود. يأخذ المحل بصمتك. وعلى هذا الرقم تصل رموز أبشر ونفاذ والبنك. انظر <a href=\"/ar/guides/sim-internet-bank\">شريحة الجوال والإنترنت وبطاقة بنكية سعودية</a>.</li>\n<li><strong>اذهب إلى غرفتك أو إلى مكان مبيتك الأول.</strong> تطبيقات النقل مثل كريم وأوبر تعمل من المطار. والأسر التي ستستأجر شقة يناسبها فندق أو شقة قصيرة الأجل في الأسبوع الأول أو الأسبوعين الأولين.</li>\n<li><strong>احفظ أرقام الطوارئ:</strong> 997 للإسعاف، و911 الرقم الموحد للطوارئ في المدينة.</li>\n</ol>\n<h2>الأسبوع الأول: الجامعة وهويتك الرقمية</h2>\n<ol>\n<li><strong>سجّل في أبشر</strong> برقم الحدود (أو رقم إقامتك)، ثم <strong>فعّله من جهاز الخدمة الذاتية</strong> ببصمتك، ثم <strong>فعّل نفاذ</strong>. وإن فشل التفعيل فانظر <a href=\"/ar/ask/absher-nafath-activation\">تفعيل أبشر أو نفاذ يفشل عندي باستمرار</a>. والترتيب الكامل في <a href=\"/ar/guides/new-student-steps\">الخطوات الأولى للطلاب الجدد</a>.</li>\n<li><strong>أصدر هوية الزائر</strong> في أبشر إن كنت على التأشيرة التعليمية. وما تستطيعه وما لا تستطيعه في <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a>.</li>\n<li><strong>استلم بطاقتك الجامعية.</strong> يستلمها الطلاب الجدد في أسبوع التهيئة. وإن وصلت بعده فخذ هوية الزائر أو الإقامة إلى مكتب البطاقة الجامعية، فيطبعها في الحال.</li>\n<li><strong>جهّز بريدك الجامعي والنظام الأكاديمي.</strong> جدولك تحت «التسجيل الإلكتروني» ثم «المقررات المسجلة». انظر <a href=\"/ar/ask/find-my-timetable\">أين أجد جدول محاضراتي؟</a></li>\n<li><strong>احجز وجباتك</strong> في المطعم الجامعي إن كنت تأكل في الحرم الجامعي. تُحجز الوجبات شهرًا كاملًا في كل مرة، فضع تذكيرًا قبل نهاية كل شهر. انظر <a href=\"/ar/guides/campus-life-islamic-university\">حياة الطالب في الجامعة الإسلامية</a>.</li>\n</ol>\n<h2>الأسبوع الثاني: المال والأوراق</h2>\n<ol>\n<li><strong>سجّل عنوانك الوطني</strong> في البريد السعودي. البنوك وخدمات التوصيل تحتاجه. انظر <a href=\"/ar/ask/short-address\">ما العنوان المختصر؟</a></li>\n<li><strong>افتح حسابًا بنكيًا</strong> واطلب بطاقة مدى. حاملو هوية الزائر يذهبون إلى الفرع بجوازهم وهوية الزائر في أبشر، أو يفتحون الحساب عبر الإنترنت من خلال نفاذ. أما المكافأة نفسها فتُصرف على <a href=\"/ar/guides/getting-your-stipend-off-the-university-card\">بطاقة المكافأة الجامعية</a> التي تصدرها الجامعة، لا في هذا الحساب.</li>\n<li><strong>جهّز حسابك في اعتماد</strong> لتذاكر الجامعة وتأكد أن بياناتك تطابق جوازك. انظر <a href=\"/ar/guides/etimad-account\">تذكرتك من الجامعة: اعتماد وأمر الإركاب والقواعد</a>.</li>\n<li><strong>راجع المواعيد المهمة</strong> لفصلك: الاختبارات والإجازات ومواعيد التأجيل والانسحاب. انظر <a href=\"/ar/guides/university-calendar-1448\">التقويم الجامعي</a>.</li>\n</ol>\n<h2>الأسبوع الثالث: السكن والتنقل</h2>\n<ol>\n<li><strong>الأسر وكل من يستأجر:</strong> عاينوا الشقق بأنفسكم، وتحققوا من العداد والتكييف، وسجلوا العقد في إيجار (عن طريق وسيط معتمد لحاملي هوية الزائر). انظر <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a>.</li>\n<li><strong>ثبّت تطبيق حافلات المدينة</strong> وأضف بطاقة. الحافلات لا تقبل النقد. انظر <a href=\"/ar/guides/haramain-train-and-city-buses\">قطار الحرمين وحافلات المدينة</a>.</li>\n<li><strong>تعلّم الطريق إلى الحرم:</strong> حافلات الجامعة وحافلات المدينة وتطبيقات النقل. انظر <a href=\"/ar/guides/getting-around\">التنقل في المدينة</a>.</li>\n<li><strong>وفّر إنترنت البيت:</strong> الألياف بالإقامة، أو جهاز توجيه 5G بشريحة بيانات لحاملي هوية الزائر.</li>\n</ol>\n<h2>الأسبوع الرابع: الحياة اليومية</h2>\n<ol>\n<li><strong>تزوّد بالمشتريات.</strong> بن داود وكارفور ولولو والعثيم وبنده هي الأسواق الكبرى، وتطبيقات التوصيل تأتيك بالطعام والمشتريات إلى الباب. والأسعار المعتادة في <a href=\"/ar/guides/cost-of-living\">كم تكلف المعيشة في المدينة</a> و<a href=\"/ar/guides/everyday-apps-and-services\">التطبيقات والخدمات اليومية</a>.</li>\n<li><strong>اعرف أين تذهب حين تمرض:</strong> المركز الطبي الجامعي للطلاب، والصيدلية للأمور الصغيرة، وأقرب قسم طوارئ لكل أمر جاد. انظر <a href=\"/ar/guides/doctors-hospitals-and-pharmacies\">الأطباء والمستشفيات والصيدليات وأرقام الطوارئ</a>.</li>\n<li><strong>احجز الروضة الشريفة</strong> في نسك، وخطط لأول سبت لك في قباء. انظر <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء</a>.</li>\n<li><strong>اختر درسًا أو حلقة</strong> تحضرها كل أسبوع. دروس اليوم في <a href=\"/ar/duroos\">الدروس</a>.</li>\n<li><strong>تأكد أن جوالك وبنكك وأبشر ما زالت تعمل معًا.</strong> فإن غيرت الشريحة فحدّث الرقم في أبشر.</li>\n</ol>\n<blockquote><p>نصيحة: احتفظ في جوالك بمجلد فيه صور جوازك وتأشيرتك وبطاقتك الجامعية وعقدك وكل إيصال. ستُطلب منك أكثر مما تتوقع.</p></blockquote>\n<h2>لست طالبًا؟</h2>\n<p>الأسر والمهاجرون على تأشيرة زيارة يتبعون معظم القائمة نفسها: الشريحة وأبشر والبنك والسكن والمواصلات. وراجع مدة بقائك التي تسمح بها تأشيرتك وكيفية التمديد في <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a>، وانظر <a href=\"/ar/guides/kindergartens-and-schools\">رياض الأطفال والمدارس</a> إن كان معك أطفال.</p>\n<blockquote><p>نصيحة: تعثرت في خطوة؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "getting-around": {
  "titleAr": "التنقل في المدينة، وإلى مكة",
  "summaryAr": "الحافلات وتطبيقات التوصيل والقيادة وتأجير السيارات، والقطار أو سيارة الأجرة المشتركة إلى مكة.",
  "bodyHtmlAr": "<p>المدينة صغيرة متقاربة. ومعظم المشاوير تأخذ ١٠ إلى ١٥ دقيقة بالسيارة.</p>\n<h2>داخل المدينة</h2>\n<ul>\n<li><strong>حافلات المدينة:</strong> ٣٫٤٥ ريالات للرحلة على خطوط المدينة. ولخط المطار أجرته الخاصة، تظهر في تطبيق حافلات المدينة. وكل تذكرة لحافلة واحدة، فتبديل الحافلة يعني الدفع من جديد. والنقد غير مقبول في الحافلة: مرر بطاقة مدى أو فيزا أو ماستركارد أو جوالك، أو ادفع في تطبيق حافلات المدينة، الذي يبيع أيضًا اشتراكات اليوم والأسبوع والشهر (١٠ و٦٠ و٢٤٠ ريالًا). خدمة العملاء: 920000877.</li>\n<li><strong>من محطة قطار الحرمين:</strong> المحطة في حي الحضراء، على بُعد نحو ٩ كيلومترات من الحرم. ويعمل الخط السريع ٣٠٠ بين المحطة ومحطة الحافلات المركزية عند المسجد النبوي، أو استعمل تطبيق توصيل.</li>\n<li><strong>تطبيقات التوصيل:</strong> بولت وكريم وجيني وأوبر. وتوقع ١٠ إلى ٣٠ ريالًا عبر المدينة، وأكثر بعد الصلوات في الحرم مباشرة، خاصة الجمعة، حين ترتفع الأسعار.</li>\n<li><strong>ممشى قباء:</strong> عربات كهربائية صغيرة تسير على ممشى قباء بين الحرم ومسجد قباء بنحو ١٠ إلى ٢٠ ريالًا. اتفق على السعر قبل أن تركب.</li>\n</ul>\n<h2>القيادة</h2>\n<p>على تأشيرة الزيارة تستطيع القيادة برخصتك إن كانت السعودية تعترف برخصة بلدك. وأحضر معها رخصة قيادة دولية، لأن شركات التأجير تطلبها عادة، واحمل دائمًا الرخصة الأصلية لا صورتها. وشراء سيارة أو تسجيلها يحتاج إلى إقامة. وكثير من شركات التأجير تطلب الإقامة أيضًا، لكن التأجير بين الأفراد شائع، والطلاب يؤجرون سياراتهم في الصيف بـ ١٬٥٠٠ إلى ٣٬٥٠٠ ريال شهريًا.</p>\n<p>البنزين ٢٫١٨ ريال للتر من ٩١ و٢٫٣٣ من ٩٥ (نوفمبر ٢٠٢٦). والمخالفات المرورية تظهر في أبشر تحت المخالفات.</p>\n<h2>إلى مكة للعمرة</h2>\n<table><thead><tr><th>الوسيلة</th><th>المدة</th><th>التكلفة (ريال)</th></tr></thead><tbody>\n<tr><td>قطار الحرمين السريع</td><td>نحو ساعتين وعشرين دقيقة</td><td>الأجرة الأساسية ١٦٢ للدرجة الاقتصادية، مع ضريبة القيمة المضافة ١٥٪؛ والأجور تتغير مع الطلب</td></tr>\n<tr><td>سيارة أجرة مشتركة من المواقف قرب مسجد بلال أو «توب تن»</td><td>أربع ساعات ونصف إلى خمس</td><td>٤٠ إلى ٥٠ للمقعد</td></tr>\n<tr><td>حافلة بين المدن</td><td>ست ساعات إلى سبع</td><td>نحو ٨٥ إلى ١٠٠</td></tr>\n<tr><td>سيارتك (نحو ٤٢٠ كيلومترًا)</td><td>أربع ساعات ونصف إلى خمس</td><td>البنزين</td></tr>\n</tbody></table>\n<h3>ركوب قطار الحرمين</h3>\n<ul>\n<li>احجز على موقع قطار الحرمين أو تطبيقه، أو في تطبيق نسك، واقرأ قواعد التغيير والاسترداد قبل أن تدفع.</li>\n<li>يُدخل كل مسافر هوية عند الحجز (إقامة أو جواز أو هوية سعودية). واحمل الهوية نفسها يوم السفر، لأنها تُطابَق مع التذكرة.</li>\n<li>لكل راكب حقيبة واحدة حتى ٢٥ كيلو (٦٥ في ٥٥ في ٣٥ سم) وحقيبة يد صغيرة. والأمتعة الزائدة غير مسموح بها في القطار.</li>\n<li>هناك تفتيش أمني قبل الرصيف، فاحضر قبل الموعد بثلاثين دقيقة على الأقل.</li>\n</ul>\n<blockquote><p>نصيحة: أجور القطار ترتفع مع الطلب، فاحجز مبكرًا لرمضان والجمعة والإجازات.</p></blockquote>"
 },
 "getting-married-in-saudi-arabia": {
  "titleAr": "الزواج في السعودية: عقد النكاح وأوراقه والإقامة",
  "summaryAr": "من يحق له الزواج في المملكة، والمأذون الشرعي والعقد الإلكتروني، والأوراق وشرائح الجوال السعودية التي يحتاجها كل طرف، واستعمال العقد خارج المملكة، وتسجيل الزواج المعقود في الخارج، ونقل إقامة الزوجة من أبيها إلى زوجها.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. يستطيع الأجنبيان أن يعقدا نكاحهما في السعودية، ويتسلما من وزارة العدل عقد زواج رسميًا إلكترونيًا. ويتناول هذا الدليل من يحق له الزواج هنا، والأوراق، والخطوات، وما يُفعل بالإقامة بعد ذلك.</p>\n<h2>من يحق له الزواج هنا</h2>\n<table><thead><tr><th>ما تحمله</th><th>هل يحق لك الزواج في المملكة؟</th></tr></thead><tbody>\n<tr><td>إقامة</td><td>نعم</td></tr>\n<tr><td>إقامة تابع على ملف أحد الوالدين أو الزوج</td><td>نعم</td></tr>\n<tr><td>تأشيرة زيارة عائلية</td><td>نعم</td></tr>\n<tr><td>تأشيرة سياحية</td><td>نعم</td></tr>\n<tr><td>تأشيرة حج أو عمرة</td><td>لا</td></tr>\n</tbody></table>\n<p>ويلزم كذلك أن يكون لكل طرف في العقد شريحة جوال سعودية مسجلة باسمه هو، لأن طلبات التأكيد تصل برسائل نصية.</p>\n<h2>ما تحتاج إليه</h2>\n<ul>\n<li><strong>خمسة أشخاص وخمس شرائح سعودية:</strong> الزوج، والزوجة، ووليّ الزوجة، والشاهدان، لكل منهم رقم سعودي باسمه.</li>\n<li><strong>الهوية:</strong> صورة من الإقامة لكل مقيم، وصورة من الجواز لمن كان على تأشيرة سياحية أو تأشيرة زيارة. ويقدم الشاهدان صورتين من إقامتيهما.</li>\n<li><strong>المهر:</strong> المبلغ المتفق عليه، ويُكتب في العقد.</li>\n</ul>\n<h2>الخطوات بالترتيب</h2>\n<ol>\n<li><strong>اختر مأذونًا شرعيًا.</strong> يسجل المأذون العقد لدى وزارة العدل، وفي موقع الوزارة قائمة بالمأذونين في كل مدينة. واتفق معه على أجرته قبل أن يبدأ.</li>\n<li><strong>أعطه البيانات.</strong> ينشئ المأذون العقد في بوابة وزارة العدل، فيختار المنطقة ويُدخل بيانات كل شخص.</li>\n<li><strong>انتظر التحقق.</strong> بعد أيام قليلة تصل إلى كل رقم من الأرقام الخمسة رسالة تطلب التأكيد. وعلى كل شخص أن يؤكد خلال ٢٤ ساعة.</li>\n<li><strong>عقد النكاح.</strong> بعد أن يؤكد الخمسة جميعًا يعقد المأذون النكاح في مكان تتفق معه عليه، بحضور الزوج والزوجة ووليّها والشاهدين. فيسأل الزوجة والزوج عن رضاهما ثم يُتم العقد.</li>\n<li><strong>العقد.</strong> يصدر العقد إلكترونيًا، ويصلك ملف PDF. واحتفظ منه بعدة نسخ.</li>\n</ol>\n<h2>استعمال العقد خارج المملكة</h2>\n<p>لتقديم العقد إلى سفارتك أو في بلدك، صدّقه من وزارة العدل، ثم من وزارة الخارجية، ثم ترجمه إلى اللغة التي يطلبها بلدك، وصدّق الترجمة من سفارة بلدك أو قنصليته في السعودية.</p>\n<h2>تزوجتما في الخارج وتقيمان هنا</h2>\n<p>إذا تزوج اثنان من حاملي الإقامة خارج السعودية، صُدّقت وثيقة الزواج من وزارة خارجية البلد الذي صدرت فيه، ثم من السفارة السعودية هناك، ثم من وزارة الخارجية في السعودية، ثم تُسلَّم إلى الجوازات.</p>\n<h2>نقل إقامة الزوجة من أبيها إلى زوجها</h2>\n<p>إذا كانت العروس على إقامة أبيها تابعةً له، انتقلت إقامتها بعد الزواج إلى ملف زوجها. ويتم ذلك في الجوازات، بموعد لخدمات المقيمين يُحجز في أبشر: انظر <a href=\"/ar/guides/family-records-on-absher#حجز-موعد-في-الجوازات-أو-الأحوال-المدنية-أو-المرور\">حجز موعد في الجوازات</a>. وخذ معك:</p>\n<ul>\n<li>موافقة الأب، ويوقّعها أمام موظف الجوازات؛</li>\n<li>نموذج نقل الإقامة. ونماذج وزارة الداخلية متاحة للتنزيل مجانًا، فلا حاجة إلى الدفع لمن يبيعونها خارج المكتب؛</li>\n<li>صورة من عقد الزواج؛</li>\n<li>جواز الزوجة وإقامتها الأصليين؛</li>\n<li>صورًا من إقامات الزوجة والزوج والأب؛</li>\n<li>خطابًا من صاحب عمل الزوج يوافق فيه على النقل، مختومًا من الغرفة التجارية؛</li>\n<li>رسوم النقل.</li>\n</ul>\n<p>وإن كانت إقامة الزوج إقامة طالب فالجامعة كفيله، فاسأل إدارة السفر عبر تواصل عما تطلبه منك قبل أن تحجز الموعد.</p>\n<p>ينقل الموظف الإقامة في النظام عند الشباك، وتُطبع البطاقة الجديدة في شباك آخر. وبعد ذلك يدير الزوج سجلاتها في أبشر تحت خدمات أفراد الأسرة: انظر <a href=\"/ar/guides/family-records-on-absher\">إقامات أسرتك وسجلاتها في أبشر</a>.</p>\n<p>والزوجة التي تقدم لاحقًا من الخارج تأتي بتأشيرات الأسرة المشروحة في <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a>.</p>\n<blockquote><p>نصيحة: تخطط لعقد نكاح ولا تعرف أي الأوراق تخصك؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "getting-your-stipend-off-the-university-card": {
  "titleAr": "بطاقة مكافأتك من الجامعة: سحب المال منها وحل مشكلاتها",
  "summaryAr": "بطاقة مصرف الراجحي التي تصرف عليها الجامعة مكافأتك: متى يصل المال، وكيف تنقله إلى حسابك عبر تطبيق محفظة أو صراف آلي، والرقم السري، وما تفعله حين تنتهي صلاحية البطاقة أو تتعطل أو تضيع.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. تصرف الجامعة المكافأة الشهرية على بطاقة بنكية تصدرها باسمك: بطاقة من مصرف الراجحي تُعرف ببطاقة المكافأة. وهذا الدليل يبين كيف تُخرج المال منها، وما تفعله حين تواجهك فيها مشكلة. أما ما تصرفه المنحة وما يوقفه ففي <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة</a>.</p>\n<h2>استلام البطاقة</h2>\n<ul>\n<li>يستلمها الطالب الجديد مع بطاقته الجامعية في اللقاء التعريفي في الأسبوع الأول. وفي ٢٠٢٦ سُلّمت البطاقتان في قاعة السلام يوم ١٧ أغسطس. أحضر معك صورة شخصية مقاس ٤×٦.</li>\n<li>فاتك اللقاء التعريفي؟ استلمها من شباك بطاقات المكافأة في الوحدة ٢٢ (انظر أدناه).</li>\n<li>الجامعة هي التي تفعّل البطاقة. ورقمك السري في الظرف الذي تأتي فيه. وتستطيع تغيير الرقم السري من صراف آلي.</li>\n</ul>\n<h2>ما تستطيعه البطاقة وما لا تستطيعه</h2>\n<table><thead><tr><th>تستطيع البطاقة</th><th>لا تستطيع البطاقة</th></tr></thead><tbody>\n<tr><td>سحب النقد من الصراف الآلي</td><td>استقبال الإيداعات النقدية أو التحويلات. فالجامعة وحدها تصرف عليها</td></tr>\n<tr><td>التحويل إلى حسابك من صراف آلي للراجحي</td><td>الإضافة إلى Apple Pay أو إلى تطبيق الراجحي</td></tr>\n<tr><td>شحن تطبيق محفظة مثل برق أو الإنماء باي أو urpay</td><td>أي استعمال بعد انتهاء صلاحيتها، ولو كان فيها مال</td></tr>\n</tbody></table>\n<h2>متى تصل المكافأة</h2>\n<ul>\n<li><strong>عادة بين يومي ٢١ و٢٥</strong> من كل شهر ميلادي، وكثيرًا ما تصل في وقت متأخر من المساء.</li>\n<li><strong>نهاية الأسبوع:</strong> إذا وافق يوم ٢٥ جمعة أو سبتًا، جاء الصرف في اليوم الذي قبله أو الذي بعده.</li>\n<li><strong>الصرف المبكر:</strong> قبل اليوم الوطني في سبتمبر، وقبل يوم التأسيس في فبراير، وفي رمضان قبل العيد بأيام. وبعد الصرف المبكر يأتي الصرف التالي بعد أكثر من ٣٠ يومًا.</li>\n<li><strong>الصيف:</strong> تُصرف المكافأة في الإجازة الصيفية أيضًا.</li>\n<li><strong>الطلاب الجدد:</strong> لا يُصرف لك شيء في شهرك الأول، ويأتي الشهران الأولان معًا في الشهر الثاني.</li>\n<li><strong>لم تصلك رسالة نصية؟</strong> التنبيهات لا تصل دائمًا. فاعرف الرصيد من الصراف الآلي، أو راجع مدفوعاتك في النظام الأكاديمي تحت <strong>شخصي</strong> ثم <strong>المكافآت</strong>.</li>\n<li><strong>رقم جوالك:</strong> تصل تنبيهات البطاقة ورموزها إلى رقم الجوال المسجل في حسابك الجامعي، ويجب أن يكون الرقم باسمك أنت. فإن غيّرت رقمك فحدّثه أولًا من أيقونة حساب المستخدم على iu.edu.sa، وانتظر بضعة أيام حتى يُحدَّث في البطاقة.</li>\n</ul>\n<h2>نقل المال إلى حسابك عبر تطبيق محفظة</h2>\n<p>هذه أسرع طريقة، ولا تحتاج فيها إلى صراف آلي. والخطوات أدناه لتطبيق برق، ويقبل الإنماء باي وurpay البطاقة بالطريقة نفسها.</p>\n<ol>\n<li>ثبّت تطبيق المحفظة وافتح فيه حسابًا باسمك.</li>\n<li>انتظر حتى تصل المكافأة إلى البطاقة. فالتطبيق لا يقبل البطاقة إلا وفيها مال.</li>\n<li>اختر إضافة رصيد من بطاقة، وأدخل رقم بطاقة المكافأة وتاريخ انتهائها ورمز التحقق (CVV)، ثم المبلغ.</li>\n<li>حين يسألك التطبيق عن مصدر دخلك، اختر <strong>مكافأة طالب</strong> أو <strong>راتب</strong>.</li>\n<li>حوّل من المحفظة إلى حسابك البنكي بالآيبان. وفي ٢٠٢٦ كان التحويل من برق إلى بنك سعودي فوريًا ومجانيًا. وبعض المحافظ الأخرى تأخذ رسومًا يسيرة على التحويل إلى بنك آخر.</li>\n</ol>\n<h2>استعمال الصراف الآلي</h2>\n<ul>\n<li>اسحب النقد من صراف آلي للراجحي برقمك السري.</li>\n<li>ولنقل المال بلا سحب نقدي، اختر التحويل في صراف آلي للراجحي وأرسله إلى حسابك برقم الحساب.</li>\n<li>وإرسال المال إلى بلدك من حسابك أو محفظتك في <a href=\"/ar/guides/sending-and-receiving-money\">إرسال المال إلى بلدك واستقباله في المدينة</a>.</li>\n</ul>\n<h2>إلى أين تذهب: شباك بطاقات المكافأة في الوحدة ٢٢</h2>\n<p>تُعالج مشكلات البطاقة في شباك المكافآت في الوحدة ٢٢، في الطابق الأرضي. ادخل من المدخل الرئيسي، وانعطف يسارًا عبر الباب الزجاجي، واقصد الشباك الذي في أقصى اليمين. والوحدة ٢٢ هي المبنى الثاني بعد كلية الدعوة وأصول الدين، في اتجاه مسجد محمد بن إبراهيم. اذهب صباحًا، فالمكتب يعمل من نحو ٨ صباحًا إلى ٢ بعد الظهر، ويُستحسن استلام البطاقات الجديدة قبل الظهر. وتُوجَّه الأسئلة عن الصرف نفسه أيضًا إلى قسم المكافآت في عمادة شؤون الطلاب.</p>\n<h2>المشكلات وحلولها</h2>\n<table><thead><tr><th>المشكلة</th><th>ما تفعله</th></tr></thead><tbody>\n<tr><td>لم تصل المكافأة حتى يوم ٢٦</td><td>راجع شاشة المكافآت. فإن لم تجدها فاذهب إلى شباك المكافآت في الوحدة ٢٢. والطالب الجديد لا يُصرف له في الشهر الأول، وبعد فصل الإجازة تعود المكافأة مع الصرف المعتاد التالي أو الذي بعده</td></tr>\n<tr><td>انتهت صلاحية البطاقة</td><td>المال محفوظ، لكن البطاقة لا تُستعمل. املأ نموذجًا في شباك الوحدة ٢٢. وتستغرق البطاقة الجديدة نحو أسبوعين، وينتقل الرصيد إليها. ولا يستطيع البنك استبدال البطاقة دون الجامعة</td></tr>\n<tr><td>نسيت الرقم السري، أو أُقفل</td><td>اطلب من شباك الوحدة ٢٢ إعادة تعيين الرقم السري أولًا. فإن لم ينجح ذلك طلبوا لك بطاقة جديدة</td></tr>\n<tr><td>ضاعت البطاقة أو سُرقت أو احتجزها صراف آلي</td><td>أبلغ شباك الوحدة ٢٢ فورًا لتُوقف البطاقة، واطلب بطاقة بديلة. وتستغرق نحو أسبوعين، وتُخصم رسوم البديلة من البطاقة، ولا يضيع شيء من المكافأة</td></tr>\n<tr><td>الصرف أقل من المعتاد</td><td>سلفة صندوق الطالب تُسدَّد من المكافأة كل شهر. انظر <a href=\"/ar/guides/university-housing-and-student-services\">غرفتك في السكن الجامعي وصندوق الطالب وتعليق الدراسة</a></td></tr>\n<tr><td>توقفت المكافأة</td><td>يوقفها فصل الإجازة، أو انتهاء مدة دراستك النظامية، أو ترك الدراسة. انظر <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة</a></td></tr>\n</tbody></table>\n<blockquote><p>نصيحة: صوّر وجه بطاقتك واحفظ الصورة في ألبوم خاص. وحين تذهب إلى شباك الوحدة ٢٢ فأحضر بطاقتك الجامعية أو هويتك. ولم يصل الصرف حتى بعد ذهابك إلى الشباك؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "gpa-warnings-and-dismissal": {
  "titleAr": "معدلك والإنذارات الأكاديمية والفصل الأكاديمي",
  "summaryAr": "كيف تحسب الجامعة الإسلامية معدلك من ٥ مع أمثلة محسوبة، وأين تراه، وأثر الرسوب في مقرر وإعادته عليه، والإنذارات الأكاديمية والفصل الأكاديمي، والفرصة الإضافية، ومرتبة الشرف، وكيف ترفع معدلًا منخفضًا.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. معدلك هو الذي يحدد حصولك على مرتبة الشرف، والمعدل المنخفض يجرّ الإنذارات، ثم الفصل في النهاية. ويبيّن هذا الدليل كيف يُحسب، وأين تراه، وما تفعله حين يبدأ في النزول.</p>\n<h2>التقديرات والنقاط</h2>\n<p>كل مقرر من ١٠٠، و٦٠ درجة النجاح. ولكل تقدير نقاط من ٥.</p>\n<table><thead><tr><th>التقدير</th><th>الدرجة</th><th>النقاط</th></tr></thead><tbody>\n<tr><td>A+</td><td>٩٥ إلى ١٠٠</td><td>٥٫٠٠</td></tr>\n<tr><td>A</td><td>٩٠ إلى ٩٤</td><td>٤٫٧٥</td></tr>\n<tr><td>B+</td><td>٨٥ إلى ٨٩</td><td>٤٫٥٠</td></tr>\n<tr><td>B</td><td>٨٠ إلى ٨٤</td><td>٤٫٠٠</td></tr>\n<tr><td>C+</td><td>٧٥ إلى ٧٩</td><td>٣٫٥٠</td></tr>\n<tr><td>C</td><td>٧٠ إلى ٧٤</td><td>٣٫٠٠</td></tr>\n<tr><td>D+</td><td>٦٥ إلى ٦٩</td><td>٢٫٥٠</td></tr>\n<tr><td>D</td><td>٦٠ إلى ٦٤</td><td>٢٫٠٠</td></tr>\n<tr><td>F</td><td>أقل من ٦٠</td><td>راسب</td></tr>\n</tbody></table>\n<ul>\n<li><strong>DN</strong> (ح): محروم من الاختبار النهائي بسبب الغياب. ويُحسب رسوبًا، وضرره على معدلك أشد من ضرر F.</li>\n<li><strong>W</strong> (ع): منسحب من المقرر. وليس رسوبًا، ولا يدخل في حساب معدلك.</li>\n</ul>\n<h2>كيف يُحسب المعدل</h2>\n<ol>\n<li>اضرب نقاط تقدير كل مقرر في عدد ساعاته المعتمدة.</li>\n<li>اجمع النواتج.</li>\n<li>اقسم المجموع على مجموع الساعات المعتمدة.</li>\n</ol>\n<p><strong>مثال لفصل واحد:</strong></p>\n<table><thead><tr><th>المقرر</th><th>الساعات</th><th>التقدير</th><th>النقاط × الساعات</th></tr></thead><tbody>\n<tr><td>المقرر ١</td><td>٣</td><td>A (٤٫٧٥)</td><td>١٤٫٢٥</td></tr>\n<tr><td>المقرر ٢</td><td>٢</td><td>B+ (٤٫٥٠)</td><td>٩٫٠٠</td></tr>\n<tr><td>المقرر ٣</td><td>٢</td><td>C (٣٫٠٠)</td><td>٦٫٠٠</td></tr>\n<tr><td><strong>المجموع</strong></td><td><strong>٧</strong></td><td></td><td><strong>٢٩٫٢٥</strong></td></tr>\n</tbody></table>\n<p>المعدل الفصلي: ٢٩٫٢٥ مقسومة على ٧ = <strong>٤٫١٨</strong>.</p>\n<p><strong>المعدل الفصلي</strong> يشمل فصلًا واحدًا. و<strong>المعدل التراكمي</strong> يشمل كل مقرر درسته، ويُحسب بالطريقة نفسها. والمعدل التراكمي هو المعتبر في الإنذارات ومرتبة الشرف والتخرج. وكلما زادت الساعات التي أنهيتها قلّ تأثير فصل واحد فيه.</p>\n<h2>أين تراه</h2>\n<ul>\n<li>لوحتك بعد الدخول، <strong>بياناتي الطلابية</strong>، تعرض معدلك الفصلي والتراكمي.</li>\n<li><strong>أكاديمي</strong>، ثم <strong>السجل الأكاديمي</strong>، يعرض كل مقرر بساعاته ونقاطه وتقديره، ومعدلك فصلًا فصلًا.</li>\n<li>تعرض الصفحة الرئيسية للنظام الأكاديمي <strong>عدد إنذارات المعدل</strong>.</li>\n<li>لا تظهر النتائج إلا بعد أن تُكمل تقييم المقررات. انظر <a href=\"/ar/guides/university-student-system\">استخدام نظام الطالب في الجامعة</a>.</li>\n</ul>\n<h2>الرسوب في مقرر وإعادته</h2>\n<ul>\n<li>يجب أن تنجح في كل مقرر في خطتك لتتخرج، فالمقرر الذي رسبت فيه تسجله مرة أخرى في فصل لاحق.</li>\n<li>فإذا نجحت فيه أُضيف التقدير الجديد إلى سجلك. ويبقى F أو DN في سجلك ويظل داخلًا في حساب معدلك، فالإعادة ترفع معدلك لكنها لا تمحو الرسوب.</li>\n<li>المقرر الذي حُرمت منه (DN) رسوب كغيره، فالحضور يحمي معدلك كما تحميه المذاكرة.</li>\n<li>الاختبار النهائي يُؤدّى مرة واحدة. والإعادة الوحيدة هي الاختبار البديل لعذر مقبول. انظر <a href=\"/ar/ask/failed-a-course\">رسبت في مقرر، فماذا يعني ذلك بالنسبة لي؟</a></li>\n</ul>\n<h2>الإنذارات الأكاديمية</h2>\n<ul>\n<li>إذا انتهى فصل ومعدلك التراكمي دون الحد الأدنى الذي تحدده الجامعة للتخرج، تلقيت <strong>إنذارًا أكاديميًا</strong>.</li>\n<li>يظهر عدد الإنذارات في الصفحة الرئيسية للنظام الأكاديمي. فراجعه بعد كل نتيجة.</li>\n<li><strong>ثلاثة فصول متتالية</strong> دون ذلك الحد تؤدي إلى الفصل الأكاديمي.</li>\n<li>الإنذار إشارة إلى أن تتحرك الآن، والقسم التالي يبيّن كيف.</li>\n</ul>\n<h2>الفصل الأكاديمي والفرصة الإضافية</h2>\n<p>تكون مفصولًا أكاديميًا في إحدى حالتين:</p>\n<ul>\n<li>إذا بقي معدلك التراكمي دون الحد الأدنى للتخرج ثلاثة فصول متتالية، أو</li>\n<li>إذا لم تُنهِ درجتك في المدة المحددة لها.</li>\n</ul>\n<p>لا يُحسب التأجيل من مدة دراستك، أما فصل الاعتذار فيُحسب. انظر <a href=\"/ar/guides/tajeel-and-itithaar\">أخذ فصل إجازة</a>.</p>\n<p><strong>الفرصة الإضافية</strong>: يستطيع الطالب المفصول أن يطلب فرصة إضافية واحدة.</p>\n<ol>\n<li>راقب فترتها في التقويم. وللفصل الثاني من ١٤٤٨ تمتد من <strong>١١ إلى ١٤ ديسمبر ٢٠٢٦</strong>.</li>\n<li>قدّم طلبك في النظام الأكاديمي خلال هذه المدة.</li>\n<li>وراجع أيضًا وكيل كليتك للشؤون التعليمية، فبإمكانه أن يدعم طلبك.</li>\n<li>راجع حالتك بعد انتهاء الفترة. فإذا عادت إلى «منتظم» سجّل مقررات الفصل.</li>\n</ol>\n<p>وفي حالة المعدل المنخفض لا تُمنح الفرصة الإضافية إلا إذا كان فصل واحد من ١٤ ساعة معتمدة كافيًا لرفع معدلك التراكمي إلى الحد الأدنى. ولا تُمدد مدة دراسة طلاب المنح بأكثر من نصف مدة الدرجة.</p>\n<h2>تقديرك العام</h2>\n<p>ويُذكر في سجلك الأكاديمي وشهادتك أيضًا التقدير العام، ويُستخرج من معدلك التراكمي. وهو ما تعنيه برامج الدراسات العليا وجهات العمل حين تقول «جيد جدًا» أو «جيد».</p>\n<table><thead><tr><th>التقدير العام</th><th>المعدل التراكمي من ٥</th></tr></thead><tbody>\n<tr><td>ممتاز</td><td>من ٤٫٥٠ إلى ٥٫٠٠</td></tr>\n<tr><td>جيد جدًا</td><td>من ٣٫٧٥ إلى أقل من ٤٫٥٠</td></tr>\n<tr><td>جيد</td><td>من ٢٫٧٥ إلى أقل من ٣٫٧٥</td></tr>\n<tr><td>مقبول</td><td>من ٢٫٠٠ إلى أقل من ٢٫٧٥</td></tr>\n</tbody></table>\n<p>والمعدل التراكمي الذي يقل عن ٢٫٠٠ دون تقدير النجاح اللازم للتخرج.</p>\n<h2>مرتبة الشرف</h2>\n<table><thead><tr><th>مرتبة الشرف</th><th>المعدل التراكمي</th></tr></thead><tbody>\n<tr><td>الأولى</td><td>من ٤٫٧٥ إلى ٥٫٠٠</td></tr>\n<tr><td>الثانية</td><td>من ٤٫٢٥ إلى أقل من ٤٫٧٥</td></tr>\n</tbody></table>\n<p>وتشترط كلتاهما أيضًا:</p>\n<ul>\n<li><strong>ألا ترسب في أي مقرر</strong> قط. فتقدير F أو DN واحد يمنع مرتبة الشرف، ولو نجحت في المقرر بعد إعادته.</li>\n<li>أن تنهي درجتك في المدة التي تحددها الجامعة لمرتبة الشرف.</li>\n<li>أن تدرس ٦٠٪ على الأقل من ساعاتك المعتمدة في الجامعة الإسلامية.</li>\n</ul>\n<p>تقدير W ليس رسوبًا، فالانسحاب من مقرر لا يحرمك مرتبة الشرف. فإن تعثرت في مقرر وكانت مرتبة الشرف تهمك، فالانسحاب قبل الموعد النهائي يحفظها لك.</p>\n<h2>رفع المعدل المنخفض</h2>\n<ul>\n<li><strong>أعد المقررات الراسبة مبكرًا.</strong> فكل مقرر تنجح فيه يضيف نقاطًا، والمقررات التي بعده تنتظره.</li>\n<li><strong>انسحب في الوقت المناسب.</strong> إن كنت متجهًا إلى الرسوب فتقدير W قبل الموعد النهائي يُبقي سجلك خاليًا من الرسوب. والقواعد في <a href=\"/ar/guides/registering-your-courses\">تسجيل مقرراتك</a>.</li>\n<li><strong>لا تبلغ حد الحرمان أبدًا.</strong> فتقدير DN أسوأ تقدير لمعدلك. وراجع شخصي، ثم الغياب، كل أسبوع.</li>\n<li><strong>احسبها بنفسك.</strong> لنفترض أن لديك ٦٠ ساعة بمعدل تراكمي ٢٫٦٠، أي ١٥٦ نقطة. ففصل من ٢٠ ساعة بمعدل ٤٫٠٠ يضيف ٨٠ نقطة، فيصير لديك ٢٣٦ نقطة على ٨٠ ساعة، أي <strong>٢٫٩٥</strong>.</li>\n<li><strong>اسأل مبكرًا.</strong> يستطيع مرشدك الأكاديمي ووكيل كليتك مساعدتك في تخطيط عبئك الدراسي قبل الإنذار الثالث.</li>\n</ul>\n<blockquote><p>نصيحة: وصلك إنذار، أو تخشى الفصل؟ كلّم وكيل كليتك فورًا. وما زلت متعثرًا؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "graduate-procedures": {
  "titleAr": "مغادرة المدينة نهائيًا: التخرج والخروج النهائي والشحن وبيع الأغراض وإغلاق الحسابات",
  "summaryAr": "كل ما تفعله حين تغادر نهائيًا، بالترتيب وعلى جدول زمني: شهادتك وغرفتك، وإخلاء الطرف والخروج النهائي بإقامة أو بهوية زائر، وتذكرة الجامعة، وشحن كتبك، وبيع الأثاث والسيارة، والحساب البنكي، والشرائح، وعربون شقتك وفواتيرها، وأوراق مدرسة أطفالك.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. مغادرة المدينة نهائيًا أكثر من تسليم غرفة. فهي أيضًا الخروج النهائي، وتذكرتك من الجامعة، والكتب التي تريد الاحتفاظ بها، والأثاث الذي لا تستطيع أخذه، وحسابك البنكي، وشريحتك، وشقتك وعربونها، وأوراق مدرسة أطفالك. وهذا الدليل يجمع كل ذلك في مكان واحد، بالترتيب الذي يلزم. يبدأ الخريجون من الأعلى. وإن كنت تغادر لسبب آخر، أو كنت أسرة لم تدرس قط، فتجاوز خطوات الجامعة وابدأ من <strong>مغادرة المملكة</strong>.</p>\n<h2>جدولك الزمني للمغادرة</h2>\n<table><thead><tr><th>متى</th><th>ما تفعله</th></tr></thead><tbody>\n<tr><td>قبل ثلاثة أشهر</td><td>تحقق من الاسم في شهادتك. أخبر مالك الشقة. اطلب من مدرسة الأطفال أوراق مغادرتهم. ابدأ بيع الأغراض الكبيرة وشحن أول صناديق الكتب.</td></tr>\n<tr><td>قبل شهر</td><td>ادفع كل مخالفة. بع السيارة أو انقلها. قرر ما يسافر معك وما يُشحن وما يذهب. اطبع مستنداتك الجامعية.</td></tr>\n<tr><td>قبل أسبوعين</td><td>سلّم غرفتك أو شقتك، واستلم عربونك، وسوِّ الكهرباء والماء، واستلم شهادتك، وصدّق مستنداتك.</td></tr>\n<tr><td>الأيام الأخيرة</td><td>إخلاء الطرف مؤكد، والتذكرة صادرة، والخروج النهائي صادر، والحساب البنكي مفرَّغ ومغلق، والشرائح الزائدة ملغاة، والصور الأخيرة ملتقطة.</td></tr>\n<tr><td>بعد أن تهبط</td><td>أبقِ رقمك السعودي فعّالًا لرموز التحقق حتى تُغلق كل الحسابات. تحقق أن شهادتك تظهر في التحقق الإلكتروني.</td></tr>\n</tbody></table>\n<h2>١. تحقق من بيانات شهادتك</h2>\n<p>تُطبع شهادة تخرجك باسمك وبياناتك كما هي في سجلات الجامعة تمامًا. راجعها في النظام الأكاديمي في فصلك الأخير، تحت <strong>إجراءات التخرج</strong>، وصحح أي اختلاف عن جوازك قبل الطباعة. وإضافة الاسم العربي الناقص بعد إصدار الوثيقة تعني أن تدفع رسوم بدل عنها. انظر <a href=\"/ar/ask/graduation-certificate-name-check\">كيف أتأكد أن اسمي صحيح في شهادة تخرجي؟</a></p>\n<p>وبعد اعتماد نتائجك النهائية تتغير حالتك في النظام الأكاديمي من <strong>منتظم</strong> إلى <strong>متخرج</strong>. وإخلاء طرفك واستلام شهادتك كلاهما ينتظر هذا التغيير، الذي يستغرق أحيانًا بضعة أسابيع بعد الاختبارات النهائية.</p>\n<h2>٢. نزّل مستنداتك واطبعها</h2>\n<p>في النظام الأكاديمي افتح <strong>شخصي</strong>، ثم <strong>المستندات الرسمية</strong>، ونزّل:</p>\n<ul>\n<li><strong>سجلك الأكاديمي</strong></li>\n<li><strong>إفادة السلوك</strong></li>\n<li><strong>إفادة التخرج</strong></li>\n</ul>\n<p>اطبع نسخة ملونة ونسختين بالأبيض والأسود من كل منها، واحتفظ بنسخ من جوازك وبطاقتك الجامعية وهوية الزائر أو الإقامة. فجاهزيتها توفر عليك رحلات إضافية.</p>\n<blockquote><p>نصيحة: إن لم ينزل شيء فاسمح بالنوافذ المنبثقة للموقع في إعدادات متصفحك وجرّب مرة أخرى في كروم على الحاسوب.</p></blockquote>\n<h2>٣. سلّم غرفتك (تسليم السكن)</h2>\n<p>مكتب الإسكان في عمادة شؤون الطلاب يتولى التسليم.</p>\n<ol>\n<li><strong>خذ استمارة التسليم</strong> من مكتب الإسكان. قل إنك متخرج وتريد تسليم غرفتك، وأعطهم رقمك الجامعي.</li>\n<li><strong>نظف الغرفة</strong> وتحقق من الأثاث. خمسة أشياء يجب أن تكون كلها موجودة: المرتبة، وهيكل السرير، والدولاب، والمكتب، والكرسي. ولا يجوز أن ينقص شيء أو يُبدَّل، وكل ناقص أو مبدَّل يُحمَّل عليك. والسجادة هي الشيء الوحيد الذي تستطيع تركه.</li>\n<li><strong>رتّب المعاينة</strong> مع مشرف مبناك، في مكتبه أو بالهاتف. يفحص الغرفة ويأخذ المفتاح ويوقع الاستمارة. <strong>احتفظ بالاستمارة الأصلية.</strong></li>\n<li><strong>عد إلى مكتب الإسكان</strong> صباح يوم العمل التالي لإخلاء الطرف النهائي. فيظهر النظام غرفتك مسلَّمة.</li>\n</ol>\n<p>تحدد الجامعة موعدًا يجب أن يُخلي الخريجون غرفهم قبله. وكان في ٢٠٢٦ يوم ٢٧ يونيو، بعد الاختبارات النهائية بنحو خمسة أسابيع. وكل ما يبقى بعد ذلك الموعد يُزال على مسؤوليتك، فرتّب تسليمك وتأشيرتك وتذكرتك على أساسه. وخريجو المعهد المنتقلون إلى إحدى الكليات يحتفظون بغرفهم طلابًا منتظمين.</p>\n<p>بطانيتك وملاءاتك لك تأخذها إلى بلدك. وكل ما اشتريته للغرفة سوى ذلك، من غلاية إلى رف كتب، يذهب معك أو إلى صديق أو إلى السوق: انظر <strong>أغراضك</strong> أدناه.</p>\n<h2>٤. أعد بطاقتك الجامعية وأخلِ طرفك</h2>\n<p>سلّم استمارة الغرفة الموقعة في مكتب الإسكان، وأعد بطاقتك الجامعية في مكتب البطاقة الجامعية. واحتفظ بنسخة أو ملف PDF للبطاقة أولًا. ثم أكمل إخلاء الطرف في النظام الأكاديمي، تحت <strong>أكاديمي</strong> ثم <strong>إخلاء الطرف</strong>. ويُفتح حين تظهر حالتك «متخرج»، ويعرض كل جهة يجب أن تخلي طرفك. ثم تؤكد إدارة السفر إخلاء طرفك في سجلات الجامعة، وبناءً عليه تصدر تذكرتك، وخروجك النهائي إن كنت تحمل إقامة. ولا يصدر شيء قبل ظهور إخلاء الطرف.</p>\n<h2>٥. استلم شهادتك وختم الجامعة</h2>\n<p>بعد أن تظهر حالتك «متخرج» احجز موعدًا للاستلام على <a href=\"https://services.iu.edu.sa/Appointment\">services.iu.edu.sa/Appointment</a>، بالدخول برقمك الجامعي. واستلم شهادتك من عمادة القبول والتسجيل في موعدك، ووقّع على استلامها. وإن لم تستطع الحضور فاملأ نموذج العمادة الرسمي لتفويض من يستلمها عنك، وأرسله عبر تواصل أولًا، وأعطِ نسخة مطبوعة منه لمن سيستلمها. انظر <a href=\"/ar/ask/degree-collection-and-verification\">هل يستطيع غيري استلام شهادتي؟</a></p>\n<p>ثم اطلب ختم الجامعة على النسخ بالأبيض والأسود من سجلك الأكاديمي وإفادة السلوك وإفادة التخرج، وعلى نسخة من شهادتك. فوزارة الخارجية لا تصدق إلا مستندات تحمل ختم الجامعة من قبل.</p>\n<h2>٦. صدّق مستنداتك: الوزارة ثم سفارتك</h2>\n<p>معظم السفارات لا تصدق شهادة سعودية قبل أن تصدقها وزارة الخارجية. والمستندات التي تُصدَّق عادة هي الشهادة وشهادة المعهد والسجل الأكاديمي وإفادة السلوك وإفادة التخرج.</p>\n<ol>\n<li>افتح خدمة التصديق في الوزارة على <a href=\"https://ratification.mofa.gov.sa/\">ratification.mofa.gov.sa</a> وادخل عبر نفاذ.</li>\n<li>ابدأ طلبًا جديدًا وأدخل كل مستند.</li>\n<li>ادفع رسوم كل مستند عبر الإنترنت، واحجز موعدًا في فرع الوزارة بالمدينة.</li>\n<li>اذهب إلى الفرع في موعدك بإيصال الدفع والنسخ المختومة.</li>\n</ol>\n<blockquote><p>نصيحة: ادفع فور الحجز. فالموعد غير المدفوع يُلغى.</p></blockquote>\n<p>والبريد السعودي يحمل المستندات أيضًا إلى وزارة الخارجية ويعيدها مصدقة، برسوم، فتوفر زيارة الفرع: اسأل في أي فرع للبريد السعودي.</p>\n<p><strong>أبوستيل أم سفارة؟</strong> السعودية عضو في اتفاقية لاهاي للأبوستيل منذ ديسمبر ٢٠٢٢. فإن كان بلدك عضوًا أيضًا (معظم أوروبا وبريطانيا وأمريكا وأستراليا والهند وباكستان وإندونيسيا وماليزيا وجنوب أفريقيا أعضاء) فأبوستيل من وزارة الخارجية هو كل ما تحتاجه مستنداتك ولا دور لسفارتك. فاطلب الأبوستيل لا ختم التصديق حين تقدّم الطلب.</p>\n<p>وإن لم يكن بلدك عضوًا فيطلب أيضًا تصديق المستندات في سفارته بالرياض أو قنصليته بجدة. وتختلف الشروط من بلد إلى بلد، فاقرأ موقع سفارتك أولًا. وخذ المستندات المصدقة من وزارة الخارجية ونسخًا من جوازك وبطاقتك الجامعية وهوية الزائر أو الإقامة، وسجّل عبر الإنترنت مسبقًا إن طلبت سفارتك ذلك. وافعل هذا قبل إخلاء الطرف والتذكرة، لأن وقتك في المملكة يقصر بعد صدور الخروج النهائي.</p>\n<h2>٧. بدل التخرج والبشت والهدايا</h2>\n<ul>\n<li><strong>بدل التخرج:</strong> يتقاضى طلاب المنحة الكاملة (الخارجية) بدل تخرج قدره مكافأة ثلاثة أشهر، لشحن كتبهم إلى بلدهم، بعد أن تؤكد الجامعة إخلاء طرفهم. ويصل إلى الحساب نفسه الذي تصل إليه مكافأتك، فأبقِ ذلك الحساب مفتوحًا حتى يصل. انظر <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة</a>.</li>\n<li><strong>الحفل:</strong> تقيم الجامعة حفل تخرج واحدًا في السنة، قرب نهاية الفصل الثاني (وكان في ٢٧ أبريل ٢٠٢٦). ويستلم الخريجون البشت والوشاح وبطاقات الدعوة قبله من عمادة القبول والتسجيل، في الدور الأرضي، في الأيام التي تعلنها الجامعة. ويُعطى كل خريج بطاقتي دعوة لأسرته. ومن يتخرج بين فصلين يحضر الحفل التالي.</li>\n<li><strong>البشت والهدايا:</strong> يُعطى خريجو البكالوريوس والماجستير والدكتوراه بشت التخرج (المشلح) وهدايا ككتب. وإن كنت قد عدت إلى بلدك فيستطيع أحد استلامها عنك: أرسل طلبًا عبر تواصل باسمك ورقم بطاقتك الجامعية وتاريخ تخرجك، والاسم الكامل ورقم البطاقة الجامعية لمن يستلم.</li>\n</ul>\n<h2>٨. مغادرة المملكة: الخروج النهائي بإقامة، أو بهوية زائر</h2>\n<p>طريقة مغادرتك تعتمد على ما تحمله.</p>\n<table><thead><tr><th>الموضوع</th><th>الإقامة</th><th>هوية الزائر (التأشيرة التعليمية)</th></tr></thead><tbody>\n<tr><td><strong>ما يصدر</strong></td><td>تأشيرة خروج نهائي. وهي مجانية، وصالحة ٦٠ يومًا من يوم إصدارها، وتحتاج ٣٠ يومًا على الأقل باقية في إقامتك، وتلغي الإقامة حين تعبر الحدود</td><td>لا شيء يصدر. تنتهي تأشيرتك التعليمية حين تغادر، فيجب أن تغادر قبل انتهائها</td></tr>\n<tr><td><strong>من يصدره</strong></td><td>إدارة السفر، بوصفها كفيلك، بعد ظهور إخلاء طرفك. أرسل طلبًا عبر تواصل إن لم يتحرك بعد أسبوع من إخلاء طرفك</td><td>اسأل إدارة السفر عبر تواصل عن إخلاء الطرف الذي تحتاجه منك، ثم احجز</td></tr>\n<tr><td><strong>أسرتك</strong></td><td>تصدر الخروج النهائي لمرافقيك بنفسك في أبشر: الخدمات، ثم الجوازات، ثم خدمات التأشيرات، ثم تأشيرة خروج نهائي. ويجب أن تكون إقاماتهم سارية ومخالفاتهم مدفوعة</td><td>الأسرة على تأشيرات الزيارة تغادر معك أو قبل انتهاء تأشيراتها</td></tr>\n<tr><td><strong>ما يمنعه</strong></td><td colspan=\"2\">المخالفات المرورية غير المدفوعة، وسيارة ما زالت مسجلة باسمك، ومرافق عليه مخالفة غير مدفوعة أو إقامته منتهية، وجواز قريب من الانتهاء. سوِّ هذه كلها أولًا</td></tr>\n<tr><td><strong>العودة</strong></td><td colspan=\"2\">تنتهي منحتك حين تتخرج، وقد تعهدت عند القبول بالعودة إلى بلدك. وتستطيع العودة لاحقًا بتأشيرة جديدة باسمك، كتأشيرة عمرة أو سياحة، والطلاب المقبولون في الدراسات العليا يصلون بتأشيرة تعليمية جديدة</td></tr>\n</tbody></table>\n<blockquote><p>ملاحظة: تبدأ الأيام الستون من يوم إصدار التأشيرة، لا من اليوم الذي تختار السفر فيه. فلا تدع التأشيرة تصدر قبل أن يثبت تاريخ تذكرتك وتُسوَّى أمور بنكك وشقتك وسيارتك. والمخالفة المسجلة بعد صدور التأشيرة يمكن أن توقفك في المطار، فراجع أبشر مرة أخرى قبل السفر بيوم.</p></blockquote>\n<h2>٩. تذكرتك إلى الوطن</h2>\n<ol>\n<li>أنهِ كل ما سبق أولًا، ومنه السفارة، قبل أن تحجز.</li>\n<li>تأكد أن الجامعة أكدت إخلاء طرفك. فتذاكر الخريجين لا تصدر إلا بعده.</li>\n<li>تصدر تذكرتك الأخيرة بأمر إركاب على اعتماد، إلى إحدى المدن التي تحددها الجامعة لبلدك. وتحقق أن اسمك في اعتماد يطابق جوازك حرفًا بحرف.</li>\n<li>أخبر وحدة التذاكر بالتاريخ الذي تستطيع السفر فيه حقًا. فتغيير التاريخ لاحقًا يكلفك فرق الأجرة، والتخلف عن الرحلة يُفقدك التذكرة.</li>\n<li>تستطيع ترقية درجة السفر على حسابك. وتذاكر أسرتك على حسابك.</li>\n</ol>\n<p>قواعد التذكرة (الصلاحية وتغيير التاريخ وعدم الاسترداد والأمتعة) في <a href=\"/ar/guides/etimad-account\">تذكرتك من الجامعة: اعتماد وأمر الإركاب والقواعد</a>.</p>\n<h2>١٠. حسابك البنكي</h2>\n<p>تغلق البنوك حسابات المقيمين عند الخروج النهائي، ويُجمَّد حساب هوية الزائر حين تنتهي الهوية. فيجب أن يتحرك المال قبل أن تغادر، لا بعده.</p>\n<ol>\n<li><strong>انتظر آخر المدفوعات:</strong> مكافأتك الأخيرة وبدل التخرج يصلان إلى هذا الحساب. راجع شاشة المكافآت في النظام الأكاديمي للمبالغ.</li>\n<li><strong>أرسل الرصيد إلى بلدك</strong> ما دام رقمك السعودي وأبشر يعملان، لأن التحويلات تحتاج رموزًا تصل إلى جوالك. وقارن المبلغ النهائي الذي تستلمه أسرتك لا السعر المعلن: انظر <a href=\"/ar/ask/send-money-home\">كيف أحوّل المال إلى بلدي من المدينة؟</a></li>\n<li><strong>ألغِ ما يُحمَّل على الحساب:</strong> الاشتراكات، وقسط السيارة، وعقد الإنترنت، وأي أمر دفع دائم.</li>\n<li><strong>أغلق الحساب في الفرع</strong> واطلب خطاب إغلاق. واحتفظ به مع أوراقك.</li>\n</ol>\n<blockquote><p>نصيحة: لا تترك في الحساب شيئًا ذا قيمة. فإخراج المال من حساب سعودي وأنت في الخارج يحتاج وكيلًا وأوراقًا وأسابيع.</p></blockquote>\n<h2>١١. جوالك وشرائحك</h2>\n<ol>\n<li><strong>انظر كل خط مسجل باسمك</strong> في «متصل» أو تطبيق هيئة الاتصالات، وألغِ ما لا تحتاجه عند شركته. فالخط المنسي يبقى في سجلك. والخطوات في <a href=\"/ar/guides/phone-sims-and-absher\">رقم جوالك والتحقق من الشرائح وأبشر</a>.</li>\n<li><strong>لا تعتمد على رقم سعودي بعد مغادرتك.</strong> فالشركات تعدّ المغادرة النهائية سببًا لإلغاء الخط، والرقم الملغى يفقد رصيده ويذهب إلى غيرك. فأنهِ كل ما يحتاج رمزًا أولًا: تحويلات البنك، ونسخة الخروج النهائي، وسجلاتك في أبشر. وإن أبقيت خطًا واحدًا فأبقه مشحونًا وعلى التجوال، وانقل بنكك إلى الموافقة من التطبيق قبل أن تغادر إن كان بنكك يتيحها.</li>\n<li><strong>احفظ ما يعيش على الرقم:</strong> صدّر محادثات واتساب وأخبر مجموعاتك برقمك الجديد قبل أن يموت الرقم السعودي.</li>\n</ol>\n<h2>١٢. شقتك: التسليم والعربون والكهرباء والماء</h2>\n<p>إن كنت مستأجرًا في المدينة فعقدك يحدد الإشعار الذي عليك تقديمه. ومعظم العقود لسنة، والخروج المبكر يحتاج موافقة المالك، فأخبر المالك كتابة بأبكر ما تستطيع.</p>\n<ol>\n<li><strong>قدّم الإشعار</strong> بالطريقة التي ينص عليها عقدك. وعقد إيجار الذي يتجدد تلقائيًا يحتاج إشعارًا كتابيًا قبل ٦٠ يومًا. والمغادرة قبل تاريخ الانتهاء تحتاج اتفاق الطرفين: يبدأ أحدكما الإنهاء في إيجار ويوافق الآخر، وكثير من العقود تفرض أجرة شهر أو شهرين على الخروج المبكر، فاقرأ ذلك البند أولًا.</li>\n<li><strong>التقط صورًا مؤرخة</strong> لكل غرفة يوم التسليم، والعدادات في الصورة.</li>\n<li><strong>وقّع التسليم</strong> مع المالك أو الوسيط، واملأ نموذج الإخلاء في إيجار خلال سبعة أيام من تاريخ الانتهاء. ويُفرج عن عربونك، الذي يحتفظ به إيجار في حسابه، حين يوقع الطرفان. ولا يُخصم إلا ضرر موثق سببته أنت، لا البلى المعتاد.</li>\n<li><strong>سوِّ الكهرباء:</strong> ادفع آخر فاتورة في تطبيق الطاقة السعودية وأزل نفسك من العداد تحت «إدارة الحساب»، لتذهب الفواتير اللاحقة إلى المالك.</li>\n<li><strong>سوِّ الماء:</strong> ادفع آخر فاتورة في تطبيق شركة المياه الوطنية. وعداد العقار المستأجر يعود إلى اسم المالك حين ينتهي العقد.</li>\n<li><strong>أعد جهاز التوجيه</strong> وأنهِ عقد إنترنت البيت مع الشركة، وإلا استمر الرسم الشهري.</li>\n</ol>\n<p>وإن حُجز شيء بلا سبب فافتح نزاعًا إيجاريًا من لوحتك في إيجار، أو اتصل بإيجار على 199011. فلا شيء في إيجار يعتمد على حسن نية المالك حين يُملأ العقد ونموذج الإخلاء كما ينبغي. انظر <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a>.</p>\n<h2>١٣. أغراضك: بع وأعطِ واشحن</h2>\n<p>قرر مبكرًا، فالأسبوع الأخير للأوراق لا لبيع ثلاجة.</p>\n<h3>بع أو أعطِ</h3>\n<ul>\n<li><strong>أين تبيع:</strong> حراج (يأخذ ١٪ من البائع على ما يُباع عبر الموقع)، ولوحات الإعلانات ومجموعات السكن وكليتك، ومحلات الأثاث المستعمل في آخر شارع الإمام البخاري، التي تشتري كما تبيع. والطلاب الجدد يصلون كل أغسطس ويريدون ما تبيعه بالضبط. واقبض بتحويل تراه يصل قبل أن يخرج الغرض من الشقة.</li>\n<li><strong>سعّر ليُباع.</strong> حتى أواخر ٢٠٢٦ يُباع طقم الكنب أو الغسالة المستعملة ببضع مئات من الريالات، والمرتبة المفردة بأقل من مئة، والمشترون يتوقعون أن يستلموا بأنفسهم. وسيارة نقل صغيرة، توقفها على الطريق أو تحجزها بالهاتف، تنقل مرتبة أو ثلاجة عبر المدينة ببضع عشرات من الريالات.</li>\n<li><strong>أعطِ الباقي.</strong> جمعيات خيرية في المدينة تجمع الأثاث والأجهزة الصالحة، والطالب الجديد في سكنك يسعد بمصباح مكتبك.</li>\n</ul>\n<h3>سيارتك</h3>\n<p>السيارة المسجلة باسمك تمنع خروجك النهائي، فبعها أو انقلها أولًا.</p>\n<ol>\n<li>ادفع كل مخالفة على السيارة وعليك، وأبقِ الاستمارة والفحص الدوري ساريين.</li>\n<li>ابدأ البيع في أبشر تحت خدمات المركبات، بإدخال رقم هوية المشتري وتاريخ ميلاده والسعر وحسابك البنكي.</li>\n<li>يؤمّن المشتري السيارة باسمه، ويقبل البيع في أبشر الخاص به، ويدفع. وحتى نوفمبر ٢٠٢٦ على النقل رسوم حكومية ١٥٠ ريالًا ورسوم أبشر ٢٣٠ ريالًا، يدفعها المشتري.</li>\n<li>سلّم السيارة، ويؤكد المشتري الاستلام في أبشر، فتخرج السيارة من اسمك. وتحقق أنها زالت من قائمة مركباتك قبل أن تطلب الخروج النهائي.</li>\n</ol>\n<h3>اشحن كتبك</h3>\n<p>الكتب أثقل ما يملكه الطالب، وبدل التخرج موجود لهذا بالذات. قارن هذه الطرق، وزن صناديقك قبل أن تختار.</p>\n<table><thead><tr><th>الطريقة</th><th>تناسب</th><th>ما تعرفه</th></tr></thead><tbody>\n<tr><td>أمتعتك المشحونة</td><td>حتى حقيبتين على تذكرة الجامعة</td><td>كثيرًا ما تكون الأرخص لأول ٤٠ إلى ٥٠ كغ. وشركات الطيران العاملة من المدينة تسمح بنحو ٢٣ كغ للحقيبة في الدرجة الاقتصادية في أكثر فئات التذاكر، والحقيبة بين ٢٣ و٣٢ كغ تُدفع عنها رسوم وزن زائد بالقطعة أو بالكيلو، ولا يُقبل في عنبر الطائرة ما يزيد على ٣٢ كغ. اشترِ الحقيبة الإضافية من شركة الطيران عبر الإنترنت قبل الرحلة لا عند الكاونتر</td></tr>\n<tr><td>البريد السعودي (سبل)</td><td>صناديق حتى ٣٠ كغ</td><td>الاقتصادي يُسلَّم إلى أقرب مكتب بريد للمستلم، والسريع والشحن البحري إلى الباب. ويُسعَّر بالوزن والبلد في حاسبة الأسعار لدى سبل. وحتى ٢٠٢٥ يكلف طرد سريع من ٣٠ كغ من أقل من ٣٠٠ ريال إلى جنوب آسيا إلى نحو ٧٥٠ ريالًا إلى أوروبا وأمريكا الشمالية. وخدمة العملاء 19992</td></tr>\n<tr><td>شركات الشحن السريع</td><td>أسرع، ومتتبَّع، وبأي وزن</td><td>أرامكس ودي إتش إل وفيديكس وسمسا ويو بي إس كلها تشحن من المدينة. اطلب من كل منها عرض سعر بالوزن، واسأل عن سعر للكتب أو للطلاب</td></tr>\n<tr><td>الشحن البحري</td><td>صناديق كثيرة إلى أفريقيا أو آسيا</td><td>مكاتب الشحن في المدينة تشحن بالصندوق أو بالمتر المكعب. بطيء، لكنه أرخص بكثير للكيلو لمكتبة كاملة</td></tr>\n</tbody></table>\n<p>احزم الكتب في صناديق صغيرة مزدوجة الجدار من ٢٠ إلى ٢٥ كغ، لأن صندوق كتب من ٣٠ كغ ينشق ويؤذي من يحمله. ضع الأثقل مسطحًا في الأسفل، واملأ الفراغات بالملابس، وألصق كل درز، واكتب اسمك وجوالك والوجهة على جانبين وداخل الغطاء. وتحاسب شركات الشحن على الأكبر من الوزن الحقيقي والوزن الحجمي (الطول في العرض في الارتفاع بالسنتيمتر مقسومًا على ٥٬٠٠٠)، فالصندوق الكبير نصف الممتلئ يكلف كما يكلف الممتلئ. واكتب قائمة بمحتويات كل صندوق بقيمة صادقة: تُدوَّن في نموذج الجمارك وهي مطالبتك إن فُقد صندوق. والكتب المطبوعة لا رسوم جمركية عليها في معظم البلدان، ومنها بريطانيا وأمريكا، وفي الحرم الجامعي مكتب للسفر والشحن يعرض أسعارًا للطلاب. والعناوين والجمارك وكل شركات الشحن في <a href=\"/ar/guides/shipping-and-receiving-parcels\">إرسال الطرود واستقبالها في المدينة</a>.</p>\n<h2>١٤. أوراق مدرسة أطفالك</h2>\n<ol>\n<li>اطلب من المدرسة شهادة انتقال وتقارير كل سنة، وسوِّ أي رسوم أولًا، لأن المدارس لا تسلّم الأوراق إلا لحساب خالٍ من المستحقات.</li>\n<li>إن كانت المدرسة التالية في بلد آخر فاسألها بالضبط أي أختام تحتاج. فتصديق أوراق المدرسة من وزارة التعليم يأخذ نحو شهر، فابدأ قبل مغادرتك بثلاثة أشهر.</li>\n<li>نزّل سجل تطعيم الأطفال من «صحتي» واطلب من العيادة أي سجلات طبية تريد الاحتفاظ بها.</li>\n</ol>\n<h2>أسبوعك الأخير</h2>\n<ol>\n<li>إخلاء الطرف مؤكد في سجلات الجامعة، والخروج النهائي صادر (الإقامة) أو إخلاء طرف إدارة السفر منجز (هوية الزائر).</li>\n<li>التذكرة بيدك، والاسم يطابق الجواز.</li>\n<li>الحساب البنكي مفرَّغ ومغلق، وخطاب الإغلاق محفوظ.</li>\n<li>الشقة مسلَّمة، والعربون مسترد، والكهرباء والماء مدفوعان، وجهاز التوجيه معاد.</li>\n<li>السيارة خارج اسمك، والمخالفات صفر في أبشر.</li>\n<li>الشرائح الزائدة ملغاة، وخط واحد باقٍ.</li>\n<li>الشهادة والسجل والنسخ المصدقة واستمارة الغرفة وخطاب الإغلاق كلها في حقيبة يدك، وصورة لكل منها على جوالك.</li>\n<li>الصناديق مشحونة، والإيصالات محفوظة.</li>\n</ol>\n<h2>بعد أن تغادر</h2>\n<ul>\n<li>يتعهد طلاب المنحة عند قبولهم بالعودة إلى بلدهم عند التخرج. ولا تستطيع البقاء في المملكة على المنحة بعد انتهاء دراستك.</li>\n<li>يستطيع أصحاب العمل والجامعات الأخرى التحقق من شهادتك في خدمة التحقق من وثائق التخرج في الجامعة. انظر <a href=\"/ar/ask/degree-collection-and-verification\">هل يستطيع غيري استلام شهادتي، وكيف يتحقق صاحب العمل منها؟</a></li>\n<li>يبقى حسابك في أبشر لك. احتفظ بكلمة مروره ورقم الجوال الذي يستعمله، فأنت تحتاجه إن عدت يومًا.</li>\n<li>زر مشايخك قبل الأسبوع الأخير، واطلب ممن درّسوك تزكية، واحتفظ ببيانات الاتصال بمشايخك ومكتب كليتك وأصدقائك. فدعاء الطالب لشيخه، ودعاء الشيخ لطالبه، لا يتوقف عند الحدود.</li>\n<li>زر المسجد النبوي زيارة أخيرة بوقت كافٍ، وسلّم عند القبر، وصلِّ في قباء، وزر البقيع.</li>\n</ul>\n<p>وفّق الله كل خريج.</p>\n<blockquote><p>نصيحة: تعثرت في خطوة؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "graduating-from-mahad": {
  "titleAr": "الانتقال من المعهد إلى الكلية",
  "summaryAr": "ثلاثة أمور تنجزها حين تُتمّ المعهد: تختار كليتك، وتستخرج بطاقتك الجامعية الجديدة، وتحتفظ بغرفتك.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. المعهد (معهد تعليم اللغة العربية) يُعدّك للدراسة في كليتك، ومدته سنتان على الأكثر بحسب المستوى الذي تُلحق به. وحين تُتمّه تنتظرك ثلاثة أمور: أمر قبل الإجازة، وأمران بعدها.</p>\n<h2>١. اختر كليتك (قبل الإجازة)</h2>\n<ul>\n<li>قرب نهاية فصلك الأخير في المعهد، ادخل إلى <a href=\"https://alisc.iu.edu.sa/\">alisc.iu.edu.sa</a> ورتّب رغباتك في الكليات: الأولى والثانية والثالثة.</li>\n<li>يعلن المعهد آخر موعد لذلك، فلا تفوّته.</li>\n<li>اختر بعناية، فطلاب المنح لا يستطيعون التحويل إلى كلية أخرى بعد توجيههم إلى كلياتهم.</li>\n</ul>\n<blockquote><p>نصيحة: إن واجهتك مشكلة في الصفحة فسجّل الدخول أولًا إلى نظام الجامعة على sso.iu.edu.sa، ثم افتح الرابط. واستخدم متصفح كروم على الحاسب، أو وضع سطح المكتب في متصفح جوالك.</p></blockquote>\n<h2>٢. استخرج بطاقتك الجامعية الجديدة (بعد الإجازة)</h2>\n<p>يصدر لك رقم جامعي جديد للكلية، فاستخدمه بعد ذلك في كل مكان. وخذ ما يلي إلى مكتب البطاقة الجامعية:</p>\n<ul>\n<li>بطاقتك الجامعية القديمة</li>\n<li>صورة شخصية بمقاس صورة الجواز</li>\n<li>رقم هوية الزائر أو رقم إقامتك</li>\n<li>رقمك الجامعي الجديد</li>\n</ul>\n<h2>٣. احتفظ بغرفتك (بعد الإجازة)</h2>\n<p>يُظهرك نظام الجامعة الآن خريجًا من المعهد، فأثبت أنك ما زلت تسكن غرفتك.</p>\n<ol>\n<li>اذهب إلى إدارة السكن وخذ الورقة التي تثبت الغرفة التي تسكنها. وهي الورقة نفسها التي أُعطيتها عند وصولك أول مرة.</li>\n<li>اذهب إلى مشرف مبناك وتحقق من أن سجلاته تتضمن رقم هوية الزائر أو رقم إقامتك، ورقمك الجامعي <strong>الجديد</strong>.</li>\n</ol>\n<h2>تحقق أيضًا</h2>\n<ul>\n<li>تستمر مكافأتك بعد انتقالك إلى الكلية. فتحقق في النظام الأكاديمي، تحت «شخصي» ثم «المكافآت»، من أن الدفعة القادمة ظاهرة وأن بطاقة مكافأتك ما زالت فعّالة. انظر <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة</a>.</li>\n<li>تجد جدولك الدراسي الجديد في النظام الأكاديمي، من «التسجيل الإلكتروني» ثم «المقررات المسجلة».</li>\n<li>وضوابط التأجيل والاعتذار مشروحة في <a href=\"/ar/guides/tajeel-and-itithaar\">أخذ فصل إجازة</a>.</li>\n</ul>\n<blockquote><p>نصيحة: هل تعثرت في خطوة؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "hajj-as-a-student": {
  "titleAr": "الحج من المدينة طالبًا أو مقيمًا",
  "summaryAr": "كيف يسجل الطلاب والأسر المقيمون في المدينة للحج في نسك: من يستطيع التقديم، والإقامة وهوية الزائر جنبًا إلى جنب، والباقات والدفع، وما تجهزه، وجدول موسم ١٤٤٨ حول الاختبارات، وعقوبات الحج بلا تصريح.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. الحج من داخل المملكة يُحجز في نسك فقط، منصة وزارة الحج والعمرة الرسمية، مع شركة حج مرخصة مدرجة فيها. ويغطي هذا الدليل الإجراء الرسمي: من يستطيع التسجيل، وما تجهزه، وكيف يجري الموسم، وما يحدث لمن يحج بلا تصريح. وحج ١٤٤٨ في ٨ إلى ١٣ ذي الحجة، أي ١٤ إلى ١٩ مايو ٢٠٢٧، ويوم عرفة السبت ١٥ مايو.</p>\n<h2>من يستطيع التسجيل</h2>\n<p>حج الداخل متاح للمواطنين وللمقيمين الذين يحملون إقامة سارية. ويجب ألا يقل عمر المتقدم عن ١٥ سنة بالتقويم الميلادي وأن يستوفي الشروط الصحية، وأن تظل إقامة المقيم سارية حتى نهاية ذي الحجة. وحين تسجل يتحقق نسك من سجلك في الأنظمة الوطنية، ومنها هل حججت من قبل.</p>\n<ul>\n<li><strong>الحجة الأولى أولًا.</strong> من لم يحج قط يحجز أولًا. ومن حج يسجل في مرحلة لاحقة، وإن بقيت أماكن فقط.</li>\n<li><strong>الإقامات الأقدم أولًا.</strong> تُعطى الأولوية للمقيمين الذين صدرت إقامتهم قبل أكثر من سنة.</li>\n<li><strong>لا تأشيرات زيارة.</strong> لا تسمح أي تأشيرة زيارة، ومنها التأشيرة السياحية الإلكترونية، بالحج.</li>\n</ul>\n<table><thead><tr><th>الموضوع</th><th>الإقامة</th><th>هوية الزائر (التأشيرة التعليمية)</th><th>الأسرة على تأشيرة زيارة</th></tr></thead><tbody>\n<tr><td><strong>حج الداخل في نسك</strong></td><td>نعم، بإقامة سارية حتى نهاية ذي الحجة</td><td>تحقق من أهليتك في نسك حين يفتح التسجيل، واسأل الجامعة عبر تواصل قبل أن تدفع شيئًا</td><td>لا</td></tr>\n<tr><td><strong>الأولوية</strong></td><td>أعلى حين تتجاوز إقامتك سنة، وللحجة الأولى</td><td>تظهر في نسك إن كنت مؤهلًا</td><td>لا ينطبق</td></tr>\n<tr><td><strong>الزوجة والأبناء في الحجز نفسه</strong></td><td>نعم، إن حمل كل منهم إقامة سارية</td><td>أفراد الأسرة المؤهلون بأنفسهم فقط</td><td>لا</td></tr>\n<tr><td><strong>مكة في أشهر الحج</strong></td><td>الدخول بتصريح حج أو تصريح دخول موسمي فقط</td><td>القاعدة نفسها</td><td>يجب البقاء خارج مكة والمشاعر من ١ ذي القعدة إلى ١٤ ذي الحجة</td></tr>\n</tbody></table>\n<p>وقواعد هوية الزائر عمومًا في <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a>.</p>\n<h2>الباقات والأسعار</h2>\n<ul>\n<li><strong>عبر نسك فقط.</strong> كل باقة داخلية تبيعها شركة مرخصة وتُحجز في تطبيق نسك أو على <a href=\"https://www.nusuk.sa/\">nusuk.sa</a>. و«الحملة» التي تُباع بالهاتف أو عبر وسائل التواصل أو بالكلام خارج نسك لا تعطيك تصريحًا.</li>\n<li><strong>الفئات.</strong> تحدد الوزارة كل موسم عددًا قليلًا من فئات الباقات. وتختلف في مخيمات منى وعرفات والمسافة إلى الجمرات والخدمات المشمولة، من فئة اقتصادية إلى مخيمات مطورة بخدمات أكثر.</li>\n<li><strong>الأسعار.</strong> تُنشر الأسعار في نسك حين يفتح حجز الباقات، شاملة ضريبة القيمة المضافة، وتتغير من موسم إلى موسم. وتبيّن كل باقة ما تشمله، فتحقق هل النقل من المدينة إلى مكة جزء منها. وكثيرًا ما لا يكون.</li>\n<li><strong>الدفع.</strong> يصدر الحجز فاتورة سداد تدفعها في تطبيق بنكك خلال المدة المبينة. والحجز غير المدفوع يُلغى. وفي ١٤٤٧ كانت المهلة ٧٢ ساعة، وخُفضت إلى ٦ ساعات في الأيام الأخيرة قبل الحج.</li>\n<li><strong>الإلغاء.</strong> الإلغاء المبكر، قبل صدور التصريح، لا يكلف شيئًا. وقرب الحج لا يُسترد شيء. ويبيّن نسك القاعدة في كل مرحلة، فاقرأها قبل أن تدفع.</li>\n</ul>\n<h2>ما تحتاجه</h2>\n<ol>\n<li><strong>إقامتك</strong>، سارية حتى نهاية ذي الحجة ١٤٤٨ (٥ يونيو ٢٠٢٧). فإن انتهت قبل ذلك فجددها أولًا. وبهوية الزائر تحقق من أهليتك في نسك ومع الجامعة قبل أن تمضي في الإجراء.</li>\n<li><strong>حساب في نسك</strong> باسمك، برقم الجوال المسجل لك في أبشر.</li>\n<li><strong>التطعيمات:</strong> الحمى الشوكية (ACWY) والإنفلونزا الموسمية، في مركز رعاية صحية أولية قبل أن تحجز. ونسك يتحقق منها.</li>\n<li><strong>بيانات أسرتك</strong> إن كانوا معك: رقم إقامة كل فرد وتاريخ ميلاده وصلته بك. ويجب أن تظهر الصلات في أبشر من قبل، فأضف زوجتك وأبناءك فيه أولًا.</li>\n<li><strong>ثمن الباقة كاملًا</strong>، جاهزًا للدفع بسداد.</li>\n</ol>\n<h2>الأخوات والمحرم</h2>\n<p>المرأة المسافرة مع زوجها أو محرم آخر تضيفه مرافقًا في الحجز نفسه، مع الشركة نفسها والباقة نفسها، ويتحقق نسك من الصلة في أبشر. وإن كان المحرم قد حج من قبل فيعرض نسك طلب استثناء للمحرم ليستطيع مرافقتها. واسأل الشركة عن أي ترتيب آخر قبل أن تدفع.</p>\n<h2>موسم ١٤٤٨ خطوة خطوة</h2>\n<p>تعلن الوزارة مواعيد كل موسم في نسك. وفي ١٤٤٧ فُتح التسجيل في ٦ رمضان، وحجز الباقات في ١٥ رمضان، وكانت الأولوية لمن لم يحج حتى نهاية شوال، ومن حج من قبل سجل من ١ ذي القعدة. ولـ ١٤٤٨ خطط حول هذه المواعيد:</p>\n<ol>\n<li><strong>من الآن إلى يناير ٢٠٢٧:</strong> جدد إقامتك إن كانت تنتهي قبل يونيو، وأضف أسرتك في أبشر، وخذ التطعيمات.</li>\n<li><strong>من بداية رمضان (٨ فبراير ٢٠٢٧):</strong> راقب نسك للتسجيل واحجز فور فتح الحجز. فأماكن الحجة الأولى تنفد أولًا.</li>\n<li><strong>أواخر شوال (أوائل أبريل ٢٠٢٧):</strong> دخول مكة لمن لا يسكنها يحتاج تصريحًا، ومن ١ ذي القعدة (٨ أبريل ٢٠٢٧) تتوقف تصاريح العمرة حتى ما بعد الحج. فأدِّ أي عمرة تنويها قبل ذلك. انظر <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء</a>.</li>\n<li><strong>٢٥ أبريل إلى ١٠ مايو ٢٠٢٧:</strong> اختبارات الفصل الثاني. راجع تاريخ بدء باقتك مع جدول اختباراتك قبل أن تحجز.</li>\n<li><strong>١١ إلى ٢٢ مايو ٢٠٢٧:</strong> إجازة عيد الأضحى، وتغطي أيام الحج. وتُستأنف الدراسة الأحد ٢٣ مايو.</li>\n</ol>\n<p>وكل مواعيد الجامعة في <a href=\"/ar/guides/university-calendar-1448\">التقويم الجامعي</a>.</p>\n<h2>الحج بلا تصريح</h2>\n<p>تطبق وزارة الداخلية قاعدة التصريح كل موسم، من ١ ذي القعدة إلى ١٤ ذي الحجة.</p>\n<ul>\n<li>كل من يُضبط يحج أو يحاول الحج بلا تصريح يُغرَّم حتى ٢٠٬٠٠٠ ريال.</li>\n<li>والمقيمون المضبوطون يُرحَّلون ويُمنعون من دخول المملكة عشر سنوات. وهذا يعني للطالب نهاية دراسته.</li>\n<li>وحاملو تأشيرة الزيارة الذين يدخلون مكة أو المشاعر أو يبقون فيها في تلك الأسابيع يُغرَّمون.</li>\n<li>وكل من ينقل أو يؤوي أو يخفي أو يستخرج تأشيرة لمن لا تصريح له يُغرَّم حتى ١٠٠٬٠٠٠ ريال عن كل شخص.</li>\n<li>ويمكن الإبلاغ عن المخالفات على 911 في مكة والمدينة والرياض والشرقية، وعلى 999 في بقية المناطق.</li>\n</ul>\n<blockquote><p>نصيحة: لست متأكدًا هل تستطيع التسجيل هذه السنة، أو أي جهة تسأل؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "haramain-train-and-city-buses": {
  "titleAr": "قطار الحرمين وحافلات المدينة",
  "summaryAr": "حجز القطار السريع إلى مكة وجدة، والأجور والأمتعة والتذاكر، وركوب حافلات المدينة بتطبيق حافلات المدينة.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. خدمتان عامتان تغطيان معظم المشاوير: قطار الحرمين السريع إلى مكة وجدة، وشبكة حافلات المدينة داخل المدينة.</p>\n<h2>قطار الحرمين</h2>\n<p>يربط القطار المدينة ومدينة الملك عبدالله الاقتصادية وجدة (ومنها مطار الملك عبدالعزيز) ومكة. ومكة على بُعد نحو ساعتين وعشرين دقيقة بالقطار المباشر. ومحطة المدينة على بُعد نحو ٩ كيلومترات من المسجد النبوي.</p>\n<h3>الحجز</h3>\n<ol>\n<li>احجز على <a href=\"https://sar.hhr.sa/\">sar.hhr.sa</a>، أو في تطبيق قطار الحرمين الرسمي، أو في تطبيق نسك.</li>\n<li>أدخل كل راكب بالهوية نفسها التي سيحملها يوم السفر: جواز أو إقامة أو هوية سعودية.</li>\n<li>اختر الدرجة الاقتصادية أو درجة الأعمال. وتتحرك الأجور مع الطلب، فالمقعد نفسه يكلف أكثر قرب الموعد وفي الأسابيع المزدحمة.</li>\n<li>تحقق من السعر النهائي. فالأسعار المعروضة أجورًا أساسية تُضاف إليها ضريبة القيمة المضافة ١٥٪ عند الدفع.</li>\n<li>احتفظ بالتذكرة الإلكترونية في جوالك. يتحقق الموظفون منها مع هويتك عند البوابة.</li>\n</ol>\n<ul>\n<li><strong>الأطفال</strong> لهم خصم ٥٠٪ في الدرجة الاقتصادية و٤٠٪ في درجة الأعمال. والرضيع في حجر أحد والديه يدفع ١٠٪ من الأجرة. وتعرض صفحة الحجز سعر كل راكب.</li>\n<li><strong>الأجور الأساسية:</strong> من المدينة إلى مكة من ١٦٢ ريالًا في الاقتصادية و٤٥٥ ريالًا في الأعمال، ومن المدينة إلى جدة من ١٣٥ ريالًا في الاقتصادية و٣٧٥ ريالًا في الأعمال، قبل الضريبة.</li>\n<li><strong>التغيير والاسترداد:</strong> التذاكر المشتراة عبر الإنترنت يمكن تغييرها أو استردادها وفق قواعد الأجرة. أما المشتراة من شباك المحطة أو الجهاز فلا.</li>\n<li><strong>خدمة العملاء:</strong> 920004433.</li>\n</ul>\n<blockquote><p>نصيحة: احجز مبكرًا لرمضان وإجازات العيدين والجمعة وإجازات الجامعة. فتلك القطارات تنفد وترتفع أجورها.</p></blockquote>\n<h3>الأمتعة</h3>\n<ul>\n<li>لكل راكب حقيبة واحدة لا يزيد وزنها على ٢٥ كيلوغرامًا ولا مقاسها على ٦٥ × ٥٥ × ٣٥ سم، وحقيبة يد صغيرة.</li>\n<li>الحقائب الزائدة غير مسموح بها في القطار. ومكاتب البريد السعودي في المحطات تستطيع إرسالها.</li>\n<li>تُفحص كل الحقائب قبل الركوب، فاحضر في وقت كافٍ.</li>\n</ul>\n<h3>الذهاب للعمرة</h3>\n<p>ميقات أهل المدينة ذو الحليفة (أبيار علي). وكثير من الناس يذهبون إلى مسجد ذي الحليفة أولًا، ويحرمون هناك، ثم يأخذون سيارة أجرة إلى المحطة. واحجز تصريح العمرة في نسك قبل السفر. انظر <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء</a>.</p>\n<h2>حافلات المدينة</h2>\n<ul>\n<li><strong>الأجرة:</strong> ٣٫٤٥ ريالات للرحلة على خطوط المدينة. ولخط المطار (٤٠٠) أجرته الخاصة، تظهر في تطبيق حافلات المدينة. وكل تذكرة لحافلة واحدة، فتبديل الحافلة يعني أجرة جديدة.</li>\n<li><strong>لا نقد في الحافلة.</strong> ادفع بمدى أو فيزا أو ماستركارد، أو أبل باي أو محفظة جوال أخرى، أو البطاقة الافتراضية في تطبيق حافلات المدينة، أو بطاقة حافلات بلاستيكية.</li>\n<li><strong>الاشتراكات في التطبيق:</strong> ١٠ رحلات في اليوم بعشرة ريالات، و٣٥ رحلة في الأسبوع بستين ريالًا، و١٧٥ رحلة في الشهر بمئتين وأربعين ريالًا.</li>\n<li><strong>استرداد المحفظة:</strong> لا يُسترد إلا رصيد فوق ٥٠ ريالًا، بعد خصم ٢٠٪، فاشحن بمبالغ صغيرة.</li>\n<li><strong>الساعات:</strong> تعمل الحافلات من نحو ٦ صباحًا إلى منتصف الليل، وبعض الخطوط على مدار الساعة. وأوقات كل خط تحت «الأسعار وأوقات الخدمة» في التطبيق.</li>\n<li><strong>خدمة العملاء:</strong> 920000877.</li>\n</ul>\n<ol>\n<li>ثبّت تطبيق <strong>حافلات المدينة</strong> وأنشئ حسابًا.</li>\n<li>أضف بطاقة بنكية أو اشترِ اشتراكًا.</li>\n<li>استعمل خريطة الخطوط في التطبيق لتخطيط رحلتك، ومنها الخطوط التي تخدم الجامعة ومحطة القطار.</li>\n<li>مرّر بطاقتك أو أظهر رمز التطبيق عند الركوب.</li>\n</ol>\n<p>تطبيقات النقل وعربات ممشى قباء وسيارات الأجرة المشتركة إلى مكة في <a href=\"/ar/guides/getting-around\">التنقل في المدينة، وإلى مكة</a>.</p>\n<blockquote><p>نصيحة: عندك سؤال عن خط؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "having-a-baby-in-madinah": {
  "titleAr": "الولادة في المدينة",
  "summaryAr": "مقارنة بين المستشفيات في الرسوم وحضور الزوج والمرافقة والطواقم النسائية بالكامل والولادة المجانية لزوجات طلاب الجامعة (روجعت في أبريل ٢٠٢٥)، ثم أوراق المولود بعد الولادة: قيد الميلاد وشهادة الميلاد والجواز وإقامة طفلك.",
  "bodyHtmlAr": "<blockquote><p>مهم: روجعت هذه المقارنة آخر مرة في أبريل ٢٠٢٥. والأسعار وأنظمة الزيارة تتغير، ودخول الزوج غرفة الولادة يقرره دائمًا الطاقم والأطباء المناوبون. اتصل بالمستشفى عند الحجز ثم مرة أخرى قرب موعد الولادة.</p></blockquote>\n<h2>الولادة المجانية لزوجات طلاب الجامعة</h2>\n<p>تستطيع زوجة طالب الجامعة أن تلد مجانًا في <strong>مستشفى أحد</strong>، بشرط أن تكون لها إقامة باسمها. وهو المستشفى الوحيد الذي يقدم ذلك.</p>\n<h2>رسوم الولادة (بالريال)</h2>\n<table><thead><tr><th>المستشفى</th><th>الولادة الطبيعية</th><th>الولادة القيصرية</th></tr></thead><tbody>\n<tr><td>مستشفى الدكتور حامد سليمان الأحمدي</td><td>٣٬٥٠٠</td><td>٧٬٠٠٠، ويُضاف ٣٬٠٠٠ عن كل قيصرية لاحقة</td></tr>\n<tr><td>مستشفى الحياة الوطني</td><td>٤٬٥٠٠ (يختلف السعر مع إبرة الظهر)</td><td>١٠٬٣٥٠، وتشمل كل الأدوية والتنويم ٣ أيام والمتابعة مع الطبيب وطبيب الأطفال</td></tr>\n<tr><td>مستشفى المدينة الوطني</td><td>٤٬٧١٥، إضافة إلى رسوم كشف ١٢٥ ورسوم أشعة صوتية ٢٦٤</td><td>اسأل المستشفى</td></tr>\n<tr><td>مستشفى المواساة</td><td>نحو ٦٬٠٠٠</td><td>اسأل المستشفى</td></tr>\n<tr><td>مستشفى صفا المدينة</td><td>٣٬٥٠٠، إضافة إلى رسوم كشف ١١٥</td><td>اسأل المستشفى</td></tr>\n<tr><td>المستشفى السعودي الألماني</td><td>٥٬٠٠٠</td><td>نحو ١٠٬٠٠٠، ويُضاف ٣٬٠٠٠ عن كل قيصرية لاحقة</td></tr>\n<tr><td>مستشفى أحد (حكومي، للمرضى على نفقتهم الخاصة)</td><td>٣٬٥٠٠، إضافة إلى رسوم كشف ١٠٠</td><td>٧٬٠٠٠، إضافة إلى رسوم كشف ١٠٠</td></tr>\n<tr><td>UMMC (دار سابقًا)</td><td>٣٬٠٠٠</td><td>٦٬٠٠٠</td></tr>\n<tr><td>مستشفى الولادة (للوافدين من غير الطلاب)</td><td>٥٬٠٠٠</td><td>اسأل المستشفى</td></tr>\n<tr><td>مستشفى الزهراء</td><td>٤٬١٠٠</td><td>٩٬٠٠٠</td></tr>\n</tbody></table>\n<h2>حضور الزوج والمرافقة</h2>\n<p>كل المستشفيات المذكورة أدناه تقرر ذلك في كل حالة على حدة، فيمكن أن يُمنع الزوج من الدخول يوم الولادة.</p>\n<ul>\n<li><strong>طاقم نسائي بالكامل:</strong> مستشفى الزهراء.</li>\n<li><strong>يُسمح للزوج بالحضور أثناء المخاض:</strong> الحياة الوطني، ومستشفى المدينة الوطني، والمواساة، والسعودي الألماني، والزهراء.</li>\n<li><strong>يُسمح للزوج بحضور الولادة نفسها:</strong> الحياة الوطني والمواساة.</li>\n<li><strong>يُسمح للزوج بالبقاء معكِ ليلًا ونهارًا بعد الولادة:</strong> الحياة الوطني، ومستشفى المدينة الوطني، والمواساة، والسعودي الألماني، والزهراء.</li>\n<li><strong>برنامج المرافِقة أثناء الولادة</strong> (تبقى امرأة مرافقة طوال الولادة، بعد أن تحصل أولًا على تصريح دخول من الأمن): أحد والزهراء.</li>\n</ul>\n<h2>من يتولى التوليد</h2>\n<p>في مستشفى الدكتور حامد سليمان الأحمدي ومستشفى المدينة الوطني والمواساة وأحد ومستشفى الولادة، يتولى الطبيب المناوب التوليد في العادة، فلا يمكن في الغالب اختيار الطبيب.</p>\n<blockquote><p>نصيحة: احجز مواعيد متابعة الحمل مبكرًا، واطلب من المستشفى سعر الولادة الحالي مكتوبًا، واسأل عما يشمله قبل أن تقرر.</p></blockquote>\n<p>ولمن تحمل تأشيرة زيارة، لا يغطي التأمين المرافق للتأشيرة الرعاية الطارئة للحمل والولادة إلا في حدود سقف منخفض (٥٬٠٠٠ ريال)، فاستعد لدفع تكلفة الولادة بنفسك.</p>\n<h2>بعد الولادة: الأوراق خطوة بخطوة</h2>\n<p>يحتاج طفلك إلى أربع أوراق بهذا الترتيب: قيد الميلاد، ثم شهادة الميلاد، ثم جواز سفر من سفارتك، ثم إضافته إلى إقامتك.</p>\n<h3>١. قيد الميلاد في المستشفى</h3>\n<ol>\n<li>يُبلَّغ عن الولادة في المستشفى الذي وُلد فيه طفلك، فلا حاجة إلى مراجعة مكتب الأحوال المدنية.</li>\n<li>قبل أن يرفع المستشفى البيانات، راجع كتابة كل اسم، أسماء الوالدين واسم المولود، حرفًا حرفًا مقابل جوازاتكم.</li>\n<li>يسلّمك المستشفى أصل تبليغ الولادة، وهو لا يُصدر إلا مرة واحدة، فاصنع منه عدة نسخ واحفظ الأصل جيدًا، فسفارتك تحتاج إليه.</li>\n</ol>\n<h3>٢. شهادة الميلاد في أبشر</h3>\n<p>بعد تسجيل الولادة، ادخل إلى أبشر وافتح <strong>الخدمات</strong>، ثم <strong>خدمات الأحوال المدنية</strong>، ثم <strong>خدمات شهادة الميلاد</strong>، ثم <strong>عرض شهادة الميلاد</strong>. اعرضها وراجعها واطبعها. وسجّل الولادة دون تأخير، فالولادة التي تُسجَّل بعد أكثر من ٣٠ يومًا من ولادة الطفل عليها رسوم تأخير قدرها ٥٠ ريالًا تُدفع إلكترونيًا، ورسوم التأخير غير المسددة تؤخر تجديد إقامتك.</p>\n<p>يرسل المستشفى تبليغ الولادة إلى وزارة الصحة، وتصلك رسالة نصية من وزارة الداخلية حين تُقيَّد الولادة، وذلك خلال أسبوعين على الأكثر. فإن لم تظهر الشهادة بعد تلك الرسالة:</p>\n<ol>\n<li>افتح في أبشر <strong>الخدمات</strong>، ثم <strong>الأحوال المدنية</strong>، ثم <strong>تسجيل المواليد</strong>. وتعمل الخدمة ما دام الطفل لم يبلغ سنة من عمره، وبعد تسجيل عنوانك الوطني.</li>\n<li>راجع كتابة كل اسم وتاريخ الميلاد. وإن وجدت خطأً فتوقف واطلب من المستشفى تصحيح تبليغه.</li>\n<li>وافق على الشروط، ثم اختر توصيل الشهادة بالبريد إلى عنوانك الوطني، أو استلامها من مكتب الأحوال المدنية.</li>\n</ol>\n<p>وإن لم يكتمل الطلب الإلكتروني، فاحجز موعدًا في الأحوال المدنية عبر أبشر بخدمة «تسجيل واقعة ميلاد»، في أي مكتب بالمنطقة التي وُلد فيها طفلك: انظر <a href=\"/ar/guides/family-records-on-absher#حجز-موعد-في-الجوازات-أو-الأحوال-المدنية-أو-المرور\">حجز موعد في الجوازات أو الأحوال المدنية أو المرور</a>. واحضر قبل موعدك بـ٢٠ دقيقة ومعك رسالة وزارة الداخلية النصية، ونسخ من جوازَي الوالدين، وإقامة الأب، وإقامة الأم إن كانت لها إقامة. وإن لم تكن الأم تابعة على إقامة الأب، كأن تكون على تأشيرة زيارة، فأضف عقد الزواج مترجمًا إلى العربية ونسخة من تأشيرتها السعودية. ثم املأ نموذج تسجيل المولود (النموذج رقم ٨٧)، وادفع رسوم التأخير البالغة ٥٠ ريالًا إن تجاوز عمر الطفل ٣٠ يومًا، فتُطبع الشهادة عند الشباك.</p>\n<h3>٣. جواز سفر المولود</h3>\n<p>تسجّل سفارتك الولادة وتصدر جواز سفر المولود. فاطّلع على قائمة الأوراق في موقع سفارتك قبل أن تذهب، فمن السفارات ما يطلب تبليغ الولادة مترجمًا لدى مترجم تعتمده. وخذ معك نسخًا من جوازات الوالدين وإقامتيهما. وإن طلبت سفارتك تصديق شهادة الميلاد السعودية، فإن وزارة الخارجية تصدقها أولًا.</p>\n<h3>٤. إقامة طفلك</h3>\n<p>إن كانت لك إقامة فأضف طفلك إليها تابعًا. وقدّم طلبًا مستقلًا لكل طفل، حتى التوائم.</p>\n<table><thead><tr><th>مكان ولادة الطفل</th><th>الرسوم</th></tr></thead><tbody>\n<tr><td>داخل السعودية</td><td>رسوم التابعين فقط، وتظهر في أبشر قبل الدفع</td></tr>\n<tr><td>خارج السعودية</td><td>رسوم التابعين، إضافة إلى ٢٬٠٠٠ ريال لتأشيرة دخول التابع</td></tr>\n</tbody></table>\n<ol>\n<li><strong>اجمع للطفل ملف PDF واحدًا لا يتجاوز ١ ميغابايت،</strong> فيه هذه الصفحات بهذا الترتيب: شهادة الميلاد، وجواز المولود، والتأمين الصحي، وإيصال الرسوم، وصورة المولود، وجوازا الوالدين وإقامتاهما.</li>\n<li><strong>وُلد خارج السعودية؟</strong> أضف تأشيرة المولود السعودية وعليها ختم الدخول ورقم الحدود، وشهادة تطعيم شلل الأطفال من المستشفى. وادفع الـ٢٬٠٠٠ ريال قبل تقديم الطلب.</li>\n<li><strong>قدّم الطلب في أبشر:</strong> خدماتي، ثم الجوازات، ثم تواصل، ثم طلب جديد. اختر القطاع «خدمات المقيمين داخل المملكة»، ثم <strong>تسجيل مولود (NewBorn registration)</strong> للمولود هنا، أو <strong>فصل تابع (Separate Dependent)</strong> للمولود في الخارج. وللمولود في الخارج اكتب رقم الحدود في الوصف.</li>\n<li><strong>انتظر رسالتين نصيتين:</strong> الأولى فيها رقم الطلب، والثانية عند الموافقة عليه. ثم ادخل إلى تواصل مرة أخرى واطبع الموافقة.</li>\n<li><strong>احجز موعدًا في الجوازات عبر أبشر،</strong> وخذ معك خطاب الموعد والموافقة وملف PDF مطبوعًا وأصل جواز المولود وصورًا شخصية.</li>\n<li><strong>راجع كل بيانات الإقامة</strong> قبل أن تغادر الشباك.</li>\n</ol>\n<p>وتواصل هنا هي خدمة الطلبات التابعة لوزارة الداخلية داخل أبشر، لا تواصل الجامعة. وأضف المولود في الخارج خلال ثلاثة أشهر من وصوله تجنبًا للغرامة. ورسوم التابعين مفصلة في <a href=\"/ar/guides/iqama-and-exit-reentry-fees\">رسوم الإقامة والخروج والعودة والخروج النهائي والتابعين</a>، وخدمات الأسرة في أبشر مشروحة في <a href=\"/ar/guides/family-records-on-absher\">إقامات أسرتك وسجلاتها في أبشر</a>.</p>\n<p>ومن كان بهوية زائر فليست له إقامة يضيف إليها المولود. سجّل الولادة واستخرج الجواز بالطريقة نفسها، ثم اسأل عمادة القبول والتسجيل عبر تواصل، تحت موضوع «التأشيرة التعليمية»، عن ترتيب إقامة طفلك.</p>\n<p><strong>الأم على تأشيرة زيارة؟</strong> المولود هنا لأمٍّ تحمل تأشيرة زيارة عائلية يحتاج إلى ختم خروج من الجوازات قبل المغادرة. اتبع الخطوات السابقة حتى استخراج الجواز. ثم احجز، قبل سفرك بـ١٥ يومًا على الأقل، موعدًا في الجوازات تحت «خدمات المقيمين»، وراجع «إدارة شؤون الوافدين» ومعك جواز المولود، وإقامة الأب وجوازه، وجواز الأم وفيه تأشيرتها السعودية، وعقد الزواج مترجمًا إلى العربية، ورسالة وزارة الداخلية النصية الخاصة بالولادة، مع نسخة من كلٍّ منها. فتختم الجوازات خروج المولود في جوازه.</p>\n<h3>٥. التطعيمات</h3>\n<p>تُعطى التطعيمات الأولى في المستشفى قبل الخروج، ويُستكمل الباقي وفق الجدول الوطني في مركز الرعاية الصحية الأولية التابع لك: انظر <a href=\"/ar/ask/baby-vaccinations\">كيف أحصل على تطعيمات طفلي الرضيع في المدينة؟</a></p>"
 },
 "historic-sites-and-masjids": {
  "titleAr": "المواقع التاريخية والمساجد في المدينة",
  "summaryAr": "المساجد ومواقع الغزوات والآبار والمزارع التي تستحق الزيارة، مقسمة بحسب المنطقة مع المسافة التقريبية من الحرم.",
  "bodyHtmlAr": "<p>المسافات تقريبية وتُقاس من المسجد النبوي. وأكثر المواقع قريبة يسهل الوصول إليها بسيارة أجرة أو عبر تطبيقات النقل، ويمكن الجمع بين عدد منها في جولة واحدة. وأفضل وقت للزيارة في الأشهر الحارة الصباح الباكر أو ما بعد العصر.</p>\n<h2>قرب الحرم</h2>\n<table><thead><tr><th>المكان</th><th>نبذة</th></tr></thead><tbody>\n<tr><td>مسجد الغمامة</td><td>صلى فيه النبي ﷺ صلاة الاستسقاء. ويقع على مسافة قصيرة مشيًا جنوب غرب المسجد النبوي.</td></tr>\n<tr><td>مسجد أبي بكر الصديق</td><td>بجوار مسجد الغمامة.</td></tr>\n<tr><td>مسجد علي بن أبي طالب</td><td>مسجد صغير يمكن الوصول إليه مشيًا.</td></tr>\n<tr><td>مسجد بلال الحبشي</td><td>سُمي باسم مؤذن النبي ﷺ، ويبعد نحو كيلومتر واحد.</td></tr>\n<tr><td>مسجد السقيا وبئره</td><td>عسكر عنده النبي ﷺ قبل غزوة بدر، ويبعد نحو كيلومترين.</td></tr>\n</tbody></table>\n<h2>قباء وجنوب المدينة</h2>\n<ul>\n<li><strong>مسجد قباء</strong> (نحو ٣٫٥ كم): أول مسجد في الإسلام. ومن تطهر في بيته ثم صلى فيه ركعتين كان له أجر عمرة. ويمشي إليه كثيرون يوم السبت عبر ممشى قباء، وطوله نحو ٣ كم ويستغرق قرابة ٤٥ دقيقة.</li>\n<li><strong>مسجد الجمعة</strong> (نحو ٤ إلى ٥ كم): أُقيمت فيه أول صلاة جمعة في المدينة، ويقع على الطريق بين الحرم وقباء.</li>\n<li><strong>بساتين قباء:</strong> تقع بئر أريس، وتُعرف ببئر الخاتم، في البساتين القريبة من قباء، وهي البئر التي سقط فيها خاتم النبي ﷺ من يد عثمان. وفي الساحة المحيطة بالمسجد مقاهٍ عائلية.</li>\n</ul>\n<h2>الخندق وجبل سلع ومسجد القبلتين</h2>\n<p>وقعت غزوة الخندق في السنة الخامسة للهجرة حول جبل سلع، شمال غرب الحرم. ولا تزال المساجد الصغيرة على سفحه تُعرف بالمساجد السبعة، مع أن عددًا منها أُعيد بناؤه أو ضُم إلى مساجد أكبر، والقائم منها اليوم أقل من سبعة. وأشهرها مسجد الفتح، وفيه دعا النبي ﷺ، ويقوم مسجد الخندق الكبير بجوار الموقع. ويستغرق التجول في المنطقة مشيًا نحو ٤٠ دقيقة.</p>\n<p><strong>مسجد القبلتين</strong> (نحو ٤ كم شمال غرب الحرم، على طريق خالد بن الوليد) هو المسجد الذي تحولت فيه القبلة من بيت المقدس إلى الكعبة بمكة. ولا يبعد عن المساجد السبعة إلا مسافة قصيرة بالسيارة، فيُزاران معًا في جولة واحدة.</p>\n<h2>أحد</h2>\n<p>عند جبل أحد، على بعد نحو ٥ كم شمال الحرم، وقعت غزوة أحد في السنة الثالثة للهجرة. وتضم مقبرة الشهداء عند سفحه سبعين شهيدًا، منهم حمزة بن عبد المطلب. ويستغرق المشي حول سفح الجبل نحو ساعة. ومسجد المستراح قريب منه.</p>\n<h2>الآبار والمزارع</h2>\n<ul>\n<li><strong>بئر رومة (بئر عثمان)،</strong> على بعد نحو ٦ كم شمال غرب الحرم: اشتراها عثمان بن عفان وجعلها للناس عامة. ولا تزال تسقي مزرعة نخيل قائمة يُباع تمرها لصالح الأعمال الخيرية. وفي بعض الأوقات لا يرى الزوار البئر إلا من خارج السور.</li>\n<li>بئر أنس بن مالك وبئر غرس في مزارع قائمة، ولا تُزاران إلا بإذن أصحاب المزارع.</li>\n<li><strong>عوالي المدينة</strong> هي الحزام الزراعي القديم للمدينة. وبعض مزارعها يستقبل الزوار في موسم جني التمر، أواخر الصيف.</li>\n</ul>\n<h2>مواقع أبعد</h2>\n<p>بدر وخيبر وينبع والعلا وغيرها تجدها في <a href=\"/ar/guides/day-trips-from-madinah\">رحلات اليوم الواحد وعطلات نهاية الأسبوع خارج المدينة</a>.</p>\n<blockquote><p>ملاحظة: المواقع التي تقع داخل مزارع قائمة ليست مفتوحة للجميع. استأذن أولًا، ولا تترك خلفك شيئًا.</p></blockquote>"
 },
 "homeschooling-in-madinah": {
  "titleAr": "تعليم أطفالك في البيت في المدينة",
  "summaryAr": "ما ينص عليه النظام السعودي في التعليم، والسجلات التي تحفظها، والمناهج واختبارات IGCSE، والعربية وحلقات القرآن، والأصدقاء والمكتبات والرياضة، وكيف تنقل طفلًا تعلّم في البيت إلى مدرسة هنا، ومعادلة الشهادات.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. بعض الأسر الناطقة بالإنجليزية في المدينة تعلّم أطفالها في البيت، بضع سنوات أو طوال مدة إقامتها. ويتناول هذا الدليل ما ينص عليه النظام السعودي في التعليم، والسجلات التي تحفظها، والمناهج والاختبارات، والعربية والقرآن، والأصدقاء والرياضة، وكيف تنقل طفلك إلى مدرسة هنا فيما بعد.</p>\n<h2>ما ينص عليه النظام</h2>\n<p>صدر في المملكة نظام التعليم العام الجديد بمرسوم ملكي، ونُشر في ٢٤ يوليو ٢٠٢٦. ويُعمل به بعد ١٨٠ يومًا من نشره، أي في يناير ٢٠٢٧. وهو يجعل التعليم إلزاميًا من سن ٦ إلى ١٥ سنة، ويبقي التعليم مجانيًا في المدارس الحكومية، ويخوّل وزارة التعليم اتخاذ الإجراء بحق كل من يحرم طفلًا في هذه السن من التعليم.</p>\n<p>قبل أن تخطط لسنة دراسية في البيت، اسأل عن تطبيق النظام على حالة طفلك. والجهة المختصة بالمدينة هي الإدارة العامة للتعليم بمنطقة المدينة المنورة، وموقعها <a href=\"https://sites.moe.gov.sa/Madinah/\">sites.moe.gov.sa/Madinah</a>. وتجيب الوزارة أيضًا على الرقم 19996 على مدار الساعة، وعبر خدمة تواصل على <a href=\"https://tawasul.moe.gov.sa/\">tawasul.moe.gov.sa</a>. اسأل عبر تواصل لتحصل على الجواب مكتوبًا، واحفظه مع سجلاتك.</p>\n<p>في النظام السعودي مساران يناسبان بعض الأسر التي تدرّس أطفالها في البيت. اسأل إدارة التعليم هل يستوفي طفلك شروط أحدهما.</p>\n<ul>\n<li><strong>الانتساب:</strong> في المرحلتين المتوسطة والثانوية يمكن أن يُسجَّل الطفل في مدرسة سعودية دون حضور يومي، ويؤدي اختبارات المدرسة في المنهج السعودي. اطبع إثبات الدخول والإقامة من أبشر وسلّمه للمدرسة قبل اختبارات الفصل الأول والفصل الثاني بأربعة أسابيع. ويُلغى انتساب الطفل الذي لم يكن مقيمًا في المملكة قبيل الاختبارات مباشرة، إلا إذا اضطرته ظروف إلى سفر لا يزيد على أسبوعين.</li>\n<li><strong>اختبار تحديد المستوى:</strong> للمرحلتين المتوسطة والثانوية، للطفل الذي لم يلتحق بمدرسة قط، أو الذي انقطع عن الدراسة ثلاث سنوات فأكثر. وتسجل إدارة التعليم المتقدمين وتحدد المواعيد.</li>\n</ul>\n<h2>اختيار المنهج</h2>\n<p>الخيارات المعتادة:</p>\n<ul>\n<li>المنهج الوطني لبلدك، بكتبه واختباراته.</li>\n<li>مدرسة إلكترونية معتمدة في بلدها، فيها حصص وتصحيح وتقرير لكل سنة.</li>\n<li>الاختبارات الدولية مثل IGCSE وA Levels، يؤديها الطفل متقدمًا خاصًا.</li>\n</ul>\n<p>أيًّا كان اختيارك، فكّر في المكان الذي سيُنهي فيه طفلك دراسته. فوزارة التعليم لا تعادل الشهادة الصادرة من الخارج بصف سعودي إلا إذا كانت المدرسة معتمدة من جهة التعليم في بلدها، وكانت شهادتها الثانوية مقبولة في جامعات ذلك البلد، وكان الطفل منتظمًا فيها بتسلسل واضح، مع سجل نجاح لكل سنة سابقة. والملحقية الثقافية السعودية في الولايات المتحدة لا تصادق شهادات الثانوية الصادرة من برامج التعليم المنزلي أو الإلكتروني أو عن بُعد. فإن كان الهدف جامعة في المملكة، فطابق الشهادة النهائية بهذه الشروط قبل سنوات المرحلة الثانوية.</p>\n<h3>أداء IGCSE وA Levels متقدمًا خاصًا</h3>\n<p>يسجل المجلس الثقافي البريطاني في السعودية المتقدمين الخاصين لاختبارات كامبريدج الدولية في مايو ويونيو وفي أكتوبر ونوفمبر، ولاختبارات بيرسون إدكسل في يناير وفي مايو ويونيو وفي أكتوبر ونوفمبر. ولكل دورة موعد نهائي للتسجيل، تجده في <a href=\"https://saudiarabia.britishcouncil.org/en/exam/igcse-school/register/dates-deadlines\">صفحة مواعيد التسجيل</a>.</p>\n<ol>\n<li>سجّل إلكترونيًا عبر نظام تسجيل المدارس التابع للمجلس الثقافي البريطاني على <a href=\"https://saudiarabia.britishcouncil.org/en/exam/igcse-school/register/private\">saudiarabia.britishcouncil.org</a>، قبل الموعد النهائي للدورة.</li>\n<li>ادفع الرسوم المعروضة في النظام. ولا يُعالج تسجيلك حتى تدفع.</li>\n<li>قبل الاختبارات بنحو ثلاثة أسابيع يصلك إشعار التسجيل (Statement of Entry) وبيانات مقر الاختبار.</li>\n</ol>\n<p>مكاتب المجلس الثقافي البريطاني في الرياض وجدة والخبر، فاسأل عن مكان اختبار طفلك قبل أن تسجل، وخطط للسفر.</p>\n<h2>السجلات والوثائق التي تحفظها</h2>\n<ul>\n<li><strong>الهوية:</strong> جواز كل طفل بتأشيرة سارية، أو إقامة الطفل. وتُجدد إقامات المرافقين في أبشر (انظر <a href=\"/ar/guides/family-records-on-absher\">إقامات أسرتك وسجلاتها في أبشر</a>). ولا إقامات مرافقين لحامل هوية زائر (انظر <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر: ما يعمل وما لا يعمل</a>).</li>\n<li><strong>شهادة الميلاد وسجل التطعيمات:</strong> كل مدرسة تطلبهما، مع تصديق شهادة الميلاد وترجمتها إلى العربية. وجدول التطعيمات السعودي في <a href=\"/ar/ask/baby-vaccinations\">كيف أطعّم طفلي في المدينة؟</a></li>\n<li><strong>الأوراق المدرسية من قبل قدومك:</strong> كل تقرير وكل شهادة، مصدقة من وزارة التعليم (أو الجهة المشرفة على المدارس) ووزارة الخارجية في البلد الذي أصدرها، ثم من السفارة السعودية هناك، ومن ملحقيتها الثقافية حيث توجد. والأوراق التي ليست بالعربية أو الإنجليزية تحتاج إلى ترجمة معتمدة.</li>\n<li><strong>سجلات برنامجك المنزلي:</strong> خطاب التسجيل، وتقرير أو كشف درجات لكل سنة، وشهادات الاختبارات، وملف صغير من أعمال طفلك في كل مادة.</li>\n</ul>\n<blockquote><p>مهم: تطلب الوزارة الأصول، بلا شطب، واسم الطفل مكتوبًا بالطريقة نفسها في كل ورقة. صحّح أي اختلاف مع المدرسة المُصدِرة قبل مغادرة بلدك، واحتفظ بنسخ ممسوحة من كل شيء.</p></blockquote>\n<h2>العربية والقرآن</h2>\n<p>اجعل للعربية وقتًا يوميًا من البداية، ليكون طفلك مستعدًا إن انتقل إلى مدرسة سعودية فيما بعد.</p>\n<ul>\n<li><strong>حلقات المسجد النبوي:</strong> حلقات قرآن مجانية للأطفال والكبار. سجّل على <a href=\"https://reg.qm.edu.sa/\">reg.qm.edu.sa</a>، وأنشئ حسابًا مستقلًا لكل طفل، واختر القسم ونوع الدراسة والوقت. ولا اختبار قبول ولا مقابلة لحلقات التلاوة والحفظ والمراجعة. واستعمل بريدًا إلكترونيًا تتابعه، لأن الحلقات تتواصل معك عن طريقه. والأعمار والأبواب والأوقات في <a href=\"/ar/guides/kindergartens-and-schools\">الروضات والمدارس لأطفالك</a>.</li>\n<li><strong>مسجد حيّك:</strong> أكثر مساجد الأحياء تقيم حلقات القرآن بعد العصر أو المغرب. اسأل الإمام.</li>\n<li><strong>أثناء صلاتك في الحرم:</strong> انظر <a href=\"/ar/ask/children-at-masjid-an-nabawi\">هل يوجد مكان لأطفالي أثناء صلاتي في المسجد النبوي؟</a></li>\n<li><strong>للأمهات:</strong> في عدد من المراكز النسائية حضانة أو روضة بجانب الدروس. انظر <a href=\"/ar/guides/sisters-studying-in-madinah\">أين تدرس الأخوات العربية والعلوم الشرعية في المدينة</a>.</li>\n</ul>\n<h2>الأصدقاء والمكتبات والرياضة</h2>\n<ul>\n<li><strong>الأسر الأخرى:</strong> تلتقي بها في حلقات الحرم، وفي المسجد بعد العصر، وفي الحدائق ومراكز الألعاب المذكورة في <a href=\"/ar/guides/kids-activities\">أماكن اللعب والترفيه للأطفال في المدينة</a>، وفي مجموعة MESH (انظر <a href=\"/ar/ask/join-mesh-group\">كيف أنضم إلى مجموعة MESH على واتساب؟</a>). والدراسة المشتركة مع أسرة أو أسرتين، يتولى فيها كل والد مادة، تمنح الأطفال فصلًا صغيرًا خاصًا بهم.</li>\n<li><strong>المكتبات:</strong> في مكتبة المسجد النبوي قاعات قراءة للأطفال، مفتوحة كل يوم. ومواقع المكتبات وما يُسمح بإدخاله إليها في <a href=\"/ar/ask/library-bags-laptops\">هل أستطيع إدخال حقيبة أو حاسوب محمول إلى المكتبات؟</a> وفي معرض المدينة المنورة للكتاب، الذي تنظمه هيئة الأدب والنشر والترجمة، أجنحة للأطفال. ومواعيد كل عام على <a href=\"https://lpt.moc.gov.sa/\">lpt.moc.gov.sa</a>.</li>\n<li><strong>الرياضة:</strong> النادي الرياضي بالجامعة الإسلامية، وحصص للأطفال مثل الجوجيتسو واللياقة، تجدها في <a href=\"/ar/guides/sports-and-activities\">الرياضة وحصص اللياقة</a>.</li>\n</ul>\n<h2>الانتقال إلى مدرسة فيما بعد</h2>\n<p>الرسوم والوثائق ونظام نور ومواعيد التسجيل في <a href=\"/ar/guides/kindergartens-and-schools\">الروضات والمدارس لأطفالك</a>. والطفل الذي تعلّم في البيت يحتاج إلى خطوات إضافية قليلة.</p>\n<ul>\n<li><strong>المدارس العالمية والأهلية</strong> تضع اختبارات القبول الخاصة بها. اسأل كل مدرسة عما تطلبه من طفل تعلّم في البيت، واحمل معك تقاريرك السنوية وملف الأعمال.</li>\n<li><strong>المدارس الحكومية</strong> تقبل أبناء حاملي الإقامة في المقاعد المتبقية بعد تسجيل الطلاب السعوديين، في حدود نسبة ١٥٪ حددها مجلس الوزراء. ويحتاج الطفل إلى خطاب إذن من وزارة التعليم وخطاب من جهة عمل الوالد. ولا يُقبل الأطفال القادمون بتأشيرة زيارة أو سياحة أو عمرة.</li>\n<li><strong>نقاط الالتحاق:</strong> الصف الأول المتوسط يتطلب النجاح في الصف السادس الابتدائي أو ما يعادله، مصدقًا. والصف الأول الثانوي يتطلب شهادة المرحلة المتوسطة أو ما يعادلها.</li>\n</ul>\n<h3>معادلة شهادة طفلك</h3>\n<ol>\n<li>اجمع الأصول: آخر شهادة وسجلات النجاح في السنوات السابقة، مصدقة ومترجمة كما سبق.</li>\n<li>قدّمها في إدارة التعليم بالمدينة. فلأي صف دون السنة الأخيرة من الثانوية تعادل الإدارة الأوراق بنفسها. أما شهادة إتمام المرحلة الثانوية فتُرسل إلى الوزارة إلكترونيًا، ويعود القرار عبر الإدارة.</li>\n<li>تُلحق المدرسة طفلك بالصف الذي يحدده قرار المعادلة.</li>\n</ol>\n<p>وفي المرحلتين المتوسطة والثانوية، يتقدم الطفل الذي لا سجلات معترفًا بها له لاختبار تحديد المستوى المذكور أعلاه.</p>"
 },
 "iqama-and-exit-reentry-fees": {
  "titleAr": "الإقامة والخروج والعودة والخروج النهائي ورسوم التابعين: كم تكلف ومن يصدرها",
  "summaryAr": "ما تتقاضاه الجوازات عن الإقامة وتأشيرات الخروج والعودة والخروج النهائي وإضافة الأسرة وتمديد تأشيرات الزيارة، ومن يصدر كل ورقة للطالب ولأسرته، والقواعد التي يقع فيها الناس، وغرامات تأخر التجديد وفقد البطاقة، وتمديد تأشيرة فرد الأسرة وهو في الخارج، وخطوات أبشر. روجع في نوفمبر ٢٠٢٦.",
  "bodyHtmlAr": "<blockquote><p>مهم: هذه رسوم خدمات الجوازات، روجعت في نوفمبر ٢٠٢٦. وتنطبق رسوم أخرى على حدة كالتأمين الصحي، فتأكد من المبلغ النهائي في أبشر قبل أن تدفع.</p></blockquote>\n<p>الطلاب الجدد على التأشيرة التعليمية لا تُصدر لهم إقامة: يحملون هوية زائر ولا يدفعون شيئًا من هذه الرسوم. والطلاب من الدفعات السابقة الذين يحملون إقامة طالب لا يدفعون شيئًا عن إقامتهم. والرسوم أدناه تهم الأسر ومن يسافر في المقام الأول. وتُدفع الرسوم عبر سداد في تطبيق بنكك تحت «المدفوعات الحكومية»، ويُظهر أبشر المبلغ النهائي قبل أن تدفع.</p>\n<h2>من يصدر ماذا</h2>\n<p>بإقامة الطالب تكون الجامعة كفيلك، فأوراقك أنت تمر عبر إدارة السفر فيها. وأوراق أسرتك تمر عبر حسابك أنت في أبشر، بوصفك رب الأسرة.</p>\n<table><thead><tr><th>الورقة</th><th>لك</th><th>لزوجتك وأبنائك</th></tr></thead><tbody>\n<tr><td>إصدار الإقامة وتجديدها</td><td>إدارة السفر، عبر مقيم. انظر <a href=\"/ar/ask/student-iqama-renewal\">من يجدد إقامتي الطلابية؟</a></td><td>وحدة الاستقبال في إدارة السفر تصدر الإقامة الأولى، وأنت تجددها في أبشر</td></tr>\n<tr><td>تأشيرة الخروج والعودة</td><td>إدارة السفر. تجمع قوائم الإجازة الصيفية والإجازات المعتمدة والتأجيل، وتتولى الطلاب الغائبين أكثر من ستة أشهر</td><td>أنت، في أبشر</td></tr>\n<tr><td>الخروج النهائي</td><td>إدارة السفر، بعد ظهور إخلاء طرفك</td><td>أنت، في أبشر</td></tr>\n<tr><td>تأشيرة زيارة لقريب، وتمديدها</td><td colspan=\"2\">أنت، في أبشر أو مقيم، بوصفك المضيف</td></tr>\n</tbody></table>\n<h2>الإقامة</h2>\n<table><thead><tr><th>من</th><th>الرسوم (ريال)</th></tr></thead><tbody>\n<tr><td>طالب بإقامة طالب</td><td>مجانًا</td></tr>\n<tr><td>عامل منزلي أو مزارع أو راعٍ</td><td>٦٠٠</td></tr>\n<tr><td>عامل في شركة أو مؤسسة</td><td>٦٥٠</td></tr>\n</tbody></table>\n<p>يمكن تجديد إقامة عامل الشركة ٣ أو ٦ أو ٩ أو ١٢ شهرًا في كل مرة:</p>\n<table><thead><tr><th>مدة التجديد</th><th>الرسوم (ريال)</th></tr></thead><tbody>\n<tr><td>٣ أشهر</td><td>١٦٣</td></tr>\n<tr><td>٦ أشهر</td><td>٣٢٥</td></tr>\n<tr><td>٩ أشهر</td><td>٤٨٨</td></tr>\n<tr><td>١٢ شهرًا</td><td>٦٥٠</td></tr>\n</tbody></table>\n<p>إقامة العامل المنزلي أو المرافق المكفول (أب أو أم أو أخ أو أخت على كفالتك) تكلف الضعف إذا جُددت وحاملها خارج السعودية: ١٬٣٠٠ ريال بدل ٦٥٠ ريالًا.</p>\n<p>يتعطل التجديد بسبب المخالفات المرورية غير المدفوعة، والأبناء غير المضافين إلى الإقامة بعد، وغرامة تأخر شهادة الميلاد، والتأشيرة المنتهية في الملف. فسوِّ هذه قبل تاريخ الانتهاء لا بعده. وطريقة تجديد إقامات زوجتك وأبنائك، حتى وهم في الخارج، مشروحة في <a href=\"/ar/guides/family-records-on-absher\">إقامات أسرتك وسجلاتها في أبشر</a>.</p>\n<h3>التأخر في التجديد</h3>\n<p>الإقامة التي لا تُجدد خلال ٣ أيام من تاريخ انتهائها تُفرض عليها غرامة:</p>\n<ul>\n<li>المرة الأولى: ٥٠٠ ريال.</li>\n<li>المرة الثانية: ١٬٠٠٠ ريال.</li>\n<li>المرة الثالثة: الترحيل.</li>\n</ul>\n<p>راجع كل إقامات أسرتك في أبشر مرة كل شهر. ومتى تم التجديد ظهر التاريخ الجديد فورًا في الإقامة الرقمية في أبشر وتوكلنا.</p>\n<h3>إذا فقدت إقامتك أو جوازك</h3>\n<ol>\n<li><strong>استخرج محضر بلاغ</strong> من أقرب مركز شرطة في اليوم نفسه، واحتفظ به.</li>\n<li><strong>الإقامة المفقودة:</strong> يطلب الكفيل بدل فاقد عبر الجوازات (إدارة السفر لإقامة الطالب، وأنت لأسرتك). ورسوم بدل الفاقد لإقامة العمل أو إقامة أحد أفراد الأسرة ١٬٠٠٠ ريال في المرة الأولى و٢٬٠٠٠ ريال في الثانية.</li>\n<li><strong>الجواز المفقود:</strong> أبلغ عنه في أبشر، ففيه خدمة للجواز المفقود أو المسروق، ثم راجع سفارتك أو قنصليتك لاستخراج جواز جديد. وتطلب السفارات محضر الشرطة، وإفادة مكتوبة بالفقد، ومطبوعًا من الجوازات ببيانات إقامتك، ونسخة من الجواز المفقود إن كانت لديك، وبطاقة هويتك الوطنية، ونسخة من إقامتك، ورسوم الجواز. ولكل دولة قائمتها، فاطّلع على موقعها أولًا.</li>\n<li><strong>انقل سجلاتك السعودية إلى الجواز الجديد:</strong> انظر <a href=\"/ar/ask/renew-passport-in-saudi\">جوازي على وشك الانتهاء</a>.</li>\n</ol>\n<p>احتفظ على جوالك بصور لوجهي إقامتك ولصفحة الصورة في جوازك، وبنسخ ورقية في البيت.</p>\n<h2>تأشيرة الخروج والعودة</h2>\n<table><thead><tr><th>التأشيرة</th><th>الرسوم (ريال)</th></tr></thead><tbody>\n<tr><td>مفردة، حتى شهرين، رحلة واحدة</td><td>٢٠٠</td></tr>\n<tr><td>كل شهر إضافي على التأشيرة المفردة</td><td>١٠٠</td></tr>\n<tr><td>متعددة، حتى ثلاثة أشهر، عدة رحلات</td><td>٥٠٠</td></tr>\n<tr><td>كل شهر إضافي على التأشيرة المتعددة</td><td>٢٠٠</td></tr>\n<tr><td>الخروج النهائي</td><td>مجانًا</td></tr>\n</tbody></table>\n<p>يجب أن تقع الأشهر الإضافية ضمن صلاحية إقامتك. وإن مددت وأنت في الخارج كلفت الأشهر الإضافية الضعف: ٢٠٠ ريال للشهر على التأشيرة المفردة و٤٠٠ ريال للشهر على المتعددة. ولا تُرد الرسوم إن ألغيت التأشيرة، فاختر المدة بعناية.</p>\n<h3>القواعد التي يقع فيها الناس</h3>\n<ul>\n<li><strong>عُد قبل انتهائها، أو مددها.</strong> مددها من أبشر قبل أن تنتهي، ما دامت الإقامة سارية ورسوم التمديد مدفوعة (الخطوات أدناه). وإن انتهت وأنت في الخارج فالكفيل يمددها إلكترونيًا عبر موقع وزارة الخارجية بدلًا من ذلك. وراقب التاريخين كليهما: تاريخ التأشيرة وتاريخ الإقامة.</li>\n<li><strong>يجب أن تبقى الإقامة سارية بعد التأشيرة.</strong> في التأشيرة المحددة بعدد الأيام يجب أن تكون الإقامة سارية مدة التأشيرة مضافًا إليها ٩٠ يومًا. وفي التأشيرة المحددة بتاريخ العودة يجب أن يقع تاريخ العودة قبل انتهاء الإقامة بسبعة أيام على الأقل.</li>\n<li><strong>يجب أن يبقى جوازك صالحًا بعد الرحلة.</strong> يجب أن يبقى الجواز ساريًا ٣ أشهر على الأقل بعد نهاية التأشيرة، وإلا رفضها أبشر. فجدد الجواز أولًا: انظر <a href=\"/ar/ask/renew-passport-in-saudi\">جوازي على وشك الانتهاء</a>.</li>\n<li><strong>المخالفات تمنعها.</strong> أي مخالفة مرورية غير مدفوعة عليك، أو على أحد التابعين، تمنع صدور التأشيرة.</li>\n<li><strong>قدّم من داخل السعودية.</strong> يجب أن يكون المسافر داخل المملكة عند إصدار التأشيرة، وبإقامة سارية.</li>\n<li><strong>البصمة مسجلة.</strong> يجب أن تكون بصمات المسافر مسجلة لدى الجوازات، أو حسابه في أبشر مفعّلًا. وهذا يشمل أفراد الأسرة أيضًا، فتحقق من بصمات كل مسافر قبل الرحلة بوقت كافٍ، واحجز موعدًا لمن لم تُسجل بصمته: انظر <a href=\"/ar/guides/family-records-on-absher#حجز-موعد-في-الجوازات-أو-الأحوال-المدنية-أو-المرور\">حجز موعد في الجوازات</a>.</li>\n<li><strong>تأشيرة مفتوحة واحدة في كل مرة.</strong> التأشيرة السابقة التي صدرت ولم تُستخدم تمنع إصدار تأشيرة جديدة، فألغها في أبشر قبل أن تصدر التالية.</li>\n<li><strong>سافر خلال ٣ أشهر، أو ألغِ التأشيرة.</strong> استخدم التأشيرة خلال ٣ أشهر من يوم إصدارها. وتأشيرة فرد الأسرة التي لن تستخدمها تُلغى في أبشر (خدمات أفراد الأسرة، ثم خدمات التأشيرات) ما دامت سارية، خلال ٩٠ يومًا من الإصدار أو قبل تاريخ العودة، أيهما أسبق. وبعد ذلك تُحتسب غرامة تلقائيًا.</li>\n<li><strong>ادفع على الإقامة الصحيحة.</strong> تُدفع الرسوم برقم إقامة المسافر نفسه، لا برقم إقامة رب الأسرة.</li>\n<li><strong>اطبعها أو احفظها.</strong> تطلب شركات الطيران رؤية التأشيرة عند إنهاء إجراءات السفر. احتفظ بنسخة على جوالك.</li>\n<li><strong>تذكرة الصيف والتأشيرة معًا.</strong> اطلب التأشيرة حين تجمع الجامعة قوائم السفر الصيفي، لتغطي تواريخ التأشيرة تواريخ التذكرة.</li>\n</ul>\n<h3>إصدارها لأحد التابعين في أبشر</h3>\n<ol>\n<li>ادخل إلى أبشر أفراد، وافتح <strong>الخدمات</strong>، ثم <strong>الجوازات</strong>، ثم <strong>تأشيرة خروج وعودة</strong> (أو <strong>تأشيرة خروج نهائي</strong>).</li>\n<li>اختر فرد الأسرة ونوع التأشيرة والأشهر، وطابق التواريخ مع تاريخ انتهاء الإقامة.</li>\n<li>حدد المدة بإحدى طريقتين: <strong>بعدد الأيام</strong>، وتُحسب من يوم مغادرة الشخص، أو <strong>بتاريخ العودة</strong>، وهو آخر يوم يجوز له أن يعود فيه.</li>\n<li>ادفع الرسوم المبينة عبر سداد في تطبيق بنكك، تحت «المدفوعات الحكومية»، برقم إقامة المسافر، ثم عد إلى أبشر لإصدار التأشيرة وتنزيلها.</li>\n</ol>\n<h3>تمديد تأشيرة فرد من الأسرة وهو في الخارج</h3>\n<p>إذا كانت زوجتك أو أبناؤك خارج السعودية واحتاجوا إلى وقت أطول، فمدد تأشيرة خروجهم وعودتهم من أبشر، ولا يلزمهم أن يعودوا أولًا.</p>\n<ol>\n<li>ادخل إلى أبشر وافتح <strong>خدمات أفراد الأسرة</strong>، ثم <strong>خدمات التأشيرات</strong>.</li>\n<li>اختر فرد الأسرة وافتح تأشيرته.</li>\n<li>ادفع رسوم التمديد (بالسعر المضاعف للتأشيرة الممددة من الخارج، المذكور أعلاه)، ثم اضغط <strong>تمديد</strong>.</li>\n<li>تحقق من تاريخ العودة الجديد في الصفحة نفسها، أو في خدمة الاستعلام العام عن التأشيرات في مقيم.</li>\n</ol>\n<p>مدد قبل أن تنتهي التأشيرة: فالتمديد في أبشر يشترط أن تكون التأشيرة والإقامة كلتاهما ساريتين. ولا يقبل أبشر التمديد إلا إذا كان فرد الأسرة خارج السعودية يوم التقديم، وكان تاريخ العودة الجديد قبل انتهاء إقامته بسبعة أيام على الأقل، وبقي مجموع تمديد التأشيرة في حدود ١٨٠ يومًا. وإذا اختلف التاريخان الهجري والميلادي على الشاشة فالعبرة بالميلادي. وإن قاربت إقامته على الانتهاء فجددها أولًا: انظر <a href=\"/ar/guides/family-records-on-absher\">إقامات أسرتك وسجلاتها في أبشر</a>.</p>\n<h3>الاستعلام عن التأشيرة دون تسجيل الدخول</h3>\n<p>تُظهر خدمة الاستعلام العام عن التأشيرات في مقيم هل تأشيرة الخروج والعودة سارية، والتاريخ الذي يجب العودة قبله، برقم الإقامة وتاريخ الميلاد فقط. انظر <a href=\"/ar/guides/check-visa-and-iqama-online\">الاستعلام إلكترونيًا عن تأشيرتك ورقم الحدود والتأمين والمخالفات</a>.</p>\n<h2>الخروج النهائي</h2>\n<p>تأشيرة الخروج النهائي مجانية. وهي صالحة ٦٠ يومًا من يوم إصدارها، ويجب أن يبقى في الإقامة ٣٠ يومًا على الأقل، وتلغي الإقامة حين يعبر حاملها الحدود، فهي آخر ورقة تأخذها، بعد تسوية البنك والسيارة والشقة. وتُرفض ما دامت هناك مخالفات غير مدفوعة، أو سيارة مسجلة باسم الشخص، أو تابع متروك على إقامة غير مسواة. والعودة لاحقًا تعني تأشيرة جديدة باسمك. وإجراءات المغادرة كاملة في <a href=\"/ar/guides/graduate-procedures\">مغادرة المدينة نهائيًا</a>.</p>\n<h3>الخروج النهائي لزوجتك أو أبنائك</h3>\n<ol>\n<li>ادخل إلى أبشر وافتح <strong>خدمات أفراد الأسرة</strong>، ثم <strong>خدمات التأشيرات</strong>، واضغط «التالي».</li>\n<li>اختر فرد الأسرة، واضغط <strong>تفاصيل أكثر</strong>، ثم <strong>إصدار تأشيرة خروج نهائي</strong>. ثم وافق على الشروط وأكّد.</li>\n<li>اطبع التأشيرة، أو احفظها ملف PDF، من الشاشة نفسها.</li>\n</ol>\n<p>لا يصدرها أبشر إلا إذا كان فرد الأسرة داخل السعودية، بإقامة سارية وجواز صالح ٦٠ يومًا على الأقل، وليست عليه مخالفات غير مدفوعة، ولا سيارة مسجلة باسمه. ورسالة الخطأ «AC3052E: Insufficient funds» تعني أن على ملف ذلك الشخص رسومًا لم تُدفع بعد: ادفعها ثم أعد المحاولة.</p>\n<h3>الإلغاء، أو انقضاء المدة</h3>\n<ul>\n<li><strong>ألغها مجانًا ما دامت سارية،</strong> من الصفحة نفسها: خدمات أفراد الأسرة، ثم خدمات التأشيرات، ثم تفاصيل أكثر. وإدارة السفر هي التي تلغي الخروج النهائي للطالب نفسه.</li>\n<li><strong>لا يمكن تمديدها.</strong> إن تغيرت خططك فألغها وأصدر تأشيرة جديدة أقرب إلى الموعد.</li>\n<li><strong>عدم المغادرة خلال الستين يومًا غرامته ١٬٠٠٠ ريال.</strong> والخروج النهائي المنتهي لا يُلغى إلا في الجوازات، بموعد لخدمات المقيمين، ومعك نموذج الإلغاء، ونسخ من التأشيرة والإقامة والجواز، وصورتان بخلفية بيضاء، ورسوم تجديد الإقامة إن انتهت الإقامة في الأثناء.</li>\n<li><strong>احتفظ بالتأشيرة المطبوعة بعد مغادرتك.</strong> فالسفارة السعودية يمكن أن تطلبها حين تتقدم لاحقًا لتأشيرة سعودية جديدة.</li>\n</ul>\n<h2>إضافة الأسرة</h2>\n<ul>\n<li>إضافة تابع، أو مولود وُلد داخل السعودية، تتم في أبشر، ويُظهر أي رسوم قبل أن تدفع. وسجّل الولادة دون تأخير، فشهادة الميلاد المتأخرة عليها غرامة وتعطل تجديد الإقامة. وطلب المولود خطوة بخطوة مشروح في <a href=\"/ar/guides/having-a-baby-in-madinah#بعد-الولادة-الأوراق-خطوة-بخطوة\">الولادة في المدينة</a>.</li>\n<li>الطفل المولود خارج السعودية يحتاج أولًا إلى تأشيرة دخول تابعًا: ٢٬٠٠٠ ريال. وأضفه خلال ثلاثة أشهر من وصوله تجنبًا للغرامة.</li>\n<li>المقابل المالي الشهري للتابعين على إقامة العمل ٤٠٠ ريال عن كل تابع في الشهر. وإقامة الطالب ليست إقامة عمل، فاسأل إدارة السفر قبل أن تبني خطتك على ذلك.</li>\n</ul>\n<h2>تأشيرات الزيارة</h2>\n<ul>\n<li>تمديد تأشيرة الزيارة: ١٠٠ ريال في كل مرة، يطلبه المضيف في أبشر ابتداءً من ٧ أيام قبل انتهاء التأشيرة. وإن طُلب في الأيام الثلاثة التي تلي انتهاءها فعليه غرامة ٥٠٠ ريال فوق ذلك. واشترِ للزائر تأمينه الصحي الجديد أولًا، لأن أبشر يرفض التمديد بدونه.</li>\n<li>من يستطيع استضافة قريب، والتأشيرة الإلكترونية، وحد ١٨٠ يومًا، كل ذلك في <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a>.</li>\n</ul>\n<h2>بهوية زائر</h2>\n<p>الطلاب على التأشيرة التعليمية لا يحملون إقامة، فلا ينطبق عليهم شيء من الرسوم أعلاه. والمغادرة والعودة تتبعان تأشيرتك لا تأشيرة خروج وعودة: انظر <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a> قبل أن تحجز رحلة، واسأل عمادة القبول والتسجيل عبر تواصل، تحت موضوع «التأشيرة التعليمية»، إن تجاوزت خططك تواريخ التأشيرة.</p>\n<blockquote><p>نصيحة: رفض أبشر التأشيرة ولا تعرف السبب؟ راجع أولًا صفحة المخالفات، والاستعلام عن منع السفر، وتواريخ إقامة كل تابع وجوازه. وما زلت متعثرًا؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "janazah-al-baqi-and-when-someone-dies": {
  "titleAr": "صلاة الجنازة والبقيع وما تفعله حين يُتوفى أحد في المدينة",
  "summaryAr": "ما يجري في صلاة الجنازة بالمسجد النبوي، وكيف يُرتَّب الغسل والتكفين والدفن في المدينة، وشهادة الوفاة في أبشر، وخطوات نقل الجثمان إلى بلده، وكيف يعين الزملاء حين يُتوفى طالب من طلاب الجامعة.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. الوفاة بعيدًا عن الأهل شديدة، وإجراءاتها في بلد آخر تزيد من ثقلها. تشرح هذه الصفحة صلاة الجنازة التي تراها في المسجد النبوي، ثم تبين ما تفعله إن تُوفي أحد من أسرتك في المدينة: الدفن هنا، وشهادة الوفاة، والخطوات إن أرادت الأسرة نقل الجثمان إلى بلده. وفي آخرها كيف يعين الزملاء حين يُتوفى طالب من طلاب الجامعة.</p>\n<h2>صلاة الجنازة في المسجد النبوي</h2>\n<p>تُقام صلاة الجنازة في المسجد النبوي بعد كل صلاة مكتوبة تقريبًا، على ميت واحد أحيانًا وعلى عدة أموات أحيانًا أخرى. وتُحضر الأسر في المدينة موتاها إلى المسجد لتصلي عليهم جماعته الكبيرة.</p>\n<ul>\n<li><strong>النداء:</strong> بعد أن يسلّم الإمام من الصلاة المكتوبة مباشرة، يُذاع عبر مكبرات الصوت إعلان قصير بأن صلاة الجنازة تليها، مثل: <em>الصلاة على الأموات، يرحمكم الله</em>.</li>\n<li><strong>ابقَ في مكانك.</strong> تُقام الجنازة في الحال، خلف الإمام نفسه وفي الصفوف نفسها. فانتظر قبل أن تبدأ صلاة سنة أو تقوم للخروج.</li>\n<li><strong>الجنائز</strong> توضع في المقدمة أمام الإمام، وتُحمل إلى الخارج بمجرد انتهاء الصلاة.</li>\n</ul>\n<blockquote><p>ملاحظة: لمسائل الفقه في الجنازة أو الغسل أو الدفن اسأل عالمًا. وعلماء الجامعة وعلماء الحرم يجيبون عن الأسئلة.</p></blockquote>\n<h2>تشييع الجنازة إلى البقيع</h2>\n<p>بعد الصلاة تُحمل الجنائز من المسجد إلى البقيع، المقبرة الواقعة في جهته الشرقية، لتُدفن فيه. ومن أراد من الرجال تشييع الجنازة مشى معها من المسجد. والدخول إلى البقيع للرجال فقط.</p>\n<p>زيارة البقيع في غير هذه الأوقات، وبوابة أمانة المدينة لحجز الزيارة، مشروحتان في <a href=\"/ar/ask/visiting-al-baqi\">هل أستطيع زيارة البقيع؟</a> و<a href=\"/ar/guides/masjid-an-nabawi-first-visit\">زيارة المسجد النبوي: دليل الزيارة الأولى</a>. ولمعرفة مكان قبر شخص ما، تُظهر خدمة البحث عن القبور على البوابة نفسها المقبرة وتاريخ الدفن.</p>\n<h2>إذا تُوفي أحد من أسرتك في المدينة</h2>\n<ul>\n<li><strong>في المستشفى،</strong> يثبت المستشفى الوفاة ويبلّغ عنها إلكترونيًا. والدفن وشهادة الوفاة كلاهما يقومان على هذا البلاغ، فلا شيء عليك تسجيله في هذه المرحلة.</li>\n<li><strong>في البيت أو في أي مكان آخر،</strong> اتصل بالرقم <strong>997</strong> للإسعاف، أو بالرقم <strong>911</strong>. وإدارة إكرام الموتى في أمانة المدينة المنورة تتولى الوفاة خارج المستشفى، وفي بوابتها خدمة للإبلاغ عن وفاة لم يصدر لها تصريح دفن من مستشفى.</li>\n<li><strong>أبلغ سفارتك أو قنصليتك</strong> مبكرًا، سواء كان الدفن في المدينة أو في بلد المتوفى.</li>\n<li><strong>حدد مكان الدفن.</strong> فكل ما بعده يتبع هذا الاختيار. وإن كانت الأسرة في الخارج فاتفقوا على شخص واحد هنا يتكلم باسمها.</li>\n</ul>\n<p>أرقام الطوارئ كلها في <a href=\"/ar/ask/emergency-numbers\">ما أرقام الطوارئ في السعودية؟</a></p>\n<h2>الغسل والتكفين والدفن في المدينة</h2>\n<p>تتولى أمانة المدينة المنورة العناية بالموتى عبر بوابة البقيع على <a href=\"https://ekram.amana-md.gov.sa/\">ekram.amana-md.gov.sa</a>، وهو الموقع نفسه الذي تُحجز منه الزيارات، وعبر منصة بلدي الوطنية. ومعظم الخطوات تتم إلكترونيًا دون مراجعة أي مكتب.</p>\n<ul>\n<li><strong>النقل والتجهيز:</strong> اطلبه إلكترونيًا. وتحدد الإدارة موعدًا لنقل الجثمان وتجهيزه بالغسل والتكفين، ليكون جاهزًا لصلاة الجنازة.</li>\n<li><strong>الجمعيات الخيرية:</strong> الجمعيات الخيرية المسجلة في المدينة تنقل الموتى وتجهزهم أيضًا. وتعرضها منصة بلدي مرتبة حسب المدينة، مع موقعها ورقم التواصل معها. وهي تستلم من المستشفيات فقط.</li>\n<li><strong>القبر:</strong> الدفن في البقيع أو في مقبرة أخرى من مقابر المدينة. وتُحجز المقبرة والموعد على منصة بلدي ببيانات المتوفى، وتؤكد الأمانة الموعد أو تعدّله مع الأسرة.</li>\n<li><strong>شهادة الدفن:</strong> بعد الدفن يطبعها مستلم الجثمان من منصة بلدي، بعد تأكيد رقم الجوال المسجل له.</li>\n</ul>\n<h2>شهادة الوفاة</h2>\n<p>تصدر شهادة الوفاة الرسمية من الأحوال المدنية عبر أبشر، بعد أن يدخل بلاغ المستشفى في النظام. وتصدرها أنت في أبشر، وتحتاج إلى حساب مفعّل.</p>\n<ol>\n<li>سجّل الدخول إلى <a href=\"https://www.absher.sa/\">absher.sa</a> بصفتك فردًا.</li>\n<li>افتح «خدماتي»، ثم «الأحوال المدنية»، ثم «خدمات شهادات الوفاة».</li>\n<li>اختر البلاغ من قائمة الوفيات التي لم تصدر لها شهادة.</li>\n<li>وافق على الإقرار وأكّد الإصدار.</li>\n</ol>\n<p>يصدرها أحد أقارب المتوفى المباشرين: الأب أو الأم، أو الابن أو البنت، أو الزوج أو الزوجة. ويصدرها صاحب العمل لموظفه. والشهادة تصدر مرة واحدة فقط، ثم تبقى في أبشر لتطلع عليها الأسرة، ويمكن التحقق من نسخة منها بخدمة «التحقق من شهادة الوفاة» على <a href=\"https://my.gov.sa/\">my.gov.sa</a>. واحتفظ بعدة نسخ مطبوعة.</p>\n<h2>نقل الجثمان إلى بلده</h2>\n<ol>\n<li><strong>تواصل مع سفارتك أو قنصليتك أولًا.</strong> فهي تشرح أوراقها الخاصة، وتصدر خطاب عدم الممانعة الذي يسمح بخروج الجثمان من المملكة.</li>\n<li><strong>سلّم السفارة موافقة أقرب الأقارب.</strong> وإن كانوا في الخارج طلبتها السفارة مكتوبة.</li>\n<li><strong>أصدر شهادة الوفاة</strong> كما سبق. فالسفارة وشركة الطيران كلتاهما تطلبانها.</li>\n<li><strong>أنهِ سجل المتوفى لدى الجوازات.</strong> يُسجَّل خروجه على الإقامة، وتُسدَّد أي مخالفات عليها أولًا.</li>\n<li><strong>التحنيط</strong> مطلوب قبل نقل الجثمان جوًا، ويصدر المستشفى شهادة تحنيط.</li>\n<li><strong>احجز الرحلة.</strong> تطلب شركات الطيران عدة نسخ مصدقة من كل مستند، فجهزها مبكرًا.</li>\n</ol>\n<h2>الأوراق بعد ذلك</h2>\n<ul>\n<li><strong>الإقامة:</strong> يتولاها الكفيل لدى الجوازات. وفي حال الزوجة أو الولد فالكفيل أنت بصفتك رب الأسرة. وسجلات أسرتك في أبشر مشروحة في <a href=\"/ar/guides/family-records-on-absher\">إقامات أسرتك وسجلاتها في أبشر</a>.</li>\n<li><strong>الطالب الذي يحمل إقامة:</strong> إدارة السفر في الجامعة تتولى إقامات الطلاب. فاكتب إليها عبر تواصل.</li>\n<li><strong>الطالب الذي يحمل هوية زائر:</strong> اكتب إلى عمادة القبول والتسجيل عبر تواصل، بموضوع «التأشيرة التعليمية».</li>\n</ul>\n<h2>حين يُتوفى طالب من طلاب الجامعة</h2>\n<p>أبلغ الجامعة في الحال: كلية الطالب، ورعاية الطلاب على الرقم <strong>920022042</strong> أو <a href=\"mailto:care@iu.edu.sa\">care@iu.edu.sa</a>. والأسرة في الخارج هي التي تختار بين الدفن في المدينة ونقل الجثمان إلى بلده، والسفارة تعمل معها على ذلك. وكل المكاتب وجهات الاتصال في <a href=\"/ar/guides/university-offices-and-contacts\">من تسأل في الجامعة الإسلامية: المكاتب والبوابات وجهات الاتصال</a>.</p>\n<p>يحمل الزملاء والأصدقاء كثيرًا من العبء في الأيام الأولى. ومن طرق العون:</p>\n<ul>\n<li><strong>صوت واحد للأسرة.</strong> اتفقوا على شخص واحد، قريب أو صديق مقرب، يتحدث مع الأسرة، لتصلها أخبار هادئة وواضحة لا رسائل كثيرة.</li>\n<li><strong>انشروا موعد الجنازة</strong> في مجموعات الفصل والسكن بعد تأكيده، ليصلي عليه الزملاء.</li>\n<li><strong>رافقوا من يتولى الأوراق</strong> إلى المستشفى أو السفارة أو الجوازات، وترجموا له، واحتفظوا بنسخة من كل مستند.</li>\n<li><strong>احفظوا جواز الطالب وإقامته أو هوية الزائر وبطاقته الجامعية</strong> للأسرة، واسألوا شؤون الطلاب قبل نقل أي شيء من غرفته في السكن.</li>\n<li><strong>لا تنشروا الأخبار والصور على وسائل التواصل الاجتماعي</strong> حتى تُبلَّغ الأسرة.</li>\n</ul>\n<blockquote><p>نصيحة: دوّن كل خطوة وقت حدوثها: من كلّمت، والتاريخ، وأي رقم مرجعي. فالأسرة والسفارة والجامعة ستسأل كل منها، وسجل مكتوب واحد يغنيك عن التكرار في أسبوع صعب.</p></blockquote>"
 },
 "kids-activities": {
  "titleAr": "أماكن اللعب والترفيه للأطفال في المدينة",
  "summaryAr": "مراكز اللعب الداخلية وحضانات المجمعات التجارية والحدائق للأطفال الصغار في المدينة، مع الأعمار التي يستقبلها كل مكان وما فيه.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. في المدينة مراكز لعب داخلية، وحضانات في المجمعات التجارية، وحدائق فيها ألعاب، وهي طريقة جيدة لقضاء ساعات العصر الحارة مع الأطفال الصغار. والأماكن في كل قسم أدناه مرتبة أبجديًا بأسمائها اللاتينية. ويُدفع رسم الدخول عن كل طفل عند مكتب الاستقبال.</p>\n<h2>مراكز اللعب الداخلية</h2>\n<h3>كينتك (Kinetic)</h3>\n<ul>\n<li><strong>الأعمار:</strong> من سنة إلى ١٣ سنة.</li>\n<li><strong>ما فيه:</strong> طابقان للعب، وفي الطابق العلوي منطقة للأطفال دون الثالثة، ومقهى.</li>\n<li><a href=\"https://maps.app.goo.gl/sjH7sompZUFuZGPL9\">الموقع على خرائط جوجل</a></li>\n</ul>\n<h3>بيكبو (Peekboo)</h3>\n<ul>\n<li><strong>ما فيه:</strong> مركز لعب داخلي كبير فيه مقهى، في مبنى يضم مطاعم ومقاهي كثيرة.</li>\n<li><a href=\"https://maps.app.goo.gl/HHUiSx6Ln8s4DbUq9\">الموقع على خرائط جوجل</a></li>\n</ul>\n<h3>بوكي (Poky)</h3>\n<ul>\n<li><strong>المكان:</strong> داخل Wow 5! (سوق الخمسة ريالات).</li>\n<li><strong>الأعمار:</strong> من سنة إلى ١٠ سنوات.</li>\n<li><strong>ما فيه:</strong> طابقان للعب، وفي الطابق الأعلى منطقة للرضع وصغار الأطفال.</li>\n<li><a href=\"https://maps.app.goo.gl/RFS3ftpoG8AVNn8P9\">الموقع على خرائط جوجل</a></li>\n</ul>\n<h2>حضانات المجمعات التجارية لمن دون الخامسة</h2>\n<p>يمكنك أن تترك طفلك دون الخامسة في هذه الحضانات، أو أن تبقى معه وتلعب.</p>\n<ul>\n<li><strong>النور مول:</strong> زحليقة تنتهي في حوض كرات، وهيكل للتسلق، وأنشطة أخرى. وفي المجمع منطقة لعب ثانية أيضًا: <a href=\"https://maps.app.goo.gl/1xB4qFEvuGpt1vjA6\">موقعها على خرائط جوجل</a>.</li>\n<li><strong>الراشد مول:</strong> الحضانة في الدور السفلي، قرب هوم سنتر، وفيها حوض كرات وزحاليق وطاولات أنشطة وأركان للعب الأدوار، منها ركن على هيئة مطبخ. وهي للأطفال دون الخامسة فقط.</li>\n</ul>\n<h2>الحدائق والمتنزهات</h2>\n<p>في حدائق مثل ريف البستان قلاع هوائية للقفز وألعاب مثل القطارات الصغيرة.</p>\n<blockquote><p>نصيحة: كثير من ألعاب صالات الترفيه في المجمعات التجارية والقلاع الهوائية الكبيرة في الحدائق مصممة للأطفال من سن الرابعة فما فوق. ولصغار الأطفال مناطقهم الخاصة في مراكز اللعب الداخلية المذكورة أعلاه.</p></blockquote>\n<p>وعن المدارس والحضانات انظر <a href=\"/ar/guides/kindergartens-and-schools\">رياض الأطفال والمدارس</a>. ومراكز الأطفال في الحرم مذكورة في <a href=\"/ar/guides/women-at-masjid-an-nabawi\">المسجد النبوي للأخوات والأسر</a>.</p>\n<blockquote><p>نصيحة: هل تعرف مكانًا للأطفال يستحق أن نضيفه؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "kindergartens-and-schools": {
  "titleAr": "الروضات والمدارس لأطفالك",
  "summaryAr": "الروضات، ونظام التعليم في السعودية، ومستندات التسجيل، ونظام نور، ونقل الطالب من مدرسة إلى أخرى، والرسوم المعتادة، ومدارس القرآن والعلوم الشرعية المجانية، وحلقات القرآن في مساجد الأحياء.",
  "bodyHtmlAr": "<p>في المدينة روضات ومدارس أهلية كثيرة، وكثير منها يقبل الأطفال الذين يحمل آباؤهم تأشيرة زيارة، لا أبناء حاملي الإقامة وحدهم. فإن ترددت مدرسة، فاسأل مرة أخرى بأدب وألحّ في الطلب.</p>\n<h2>الروضة</h2>\n<ul>\n<li><strong>السن:</strong> من ثلاث سنوات.</li>\n<li><strong>اليوم الدراسي:</strong> التوصيل نحو الساعة ٧:٠٠، والحصص من ٧:٣٠، والانصراف في ١٢:٠٠.</li>\n<li><strong>الرسوم:</strong> نحو ٤٬٠٠٠ ريال في السنة للطفل، تُدفع كل فصل، مع خصم للإخوة. والرسوم نفسها لأسر التأشيرة وأسر الإقامة.</li>\n<li><strong>اللغة:</strong> بعض الفصول بالعربية، وبعضها يتبع برامج دولية قائمة على الإنجليزية.</li>\n</ul>\n<h2>ما تحضره</h2>\n<ol>\n<li>شهادة ميلاد طفلك.</li>\n<li>جوازات السفر بتأشيرات سارية.</li>\n<li>صورة شخصية.</li>\n<li>شهادة طبية إن طُلبت. والعيادات الخاصة تجري الفحص بنحو ١٥٠ ريالًا.</li>\n</ol>\n<h2>المدارس</h2>\n<p>المدارس الحكومية والمدارس الأهلية السعودية تعلّم البنين والبنات منفصلين. وكثير من المدارس العالمية تجمعهم في السنوات الأولى، فتحقق من سياسة كل مدرسة. والمدارس العالمية تتبع المناهج البريطانية أو الأمريكية أو البكالوريا الدولية أو مناهج وطنية أخرى. ولا تقبل المدارس الحكومية الأطفال الموجودين في المملكة بتأشيرة زيارة أو سياحة أو عمرة. وابن حامل الإقامة لا يلتحق بها إلا بخطاب إذن من وزارة التعليم، يتوقف على توفر مقاعد لغير السعوديين، وخطاب من جهة عمل ولي الأمر. وبعض المدارس الأهلية أيضًا لا تقبل إلا الأطفال حاملي الإقامة، فاسأل كل مدرسة قبل أن ترتب أمورك. وعدة مدارس تمنح أسر الجامعة الإسلامية خصمًا (انظر <a href=\"/ar/discounts\">خصومات الطلاب</a>).</p>\n<h3>نظام التعليم في السعودية</h3>\n<table><thead><tr><th>المرحلة</th><th>السن</th><th>المدة</th></tr></thead><tbody>\n<tr><td>الروضة</td><td>من ٣ إلى ٦</td><td>حتى ٣ سنوات</td></tr>\n<tr><td>الابتدائية</td><td>من ٦</td><td>٦ سنوات</td></tr>\n<tr><td>المتوسطة</td><td>من ١٢</td><td>٣ سنوات</td></tr>\n<tr><td>الثانوية</td><td>من ١٥</td><td>٣ سنوات</td></tr>\n</tbody></table>\n<p>أيام الدراسة من الأحد إلى الخميس، من نحو الساعة ٧:٠٠ إلى ١٣:٠٠ أو ١٤:٠٠.</p>\n<h3>مستندات الطفل في سن المدرسة</h3>\n<ul>\n<li>إقامة ولي الأمر وجوازه.</li>\n<li>جواز الطفل، وإقامته إن كانت له إقامة.</li>\n<li>شهادة الميلاد، مصدقة ومترجمة إلى العربية.</li>\n<li>سجل التطعيمات.</li>\n<li>الشهادات المدرسية للسنتين أو السنوات الثلاث الأخيرة، مترجمة ومصدقة إن لم تكن بالعربية أو الإنجليزية.</li>\n<li>شهادة المغادرة من آخر مدرسة.</li>\n<li>من أربع إلى ثماني صور شخصية.</li>\n</ul>\n<h3>نور، نظام الوزارة للمدارس</h3>\n<p>بعد قبول طفلك تسجله المدرسة في نور، نظام وزارة التعليم، وفيه تُسجَّل الشهادات والانتقال من صف إلى صف. ويدخل الآباء إلى نور عبر نفاذ للاطلاع على النتائج والحضور والتقييمات.</p>\n<h3>نقل الطالب أثناء العام</h3>\n<ol>\n<li>تأكد أن في المدرسة الجديدة مقعدًا.</li>\n<li>اطلب من المدرسة الحالية شهادة نقل.</li>\n<li>تكمل المدرسة الجديدة النقل في نور.</li>\n</ol>\n<p>المدارس الأهلية تتقاضى في العادة رسوم الفصل الذي أنت فيه كاملة، فاجعل النقل في نهاية فصل.</p>\n<h3>رسوم المدارس الأهلية</h3>\n<p>المدارس الأهلية على المسار السعودي تتقاضى نحو ٩٬٠٠٠ إلى ٢٥٬٠٠٠ ريال في السنة، وتزيد مع كل مرحلة، والمسارات العالمية بالإنجليزية أغلى. والزي والكتب والحافلة المدرسية خارج الرسوم، والحافلة وحدها تضيف ٣٬٠٠٠ ريال أو أكثر في السنة. وبعض المدارس تخصم ١٠٪ للإخوة والأخوات وتقبل الرسوم على ثلاث دفعات. وبعض المدارس الأهلية تغلق التسجيل للعام الجديد في أواخر أغسطس، والمدارس العالمية تفتحه من يناير أو فبراير، فقدّم مبكرًا في أول العام.</p>\n<h2>مدارس القرآن والعلوم الشرعية المجانية</h2>\n<p>مرتبة ترتيبًا أبجديًا.</p>\n<table><thead><tr><th>المدرسة</th><th>السن والمدة</th><th>من يلتحق بها</th><th>ما تطلبه</th></tr></thead><tbody>\n<tr><td>حلقات المسجد النبوي</td><td>من ٥ سنوات، بلا حد للنهاية</td><td>الأطفال والكبار بإقامة أو بأي تأشيرة</td><td>جواز بتأشيرة أو إقامة، ورقم جوال سعودي. والتسجيل على <a href=\"https://reg.qm.edu.sa/\">reg.qm.edu.sa</a> في أي وقت من السنة</td></tr>\n<tr><td>دار الحديث</td><td>من ١١ سنة، لمدة ٦ سنوات: ٣ متوسط و٣ ثانوي</td><td>الأطفال حاملو الإقامة</td><td>القراءة والكتابة بالعربية؛ وحفظ جزأين إلى ثلاثة للمتوسط، وأربعة إلى خمسة للثانوي؛ وآخر شهادة مدرسية مصدقة ومترجمة إلى العربية ومعادلة في مكتب وزارة التعليم؛ والتسجيل إلكترونيًا، ثم اختبار تحديد مستوى حضوري في مايو أو يونيو</td></tr>\n<tr><td>معهد المسجد النبوي</td><td>من ١٢ سنة للمتوسط، ومن ١٥ للثانوي، ٣ سنوات لكل منهما</td><td>حاملو الإقامة، بموافقة مكتوبة من الكفيل</td><td>العربية، وحفظ القرآن، واختبار تحريري ومقابلة. وفترة تسجيل واحدة في السنة: كانت لعام ١٤٤٨ من ٥ إلى ٢٠ صفر (من ١٩ يوليو إلى ٣ أغسطس ٢٠٢٦). انظر <a href=\"/ar/guides/masjid-an-nabawi-institute-and-college\">معهد المسجد النبوي وكلية المسجد النبوي</a></td></tr>\n</tbody></table>\n<ul>\n<li>تدرّس دار الحديث القرآن والعلوم الشرعية والعربية والتاريخ والرياضيات، وتصرف لطلابها مكافأة شهرية قدرها نحو ٣٠٠ ريال في المرحلة المتوسطة و٣٥٠ ريالًا في الثانوية. ولخريجيها أولوية في القبول بالجامعة الإسلامية. ومن أراد مجالًا آخر كالطب أو الهندسة انتقل إلى مدرسة ثانوية حكومية بعد المتوسطة.</li>\n<li>تنعقد الحلقات بعد الفجر أو الضحى، وبين العصر والمغرب، وبين المغرب والعشاء، وبعض الفصول عن بُعد. وحلقات الرجال عند الباب ٢٢ في الدور الأول، وحلقات النساء عند الباب ٢٤ أو الباب ١٣ في الدور الثاني. وتمنح مكافآت يسيرة على اجتياز اختبارات الحفظ، تُحوَّل إلى حساب بنكي، فاجعل خطاب الآيبان من بنكك جاهزًا.</li>\n</ul>\n<h2>حلقات القرآن</h2>\n<p>أكثر مساجد الأحياء تقيم حلقات تحفيظ القرآن بعد العصر أو المغرب، وتبدأ عادةً بجزء عمّ والتجويد والقراءة. اسأل إمام مسجد حيّك. والمسجد النبوي أيضًا يقيم حلقات للأطفال (انظر أعلاه).</p>"
 },
 "living-on-a-visitor-id": {
  "titleAr": "العيش بهوية زائر: ما يعمل وما لا يعمل",
  "summaryAr": "الطلاب الجدد على التأشيرة التعليمية يحصلون على هوية زائر لا إقامة. البنك والشريحة وأبشر والإيجار والقيادة والسفر والأسرة، جنبًا إلى جنب مع الإقامة.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. الطلاب الذين يصلون على التأشيرة التعليمية (تأشيرة الطالب) يُمنحون هوية زائر رقمية مرتبطة برقم الحدود. ولا تُصدر لهم إقامة. ومعظم الحياة اليومية يعمل بهوية الزائر، لكن بعض الأمور تحتاج خطوات مختلفة، وقليلها مقصور على حاملي الإقامة. وهذه الصفحة تضع الحالتين جنبًا إلى جنب.</p>\n<h2>ما هوية الزائر</h2>\n<ul>\n<li>تصدرها المديرية العامة للجوازات عبر حسابك في أبشر، وترتبط <strong>برقم الحدود</strong>، وهو الرقم المكوّن من ١٠ أرقام الذي تعطيك إياه الجوازات عند دخولك المملكة أول مرة. وتكتبه الجوازات بخط اليد في جوازك، وتجده خدمة الاستعلام العام عن رقم الحدود في أبشر برقم التأشيرة وتاريخ إصدارها.</li>\n<li>وهي رقمية فقط ولا تُطبع على ورق.</li>\n<li>والتأشيرة التعليمية طويلة الأمد التي وراءها صالحة لسنة واحدة وتُجدد كل سنة ما دمت تدرس.</li>\n<li>وتقبل الجوازات هوية الزائر الرقمية إثباتًا رسميًا للهوية داخل المملكة، فتستطيع إظهارها من جوالك عند نقاط التفتيش والمكاتب.</li>\n<li>ويبقى جوازك هو وثيقة سفرك. احمله للطيران ولأي بنك أو مكتب يطلب رؤيته.</li>\n<li>وكل ما يرتبط بهوية الزائر، كالحساب البنكي، يعمل ما دامت تأشيرتك سارية. فراقب تاريخ الانتهاء في أبشر.</li>\n</ul>\n<h2>هوية الزائر والإقامة جنبًا إلى جنب</h2>\n<table><thead><tr><th>الموضوع</th><th>هوية الزائر (التأشيرة التعليمية)</th><th>الإقامة</th></tr></thead><tbody>\n<tr><td><strong>أبشر ونفاذ</strong></td><td>سجّل برقم الحدود</td><td>سجّل برقم الإقامة</td></tr>\n<tr><td><strong>الحساب البنكي وبطاقة مدى</strong></td><td>نعم، في الفرع أو عبر الإنترنت بنفاذ. ويُجمَّد الحساب حين تنتهي هوية الزائر</td><td>نعم، في تطبيق البنك أو في الفرع</td></tr>\n<tr><td><strong>شريحة الجوال</strong></td><td>نعم، مسجلة على جوازك ورقم الحدود بالبصمة</td><td>نعم، مسجلة على إقامتك</td></tr>\n<tr><td><strong>إنترنت الألياف في البيت</strong></td><td>لا. استعمل جهاز توجيه 5G بشريحة بيانات</td><td>نعم</td></tr>\n<tr><td><strong>عقد الإيجار في إيجار</strong></td><td>نعم، عن طريق وسيط معتمد في إيجار</td><td>نعم، ينشئه وسيط معتمد أو المالك وتوافق عليه أنت</td></tr>\n<tr><td><strong>رخصة القيادة السعودية</strong></td><td>لا</td><td>نعم، باستبدال رخصتك الأجنبية</td></tr>\n<tr><td><strong>شراء سيارة أو تسجيلها</strong></td><td>لا</td><td>نعم</td></tr>\n<tr><td><strong>تصاريح العمرة والروضة في نسك</strong></td><td>نعم</td><td>نعم</td></tr>\n<tr><td><strong>الحج من داخل المملكة</strong></td><td>اسأل الجامعة قبل أن تسجل أو تدفع ثمن باقة</td><td>نعم، عبر نسك حين يفتح التسجيل</td></tr>\n<tr><td><strong>السفر إلى الخارج</strong></td><td>تحقق في أبشر أن تأشيرتك تغطي موعد عودتك، واتبع إشعار الجامعة عن السفر في الإجازات</td><td>تأشيرة خروج وعودة من أبشر قبل كل رحلة</td></tr>\n<tr><td><strong>رسوم إقامتك أنت</strong></td><td>لا شيء</td><td>لا شيء على إقامة الطالب نفسه. والمرافقون يدفعون</td></tr>\n</tbody></table>\n<h2>الحصول على هوية الزائر</h2>\n<p>أدِّ هذه الخطوات بالترتيب، لأن كل خطوة تحتاج إلى التي قبلها. والأسبوع الأول كاملًا، مع البطاقة الجامعية وحسابات الجامعة، في <a href=\"/ar/guides/new-student-steps\">الخطوات الأولى للطلاب الجدد</a>.</p>\n<ol>\n<li><strong>اشترِ شريحة سعودية.</strong> خذ جوازك إلى أي فرع لشركة اتصالات. يُسجَّل الخط على جوازك ورقم الحدود، ويأخذون بصمتك. وتحتاج هذا الرقم لكل رمز تحقق بعد ذلك.</li>\n<li><strong>سجّل في أبشر</strong> مستخدمًا جديدًا برقم الحدود وبريدك الإلكتروني ورقم جوالك الجديد.</li>\n<li><strong>فعّل أبشر من جهاز الخدمة الذاتية.</strong> الأجهزة موجودة في مكاتب الجوازات وفي الجامعة وفي المطارات وفي بعض المجمعات التجارية. أدخل رقم الحدود وسجّل بصمتك.</li>\n<li><strong>فعّل نفاذ</strong> في تطبيق نفاذ: افتح الإعدادات، واختر تفعيل الهوية الرقمية الوطنية، وأكمل بياناتك والتحقق بالوجه. فالبنوك وإيجار ومعظم المواقع الحكومية تتحقق من هويتك عبر نفاذ.</li>\n<li><strong>أصدر هوية الزائر</strong> في أبشر: اختر <strong>إصدار هوية زائر</strong> وأكمل البيانات. ثم تظهر في التطبيق.</li>\n<li><strong>سجّل عنوانك الوطني</strong> في البريد السعودي. فالبنوك تحتاج عنوانًا في السعودية، وخدمات التوصيل تستعمله. انظر <a href=\"/ar/ask/short-address\">ما العنوان المختصر؟</a></li>\n<li><strong>افتح حسابًا بنكيًا</strong> (أدناه).</li>\n</ol>\n<blockquote><p>ملاحظة: إذا تكرر فشل تفعيل أبشر أو نفاذ فاتصل بخدمة عملاء أبشر على <strong>920020405</strong>، واختر اللغة الإنجليزية، وأدخل رقم الحدود، واطلب فتح تذكرة دعم فني. وقل إنك طالب منحة دولي جديد على تأشيرة طالب ومعك رقم حدود. ويستغرق الحل أحيانًا بضعة أيام. انظر <a href=\"/ar/ask/absher-nafath-activation\">تفعيل أبشر أو نفاذ يفشل عندي باستمرار</a>.</p></blockquote>\n<h2>البنك</h2>\n<p>يسمح البنك المركزي السعودي للبنوك بفتح حسابات لحاملي هوية الزائر الصادرة من وزارة الداخلية. ويجب أن يدوّن البنك عنوانك في السعودية وعنوانك في بلدك والغرض من إقامتك، ولا يستطيع إبقاء الحساب عاملًا بعد انتهاء تأشيرتك.</p>\n<ol>\n<li>تأكد أن هوية الزائر تظهر سارية في أبشر، وأن عنوانك الوطني مسجل، وأن رقم جوالك مرتبط بأبشر.</li>\n<li><strong>في الفرع:</strong> خذ جوازك وأظهر هوية الزائر في تطبيق أبشر. <strong>عبر الإنترنت:</strong> قدّم الطلب في تطبيق البنك أو موقعه وأكّد هويتك عبر نفاذ.</li>\n<li>قل إنك طالب في الجامعة الإسلامية على التأشيرة التعليمية، وأعطهم عنوانك في بلدك.</li>\n<li>يصلك رقم الحساب برسالة نصية. استلم بطاقة مدى من الفرع أو اطلب إرسالها بالبريد.</li>\n<li>حسابك الخاص للتحويلات والإنفاق اليومي. أما المكافأة نفسها فتُصرف على <a href=\"/ar/guides/getting-your-stipend-off-the-university-card\">بطاقة المكافأة الجامعية</a>، ومنها تنقلها إلى حسابك.</li>\n</ol>\n<blockquote><p>نصيحة: تطبّق البنوك القواعد بطرق مختلفة من فرع إلى فرع. فإن رفض فرع فجرّب فرعًا آخر أو بنكًا آخر.</p></blockquote>\n<h2>الجوال والإنترنت</h2>\n<ul>\n<li>إنترنت الألياف الثابت يحتاج إلى إقامة. وبهوية الزائر ضع شريحة بيانات غير محدودة في جهاز توجيه 5G محمول ليكون عندك واي فاي في البيت.</li>\n<li>إن توقف خطك فخذ جوازك إلى فرع شركتك. ثم حدّث الرقم في أبشر لتظل رموزك تصلك: انظر <a href=\"/ar/guides/phone-sims-and-absher\">رقم جوالك والتحقق من الشرائح وأبشر</a>.</li>\n</ul>\n<h2>استئجار شقة</h2>\n<p>تستطيع تسجيل عقد إيجار في منصة إيجار بهوية الزائر. ويقوم بذلك وسيط معتمد نيابة عنك.</p>\n<ol>\n<li>ابحث عن شقة واتفق على الأجرة ومدة العقد وطريقة الدفع.</li>\n<li>اختر وسيطًا عقاريًا من قائمة إيجار الرسمية للوسطاء المعتمدين.</li>\n<li>أعطِ الوسيط بياناتك وبيانات المالك. يُدخل الوسيط العقد في إيجار.</li>\n<li>يصلك أنت والمالك رابط برسالة نصية. راجع البيانات ووافق.</li>\n</ol>\n<p>العقد المسجل يحمي الطرفين. والمزيد عن اختيار الشقة في <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a>.</p>\n<h2>القيادة والسيارات</h2>\n<ul>\n<li>رخصة القيادة السعودية وتملك السيارة كلاهما يحتاج إلى إقامة، فليس أي منهما متاحًا بهوية الزائر.</li>\n<li>تستطيع القيادة برخصتك إن كانت السعودية تعترف برخصة بلدك. واحمل الأصل. ولشركات تأجير السيارات قواعدها، وكثير منها يطلب رخصة قيادة دولية.</li>\n<li>المخالفات المرورية تظهر في أبشر تحت المخالفات. ادفعها من تطبيق بنكك.</li>\n</ul>\n<p>وحين تحمل إقامة فالاستبدال في <a href=\"/ar/guides/drivers-license\">القيادة في المدينة: رخصة القيادة السعودية</a>.</p>\n<h2>العمرة والروضة والحج</h2>\n<ul>\n<li>احجز تصاريح العمرة والروضة في تطبيق نسك. انظر <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء</a>.</li>\n<li>الحج من داخل المملكة يُحجز في نسك حين يفتح التسجيل، وتأشيرة الزيارة لا تسمح بالحج. وقبل أن تسجل أو تدفع ثمن باقة بهوية الزائر اسأل الجامعة عبر تواصل هل أنت مؤهل.</li>\n</ul>\n<h2>الأسرة</h2>\n<p>تأشيرات الأسرة للطلاب على التأشيرة التعليمية تمر بإجراءات الجامعة نفسها، فاسأل الجامعة عبر تواصل قبل أن تخطط. وكثير من الزوجات والأبناء والآباء يأتون على تأشيراتهم الخاصة، وأكثرها التأشيرة السياحية الإلكترونية حين يكون جوازهم مؤهلًا لها. والخيارات وقواعد التمديد في <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a>. ويستطيع الأطفال الالتحاق بكثير من الروضات والمدارس الأهلية: انظر <a href=\"/ar/guides/kindergartens-and-schools\">رياض الأطفال والمدارس</a>.</p>\n<h2>قبل أن تنتهي هوية الزائر</h2>\n<p>حسابك البنكي وبطاقة مدى وكل ما يرتبط بهوية الزائر يتوقف حين تنتهي، حتى تُجدَّد. فتعامل معه كموعد نهائي.</p>\n<ol>\n<li>دوّن تاريخ الانتهاء الظاهر في أبشر، وضع تذكيرين قبله بشهر وبأسبوع. وتستطيع أيضًا التحقق من تأشيرتك دون تسجيل الدخول عبر خدمة الاستعلام العام عن التأشيرات في مقيم، برقم التأشيرة ورقم جوازك: انظر <a href=\"/ar/guides/check-visa-and-iqama-online\">الاستعلام إلكترونيًا عن تأشيرتك ورقم الحدود والتأمين والمخالفات</a>.</li>\n<li>اسأل الجامعة عن التجديد قبل ذلك التاريخ بوقت كافٍ، عبر تواصل.</li>\n<li>احتفظ بما يكفي من النقد أو ببطاقة أجنبية تعمل لتمضي بضعة أيام إن جُمدت بطاقتك السعودية.</li>\n<li>بعد التجديد تحقق أن التاريخ الجديد يظهر في أبشر وأن بنكك عنده. فإن بقيت بطاقتك مجمدة فخذ جوازك إلى الفرع.</li>\n<li>إن توقف خطك فخذ جوازك إلى شركتك، ثم حدّث الرقم في أبشر لتظل رموزك تصلك.</li>\n</ol>\n<p>والطلاب العائدون بعد تأجيل أو اعتذار أو انقطاع عن الدراسة يطلبون تأشيرة جديدة على «منحتي» في <a href=\"https://minhatee2.iu.edu.sa/Home/VisaLanding\">minhatee2.iu.edu.sa</a>، بالدخول برقمهم الجامعي.</p>\n<h2>حين لا يعمل شيء</h2>\n<p>أرسل أسئلتك عن التأشيرة التعليمية إلى الجامعة عبر تواصل:</p>\n<ol>\n<li>ادخل إلى صفحتك الطلابية وافتح <strong>تواصل</strong>.</li>\n<li>اختر <strong>عمادة القبول والتسجيل</strong>.</li>\n<li>اختر الموضوع <strong>التأشيرة التعليمية</strong> واشرح حالتك كاملة: ما جربته، وأين، وماذا قيل لك.</li>\n<li>تابع بريدك الجامعي. فالرد يصل إليه.</li>\n</ol>\n<p>وبقية المكاتب وجهات الاتصال في <a href=\"/ar/guides/university-offices-and-contacts\">من تسأل في الجامعة الإسلامية</a>.</p>\n<blockquote><p>نصيحة: ما زلت متعثرًا؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "lost-your-iqama-passport-or-card": {
  "titleAr": "فقدت جوازك أو إقامتك أو جوالك أو بطاقتك الجامعية؟ ماذا تفعل",
  "summaryAr": "خطوة بخطوة لكل حالة فقدان: الجواز، وبطاقة الإقامة، والجوال الذي عليه هوية الزائر وأبشر، والبطاقة الجامعية، وبطاقة المكافأة، والبطاقة البنكية، مع من تبلغه وما تبدأ به.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. فقدان وثيقة في بلد غريب أمر مخيف، لكن لكل فقدان هنا طريقًا واضحًا. فتصرّف في اليوم نفسه: الإبلاغ عن فقدان الجواز أو الإقامة واجب خلال ٢٤ ساعة. ابحث عما فقدته أدناه واتبع الخطوات بالترتيب.</p>\n<h2>الساعة الأولى</h2>\n<ol>\n<li><strong>ابحث مرة أخرى بهدوء</strong> حيث كان معك آخر مرة: غرفتك، والمطعم الجامعي، والمصلى، والحافلة، والسيارة التي جئت فيها.</li>\n<li><strong>ضاع منك في الحرم الجامعي؟</strong> اسأل أمن الجامعة، والعلاقات الطلابية في الدور الأول من عمادة شؤون الطلاب. فالأشياء التي يُعثر عليها في الحرم الجامعي تُسلَّم إليهم، وهم يتواصلون مع صاحبها. وإن وجدت أنت شيئًا فسلّمه إليهم.</li>\n<li><strong>أوقف كل ما فيه مال:</strong> جمّد بطاقتك البنكية في تطبيق بنكك، وأبلغ عن بطاقة المكافأة (انظر أدناه).</li>\n<li><strong>أوقف شريحتك</strong> إن ضاع جوالك، بالاتصال بشركة الاتصالات، حتى لا يستقبل أحد رموزك.</li>\n<li><strong>دوّن ما فقدته</strong>، ومتى وأين. فستحتاج إليه في محضر الشرطة.</li>\n</ol>\n<h2>جواز سفرك</h2>\n<ol>\n<li><strong>احصل على محضر من الشرطة</strong> في أقرب مركز شرطة. وخذ معك من يتكلم العربية إن استطعت، واحتفظ بالمحضر.</li>\n<li><strong>أبلغ عن الفقدان في أبشر.</strong> ففي أبشر خدمة للإبلاغ عن فقدان جواز السفر أو سرقته.</li>\n<li><strong>اطلب جوازًا جديدًا</strong> من سفارة بلدك في الرياض أو قنصليته في جدة. ومعظمها يطلب محضر الشرطة، وإقرارًا مكتوبًا بالفقدان، ونسخة من الجواز المفقود إن كانت عندك، وبطاقة هويتك الوطنية من بلدك، ومطبوعة من الجوازات ببيانات إقامتك ونسخة من إقامتك إن كانت لك إقامة، ورسوم الجواز. ولكل بلد قائمته، فاقرأ موقع سفارتك أولًا، لأن كثيرًا منها يستقبل الطلبات إلكترونيًا أو بالبريد.</li>\n<li><strong>انقل سجلك السعودي إلى الجواز الجديد.</strong> بهوية الزائر: أرسل نسخة من الجواز الجديد إلى عمادة القبول والتسجيل عبر تواصل، بموضوع «التأشيرة التعليمية». وبالإقامة الطلابية: أرسلها إلى إدارة السفر عبر تواصل.</li>\n<li><strong>تأكد أن الجواز الجديد ظاهر في أبشر</strong> قبل أن تحجز أي سفر، وأن اسمك في اعتماد ما زال مطابقًا له حرفًا بحرف.</li>\n</ol>\n<p>والتحديث نفسه بعد التجديد العادي في <a href=\"/ar/ask/renew-passport-in-saudi\">جوازي على وشك الانتهاء. كيف أجدده؟</a></p>\n<h2>بطاقة إقامتك</h2>\n<ul>\n<li><strong>إقامتك الرقمية</strong> في تطبيق أبشر معتمدة هويةً لك داخل المملكة، فتستطيع إبرازها ريثما تستبدل البطاقة.</li>\n<li><strong>احصل على محضر من الشرطة</strong> في أقرب مركز شرطة.</li>\n<li><strong>أخبر إدارة السفر</strong> عبر تواصل، وأرفق محضر الشرطة. فالجامعة كفيلك، ولذلك تُطلب البطاقة المطبوعة الجديدة عن طريقها.</li>\n</ul>\n<p>ومن يجدد الإقامة الطلابية، وما يؤخرها، في <a href=\"/ar/ask/student-iqama-renewal\">من يجدد إقامتي الطلابية؟</a></p>\n<h2>جوالك، وعليه هوية الزائر وأبشر</h2>\n<p>هوية الزائر رقمية فقط، فلا يمكن أن تضيع: هي في حسابك على أبشر، لا في جوالك. وما تفقده مع الجوال هو الوصول إليها.</p>\n<ol>\n<li><strong>استخرج شريحة بديلة بالرقم نفسه</strong> من فرع شركة الاتصالات. خذ معك جوازك (أو إقامتك). ويتحقق الفرع من بصمتك.</li>\n<li><strong>ادخل إلى أبشر</strong> على الجوال الجديد. فإن لم تعمل كلمة المرور أو الرقم، فأعد تعيينهما من جهاز الخدمة الذاتية لأبشر ببصمتك. والأجهزة موجودة في مكاتب الجوازات والمجمعات التجارية والمطارات ومراكز الخدمات الحكومية.</li>\n<li><strong>فعّل نفاذ مرة أخرى</strong> على الجوال الجديد، بالتحقق الحيوي.</li>\n<li><strong>ادخل إلى بنكك وتوكلنا وتطبيق الجامعة</strong> مرة أخرى عبر نفاذ.</li>\n</ol>\n<p>وإن لم يتفعل أبشر أو نفاذ فانظر <a href=\"/ar/ask/absher-nafath-activation\">تفعيل أبشر أو نفاذ يفشل عندي باستمرار</a>. ولتغيير الرقم في أبشر انظر <a href=\"/ar/ask/change-absher-mobile\">كيف أغيّر رقم الجوال المسجل في حسابي على أبشر؟</a></p>\n<h2>بطاقتك الجامعية</h2>\n<ul>\n<li>بطاقتك الجامعية رقمية أيضًا، في تطبيق توكلنا، فأبرزها ريثما تنتظر.</li>\n<li>تُصدر البطاقة المطبوعة الجديدة في الوحدة ٢٢، الطابق الأرضي، في مكتب الخدمات الشاملة، من نحو ٨ صباحًا إلى ٢ بعد الظهر.</li>\n<li>أحضر صورة شخصية مقاس ٤×٦ من استوديو تصوير، وهويتك في توكلنا أو أبشر.</li>\n</ul>\n<h2>بطاقة مكافأتك</h2>\n<ol>\n<li>أبلغ عنها فورًا في شباك بطاقات المكافأة في الوحدة ٢٢، الطابق الأرضي، لتُوقف البطاقة.</li>\n<li>املأ نموذج البطاقة البديلة. وتستغرق نحو أسبوعين، وتُخصم رسوم البديلة من البطاقة.</li>\n<li>مكافأتك لا تضيع، فالرصيد ينتقل إلى البطاقة الجديدة.</li>\n</ol>\n<p>والتفاصيل في <a href=\"/ar/guides/getting-your-stipend-off-the-university-card\">بطاقة مكافأتك من الجامعة</a>.</p>\n<h2>بطاقتك البنكية</h2>\n<ol>\n<li>جمّد البطاقة في تطبيق بنكك فورًا، أو اتصل ببنكك.</li>\n<li>اطلب بطاقة بديلة من التطبيق، أو اطبعها من جهاز إصدار البطاقات في أحد فروع بنكك.</li>\n<li>راجع مدفوعاتك الأخيرة، وأبلغ البنك في اليوم نفسه عن أي عملية لم تقم بها.</li>\n</ol>\n<h2>قبل أن يقع الفقدان</h2>\n<ul>\n<li>احفظ صورًا لجوازك وتأشيرتك أو إقامتك وبطاقتك الجامعية وبطاقة المكافأة في ألبوم خاص على جوالك، واحتفظ بنسخة ورقية من جوازك في غرفتك.</li>\n<li>لا تحمل جوازك إلا حين تحتاج إليه، كالسفر أو شباك البنك أو السفارة. فهويتك الرقمية في أبشر تكفي داخل المملكة.</li>\n<li>اكتب أرقام خدمة العملاء لشركة الاتصالات ولبنكك على ورقة، بعيدًا عن الجوال.</li>\n</ul>\n<blockquote><p>نصيحة: تعثرت في خطوة، أو لا تعرف أي مكتب تقصد؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "masjid-an-nabawi-first-visit": {
  "titleAr": "زيارة المسجد النبوي: دليل الزيارة الأولى",
  "summaryAr": "ما في داخل المسجد النبوي، وكيف تحجز الروضة، وكيف تزور البقيع، والعادات الصغيرة التي تجعل الزيارة هادئة.",
  "bodyHtmlAr": "<p>بنى المسجدَ النبيُّ ﷺ وأصحابه في السنة الأولى من الهجرة، ووُسّع مرات كثيرة منذ ذلك الحين. ومعظم الطلاب والأسر يذهبون إليه عدة مرات في الأسبوع. وهذه الملاحظات تعين على أن تمر الزيارات الأولى بسلاسة.</p>\n<h2>ما تجده في الداخل</h2>\n<table><thead><tr><th>المكان</th><th>ما هو</th></tr></thead><tbody>\n<tr><td><strong>الروضة الشريفة</strong></td><td>ما بين حجرة النبي ﷺ ومنبره، ويميزها السجاد الأخضر. والدخول بالحجز فقط.</td></tr>\n<tr><td><strong>حجرة النبي ﷺ</strong></td><td>مثوى النبي ﷺ وأبي بكر وعمر. يسلّم الزائرون بهدوء وباختصار، ويواصلون السير ولا يعيقون من خلفهم.</td></tr>\n<tr><td><strong>المنبر والمحراب</strong></td><td>المنبر ومحراب الصلاة اللذان يحدّان الروضة.</td></tr>\n<tr><td><strong>القبة الخضراء</strong></td><td>القبة فوق الحجرة. والساحة المكشوفة في الجهة الجنوبية تعطي أفضل منظر.</td></tr>\n<tr><td><strong>مكتبة المسجد النبوي</strong></td><td>مكتبة مخطوطات نادرة ونصوص تراثية للباحثين والطلاب، مفتوحة كل يوم على مدار الساعة، بقاعات قراءة للرجال والنساء والأطفال. مكتبة الرجال في الدور العلوي، يُصعد إليها بالسلم الكهربائي قرب الباب ١٠. ومكتبة النساء عند مصليات النساء قرب البابين ٢٤ و١٦. والحقائب غير مسموح بها، والحواسيب المحمولة تحتاج تصريحًا.</td></tr>\n<tr><td><strong>متحف السيرة النبوية</strong></td><td>معرض متعدد الوسائط عن حياة النبي ﷺ والحضارة الإسلامية، جنوب المسجد مباشرة. الدخول بتذكرة تُحجز عبر الإنترنت: ٤٠ ريالًا للتذكرة العادية (نوفمبر ٢٠٢٦)، ومجانًا للأطفال دون السابعة. تعريف أول جيد للأطفال.</td></tr>\n<tr><td><strong>مظلات الساحات</strong></td><td>٢٥٠ مظلة كبيرة تُفتح وتُغلق تلقائيًا مع الشمس والطقس، فتبقى الساحات مظللة للصلاة.</td></tr>\n<tr><td><strong>المراكز الصحية</strong></td><td>مركزان مفتوحان على مدار الساعة: عند باب جبريل (٣٥٥) وعند الصافية (٣٠٥).</td></tr>\n<tr><td><strong>الميضآت ودورات المياه</strong></td><td>مرافق كبيرة حول أطراف المسجد، بعضها تحت الأرض يُنزل إليه بمنحدرات في الساحات. وهي أنظف ما تكون بعد الصلاة مباشرة وأزحم ما تكون قبلها.</td></tr>\n</tbody></table>\n<h2>حجز الروضة</h2>\n<ol>\n<li>ثبّت تطبيق <strong>نسك</strong> أو افتح موقع نسك وسجّل الدخول. المقيمون يدخلون بنفاذ. والتصريح مجاني ويصدر في الحال.</li>\n<li>اختر التاريخ والموعد. وللرجال والنساء مواعيد منفصلة وأوقات منفصلة، والوقت المطبوع في تصريحك هو المعتبر.</li>\n<li>احجز بأبكر ما يسمح به التطبيق. فالمواعيد تنفد بسرعة، وأكثر ما يكون ذلك في رمضان وموسم الحج والإجازات المدرسية. ويظهر التطبيق كم تصريحًا تستطيع حجزه.</li>\n<li>أبقِ التطبيق مفتوحًا مع تشغيل الموقع وأنت في المسجد، لأن مواعيد قريبة تُطرح خلال اليوم لمن هم قريبون. وتستطيع أيضًا الانضمام إلى قائمة الانتظار في التطبيق.</li>\n<li>احضر في موعدك المحجوز واتبع المنظمين. وتوقع انتظار نحو ٢٠ دقيقة قبل الدخول، واجعل الزيارة قصيرة ليصلي غيرك أيضًا.</li>\n</ol>\n<h2>مقبرة البقيع</h2>\n<p>البقيع في الجهة الشرقية من المسجد، عبر الساحة. وهو مفتوح للرجال فقط، والدخول مجاني. ويمكن حجز الزيارة ومعرفة مستوى الازدحام على بوابة البقيع التابعة لأمانة المدينة على <a href=\"https://ekram.amana-md.gov.sa/\">ekram.amana-md.gov.sa</a>. والتصوير غير مسموح به في الداخل. وتستطيع النساء رؤيته من خارج السور.</p>\n<h2>أمور صغيرة تعين</h2>\n<ul>\n<li>احضر قبل الصلاة بعشرين إلى ثلاثين دقيقة إن أردت مكانًا قرب الوسط.</li>\n<li>احمل حقيبة صغيرة بسحّاب. فالحقائب الأكبر تُفحص عند الأمن، والأحذية توضع على الأرفف. ومركز حفظ الأمانات المجاني يحفظ الحقائب حتى أربع ساعات على مدار الساعة. وقواعد الحقائب في المكتبة في جواب المكتبة.</li>\n<li>أحضر سجادة صلاة صغيرة للساحات المكشوفة، لأن الرخام يسخن في الظهيرة صيفًا.</li>\n<li>تضعف إشارة الجوال في أوقات الازدحام. فاتفق مع أسرتك على مكان لقاء قبل أن تفترقوا.</li>\n<li>احفظ رقم الباب الذي دخلت منه. فالمسجد ضخم والمخارج متشابهة. وأرقام الأبواب تتغير أثناء أعمال البناء، فاتبع اللوحات.</li>\n<li>زر حجرة النبي ﷺ من الممرات التي تبدأ من باب السلام (الباب ١). واخفض صوتك، وسلّم باختصار وامضِ، ولا تزاحم ولا تمسح الجدران طلبًا للبركة.</li>\n<li>تُعار الكراسي المتحركة مجانًا من مكتب إدارة الأبواب عند الباب ٧، والمصاعد عند البابين ٩ و٣٣ تصعد إلى السطح. والمزيد للأسر ولذوي الحركة المحدودة في <a href=\"/ar/guides/women-at-masjid-an-nabawi\">المسجد النبوي للأخوات والأسر</a>.</li>\n<li>ضاع طفل؟ المكتب الرئيسي عند جدار البقيع مقابل باب الساحة 34C، ومكتب في كل من مصليي النساء الشرقي والغربي. وللهيئة العامة للعناية بشؤون الحرمين رقم موحد <strong>1966</strong>.</li>\n</ul>\n<blockquote><p>نصيحة: لدروس المسجد اليومية انظر صفحة <a href=\"/ar/duroos\">الدروس</a>. ولحلقات القرآن والمتون المجانية انظر <a href=\"/ar/programs\">الدراسة في المدينة</a>.</p></blockquote>\n<p>انظر أيضًا <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء من المدينة</a> و<a href=\"/ar/guides/historic-sites-and-masjids\">المواقع التاريخية والمساجد في المدينة</a>.</p>"
 },
 "masjid-an-nabawi-institute-and-college": {
  "titleAr": "معهد المسجد النبوي وكلية المسجد النبوي",
  "summaryAr": "دراسة مجانية بدوام كامل داخل الحرم، من المرحلة المتوسطة إلى البكالوريوس، للإخوة والأخوات من حملة الإقامة: من يحق له التقديم، وفترة التسجيل السنوية في صفر، والاختبار والمقابلة.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. لمعهد الحرم المكي فرع في المسجد النبوي، يضم معهدًا للمرحلتين المتوسطة والثانوية، وكليةً لمرحلة البكالوريوس. والدراسة مجانية وبدوام كامل داخل المسجد، مع أقسام منفصلة للطلاب والطالبات.</p>\n<h2>المراحل</h2>\n<table><thead><tr><th>المرحلة</th><th>من يحق له التقديم</th></tr></thead><tbody>\n<tr><td>المتوسطة (المعهد)</td><td>من لا يقل عمره عن ١٢ سنة في بداية العام، ويحمل شهادة المرحلة الابتدائية</td></tr>\n<tr><td>الثانوية (المعهد)</td><td>من لا يقل عمره عن ١٥ سنة في بداية العام، ويحمل شهادة المرحلة المتوسطة</td></tr>\n<tr><td>البكالوريوس (الكلية)</td><td>من يحمل شهادة الثانوية العامة أو ما يعادلها بنسبة لا تقل عن ٨٥٪، ويحفظ ثلاثة أجزاء من القرآن على الأقل. ويُشترط لغير السعوديين ألا تقل المدة المتبقية في إقامتهم عن ثلاثة أشهر</td></tr>\n</tbody></table>\n<h2>من يحق له التقديم</h2>\n<ul>\n<li><strong>يُشترط لغير السعوديين إقامة سارية.</strong> ولهم حصة قبول مستقلة. ولا تكفي هوية الزائر ولا تأشيرة الزيارة للتسجيل.</li>\n<li>حسن السيرة والسلوك، وألا يكون سبق فصله من المعهد أو من مؤسسة تعليمية مماثلة لأسباب تأديبية.</li>\n<li>الدراسة بدوام كامل، فتلزمك موافقة مكتوبة من جهة عملك أو من كفيلك.</li>\n<li>يجب أن تُعادَل الشهادات الصادرة من خارج المملكة وتُصدَّق من الجهات المختصة قبل التقديم.</li>\n<li>إجادة العربية، فالتدريس والاختبارات والمقابلة كلها بالعربية.</li>\n</ul>\n<h2>متى وكيف تتقدم</h2>\n<p>يفتح التسجيل مرة واحدة في السنة، من ٥ إلى ٢٠ صفر. ووافق ذلك في عام ١٤٤٨ الفترة من ١٩ يوليو إلى ٣ أغسطس ٢٠٢٦. وفي عام ١٤٤٩ يقع صفر في يوليو ٢٠٢٧.</p>\n<ol>\n<li>أنجز معادلة شهاداتك وتصديقها قبل صفر بوقت كافٍ، فهذه أطول الخطوات وقتًا.</li>\n<li>حين يفتح التسجيل تقدّم إلكترونيًا عبر بوابة الهيئة العامة للعناية بشؤون المسجد الحرام والمسجد النبوي، واختر فرع المسجد النبوي والمرحلة التي تريدها.</li>\n<li>أدِّ الاختبار التحريري حضوريًا. وكان في عام ١٤٤٨ يوم ١١ ربيع الأول.</li>\n<li>احضر المقابلة الشخصية حضوريًا. وكانت في عام ١٤٤٨ يوم ١٣ ربيع الأول.</li>\n<li>تابع البوابة وجوالك لمعرفة النتيجة.</li>\n</ol>\n<p>وتتقدم الأخوات في الفترة نفسها إلى المعهد والكلية في القسم النسائي. انظر <a href=\"/ar/programs/nabawi-women\">برامج المسجد النبوي للنساء</a>.</p>\n<h2>لمن لا يحمل إقامة</h2>\n<p>تستطيع مع ذلك أن تطلب العلم في الحرم كل يوم. فدروس المشايخ مفتوحة للجميع بلا تسجيل، أما حلقات القرآن والمتون فالتسجيل فيها إلكتروني. انظر <a href=\"/ar/programs/nabawi-halaqat\">حلقات القرآن والمتون في المسجد النبوي</a> و<a href=\"/ar/duroos\">دروس اليوم</a>.</p>\n<blockquote><p>نصيحة: ألديك سؤال يخص حالتك؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "new-student-steps": {
  "titleAr": "الخطوات الأولى للطلاب الجدد: الشريحة وأبشر وهوية الزائر والبطاقة الجامعية والحساب البنكي",
  "summaryAr": "ما تفعله بعد وصولك بالترتيب: شريحة سعودية، ثم أبشر وجهاز الخدمة الذاتية، ثم نفاذ، ثم هوية الزائر، ثم العنوان الوطني، ثم الحساب البنكي، ثم لقاء التهيئة، ثم بطاقة المكافأة والبطاقة الجامعية، ثم حساباتك في الجامعة واعتماد.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. الطلاب الجدد على التأشيرة التعليمية يؤدون هذه الخطوات بهذا الترتيب، لأن كل خطوة تحتاج إلى التي قبلها. وفي نهايتها يكون عندك رقم سعودي، وأبشر ونفاذ مفعّلان، وهوية الزائر، وحساب بنكي، وبطاقة المكافأة، وبطاقتك الجامعية، وحساباتك في الجامعة.</p>\n<h2>قبل أن تبدأ</h2>\n<ul>\n<li>احتفظ بجواز سفرك معك، واعرف <strong>رقم الحدود</strong>، وهو الرقم المرتبط بتأشيرتك عند دخولك المملكة أول مرة.</li>\n<li>اجعل عندك بريدًا إلكترونيًا تفتحه من جوالك.</li>\n<li>أحضر ما يكفيك من المال لشهريك الأولين. فلا تُصرف مكافأة في شهرك الأول.</li>\n</ul>\n<h2>الخطوات</h2>\n<ol>\n<li><strong>اشترِ شريحة سعودية.</strong> في أي فرع لشركة اتصالات، أظهر جوازك وتأشيرتك أو رقم الحدود. يتحقق المحل من بصمتك ويسجل الخط باسمك. وكل رمز تحقق بعد ذلك يصل إلى هذا الرقم.</li>\n<li><strong>سجّل في أبشر</strong> مستخدمًا جديدًا، برقم الحدود وبريدك الإلكتروني ورقم جوالك الجديد.</li>\n<li><strong>فعّل أبشر من جهاز الخدمة الذاتية.</strong> الأجهزة موجودة في مكاتب الجوازات وفي الجامعة وفي المطارات وفي بعض المجمعات التجارية. أدخل رقم الحدود وسجّل بصمتك.</li>\n<li><strong>فعّل نفاذ</strong> في تطبيق نفاذ: افتح الإعدادات، واختر تفعيل الهوية الرقمية الوطنية، وأكمل بياناتك والتحقق بالوجه.</li>\n<li><strong>أصدر هوية الزائر</strong> في أبشر: اختر <strong>إصدار هوية زائر</strong> وأكمل البيانات. وهي رقمية فقط، تظهر في تطبيق أبشر ولا تُطبع.</li>\n<li><strong>سجّل عنوانك الوطني</strong> في البريد السعودي. البنك يحتاجه. انظر <a href=\"/ar/ask/short-address\">ما العنوان المختصر؟</a></li>\n<li><strong>افتح حسابًا بنكيًا.</strong> إما أن تذهب إلى الفرع بجوازك وتُظهر هوية الزائر في تطبيق أبشر، وإما أن تفتح الحساب عبر الإنترنت وتؤكد هويتك عبر نفاذ. يصلك رقم الحساب برسالة نصية، وتستلم بطاقة مدى من الفرع أو تُرسل إليك بالبريد. وهذا هو الحساب الذي تنقل إليه مكافأتك من بطاقة الجامعة. انظر <a href=\"/ar/guides/sim-internet-bank\">شريحة الجوال والإنترنت وبطاقة بنكية سعودية</a>.</li>\n<li><strong>احضر لقاء التهيئة.</strong> للطلاب الجدد لقاء تهيئة في الأسبوع الأول، تعلن عنه الجامعة في حسابها على منصة X. وهو يشرح لك سير أسابيعك الأولى، فلا تفوّته.</li>\n<li><strong>استلم بطاقة المكافأة.</strong> تُصرف مكافأتك على بطاقة مكافأة جامعية (بطاقة من مصرف الراجحي)، لا في حسابك الخاص. ويستلمها الطلاب الجدد بعد التهيئة، وتُصدر البطاقات وتُجدد في مكتب البطاقات بالوحدة ٢٢. وتأتي مكافأتك الأولى في شهرك الثاني، مضاعفةً. انظر <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة</a> و<a href=\"/ar/guides/getting-your-stipend-off-the-university-card\">سحب مكافأتك من بطاقة الجامعة</a>.</li>\n<li><strong>استخرج بطاقتك الجامعية.</strong> هويتك الجامعية رقمية، في تطبيق توكلنا. والبطاقة المطبوعة اختيارية: خذ صورة مقاس ٤×٦ وهويتك إلى مكتب الخدمات الشاملة في الدور الأرضي من الوحدة ٢٢، من ٨ صباحًا إلى ٢ ظهرًا في أيام العمل.</li>\n<li><strong>ادخل إلى حساباتك الجامعية</strong> على sso.iu.edu.sa عبر نفاذ أو برقمك الجامعي وكلمة المرور ورمز التحقق. بذلك يُفتح لك بريدك الجامعي والنظام الأكاديمي وبلاك بورد وتواصل. وجدولك تحت «التسجيل الإلكتروني» ثم «المقررات المسجلة». وفي الجدول اليوم ١ هو الأحد واليوم ٥ هو الخميس.</li>\n<li><strong>تأكد أن رقم هويتك مسجل في ملفك الجامعي.</strong> فبغير رقم هوية الزائر أو الإقامة في النظام الأكاديمي لا تستطيع إدارة السفر إصدار تذاكرك ولا تأشيراتك. ادخل إلى موقع الجامعة وافتح «الخدمات الأكاديمية» ثم «المعلومات الأكاديمية»، وانظر في خانة «رقم الهوية». فإن كانت فارغة فاذهب إلى إدارة السفر بجوازك وهوية الزائر.</li>\n<li><strong>جهّز حسابك في اعتماد</strong> لتذاكر الجامعة، واجعل اسمك فيه مطابقًا لجوازك تمامًا. انظر <a href=\"/ar/guides/etimad-account\">تذكرتك من الجامعة: اعتماد وأمر الإركاب والقواعد</a>.</li>\n</ol>\n<blockquote><p>ملاحظة: إذا تكرر فشل تفعيل أبشر أو نفاذ فاتصل بخدمة عملاء أبشر على <strong>920020405</strong> (على مدار الساعة)، واختر اللغة الإنجليزية، وأدخل رقم الحدود، واطلب فتح تذكرة دعم فني. انظر <a href=\"/ar/ask/absher-nafath-activation\">تفعيل أبشر أو نفاذ يفشل عندي باستمرار</a>.</p></blockquote>\n<h2>إن كنت تحمل إقامة</h2>\n<p>طلاب الدفعات السابقة الذين يحملون إقامة يتبعون الترتيب نفسه مع فرقين: أبشر ونفاذ والشريحة تستعمل رقم الإقامة، ولا توجد هوية زائر تُصدر. كما تسمح البنوك لحاملي الإقامة بفتح الحساب من تطبيق البنك.</p>\n<h2>ما بعد ذلك</h2>\n<ul>\n<li>ما تستطيعه هوية الزائر وما لا تستطيعه، وما تفعله قبل انتهائها: <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a>.</li>\n<li>الوجبات والحافلات والمركز الطبي والمكتبة: <a href=\"/ar/guides/campus-life-islamic-university\">حياة الطالب في الجامعة الإسلامية</a>.</li>\n<li>أي مكتب يتولى أي أمر: <a href=\"/ar/guides/university-offices-and-contacts\">من تسأل في الجامعة الإسلامية</a>.</li>\n<li>بقية شهرك الأول: <a href=\"/ar/guides/first-30-days-in-madinah\">أيامك الثلاثون الأولى في المدينة</a>.</li>\n</ul>\n<blockquote><p>نصيحة: تعثرت في خطوة؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "other-universities-in-madinah": {
  "titleAr": "الجامعات الأخرى في المدينة",
  "summaryAr": "جامعة الأمير مقرن، وجامعة الأمير مساعد بن عبدالرحمن (الجامعة السعودية الإلكترونية سابقًا)، وجامعة طيبة: ما تقدمه كل واحدة، وأين موقع الجامعة الإسلامية بينها.",
  "bodyHtmlAr": "<p>الجامعة الإسلامية هي الطريق الرئيسي للطلاب الدوليين، بمنحة كاملة ومعهد تعليم اللغة العربية. وفي المدينة جامعات أخرى أيضًا. وشروط القبول والرسوم ولغة التدريس تختلف في كل واحدة، فراجع دائمًا صفحة القبول في الجامعة نفسها قبل التقديم.</p>\n<h2>الجامعات</h2>\n<table><thead><tr><th>الجامعة</th><th>النوع</th><th>تُعرف بـ</th></tr></thead><tbody>\n<tr><td><strong>الجامعة الإسلامية بالمدينة المنورة</strong></td><td>حكومية، أُسست سنة ١٩٦١</td><td>الشريعة والقرآن والحديث والدعوة والعربية، بمنح لطلاب من أنحاء العالم. انظر <a href=\"/ar/guides/applying-to-the-islamic-university\">التقديم إلى الجامعة الإسلامية</a>.</td></tr>\n<tr><td><strong>جامعة الأمير مقرن</strong></td><td>أهلية غير ربحية</td><td>ثلاث كليات: الأعمال والسياحة، وعلوم الحاسب والأمن السيبراني، والهندسة. والطلاب يدفعون رسومًا، وللجامعة برنامج منح خاص بها.</td></tr>\n<tr><td><strong>جامعة الأمير مساعد بن عبدالرحمن، فرع المدينة</strong></td><td>حكومية، تعليم مدمج</td><td>كانت تُعرف حتى سبتمبر ٢٠٢٦ بالجامعة السعودية الإلكترونية. إدارة الأعمال، والحوسبة والمعلوماتية، والعلوم الصحية، بدراسة تجمع بين الإنترنت وجلسات في مركزها بالمدينة.</td></tr>\n<tr><td><strong>جامعة طيبة</strong></td><td>حكومية، أُسست سنة ٢٠٠٣</td><td>كليات في كل التخصصات ومنها الطب والهندسة وعلوم الحاسب والصيدلة والتربية والشريعة والأعمال. ولها منح دولية خاصة بها للبكالوريوس والماجستير، يُقدم إليها عبر منصة «ادرس في السعودية». والمتقدم للبكالوريوس يكون بين ١٧ و٢٤ سنة، ويقيم خارج السعودية، ويحمل شهادة ثانوية عمرها أقل من خمس سنوات.</td></tr>\n</tbody></table>\n<h2>التقديم</h2>\n<ul>\n<li><strong>الجامعة الإسلامية بالمدينة المنورة:</strong> يُقدم عليها عبر منصة «ادرس في السعودية» (studyinsaudi.sa)، في فترة التقديم الرئيسية في الربيع أو في دورة إضافية لاحقة. والخطوات والمستندات والمواعيد في <a href=\"/ar/guides/applying-to-the-islamic-university\">التقديم إلى الجامعة الإسلامية</a>.</li>\n<li><strong>جامعة الأمير مقرن:</strong> مفتوحة للسعوديين والمقيمين والزائرين والطلاب الدوليين الحاملين لشهادة الثانوية، ويُقدم عليها عبر upm.edu.sa. وللفصل الأول من ١٤٤٨ كانت فترة التقديم من ١٤ يونيو إلى ٣٠ أغسطس ٢٠٢٦. ويبدأ الطلاب بسنة تحضيرية، أو ينتقلون إلى تخصصهم مباشرةً بدرجة ٥ في الآيلتس أو ٥٠٠ في التوفل. والرسوم بحسب الساعات المعتمدة، ومنحها بالتنافس على الدرجات ودرجة اللغة الإنجليزية.</li>\n<li><strong>جامعة الأمير مساعد بن عبدالرحمن:</strong> يُقدم عليها عبر بوابة القبول في الجامعة نفسها. وحملت اسمها الجديد بأمر ملكي في ١٨ سبتمبر ٢٠٢٦.</li>\n<li><strong>جامعة طيبة:</strong> المقيمون يتقدمون عبر بوابة القبول في الجامعة نفسها. والمتقدمون من الخارج يتقدمون لمنحها الدولية عبر منصة «ادرس في السعودية»، بشروط السن والشهادة المذكورة أعلاه.</li>\n</ul>\n<h2>الاختيار</h2>\n<ul>\n<li><strong>تريد العلوم الشرعية والعربية؟</strong> الجامعة الإسلامية مبنية لذلك. والطرق الأخرى في <a href=\"/ar/programs\">الدراسة في المدينة</a>.</li>\n<li><strong>تريد شهادة مهنية؟</strong> في الجامعة الإسلامية أيضًا كليات الهندسة والحاسب والعلوم، تُدرَّس بالإنجليزية وتطلب الآيلتس أو التوفل. قارن البرامج والرسوم ولغة التدريس في صفحة القبول في كل جامعة. والمتقدمون الدوليون يتقدمون إلى أكثرها عبر منصة «ادرس في السعودية».</li>\n<li><strong>تحتاج إلى ساعات مرنة؟</strong> البرامج الإلكترونية والمدمجة تناسب من يعمل أو عليه واجبات أسرية.</li>\n<li><strong>تقيم بتأشيرة؟</strong> الدراسة للحصول على شهادة تحتاج إلى تأشيرة طالب. انظر <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a>.</li>\n</ul>"
 },
 "owning-property-as-a-non-saudi": {
  "titleAr": "تملّك غير السعودي مسكنًا في المدينة: الأحكام والنطاقات وطريقة التقديم",
  "summaryAr": "من يحق له التملك في المدينة بموجب نظام ٢٠٢٦، وأحكام مكة والمدينة (النطاقات المعتمدة، وللمسلمين فقط)، ووضع أسرتك، والخطوات الخمس في منصة «عقارات السعودية»، والتكاليف، وما يمنحك التملك وما لا يمنحك.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. منذ سنة ٢٠٢٦ يستطيع غير السعودي أن يتملك مسكنًا في المدينة، في حدود أضيق هنا من أي مكان آخر في المملكة. ويشرح هذا الدليل من تنطبق عليه الشروط، وما أحكام مكة والمدينة، وكيف يسير الطلب في المنصة الرسمية، وما تتحقق منه قبل أن تدفع. والإيجار لا يتأثر: كل من يحمل إقامة أو هوية زائر يستأجر عبر إيجار، كما في <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a>.</p>\n<h2>الأحكام في جدول واحد</h2>\n<table><thead><tr><th>أنت</th><th>داخل نطاق معتمد</th><th>خارج النطاقات</th></tr></thead><tbody>\n<tr><td>مقيم بإقامة سارية</td><td>تتملك في كل المدن. وفي مكة والمدينة بشرط أن تكون مسلمًا</td><td>مسكن واحد لاستعمالك في أي مدينة عدا مكة والمدينة</td></tr>\n<tr><td>حامل الإقامة المميزة</td><td>كالمقيم</td><td>المساكن والمحلات والعقارات الصناعية في كل المدن عدا مكة والمدينة. وفي المدينتين المقدستين حق انتفاع فقط</td></tr>\n<tr><td>تعيش خارج السعودية</td><td>تتملك في كل المدن بعد الحصول على هوية رقمية سعودية من سفارة أو قنصلية سعودية. وفي مكة والمدينة بشرط أن تكون مسلمًا</td><td>لا</td></tr>\n<tr><td>مواطن خليجي</td><td>كالمقيم، مع شرط الإسلام في المدينتين المقدستين</td><td>المساكن والعقارات الاستثمارية في كل المدن عدا مكة والمدينة</td></tr>\n<tr><td>شركة أو جمعية أجنبية</td><td>كل المدن عدا مكة والمدينة</td><td>لا</td></tr>\n</tbody></table>\n<p>النظام هو نظام تملك غير السعوديين للعقار المحدّث، الصادر بمرسوم ملكي في ١٤ يوليو ٢٠٢٥ والنافذ منذ ٢٢ يناير ٢٠٢٦. ولائحته التنفيذية وخريطة النطاقات المعتمدة صدرتا في ٢٣ يونيو ٢٠٢٦. وتتولاه الهيئة العامة للعقار، ومنصتها الرسمية «عقارات السعودية» على <a href=\"https://saudiproperties.rega.gov.sa/\">saudiproperties.rega.gov.sa</a>.</p>\n<h2>المدينة ومكة: ما المختلف</h2>\n<ul>\n<li><strong>للمسلمين فقط.</strong> الفرد غير السعودي لا يتملك عقارًا في المدينتين المقدستين إلا إن كان مسلمًا، سواء أقام في المملكة أو خارجها.</li>\n<li><strong>داخل النطاقات فقط.</strong> لا حق هنا في مسكن واحد خارج النطاقات، بخلاف بقية المملكة. والنطاقات مرسومة على الخريطة التفاعلية في «عقارات السعودية». تحقق من القطعة أو المبنى بعينه على الخريطة قبل دفع العربون، لأن بعض الشوارع تقع خارج الحد بقليل.</li>\n<li><strong>لا شركات أجنبية.</strong> الشركات والجمعيات المؤسسة في الخارج لا تتملك هنا أصلًا. والشركة السعودية التي فيها شركاء أجانب تتبع أحكام الشركات.</li>\n<li><strong>الملكية التامة فقط.</strong> يجب أن يكون العقار مسجلًا في السجل العقاري ملكيةً تامة. والأرض التي لها صك ورقي قديم بلا قيد في السجل لا تُشترى بهذا الطريق.</li>\n</ul>\n<h2>أسرتك تُحسب معك</h2>\n<p>زوجتك وأولادك يُعدّون تابعين لك في المسكن المشترى لسكن الأسرة. فلا تتملك زوجتك ولا أحد أولادك مسكنًا باسمه ما دمت تملك واحدًا، إلا بعد الطلاق أو حين يبلغ الولد ٢٥ سنة.</p>\n<h2>قبل أن تتقدم</h2>\n<ul>\n<li>إقامة سارية أو إقامة مميزة. ومن يعيش في الخارج: هوية رقمية سعودية صادرة عبر سفارة أو قنصلية سعودية.</li>\n<li>حساب بنكي في السعودية باسمك.</li>\n<li>رقم جوال سعودي مربوط بهويتك الرقمية، لأن الإشعارات الرسمية تصل برسائل نصية إلى هذا الرقم وعبر المنصة.</li>\n</ul>\n<p>طلاب التأشيرة التعليمية يحملون هوية زائر لا إقامة، فطريق المقيمين ليس مفتوحًا لهم. والطالب المبتعث الذي يريد الشراء يتقدم بصفته مقيمًا خارج المملكة، بهوية رقمية من بعثة سعودية، وشرط الإسلام ينطبق كالمعتاد.</p>\n<h2>كيف يسير الطلب</h2>\n<ol>\n<li><strong>جهّز الأساسيات:</strong> إقامة سارية أو هوية رقمية، وحساب بنكي سعودي، ورقم جوال سعودي.</li>\n<li><strong>اختر العقار</strong> في «عقارات السعودية» أو في أي مكان آخر، وتأكد على خريطة المنصة أنه داخل نطاق معتمد.</li>\n<li><strong>سجّل في «عقارات السعودية»</strong> وأكمل التحقق من الهوية.</li>\n<li><strong>أجرِ فحص الأهلية</strong> في المنصة ونزّل شهادة الأهلية التي تصدرها.</li>\n<li><strong>أتمّ الشراء:</strong> ادفع الثمن والرسوم إلكترونيًا، لا نقدًا أبدًا، وأنهِ الإفراغ والصك الإلكتروني. ويُقيَّد حقك بعدها في السجل العقاري.</li>\n</ol>\n<p>كل دفعة في هذه العملية إلكترونية، وفق قواعد المدفوعات للبنك المركزي السعودي. وضريبة التصرفات العقارية ٥٪ من الثمن تنطبق على بيع العقارات في المملكة، فأدخلها في ميزانيتك مع عمولة الوسيط.</p>\n<h2>بعد أن تتملك</h2>\n<ul>\n<li>التملك لا يمنحك إقامة ولا تأشيرة. وإقامتك وبقاؤك يتبعان كفيلك أو تأشيرتك كما كانا.</li>\n<li>لك حقوق أي مالك: أن تسكن العقار، أو تؤجره عبر إيجار، أو تبيعه.</li>\n<li>الهيئة العامة للعقار تفتش وتغرّم على مخالفة النظام. والقرار يمنحك بين ١٠ و١٨٠ يومًا لتصحيح الوضع، والنظام يجيز غرامات تصل إلى ١٠ ملايين ريال والبيع الجبري في المخالفات الجسيمة. والإشعارات المرسلة عبر المنصة أو برسالة نصية إلى رقمك المسجل تُعدّ مبلَّغة، فأبقِ كليهما محدّثًا.</li>\n</ul>\n<h2>هل يشتري الطالب؟</h2>\n<p>أكثر الطلاب يستأجرون، والإيجار لإقامة بضع سنوات أرخص وأسهل. والشراء مناسب لأسرة مستقرة في المدينة على المدى الطويل، معها المال لتدفع كاملًا، وفي عقار داخل نطاق تسرّها ملكيته ولو انتهت إقامتها مبكرًا. والأسعار داخل النطاقات تحددها المشاريع الجديدة، فقارنها بالإيجارات في <a href=\"/ar/guides/cost-of-living\">كم تكلف المعيشة في المدينة</a> قبل أن تقرر.</p>\n<h2>أين تسأل</h2>\n<p>خط دعم الهيئة العامة للعقار 920017183 داخل المملكة و00966920017183 من الخارج، وبريدها saudiproperties@rega.gov.sa. والدليل الرسمي لتملك غير السعوديين منشور في المنصة بالعربية.</p>\n<blockquote><p>نصيحة: لا تدفع عربونًا أبدًا على وعد بأن الأرض «ستدخل النطاقات قريبًا». الخريطة في المنصة وحدها هي المعتبرة. عندك سؤال؟ راسل المشرف على واتساب على الرقم +1 234 567 9076 أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "phone-sims-and-absher": {
  "titleAr": "رقم جوالك والتحقق من الشرائح وأبشر",
  "summaryAr": "اعرف رقمك ورصيدك، وكم شريحة مسجلة على إقامتك، وألغِ شريحة لا تعرفها، وحدّث رقم جوالك في أبشر، وفعّل أبشر، وانقل شريحة إلى اسم شخص آخر.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. تغير الشركات أكوادها أحيانًا، فاسأل الشركة إن توقف كود عن العمل.</p>\n<h2>أكواد رقمك ورصيدك</h2>\n<table><thead><tr><th>الشركة</th><th>رقمك</th><th>الرصيد</th><th>خدمة العملاء</th></tr></thead><tbody>\n<tr><td>موبايلي</td><td>*222#</td><td>*1411#</td><td>1100</td></tr>\n<tr><td>STC</td><td>*150#</td><td>*166#</td><td>900</td></tr>\n<tr><td>زين</td><td>*144#</td><td>*142#</td><td>959</td></tr>\n</tbody></table>\n<p>اطلب الكود من الشريحة التي تريد التحقق منها.</p>\n<h2>كم شريحة مسجلة على إقامتك</h2>\n<p>تدير هيئة الاتصالات والفضاء والتقنية منصة اسمها «متصل» تعرض الخطوط المسجلة على إقامتك. ولا تظهر فيها إلا الأرقام الفعّالة الموثقة. فإن لم يظهر رقم تستعمله فاطلب من شركته التحقق من توثيقه.</p>\n<ol>\n<li><strong>ادخل إلى «متصل» بنفاذ.</strong> تظهر أرقامك المسجلة في الحال.</li>\n<li><strong>استعمل «الاستعلام عن أرقامي» بلا تسجيل دخول.</strong> اختر اللغة، وأدخل رقم إقامتك وتاريخ ميلادك، وأجب بنعم عن امتلاكك رقم جوال، وأدخل ذلك الرقم ورمز التحقق، ثم اضغط استعلام. أدخل الرمز الذي يصل إلى جوالك واضغط إرسال.</li>\n<li><strong>لا تستطيع الوصول إلى رقمك المسجل؟</strong> أجب بلا عن امتلاكك رقم جوال. فتحصل على ملخص قصير بتفاصيل أقل.</li>\n<li><strong>تطبيق الهيئة:</strong> ادخل وافتح «أرقامي». والخدمة مجانية.</li>\n<li><strong>توكلنا:</strong> ادخل وافتح الاستعلام عن أرقام الجوال.</li>\n</ol>\n<blockquote><p>ملاحظة: هذه الخطوات تستعمل رقم الإقامة. فإن كنت هنا بهوية زائر فاسأل شركتك في الفرع أي الخطوط مسجلة على جوازك.</p></blockquote>\n<h2>رقم لا تعرفه</h2>\n<ol>\n<li>اتصل بالشركة (STC على 900، أو موبايلي على 1100، أو زين على 959، أو في الفرع) وبيانات إقامتك جاهزة، واطلب إلغاءه. وفي الفرع أبرز إقامتك واذكر الرقم، فيُلغى الخط خلال ٢٤ ساعة.</li>\n<li>قدّم شكوى واحتفظ برقمها المرجعي.</li>\n<li>إن لم تحل الشركة الأمر خلال خمسة أيام عمل فصعّده إلى الهيئة عبر خدمة شكاوى الاتصالات.</li>\n<li>راجع «متصل» مرة أخرى لتتأكد أن الرقم زال.</li>\n</ol>\n<h2>تحديث رقم جوالك في أبشر</h2>\n<p>يرسل أبشر رموز التحقق إلى الرقم المسجل عنده، فحدّثه حين تغير شريحتك. ويجب أن يكون الرقم الجديد فعّالًا، يستقبل الرسائل النصية، ومسجلًا على هويتك أنت (أو هوية أحد أقاربك المقربين). ويحتفظ بنكك بسجله الخاص لرقمك، فحدّثه عند البنك أيضًا.</p>\n<ul>\n<li><strong>تطبيق أبشر:</strong> قبل تسجيل الدخول افتح «إدارة الهوية الرقمية»، واختر «تغيير رقم الجوال»، وأدخل رقم إقامتك أو هويتك وتاريخ ميلادك، وأدخل الرقم الجديد وأكمل التحقق الحيوي.</li>\n<li><strong>تطبيق نفاذ:</strong> افتح «إدارة حساب الهوية الرقمية»، واختر «تحديث رقم جوال الهوية الرقمية»، وأدخل رقم إقامتك، ثم الرقم الجديد والرمز الذي يصل إليه، وأكمل التحقق الحيوي. ولخطوة البصمة ضع يدك اليسرى مبسوطة ودع الكاميرا تلتقط الأصابع الأربعة دون الإبهام. فإن لم تنجح فاضبط المسافة ووضوح الصورة وأعد المحاولة. ويعمل الرقم الجديد في أبشر بعد نحو عشر دقائق.</li>\n<li><strong>جهاز أبشر للخدمة الذاتية</strong> (في مكاتب الجوازات والمجمعات التجارية والمطارات ومراكز الخدمات الحكومية): اختر لغتك، وأدخل رقم إقامتك أو هويتك، واختر «تحديث رقم الجوال»، وامسح بصمتك، ثم أدخل الرقم الجديد والرمز الذي يصل إليه. وهذا هو الطريق إن لم يعد رقمك القديم بيدك.</li>\n</ul>\n<h2>تفعيل أبشر</h2>\n<p>بعد أن تسجل في أبشر برقم إقامتك أو رقم الحدود، ورقم جوال سعودي باسمك، وبريد إلكتروني، يجب تفعيل الحساب ببصماتك. ولذلك ثلاث طرق:</p>\n<ol>\n<li><strong>في تطبيق نفاذ:</strong> افتح الإعدادات، واختر تفعيل الهوية الرقمية الوطنية عبر الخدمة الذاتية في أبشر، وادخل باسم المستخدم وكلمة المرور في أبشر، وأدخل البيانات المطلوبة، ثم التقط بصمات يدك اليسرى بكاميرا الجوال. وبعدها ادخل إلى أبشر لتتأكد أن الحساب يظهر مفعّلًا.</li>\n<li><strong>في جهاز أبشر للخدمة الذاتية</strong> (في مكاتب الجوازات والمجمعات التجارية والمطارات ومراكز الخدمات الحكومية): أدخل رقم إقامتك أو رقم الحدود، وامسح بصماتك، وأكّد بالرمز الذي يصل إلى جوالك المسجل.</li>\n<li><strong>في مكتب الجوازات،</strong> بموعد تحجزه في أبشر.</li>\n</ol>\n<p>تواجه صعوبة في تفعيل أبشر أو نفاذ من الأساس؟ انظر <a href=\"/ar/ask/absher-nafath-activation\">تفعيل أبشر أو نفاذ يفشل عندي باستمرار</a>.</p>\n<h2>نقل شريحة إلى اسم شخص آخر</h2>\n<p>الخط المسجل على إقامتك يبقى في عهدتك حتى يُنقل أو يُلغى. فإن أردت أن تسلّم شريحة لشخص آخر فاذهبا معًا إلى فرع الشركة بإقامتيكما ورقميكما المسجلين في أبشر، فيُنقل الخط هناك إلى اسم مالكه الجديد. وتتيح بعض الشركات أيضًا أن يبدأ المالك النقل من تطبيقها، فيقبله المالك الجديد بنفاذ خلال ٢٤ ساعة. ثم راجع «متصل» لتتأكد أن الخط خرج من إقامتك.</p>\n<p>وتجد عمليات تحقق أخرى لا تحتاج إلى تسجيل دخول، مثل رقم الحدود ومواعيد تأشيرتك، في <a href=\"/ar/guides/check-visa-and-iqama-online\">الاستعلام إلكترونيًا عن تأشيرتك ورقم الحدود والتأمين والمخالفات</a>.</p>"
 },
 "postgraduate-admission-1448": {
  "titleAr": "القبول في الدراسات العليا بالجامعة الإسلامية: الماجستير والدكتوراه والدبلومات",
  "summaryAr": "من يستطيع التقديم للماجستير أو الدكتوراه أو الدبلوم العالي، وكيف تتقدم من داخل المملكة أو من خارجها، وشروط كل قسم، وكيف يُرتَّب المتقدمون، ومستندات التسجيل، ومواعيد ١٤٤٨ ورسومها، وما تحصل عليه كل فئة من الطلاب.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. تقبل عمادة الدراسات العليا طلاب الماجستير والدكتوراه والدبلوم العالي مرة واحدة في السنة. وفترة التقديم لعام ١٤٤٨ مغلقة، وفترة ١٤٤٩ لم تُفتح بعد. وتبيّن دورة ١٤٤٨ أدناه ما ينبغي أن تجهّزه.</p>\n<h2>المواعيد</h2>\n<table><thead><tr><th>دفعة ١٤٤٨</th><th>فترة التقديم</th></tr></thead><tbody>\n<tr><td>الماجستير والدكتوراه</td><td>فُتحت في ١٦ نوفمبر ٢٠٢٥ وأُغلقت في أوائل ديسمبر ٢٠٢٥</td></tr>\n<tr><td>الدبلومات العليا</td><td>من ٥ إلى ١١ أبريل ٢٠٢٦ (من ١٧ إلى ٢٣ شوال ١٤٤٧)</td></tr>\n</tbody></table>\n<p>تعلن الجامعة عن كل فترة تقديم في حساب العمادة على إكس، <a href=\"https://x.com/highstudies_iu\">@highstudies_iu</a>، وفي قناتها على تيليجرام، <a href=\"https://t.me/highstudies_iu\">t.me/highstudies_iu</a>. وقد فُتحت فترة الماجستير والدكتوراه لعام ١٤٤٨ في منتصف نوفمبر واستمرت نحو ثلاثة أسابيع، فتابع هذه القنوات من أوائل نوفمبر، وجهّز مستنداتك قبل أن تُفتح.</p>\n<p>وللمتقدمين من داخل المملكة سارت دورة ١٤٤٨ بعد ذلك هكذا: الاختبارات التخصصية في منتصف يناير ٢٠٢٦، والمقابلات في أواخر يناير، وإعلان القبول ابتداءً من رمضان. ومحاضرات الدراسات العليا مسائية.</p>\n<blockquote><p>نصيحة: تقيم الجامعة في الحرم الجامعي «أسبوع الدراسات العليا» لطلاب المستويات الأخيرة. وقد افتُتح في ٢٠٢٦ يوم ٨ نوفمبر في قاعات السلام، بمعرض عن كل برنامج وشروط القبول فيه.</p></blockquote>\n<h2>كيف تتقدم</h2>\n<table><thead><tr><th>الموضوع</th><th>من داخل المملكة</th><th>من خارج المملكة</th></tr></thead><tbody>\n<tr><td><strong>من يتقدم</strong></td><td>السعوديون ومواطنو دول مجلس التعاون والمقيمون إقامة نظامية (منحة داخلية)، وطلاب المنح الخارجية الذين يدرسون في الجامعة حاليًا وأوشكوا على التخرج</td><td>المتقدمون الدوليون لمنحة خارجية ممن ليست لهم منحة في المملكة</td></tr>\n<tr><td><strong>أين تتقدم</strong></td><td>بوابة القبول في الدراسات العليا بالجامعة، <a href=\"https://postgraduate.iu.edu.sa/\">postgraduate.iu.edu.sa</a></td><td>بوابة «منحتي» للدراسات العليا، <a href=\"https://postgraduateminhatee.iu.edu.sa/\">postgraduateminhatee.iu.edu.sa</a></td></tr>\n<tr><td><strong>الاختبار التحريري</strong></td><td>إن كان القسم يعقده</td><td>تُعفى منه، إلا إن كنت حاصلًا على منحة في المملكة حاليًا</td></tr>\n</tbody></table>\n<ul>\n<li>تُدرَّس جميع البرامج في المقر الرئيسي بالمدينة المنورة.</li>\n<li><strong>ليس للجامعة مكاتب ولا وكلاء في أي مكان</strong> يستقبلون الطلبات نيابة عنها.</li>\n<li><strong>رسوم التقديم: ٣٠٠ ريال</strong> على كل متقدم، غير مستردة، وتُدفع بفاتورة إلكترونية في البوابة. ولا يُنظر في طلبك، ولا يحق لك دخول الاختبار، حتى تدفعها.</li>\n<li>تتقدم بنفسك. فاحفظ بيانات دخولك، وسجّل بريدًا إلكترونيًا ورقم جوال يعملان (دون حجب الرسائل النصية الدعائية)، وتابع طلبك في البوابة.</li>\n</ul>\n<blockquote><p>مهم: الرسالة التي تصلك من أيٍّ مما يلي تُعد إشعارًا رسميًا من الجامعة: حساب العمادة على إكس، أو بوابة القبول (الصفحة العامة أو صفحتك الخاصة)، أو بريدك الرسمي، أو رسالة نصية، أو رقم واتساب القبول، أو بريد وحدة القبول.</p></blockquote>\n<h2>من يستطيع التقديم</h2>\n<p>السعوديون، ومواطنو دول مجلس التعاون، والمقيمون في المملكة إقامة نظامية (منحة داخلية)، والمتقدمون الدوليون (منحة خارجية).</p>\n<p><strong>للتقديم يلزمك:</strong> مؤهل من جهة تعترف بها وزارة التعليم، وألا يكون لك سجل سلوكي يمنع القبول، ودفع رسوم التقديم البالغة ٣٠٠ ريال، ورفع جميع المستندات المطلوبة مطابقة للبيانات قبل الموعد النهائي، واللياقة الطبية، وأي شروط إضافية يضعها قسمك.</p>\n<p><strong>وللقبول يلزمك:</strong> اجتياز الاختبار التخصصي والمقابلة في القسم إن كان يعقدهما، واجتياز أي مقررات تكميلية يقررها، واستكمال جميع مستندات القبول قبل الموعد النهائي وإلا أُلغي الترشيح، ودفع رسوم الفصل الأول قبل التسجيل إن كان البرنامج مدفوعًا.</p>\n<p>إن تقدمت دون أن تستوفي الشروط فالمسؤولية عليك، ولا تُرد رسوم التقديم البالغة ٣٠٠ ريال. فراجع شروط برنامجك أدناه قبل أن تدفع.</p>\n<h3>عن مؤهلاتك</h3>\n<ul>\n<li><strong>غير السعودي الحاصل على مؤهل من الخارج:</strong> القبول النهائي يتطلب تصديق السفارة السعودية على مؤهلك. ويمكنك أن تتقدم وتُرشَّح قبل أن تحصل عليه.</li>\n<li><strong>من لم يتخرج بعد:</strong> يُفاضَل بينك وبين المتقدمين الآخرين بتقديرك ومعدلك التراكمي وقت التقديم، ولا يُحتسب أي ارتفاع لاحق في معدلك.</li>\n<li>تمنح الجامعة الدرجة العلمية فقط، ولا تتحمل أي مسؤولية عن توظيفك أو ترقيتك، ولا تطلب موافقة جهة عملك. وترتيب ذلك عليك أنت.</li>\n</ul>\n<h2>تدرس في الجامعة حاليًا؟</h2>\n<p>الطلاب الحاصلون على منحة من الجامعة الإسلامية يتقدمون على بوابة الدراسات العليا بالجامعة، لا على «منحتي». والقواعد لدفعة ١٤٤٨ صارمة:</p>\n<ul>\n<li><strong>يحق لك التقديم في سنتك الأخيرة</strong> إن كنت ستتخرج قبل بداية البرنامج.</li>\n<li><strong>إن كنت تخرجت فعلًا فلا يحق لك التقديم.</strong> والاستثناء الوحيد قرار خاص من رئيس الجامعة، للطلاب الذين تخرجوا بعد بداية الفصل الأول من ١٤٤٧ وما زالت منحتهم سارية.</li>\n<li><strong>السنة الأخيرة من البكالوريوس:</strong> تُعد متوقع التخرج إن كانت ساعاتك المتبقية في حدود العبء الأقصى المسموح به، بما في ذلك الفصل الصيفي.</li>\n<li><strong>السنة الأخيرة من ماجستير الرسالة:</strong> أن تكون رسالتك نوقشت مع التوصية بمنح الدرجة، أو سُلّمت وحُدد موعد مناقشتها في الفصل الثاني من ١٤٤٧ على الأكثر.</li>\n<li><strong>السنة الأخيرة من ماجستير المقررات:</strong> أن يكون مشروع تخرجك مسلَّمًا عند التقديم.</li>\n</ul>\n<p>تُرتَّب بحسب تقديرك ومعدلك يوم التقديم. وإن لم تتخرج في الوقت المحدد فقدت الترشيح، ولا يمكنك الاحتفاظ به للعام التالي. وطالب المنحة الذي ينتقل مباشرة من البكالوريوس إلى الماجستير يحتفظ بغرفته.</p>\n<p>وحاملو الإقامة على المنحة الداخلية يتقدمون على البوابة نفسها. ويحق للخريجين التقديم إن كان مؤهلهم من جامعة حكومية في دول مجلس التعاون أو من جامعة تعترف بها وزارة التعليم السعودية. أما متوقعو التخرج فلا يُقبلون إلا من الجامعة الإسلامية.</p>\n<h2>الشروط بحسب القسم</h2>\n<p>هذه أبرز شروط دفعة ١٤٤٨، فوق الشروط العامة المذكورة أعلاه. و«الاختبار» هو الاختبار التخصصي التحريري، و«المقابلة» هي المقابلة الشخصية، وكل منهما من ١٠٠. والمتقدمون من خارج المملكة ممن ليست لهم منحة حالية يُعفون من الاختبار التحريري، لكنهم يدخلون المقابلة وأي اختبار في القرآن.</p>\n<table><thead><tr><th>القسم</th><th>التقدير السابق</th><th>حفظ القرآن</th><th>درجات النجاح</th></tr></thead><tbody>\n<tr><td>العقيدة</td><td>جيد جدًا. الماجستير: مؤهل شرعي. الدكتوراه: تخصص العقيدة</td><td>لا يوجد</td><td>الاختبار ٦٠، والمقابلة ٦٠</td></tr>\n<tr><td>معهد اللغة العربية (تعليم اللغة العربية للناطقين بغيرها)</td><td>جيد جدًا للماجستير. الدبلوم: مؤهل في اللغة العربية أو الشريعة</td><td>لا يوجد</td><td>الاختبار ٦٠</td></tr>\n<tr><td>الدعوة والثقافة الإسلامية</td><td>جيد جدًا (الدبلوم: جيد)</td><td>الدبلوم جزء واحد، والماجستير ٣ أجزاء، والدكتوراه ٥</td><td>الاختبار ٦٠، والمقابلة ٦٠، والقرآن ٦٠</td></tr>\n<tr><td>التربية (ماجستير)</td><td>جيد جدًا، بالدراسة النظامية</td><td>لا يوجد</td><td>الاختبار ٦٠، والمقابلة ٦٠</td></tr>\n<tr><td>التربية (دكتوراه)</td><td>ماجستير في التخصص نفسه</td><td>لا يوجد</td><td>الاختبار ٧٠، والمقابلة ٧٠</td></tr>\n<tr><td>الفقه وأصول الفقه</td><td>جيد جدًا، بالدراسة النظامية. الماجستير: مؤهل شرعي</td><td>لا يوجد</td><td>الاختبار ٦٠، والمقابلة ٦٠</td></tr>\n<tr><td>فقه السنة</td><td>جيد جدًا</td><td>الماجستير ٣ أجزاء، والدكتوراه ٥</td><td>التحريري والشفهي ٧٠، والقرآن ٨٠</td></tr>\n<tr><td>علوم الحديث</td><td>جيد جدًا. الماجستير: مؤهل في الحديث أو الشريعة</td><td>الماجستير ٤ أجزاء، والدكتوراه ٨</td><td>التحريري والشفهي ٧٠، والقرآن ٨٠</td></tr>\n<tr><td>التاريخ والحضارة</td><td>جيد جدًا. ويحق لخريجي الجغرافيا والأدب التقديم</td><td>لا يوجد</td><td>الاختبار ٦٠</td></tr>\n<tr><td>الاقتصاد الإسلامي</td><td>جيد جدًا</td><td>لا يوجد</td><td>الاختبار ٦٠، والمقابلة ٦٠</td></tr>\n<tr><td>الدراسات القضائية</td><td>الدبلومات: جيد. الماجستير والدكتوراه: جيد جدًا</td><td>لا يوجد</td><td>الاختبار ٦٠، والمقابلة ٦٠</td></tr>\n<tr><td>القانون (الأنظمة)</td><td>جيد جدًا، بالدراسة النظامية</td><td>لا يوجد</td><td>الاختبار ٦٠، والمقابلة ٦٠</td></tr>\n<tr><td>اللغويات والأدب والبلاغة</td><td>جيد، مع بكالوريوس في اللغة العربية</td><td>لا يوجد</td><td>الاختبار ٦٠</td></tr>\n<tr><td>الإعلام والاتصال</td><td>غير محدد</td><td>لا يوجد</td><td>الاختبار ٦٠، والمقابلة ٦٠</td></tr>\n<tr><td>القراءات</td><td>جيد جدًا. الماجستير: مؤهل في القراءات أو إجازة في القراءات العشر</td><td>القرآن كاملًا</td><td>الاختبار ٦٠، والمقابلة ٦٠</td></tr>\n<tr><td>التفسير وعلوم القرآن</td><td>جيد جدًا، بالدراسة النظامية الكاملة</td><td>الماجستير ٥ أجزاء، والدكتوراه ١٠</td><td>الاختبار ٦٠</td></tr>\n</tbody></table>\n<p>الدبلوم العالي في التوجيه والإرشاد متاح لطلاب المنح الخارجية فقط، ببكالوريوس بتقدير جيد جدًا ودرجة ٦٠ في الاختبار. ومتقدم الماجستير في الدعوة الذي درس الدبلوم العالي في الدعوة والثقافة الإسلامية يلزمه معدل ٤٫٧٥ من ٥ على الأقل في الدبلوم.</p>\n<h2>العلوم والهندسة والحاسب</h2>\n<p>لبرامج الماجستير هذه شروط إضافية في دفعة ١٤٤٨:</p>\n<ul>\n<li><strong>المؤهل:</strong> بكالوريوس بالدراسة النظامية في التخصص نفسه. وبرامج الهندسة تقبل خريجي الهندسة، والطاقة المتجددة والميكاترونكس تقبلان مهندسي الكهرباء أو الميكانيكا فقط. وعلم البيانات والأمن السيبراني يقبلان خريجي علوم الحاسب وتقنية المعلومات ونظم المعلومات، لا خريجي كليات التربية.</li>\n<li><strong>المعدل:</strong> ٣٫٥٠ من ٥ أو ٢٫٥٠ من ٤ على الأقل في الهندسة والحاسب، وتقدير «جيد» على الأقل في الفيزياء والكيمياء والرياضيات.</li>\n<li><strong>اللغة الإنجليزية:</strong> التوفل الورقي ٤٥٠ على الأقل، أو التوفل الإلكتروني (iBT) ٤٥، أو الآيلتس ٤ (و٤٫٥ للأمن السيبراني)، أو اختبار STEP ٦٠، خلال السنتين الأخيرتين.</li>\n<li><strong>الإعفاء من الإنجليزية:</strong> تعفي الهندسة والعلوم منها إن كنت من مواطني دولة ناطقة بالإنجليزية أو درست البكالوريوس فيها. وتقبل العلوم أيضًا تعهدًا مكتوبًا بإحضار الشهادة قبل تقديم خطة الرسالة. أما الحاسب فلا إعفاء فيه.</li>\n<li><strong>اختبار القدرات (قياس):</strong> ٦٠ على الأقل، خلال السنوات الخمس الأخيرة، للمتقدمين السعوديين ومتقدمي المنحة الداخلية. ويُعفى منه طلاب المنح الخارجية.</li>\n<li><strong>المقابلة:</strong> مطلوبة لعلم البيانات والأمن السيبراني.</li>\n<li><strong>خطاب بيان الغرض من الدراسة:</strong> مطلوب للفيزياء والكيمياء والرياضيات.</li>\n</ul>\n<h2>كيف يُرتَّب المتقدمون</h2>\n<p>كل متقدم مستوفٍ للشروط يحصل على نسبة موزونة، وأصحاب النسب الأعلى يفوزون بالمقاعد. وتحدد اللجنة الدائمة للدراسات العليا في الجامعة عدد المقاعد لطلاب المنح الخارجية والمنح الداخلية والسعوديين، بحسب عدد الناجحين في كل فئة. وأوزان ١٤٤٨:</p>\n<table><thead><tr><th>البرامج</th><th>كيف تُحسب النسبة</th></tr></thead><tbody>\n<tr><td>التقديم من خارج المملكة (دون منحة حالية): البرامج الشرعية والعربية وبرامج العلوم والهندسة</td><td>٥٠٪ المعدل السابق، و٥٠٪ المقابلة</td></tr>\n<tr><td>التقديم من خارج المملكة (دون منحة حالية): برامج الحاسب</td><td>٥٠٪ المعدل، و٣٠٪ المقابلة، و٢٠٪ اختبار الإنجليزية</td></tr>\n<tr><td>أكثر البرامج الشرعية والعربية والتربوية والإعلامية داخل المملكة</td><td>٤٠٪ المعدل، و٣٠٪ الاختبار التحريري، و٣٠٪ المقابلة</td></tr>\n<tr><td>التفسير؛ اللغويات؛ الأدب والبلاغة؛ التاريخ والحضارة؛ دبلوم مهارات اللغة العربية؛ دبلوم التوجيه والإرشاد</td><td>٥٠٪ المعدل، و٥٠٪ الاختبار التحريري</td></tr>\n<tr><td>دبلوم التحكيم</td><td>٦٠٪ معدل البكالوريوس، و٤٠٪ المقابلة</td></tr>\n<tr><td>الحاسب، داخل المملكة</td><td>٥٠٪ المعدل، و٣٠٪ المقابلة، و١٠٪ اختبار القدرات، و١٠٪ اختبار الإنجليزية</td></tr>\n<tr><td>الهندسة، داخل المملكة</td><td>٥٠٪ المعدل، و٢٠٪ المقابلة، و١٥٪ اختبار القدرات، و١٥٪ اختبار الإنجليزية</td></tr>\n<tr><td>الفيزياء، الكيمياء، الرياضيات</td><td>٥٠٪ المعدل، و٢٥٪ اختبار القدرات، و١٥٪ المقابلة، و١٠٪ شهادة الإنجليزية</td></tr>\n<tr><td>المختبرات الصناعية (ماجستير مهني)</td><td>٥٠٪ المعدل، و٢٥٪ اختبار القدرات، و٢٥٪ سنوات الخبرة في المختبرات</td></tr>\n</tbody></table>\n<p>لا يُحتسب اختبار القدرات إلا للمتقدمين السعوديين ومتقدمي المنحة الداخلية، ويُعفى منه طلاب المنح الخارجية.</p>\n<h2>مستندات التسجيل</h2>\n<p>بعد ترشيحك، ارفع ما يلي في بوابة القبول قبل الموعد الذي تعلنه العمادة، كل مستند ملف PDF لا يتجاوز ٥ ميغابايت، وإلا أُلغي ترشيحك. للطلاب غير السعوديين:</p>\n<ol>\n<li>وثيقة التخرج</li>\n<li>السجل الأكاديمي</li>\n<li>صورة من إقامتك</li>\n<li>صورة من جواز سفرك</li>\n<li>اتفاقية القبول، موقعة ومؤرخة</li>\n<li>شهادة اختبار القدرات، للبرامج التي تشترطه</li>\n<li>تصديق السفارة السعودية على شهادتك، إن كانت من خارج المملكة</li>\n<li>شهادة اللغة الإنجليزية، للبرامج التي تشترطها</li>\n</ol>\n<p>ثم املأ نموذج التسجيل في الجامعة. وفي البرنامج المدفوع، ادفع رسوم الفصل الأول قبل تسجيلك. وإن ثبت أن شيئًا مما قدمته غير صحيح أو معدَّل أُلغي قبولك، ولو بعد أن تبدأ الدراسة، وتترتب على ذلك العقوبات النظامية.</p>\n<h2>رسوم دفعة ١٤٤٨</h2>\n<p>تُحتسب الرسوم في البرامج المدفوعة عن الحد الأدنى لمدة الدراسة فقط: سنة للدبلوم، وسنتان للماجستير، وثلاث سنوات للدكتوراه. ولا رسوم على الفصول الزائدة على ذلك. والمبالغ بالريال السعودي.</p>\n<table><thead><tr><th>البرنامج</th><th>الدرجة</th><th>للفصل الواحد</th><th>للبرنامج كاملًا</th></tr></thead><tbody>\n<tr><td>العقيدة</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>العقيدة</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>مهارات اللغة العربية</td><td>دبلوم</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>التحكيم</td><td>دبلوم</td><td>٨٬٠٠٠</td><td>١٦٬٠٠٠</td></tr>\n<tr><td>الكيمياء</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>التربية المقارنة</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>المناهج وطرق التدريس</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>المناهج وطرق التدريس</td><td>دكتوراه</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الأمن السيبراني</td><td>دبلوم</td><td>٨٬٠٠٠</td><td>١٦٬٠٠٠</td></tr>\n<tr><td>الأمن السيبراني</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الدعوة</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الدعوة والثقافة الإسلامية</td><td>دبلوم</td><td>٨٬٠٠٠</td><td>١٦٬٠٠٠</td></tr>\n<tr><td>الدعوة والثقافة الإسلامية</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>علم البيانات</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الإدارة التربوية</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الإدارة التربوية</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>علم النفس التربوي</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>إدارة الهندسة والتقنية</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الفقه</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الفقه</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>فقه السنة</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>فقه السنة</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>أصول التربية الإسلامية</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>أصول التربية الإسلامية</td><td>دكتوراه</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>التوجيه والإرشاد</td><td>دبلوم</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>علوم الحديث</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>علوم الحديث</td><td>دكتوراه</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>التاريخ والحضارة</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>التاريخ والحضارة</td><td>دكتوراه</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الثقافة الإسلامية</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الاقتصاد الإسلامي</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الاقتصاد الإسلامي</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>الدراسات القضائية</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الدراسات القضائية</td><td>دكتوراه</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>القضاء والسياسة الشرعية</td><td>دبلوم</td><td>٨٬٠٠٠</td><td>١٦٬٠٠٠</td></tr>\n<tr><td>القانون (الأنظمة)</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>القانون (الأنظمة)</td><td>دكتوراه</td><td>١٣٬٠٠٠</td><td>٧٨٬٠٠٠</td></tr>\n<tr><td>اللغويات</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>اللغويات</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>الأدب والبلاغة</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الأدب والبلاغة</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>الرياضيات</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الميكاترونكس والروبوتات</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الإعلام والاتصال</td><td>دبلوم</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الإعلام والاتصال</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الفيزياء</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>العلوم المهنية في المختبرات الصناعية</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>القراءات</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>القراءات</td><td>دكتوراه</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الأديان والمذاهب الفكرية</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الطاقة المتجددة</td><td>ماجستير</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>الفرق والمذاهب</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>الفرق والمذاهب</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>التفسير وعلوم القرآن</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>التفسير وعلوم القرآن</td><td>دكتوراه</td><td>مجاني</td><td>مجاني</td></tr>\n<tr><td>تعليم اللغة العربية للناطقين بغيرها</td><td>دبلوم</td><td>٨٬٠٠٠</td><td>١٦٬٠٠٠</td></tr>\n<tr><td>تعليم اللغة العربية للناطقين بغيرها</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>تعليم اللغة العربية للناطقين بغيرها</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n<tr><td>أصول الفقه</td><td>ماجستير</td><td>١١٬٠٠٠</td><td>٤٤٬٠٠٠</td></tr>\n<tr><td>أصول الفقه</td><td>دكتوراه</td><td>١١٬٠٠٠</td><td>٦٦٬٠٠٠</td></tr>\n</tbody></table>\n<p>دبلوم تعليم اللغة العربية للناطقين بغيرها يُعِدّ المعلمين، وهو لخريجي اللغة العربية أو الدراسات الإسلامية، وليس دورة لتعلم العربية.</p>\n<h2>ما تحصل عليه طالبًا في الدراسات العليا</h2>\n<table><thead><tr><th>إن كنت</th><th>ما تحصل عليه</th></tr></thead><tbody>\n<tr><td>سعوديًا، أو مواطنًا من دول مجلس التعاون، أو من غير محددي الجنسية المقيمين في دول المجلس، أو من أبناء المواطنات السعوديات</td><td>مقعد دراسي، والمكتبة، والخدمات الطبية، والوجبات المدعومة، والسكن المدعوم متى توفر، والأنشطة العلمية والثقافية</td></tr>\n<tr><td><strong>طالب منحة خارجية</strong> (على نفقة الجامعة)</td><td>مقعد دراسي، و<strong>مكافأة شهرية</strong>، وبدل تجهيز، وبدل كتب، وبدل طباعة، وبدل تخرج، والسكن، والوجبات المدعومة، و<strong>تذاكر السفر</strong>، والمكتبة، والخدمات الطبية، والأنشطة</td></tr>\n<tr><td><strong>طالب منحة داخلية</strong> (مقيم إقامة نظامية)</td><td>مقعد دراسي، والمكتبة، والأنشطة العلمية والثقافية</td></tr>\n</tbody></table>\n<h2>التواصل مع عمادة الدراسات العليا</h2>\n<p>يكون التواصل في أوقات الدوام الرسمي. وإن لم تُحل مشكلتك فبإمكانك التواصل معهم مرة أخرى خلال يوم عمل واحد.</p>\n<ul>\n<li>إكس: <a href=\"https://x.com/highstudies_iu\">@highstudies_iu</a></li>\n<li>واتساب وحدة القبول: <strong>0148137257</strong></li>\n<li>بريد وحدة القبول: <a href=\"mailto:g.r@iu.edu.sa\">g.r@iu.edu.sa</a></li>\n<li>التحويلات الهاتفية: <strong>31009</strong> و<strong>31006</strong></li>\n</ul>\n<p>والقبول في مرحلة البكالوريوس مشروح في <a href=\"/ar/guides/applying-to-the-islamic-university\">التقديم إلى الجامعة الإسلامية</a>.</p>\n<blockquote><p>نصيحة: لديك سؤال عن طلبك أنت؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "ramadan-in-madinah": {
  "titleAr": "رمضان في المدينة: الحرم والجامعة والحياة اليومية",
  "summaryAr": "تواريخ ١٤٤٨، والتراويح والتهجد والإفطار في المسجد النبوي، ومواعيد الروضة، والتسجيل في الاعتكاف، ومواعيد المحاضرات في الجامعة وإجازة العيد، والمحلات والدوائر وحافلات رمضان المجانية، وزكاة الفطر وصلاة العيد.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. رمضان يقلب يوم المدينة رأسًا على عقب. تسهر المدينة، ويمتلئ المسجد النبوي من العصر، ويُبسط الإفطار لمئات الآلاف في الساحات، وتجمع العشر الأواخر أكبر الحشود في السنة بعد الحج. يبدأ رمضان ١٤٤٨ في ٨ فبراير ٢٠٢٧، ويوافق عيد الفطر ٩ مارس ٢٠٢٧. ويغطي هذا الدليل الحرم، والجامعة، والحياة اليومية، وزكاة الفطر والعيد، ويبيّن ما يتغير من سنة إلى سنة.</p>\n<h2>تواريخ ١٤٤٨</h2>\n<table><thead><tr><th>ماذا</th><th>متى</th></tr></thead><tbody>\n<tr><td>١ رمضان</td><td>الاثنين ٨ فبراير ٢٠٢٧</td></tr>\n<tr><td>إجازة يوم التأسيس (الجامعة)</td><td>من ١٩ إلى ٢٢ فبراير ٢٠٢٧</td></tr>\n<tr><td>إجازة عيد الفطر في الجامعة</td><td>من ٢٦ فبراير إلى ١٣ مارس ٢٠٢٧. تتوقف المحاضرات قبل العشر الأواخر، وتُستأنف يوم الأحد ١٤ مارس</td></tr>\n<tr><td>العشر الأواخر</td><td>من ليلة ٢١ رمضان، السبت ٢٧ فبراير ٢٠٢٧</td></tr>\n<tr><td>عيد الفطر</td><td>الثلاثاء ٩ مارس ٢٠٢٧، ويُثبت برؤية الهلال في الليلة السابقة</td></tr>\n</tbody></table>\n<p>كل التواريخ في <a href=\"/ar/guides/university-calendar-1448\">تقويم الجامعة</a>، والصفحة الرئيسية تعدّ الوقت إلى الإفطار والسحور طوال الشهر.</p>\n<h2>المسجد النبوي في رمضان</h2>\n<ul>\n<li><strong>التراويح</strong> بعد العشاء، عشر ركعات وثلاث للوتر، يؤمّها أئمة المسجد بالتناوب. وتنشر الرئاسة العامة جدول الأئمة قبل بداية الشهر.</li>\n<li><strong>التهجد</strong> يُضاف في العشر الأواخر، بعد منتصف الليل وقبل السحور، ويبقى المسجد مفتوحًا طوال الليل.</li>\n<li><strong>الإفطار</strong> يُبسط على سُفر طويلة في الساحات وفي الداخل: تمر وماء ولبن وخبز وقهوة، تقدمه الأسر والجمعيات بتصاريح تصدر عبر منصة إحسان. اجلس في أي مكان، وكُل مما أمامك، وساعد في طيّ السفرة قبل صلاة المغرب. ولا يوزع أحد طعامًا بلا تصريح، فلا تحضر شيئًا لتوزيعه.</li>\n<li><strong>الروضة</strong> تعمل بجدول رمضاني، وجدول آخر للعشر الأواخر. وفي ١٤٤٧ كانت للنساء في العشر الأواخر فترة واحدة من ٦:٠٠ إلى ١١:٠٠ صباحًا، وللرجال ثلاث فترات: من ١١:٢٠ صباحًا إلى ٨ مساءً، ومن ١١ ليلًا إلى منتصف الليل، ومن ٢ إلى ٥ فجرًا. وتنشر الرئاسة جدول ١٤٤٨ قبل الشهر. احجز في نسك كالمعتاد، وفي لحظة فتح مواعيد رمضان، لأنها تنفد في دقائق.</li>\n<li><strong>مستوى الازدحام</strong> في كل مصلى وفي الساحات تنشره الرئاسة مباشرةً على alharamain.gov.sa. راجعه قبل أن تخرج من البيت في الليالي الوترية.</li>\n<li><strong>الحقائب:</strong> مركز حفظ الأمانات المجاني يحفظ الحقائب حتى أربع ساعات. وسجادة الصلاة والحقيبة الصغيرة تدخلان، أما الحقائب الكبيرة والطعام فلا.</li>\n</ul>\n<blockquote><p>نصيحة: في الجمعة والليالي الوترية كن داخل المسجد قبل أذان العشاء بساعة، وإلا صليت في الشوارع حوله. والشوارع مفروشة وفيها مكبرات صوت، وفيها يصلي أكثر أهل المدينة ليلة السابع والعشرين.</p></blockquote>\n<h2>الاعتكاف</h2>\n<p>الاعتكاف في المسجد النبوي من ٢٠ رمضان إلى آخر الشهر، ويحتاج إلى تصريح. يُفتح التسجيل في أول أيام رمضان (وفي ١٤٤٧ فُتح في ٣ رمضان) في بوابة الرئاسة على eservices.alharamain.gov.sa، بالدخول عبر نفاذ للمواطنين والمقيمين. ويُشترط أن يكون المتقدم في الثامنة عشرة فأكثر، والأماكن محدودة، والمقبولون تصلهم رسالة نصية. أحضر سجادة صلاة وملاءة خفيفة ووسادة وقطعتي إحرام. وللنساء مكان خاص بمدخل خاص. وطلاب التأشيرة التعليمية: افتحوا البوابة بنفاذ يوم فتح التسجيل، واسألوا عمادة شؤون الطلاب عبر تواصل إن رفضتكم.</p>\n<h2>الجامعة في رمضان</h2>\n<ul>\n<li>تبدأ المحاضرات الساعة ١٠:٠٠ وتُختصر إلى فترات من ٣٥ دقيقة (١٠:٠٠، ١٠:٤٠، ١١:٢٠، ١٢:٠٠)، مع استراحات عند الظهر والعصر. ويُنشر الجدول في قنوات الجامعة في الأيام التي تسبق رمضان.</li>\n<li>إجازة العيد تبدأ في ١٩ رمضان، فالعشر الأواخر خالية من المحاضرات.</li>\n<li>عمادة شؤون الطلاب تقدم إفطارًا مجانيًا كل يوم بجوار الملعب الرياضي في الجامعة، وتوزع وجبات السحور. والوجبات تنفد، فاحمل تمرًا وماءً إن كنت عائدًا متأخرًا من الحرم.</li>\n<li>حافلات الجامعة المجانية إلى الحرم تعمل في المساء. ونقاط الركوب ومواعيده تتغير في هذا الشهر: راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a> لمعرفة المواعيد الحالية.</li>\n<li>لا تقع اختبارات نهائية في رمضان ١٤٤٨. واختبارات الفصل الثاني النهائية تبدأ في ٢٥ أبريل ٢٠٢٧.</li>\n</ul>\n<h2>الحياة اليومية</h2>\n<ul>\n<li><strong>المحلات والمطاعم</strong> تغلق بعد الظهر وتفتح بعد التراويح حتى السحور. والأسواق المركزية تفتح طوال النهار. تسوّق في آخر الليل، حين تكون المدينة مستيقظة.</li>\n<li><strong>الدوائر:</strong> الدوائر الحكومية والبنوك تعمل ساعات أقصر. وأصحاب العمل في القطاع الخاص يخفّضون دوام الموظفين المسلمين إلى ست ساعات بحكم النظام. وأبشر ونفاذ وتطبيقات البنوك لا تتغير.</li>\n<li><strong>المواصلات:</strong> حافلات المدينة تشغّل حافلات رمضان المجانية من مواقف التوقف والانتقال في أنحاء المدينة إلى المسجد النبوي وإلى قباء، من ٣ عصرًا حتى ساعة بعد التراويح، وفي العشر الأواخر حتى نصف ساعة بعد التهجد. والمسارات في تطبيق حافلات المدينة كل سنة. وأسعار تطبيقات التوصيل ترتفع بعد التراويح، فامشِ أول عشر دقائق مبتعدًا عن الحرم قبل أن تطلب.</li>\n<li><strong>الأكل علنًا</strong> في النهار غير مقبول. والمسافرون غير الصائمين والأطفال يأكلون في الداخل.</li>\n<li><strong>الأسعار:</strong> أسعار الفنادق حول الحرم في أعلاها في العشر الأواخر. وللتمور والحلويات وأطعمة رمضان أسواقها، وتُفتح أسواق رمضان الليلية في أنحاء المدينة.</li>\n<li><strong>العمرة في رمضان</strong> تعدل حجة، فالقطارات والحافلات إلى مكة ممتلئة. احجز القطار وتصريح نسك قبلها بأسابيع. انظر <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء من المدينة</a>.</li>\n<li><strong>الأسر:</strong> مراكز الأطفال في الحرم ومصليات النساء أشد ازدحامًا بعد التراويح. وكل ما يخص الأخوات والأطفال في <a href=\"/ar/guides/women-at-masjid-an-nabawi\">المسجد النبوي للأخوات والأسر</a>.</li>\n</ul>\n<h2>زكاة الفطر</h2>\n<p>زكاة الفطر صاع من قوت البلد عن كل فرد من أهل البيت، تُخرج قبل صلاة العيد. وفي المدينة تُعطى أرزًا أو تمرًا للأسر المحتاجة، أو تُدفع مالًا عبر المنصة الوطنية للتبرع إحسان على ehsan.sa، التي تستقبلها عن كل شخص وبحسب المنطقة في آخر أيام رمضان بالقيمة المعلنة كل سنة. وإرسالها إلى بلدك يكون أيضًا بحوالتك العادية: انظر <a href=\"/ar/guides/sending-and-receiving-money\">إرسال المال إلى بلدك واستقباله في المدينة</a>.</p>\n<h2>العيد</h2>\n<ul>\n<li>صلاة العيد في المسجد النبوي بعد الشروق بقليل، وتنشر وزارة الشؤون الإسلامية الموعد الدقيق للمدينة في اليوم السابق (٦:٤٠ صباحًا لعيد الفطر ١٤٤٧). احضر قبلها بساعة مع سجادتك، وتوقع أن تصلي في الساحات. انظر <a href=\"/ar/ask/eid-prayer-in-madinah\">أين تقام صلاة العيد في المدينة؟</a></li>\n<li>وتقام صلاة العيد أيضًا في الجوامع الكبيرة ومصليات العيد المفتوحة في كل حي، وهي أقل ازدحامًا بكثير.</li>\n<li>تفتح المحلات عصر اليوم الأول، وتخفيضات العيد من مواسم التخفيضات الأربعة الكبرى في السنة.</li>\n<li>إجازة الجامعة مستمرة حتى ١٣ مارس، فخطط لرحلة أو دورة علمية أو أسبوع هادئ للمراجعة.</li>\n</ul>\n<h2>ما يتغير كل سنة</h2>\n<p>جدول الروضة، ومسارات الحافلات، وموعد التسجيل في الاعتكاف، ومواعيد المحاضرات في الجامعة، وموعد صلاة العيد، كلها تُعلن من جديد كل رمضان. تابع قنوات الرئاسة وتطبيق حافلات المدينة وإعلانات الجامعة في شعبان، ووضع رمضان في الصفحة الرئيسية يعرض مواعيد الإفطار والسحور لكل يوم.</p>\n<blockquote><p>نصيحة: توقفت عند خطوة، أو تغيّر موعد؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "registering-your-courses": {
  "titleAr": "تسجيل مقرراتك: الإضافة والحذف والانسحاب",
  "summaryAr": "كيف يجري تسجيل المقررات كل فصل في الجامعة الإسلامية: جدولك الثابت في الفصل الأول، وفترة الحذف والإضافة ودفعاتها، وحدود الساعات المعتمدة والمتطلبات السابقة، والإضافة والحذف مع التثبيت، والتعديل بعد انتهاء الفترة، والانسحاب من مقرر بتقدير W.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. تبني جدولك كل فصل في النظام الأكاديمي، في فترة قصيرة حول بدء الدراسة. ويشرح هذا الدليل القواعد، وترتيب الخطوات، وما تفعله حين لا يقبل النظام مقررًا. والخطوات شاشةً شاشةً لكل أجزاء النظام في <a href=\"/ar/guides/university-student-system\">استخدام نظام الطالب في الجامعة</a>.</p>\n<h2>فصلك الأول</h2>\n<ul>\n<li>تسجل كليتك مقررات فصلك الأول عنك، وتعطيك جدولًا جاهزًا. ولا تستطيع تغييره، فلا شيء عليك في فترة الحذف والإضافة.</li>\n<li>كثيرًا ما تكون جداول الفصل الأول صباحية كلها أو مسائية كلها. وهذا أمر معتاد.</li>\n<li>طوال سنتك الأولى لا تستطيع حذف مقرر ولا الانسحاب منه، ولا يُسمح بالتأجيل أو الاعتذار إلا لأسباب قاهرة.</li>\n<li>ومن فصلك الثاني تستطيع تغيير الشعب والأوقات في فترة الحذف والإضافة.</li>\n</ul>\n<h2>فترة التسجيل</h2>\n<ol>\n<li><strong>تظهر الجداول</strong> في النظام الأكاديمي في الأيام التي تسبق الفصل. فراجع ما سُجل لك تحت <strong>التسجيل الإلكتروني</strong>، ثم <strong>المقررات المسجلة</strong>.</li>\n<li><strong>يُفتح الحذف والإضافة على دفعات</strong> مرتبة على الأرقام الجامعية، ويبدأ بالأقرب إلى التخرج. وتُعلمك صفحة الحذف والإضافة، ورسالة نصية، بموعد فتحه لك. والموقع مزدحم في البداية، فإن كان بطيئًا فأعد المحاولة بعد قليل.</li>\n<li><strong>تمتد الفترة أيامًا قليلة.</strong> وللفصل الثاني من ١٤٤٨ يكون الحذف والإضافة من <strong>١٧ إلى ٢١ ديسمبر ٢٠٢٦</strong>، وتبدأ الدراسة يوم الأحد ٢٠ ديسمبر. وكل المواعيد في <a href=\"/ar/guides/university-calendar-1448\">التقويم الجامعي</a>، والنظام الأكاديمي هو المرجع المحدَّث إن مُددت فترة.</li>\n<li><strong>تبدأ الدراسة</strong> مع انتهاء الفترة، أو في أيامها الأخيرة. وبعض المعلمين يسجلون الحضور من أول محاضرة، فاحضر من اليوم الأول.</li>\n</ol>\n<h2>قبل أن تبدأ: الساعات والمتطلبات السابقة والشعب</h2>\n<ul>\n<li><strong>الساعات المعتمدة.</strong> في كليات العلوم الشرعية والعربية والأنظمة والأعمال تسجل بين <strong>١٨ و٢٥</strong> ساعة معتمدة في الفصل. وفي الكليات العلمية من <strong>١٠ إلى ٢٠</strong>. والطالب في فصله الأخير الذي يحتاج إلى ساعات أكثر ليتخرج يطلب من كليته رفع الحد حتى ٢٨ ساعة.</li>\n<li><strong>المتطلبات السابقة.</strong> لا يُفتح لك مقرر إلا بعد أن تجتاز المقرر الذي قبله. فـ«القرآن ٥» يتطلب «القرآن ٤»، و«النحو ٢» يتطلب «النحو ١»، وهكذا. ولذلك يأتي المقرر الذي رسبت فيه أو حذفته أولًا، قبل المقررات المبنية عليه. وخطتك، برموز كل مقرر ومستواه، تحت <strong>أكاديمي</strong>، ثم <strong>خطة الطالب</strong>.</li>\n<li><strong>الشعب والمعلمون.</strong> في <strong>التسجيل الإلكتروني</strong>، ثم <strong>المقررات المطروحة وفق الخطة</strong>، تجد كل شعبة بأوقاتها ومعلمها، وهل هي مفتوحة أم مكتملة. وعبارة «لم يحدد من الكلية» تعني أن المعلم لم يُعيَّن بعد. وأوقات الشعب ثابتة، أما المعلم المذكور فيتغير أحيانًا بعد إغلاق الفترة.</li>\n<li><strong>لا تعارض ولا شعب مكتملة.</strong> لا يسجل النظام مقررين في وقت واحد، ولا يفتح شعبة مكتملة.</li>\n</ul>\n<h2>الإضافة والحذف خطوة بخطوة</h2>\n<p>استخدم الحاسوب. فالصفحة لا تعمل جيدًا على الجوال، وتنتهي جلستها إن تركتها مفتوحة طويلًا. وتحقق أولًا من الفصل الظاهر أعلى الصفحة، لأنها تفتح أحيانًا على الفصل السابق. وحين يكون النظام مزدحمًا فثبّت مقررًا أو مقررين في كل مرة بدل الجدول كله دفعة واحدة، وحدّث «المقررات المسجلة» بعد كل تثبيت.</p>\n<ol>\n<li>افتح <strong>التسجيل الإلكتروني</strong>، ثم <strong>الحذف والإضافة</strong>.</li>\n<li>ضع علامة على المقرر، واضغط العدسة تحت <strong>ابحث عن شعبة</strong>، واختر رقم الشعبة.</li>\n<li>اضغط <strong>إضافة</strong>. فينتقل المقرر إلى <strong>إجراءات غير مثبتة</strong>.</li>\n<li>لحذف مقرر اضغط زر <strong>حذف</strong> الأحمر بجانبه.</li>\n<li>اضغط <strong>تثبيت</strong>. فلا يُسجَّل شيء ولا يُحذف حتى تثبّت.</li>\n<li>افتح <strong>المقررات المسجلة</strong> وراجع مجموع ساعاتك وكل مقرر.</li>\n</ol>\n<blockquote><p>نصيحة: للانتقال من شعبة مسائية إلى صباحية، دوّن الشعبة الصباحية المفتوحة من «المقررات المطروحة وفق الخطة»، ثم احذف شعبتك وأضف الجديدة في الجلسة نفسها قبل أن تضغط «تثبيت». وراجع اختياراتك قبل التثبيت: فحذف المقرر بعد التثبيت ليس سهلًا دائمًا، ولا يجوز لك أبدًا أن تنزل عن الحد الأدنى للعبء الدراسي.</p></blockquote>\n<h2>حين لا يقبل النظام مقررًا</h2>\n<table><thead><tr><th>ما تراه</th><th>معناه وما تفعله</th></tr></thead><tbody>\n<tr><td>المقرر غير موجود في «المقررات المطروحة وفق الخطة»</td><td>لم تجتز متطلبه السابق، أو لم يُطرح هذا الفصل. راجع «خطة الطالب»</td></tr>\n<tr><td>الشعبة مكتملة</td><td>عاود البحث في أوقات مختلفة، فالمقاعد تتفرغ حين يبدّل طلاب آخرون شعبهم. وإن بقيت الشعب كلها مكتملة فراسل مرشدك الأكاديمي في النظام الأكاديمي واطلب توسيع الشعبة، أو اسأل عمادة القبول والتسجيل عبر تواصل، مع رمز المقرر. وتُفتح الشعب أو تُوسَّع في الغالب حين يطلب ذلك عدد من الطلاب معًا</td></tr>\n<tr><td>تعارض مع مقرر آخر</td><td>اختر شعبة في وقت آخر، أو احذف أحد المقررين</td></tr>\n<tr><td>الصفحة تقول إن موعدك لم يحن بعد</td><td>لم تُفتح دفعتك. راجع الموعد الظاهر في الصفحة</td></tr>\n<tr><td>ساعاتك دون الحد الأدنى بسبب مقررات راسبة أو تعارض</td><td>راجع عمادة القبول والتسجيل في الدور الثالث، أو وكيل كليتك، خلال الفترة</td></tr>\n<tr><td>أنت في فصل تخرجك ولم تُسجَّل الساعات التي تحتاجها</td><td>الأمر نفسه: راجع حضوريًا خلال الفترة، ومعك «المقررات المتبقية في الخطة»</td></tr>\n</tbody></table>\n<h2>بعد إغلاق الفترة</h2>\n<ul>\n<li>تُقفل صفحة الحذف والإضافة بانتهاء الفترة. ومن بعدها يصبح أي تعديل طلبًا، ولا يُقبل إلا بعذر مقبول أو إن كنت في فصل تخرجك.</li>\n<li>لتغيير الشعبة أو الوقت راجع وكيل كليتك ومعك رقم شعبة مفتوحة لا تتعارض مع جدولك.</li>\n<li>لمقرر ناقص أو خطأ في التسجيل أرسل طلبًا عبر تواصل إلى عمادة القبول والتسجيل، مع رمز المقرر ورقم الشعبة وصورة الشاشة، أو راجع مكتبها في الدور الثالث.</li>\n<li>تصرّف في الأسبوع الأول. فكلما تأخرت صعب التعديل.</li>\n</ul>\n<h2>الانسحاب من مقرر</h2>\n<p>إن تعثرت في مقرر فتستطيع الانسحاب منه أثناء الفصل، فتحصل على <strong>W</strong> بدل الرسوب. ولا يدخل تقدير W في حساب معدلك. والانسحاب من مقررات مفردة لا يؤثر في مكافأتك ولا في غرفتك، ما دمت فوق الحد الأدنى للعبء الدراسي. وإنما يؤثر فيهما ترك الفصل كله.</p>\n<ol>\n<li>افتح <strong>أكاديمي</strong>، ثم <strong>الإعتذار عن مقرر</strong>، ثم <strong>طلب إعتذار</strong>.</li>\n<li>اختر المقرر وأرسل الطلب. ولا تحتاج إلى موافقة معلمك.</li>\n<li>تابع طلبك تحت <strong>إظهار المقررات المعتذر عنها</strong>. ويصدر القرار عادة خلال يوم إلى أسبوعين.</li>\n<li>واظب على حضور المقرر حتى تُعتمد موافقة الانسحاب. فغيابك يُحسب عليك إلى ذلك الحين.</li>\n</ol>\n<p><strong>الحدود:</strong></p>\n<ul>\n<li><strong>مقرران</strong> على الأكثر في الفصل الواحد، و<strong>ستة</strong> في دراستك كلها.</li>\n<li>مرة واحدة فقط للمقرر نفسه.</li>\n<li>لا يجوز إن نزل بك عن الحد الأدنى للعبء الدراسي، ولا في سنتك الأولى، ولا في فصل تخرجك المتوقع، ولا من مقرر حُرمت منه بسبب الغياب.</li>\n<li>في الفترة المحددة فقط. وللفصل الثاني من ١٤٤٨ تمتد من <strong>٢٠ ديسمبر ٢٠٢٦ إلى ١٣ مارس ٢٠٢٧</strong>.</li>\n</ul>\n<p>ولترك فصل كامل استخدم التأجيل أو الاعتذار بدلًا من ذلك: انظر <a href=\"/ar/guides/tajeel-and-itithaar\">أخذ فصل إجازة</a>. ولا تكتفِ أبدًا بالانقطاع عن الحضور. فالغياب عشرين يومًا متتالية بلا تأجيل ولا اعتذار يؤدي إلى طي قيدك.</p>\n<p>تدرس عن بعد في المقررات الإلكترونية؟ فانسحابك يكون عبر تواصل إلى مركز التعلم الإلكتروني: انظر <a href=\"/ar/guides/studying-online-at-the-islamic-university\">الدراسة عن بعد في الجامعة الإسلامية</a>.</p>\n<h2>التدارك</h2>\n<ul>\n<li>المقرر الذي رسبت فيه أو حذفته يجب أن تسجله مرة أخرى في فصل لاحق. فقدّمه على غيره، لأن المقررات التي بعده تنتظره.</li>\n<li>لا يُطرح في الفصل الصيفي إلا بعض المقررات، ولا يُعقد كل سنة. انظر <a href=\"/ar/ask/summer-semester\">هل يوجد فصل صيفي؟</a></li>\n<li>وأثر الرسوب على معدلك ومدة دراستك في <a href=\"/ar/guides/gpa-warnings-and-dismissal\">معدلك والإنذارات الأكاديمية والفصل الأكاديمي</a>.</li>\n</ul>\n<blockquote><p>نصيحة: مقرر لا يقبل التسجيل والفترة توشك أن تنتهي؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "scholarship-stipend-and-allowances": {
  "titleAr": "مالك من المنحة: المكافأة والبدلات والتذاكر",
  "summaryAr": "ما تدفعه المنحة الكاملة ومتى: المكافأة الشهرية ومواعيد صرفها، وبطاقة المكافأة الجامعية، وبدلات التجهيز والكتب والتفوق والتخرج، والتذكرة السنوية إلى بلدك، وسُلف صندوق الطالب، وما يوقف الصرف.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. المنحة الكاملة (الخارجية) في الجامعة الإسلامية تدفع أكثر من المكافأة الشهرية. وهذه الصفحة تبين كل مبلغ، ومتى يُصرف، وأين يصل، وما يوقفه.</p>\n<h2>ما تعطيك المنحة الكاملة</h2>\n<ul>\n<li><strong>مكافأة شهرية</strong>.</li>\n<li><strong>بدل تجهيز</strong> قدره مكافأة شهرين، يُصرف بعد وصولك أول مرة.</li>\n<li><strong>بدل كتب</strong> مرة في السنة لطلاب الكليات. وفي ١٤٤٨ صُرف في أكتوبر.</li>\n<li><strong>بدل التفوق</strong> لأصحاب الدرجات العالية. انظر أدناه.</li>\n<li><strong>بدل تخرج</strong> قدره مكافأة ثلاثة أشهر، لشحن كتبك إلى بلدك.</li>\n<li><strong>تذكرة إلى بلدك في نهاية كل عام دراسي</strong>، على الدرجة السياحية المخفضة، وبأقصر الطرق. ولا تُعطى إلا إن لم تكن جهة أخرى توفر لك تذكرة.</li>\n<li>سكن جامعي، وثلاث وجبات مدعومة في اليوم، وحافلات مجانية إلى الحرم، ورعاية طبية مجانية في المركز الطبي الجامعي.</li>\n</ul>\n<h2>المنحة الجزئية</h2>\n<p>المنحة الجزئية (الداخلية)، للمتقدمين المقيمين في السعودية، تغطي الرسوم الدراسية فقط. فلا مكافأة فيها ولا بدلات، ولا تشمل تذكرة ولا وجبات ولا سكنًا مجانيًا. وإن توفرت أماكن عرضت الجامعة على طلاب المنحة الجزئية غرفة مدفوعة في الوحدة ١٣: انظر <a href=\"/ar/guides/unit-13-and-paid-university-housing\">الوحدة ١٣ والسكن الجامعي المدفوع</a>.</p>\n<h2>المكافأة الشهرية</h2>\n<ul>\n<li><strong>قيمتها</strong> تحددها الجامعة، وتختلف باختلاف كليتك. وفي عامي ١٤٤٧ و١٤٤٨ كان طالب البكالوريوس في الكليات الشرعية والعربية يتقاضى ٨٤٠ ريالًا في الشهر. وتجد مدفوعاتك أنت في النظام الأكاديمي تحت <strong>شخصي</strong> ثم <strong>المكافآت</strong>.</li>\n<li><strong>أين تُصرف:</strong> على <strong>بطاقة المكافأة الجامعية</strong>، وهي بطاقة من مصرف الراجحي تصدرها لك الجامعة. ولا تُحوَّل إلى حساب بنكي باسمك. انظر القسم التالي.</li>\n<li><strong>متى:</strong> عادةً بين <strong>الحادي والعشرين والخامس والعشرين</strong> من كل شهر ميلادي، في آخر الليل. وإن وافق يوم الصرف عطلة نهاية الأسبوع انتقل إلى أقرب يوم عمل، وتصرفها الجامعة مبكرًا قبل الإجازات الرسمية، كاليوم الوطني ويوم التأسيس. وبعد الصرف المبكر يأتي الصرف التالي بعد أكثر من شهر.</li>\n<li><strong>طوال العام:</strong> تُصرف كل شهر، ومنها شهور الإجازة الصيفية.</li>\n<li><strong>التنبيهات:</strong> الرسالة النصية لا تصل دائمًا، فتحقق من رصيد البطاقة نفسها.</li>\n</ul>\n<h3>أشهرك الأولى</h3>\n<p>لا يتقاضى الطلاب الجدد مكافأة في شهرهم الأول. ويأتي في الشهر الثاني صرف مضاعف يغطي الشهرين: ففي سبتمبر ٢٠٢٦ تسلّم الطلاب الجدد دفعتين بقيمة المكافأة الشهرية، بينهما يوم واحد. وبدل التجهيز دفعة مستقلة. فإن لم يصلك شيء حتى نهاية شهرك الثاني فراجع قسم المكافآت في عمادة شؤون الطلاب.</p>\n<blockquote><p>نصيحة: أحضر ما يكفيك من المال لشهريك الأولين، فأول مكافأة تصلك في شهرك الثاني.</p></blockquote>\n<h2>بطاقة المكافأة الجامعية</h2>\n<ul>\n<li><strong>استلامها:</strong> يتسلم الطلاب الجدد البطاقة بعد اللقاء التعريفي. وتُصدر البطاقات وتُجدد في مكتب البطاقات بالوحدة ٢٢، من ٨:٠٠ صباحًا إلى ٢:٠٠ ظهرًا في أيام العمل. وتفعّل الجامعة البطاقة، ويأتي الرقم السري في الظرف. ويمكنك تغيير الرقم السري من أي صراف آلي للراجحي.</li>\n<li><strong>المال يخرج منها فقط:</strong> لا تقبل البطاقة إيداعًا نقديًا ولا تحويلًا إليها، ولا يمكن إضافتها إلى Apple Pay ولا إلى تطبيق الراجحي.</li>\n<li><strong>الانتفاع بالمال:</strong> اسحبه من صراف آلي للراجحي، أو انقله إلى حسابك البنكي بتطبيق برق، فوريًا ومجانًا. والخطوات بالتفصيل في <a href=\"/ar/guides/getting-your-stipend-off-the-university-card\">سحب مكافأتك من البطاقة الجامعية</a>.</li>\n<li><strong>حسابك أنت:</strong> افتح حسابًا بنكيًا سعوديًا مبكرًا ليكون لديك مكان تنقل إليه المال. وإن كنت بهوية زائر فانظر <a href=\"/ar/guides/sim-internet-bank\">شريحة الجوال والإنترنت وبطاقة بنكية سعودية</a>.</li>\n<li><strong>بطاقة مفقودة أو ابتلعها الصراف أو منتهية:</strong> اطلب من قسم المكافآت بدل فاقد. ويستغرق ذلك نحو أسبوعين، وتُخصم رسوم يسيرة من البطاقة، وتبقى مكافأتك محفوظة. والبطاقة المنتهية لا تعمل إطلاقًا، فجددها قبل تاريخ انتهائها.</li>\n<li><strong>بعد تغيير البطاقة:</strong> البطاقة الجديدة أو المجددة تؤخر الصرف أحيانًا حتى تحدّث الجامعة سجلاتها. فإن تأخرت دفعة بعد التغيير فأبلغ قسم المكافآت.</li>\n</ul>\n<h2>بدل التفوق</h2>\n<p>يتقاضى طلاب المنحة الكاملة الحاصلون على <strong>معدل فصلي ٤٫٥٠ فأكثر من ٥ في كلا الفصلين</strong> من العام الدراسي بدل التفوق مرة في السنة. وكان في السنوات الأخيرة ١٬٠٠٠ ريال.</p>\n<ul>\n<li>يُحسب معدل كل فصل وحده، ولا عبرة بالمعدل التراكمي.</li>\n<li>لا يحتاج إلى تقديم. يُصرف على بطاقة المكافأة على دفعات بعد انتهاء العام، عادةً من يوليو، وتأتي آخر الدفعات مع مكافأة أغسطس أو سبتمبر.</li>\n<li>الحرمان في أي مقرر يُسقطه.</li>\n<li>إن استوفيت الشرط ولم يصلك شيء حتى نهاية سبتمبر فاسأل قسم المكافآت.</li>\n</ul>\n<h2>سُلف صندوق الطالب</h2>\n<p>إن ضاقت بك النفقة فصندوق الطالب في الوحدة ٢٢ يعطي سُلفًا تصل إلى <strong>٢٬٠٠٠ ريال</strong>، تُسدَّد على أقساط شهرية ثابتة تُخصم من مكافأتك.</p>\n<ol>\n<li>خذ استمارة الصندوق من الوحدة ٢٢.</li>\n<li>أحضر شهادة آيبان لحسابك البنكي، وسجلك الأكاديمي، وبطاقتك الجامعية.</li>\n<li>سلّم الاستمارة. ويصل المبلغ إلى حسابك خلال أسبوع إلى أربعة أسابيع.</li>\n</ol>\n<p>لا تُعطى السلفة إلا مرة واحدة، ولا تُعطى في سنتك الأخيرة. والمعدل الجيد يقوّي طلبك. وفي الصندوق أيضًا قسم للإعانة للطلاب الذين يمرون بضائقة حقيقية.</p>\n<h2>ما يوقف المكافأة</h2>\n<ul>\n<li><strong>التأجيل أو الاعتذار:</strong> تتوقف المكافأة في الفصل الذي لا تدرس فيه. وفصل التأجيل لا يُحسب من مدة دراستك، فالفصل الإضافي الذي يضيفه في آخر دراستك تُصرف مكافأته. أما فصل الاعتذار فيُحسب منها، فالفصل الذي تضيفه لتعويضه يقع خارج المدة المدفوعة. انظر <a href=\"/ar/guides/tajeel-and-itithaar\">أخذ فصل إجازة</a>.</li>\n<li><strong>تجاوز المدة النظامية لبرنامجك:</strong> تغطي المكافأة العدد المعتاد من الفصول في خطتك الدراسية. وما زاد عليه من فصول لا مكافأة فيه إلا بموافقة الجامعة.</li>\n<li><strong>ترك الدراسة:</strong> الانسحاب أو الفصل ينهي المنحة.</li>\n</ul>\n<h2>تذكرتك إلى بلدك</h2>\n<p>في كل عام دراسي تعطيك الجامعة تذكرة ذهاب وعودة إلى بلدك على الدرجة السياحية المخفضة، تصدر بأمر إركاب على اعتماد. والقواعد الرئيسية:</p>\n<ul>\n<li>تكون إلى إحدى المدن التي تحددها الجامعة لبلدك. ففي ٢٠٢٦ مثلًا اختار الطلاب المسافرون إلى الولايات المتحدة نيويورك أو واشنطن العاصمة. وأي رحلة مواصلة بعد تلك المدينة على حسابك.</li>\n<li>لا تُعطى إلا إن لم تكن جهة أخرى توفر لك تذكرة.</li>\n<li>صالحة ٣ أشهر من تاريخ السفر الأول. ولا يُغيَّر الاسم ولا الوجهة ولا مطارا الذهاب.</li>\n<li>تغيير التاريخ على حسابك، والإلغاء يعيد التذكرة إلى الجامعة بلا استرداد نقدي، والتخلف عن الرحلة يُفقدك التذكرة.</li>\n<li>حقيبة يد واحدة وحقيبتان مشحونتان.</li>\n</ul>\n<p>طريقة طلبها، وكيف تصل التذاكر الجماعية، وماذا تفعل إن تعارضت مع اختبار، كلها في <a href=\"/ar/guides/etimad-account\">تذكرتك من الجامعة: اعتماد وأمر الإركاب والقواعد</a>.</p>\n<h2>الطلاب المتزوجون</h2>\n<p>يدير صندوق المنح في الجامعة برامج دعم لطلاب المنح المتزوجين الذين تقيم أسرهم معهم في المدينة، ومنها برنامج تفريج كرب. ويعلن الصندوق عن كل دورة في قناته على تيليجرام، <a href=\"https://t.me/BoxIslamicUniversity1\">t.me/BoxIslamicUniversity1</a>. وحين يطلب من الطلاب المتزوجين تحديث بياناتهم فأرسل إفادة قيد حديثة، وشهادة آيبان، وإقامات جميع أفراد الأسرة، كلها بصيغة PDF، قبل الموعد النهائي.</p>\n<p>ومن الدورات السابقة إعانة نقدية عاجلة (مارس ٢٠٢٤) وبطاقات تموينية (ديسمبر ٢٠٢٤). وكانت دورة البطاقات التموينية مفتوحة لطلاب المنح المتزوجين المقيمين مع أسرهم في المدينة، بما في ذلك الأسر التي تحمل فيها الزوجة إقامة باسمها أو تقيم بتأشيرة زيارة أو سياحة أو عمرة. والدورات تُغلق خلال أيام، ففعّل التنبيهات للقناة.</p>\n<h2>حين تتخرج</h2>\n<p>يتقاضى الخريجون بدل التخرج، وقدره مكافأة ثلاثة أشهر، وتذكرة أخيرة إلى بلدهم، بعد أن تؤكد الجامعة إخلاء طرفهم. ويصل البدل إلى بطاقتك بعد شهر إلى شهرين من تخرجك. والخطوات في <a href=\"/ar/guides/graduate-procedures\">مغادرة المدينة نهائيًا</a>.</p>\n<blockquote><p>نصيحة: دفعة ناقصة أو خاطئة؟ راجع شاشة المكافآت ورصيد بطاقتك أولًا، ثم اذهب إلى قسم المكافآت في عمادة شؤون الطلاب أو أرسل طلبًا عبر تواصل. وإن بقي الأمر عالقًا فراسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "seasons-and-camping": {
  "titleAr": "المدينة في كل فصل: الصيف والشتاء ورمضان وأماكن التخييم",
  "summaryAr": "السنة شهرًا بشهر، ومتى تزدحم المدينة، والصيف بالتفصيل (الحر وكيف تتقيه، وفاتورة الكهرباء، وإجازة الجامعة الطويلة وهل تسافر إلى بلدك أو تبقى، والخروج والعودة قبل السفر، والدورات الصيفية)، وأحكام التخييم وأماكنه.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. للمدينة فصلان حقيقيان، صيف حار طويل وشتاء معتدل قصير، ويمر بهما رمضان والحج متقدمَين نحو أحد عشر يومًا كل سنة. ويغطي هذا الدليل السنة شهرًا بشهر، ومتى تزدحم المدينة، والصيف بالتفصيل (الحر، وفواتيرك، وإجازة الجامعة الطويلة وما تفعل فيها)، وأحكام التخييم وأماكنه.</p>\n<h2>السنة في المدينة</h2>\n<table><thead><tr><th>الفصل</th><th>درجات الحرارة المعتادة</th><th>كيف يكون</th></tr></thead><tbody>\n<tr><td>الشتاء، من نوفمبر إلى فبراير</td><td>من ١٢ إلى ٢٤° في يناير، وأدفأ في نوفمبر</td><td>بارد وجاف في الغالب، وأفضل طقس للمشي والرحلات. والليالي باردة في الساحات المكشوفة، فأحضر طبقة إضافية للمغرب والعشاء. وأكثر المطر القليل في السنة ينزل بين نوفمبر ويناير، وأحيانًا في دفعات غزيرة مفاجئة. وهو أيضًا أشد مواسم العمرة ازدحامًا.</td></tr>\n<tr><td>الربيع، من مارس إلى مايو</td><td>من ١٥ إلى ٤٠°</td><td>لطيف في مارس وأوائل أبريل، وحار بحلول مايو. والعواصف الترابية تأتي في الغالب من مارس إلى مايو.</td></tr>\n<tr><td>الصيف، من يونيو إلى أغسطس</td><td>من ٢٨ إلى ٤٤°، وأشد في أسوأ الأيام</td><td>حار جدًا، وأغسطس أشد الأشهر حرًا. اقضِ أعمالك في الخارج قبل ٩ صباحًا أو بعد ٦ مساءً، واشرب الماء طوال اليوم. وموسم صرام التمر في أواخر الصيف.</td></tr>\n<tr><td>الخريف، من سبتمبر إلى أكتوبر</td><td>من ٢٣ إلى ٤١°</td><td>سبتمبر ما زال حارًا جدًا. وينكسر الحر خلال أكتوبر وتخفّ الحشود.</td></tr>\n</tbody></table>\n<h2>متى تزدحم المدينة</h2>\n<ul>\n<li><strong>الحج</strong> (من ٨ إلى ١٣ ذي الحجة، ويتقدم كل سنة): أسعار الفنادق في أعلاها والزحام حول الحرم شديد.</li>\n<li><strong>رمضان، ولا سيما العشر الأواخر:</strong> حشود هائلة في التراويح والتهجد. والنهار هادئ، والحياة والتسوق تبدأ بعد المغرب. والشهر كله في <a href=\"/ar/guides/ramadan-in-madinah\">رمضان في المدينة</a>.</li>\n<li><strong>من ديسمبر إلى فبراير:</strong> موسم العمرة الرئيسي، بأعداد مرتفعة لكنها أثبت.</li>\n<li>من أواخر سبتمبر إلى منتصف نوفمبر، ومن أواخر فبراير إلى مارس، أفضل جمع بين الطقس والهدوء.</li>\n</ul>\n<h2>الصيف: كم حرارته ومتى</h2>\n<table><thead><tr><th>الشهر</th><th>العظمى المعتادة نهارًا</th><th>الصغرى المعتادة ليلًا</th><th>ماذا يعني</th></tr></thead><tbody>\n<tr><td>مايو</td><td>من ٣٨ إلى ٤٠°</td><td>٢٥°</td><td>حار. الأعمال في الخارج قبل ٩ صباحًا وبعد المغرب</td></tr>\n<tr><td>من يونيو إلى أغسطس</td><td>من ٤٢ إلى ٤٥°</td><td>من ٢٨ إلى ٣٠°</td><td>حار جدًا. ساحات الحرم ساخنة الملمس بحلول الضحى، والعواصف الترابية تأتي في بعض العصاري</td></tr>\n<tr><td>سبتمبر</td><td>من ٣٩ إلى ٤١°</td><td>٢٦°</td><td>ما زال حارًا جدًا حتى الأسبوع الأخير</td></tr>\n<tr><td>أكتوبر</td><td>من ٣٣ إلى ٣٦°</td><td>٢١°</td><td>ينكسر الحر. والأمسيات لطيفة من جديد</td></tr>\n</tbody></table>\n<h2>كيف تتقي الحر</h2>\n<ul>\n<li>ابتعد عن الشمس المباشرة بين ١٠ صباحًا و٤ عصرًا. امشِ في الجانب المظلل، واستظل بمظلات ساحات الحرم، واحمل مظلة خاصة بك، والبس الألوان الفاتحة.</li>\n<li>اشرب قبل أن تعطش. من لترين إلى أربعة لترات في اليوم أمر معتاد في الصيف. وبرادات الماء عند كل باب من أبواب الحرم وفي أكثر المساجد.</li>\n<li>الصداع والدوار والتعرق الشديد والغثيان والتقلصات علامات الإجهاد الحراري: ادخل إلى مكان مكيّف، واشرب، وبرّد الرقبة والمعصمين بالماء، واسترح. أما التشوش أو الإغماء أو الجلد الحار الجاف فضربة شمس: اتصل بـ 997 فورًا، وبرّد المصاب بالماء وأنت تنتظر.</li>\n<li>الأطفال والحوامل والوالدان الكبيران ومن يصوم في يوم حار هم الأكثر عرضة. وصيام التطوع في الصيف، كعاشوراء والاثنين والخميس، يقع في أيام طويلة جدًا، فخطط لعصر هادئ.</li>\n<li>السيارة المتوقفة تصير فرنًا في دقائق. لا تترك فيها طفلًا ولا حيوانًا أبدًا، وشغّل المكيف قبل أن تركب.</li>\n<li>خط الاستشارات في وزارة الصحة 937، على مدار الساعة، وبعدة لغات.</li>\n</ul>\n<blockquote><p>نصيحة: الفجر والساعة التي بعده أجمل أوقات يوم الصيف في المدينة. والطلاب الذين يصلون الفجر في الحرم، ويدرسون حتى الظهر، وينامون بعد الظهر، ويخرجون بعد المغرب، يجدون الصيف سهلًا.</p></blockquote>\n<h2>ماذا يفعل الصيف بفواتيرك</h2>\n<p>التكييف هو أكثر فاتورة الكهرباء في الصيف. وتعرفة السكن في ٢٠٢٦ هي ١٨ هللة للكيلوواط ساعة حتى ٦٠٠٠ كيلوواط ساعة في الشهر، و٣٠ هللة فوق ذلك، مع ضريبة القيمة المضافة ١٥٪. ومن ١ يناير ٢٠٢٧ ترتفع إلى ٢١ و٣٣ هللة، مع رسم شهري ثابت نحو ٧٠ ريالًا لقاطع منزلي عادي. والشقة ذات الغرفتين مع مكيفين سبليت يعملان أكثر اليوم تستهلك من ١٠٠٠ إلى ٢٠٠٠ كيلوواط ساعة في شهر الصيف، فتوقع نحو ٢٠٠ إلى ٥٠٠ ريال في الشهر صيفًا مقابل ١٠٠ إلى ١٥٠ شتاءً، وأكثر بتعرفة ٢٠٢٧. اضبط المكيف على ٢٤°، ونظّف الفلاتر في مايو، وأغلق الستائر في الجهة المشمسة. وأرقام السنة في <a href=\"/ar/guides/cost-of-living\">كم تكلف المعيشة في المدينة</a>.</p>\n<h2>الإجازة الطويلة: التواريخ</h2>\n<table><thead><tr><th>١٤٤٨ و١٤٤٩</th><th>التاريخ</th></tr></thead><tbody>\n<tr><td>الاختبارات النهائية للفصل الثاني</td><td>من ٢٥ أبريل إلى ١٠ مايو ٢٠٢٧</td></tr>\n<tr><td>إجازة عيد الأضحى</td><td>من ١١ إلى ٢٢ مايو ٢٠٢٧</td></tr>\n<tr><td>بداية إجازة نهاية العام</td><td>٣ يونيو ٢٠٢٧</td></tr>\n<tr><td>دراسة الفصل الصيفي (اختياري، إن أقامته الجامعة)</td><td>٦ يونيو ٢٠٢٧</td></tr>\n<tr><td>الاختبارات النهائية للفصل الصيفي</td><td>٢٧ يوليو ٢٠٢٧</td></tr>\n<tr><td>بداية العام الدراسي ١٤٤٩</td><td>٢٢ أغسطس ٢٠٢٧</td></tr>\n</tbody></table>\n<p>النظام الأكاديمي هو المرجع المباشر لهذه التواريخ، وكلها في <a href=\"/ar/guides/university-calendar-1448\">تقويم الجامعة</a>.</p>\n<h2>تسافر إلى بلدك أو تبقى؟</h2>\n<table><thead><tr><th>الموضوع</th><th>السفر إلى بلدك</th><th>البقاء في المدينة</th></tr></thead><tbody>\n<tr><td>التذكرة</td><td>لطلاب المنحة الكاملة، تذكرة الجامعة السنوية الصادرة بأمر إركاب في اعتماد تغطي رحلة ذهاب وعودة واحدة إلى إحدى المدن التي تحددها الجامعة لبلدك. سجّل حين تجمع إدارة السفر قوائم الصيف، لأن من فاتته القائمة لا تذكرة له</td><td>التذكرة سنوية، والتذكرة غير المستعملة لا تُرحّل</td></tr>\n<tr><td>المكافأة</td><td>مستمرة خلال الإجازة لطلاب المنحة الكاملة</td><td>مستمرة</td></tr>\n<tr><td>السكن</td><td>طلاب المنحة الكاملة يحتفظون بغرفهم، إلا الخريجين فيخلونها بحلول الموعد الذي تحدده الجامعة (٢٧ يونيو في ٢٠٢٦). أفرغها من الأشياء الثمينة، واقفل الخزانة، والتقط صورًا، لأن السرقات من الوحدات التي تخلو تقع كل صيف</td><td>الوحدات السكنية تبقى مفتوحة. والمطعم الجامعي يغلق خلال الإجازة ويعود مع العام الجديد</td></tr>\n<tr><td>الإقامة</td><td>حاملو الإقامة يحتاجون إلى تأشيرة خروج وعودة قبل السفر. وحاملو هوية الزائر يسافرون بتأشيرتهم ويعودون بها ما دامت سارية</td><td>لا شيء عليك</td></tr>\n<tr><td>الدراسة</td><td>خذ المتون معك وحافظ على عربيتك</td><td>الدورة الصيفية في الحرم، والدورات العلمية في أنحاء المملكة، والمكتبة</td></tr>\n</tbody></table>\n<p>المنحة الجزئية (الداخلية) لا مكافأة فيها ولا تذكرة ولا سكن مجاني، فتخطط للصيف من مالك الخاص.</p>\n<h2>قبل أن تسافر للصيف</h2>\n<ol>\n<li>بالإقامة، تحقق في أبشر قبل الحجز أن تأشيرة الخروج والعودة تغطي الإجازة. وفي ١٤٤٨ تصدر الجامعة تأشيرات متعددة على دفعات بتواريخ انتهاء محددة، وأحيانًا بلا طلب، والدفعة الأخيرة تغطي إجازة الشتاء ورمضان والصيف. والتأشيرة التي تطلبها بنفسك تكلف ٢٠٠ ريال للمفردة حتى شهرين و٥٠٠ ريال للمتعددة لثلاثة أشهر. ولا تتجاوز التأشيرة تاريخ انتهاء إقامتك، فالإقامة التي تنتهي في الصيف تُجدد أولًا.</li>\n<li>عُد قبل تاريخ العودة في التأشيرة. والتمديد من الخارج بضعف الرسوم، ولا يصح إلا والتأشيرة سارية.</li>\n<li>بهوية الزائر، تحقق في أبشر أن تأشيرتك تغطي تاريخ عودتك، واسأل عمادة القبول والتسجيل عبر تواصل إن كانت تنتهي خلال الإجازة.</li>\n<li>سدد المخالفات المرورية أولًا. فالمخالفة توقف التأشيرة.</li>\n<li>الجامعة تحدد مواعيد سفر جماعية لأكثر الطلاب. وطلاب الماجستير والدكتوراه يختارون مواعيدهم، فليختاروها بعناية: القواعد في <a href=\"/ar/guides/etimad-account\">تذكرتك من الجامعة: اعتماد وأمر الإركاب والقواعد</a> تجعل تغيير الموعد مكلفًا وعدم الحضور نهائيًا.</li>\n</ol>\n<p>الرسوم والتفاصيل في <a href=\"/ar/guides/iqama-and-exit-reentry-fees\">الإقامة والخروج والعودة والخروج النهائي ورسوم المرافقين</a>.</p>\n<h2>إن بقيت: الدورات الصيفية والدراسة الهادئة</h2>\n<ul>\n<li>المسجد النبوي يقيم دورة صيفية في القرآن والمتون كل سنة في محرم وصفر، حضوريًا وعن بعد، للرجال والنساء، بمجالس بعد الفجر وبعد العصر. وفي ١٤٤٨ أقيمت من ٥ إلى ٣١ يوليو ٢٠٢٦. والتسجيل عبر البوابة التعليمية للحرم، ويُعلن في قنوات الرئاسة قبل محرم.</li>\n<li>عدد من المشايخ يوقفون دروسهم المنتظمة في الصيف وموسم الحج ويستأنفونها في ربيع الأول. وصفحة <a href=\"/ar/duroos\">الدروس</a> تبيّن الدروس المتوقفة.</li>\n<li>الدورات العلمية المكثفة تقام في مدن أخرى في صفر، وبعضها بسكن. وتُعلن في صفحة مستجدات الدروس حين تُعرف مواعيدها.</li>\n<li>المكتبة المركزية في الجامعة مفتوحة خلال الفصل الصيفي، من الأحد إلى الخميس، مكيّفة وهادئة.</li>\n<li>أهل المدينة يخرجون بعد العشاء. والحدائق وممشى قباء ومزارع النخيل عامرة حتى ما بعد منتصف الليل في الصيف.</li>\n</ul>\n<h2>الأسر في الصيف</h2>\n<ul>\n<li>المدارس مغلقة من أواخر يونيو إلى أواخر أغسطس. ومراكز اللعب ومناطق الأطفال في المجمعات التجارية هي الحل في النهار، والحدائق بعد المغرب. انظر <a href=\"/ar/guides/kids-activities\">أماكن اللعب والترفيه للأطفال في المدينة</a>.</li>\n<li>بعض المجمعات السكنية والفنادق تبيع اشتراكات صيفية في المسابح، والنادي الرياضي في الجامعة فيه مسبح لأعضائه.</li>\n<li>صرام التمر يبدأ في أواخر يوليو، وسوق التمور في أفضل حالاته في أغسطس وسبتمبر. انظر <a href=\"/ar/guides/dates-of-madinah\">تمور المدينة: الأصناف وكيف تشتري</a>.</li>\n<li>الوالدان الزائران في الصيف يجدان أرخص فنادق السنة وأشد العصاري حرًا. وخطة الزيارة في <a href=\"/ar/guides/bringing-parents-to-visit\">استقدام والديك لزيارة المدينة</a>.</li>\n</ul>\n<h2>التخييم</h2>\n<p>التخييم في البر والأودية نشاط مفضل في نهاية الأسبوع من أكتوبر إلى أبريل، لكنه منظَّم. فالتخييم في مناطق الغطاء النباتي الطبيعي يحتاج إلى ترخيص من المركز الوطني لتنمية الغطاء النباتي، يصدر عبر منصة «نباتي»، والمحميات تحتاج إلى تصريح، والتخييم بلا ترخيص في الغابات أو المتنزهات الوطنية غرامته تصل إلى ٣٠٠٠ ريال. راجع الأحكام الحالية قبل أن تذهب، واحترم المناطق التراثية المعلَّمة حول أحد.</p>\n<ul>\n<li><strong>النار:</strong> مواقد الغاز والفحم المستورد المشترى هي المعتاد. لا تشترِ ولا توقد الحطب المحلي أو الفحم المصنوع من الأشجار المحلية أبدًا: فهو ممنوع، والغرامات تبدأ بالآلاف لكل متر مكعب. ولا توقد نارًا داخل محمية أو حديقة عامة، وتحقق من قيود إشعال النار في الصيف.</li>\n<li><strong>النفايات:</strong> أعد كل شيء معك، ومنه رماد الفحم وبقايا الطعام. وأحضر أكياس نفايات كبيرة.</li>\n<li><strong>الماء والسلامة:</strong> احمل ١٠ لترات على الأقل للشخص في اليوم، وأخبر أحدًا بطريقك، وتجنب الأودية حين يُتوقع المطر.</li>\n<li><strong>الحيوانات:</strong> انفض حذاءك في الصباح، وابتعد عن الكلاب الضالة والإبل.</li>\n<li><strong>الجمعة:</strong> خطط لتكون في المدينة أو في مسجد قرية قريبة لصلاة الجمعة.</li>\n</ul>\n<h3>أماكن يخيّم فيها الناس</h3>\n<table><thead><tr><th>المكان</th><th>ملاحظات</th></tr></thead><tbody>\n<tr><td>صحراء الحمراء، شمال المدينة</td><td>رمل أحمر مفتوح، بلا ظل ولا ماء. يُنصح بسيارة دفع رباعي.</td></tr>\n<tr><td>حديقة الملك فهد</td><td>للنهار فقط. مظلات للجلوس وأماكن للشواء.</td></tr>\n<tr><td>طريق خيبر</td><td>أرض صخرية أعلى، أبرد في أمسيات الصيف. تحقق من الطقس تحسبًا للسيول.</td></tr>\n<tr><td>وادي العقيق</td><td>امتدادات رملية مستوية صلبة على بعد نحو ٣٠ كم من الحرم. أفضله من أكتوبر إلى مارس.</td></tr>\n<tr><td>وادي النقي</td><td>وادٍ رملي واسع جنوب المدينة تحبه الأسر. أفضله من أكتوبر إلى أبريل.</td></tr>\n<tr><td>سفوح جبل أحد</td><td>الجهة العامة فقط، بعيدًا عن المناطق التراثية.</td></tr>\n</tbody></table>\n<h3>المعدات</h3>\n<p>معدات التخييم تُباع عبر الإنترنت وفي المحلات حول سوق المناخة، ومنها مشاوي الفحم والدلال والفرش الأرضية.</p>\n<blockquote><p>نصيحة: توقفت عند خطوة؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "sending-and-receiving-money": {
  "titleAr": "إرسال المال إلى بلدك واستقباله في المدينة",
  "summaryAr": "طرق إرسال المال إلى الخارج من حساب أو محفظة سعودية، وكم تكلف كل طريقة حقًا، والأنظمة التي تنطبق عليك، والحدود والمواعيد، والأخطاء التي تضيّع المال، وكيف ترسل لك أسرتك المال.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. يرسل كل طالب وكل أسرة في المدينة تقريبًا مالًا إلى بلده في وقت ما: مكافأة مدّخرة للوالدين، أو عون في زواج أخ، أو الرصيد كله قبل المغادرة. ويغطي هذا الدليل طرق الإرسال، وكم تكلف كل طريقة حقًا، والأنظمة التي تنطبق عليك، وكيف تستقبل المال من بلدك.</p>\n<h2>ثلاثة أمور تعرفها أولًا</h2>\n<ul>\n<li><strong>الريال مربوط بسعر ٣٫٧٥ للدولار الأمريكي.</strong> فلا يوجد يوم جيد أو سيئ لإرسال الدولارات، وكل ما يتغير هو الرسوم والسعر إلى عملة بلدك.</li>\n<li><strong>التكلفة الحقيقية هي الرسوم مع السعر.</strong> الحوالة المعلنة بلا رسوم تكلف أكثر أحيانًا بسعر أسوأ. فقبل التأكيد اقرأ المبلغ الذي ستستلمه أسرتك، وقارن هذا الرقم بين تطبيقين.</li>\n<li><strong>كل شيء يمر عبر حسابك أو محفظتك.</strong> بعد ثلاثة أشهر من وصولك، أو حين تحمل إقامة، لا ترسل البنوك المال إلى الخارج لك إلا من حساب باسمك. ومراكز الحوالات تمنح العضوية بالإقامة. ولا ينبغي لأحد أن يرسل المال باسمك، ولا ترسله أنت باسم غيرك.</li>\n</ul>\n<h2>طرق الإرسال</h2>\n<table><thead><tr><th>الطريقة</th><th>كيف تعمل</th><th>تناسب</th></tr></thead><tbody>\n<tr><td>تطبيق بنكك</td><td>حوالة دولية إلى حساب بنكي في الخارج، من الحساب الذي تصله مكافأتك</td><td>المبالغ الكبيرة، والدول التي للبنك فيها طريق مباشر</td></tr>\n<tr><td>مركز حوالات</td><td>أذرع الحوالات التابعة للبنوك، مثل إنجاز وتحويل الراجحي، ولها فروع في المدينة وتطبيقات خاصة. العضوية بإقامتك</td><td>الاستلام النقدي للأسرة، والممرات الرئيسية إلى جنوب آسيا وأفريقيا</td></tr>\n<tr><td>محفظة رقمية</td><td>برق وD360 وموبايلي باي وSTC Bank وتيقمو ويور باي ترسل إلى الخارج من محفظة تُشحن من بطاقتك أو حسابك</td><td>المبالغ الصغيرة المتكررة، والنتيجة خلال دقائق</td></tr>\n<tr><td>شبكات الاستلام النقدي</td><td>موني جرام وويسترن يونيون، عبر التطبيقات والفروع السابقة</td><td>الأسرة التي لا حساب بنكي لها، في بلدة فيها وكيل</td></tr>\n</tbody></table>\n<p>أيّ هذه الطرق يُفتح لك يعتمد على هويتك. بالإقامة كلها. وبهوية الزائر: الحساب البنكي، والمحافظ التي قبلت هوية الزائر حين فتحتها: انظر <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر: ما يعمل وما لا يعمل</a>.</p>\n<h2>كم تكلف</h2>\n<p>البنك المركزي السعودي يضع حدًا أعلى لرسوم البنوك على الخدمات الأساسية، بدليل رسوم نافذ منذ ٢٠ فبراير ٢٠٢٦، وتُضاف ضريبة القيمة المضافة ١٥٪ إلى كل رسم. وفي نوفمبر ٢٠٢٦ يأخذ البنك حتى ٤٠ ريالًا مع الضريبة على الحوالة إلى بنك أجنبي، وأقل من ذلك على الطرق المباشرة إلى الهند وباكستان والفلبين. ومراكز الحوالات تأخذ نحو ٢٠ إلى ٥٠ ريالًا للحوالة. والمحافظ من لا شيء إلى نحو ٥٠ ريالًا، بحسب البلد وهل يذهب المال إلى حساب بنكي أو محفظة أو شباك نقدي. وفوق كل رسم يأتي سعر الصرف، وفيه أكثر الفرق، فقارن المبلغ المستلم لا الرسوم.</p>\n<h2>ما تحتاجه</h2>\n<ol>\n<li><strong>هويتك وحسابك:</strong> الإقامة أو هوية الزائر، والحساب أو المحفظة باسمك، موثقًا بنفاذ. والمواطنون الأمريكيون يجيبون عن أسئلة البنك الخاصة بقانون فاتكا، ويقدمون رقم الضمان الاجتماعي أحيانًا.</li>\n<li><strong>بيانات المستلم:</strong> اسمه الكامل كما في هويته تمامًا، واسم بنكه، ورقم الحساب أو الآيبان، ورمز السويفت للحوالة البنكية. وللاستلام النقدي: اسمه كما في الهوية التي سيبرزها.</li>\n<li><strong>الغرض:</strong> كل حوالة تسأل عنه. و«إعالة الأسرة» هو الجواب الصادق لأكثر الطلاب.</li>\n<li><strong>إثبات مصدر المال</strong> في الحوالة الكبيرة، مثل شاشة المكافآت التي تُظهر مكافأتك، أو عقد بيع سيارة.</li>\n</ol>\n<h2>الحدود والمواعيد</h2>\n<ul>\n<li>كل بنك ومحفظة يضع حدودًا يومية وشهرية خاصة به، مربوطة بدخلك الموثق، فالطالب الذي يرسل مدخرات سنة كاملة دفعة واحدة يصطدم بالحد. وزّعها على أيام أو استعمل البنك بدل المحفظة.</li>\n<li>الحوالة إلى حساب بنكي في الخارج تصل خلال يوم إلى ثلاثة أيام عمل. وحوالات المحافظ والاستلام النقدي تصل عادةً خلال دقائق.</li>\n<li>الجمعة والسبت عطلة نهاية الأسبوع في السعودية. والحوالة المرسلة مساء الخميس تتحرك يوم الأحد.</li>\n</ul>\n<h2>أخطاء تكلف المال</h2>\n<ul>\n<li><strong>آيبان خاطئ أو اسم غير مطابق.</strong> يرتد المال بعد أسابيع، وتضيع الرسوم. انسخ الآيبان من صورة شاشة، لا من ذاكرتك.</li>\n<li><strong>تسليم النقد لشخص غريب</strong> يعدك بأن يدفع لأسرتك في بلدك. التحويل غير الرسمي مخالف للنظام هنا، ولا جهة تشتكي إليها إن فشل. ومبادلة النقد مع صديق تعرفه أمر خاص بينكما.</li>\n<li><strong>حمل نقد كثير</strong> عبر المطار. النقد والذهب والأشياء الثمينة فوق حد الجمارك يجب الإفصاح عنها عند المغادرة وعند الوصول إلى بلدك.</li>\n<li><strong>التأجيل إلى الأسبوع الأخير.</strong> الحوالات تحتاج إلى الرموز المرسلة إلى رقمك السعودي وإلى أبشر يعمل، فأرسل رصيدك قبل أن تغادر نهائيًا: انظر <a href=\"/ar/guides/graduate-procedures\">مغادرة المدينة نهائيًا: التخرج والخروج النهائي والشحن وبيع الأغراض وإغلاق الحسابات</a>.</li>\n</ul>\n<h2>استقبال المال من بلدك</h2>\n<p>تستطيع أسرتك أن ترسل إلى حسابك السعودي بمعلومتين: الآيبان، وهو الرمز المكوّن من ٢٤ حرفًا ورقمًا ويبدأ بـ SA ويظهر في تطبيق بنكك، ورمز السويفت لبنكك، مع اسمك كما يحفظه البنك تمامًا. ويحوّل البنك الدولارات أو عملتهم إلى ريالات عند الوصول، خلال يوم أو يومين من الاستلام.</p>\n<ul>\n<li><strong>من يدفع الرسوم:</strong> بنك المرسل يسأل. «OUR» تعني أن المرسل يدفع كل الرسوم وتستلم المبلغ كاملًا. و«SHA» تقسمها، فيقتطع بنك في الطريق رسومه، ويصل المبلغ ناقصًا ٥٠ إلى ١٥٠ ريالًا. وفي المبالغ الصغيرة اطلب من المرسل اختيار OUR.</li>\n<li><strong>للمحافظ آيبان أيضًا،</strong> وعدة محافظ غيّرت بنوكها في ٢٠٢٥ و٢٠٢٦ وأصدرت آيبانات جديدة. أرسل لأسرتك الآيبان الظاهر في التطبيق اليوم، لا آيبانًا من رسالة قديمة.</li>\n<li><strong>الحوالة الواردة الكبيرة أو غير المعتادة</strong> يسأل البنك عن غرضها. وخطاب المنحة أو رسالة من أسرتك يجيب عن ذلك.</li>\n<li><strong>شبكات الاستلام النقدي</strong> تصرف في المدينة أيضًا بجوازك أو إقامتك. وأسرع طريق للطالب الجديد في الأسابيع الأولى بطاقة من بلده يستعملها في أي صراف، حتى يُفتح الحساب السعودي: انظر <a href=\"/ar/guides/sim-internet-bank\">شريحة الجوال والإنترنت وبطاقة بنكية سعودية</a>.</li>\n</ul>\n<h2>الزكاة والصدقة</h2>\n<p>الزكاة والصدقة للجمعيات داخل المملكة تمر عبر المنصتين الوطنيتين إحسان (ehsan.sa) وزكاتي، وتقبلان مدى والبطاقات وApple Pay. وتستقبل إحسان أيضًا زكاة الفطر في آخر أيام رمضان: تختار المنطقة وعدد الأشخاص وتدفع القيمة المعلنة للشخص. والزكاة لأسرتك ومجتمعك في بلدك تذهب مع حوالتك العادية، والغرض «زكاة» أو «إعالة الأسرة».</p>\n<blockquote><p>نصيحة: احتفظ بإيصال كل حوالة. بعض الدول تفرض ضريبة على المال الوارد من الخارج أو تسأل عن مصدره، والإيصال يجيب عن السؤال. والمزيد في <a href=\"/ar/ask/send-money-home\">كيف أحوّل المال إلى بلدي من المدينة؟</a>، أو راسل المشرف على واتساب على الرقم +1 234 567 9076 أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "shipping-and-receiving-parcels": {
  "titleAr": "إرسال الطرود واستقبالها في المدينة: عنوانك والجمارك وشركات الشحن والصناديق إلى بلدك",
  "summaryAr": "العنوان الوطني والعنوان المختصر، واستقبال الطرود من الخارج وما تفرضه الجمارك، والتسوق عبر الإنترنت، والإرسال داخل المملكة، وإرسال صناديق الكتب والهدايا إلى الخارج بالبريد أو شركات الشحن أو البحر.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. كتب من بلدك، وجوال تطلبه عبر الإنترنت، وعلبة تمر لوالدتك، ومكتبة تشحنها عند تخرجك: كل ذلك يمر عبر الأنظمة القليلة نفسها. ويغطي هذا الدليل عنوانك، واستقبال الطرود من الخارج ورسومها، والتسوق عبر الإنترنت، والإرسال داخل المملكة وإلى الخارج.</p>\n<h2>عنوانك: لا شيء يتحرك بدونه</h2>\n<p>كل توصيل في السعودية موجه إلى عنوان وطني، ومنذ يناير ٢٠٢٦ ترفض شركات الشحن الطرود التي لا تحمله. والبنوك وأبشر والجامعة تستعمله أيضًا، والتسجيل مجاني.</p>\n<ol>\n<li>افتح تطبيق البريد السعودي (سبل) أو address.gov.sa وسجّل الدخول بنفاذ. وطلاب هوية الزائر يسجلون الدخول بالطريقة نفسها بعد تفعيل أبشر ونفاذ.</li>\n<li>اختر «عناويني الوطنية»، ثم «إضافة»، وحدد مبناك على الخريطة، وأدخل رقم المبنى والوحدة والطابق.</li>\n<li>أكّد، ثم نزّل ملف إثبات العنوان بصيغة PDF. والبنوك والجامعة تقبله.</li>\n<li>احفظ عنوانك المختصر، وهو أربعة أحرف وأربعة أرقام تمثل العنوان كله، واستعمله في كل نموذج طلب.</li>\n</ol>\n<p>إن انتقلت فحدّث العنوان في التطبيق، لأن العنوان المختصر يتغير مع الشقة. والمزيد في <a href=\"/ar/ask/short-address\">ما العنوان المختصر، وكيف أعرف عنواني؟</a> وطلاب السكن الجامعي يستعملون العنوان المسجل لمبناهم، ويسألون مشرف المبنى كيف تُسلَّم الطرود هناك.</p>\n<h2>استقبال طرد من الخارج</h2>\n<ol>\n<li><strong>أعطِ المرسل عنوانك الوطني كاملًا ورقم جوالك السعودي.</strong> شركة الشحن تتصل بهذا الرقم أو تراسله للتوصيل ولأي رسوم.</li>\n<li><strong>توقّع ضريبة القيمة المضافة.</strong> ضريبة القيمة المضافة ١٥٪ تُفرض على كل المستوردات تقريبًا مهما كانت قيمتها. والشحنة الشخصية التي قيمتها ١٠٠٠ ريال أو أقل، مع تكلفة الشحن، لا رسوم جمركية عليها، بل الضريبة ورسم معالجة صغير فقط. وفوق ١٠٠٠ ريال تُضاف الرسوم الجمركية أيضًا.</li>\n<li><strong>ادفع لشركة الشحن قبل التوصيل.</strong> شركة الشحن تدفع الجمارك عند الحدود، وتحصّل منك الرسوم والضريبة ورسم المعالجة بالبطاقة أو في تطبيقها، ثم توصل. ورسم المعالجة ١٥ ريالًا على الشحنة التي قيمتها حتى ١٠٠٠ ريال، و٠٫١٥٪ من القيمة فوق ذلك، بين ١٥ و٥٠٠ ريال. وتقسيم الطلب الواحد على عدة طرود لا يفيد: الطرود التي تصل معًا تُعامل شحنةً واحدة.</li>\n<li><strong>لا تضع الأدوية في الطرود.</strong> الأدوية المرسلة بالبريد تحتجزها الجمارك ما لم يحمل المستلم تصريح الهيئة العامة للغذاء والدواء. انظر <a href=\"/ar/ask/bringing-medicine-into-saudi\">هل أستطيع إحضار دوائي المعتاد إلى السعودية؟</a></li>\n</ol>\n<p>الكتب والملابس وأكثر الأغراض الشخصية تصل بلا مشكلة. والخمور ومنتجات الخنزير والمخدرات وكل ما يخدش الحياء العام ممنوعة، فيُتلف الطرد ويُستجوب المستلم. والطائرات المسيّرة وأجهزة اللاسلكي والكميات الكبيرة من أي شيء تحتاج إلى تصريح.</p>\n<h2>التسوق عبر الإنترنت داخل المملكة</h2>\n<p>Amazon.sa ونون يوصلان في أنحاء المدينة خلال يوم إلى ثلاثة أيام، وكلاهما يقبل الدفع نقدًا أو بالبطاقة عند الاستلام. والمتاجر في المنصات الكبيرة تشحن مع الشركات المذكورة أدناه، ويصل رقم التتبع برسالة نصية. اطلب إلى عنوانك المختصر، وأجب عن اتصال المندوب، وافحص الصندوق قبل التوقيع على استلامه. وحراج وأسواق المستعمل هي مصدر الطالب للأثاث والأجهزة، مع توصيل في اليوم نفسه بسيارة نقل: انظر <a href=\"/ar/guides/everyday-apps-and-services\">التطبيقات والخدمات اليومية</a>.</p>\n<h2>إرسال طرد داخل السعودية</h2>\n<p>خمس شركات تغطي البلد كله من المدينة، مرتبة هنا أبجديًا بأسمائها اللاتينية: أرامكس، وجي آند تي إكسبريس، وناقل إكسبريس، وسمسا إكسبريس، وسبل. ولكل منها محلات في المدينة وتطبيق يحجز الاستلام من بابك.</p>\n<ul>\n<li>في نوفمبر ٢٠٢٦ يكلف الطرد الصغير إلى الرياض أو جدة أو مكة نحو ١٥ إلى ٣٥ ريالًا، وخدمة «إكسبرس بلس» من سبل تأخذ أي صندوق حتى ٣٠ كجم إلى أي مكان في المملكة بسعر ثابت ١٤١ ريالًا.</li>\n<li>غلّفه في صندوق لا في كيس، واكتب عليه العنوان المختصر للمستلم ورقم جواله، واحتفظ برقم التتبع.</li>\n<li>تبيع شيئًا لطالب في مدينة أخرى؟ شركات الشحن تحصّل المبلغ نقدًا عند التسليم لك وتحوّله إليك خلال الأسبوع.</li>\n</ul>\n<h2>إرسال طرد إلى الخارج</h2>\n<table><thead><tr><th>الطريقة</th><th>ما تعرفه</th></tr></thead><tbody>\n<tr><td>سبل</td><td>صناديق حتى ٣٠ كجم إلى كل الدول تقريبًا، بثلاث خدمات: الاقتصادي، ويُسلَّم في أقرب مكتب بريد إلى المستلم؛ والسريع، إلى الباب؛ والشحن البحري، وهو الأرخص للكيلو في الصناديق الثقيلة والأبطأ. والسعر بحسب الوزن والوجهة، وحاسبة splonline.com.sa تعطيه في دقيقة. وفي ٢٠٢٥ كان الطرد السريع بوزن ٣٠ كجم من أقل من ٣٠٠ ريال إلى جنوب آسيا إلى نحو ٧٥٠ ريالًا إلى أوروبا. وإلى الولايات المتحدة يكلف نحو ٤٠٠ و٦٢٠ و٧٨٠ ريالًا لـ ١٠ و٢٠ و٣٠ كجم في ٢٠٢٦. وخدمة العملاء 19992</td></tr>\n<tr><td>أرامكس ودي إتش إل وفيديكس وسمسا ويو بي إس</td><td>أسرع، ومتتبَّعة من الباب إلى الباب، بسعر أعلى للكيلو. اطلب من كل منها عرض سعر واسأل عن سعر خاص بالكتب</td></tr>\n<tr><td>الشحن البحري</td><td>مكاتب الشحن في المدينة تشحن بالصندوق أو بالمتر المكعب إلى أفريقيا وآسيا. أسابيع في الطريق، لكنه أرخص طريقة لنقل مكتبة كاملة</td></tr>\n<tr><td>حقيبة مسجلة إضافية</td><td>كثيرًا ما تكون الأرخص لأول ٢٠ إلى ٣٠ كجم إن كنت مسافرًا أصلًا. اشترها من شركة الطيران قبل يوم السفر</td></tr>\n</tbody></table>\n<p>كل شركة تحتسب الأكبر من الوزن الفعلي والوزن الحجمي (الطول في العرض في الارتفاع بالسنتيمتر، مقسومًا على ٥٠٠٠)، فالصندوق الكبير نصف الفارغ يكلف ما يكلفه الممتلئ. غلّف الكتب في صناديق مزدوجة الجدار بوزن ٢٠ إلى ٢٥ كجم، واكتب عنوان المستلم وهاتفه وعنوانك على جانبين وداخل الغطاء، واكتب محتويات كل صندوق بقيمة صادقة لنموذج الجمارك. والممنوع في البريد: النقد، والمجوهرات، وبطاريات الليثيوم المنفصلة، والبخاخات، والعطور بكميات، والأدوية الموصوفة، وكل ما تمنعه الوجهة. والكتب المطبوعة لا رسوم جمركية عليها في أكثر الدول، والمستلم يدفع ما ينطبق من رسوم أو ضرائب، فراجع أنظمة بلدك في «الأغراض الشخصية» قبل أن يخرج الصندوق الأول. والتمر يسافر جيدًا، وعلبة مغلقة من تمر المدينة هي الهدية التي تطلبها كل أسرة: انظر <a href=\"/ar/guides/dates-of-madinah\">تمور المدينة: الأصناف وكيف تشتري</a>.</p>\n<p>تغادر نهائيًا وتشحن كل شيء؟ الخطة كاملة، ومعها بيع ما لا تستطيع شحنه، في <a href=\"/ar/guides/graduate-procedures\">مغادرة المدينة نهائيًا: التخرج والخروج النهائي والشحن وبيع الأغراض وإغلاق الحسابات</a>.</p>\n<h2>في قطار الحرمين</h2>\n<p>كل راكب يأخذ حقيبة واحدة حتى ٢٥ كجم ومقاس ٦٥ في ٥٥ في ٣٥ سم مع قطعة يد، والأمتعة الزائدة تُرد عند نقطة التفتيش. وشباك سبل في المحطة يشحن الحقيبة الزائدة إلى محطة الوصول لتُستلم في اليوم التالي، بنحو ٧٥ إلى ١٥٠ ريالًا للحقيبة في ٢٠٢٦، فالطالب الذي ينتقل بين المدينة ومكة أو جدة بأكثر من حقيبة يرسل الصندوق الزائد قبل يوم. وماء زمزم يسافر حقيبةً مسجلة في عبوته المغلقة على أكثر شركات الطيران، ولا يُرسل بالبريد. والتفاصيل في <a href=\"/ar/guides/haramain-train-and-city-buses\">قطار الحرمين وحافلات المدينة</a>.</p>\n<blockquote><p>نصيحة: الطرد المتوقف أيامًا يعني في الغالب أن شركة الشحن لم تصل إلى رقمك أو أن عنوانك ناقص. افتح صفحة التتبع، واقرأ الملاحظة، واتصل بالشركة. ما زال متوقفًا؟ راسل المشرف على واتساب على الرقم +1 234 567 9076 أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "sim-internet-bank": {
  "titleAr": "شريحة الجوال والإنترنت وبطاقة بنكية سعودية",
  "summaryAr": "أي شبكة تختار، وكيف تحصل على الإنترنت بلا إقامة، وكيف صار بإمكان الزائرين فتح حساب بنكي.",
  "bodyHtmlAr": "<h2>شريحة الجوال</h2>\n<p>أحضر جواز سفرك وفيه تأشيرة سارية مع رقم الحدود (رقم الدخول المرتبط بتأشيرتك)، أو إقامتك إن كانت لديك. تشتري الشريحة من المطار أو من المجمعات التجارية أو من أي فرع لشركات الاتصالات. يأخذ المحل بصمتك ويسجل الخط باسمك: على جوازك ورقم الحدود إن كنت على تأشيرة أو هوية زائر، أو على إقامتك إن كانت لديك. اشترِ شريحة سعودية حقيقية لا شريحة إلكترونية للبيانات فقط، لأن البنوك وأبشر يرسلان رموز التحقق برسائل نصية. والطلاب الجدد على التأشيرة التعليمية يحتاجون هذا الرقم قبل أي شيء آخر، لأن أبشر يُسجَّل به.</p>\n<p>تختلف التغطية والأسعار من حي إلى حي ومن شهر إلى شهر، فقارن باقات كل شركة في وقتها، واسأل الطلاب في مبناك عن الشبكة الأفضل عندهم.</p>\n<h2>الإنترنت في البيت</h2>\n<p>الإنترنت الثابت في البيت (نحو ٢٥٠ إلى ٣٠٠ ريال شهريًا) يحتاج إلى إقامة. ومن لا إقامة له يشتري جهاز توجيه محمولًا (راوتر) ويضع فيه شريحة بيانات غير محدودة، فيكون عنده واي فاي للشقة كلها.</p>\n<h2>حساب بنكي محلي</h2>\n<p>منذ سبتمبر ٢٠٢٥ يسمح البنك المركزي السعودي للزائرين الذين يحملون هوية زائر بفتح حساب والحصول على بطاقة صراف، بعد أن كان ذلك يحتاج إلى إقامة. وتختلف الخطوات بين الفئتين.</p>\n<h3>بالإقامة</h3>\n<ol>\n<li>تأكد أن لديك رقم جوال سعوديًا مسجلًا على إقامتك.</li>\n<li>افتح الحساب في تطبيق البنك بالدخول عبر نفاذ، أو في الفرع بإقامتك.</li>\n<li>اطلب بطاقة مدى.</li>\n</ol>\n<h3>بهوية زائر</h3>\n<ol>\n<li>تأكد أن لديك رقم جوال سعوديًا باسمك مرتبطًا بحسابك في أبشر.</li>\n<li>فعّل نفاذ، فهو ما يتحقق به فتح الحساب عبر الإنترنت من هويتك، ثم أصدر هوية الزائر في أبشر وتأكد أنها تظهر سارية.</li>\n<li>سجّل عنوانك الوطني في البريد السعودي. يدوّن البنك عنوانك في السعودية وعنوانك في بلدك والغرض من إقامتك.</li>\n<li>افتح الحساب بإحدى طريقتين. <strong>في الفرع:</strong> خذ جوازك وأظهر هوية الزائر في تطبيق أبشر. <strong>عبر الإنترنت:</strong> قدّم الطلب في تطبيق البنك أو موقعه وأكّد هويتك عبر نفاذ. لكل بنك شروطه الإضافية، فإن ردّك بنك فجرّب بنكًا آخر.</li>\n<li>يصلك رقم الحساب برسالة نصية. استلم بطاقة مدى من الفرع أو اطلب إرسالها إلى عنوانك الوطني.</li>\n</ol>\n<p>المواطنون الأمريكيون: تُجري البنوك تدقيقًا إضافيًا بموجب اتفاقية فاتكا، وبعضها يطلب رقم الضمان الاجتماعي، فاحمله معك.</p>\n<p>حساب هوية الزائر يعمل ما دامت هوية الزائر ومدة بقائك ساريتين. فإذا انتهت الهوية جمّد البنك الحساب حتى تُجدَّد، فجدّد تأشيرتك في وقتها.</p>\n<blockquote><p>نصيحة: بطاقة مدى تستحق العناء. بعض المحلات لا تقبل إلا مدى أو النقد، والبطاقات الأجنبية يوقفها أحيانًا نظام الأمان في البنك، وتحتاج بطاقة محلية لدفع الفواتير والرسوم الحكومية.</p></blockquote>\n<p>عندك شريحة من قبل؟ انظر <a href=\"/ar/guides/phone-sims-and-absher\">رقم جوالك والتحقق من الشرائح وأبشر</a> لمعرفة رموز التحقق والتحقق من الشرائح وتحديث رقمك في أبشر.</p>\n<p>طلاب الجامعة: تُصرف المكافأة على <a href=\"/ar/guides/getting-your-stipend-off-the-university-card\">بطاقة المكافأة الجامعية</a>، لا في حساب تفتحه بنفسك. وحسابك الخاص لاستقبال المال من بلدك ولنقل مكافأتك إليه. انظر <a href=\"/ar/guides/new-student-steps\">الخطوات الأولى للطلاب الجدد</a>.</p>"
 },
 "sisters-studying-in-madinah": {
  "titleAr": "أين تدرس الأخوات العربية والعلوم الشرعية في المدينة",
  "summaryAr": "الخيارات الحضورية للأخوات، مرتبة أبجديًا بأسمائها اللاتينية: المراكز النسائية للعربية والقرآن والشريعة، ومعهد المسجد النبوي وكليته، مع بيان لمن يصلح كل منها وما يدرّسه وطريقة التقديم.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. في المدينة عدة أماكن تدرس فيها الأخوات العربية والقرآن والعلوم الشرعية حضوريًا، وهي مرتبة هنا أبجديًا بحسب أسمائها اللاتينية، ومعهد المسجد النبوي وكليته معًا في آخرها. والتدريس فيها كلها بالعربية، وأكثر الدروس صباحية. ويلزم التواصل مع كل جهة لمعرفة موعد بدء فصلها القادم قبل بناء أي خطة عليه.</p>\n<h2>نظرة سريعة</h2>\n<table><thead><tr><th>المكان</th><th>ما يدرّسه</th><th>المدة</th><th>الحضانة</th></tr></thead><tbody>\n<tr><td>أكاديمية المعرفة</td><td>العربية لغير الناطقات بها، والشريعة، والقرآن</td><td>العربية سنتان، والشريعة سنة</td><td>نعم</td></tr>\n<tr><td>دار التوحيد والسنة</td><td>القرآن والتجويد والعربية والمتون</td><td>دروس مستمرة</td><td>نعم، للأعمار من سنة إلى ٣ سنوات، وروضة للأعمار من ٤ إلى ٦ سنوات</td></tr>\n<tr><td>مركز مشكاة</td><td>العربية والدراسات الإسلامية</td><td>سنتان</td><td>نعم</td></tr>\n<tr><td>مركز طيبة</td><td>العربية في ٤ مستويات، مع القرآن والدراسات الإسلامية</td><td>سنتان</td><td>نعم</td></tr>\n<tr><td>معهد المسجد النبوي</td><td>المتون العلمية، في المرحلتين المتوسطة والثانوية</td><td>٦ سنوات</td><td>لا</td></tr>\n<tr><td>كلية المسجد النبوي</td><td>بكالوريوس في الشريعة</td><td>٤ سنوات</td><td>لا</td></tr>\n</tbody></table>\n<h2>أكاديمية المعرفة</h2>\n<p>تديرها جمعية المعرفة الخيرية بالمدينة المنورة، وهي للنساء اللواتي ليست العربية لغتهن الأولى. وعُرفت من قبل بأسماء مركز المنار ومركز تعلّم ومركز نبراس.</p>\n<ul>\n<li><strong>المكان:</strong> حي الإسكان، مقابل مسجد عبد اللطيف آل الشيخ. الهاتف 014 846 1300.</li>\n<li><strong>برنامج العربية (سنتان):</strong> مستوى تمهيدي (الحروف والقراءة والكتابة والقرآن)، ثم أربعة مستويات على سلسلة كتب المدينة تشمل النحو والقراءة والتعبير والكتابة. ويضيف المستويان الثالث والرابع العقيدة والحديث والسيرة والتاريخ. وتحفظ الطالبات جزء عمّ وجزء تبارك إلى جانب الدراسة.</li>\n<li><strong>برنامج الشريعة (سنة واحدة، في مستويين):</strong> التفسير والحديث والفقه والعقيدة وعلوم القرآن والنحو والتجويد وأصول الفقه، ثم السيرة والتربية ومصطلح الحديث والبحث العلمي. ويتطلب مستوى جيدًا في العربية.</li>\n<li><strong>برنامج القرآن:</strong> للطالبات المتمكنات من العربية الحافظات سبعة أجزاء. ويدرّسه معلمون رجال من وراء ساتر، بإشراف معلمة.</li>\n<li><strong>التقديم:</strong> جواز السفر مع الإقامة أو التأشيرة، واختبار تحديد المستوى.</li>\n<li><strong>للأمهات:</strong> حضانة، وحافلة نقل برسوم.</li>\n</ul>\n<h2>دار التوحيد والسنة</h2>\n<p>مركز نسائي في حي السقمان للأخوات والفتيات. وبدأت الدراسة فيه في ١ نوفمبر ٢٠٢٦.</p>\n<ul>\n<li><strong>ما يدرّسه:</strong> القرآن والتجويد والقاعدة النورانية واللغة العربية والمتون الشرعية الأساسية.</li>\n<li><strong>التقديم:</strong> حضوريًا في المركز بين السابعة والحادية عشرة صباحًا. والمقاعد محدودة.</li>\n<li><strong>للأمهات:</strong> حضانة للأعمار من سنة إلى ٣ سنوات، وروضة للأعمار من ٤ إلى ٦ سنوات.</li>\n</ul>\n<p>وبيانات التواصل في صفحة <a href=\"/ar/programs/dar-tawheed-sunnah\">دار التوحيد والسنة</a>.</p>\n<h2>مركز مشكاة</h2>\n<ul>\n<li><strong>المكان:</strong> حي العريض. <a href=\"https://maps.app.goo.gl/1UFgNiPjZ7pS1ybu9\">الموقع على خرائط جوجل</a></li>\n<li><strong>المدة:</strong> سنتان.</li>\n<li><strong>الكتب:</strong> «العربية بين يديك»، مع كتب في الدراسات الإسلامية يختارها المركز. ودروس القرآن تشمل جزء عمّ وبعض جزء تبارك.</li>\n<li><strong>التقديم:</strong> جواز السفر مع الإقامة أو التأشيرة. ولا يُطلب اختبار تحديد المستوى إلا ممن تريد البدء فوق المستوى الأول.</li>\n<li><strong>للأمهات:</strong> حضانة.</li>\n</ul>\n<h2>مركز طيبة</h2>\n<ul>\n<li><strong>المكان:</strong> حي طيبة. <a href=\"https://maps.app.goo.gl/NPFFeZu8MUvxfnK19\">الموقع على خرائط جوجل</a></li>\n<li><strong>المدة:</strong> سنتان، في ٤ مستويات.</li>\n<li><strong>الكتب:</strong> «العربية بين يديك» من الكتاب الأول إلى الرابع، مع القرآن والكتابة في كل مستوى. ويضيف المستوى الأول القاعدة النورانية، وتضيف المستويات من الثاني إلى الرابع الفقه والعقيدة والسيرة والحديث، ويضيف المستويان الثالث والرابع التفسير، ويضيف المستوى الرابع الإملاء.</li>\n<li><strong>التقديم:</strong> جواز سفر الطالبة وإقامة زوجها، ثم اختبار تحديد المستوى. وإذا اكتمل العدد في المستوى بدأت الطالبة في الفصل الدراسي التالي.</li>\n<li><strong>للأمهات:</strong> حضانة، وحافلة نقل برسوم.</li>\n</ul>\n<h2>معهد وكلية المسجد النبوي</h2>\n<p>دراسة مجانية بدوام كامل داخل الحرم، في مصليات النساء بالمسجد. ولا يحضر الأطفال الدروس.</p>\n<ul>\n<li><strong>المعهد، المرحلة المتوسطة (٣ سنوات):</strong> متون تأسيسية في التجويد والتوحيد والتفسير والحديث والفقه والفرائض والسيرة والنحو والإملاء والخط العربي. وتحفظ الطالبات جزء عمّ.</li>\n<li><strong>المعهد، المرحلة الثانوية (٣ سنوات):</strong> متون أعلى، وتُضاف إليها أصول التفسير ومصطلح الحديث والتاريخ والبلاغة. ويُشترط للالتحاق بها حفظ سبعة أجزاء. وتنتهي كل مرحلة بشهادة.</li>\n<li><strong>الكلية (٤ سنوات):</strong> بكالوريوس في الشريعة.</li>\n</ul>\n<h3>من يحق لها التقديم</h3>\n<ul>\n<li>يُشترط لغير السعوديات إقامة سارية. ولا تكفي هوية الزائر ولا تأشيرة الزيارة للتسجيل.</li>\n<li>إجادة العربية كتابة ومحادثة، فالاختبار والمقابلة بالعربية.</li>\n<li>الشهادات الصادرة من خارج المملكة يجب أن تُعادَل وتُصدَّق قبل التقديم.</li>\n<li>التابعات يحتجن إلى خطاب إذن من الكفيل. وتُحضِر المتقدمات للكلية أيضًا خطابَي تزكية من مدرسة أو من معلم قرآن.</li>\n</ul>\n<h3>موعد التقديم وطريقته</h3>\n<p>يفتح التسجيل مرة واحدة في السنة، في شهر صفر، للمعهد والكلية معًا. وكان في عام ١٤٤٨ من ٥ إلى ٢٠ صفر (من ١٩ يوليو إلى ٣ أغسطس ٢٠٢٦).</p>\n<ol>\n<li>التقديم إلكترونيًا على بوابة الهيئة العامة للعناية بشؤون المسجد الحرام والمسجد النبوي أثناء فترة التسجيل، مع جمع المستندات كلها في ملف PDF واحد.</li>\n<li>أداء الاختبار التحريري حضوريًا. وكان في عام ١٤٤٨ يوم ١١ ربيع الأول (٢٤ أغسطس ٢٠٢٦).</li>\n<li>حضور المقابلة الشخصية حضوريًا. وكانت في عام ١٤٤٨ يوم ١٣ ربيع الأول (٢٦ أغسطس ٢٠٢٦).</li>\n<li>إحضار أصول المستندات وصورها عند القبول، ثم بدء الدراسة.</li>\n</ol>\n<p>والشروط الكاملة لكل مرحلة في <a href=\"/ar/guides/masjid-an-nabawi-institute-and-college\">معهد المسجد النبوي وكلية المسجد النبوي</a> و<a href=\"/ar/programs/nabawi-women\">برامج المسجد النبوي للنساء</a>.</p>\n<h2>الدراسة دون التحاق</h2>\n<p>حلقات القرآن والمتون المجانية للأخوات في الحرم يُسجَّل فيها إلكترونيًا، والدروس العلمية في المسجد مفتوحة للجميع. انظر <a href=\"/ar/guides/women-at-masjid-an-nabawi\">المسجد النبوي للأخوات والأسر</a>. وللدراسة عن بُعد والطرق الأخرى، انظر <a href=\"/ar/ask/sisters-study\">أين تدرس الأخوات؟</a> و<a href=\"/ar/programs\">الدراسة في المدينة</a>.</p>\n<blockquote><p>نصيحة: لديكِ سؤال عن حالتك الخاصة؟ راسلي المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "sports-and-activities": {
  "titleAr": "الرياضة وحصص اللياقة",
  "summaryAr": "مرافق النادي الرياضي بالجامعة الإسلامية وأسعار الاشتراك وقواعد إيقافه مؤقتًا، إضافة إلى حصص الجوجيتسو واللياقة للأطفال والكبار بمواعيدها وأسعارها.",
  "bodyHtmlAr": "<p>تتناول هذه الصفحة النادي الرياضي بالجامعة الإسلامية داخل الحرم الجامعي، والحصص المنتظمة التي تُقام فيه للطلاب والأسر. والصالات الرياضية في المدينة للرجال فقط أو للنساء فقط (انظر <a href=\"/ar/guides/everyday-apps-and-services\">التطبيقات والخدمات اليومية</a> للأسعار المعتادة). روجعت التفاصيل في ٩ نوفمبر ٢٠٢٦.</p>\n<h2>النادي الرياضي بالجامعة الإسلامية</h2>\n<p>يقع النادي الرياضي للجامعة في الحرم الجامعي الرئيسي، خلف الكليات العلمية، وله فرع واحد. ويستطيع الاشتراك فيه طلاب الجامعة ومنسوبوها ومن هم من خارج الجامعة، لكلٍّ سعره، والطلاب يدفعون الأقل.</p>\n<h3>المرافق</h3>\n<ul>\n<li>صالة رياضية مغلقة فيها ملاعب لكرة السلة وكرة اليد والكرة الطائرة، ومقاعد للجمهور</li>\n<li>مسبح أولمبي مغطى ومكيف، ومسبح أولمبي خارجي مغلق للصيانة</li>\n<li>ملعب إسكواش</li>\n<li>صالة للأثقال وبناء الأجسام</li>\n<li>صالة كروس فت</li>\n<li>صالة كارديو فيها دراجات ثابتة وأجهزة إليبتيكال</li>\n<li>ملاعب خارجية لكرة القدم والخماسيات والكرة الطائرة والتنس</li>\n<li>IU Coffee للمشروبات الساخنة والباردة والوجبات الصحية، وIU Store متجر للمستلزمات الرياضية</li>\n</ul>\n<h3>أسعار الاشتراك</h3>\n<table><thead><tr><th>الاشتراك</th><th>طلاب الجامعة</th><th>منسوبو الجامعة</th><th>غيرهم</th></tr></thead><tbody>\n<tr><td>يوم واحد</td><td>٣٠ ريالًا</td><td>٣٠ ريالًا</td><td>٣٠ ريالًا</td></tr>\n<tr><td>شهر</td><td>١٢٥ ريالًا</td><td>١٧٥ ريالًا</td><td>٢٥٠ ريالًا</td></tr>\n<tr><td>٣ أشهر</td><td>٣٤٥ ريالًا</td><td>٤٥٠ ريالًا</td><td>٦٠٠ ريال</td></tr>\n<tr><td>٦ أشهر</td><td>٦٠٠ ريال</td><td>٨٠٠ ريال</td><td>١٬٠٠٠ ريال</td></tr>\n<tr><td>١٢ شهرًا</td><td>١٬٠٠٠ ريال</td><td>١٬٢٠٠ ريال</td><td>١٬٧٠٠ ريال</td></tr>\n</tbody></table>\n<p>كل الأسعار شاملة ضريبة القيمة المضافة. وفي اشتراك الشهر يدفع الطالب نصف السعر العام تمامًا. وفي الاشتراكات الأطول يوفر الطالب نحو ٤٠٪ (مثلًا ١٬٠٠٠ ريال في السنة بدل ١٬٧٠٠)، لكن التكلفة الشهرية تنخفض أكثر: فالسنة تعادل نحو ٨٣ ريالًا في الشهر.</p>\n<h3>إيقاف الاشتراك مؤقتًا</h3>\n<p>تستطيع إيقاف (تجميد) الاشتراك الأطول مؤقتًا، كأن تسافر في الإجازات:</p>\n<ul>\n<li>٣ أشهر: مرة واحدة، حتى ١٥ يومًا</li>\n<li>٦ أشهر: مرة واحدة، حتى ٣٠ يومًا</li>\n<li>١٢ شهرًا: مرتين، حتى ٦٠ يومًا في المجموع</li>\n</ul>\n<blockquote><p>نصيحة: اشتراك اليوم الواحد بـ٣٠ ريالًا للجميع، فجرّب النادي مرة قبل أن تدفع اشتراكًا أطول.</p></blockquote>\n<p>الخصومات في الصالات والأندية وإسطبلات الفروسية الأخرى في المدينة مذكورة في <a href=\"/ar/discounts\">خصومات الطلاب</a>.</p>\n<h2>الجوجيتسو والمصارعة واللياقة في المركز الرياضي بالجامعة الإسلامية</h2>\n<p>يقدم برنامج Sunnah Strength حصصًا للأطفال والكبار في المركز الرياضي بالجامعة. والمدرب مدرب رياضة ولياقة أمريكي، معتمد من NASM وASEP، وحاصل على الحزام الأسود في الجوجيتسو. والبرنامج يناسب المبتدئين ويشمل الجوجيتسو والمصارعة بأنواعها، وتدريب القوة واللياقة، وتمارين القفز (البلايومتركس)، والدفاع عن النفس والنزال، وتحديات بناء روح الفريق.</p>\n<h3>الأطفال</h3>\n<p>البنون من ٥ إلى ١٤ سنة، والبنات من ٥ إلى ١١ سنة.</p>\n<table><thead><tr><th>الأيام</th><th>الوقت</th></tr></thead><tbody>\n<tr><td>الأحد والثلاثاء والخميس</td><td>٢:٠٠ إلى ٣:٠٠ مساءً</td></tr>\n<tr><td>الاثنين والأربعاء (جديد)</td><td>٥:٣٠ إلى ٦:٣٠ مساءً</td></tr>\n<tr><td>السبت</td><td>١٠:٠٠ صباحًا</td></tr>\n</tbody></table>\n<p>الرسوم الشهرية: ٢٧٥ ريالًا للطفل الواحد، و٢٥٠ ريالًا لكل طفل لطفلين أو أكثر، و٢٠٠ ريال لكل طفل لأربعة أطفال أو أكثر.</p>\n<h3>الكبار (١٥ سنة فأكثر)</h3>\n<table><thead><tr><th>الأيام</th><th>الوقت</th></tr></thead><tbody>\n<tr><td>الأحد والثلاثاء والخميس</td><td>١:٠٠ إلى ٢:٠٠ مساءً</td></tr>\n<tr><td>الاثنين والأربعاء (حصة مسائية)</td><td>٦:٣٠ إلى ٧:٣٠ مساءً</td></tr>\n</tbody></table>\n<p>الرسوم الشهرية: ٢٠٠ إلى ٢٥٠ ريالًا. والكبار من ١٨ سنة فأكثر في البرنامج يستعملون أيضًا مرافق الصالة الرياضية بالجامعة، ومنها منطقة الكروس فت والمسبح والساونا.</p>\n<p>للإخوة والأسر وطلاب الجامعة الإسلامية خصومات، فاسأل عند التسجيل. ويُقدَّم أيضًا تدريب خاص فردي ودروس سباحة.</p>\n<p>للتسجيل أو السؤال، اتصل أو راسل على واتساب: <strong>+966 56 171 7539</strong>.</p>"
 },
 "studying-online-at-the-islamic-university": {
  "titleAr": "الدراسة عن بُعد في الجامعة الإسلامية: برامج التعليم عن بُعد خطوة بخطوة",
  "summaryAr": "برامج الجامعة الإسلامية الثلاثة عن بُعد وتكاليفها، واختيار التخصص، والتقديم وأول دخول، والتسجيل والدفع كل فصل، والمحاضرات المباشرة والمسجلة، والحضور، ودرجات أعمال الفصل الستون، والاختبارات والكاميرا مفتوحة، والنتائج، والطلبات، والمشكلات الشائعة، وبمن تتواصل.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. تقدّم الجامعة الإسلامية بعض برامجها عن بُعد، فتدرس مقررات جامعية في العلوم الشرعية وأنت في بلدك، باللغة العربية، على أيدي أساتذة الجامعة أنفسهم. ويشرح هذا الدليل برامج الدراسة عن بُعد الثلاثة، وتكاليفها، وكيف يسير الفصل من التسجيل إلى النتائج. والشاشات هي نفسها التي يستعملها الطلاب في المدينة، وكل واحدة منها مشروحة خطوة بخطوة في <a href=\"/ar/guides/university-student-system\">استعمال النظام الطلابي في الجامعة</a>.</p>\n<p>الدراسة عن بُعد منفصلة عن المنحة للدراسة في المدينة. فإن أردت القدوم إلى المدينة طالبًا متفرغًا فانظر <a href=\"/ar/guides/applying-to-the-islamic-university\">التقديم إلى الجامعة الإسلامية</a>.</p>\n\n<h2>برامج الدراسة عن بُعد الثلاثة</h2>\n<table><thead><tr><th></th><th>المقررات الجامعية الإلكترونية</th><th>بكالوريوس الشريعة عن بعد</th><th>الدبلوم المشارك في القراءات السبع</th></tr></thead><tbody>\n<tr><td><strong>ما تدرسه</strong></td><td>أي تخصص من سبعة: القرآن الكريم، والحديث الشريف، والعقيدة والدعوة، والشريعة، واللغة العربية، والاقتصاد، والأنظمة</td><td>الشريعة فقط</td><td>القراءات السبع</td></tr>\n<tr><td><strong>الخطة</strong></td><td>مرنة: تختار مقرراتك وعبئك الدراسي بنفسك</td><td>ثابتة: ثمانية مستويات، في كل منها نحو تسعة مقررات، وعليك الالتزام بها</td><td>فصلان دراسيان</td></tr>\n<tr><td><strong>العبء في كل فصل</strong></td><td>لا حد أدنى، وحتى ٢٥ ساعة معتمدة</td><td>من ١٢ إلى ٢٥ ساعة معتمدة</td><td>يحدده البرنامج</td></tr>\n<tr><td><strong>المدة</strong></td><td>بلا حد زمني</td><td>من ٨ إلى ١٢ فصلًا دراسيًا</td><td>فصلان دراسيان</td></tr>\n<tr><td><strong>ما تحصل عليه</strong></td><td>شهادة لكل مقرر تنجح فيه، وشهادة مصغرة لكل مجموعة من المقررات المترابطة، ودبلوم مشارك أو دبلوم متوسط أو بكالوريوس متى أكملت متطلباته</td><td>بكالوريوس في الشريعة</td><td>دبلوم مشارك</td></tr>\n<tr><td><strong>التكلفة</strong></td><td>٢٣٠ ريالًا للساعة المعتمدة، مع رسوم تسجيل قدرها ٢٣٠ ريالًا كل فصل</td><td>مجاني للطلاب الحاصلين على منحة</td><td>٢٣٠ ريالًا للساعة المعتمدة</td></tr>\n<tr><td><strong>القبول</strong></td><td>بلا مقابلة. تقدّم عبر الإنترنت وترفع مستنداتك</td><td>لا يُطرح إلا حين تموّل جهات مانحة منحًا له. وتختار الجامعة المستفيدين من بين المتقدمين، فالمقاعد أقل</td><td>حفظ القرآن كاملًا، ومقابلة شخصية</td></tr>\n</tbody></table>\n<p>وتُختم كلتا درجتي البكالوريوس باختبار يُؤدّى حضوريًا في نهاية البرنامج. وما سوى ذلك من الدراسة، بما فيه المحاضرات والاختبارات، يكون عبر الإنترنت.</p>\n\n<h2>أي البرامج يناسبك</h2>\n<ul>\n<li><strong>المقررات الإلكترونية</strong> تناسبك إن كان وقتك أو ميزانيتك يتغيران من فصل إلى فصل. فلا تدفع إلا عن الساعات التي تسجلها، وتستطيع الانقطاع فصلًا دون أي طلب وتبقى طالبًا منتظمًا، وتحتفظ بكل ساعة نجحت فيها مهما طالت المدة. فبعض الطلاب يدرس سنتين ويتوقف عند دبلوم متى استوفى شروطه، وبعضهم يواصل إلى البكالوريوس.</li>\n<li><strong>بكالوريوس الشريعة</strong> يناسبك إن كنت تستطيع الالتزام بعبء كامل ثابت في كل فصل وتريد مقعدًا مجانيًا. وهو درجة نظامية بخطة محددة يلزمك اتباعها.</li>\n<li><strong>دبلوم القراءات</strong> للطلاب الذين يحفظون القرآن كاملًا.</li>\n</ul>\n<p>والدراسة مناسبة للمبتدئين. فالمقررات تبدأ من المستويات التمهيدية وتتدرج، وتجمع بين الفهم والحفظ. ولا يُشترط حفظ أي قدر من القرآن لبدء المقررات الإلكترونية أو البكالوريوس، فالحفظ يبدأ متدرجًا من سورة البقرة في المستويات الأولى.</p>\n\n<h2>تخصصات المقررات الإلكترونية</h2>\n<table><thead><tr><th>التخصص</th><th>محوره</th></tr></thead><tbody>\n<tr><td>الشريعة</td><td>الفقه وأصول الفقه</td></tr>\n<tr><td>القرآن الكريم</td><td>القراءات والتجويد والتفسير</td></tr>\n<tr><td>الحديث الشريف</td><td>الحديث بأسانيده ومتونه، والجرح والتعديل</td></tr>\n<tr><td>العقيدة والدعوة</td><td>التوحيد والعقيدة</td></tr>\n<tr><td>اللغة العربية</td><td>النحو والصرف والبلاغة</td></tr>\n<tr><td>الأنظمة</td><td>القانون، وفي مقدمته النظام السعودي</td></tr>\n<tr><td>الاقتصاد</td><td>الاقتصاد، والاقتصاد الإسلامي، والرياضيات</td></tr>\n</tbody></table>\n<p>وتشترك التخصصات في بعض المقررات العامة. وفي بكالوريوس الشريعة يقوم البرنامج على الفقه بأبوابه، وأصول الفقه، والقواعد الفقهية، والدراسات القضائية.</p>\n<h3>كيف تتخصص</h3>\n<p>مقررات التخصصات كلها مفتوحة لك عند التسجيل. وتخصصك يتحدد بما تجمعه من مقررات:</p>\n<ol>\n<li>اختر التخصص الذي تقصده، وابحث عن مقرراته في جدول المقررات في دليل الطالب الخاص ببرنامجك. وكلمة «نعم» تحت التخصص تعني أن المقرر مطلوب فيه.</li>\n<li>سجّل تلك المقررات فصلًا بعد فصل.</li>\n<li>إذا نجحت في كل مقررات التخصص ومتطلباته فاطلب المؤهل.</li>\n</ol>\n<blockquote><p>نصيحة: خطط الكليات في المدينة خريطة جيدة لترتيب مقرراتك، والفروق بينها وبين خطة الدراسة عن بُعد يسيرة. انظر <a href=\"/ar/guides/what-you-study-by-level\">ما تدرسه مستوى بعد مستوى</a>.</p></blockquote>\n\n<h2>التقديم</h2>\n<ul>\n<li>قدّم على موقع الجامعة الرسمي <a href=\"https://iu.edu.sa/\">iu.edu.sa</a>. ولا مقابلة للمقررات الإلكترونية.</li>\n<li>ارفع المستندات المطلوبة، كصورة جواز السفر وشهاداتك، وأكمل خطوات التسجيل في الموقع.</li>\n<li>تابع طلبك عبر البريد الإلكتروني. وراقب صندوق الوارد ومجلد الرسائل غير المرغوب فيها.</li>\n<li>بعد قبولك تصلك رسالة من IU Eservices بعنوان <strong>IU Single Sign-On</strong>، فيها رقمك الجامعي وكلمة مرور مؤقتة.</li>\n</ul>\n\n<h2>أول دخول لك</h2>\n<ol>\n<li>افتح <a href=\"https://iu.edu.sa/\">iu.edu.sa</a> واضغط أيقونة <strong>حساب المستخدم</strong> في الأعلى.</li>\n<li>اضغط <strong>الدخول بالرقم الجامعي / الوظيفي</strong>. والخيار الآخر نفاذ، لمن يملكه.</li>\n<li>اكتب رقمك الجامعي، وكلمة المرور المؤقتة، و<strong>رمز التحقق</strong> الظاهر بجانب الخانة، ثم اضغط <strong>دخول</strong>.</li>\n<li>غيّر كلمة المرور فورًا: اضغط أيقونة <strong>حساب المستخدم</strong>، ثم <strong>تغيير كلمة المرور</strong>. ويجب ألا تقل عن ٨ خانات، وفيها حرف كبير وحرف صغير ورقم ورمز مثل ! @ # $ أو %.</li>\n<li>تحقق من رقم جوالك تحت <strong>تغيير رقم الجوال</strong>. فإليه تصل رموزك وتنبيهات الجامعة.</li>\n</ol>\n<p>لوحتك الرئيسية، <strong>بياناتي الطلابية</strong>، تعرض الفصل الذي التحقت فيه، ومجموع غيابك، ومحاضرات اليوم. ولطلاب المقررات الإلكترونية تبقى خانات الفصل الحالي والمعدل الفصلي والمعدل التراكمي فارغة: فكل مقرر يُمنح شهادته وحده، فلا يُحسب هناك معدل. ولا تظهر محاضرات اليوم إلا إذا أدخل الأستاذ مواعيدها في النظام الأكاديمي، فتابع مقرراتك في بلاك بورد أيضًا.</p>\n\n<h2>المنصات التي ستستعملها</h2>\n<table><thead><tr><th>المنصة</th><th>ما تفعله فيها</th></tr></thead><tbody>\n<tr><td><strong>النظام الأكاديمي</strong></td><td>التسجيل والدفع، والاطلاع على مقرراتك المسجلة وغيابك ونتائجك وسجلك الأكاديمي وخطتك، وطباعة المستندات، والتواصل مع مرشدك الأكاديمي</td></tr>\n<tr><td><strong>بلاك بورد</strong> (إدارة التعلم الإلكتروني زدني)</td><td>المحاضرات المباشرة والمسجلة، وملفات المقررات، والواجبات، والاختبارات، ودرجاتك، والرسائل إلى أساتذتك</td></tr>\n<tr><td><strong>تواصل</strong> (نظام تواصل / إدارة الطلبات)</td><td>الطلبات والمشكلات، ومنها الانسحاب من مقرر</td></tr>\n<tr><td><strong>المكتبة الرقمية السعودية</strong></td><td>الكتب والمراجع. وهي لا تفتح في الغالب إلا من داخل السعودية، ولذلك يرسل الأساتذة الكتب والمذكرات التي تحتاجها</td></tr>\n</tbody></table>\n<p>وكلها تفتح من الدخول نفسه. وأيقونة <strong>زدني</strong> تفتح بلاك بورد دون دخول ثانٍ. وعلى الجوال أو الجهاز اللوحي افتح تطبيق Blackboard، واكتب Islamic University of Madinah، واضغط <strong>المتابعة باستخدام تسجيل الدخول عبر الويب</strong>، وسجّل الدخول بكتابة رقمك الجامعي في خانة اسم المستخدم.</p>\n\n<h2>تسجيل مقرراتك كل فصل</h2>\n<p>استعمل الحاسوب. فصفحة التسجيل لا تعمل جيدًا على الجوال، وتنتهي جلستها إذا تركتها مفتوحة مدة طويلة.</p>\n<ol>\n<li>افتح <strong>النظام الأكاديمي</strong>، ثم <strong>التسجيل الإلكتروني</strong>. واقرأ <strong>تعليمات و إرشادات</strong> في المرة الأولى.</li>\n<li>افتح <strong>المقررات المطروحة وفق الخطة</strong> لترى ما يمكنك تسجيله.</li>\n<li>افتح <strong>الحذف والإضافة</strong>. وضع علامة على المقرر، واضغط العدسة تحت <strong>ابحث عن شعبة</strong>، ثم اضغط رقم الشعبة في النافذة التي تفتح.</li>\n<li>انزل إلى الأسفل واضغط <strong>إضافة</strong>. فينتقل المقرر إلى <strong>إجراءات غير مثبتة</strong>.</li>\n<li>اضغط <strong>تثبيت</strong>. فلا يُسجَّل شيء قبل التثبيت.</li>\n<li>ادفع رسومك كما في القسم التالي.</li>\n<li>افتح <strong>المقررات المسجلة</strong> وتحقق من كل مقرر وساعاته وأستاذه.</li>\n</ol>\n<ul>\n<li>راجع اختياراتك قبل التثبيت، عدد المقررات وأيها. فحذف المقرر بعد ذلك ليس سهلًا دائمًا.</li>\n<li>وإن اضطررت إلى حذف مقرر بعد التثبيت ولم ينجح الحذف، فأرسل طلبًا عبر تواصل إلى مركز التعليم الإلكتروني تطلب فيه حذف المقرر (الخطوات أدناه).</li>\n</ul>\n\n<h2>الرسوم والدفع بالبطاقة</h2>\n<p>رسوم المقررات الإلكترونية قسمان: <strong>رسوم تسجيل قدرها ٢٣٠ ريالًا</strong> في بداية كل فصل، و<strong>٢٣٠ ريالًا عن كل ساعة معتمدة</strong> تضيفها.</p>\n<table><thead><tr><th>مثال لفصل</th><th>بالريال</th></tr></thead><tbody>\n<tr><td>رسوم التسجيل</td><td>٢٣٠</td></tr>\n<tr><td>ثلاثة مقررات بساعتين ومقرر بثلاث ساعات: ٩ ساعات × ٢٣٠</td><td>٢٬٠٧٠</td></tr>\n<tr><td><strong>المجموع</strong></td><td><strong>٢٬٣٠٠</strong></td></tr>\n</tbody></table>\n<ol>\n<li>في النظام الأكاديمي افتح <strong>شخصي</strong>، ثم <strong>الدفع الإلكتروني</strong>، ثم <strong>بطاقات</strong>.</li>\n<li>يظهر لك المبلغ المستحق. فاكتب المبلغ نفسه تمامًا تحت <strong>المبلغ المراد دفعه</strong> واضغط <strong>دفع</strong>.</li>\n<li>ادفع ببطاقة مدى أو فيزا أو ماستركارد. وبعد نجاح الدفع تُبلَّغ الإدارة المالية تلقائيًا ويُحدَّث المبلغ المستحق عليك. ولا حاجة إلى إرسال الإيصال إلى أحد، لكن احتفظ بنسخة منه.</li>\n</ol>\n<p><strong>قبل أن تدفع:</strong></p>\n<ul>\n<li>تأكد أن بطاقتك تعمل للشراء خارج بلدك وأنها غير موقوفة.</li>\n<li>اجعل في البطاقة أكثر من المبلغ المستحق، فبنكك يضيف رسوم تحويل العملة.</li>\n<li>وإن كانت بطاقتك لا تدفع خارج بلدك فاطلب من قريب أو أحد معارفك ممن يقيم خارج بلدك أن يدفع عنك.</li>\n<li>ولا تطلب أبدًا من زميل في الدراسة أن يدفع عنك، لا في مجموعة ولا على الخاص. فذلك غير مسموح به.</li>\n<li>وإن فشل الدفع وخُصم المبلغ من حسابك فتواصل مع البنك الذي أصدر بطاقتك.</li>\n</ul>\n\n<h2>كيف يُدرَّس المقرر</h2>\n<p>لكل مقرر عدد محدد من الساعات الأسبوعية يختلف من مقرر إلى آخر. وتنقسم قسمين:</p>\n<ul>\n<li><strong>المحاضرة التزامنية</strong>: لقاء مباشر مع أستاذك في بلاك بورد، مدته نحو ساعة.</li>\n<li><strong>المحاضرة غير التزامنية</strong>: محاضرات مسجلة وأنشطة تعلم محددة تغطي جزءًا من المقرر.</li>\n</ul>\n<p><strong>مثال:</strong> مقرر فقه العبادات ١ في تخصص الشريعة له ٤ ساعات أسبوعية: ساعة تزامنية واحدة و٣ ساعات غير تزامنية. والساعات المعتمدة للمقرر تحدد وزنه في المعدل الفصلي والتراكمي.</p>\n<p>ويدرّس الأساتذة في الغالب من ملخصاتهم ومذكراتهم، مع مواد إثرائية في بلاك بورد. وكل الأساتذة في برامج الدراسة عن بُعد رجال. والجامعة تدرّس طلابًا في بلدان كثيرة، فيراعي الأساتذة فروق التوقيت في تحديد مواعيد المحاضرات.</p>\n<h3>حضور محاضرة مباشرة</h3>\n<ol>\n<li>في بلاك بورد افتح <strong>المقررات الدراسية</strong> واضغط المقرر.</li>\n<li>تحت <strong>التفاصيل والإجراءات</strong> اضغط <strong>Class Collaborate</strong>، ثم <strong>الانضمام إلى الجلسة</strong>، واضغط الدرس.</li>\n<li>ولتحتفظ بالملف الذي يعرضه أستاذك، اضغط أيقونة التنزيل أعلى الملف المعروض أثناء الجلسة.</li>\n</ol>\n<p>ولا يلزمك فتح الكاميرا في المحاضرات.</p>\n<h3>مشاهدة محاضرة مسجلة</h3>\n<ol>\n<li>اضغط النقاط الثلاث بجانب <strong>Class Collaborate</strong>، ثم <strong>عرض جميع التسجيلات</strong>.</li>\n<li>اضغط تسجيل الدرس، ثم <strong>المشاهدة الآن</strong>.</li>\n</ol>\n<p>وتبقى التسجيلات متاحة إلى ما بعد الاختبارات النهائية.</p>\n\n<h2>الحضور</h2>\n<ul>\n<li>تُبث المحاضرات مباشرة. فإن شاهدت التسجيل <strong>خلال ٢٤ ساعة</strong> لم يُسجَّل عليك غياب.</li>\n<li>وبعض المحاضرات يجب حضورها مباشرة، وفي مقدمتها حلقات القرآن، وبعض الأساتذة يوجبون الحضور المباشر على كل الطلاب. ويخبرك أستاذك بذلك في بداية المقرر.</li>\n<li>ويُسجَّل الحضور إلكترونيًا عند حضورك المحاضرة أو تخلفك عنها. وبعض الأساتذة يسجلونه يدويًا، فاعرف طريقة كل أستاذ، ولا سيما في مقررات القرآن.</li>\n<li>والغياب المعتبر هو المسجل في النظام الأكاديمي: <strong>شخصي</strong> ثم <strong>الغياب</strong> يعرض غيابك وتأخرك ونسبة غيابك في كل مقرر، والمجموع في لوحتك الرئيسية. أما الحضور الظاهر في بلاك بورد فللمتابعة فقط، والإنذارات تصدر من سجل النظام الأكاديمي.</li>\n</ul>\n\n<h2>درجاتك: ٦٠ لأعمال الفصل و٤٠ للنهائي</h2>\n<p>كل مقرر من ١٠٠: <strong>٦٠ درجة لأعمال الفصل</strong> و<strong>٤٠ درجة للاختبار النهائي</strong>. ويوزع كل أستاذ الستين بطريقته، من بين هذه:</p>\n<ul>\n<li>اختبار فصلي أو اختباران</li>\n<li>أسئلة يضعها في بلاك بورد لتجيب عنها</li>\n<li>بحث في موضوع محدد</li>\n<li>تلخيص كتاب محدد</li>\n<li>المشاركة في نقاش يفتحه الأستاذ في بلاك بورد</li>\n<li>درجات للمشاركة في المحاضرات</li>\n<li>في مقررات القرآن، تسجيلات لحفظك ترفعها في واجب على بلاك بورد</li>\n<li>واجبات ومهام أخرى</li>\n</ul>\n<ul>\n<li>الاختبارات الفصلية تُؤدّى دون الرجوع إلى الكتب والمذكرات ما لم يسمح أستاذك بالمذكرات، وبعضها يُراقَب كالاختبار النهائي.</li>\n<li>لكل مهمة تاريخ بداية وتاريخ تسليم. فسلّمها قبل الموعد، وإلا فاتتك درجاتها.</li>\n<li>الدروس الإثرائية دروس للتعلم الذاتي لا درجات عليها، لكنك مطالب بإكمالها.</li>\n</ul>\n<blockquote><p>نصيحة: في بلاك بورد افتح <strong>التقويم</strong>، ثم <strong>تواريخ الاستحقاق</strong> كل أسبوع، وفعّل الإشعارات من إعداداتك: على الحاسوب تحت اسمك، وعلى الجوال تحت <strong>المزيد</strong> ثم <strong>الإعدادات</strong>. وتستطيع إضافة أوقات مذاكرتك إلى التقويم بزر +.</p></blockquote>\n\n<h2>الاختبارات</h2>\n<ul>\n<li>تُؤدّى الاختبارات عبر الإنترنت، على الحاسوب، والكاميرا مفتوحة طوال الاختبار.</li>\n<li>وأكثر الأسئلة صواب وخطأ واختيار من متعدد. والمحاضرات والاختبارات الفصلية والنهائية تسير بالطريقة نفسها في المقررات الإلكترونية وبكالوريوس الشريعة، لكن كل أستاذ يضع أسئلته بنفسه.</li>\n<li>وقبل كل اختبار تحقق من الكاميرا واتصال الإنترنت والشاحن، واجلس في مكان هادئ لا يقطعك فيه أحد.</li>\n<li>تخلفت عن اختبار نهائي لعذر حقيقي؟ بعد الاختبارات النهائية افتح <strong>أكاديمي</strong>، ثم <strong>تقديم الأعذار عن غياب الاختبار النهائي</strong>، ثم <strong>طلب اعتذار عن الاختبارات النهائية</strong>، لتطلب اختبارًا بديلًا. وتابعه تحت <strong>اظهار و متابعة طلبات الاعتذار</strong>.</li>\n<li>ولا يوجد فصل صيفي لطلاب الدراسة عن بُعد.</li>\n</ul>\n\n<h2>النتائج والشهادات</h2>\n<ol>\n<li><strong>قيّم كل مقرر أولًا.</strong> فنتائجك، ومنها درجات أعمال الفصل، تبقى مخفية حتى تفعل. افتح <strong>أكاديمي</strong>، ثم <strong>تقييم المقررات</strong>، واضغط رمز كل مقرر وأجب عن كل العبارات. ويُفتح التقييم قبيل الاختبارات ولمدة قصيرة في بدايتها، ثم يُغلق، فبادر إليه فور فتحه.</li>\n<li>افتح <strong>التسجيل الإلكتروني</strong>، ثم <strong>نتائج المقررات</strong>، واختر الفصل. ويظهر لكل مقرر درجة الاختبار النهائي، ودرجة أعمال الفصل، والمجموع، والتقدير. واضغط <strong>طباعة</strong> لتحتفظ بنسخة.</li>\n<li><strong>السجل الأكاديمي</strong>، تحت أكاديمي، يعرض ساعاتك المسجلة والمجتازة وتقديرك في كل مقرر. وهو لاطلاعك أنت.</li>\n<li>ما اجتزته وما بقي عليك: <strong>أكاديمي</strong>، ثم <strong>المقررات المجتازة في الخطة</strong> أو <strong>المقررات المتبقية في الخطة</strong> أو <strong>خطة الطالب</strong>.</li>\n<li>والأوراق الرسمية تحت <strong>شخصي</strong>، ثم <strong>المستندات الرسمية</strong>: <strong>كشف حساب الطالب</strong> و<strong>شهادة إتمام مقرر جامعي إلكتروني</strong>. وهي تفتح في نافذة منبثقة، فاسمح بالنوافذ المنبثقة لموقع eservices.iu.edu.sa في متصفحك.</li>\n</ol>\n<p>واعتراف بلدك بالشهادة يرجع إلى أنظمته، فاسأل وزارة التعليم فيه قبل أن تعتمد عليها في وظيفة أو دراسة لاحقة. وهي نافعة في المراكز الإسلامية وفي العمل الدعوي.</p>\n\n<h2>الطلبات والتواصل</h2>\n<h3>تواصل</h3>\n<ol>\n<li>من صفحة الدخول افتح <strong>نظام تواصل / إدارة الطلبات</strong>.</li>\n<li>اضغط <strong>طلب جديد</strong>.</li>\n<li>اختر <strong>التواصل مع مركز التعليم الإلكتروني (بلاك بورد)</strong> لكل ما يتعلق بمقرراتك أو التسجيل أو بلاك بورد، أو <strong>تواصل تقني</strong> للأعطال التقنية.</li>\n<li>اكتب للطلب عنوانًا واضحًا تحت <strong>الموضوع</strong>، واشرحه تحت <strong>تفاصيل الطلب</strong>، وأرفق لقطة شاشة إن كانت تفيد.</li>\n<li>اضغط <strong>إرسال الطلب</strong>، وتابع الرد تحت <strong>طلباتي</strong>.</li>\n</ol>\n<h3>ترك مقرر أو فصل</h3>\n<ul>\n<li><strong>المقررات الإلكترونية:</strong> للانسحاب من مقرر أرسل طلبًا عبر تواصل إلى مركز التعليم الإلكتروني. فشاشة الانسحاب من مقرر في النظام الأكاديمي لا تعمل لهذه المقررات. ولا تأجيل فيها ولا اعتذار، ولا حاجة إليهما: فالفصل الذي لا تسجل فيه مقررات يُبقيك طالبًا منتظمًا.</li>\n<li><strong>بكالوريوس الشريعة:</strong> لطلب التأجيل، أي تأجيل فصل، أو الاعتذار، أي ترك فصل، افتح <strong>أكاديمي</strong>، ثم <strong>إدخال حركات أكاديمية</strong>، ثم <strong>إدخال حركة أكاديمية جديدة</strong>، واقرأ الشروط واضغط <strong>أوافق</strong>. وهذه الشاشة لا تُفتح إلا في الفترات التي تحددها الجامعة. ولك <strong>ثلاث فرص فقط</strong> طوال البرنامج كله. ولا تنقطع عن الدراسة دون إجراء أبدًا، فالانقطاع يؤدي إلى طي القيد. والطلبات السابقة تحت <strong>حركات أكاديمية سابقة</strong>.</li>\n</ul>\n<h3>أساتذتك ومرشدك الأكاديمي</h3>\n<ul>\n<li>الطريقان الرسميان للتواصل مع الأستاذ هما بريدك الجامعي ورسائل بلاك بورد. ففي بلاك بورد افتح المقرر واضغط أيقونة الظرف بجانب اسم الأستاذ. وفي النظام الأكاديمي افتح <strong>شخصي</strong>، ثم <strong>إرسال بريد إلكتروني</strong>، وضع علامة على الأستاذ، واكتب الموضوع والرسالة، واضغط <strong>إرسال</strong>.</li>\n<li>مرشدك الأكاديمي: <strong>أكاديمي</strong>، ثم <strong>التواصل مع المرشد الأكاديمي</strong>، ثم <strong>طلب تواصل جديد</strong>. اكتب رسالتك، وأرفق ملفًا عند الحاجة، واضغط <strong>إرسال</strong>.</li>\n</ul>\n<p>وتصحيح الاسم أو الجنسية أو تاريخ الميلاد، وسائر الشاشات، في <a href=\"/ar/guides/university-student-system\">استعمال النظام الطلابي في الجامعة</a>.</p>\n\n<h2>المشكلات الشائعة</h2>\n<table><thead><tr><th>المشكلة</th><th>ما تفعله</th></tr></thead><tbody>\n<tr><td>لا أستطيع الدخول مطلقًا</td><td>راسل <strong>it.care@iu.edu.sa</strong> لطلب كلمة مرور، أو استعمل نموذج الزائر على <a href=\"https://helpdesk.iu.edu.sa/newticket_guest\">helpdesk.iu.edu.sa/newticket_guest</a></td></tr>\n<tr><td>نسيت كلمة مرور بلاك بورد</td><td>في صفحة تسجيل الدخول عبر الويب اضغط <strong>هل نسيت كلمة المرور؟</strong>، واكتب اسمك الأول واسم عائلتك كما سُجّلا تمامًا، مع رقمك الجامعي أو بريدك، فتصلك رسالة لإعادة التعيين. انظر <a href=\"/ar/ask/blackboard-login\">كيف أدخل إلى بلاك بورد؟</a></td></tr>\n<tr><td>تظهر شرطة مكان معدلي والفصل الحالي</td><td>هذا طبيعي في المقررات الإلكترونية. وتقديراتك تحت نتائج المقررات</td></tr>\n<tr><td>لا أرى نتائجي</td><td>أكمل تقييم كل المقررات أولًا</td></tr>\n<tr><td>فاتتني محاضرة مباشرة</td><td>شاهد التسجيل خلال ٢٤ ساعة. وفي حلقات القرآن ومع الأساتذة الذين يوجبون الحضور المباشر يبقى الغياب مسجلًا</td></tr>\n<tr><td>لا يُحذف المقرر بعد تثبيته</td><td>أرسل طلبًا عبر تواصل إلى مركز التعليم الإلكتروني مع رمز المقرر</td></tr>\n<tr><td>رُفضت بطاقتي</td><td>تأكد أنها تسمح بالدفع خارج بلدك، وأنها غير موقوفة، وفيها أكثر من المبلغ المستحق، ثم راجع بنكك</td></tr>\n<tr><td>فشل الدفع لكن المبلغ خُصم</td><td>تواصل مع البنك الذي أصدر بطاقتك، ومعك الإيصال أو لقطة شاشة</td></tr>\n<tr><td>محاضرات اليوم لا تعرض شيئًا</td><td>لم يُدخل أستاذك المواعيد في النظام الأكاديمي. فراجع المقرر في بلاك بورد</td></tr>\n<tr><td>المكتبة الرقمية السعودية لا تفتح</td><td>هي لا تفتح في الغالب إلا من داخل السعودية. فاطلب المادة من أستاذك في بلاك بورد</td></tr>\n<tr><td>المستندات الرسمية لا تفتح</td><td>اسمح بالنوافذ المنبثقة لموقع eservices.iu.edu.sa في متصفحك</td></tr>\n</tbody></table>\n<p>ولا تفتح أبدًا روابط تُنشر في محادثات الشعب: انظر <a href=\"/ar/ask/blackboard-phishing\">أحدهم نشر رابطًا في محادثة شعبتي في بلاك بورد</a>.</p>\n\n<h2>بمن تتواصل</h2>\n<table><thead><tr><th>الموضوع</th><th>جهة التواصل</th></tr></thead><tbody>\n<tr><td>مقرراتك والتسجيل وبلاك بورد</td><td>طلب عبر تواصل إلى مركز التعليم الإلكتروني، أو <strong>elc@iu.edu.sa</strong></td></tr>\n<tr><td>بلاك بورد</td><td><strong>bb@iu.edu.sa</strong></td></tr>\n<tr><td>الدعم التقني</td><td><strong>it.support@iu.edu.sa</strong></td></tr>\n<tr><td>كلمات المرور وحسابك الجامعي</td><td><strong>it.care@iu.edu.sa</strong>، أو عمادة تقنية المعلومات والتعليم الإلكتروني على الرقم <strong>‎+966 14 847 1856‎</strong></td></tr>\n<tr><td>القبول والتسجيل</td><td><strong>admission.reg@iu.edu.sa</strong> أو <strong>admiss.deanship@iu.edu.sa</strong></td></tr>\n<tr><td>ليس لديك حساب بعد، أو أُغلق حسابك</td><td>نموذج الزائر على <a href=\"https://helpdesk.iu.edu.sa/\">helpdesk.iu.edu.sa</a></td></tr>\n</tbody></table>\n<blockquote><p>نصيحة: تعثرت في أي خطوة؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "tajeel-and-itithaar": {
  "titleAr": "أخذ فصل إجازة: التأجيل والاعتذار",
  "summaryAr": "كيف تؤجل فصلًا (التأجيل) أو تعتذر عن فصل (الاعتذار)، والحدود، وأثر كل منهما على مكافأتك وغرفتك وتأشيرتك ومدة دراستك، وتسليم غرفتك وأنت في الخارج، وقاعدة الستين يومًا، وفترات ١٤٤٨، والعودة بعد طي القيد، وكيف تقدّم.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. التأجيل والاعتذار كلاهما يخرجك من فصل دراسي، لكنهما يختلفان في طريقة عملهما ويشتركان في حد واحد. اقرأ هذا قبل أن تقدّم، وكلّم كليتك أو المعهد أولًا.</p>\n<h2>التأجيل والاعتذار باختصار</h2>\n<table><thead><tr><th>الموضوع</th><th>التأجيل</th><th>الاعتذار</th></tr></thead><tbody>\n<tr><td>ما هو</td><td>تأجيل فصل قبل أن يبدأ</td><td>اعتذار عن فصل بدأته فعلًا</td></tr>\n<tr><td>متى</td><td>فترة التأجيل قبيل بداية الفصل</td><td>بعد فترة التأجيل، أثناء الفصل</td></tr>\n<tr><td>الموافقة</td><td>لا بد من موافقة كليتك</td><td>لا بد من موافقة كليتك</td></tr>\n<tr><td>مقرراتك</td><td>لا تُسجَّل في ذلك الفصل</td><td>تُسحب من كل مقررات ذلك الفصل بتقدير W، وهو ليس رسوبًا</td></tr>\n<tr><td>المدة القصوى للدراسة</td><td>لا يُحتسب، فيتأخر موعدك النهائي</td><td>يُحتسب، فيبقى موعدك النهائي كما هو</td></tr>\n<tr><td>المكافأة</td><td>تتوقف</td><td>تتوقف</td></tr>\n<tr><td>الغرفة في السكن</td><td>سلّمها أولًا، فالطلب لا يُعتمد حتى تسلّمها</td><td>سلّمها واخرج من السكن بمجرد تغير حالتك</td></tr>\n<tr><td>التأشيرة (إقامة، فصل واحد)</td><td>خروج وعودة: تغادر المملكة وتعود قبل بداية الفصل التالي بأسبوع</td><td>خروج وعودة: تغادر المملكة وتعود قبل بداية الفصل التالي بأسبوع</td></tr>\n</tbody></table>\n<h2>الحدود</h2>\n<ul>\n<li>لا يتجاوز مجموع التأجيل والاعتذار <strong>ثلاثة فصول</strong> في برنامجك كله.</li>\n<li>في <strong>سنتك الأولى</strong> لا يُسمح بأي منهما إلا لأسباب قاهرة. ولا يجوز لك في السنة الأولى أيضًا الانسحاب من مقررات بعينها ولا التحويل إلى كلية أخرى.</li>\n<li>ولأن الاعتذار يُحتسب من مدتك القصوى للدراسة، فعليك أن تستوعب المقررات الفائتة في فصول لاحقة. فإن نفد وقتك عرّضت نفسك لعدم الحصول على درجتك.</li>\n<li>للانسحاب من مقرر واحد بدل الفصل كله، انظر <a href=\"/ar/guides/exams-results-and-attendance\">الاختبارات والنتائج والحضور</a>.</li>\n</ul>\n<h2>فترات ١٤٤٨</h2>\n<table><thead><tr><th>الفصل الثاني ١٤٤٨</th><th>المواعيد</th></tr></thead><tbody>\n<tr><td>التأجيل</td><td>من ١٣ إلى ١٩ ديسمبر ٢٠٢٦</td></tr>\n<tr><td>الاعتذار عن الفصل والانسحاب من مقرر</td><td>من ٢٠ ديسمبر ٢٠٢٦ إلى ١٣ مارس ٢٠٢٧</td></tr>\n<tr><td>طلبات إعادة القيد للفصل التالي، بعد طي القيد أو فصل إجازة</td><td>من ٢٤ يناير إلى ١١ أبريل ٢٠٢٧</td></tr>\n</tbody></table>\n<p>فترات كل فصل في <a href=\"/ar/guides/university-calendar-1448\">التقويم الجامعي</a>، والنظام الأكاديمي هو المرجع المحدَّث إن مُددت فترة. وخارج الفترة تظهر على الشاشة عبارة «لا يمكن إدخال اي حركة في هذه الفترة». وإن فاتتك فترة التأجيل لم يبقَ إلا الاعتذار.</p>\n<h2>كيف تقدّم في النظام الأكاديمي</h2>\n<p>الخطوات واحدة في الحالتين. واستخدم الحاسوب إن استطعت.</p>\n<ol>\n<li>ادخل إلى نظام الجامعة وافتح <strong>النظام الأكاديمي</strong>.</li>\n<li>تحت <strong>أكاديمي</strong> اختر <strong>ادخال حركات اكاديمية</strong>، ثم <strong>ادخال حركات أكاديمية جديدة</strong>.</li>\n<li>اقرأ الشروط المعروضة على الشاشة، ومنها أحكام التأشيرة والسكن المذكورة أدناه، واضغط <strong>أوافق</strong>.</li>\n<li>اجعل <strong>نوع الحركة</strong> <strong>تأجيل</strong> للتأجيل، أو <strong>الاعتذار</strong> للاعتذار، وهو يظهر بعد إغلاق فترة التأجيل. ولا تختر <strong>إنسحاب</strong>، فهو يسحبك من الجامعة.</li>\n<li>اختر الفصول. لفصل واحد اجعل <strong>من بداية الفصل</strong> و<strong>إلى نهاية الفصل</strong> الفصل نفسه. ولفصلين اجعل <strong>إلى نهاية الفصل</strong> الفصل الثاني.</li>\n<li>اختر <strong>السبب</strong> المناسب. وأضف ملاحظاتك تحت <strong>ملاحظات</strong> وملفات PDF داعمة تحت <strong>مرفقات</strong>، كتقرير طبي. ثم اضغط <strong>التالي</strong>.</li>\n<li>راجع الملخص واضغط <strong>حفظ</strong>، ثم <strong>انهاء</strong>.</li>\n<li>إن كنت تسكن في السكن الجامعي فسلّم غرفتك الآن (انظر أدناه). وراجع وكيل كليتك أو المعهد، الذي يتولى شؤون الطلاب، فلعل هناك نماذج أخرى ينبغي إكمالها.</li>\n</ol>\n<p><strong>متابعة طلبك:</strong> كرر الخطوتين ١ و٢، لكن اختر <strong>إظهار الحركات الأكاديمية</strong>. وبعد الموافقة تتغير حالتك (<strong>الوضع العام</strong>) من <strong>منتظم</strong> إلى <strong>مؤجل</strong>. وتبقى الطلبات السابقة تحت <strong>حركات أكاديمية سابقة</strong>. وإن بقي الطلب أيامًا بلا رد فتابعه مع وكيل كليتك. وبقية شاشات النظام الأكاديمي مشروحة في <a href=\"/ar/guides/university-student-system\">استخدام نظام الطالب في الجامعة</a>.</p>\n<h2>ماذا يحدث بعد التقديم</h2>\n<ul>\n<li>لا يسري طلبك إلا إذا تغيرت حالتك. وإلى ذلك الحين تبقى طالبًا منتظمًا، <strong>فواظب على حضور محاضراتك</strong>، لأن الغياب في هذه المدة يُحتسب عليك.</li>\n<li>بمجرد تغير حالتك، أخلِ غرفتك في السكن الجامعي فورًا.</li>\n<li>تتوقف مكافأتك في الفصل الذي تغيب فيه.</li>\n</ul>\n<h2>غرفتك في السكن</h2>\n<p>لا يُعتمد طلب التأجيل حتى يُظهر مكتب الإسكان أنه لا غرفة باسمك. وبعد الاعتذار تسلّم الغرفة بمجرد تغير حالتك. والأغراض المتروكة في السكن بعد الموعد الذي تحدده العمادة تُزال على مسؤوليتك.</p>\n<ol>\n<li>أفرغ الغرفة. وكل ما وفرته الجامعة يبقى فيها: المرتبة والسرير والخزانة والمكتب والكرسي.</li>\n<li>خذ نموذج التسليم من مكتب الإسكان في الوحدة ٢٢، أو من عمادة شؤون الطلاب.</li>\n<li>يتأكد مشرف مبناك من أن الغرفة فارغة، ويستلم المفتاح ويوقّع النموذج.</li>\n<li>أعد النموذج الموقّع إلى مكتب الإسكان، فيسجل الغرفة مسلَّمة.</li>\n</ol>\n<h3>إن كنت في الخارج بالفعل</h3>\n<p>وكّل زميلًا لك يسلّم الغرفة عنك.</p>\n<ol>\n<li>في تواصل على <a href=\"https://helpdesk.iu.edu.sa/\">helpdesk.iu.edu.sa</a>، اضغط <strong>طلب جديد</strong> واختر <strong>إدارة الإسكان</strong>. واكتب عنوانًا مثل «تفويض بتسليم غرفتي».</li>\n<li>اكتب: «أنا الطالب [اسمك الكامل]، الرقم الجامعي [رقمك]، أفوّض الطالب [اسمه الكامل]، الرقم الجامعي [رقمه]، بتسليم غرفتي: الوحدة [..]، الدور [..]، الغرفة [..]، السرير [..]». ثم أرسله.</li>\n<li>يطبع زميلك الطلب ويأخذه إلى مكتب الإسكان في الوحدة ٢٢، ويستلم نموذج التسليم.</li>\n<li>يفرغ الغرفة، ويتحقق منها المشرف ويوقّع، ثم يعيد النموذج إلى مكتب الإسكان.</li>\n<li>بمجرد أن يُظهر النظام أنه لا غرفة باسمك، يمكن اعتماد تأجيلك.</li>\n</ol>\n<h2>السفر وتأشيرتك</h2>\n<p>هذه الأحكام للطلاب الدوليين على المنحة الكاملة. وهي معروضة على شاشة التقديم، وتوافق عليها عند تقديم الطلب.</p>\n<h3>إن كنت تحمل إقامة</h3>\n<table><thead><tr><th>طلبك</th><th>التأشيرة التي تُمنح لك</th><th>ما يجب عليك</th></tr></thead><tbody>\n<tr><td>تأجيل أو اعتذار لفصل واحد</td><td>تأشيرة خروج وعودة</td><td>أخلِ السكن وغادر المملكة بمجرد تغير حالتك، وعد قبل بداية الفصل التالي بأسبوع</td></tr>\n<tr><td>تأجيل أو اعتذار لأكثر من فصل، أو انسحاب من الجامعة</td><td>تأشيرة خروج نهائي</td><td>أكمل إخلاء طرفك وغادر المملكة خلال أسبوعين من تغير حالتك</td></tr>\n<tr><td>العودة إلى الدراسة بعد خروج نهائي (إعادة الانتظام)</td><td>تأشيرة دراسة جديدة</td><td>تقدّم لها حين تعلن عمادة القبول والتسجيل، ولا يمكنك العودة إلى الدراسة بأي نوع آخر من التأشيرات</td></tr>\n</tbody></table>\n<p><strong>قاعدة الستين يومًا.</strong> إذا انتهت تأشيرة خروجك وعودتك وأنت في الخارج بتأجيل أو اعتذار، فأرسل طلبًا عبر تواصل إلى إدارة السفر لتمديدها، خلال ٦٠ يومًا من يوم انتهائها. واطلب من أحد في المدينة أن يدفع الرسوم ويكمل الإجراءات عنك. وأنجز ذلك في اليوم التاسع والخمسين على أقصى تقدير. فبعد ٦٠ يومًا تصبح حالتك «خرج ولم يعد»: فلا يمكن تمديد التأشيرة بعد ذلك، وتتقدم لتأشيرة دراسة جديدة كما يفعل الطلاب الجدد.</p>\n<h3>إن كنت تحمل هوية زائر</h3>\n<p>قبل أن تغادر، اسأل الجامعة عبر تواصل عن أثر حالتك على تأشيرتك، وتحقق من تاريخ انتهائها في أبشر. انظر <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a>.</p>\n<h3>الحصول على تأشيرة جديدة للعودة</h3>\n<p>طلاب التأجيل والاعتذار العائدون الذين صارت حالتهم «خرج ولم يعد»، والطلاب الذين طُوي قيدهم، يطلبون تأشيرة دراسة جديدة من <a href=\"https://minhatee2.iu.edu.sa/Home/VisaLanding\">صفحة التأشيرات في منحتي</a>، بالدخول برقمهم الجامعي. وتعلن عمادة القبول والتسجيل موعد فتحها كل فصل، والخطاب المطلوب للتقديم موجود في موقع الجامعة. ومن هناك تسير الإجراءات كما تسير للطلاب الجدد، عبر السفارة السعودية في بلدك.</p>\n<p>الطيران في فصل الإجازة على حسابك، فتذكرة الجامعة هي التذكرة السنوية إلى بلدك.</p>\n<h2>العودة بعد طي القيد</h2>\n<p>الغياب ٢٠ يومًا متصلة دون تأجيل أو اعتذار يؤدي إلى طي قيدك («مطوي القيد»). ولا يُعاد فتح القيد المطوي إلا مرة واحدة، خلال أربعة فصول.</p>\n<ol>\n<li>خلال فترة إعادة القيد، افتح النظام الأكاديمي، ثم <strong>أكاديمي</strong>، ثم <strong>ادخال حركات اكاديمية</strong>، ثم <strong>ادخال حركة أكاديمية جديدة</strong>، واضغط <strong>أوافق</strong>.</li>\n<li>اجعل <strong>نوع الحركة</strong> <strong>اعادة قيد</strong>، واختر السبب المناسب، وأرفق عذرك، ثم اضغط <strong>التالي</strong> وأرسل.</li>\n<li>إن كنت خارج المملكة، فاطلب تأشيرتك الجديدة من منحتي كما سبق بعد قبولك.</li>\n</ol>\n<h2>أسئلة</h2>\n<p><strong>هل أستطيع التقديم من الخارج؟</strong> نعم، فالطلب إلكتروني. ووكّل زميلًا يسلّم غرفتك كما سبق، وانتبه لقاعدة الستين يومًا إن انتهت تأشيرتك.</p>\n<p><strong>هل أستطيع إلغاء الطلب؟</strong> راجع كليتك أو المعهد فورًا، فهم الذين يعيدونك إلى شعبك الدراسية عند الحاجة.</p>\n<blockquote><p>نصيحة: لست متأكدًا أيهما يناسب حالتك؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "umrah-rawdah-quba": {
  "titleAr": "العمرة والروضة وقباء من المدينة",
  "summaryAr": "كيف تحجز الروضة، وتزور قباء كل سبت، وتصل إلى مكة للعمرة.",
  "bodyHtmlAr": "<h2>مسجد قباء كل سبت</h2>\n<p>صلاة ركعتين في مسجد قباء بعد التطهر في البيت لها أجر عمرة، وكان النبي ﷺ يزوره يوم السبت. وهو على بُعد ٣ إلى ٤ كيلومترات من الحرم على ممشى قباء، نحو ٤٥ دقيقة سيرًا، وفيه عربات كهربائية بنحو ١٠ إلى ٢٠ ريالًا (اتفق على السعر أولًا). ولا تحتاج حجزًا للصلاة في قباء.</p>\n<h2>الروضة الشريفة</h2>\n<ol>\n<li>ثبّت تطبيق <strong>نسك</strong> وسجّل الدخول.</li>\n<li>احجز موعدًا للروضة. التصريح مجاني ويصدر في الحال. والمقيمون يدخلون بنفاذ. وتُفتح المواعيد مسبقًا وتنفد بسرعة، ويعرض التطبيق كم تصريحًا تستطيع حجزه. وللرجال والنساء أوقات منفصلة.</li>\n<li>إن لم يكن موعد متاحًا فانضم إلى قائمة الانتظار في التطبيق، أو أبقِ التطبيق مفتوحًا مع تشغيل الموقع وأنت في المسجد، لأن مواعيد اليوم نفسه تُطرح لمن هم قريبون.</li>\n<li>قبل موعدك بيوم يرسل نسك تذكيرًا يطلب منك التأكيد أو الإلغاء. فأكّد الحجز، أو ألغِه ليذهب المكان إلى غيرك.</li>\n<li>احضر في الوقت المكتوب في حجزك واتبع المنظمين. ورمز الباركود في التصريح لا يفتح البوابات الآلية إلا في وقت موعدك، ولذوي الاحتياجات الخاصة مسار خاص بهم.</li>\n<li>صلِّ ركعتين وادعُ بهدوء، ثم أفسح المكان لغيرك.</li>\n</ol>\n<ul>\n<li><strong>احجز قبل وصولك.</strong> ينشئ الزائر حسابه في نسك برقمَي الجواز والتأشيرة فور صدور التأشيرة، ويحجز من بلده، لأن المواعيد في المواسم المزدحمة تنفد قبل أن يصل الناس.</li>\n<li><strong>متى تُطرح المواعيد.</strong> تُطرح مواعيد الأسبوع التالي في الغالب بعد ظهر الجمعة بتوقيت السعودية، وتُفتح دفعات صغيرة كل ٣٠ دقيقة تقريبًا على مدار اليوم. فافتح التطبيق مرات في اليوم، ولا سيما بعد ظهر الجمعة.</li>\n<li><strong>احجز في الفئة الصحيحة.</strong> التصريح المحجوز في فئة الرجال لا يفتح بوابة النساء، وأوقات النساء مختلفة. ويدخل الرجال في العادة من آخر الليل إلى الصباح الباكر، وكثيرًا ما يكون دخولهم من الباب رقم ٣٧ (باب السلام). وللنساء فترتان، الصباح الباكر وآخر المساء، وكثيرًا ما يكون دخولهن من الباب رقم ٢٥ (باب عثمان بن عفان). والعبرة بالباب والوقت المكتوبين في تصريحك.</li>\n<li><strong>الأطفال.</strong> لا يُسمح بدخول الرضّع والأطفال الصغار جدًا. ومن سن الخامسة يحتاج الطفل إلى تصريح خاص به، يُحجز كتصريح البالغ.</li>\n<li><strong>احضر قبل موعدك بـ٣٠ دقيقة</strong> وتجنّب التصوير في الداخل، فخلفك كثيرون ينتظرون.</li>\n<li><strong>لا تستعمل إلا تطبيق نسك الرسمي</strong> الذي تصدره وزارة الحج والعمرة. ولا يستطيع أحد أن يبيعك تصريحًا للروضة أو دخولًا مضمونًا، فالتصريح مجاني وباسمك أنت، وكل عرض لدخول مدفوع احتيال.</li>\n</ul>\n<h2>البقيع</h2>\n<p>جنة البقيع، حيث دُفن كثير من الصحابة وأهل بيت النبي ﷺ، في الجهة الشرقية من الحرم. وهو مفتوح للرجال. ويمكن حجز الزيارة ومعرفة مستوى الازدحام على بوابة البقيع التابعة لأمانة المدينة على <a href=\"https://ekram.amana-md.gov.sa/\">ekram.amana-md.gov.sa</a>.</p>\n<h2>العمرة من المدينة</h2>\n<ol>\n<li><strong>احجز تصريح العمرة في نسك</strong> قبل السفر. وهو مجاني. حاملو الإقامة يدخلون بنفاذ، والزائرون يسجلون ببيانات جوازهم وتأشيرتهم. ولا تستطيع حمل أكثر من تصريح واحد فعّال في وقت واحد، ولا يُغيَّر وقته، فألغِه في التطبيق واحجز من جديد إن تغيرت خطتك.</li>\n<li><strong>أحرم من الميقات.</strong> وهو لمن يخرج من المدينة ذو الحليفة (أبيار علي)، على بُعد نحو ١٤ كيلومترًا من المسجد النبوي على طريق مكة. والحافلات والسيارات تقف فيه.</li>\n<li><strong>سافر إلى مكة،</strong> على بُعد نحو ٤٢٠ كيلومترًا: نحو ساعتين وعشرين دقيقة بقطار الحرمين (الأجرة الأساسية ١٦٢ ريالًا تُضاف إليها ضريبة القيمة المضافة) أو أربع ساعات ونصفًا إلى خمس بالطريق البري. انظر «التنقل في المدينة، وإلى مكة» للخيارات.</li>\n</ol>\n<p>كل تأشيرة سعودية سارية تسمح بالعمرة بتصريح من نسك، ومنها التأشيرة السياحية الإلكترونية وتأشيرة الزيارة العائلية. ومن ١ ذي القعدة ١٤٤٨ (٨ أبريل ٢٠٢٧) تتوقف تصاريح العمرة لموسم الحج. والأقارب القادمون بتأشيرة عمرة يلتزمون بمواعيد موسم تأشيرتهم: انظر <a href=\"/ar/guides/bringing-parents-to-visit\">استقدام والديك لزيارة المدينة</a>.</p>\n<p>وتُعار الكراسي المتحركة مجانًا في المسجد الحرام أيضًا، على مدار الساعة، وأي عامل في الحرم يدلّك على أقرب نقطة استلام. سجّل اسمك، وأعد الكرسي فور انتهاء عمرتك.</p>\n<blockquote><p>نصيحة: العمرة في رمضان تعدل حجة في الأجر، فتمتلئ القطارات والحافلات. احجز قبلها بوقت كافٍ.</p></blockquote>"
 },
 "unit-13-and-paid-university-housing": {
  "titleAr": "الوحدة ١٣: السكن الجامعي المدفوع للطلاب السعوديين وطلاب المنحة الداخلية",
  "summaryAr": "من يحق له التقدم لغرفة مدفوعة في الوحدة ١٣، ومن يُقدَّم، والسعر في الفصل والتأمين، وكيف تتقدم، وكيف تجدد كل فصل بالدفع لصندوق الطالب، وكيف تسلّم الغرفة.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. تعطي الجامعة طلاب المنحة الكاملة (الخارجية) غرفة مجانية: انظر <a href=\"/ar/ask/is-housing-included\">هل السكن مشمول؟</a> أما من لا يحمل منحة كاملة، وهم الطلاب السعوديون وطلاب المنحة الداخلية (الجزئية)، فيستطيعون التقدم لغرفة مدفوعة في الوحدة ١٣، وهي سكن الجامعة المدفوع للطلاب الرجال داخل الحرم الجامعي. وهذا الدليل يبين من يحق له التقدم، وكم يكلف، وكيف تتقدم وتجدد.</p>\n<h2>من يحق له التقدم</h2>\n<ul>\n<li><strong>الطلاب السعوديون،</strong> مع تقديم القادمين من خارج المدينة. وتُثبت ذلك بشهادة الثانوية من مدرسة خارج المدينة.</li>\n<li><strong>طلاب المنحة الداخلية.</strong> تنظر لجنة في كل طلب.</li>\n<li>لا تُعطى الغرف إلا حين تتوفر أماكن شاغرة. والمنحة الداخلية تغطي الرسوم الدراسية فقط ولا سكن فيها، فالغرفة المدفوعة طلب مستقل، والمكان غير مضمون أبدًا.</li>\n<li>الطالب الساكن في السكن الجامعي إذا تخرج وقُبل في الماجستير احتفظ بغرفته.</li>\n</ul>\n<h2>كم يكلف</h2>\n<table><thead><tr><th>البند</th><th>المبلغ</th><th>متى</th></tr></thead><tbody>\n<tr><td>الإيجار</td><td>١٬٠٠٠ ريال للفصل</td><td>قبل استلام الغرفة، ثم قبل كل فصل جديد</td></tr>\n<tr><td>التأمين</td><td>٥٠٠ ريال، مرة واحدة</td><td>مع دفعتك الأولى. ويُرد إليك حين تسلّم الغرفة بعد تخرجك</td></tr>\n</tbody></table>\n<ul>\n<li>كل غرفة يسكنها طالبان.</li>\n<li>وللمقارنة، تؤجَّر الغرفة المفروشة بحمام خاص قرب الجامعة بنحو ١٬٥٠٠ ريال في الشهر، شاملة الفواتير (٢٠٢٦). والشقق والإيجارات في <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a> و<a href=\"/ar/guides/cost-of-living\">كم تكلف المعيشة في المدينة</a>.</li>\n</ul>\n<h2>كيف تتقدم</h2>\n<ol>\n<li><strong>ترقّب الإعلان</strong> في بداية العام الدراسي. تعلن إدارة صندوق الطالب الغرف الشاغرة، مع نموذج تقديم إلكتروني. وفي عام ١٤٤٨ فُتح النموذج في ١٤ أغسطس ٢٠٢٦.</li>\n<li><strong>املأ النموذج</strong> ما دام مفتوحًا.</li>\n<li><strong>راجع مكتب الإسكان</strong> في عمادة شؤون الطلاب أيضًا، والأفضل أن يكون ذلك في الأسبوع الأول أو قبل بدء الفصل، واطلب التأكد من أن طلبك في القائمة.</li>\n<li><strong>تابع طلبك كل بضعة أيام.</strong> يستغرق الرد من أسبوع إلى شهر، وأحيانًا فصلًا دراسيًا كاملًا.</li>\n<li><strong>بعد القبول ادفع</strong> الإيجار والتأمين كما تبين رسالة القبول. ومن يسكن لأول مرة يدفع قبل أن يستلم الغرفة.</li>\n</ol>\n<h2>التجديد كل فصل</h2>\n<ol>\n<li>قبل كل فصل جديد يصلك إشعار بالتجديد، ولديك نحو أسبوعين للدفع.</li>\n<li>حوّل <strong>١٬٠٠٠ ريال</strong> إلى الحساب البنكي لصندوق الطالب المذكور في الإشعار. واكتب اسمك ورقم غرفتك في بيان التحويل.</li>\n<li>اطبع إيصال التحويل وثبّته بالدبّاسة مع سجلك الأكاديمي الذي يثبت أنك مسجل في هذا الفصل. والسجل في النظام الأكاديمي تحت <strong>أكاديمي</strong> ثم <strong>السجل الأكاديمي</strong>.</li>\n<li>سلّم الورقتين لمشرف الوحدة قبل الموعد المحدد في الإشعار.</li>\n</ol>\n<blockquote><p>نصيحة: ادفع في يوم وصول الإشعار، ليكون إيصالك جاهزًا قبل الموعد بوقت كافٍ.</p></blockquote>\n<h2>السكن في الوحدة ١٣</h2>\n<ul>\n<li>تسري القواعد نفسها المعمول بها في كل سكن جامعي: الأثاث يبقى في الغرفة، والإصلاحات تمر عبر تواصل، وتبادل الغرف يُرتَّب مع مشرف الوحدة. انظر <a href=\"/ar/guides/university-housing-and-student-services\">غرفتك في السكن الجامعي وصندوق الطالب وتعليق الدراسة</a>.</li>\n<li><strong>فصل الإجازة:</strong> تأجيل الفصل يعني أن تسلّم الغرفة أولًا. انظر <a href=\"/ar/guides/tajeel-and-itithaar\">أخذ فصل إجازة</a>.</li>\n<li><strong>المغادرة:</strong> سلّم الغرفة لمشرف الوحدة وخذ توقيعه. فإخلاء طرفك عند التخرج يحتاج إليه، وبه يُرد إليك التأمين. انظر <a href=\"/ar/guides/graduate-procedures\">مغادرة المدينة نهائيًا</a>.</li>\n</ul>\n<blockquote><p>نصيحة: الطلاب المتزوجون والأسر يستأجرون في المدينة: انظر <a href=\"/ar/ask/married-students-housing\">هل يحصل الطلاب المتزوجون على سكن مجاني؟</a> وعندك سؤال عن طلب سكنك أنت؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "university-calendar-1448": {
  "titleAr": "التقويم الجامعي والإجازات",
  "summaryAr": "التقويم الأكاديمي للجامعة لعام ١٤٤٨ إلى ١٤٤٩ وأهم المناسبات الإسلامية، مع العدّ التنازلي لكل موعد.",
  "bodyHtmlAr": "<p>مواعيد الجامعة الإسلامية للعام الدراسي ١٤٤٨ إلى ١٤٤٩: بداية الدراسة، والاختبارات النهائية، والإجازات، وفترات الطلبات، وأهم المناسبات الإسلامية، مع العدّ التنازلي لكل موعد. والتواريخ الهجرية على تقويم أم القرى.</p>"
 },
 "university-email-and-microsoft-365": {
  "titleAr": "بريدك الجامعي وMicrosoft 365",
  "summaryAr": "عنوان بريدك الجامعي، وطريقة الدخول إليه، وتطبيقات Microsoft 365 المجانية ومساحة التخزين البالغة ١ تيرابايت التي تأتي معه، ولماذا يلزمك أن تقرأه كل يوم، ومراسلة أساتذتك، وحماية حسابك، وحفظ ملفاتك قبل أن تتخرج.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. لكل طالب في الجامعة الإسلامية حساب بريد جامعي. تصل إليه الإشعارات الرسمية، والردود على طلباتك، ورسائل أساتذتك، ويمنحك Microsoft 365 مجانًا طوال دراستك.</p>\n<h2>عنوان بريدك</h2>\n<p>بريدك الجامعي هو رقمك الجامعي متبوعًا بـ <strong>@stu.iu.edu.sa</strong>. ويظهر أيضًا في النظام الأكاديمي تحت <strong>شخصي</strong> ثم <strong>المعلومات الشخصية</strong>، وفيها تستطيع أن تضيف بريدًا شخصيًا كذلك.</p>\n<h2>الدخول</h2>\n<ol>\n<li>افتح <a href=\"https://outlook.office.com/\">outlook.office.com</a>، أو ثبّت تطبيق Outlook على جوالك.</li>\n<li>ادخل بعنوان بريدك الجامعي كاملًا وكلمة مرورك الجامعية، وهي نفسها كلمة مرور النظام الأكاديمي.</li>\n<li>إن لم يُفتح الحساب في المرة الأولى، فادخل أولًا من <a href=\"https://sso.iu.edu.sa/\">sso.iu.edu.sa</a> ثم أعد المحاولة.</li>\n<li>ما زلت لا تستطيع الدخول؟ راسل <strong>it.care@iu.edu.sa</strong>، وهو عنوان الجامعة المخصص لطلبات كلمة المرور.</li>\n</ol>\n<p>طريقة تغيير كلمة المرور، وشروط كلمة المرور الجديدة، في <a href=\"/ar/guides/university-student-system\">استخدام نظام الطالب في الجامعة</a>.</p>\n<h2>ما يأتي معه</h2>\n<ul>\n<li><strong>تطبيقات Microsoft 365</strong>: Word وExcel وPowerPoint وOutlook، مجانًا، على الإنترنت وللتثبيت على حاسوبك وجوالك. ادخل إلى كل تطبيق منها ببريدك الجامعي.</li>\n<li><strong>مساحة تخزين سحابية بسعة ١ تيرابايت</strong> في OneDrive، لملاحظاتك وبحوثك وأوراقك الممسوحة ضوئيًا.</li>\n</ul>\n<h2>اقرأه كل يوم</h2>\n<ul>\n<li>ترسل الجامعة إشعاراتها الرسمية إلى بريدك الجامعي، كالإعلان عن تقديم أعذار الاختبارات النهائية والاختبارات البديلة، والردود كالرد على التظلم من درجة.</li>\n<li>ويعتمده أساتذتك، مع رسائل بلاك بورد، وسيلةً رسمية للتواصل معك.</li>\n<li>فعّل الإشعارات في تطبيق Outlook حتى لا تبقى رسالة تنتظر دون قراءة.</li>\n</ul>\n<h2>مراسلة أساتذتك</h2>\n<ul>\n<li>في النظام الأكاديمي، تحت <strong>شخصي</strong> ثم <strong>إرسال بريد إلكتروني</strong>، تجد قائمة بأساتذتك مع عناوين بريدهم. اختر أحدهم، واكتب الموضوع والرسالة، ثم اضغط <strong>إرسال</strong>.</li>\n<li>أو اكتب من Outlook، واذكر في الأسطر الأولى اسمك الكامل ورقمك الجامعي والمقرر وشعبتك.</li>\n<li>اجعل رسالتك موجزة مهذبة، واكتبها بالعربية إن استطعت.</li>\n</ul>\n<h2>حماية حسابك</h2>\n<ul>\n<li>كلمة مرورك الجامعية تفتح كل شيء: بريدك، والنظام الأكاديمي، وبلاك بورد، وتواصل. فلا تعطها أحدًا أبدًا، ولو كان زميلًا يعرض أن يسجل لك مقرراتك.</li>\n<li>لا تفتح أبدًا روابط يرسلها إليك من لا تعرفه، في بريدك أو في محادثات الشعب. انظر <a href=\"/ar/ask/blackboard-phishing\">أحدهم نشر رابطًا في محادثة شعبتي في بلاك بورد</a>.</li>\n<li>أبقِ رقم الجوال المسجل في حسابك الجامعي محدّثًا، لأن رموز الدخول تصل إليه.</li>\n</ul>\n<h2>قبل أن تتخرج</h2>\n<p>يُغلق حسابك الجامعي بعد تخرجك، ويذهب معه بريدك وملفاتك في OneDrive. ففي فصلك الأخير انسخ ملفاتك إلى مساحة تخزين خاصة بك، وأعطِ الجامعة وأساتذتك بريدًا شخصيًا لكل ما يأتي بعد ذلك.</p>\n<blockquote><p>نصيحة: لا تستطيع الدخول إلى بريدك الجامعي؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "university-housing-and-student-services": {
  "titleAr": "غرفتك في السكن الجامعي وصندوق الطالب وتعليق الدراسة",
  "summaryAr": "السكن في مباني الجامعة: ما يبقى في غرفتك، والإصلاحات وانقطاع الكهرباء، والغرف المؤقتة والسكوترات؛ وسلفة صندوق الطالب بلا فوائد حتى ٢٬٠٠٠ ريال وإعاناته؛ وكيف يُعلن تعليق الدراسة بسبب الطقس.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. يجمع هذا الدليل ثلاثة أمور يحتاجها كل طالب يسكن في الحرم الجامعي عاجلًا أو آجلًا: قواعد غرفتك، وصندوق الطالب حين يضيق بك المال، وما يحدث حين يسوء الطقس في المدينة. أما الوجبات والحافلات والمركز الطبي والمكتبة ففي <a href=\"/ar/guides/campus-life-islamic-university\">حياة الطالب في الجامعة الإسلامية</a>.</p>\n<h2>غرفتك</h2>\n<ul>\n<li><strong>الأثاث يبقى.</strong> السرير والدولاب والمكتب والكرسي تابعة للغرفة. فلا تُخرج منها شيئًا، لأنك تسلّمها كلها عند مغادرتك.</li>\n<li><strong>الإنترنت:</strong> في الغرف منفذ شبكة (إيثرنت) للاتصال بالكابل.</li>\n<li><strong>أغلق بابك بالمفتاح</strong> كلما خرجت، وأبقِ حقيبتك معك في المصليات والمطعم الجامعي. فالسرقات تقع في الحرم الجامعي.</li>\n<li><strong>تغيير الغرفة:</strong> التبادل بين الطلاب يُرتَّب مع مشرف الوحدة.</li>\n<li><strong>فصل الإجازة:</strong> لا يُعتمد التأجيل إلا بعد أن تسلّم غرفتك وتخليها. انظر <a href=\"/ar/guides/tajeel-and-itithaar\">أخذ فصل إجازة</a>.</li>\n<li><strong>غرفة مؤقتة:</strong> الطالب المنتقل بين غرفتين، أو الخريج الذي ينتظر خروجه النهائي، يُعطى غرفة مؤقتة في الوحدة ٥. اسأل في مكتب الإسكان الرئيسي في الوحدة ٢٢.</li>\n<li><strong>السكوترات الكهربائية</strong> التي تُستعمل داخل الحرم الجامعي يجب أن تُسجَّل برمز QR وأن تحمل ملصقًا من الوحدة ٢٢. واقفل السكوتر كلما تركته.</li>\n</ul>\n<h2>الإصلاحات وانقطاع الكهرباء</h2>\n<ol>\n<li><strong>انقطعت الكهرباء عن غرفتك وحدها؟</strong> افحص لوحة القواطع في نهاية ممرك أولًا.</li>\n<li><strong>أي عطل باقٍ</strong>، كالمقبس أو الإضاءة أو التكييف أو السباكة: أرسل طلبًا عبر تواصل على <a href=\"https://helpdesk.iu.edu.sa/\">helpdesk.iu.edu.sa</a>، تحت «صيانة»، ثم نوع العطل، مثل «كهرباء». واذكر وحدتك وطابقك ورقم غرفتك، وأرفق صورة.</li>\n<li><strong>انقطعت الكهرباء عن المبنى كله،</strong> أو هناك تسرب أو أي خطر: أخبر مشرف وحدتك فورًا.</li>\n</ol>\n<p>وكيف تكتب طلبًا يُستجاب له في <a href=\"/ar/guides/university-offices-and-contacts\">من تسأل في الجامعة الإسلامية</a>.</p>\n<h2>صندوق الطالب: السلف والإعانات</h2>\n<p>يساعد صندوق الطالب الطلاب الذين ضاق بهم المال، بسلفة بلا فوائد، وبإعانة للطلاب الذين يمرون بضائقة. ومكتبه في الوحدة ٢٢.</p>\n<table><thead><tr><th>السلفة</th><th>التفاصيل</th></tr></thead><tbody>\n<tr><td>المبلغ</td><td>حتى ٢٬٠٠٠ ريال. ويُراعى معدلك التراكمي في تحديد ما تُعطاه</td></tr>\n<tr><td>السداد</td><td>٢٠٠ ريال في الشهر، تُخصم من مكافأتك</td></tr>\n<tr><td>كم مرة</td><td>مرة واحدة فقط</td></tr>\n<tr><td>لا تُتاح لـ</td><td>طلاب الفصل الأول، إذ ليس لهم معدل بعد، وطلاب السنة الأخيرة</td></tr>\n<tr><td>مدة الوصول</td><td>من أسبوع إلى أسبوعين، وحتى شهر في أوقات الضغط</td></tr>\n</tbody></table>\n<ol>\n<li>جهّز <strong>شهادة آيبان</strong> لحسابك البنكي، مطبوعة من تطبيق بنكك أو من الفرع.</li>\n<li>اطبع <strong>سجلك الأكاديمي</strong> من النظام الأكاديمي، ونسخة من هويتك من أبشر (إقامتك أو هوية الزائر).</li>\n<li>خذها مع بطاقتك الجامعية إلى مكتب صندوق الطالب في الوحدة ٢٢، واملأ نموذج السلفة.</li>\n<li>تُصرف السلفة في حسابك البنكي، ويبدأ سدادها من مكافأتك في الأشهر التالية.</li>\n</ol>\n<p><strong>الإعانة:</strong> للصندوق أيضًا قسم للإعانة يخدم الطلاب الذين يمرون بضائقة. فاسأل في مكتبه في الوحدة ٢٢. وإيجار الغرف المدفوعة في الوحدة ١٣ يُدفع للصندوق أيضًا: انظر <a href=\"/ar/guides/unit-13-and-paid-university-housing\">الوحدة ١٣: السكن الجامعي المدفوع</a>.</p>\n<blockquote><p>نصيحة: سداد السلفة هو ما يفسر وصول المكافأة ناقصة ٢٠٠ ريال. فاحسب حسابه قبل أن تقترض: انظر <a href=\"/ar/guides/getting-your-stipend-off-the-university-card\">بطاقة مكافأتك من الجامعة</a>.</p></blockquote>\n<h2>حين تُعلَّق الدراسة</h2>\n<ul>\n<li><strong>نادرًا ما تعلّق الجامعة الدراسة بسبب الطقس.</strong> فمعظم الطلاب يسكنون داخل الحرم الجامعي، لذلك تمضي المحاضرات والاختبارات عادة في المطر. وفي ديسمبر ٢٠٢٥ أغلقت الأمطار الغزيرة مدارس المدينة وجامعاتها الأخرى، ومضت الجامعة الإسلامية في اختباراتها النهائية.</li>\n<li><strong>لا يُعتدّ إلا بإعلان الجامعة.</strong> فإغلاق المدارس في المدينة، أو تعليق الدراسة في جامعة أخرى، لا يغلق الجامعة الإسلامية.</li>\n<li><strong>أين يُعلن:</strong> في حساب الجامعة الرسمي على منصة X (@iu_edu) وحساب عمادة شؤون الطلاب (@dsa_iu_edu).</li>\n<li><strong>الإجازات المطوّلة للمدارس لا تشمل الجامعة.</strong> ففي الفصل الأول الإجازة الوحيدة هي اليوم الوطني. وكل الإجازات في <a href=\"/ar/guides/university-calendar-1448\">التقويم الجامعي</a>.</li>\n</ul>\n<blockquote><p>نصيحة: في يوم العاصفة ابقَ في السكن ولا تتنقل عبر المدينة، وراجع الحسابات الرسمية قبل أن تخرج إلى محاضرة مبكرة. عندك سؤال عن غرفتك أو عن الصندوق؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "university-offices-and-contacts": {
  "titleAr": "من تسأل في الجامعة الإسلامية: المكاتب والبوابات وجهات الاتصال",
  "summaryAr": "أي مكتب أو بوابة يتولى التذاكر والتأشيرات والتسجيل والغياب والسكن والصحة والوجبات وكلمات المرور والمستندات، مع الأرقام والبريد والروابط، وكيف تسجّل الدخول، وكيف تكتب طلبًا يلقى ردًّا.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. معظم المشكلات في الجامعة تُحل بسرعة حين تصل إلى المكتب الصحيح. وهذه الصفحة تبين من يتولى كل أمر، والبوابة أو جهة الاتصال الخاصة به.</p>\n<h2>ابدأ هنا</h2>\n<ul>\n<li><strong>رعاية الطلاب:</strong> اتصل بالرقم <strong>920022042</strong> أو راسل <strong>care@iu.edu.sa</strong> حين لا تعرف الجهة المختصة بسؤالك.</li>\n<li><strong>تواصل</strong>، نظام الطلبات في الجامعة، على <a href=\"https://helpdesk.iu.edu.sa/\">helpdesk.iu.edu.sa</a>. ادخل بحسابك الجامعي وأرسل طلبك إلى المكتب المختص. وإن لم تستطع الدخول بعد فاستعمل نموذج الزائر على <a href=\"https://helpdesk.iu.edu.sa/newticket_guest\">helpdesk.iu.edu.sa/newticket_guest</a>. وكثيرًا ما لا يظهر الرد إلا بعد إغلاق الطلب، فإن لم تجد شيئًا فغيّر تصفية الطلبات من الطلبات قيد المعالجة إلى الطلبات المغلقة بانتظار التقييم.</li>\n<li><strong>بريدك الجامعي.</strong> الردود والإشعارات الرسمية تصل إليه، فاقرأه كل يوم.</li>\n<li><strong>وكيل كليتك</strong> لشؤون الطلاب: الغياب، والأعذار، ومشكلات الجدول بعد الحذف والإضافة، وكل ما تقرره كليتك.</li>\n</ul>\n<h2>من يتولى ماذا</h2>\n<table><thead><tr><th>تحتاج إلى</th><th>من يتولاه</th><th>أين</th></tr></thead><tbody>\n<tr><td>تذكرتك إلى بلدك، وتذكرة وصولك، وشؤون الجواز</td><td>إدارة السفر</td><td>التذاكر عبر اعتماد: انظر <a href=\"/ar/guides/etimad-account\">تذكرتك من الجامعة: اعتماد وأمر الإركاب والقواعد</a>. وتذاكر الوصول عبر منحتي</td></tr>\n<tr><td>تأشيرة الخروج والعودة، وتجديد إقامتك</td><td>إدارة السفر</td><td><strong>نظام إدارة السفر</strong> في الخدمات الإلكترونية للجامعة، أو تواصل</td></tr>\n<tr><td>تأشيرتك التعليمية وهوية الزائر</td><td>عمادة القبول والتسجيل</td><td>تواصل، بموضوع «التأشيرة التعليمية»: انظر <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر</a></td></tr>\n<tr><td>التسجيل، وجدولك، وحذف المقررات وإضافتها، والتأجيل والاعتذار، والتحويل</td><td>عمادة القبول والتسجيل</td><td>النظام الأكاديمي، وتواصل أو <strong>admission.reg@iu.edu.sa</strong> لما لا يتيحه النظام</td></tr>\n<tr><td>تأشيرة جديدة بعد تأجيل أو اعتذار أو انقطاع عن الدراسة</td><td>عمادة القبول والتسجيل</td><td><a href=\"https://minhatee2.iu.edu.sa/Home/VisaLanding\">صفحة التأشيرات في منحتي</a>، بالدخول برقمك الجامعي</td></tr>\n<tr><td>عذر غياب، أو اختبار نهائي فاتك، أو درجة تريد مراجعتها</td><td>كليتك</td><td>شاشات النظام الأكاديمي المشروحة في <a href=\"/ar/guides/exams-results-and-attendance\">الاختبارات والنتائج والحضور في الجامعة الإسلامية</a>، ثم وكيل كليتك</td></tr>\n<tr><td>إرشاد في خطتك الدراسية</td><td>مرشدك الأكاديمي</td><td>النظام الأكاديمي، أكاديمي، ثم <strong>التواصل مع المرشد الأكاديمي</strong></td></tr>\n<tr><td>رسالة إلى أستاذ</td><td>الأستاذ نفسه</td><td>النظام الأكاديمي، شخصي، ثم <strong>إرسال بريد إلكتروني</strong>، أو رسالة في بلاك بورد</td></tr>\n<tr><td>السكن والأنشطة والأندية والحياة في السكن</td><td>عمادة شؤون الطلاب</td><td>تواصل، أو المكتب حضوريًا. ومكتب السكن الخاص بتسليم الغرف في الوحدة ٢٢</td></tr>\n<tr><td>مكافأتك وبطاقة المكافأة</td><td>خدمة المكافآت</td><td>النظام الأكاديمي، شخصي، ثم المكافآت</td></tr>\n<tr><td>خطاب يثبت أنك طالب، أو سجل أكاديمي</td><td>يصدر تلقائيًا، مجانًا ومختومًا</td><td>النظام الأكاديمي، شخصي، ثم المستندات الرسمية</td></tr>\n<tr><td>كلمات المرور ومشكلات الدخول</td><td>عمادة تقنية المعلومات والتعليم الإلكتروني</td><td><strong>it.care@iu.edu.sa</strong>، أو <strong>‎+966 14 847 1856‎</strong></td></tr>\n<tr><td>بلاك بورد</td><td>مركز التعليم الإلكتروني</td><td><strong>bb@iu.edu.sa</strong>، أو طلب عبر تواصل إلى مركز التعليم الإلكتروني: انظر <a href=\"/ar/ask/blackboard-login\">كيف أدخل إلى بلاك بورد؟</a></td></tr>\n<tr><td>طبيب أو طبيب أسنان</td><td>المركز الطبي الجامعي</td><td>احجز على <a href=\"https://vcappointments.iu.edu.sa/\">vcappointments.iu.edu.sa</a></td></tr>\n<tr><td>الضغط النفسي، أو قلق الاختبارات، أو الحنين إلى الأهل، أو صعوبة شخصية</td><td>وحدة التوجيه والإرشاد الطلابي في عمادة شؤون الطلاب</td><td>حضوريًا، بجوار مسجد الإمام ابن باز من جهة المطعم الجامعي، أو عن طريق وحدة الإرشاد في كليتك. مجانًا</td></tr>\n<tr><td>الوجبات في المطعم الجامعي</td><td>المطعم الجامعي</td><td>احجز شهريًا على <a href=\"https://restaurant.iu.edu.sa/\">restaurant.iu.edu.sa</a></td></tr>\n<tr><td>طلب الالتحاق، قبل أن تصل</td><td>عمادة القبول والتسجيل</td><td><a href=\"https://minhatee2.iu.edu.sa/\">منحتي</a> ومكتب الدعم فيها، و«ادرس في السعودية» للقبول النهائي والتأشيرة</td></tr>\n</tbody></table>\n<h2>تسجيل الدخول</h2>\n<ol>\n<li>افتح <a href=\"https://iu.edu.sa/\">iu.edu.sa</a> واضغط أيقونة <strong>حساب المستخدم</strong> في الشريط العلوي، أو اذهب مباشرة إلى sso.iu.edu.sa.</li>\n<li>اختر <strong>الدخول عن طريق نفاذ</strong>، أو <strong>الدخول بالرقم الجامعي / الوظيفي</strong>.</li>\n<li>بالرقم الجامعي: اكتب الرقم وكلمة المرور و<strong>رمز التحقق</strong> الظاهر على الشاشة بجوار الخانة. واضغط سهم التحديث إن صعبت قراءة الرمز. ثم اضغط <strong>دخول</strong>.</li>\n<li>إن تعلّق الموقع فادخل عبر نفاذ أو استعمل تطبيق الجامعة.</li>\n</ol>\n<p>دخول واحد يفتح كل أنظمة الجامعة. وتغيّر كلمة المرور، ورقم الجوال الذي تصله تنبيهات الجامعة ورموزها، من أيقونة <strong>حساب المستخدم</strong> نفسها. وكل شاشة مشروحة خطوة بخطوة في <a href=\"/ar/guides/university-student-system\">استعمال نظام الطالب في الجامعة</a>.</p>\n<h2>البوابات التي ستستعملها</h2>\n<ul>\n<li><strong>النظام الأكاديمي:</strong> خمس قوائم: التسجيل الإلكتروني، وشخصي، وأكاديمي، ونظام إدارة السفر، وإجراءات التخرج. وفيه جدولك ونتائجك وغيابك وطلباتك الأكاديمية ومكافآتك ومستنداتك الرسمية.</li>\n<li><strong>بلاك بورد</strong>، وأيقونته باسم <strong>زدني</strong>: مقرراتك وموادك واختباراتك ومحادثات الشعب. ولا تفتح أبدًا روابط تنشرها حسابات لا تعرفها: انظر <a href=\"/ar/ask/blackboard-phishing\">أحدهم نشر رابطًا في محادثة شعبتي في بلاك بورد</a>.</li>\n<li><strong>تواصل</strong> (نظام تواصل / إدارة الطلبات): الطلبات إلى أي مكتب.</li>\n<li><strong>المكتبة الرقمية السعودية:</strong> كتب ودوريات وقواعد بيانات، تُفتح من داخل المملكة.</li>\n<li><strong>منحتي:</strong> طلب الالتحاق، وطلب تذكرة الوصول، وتجديد التأشيرة للطلاب العائدين.</li>\n<li><strong>اعتماد:</strong> أوامر الإركاب لتذاكر الجامعة.</li>\n</ul>\n<h2>كيف تكتب طلبًا يلقى ردًّا</h2>\n<ol>\n<li>أرسله إلى المكتب الذي يتولى الأمر، بحسب الجدول أعلاه. وفي تواصل اضغط <strong>طلب جديد</strong> واختر المكتب من القائمة.</li>\n<li>ضع له عنوانًا واضحًا في خانة <strong>الموضوع</strong>. وفي خانة <strong>تفاصيل الطلب</strong> ابدأ باسمك الكامل كما في جوازك، ورقمك الجامعي، وكليتك.</li>\n<li>اذكر في أسطر قليلة ما تحتاج إليه، وما جربته من قبل، وأين، وماذا قيل لك.</li>\n<li>أرفق لقطات شاشة لأي خطأ ونسخًا من المستندات المتعلقة بالأمر، ثم اضغط <strong>إرسال الطلب</strong>.</li>\n<li>تابعه من <strong>طلباتي</strong>، واحفظ الرقم المرجعي لتتابعه به.</li>\n<li>راقب بريدك الجامعي للرد، وأجب عن أي استفسار لاحق في اليوم نفسه. وإن لم يأتك شيء فتابعه حضوريًا.</li>\n</ol>\n<blockquote><p>نصيحة: يجب أن يطابق اسمك جوازك حرفًا بحرف في كل بوابة. فالاختلاف أكثر أسباب تعطل التذاكر والطلبات شيوعًا.</p></blockquote>\n<h2>الأخبار الرسمية</h2>\n<p>تنشر الجامعة الإعلانات والتقاويم والمواعيد النهائية على X: <strong>@iu_edu</strong> للجامعة، و<strong>@AdmissDeanship</strong> لعمادة القبول والتسجيل، و<strong>@dsa_iu_edu</strong> لعمادة شؤون الطلاب. فاعتمد على هذه الحسابات وعلى بريدك الجامعي، لا على الرسائل المعاد توجيهها في المجموعات.</p>\n<h2>خارج الجامعة</h2>\n<table><thead><tr><th>الغرض</th><th>جهة الاتصال</th></tr></thead><tbody>\n<tr><td>أبشر أو نفاذ لا يتفعّل</td><td>خدمة عملاء أبشر، <strong>920020405</strong>، على مدار الساعة. انظر <a href=\"/ar/ask/absher-nafath-activation\">تفعيل أبشر أو نفاذ يفشل عندي باستمرار</a></td></tr>\n<tr><td>عقد إيجار</td><td>إيجار، <strong>199011</strong></td></tr>\n<tr><td>حافلات المدينة</td><td>حافلات المدينة، <strong>920000877</strong></td></tr>\n<tr><td>قطار الحرمين</td><td><strong>920004433</strong></td></tr>\n<tr><td>المسجد النبوي</td><td>الهيئة العامة للعناية بشؤون المسجد الحرام والمسجد النبوي، <strong>1966</strong></td></tr>\n<tr><td>الطوارئ</td><td>الإسعاف <strong>997</strong>، والرقم الموحد للطوارئ <strong>911</strong></td></tr>\n</tbody></table>\n<p>الحياة اليومية في الحرم الجامعي في <a href=\"/ar/guides/campus-life-islamic-university\">حياة الطالب في الجامعة الإسلامية</a>.</p>\n<blockquote><p>نصيحة: لا تعرف أي مكتب تسأل؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "university-student-system": {
  "titleAr": "استخدام نظام الطالب في الجامعة خطوة بخطوة",
  "summaryAr": "كل شاشة تستخدمها طالبًا في الجامعة الإسلامية: الدخول، وكلمة المرور، وقوائم النظام الأكاديمي، والتسجيل والتثبيت، وجدولك، والنتائج وتقييم المقررات، والغياب، وشاشة مكافأتك، والمستندات، والطلبات، وتواصل، وبلاك بورد، وبمن تتصل حين يتعطل شيء.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. يكاد كل ما تفعله طالبًا في الجامعة الإسلامية يجري في أنظمة إلكترونية قليلة: تسجيل المقررات، والاطلاع على نتائجك، وطلب إجازة فصل دراسي، وطباعة خطاب. وتشرح هذه الصفحة كل شاشة، بأسماء القوائم كما تظهر في النظام تمامًا.</p>\n<h2>الأنظمة التي ستستخدمها</h2>\n<table><thead><tr><th>النظام</th><th>الغرض منه</th></tr></thead><tbody>\n<tr><td><strong>النظام الأكاديمي</strong></td><td>التسجيل، وجدولك، والنتائج، والسجل الأكاديمي، والخطة الدراسية، والغياب، والطلبات، وسجل مكافأتك، والمستندات الرسمية، وبياناتك الشخصية</td></tr>\n<tr><td><strong>بلاك بورد</strong> (إدارة التعلم الإلكتروني زدني)</td><td>محاضراتك عبر الإنترنت: المواد، والواجبات، والاختبارات، والمحاضرات المسجلة، والرسائل إلى معلميك</td></tr>\n<tr><td><strong>تواصل</strong> (نظام تواصل / إدارة الطلبات)</td><td>الطلبات والمشكلات الموجهة إلى أي جهة في الجامعة</td></tr>\n<tr><td><strong>المكتبة الرقمية السعودية</strong></td><td>الكتب والمراجع. ولا تعمل في الغالب إلا من داخل المملكة</td></tr>\n</tbody></table>\n<p>تفتح كلها بدخول واحد، فلا تحتاج إلا إلى كلمة مرور واحدة. أما بريدك الجامعي فمنفصل عنها: انظر <a href=\"/ar/guides/university-email-and-microsoft-365\">بريدك الجامعي وMicrosoft 365</a>.</p>\n<h2>الدخول</h2>\n<ol>\n<li>افتح <a href=\"https://iu.edu.sa/\">iu.edu.sa</a> واضغط أيقونة <strong>حساب المستخدم</strong> أعلى الصفحة، أو اذهب مباشرة إلى <a href=\"https://sso.iu.edu.sa/\">sso.iu.edu.sa</a>.</li>\n<li>اختر <strong>الدخول عن طريق نفاذ</strong>، أو <strong>الدخول بالرقم الجامعي / الوظيفي</strong>.</li>\n<li>إن دخلت برقمك الجامعي: اكتب الرقم وكلمة المرور و<strong>رمز التحقق</strong> الظاهر بجانب الخانة. واضغط سهم التحديث إن صعبت قراءة الرمز.</li>\n<li>اضغط <strong>دخول</strong>. تعرض لوحتك، <strong>بياناتي الطلابية</strong>، فصلك الحالي، ومعدلك الفصلي والتراكمي، ومجموع غيابك، ومحاضرات اليوم.</li>\n<li>اضغط المربع الذي تحتاجه: <strong>النظام الأكاديمي</strong>، أو <strong>زدني</strong> لبلاك بورد، أو <strong>تواصل</strong>.</li>\n</ol>\n<p><strong>دخولك الأول:</strong> يصلك رقمك الجامعي وكلمة مرور مؤقتة بالبريد الإلكتروني من IU Eservices، بعنوان IU Single Sign-On. غيّر كلمة المرور فور دخولك.</p>\n<p><strong>إن توقف الدخول عن الاستجابة أو لم تُقبل كلمة المرور:</strong> ادخل عن طريق نفاذ بدلًا من ذلك، ثم عيّن كلمة مرور جديدة من قائمة الحساب. وإن لم يعمل نفاذ معك أيضًا فراسل <strong>it.care@iu.edu.sa</strong>، وهو العنوان المخصص لطلبات كلمة المرور.</p>\n<h2>تغيير كلمة المرور أو رقم الجوال</h2>\n<ol>\n<li>اضغط أيقونة <strong>حساب المستخدم</strong>، ثم <strong>تغيير كلمة المرور</strong> أو <strong>تغيير رقم الجوال</strong>.</li>\n<li><strong>كلمة المرور:</strong> اكتب كلمة المرور الحالية، أو أكّد عن طريق نفاذ، ثم الجديدة مرتين، واضغط <strong>تحديث</strong>. ويجب ألا تقل عن ٨ خانات، وأن تحتوي حرفًا إنجليزيًا كبيرًا وحرفًا إنجليزيًا صغيرًا ورقمًا ورمزًا مثل ! @ # $ أو %.</li>\n<li><strong>الجوال:</strong> اكتب الرقم الجديد، واضغط <strong>تحديث</strong>، ثم أدخل الرمز المرسل إلى ذلك الرقم. وأبقِ هذا الرقم محدّثًا، فإليه تصل رموز التحقق وتنبيهات الجامعة.</li>\n</ol>\n<h2>التنقل في النظام الأكاديمي</h2>\n<p>في أعلى النظام الأكاديمي خمس قوائم.</p>\n<table><thead><tr><th>القائمة</th><th>ما تجده فيها</th></tr></thead><tbody>\n<tr><td><strong>التسجيل الإلكتروني</strong></td><td>تعليمات و إرشادات، المقررات المطروحة وفق الخطة، المقررات المسجلة (جدولك)، نتائج المقررات، الحذف والإضافة</td></tr>\n<tr><td><strong>شخصي</strong></td><td>تحديث الاسم باللغة العربية أو الانجليزية، المعلومات الشخصية، الغياب، إرسال بريد إلكتروني إلى معلم، المستندات الرسمية، طلب تعديل الجنسية ومكان الميلاد، المكافآت (مكافأتك)، الدفع الإلكتروني</td></tr>\n<tr><td><strong>أكاديمي</strong></td><td>السجل الأكاديمي، حركات أكاديمية سابقة، خطة الطالب، المقررات المجتازة والمتبقية في الخطة، تقييم المقررات، الاختبارات النهائية، تقديم الأعذار عن غياب المحاضرات، تقديم الأعذار عن غياب الاختبار النهائي، إدخال حركات اكاديمية، الإعتذار عن مقرر، إخلاء طرف، التواصل مع المرشد الأكاديمي</td></tr>\n<tr><td><strong>نظام إدارة السفر</strong></td><td>طلباتك إلى إدارة السفر</td></tr>\n<tr><td><strong>اجراءات التخرج</strong></td><td>خطوات تخرجك، ومراجعة البيانات التي تُطبع في شهادتك</td></tr>\n</tbody></table>\n<p>وتعرض الصفحة الرئيسية أيضًا <strong>الوضع العام</strong>، والمفترض أن تظهر فيه كلمة <strong>منتظم</strong>، و<strong>عدد إنذارات المعدل</strong>. وما يعنيه الإنذار تجده في <a href=\"/ar/guides/gpa-warnings-and-dismissal\">معدلك والإنذارات الأكاديمية والفصل الأكاديمي</a>.</p>\n<blockquote><p>نصيحة: تفتح المستندات الرسمية في نافذة منبثقة. فإن لم يفتح شيء فاسمح بالنوافذ المنبثقة للموقع eservices.iu.edu.sa. في متصفح Chrome على الحاسوب: الإعدادات، ثم الخصوصية والأمان، ثم إعدادات المواقع، ثم النوافذ المنبثقة وعمليات إعادة التوجيه. وعلى جوال أندرويد: Chrome، ثم الإعدادات، ثم إعدادات المواقع، ثم النوافذ المنبثقة.</p></blockquote>\n<h2>جدولك ومقرراتك المسجلة</h2>\n<ol>\n<li>افتح <strong>التسجيل الإلكتروني</strong>، ثم <strong>المقررات المسجلة</strong>.</li>\n<li>اختر الفصل. يظهر لكل مقرر رمزه وشعبته وساعاته المعتمدة ويومه ووقته وقاعته ومعلمه، وفي الأسفل مجموع ساعاتك المعتمدة واسم مرشدك الأكاديمي.</li>\n<li>اضغط <strong>طباعة</strong> لتحتفظ بنسخة.</li>\n</ol>\n<ul>\n<li><strong>الأيام أرقام:</strong> ١ للأحد، و٢ للاثنين، و٣ للثلاثاء، و٤ للأربعاء، و٥ للخميس.</li>\n<li><strong>القاعة</strong> يُذكر فيها المبنى أولًا. فكلمة «الدعوة» مثلًا تعني مبنى كلية الدعوة.</li>\n<li><strong>المقررات المطروحة وفق الخطة</strong> تعرض كل شعبة يمكنك تسجيلها هذا الفصل، مع معلمها، وهل هي مفتوحة أم مكتملة. والمقرر الذي لم تجتز متطلبه السابق لا يظهر فيها.</li>\n</ul>\n<h2>إضافة مقرر وحذفه</h2>\n<p>لا يُفتح الحذف والإضافة إلا في فترته المحددة في التقويم الأكاديمي، وكليتك تعطي طلاب الفصل الأول جدولًا ثابتًا. والقواعد والمواعيد وما تفعله بعد انتهاء الفترة في <a href=\"/ar/guides/registering-your-courses\">تسجيل مقرراتك: الإضافة والحذف والانسحاب</a>. واستخدم الحاسوب، فالصفحة لا تعمل جيدًا على الجوال.</p>\n<ol>\n<li>افتح <strong>التسجيل الإلكتروني</strong>، ثم <strong>الحذف والإضافة</strong>.</li>\n<li>ضع علامة في المربع بجانب المقرر الذي تريده.</li>\n<li>اضغط العدسة تحت <strong>ابحث عن شعبة</strong>. وإن كان للمقرر أكثر من شعبة ظهر لك مربع: اضغط رقم الشعبة التي تريدها.</li>\n<li>انزل إلى أسفل الصفحة واضغط <strong>إضافة</strong>.</li>\n<li>يظهر المقرر الآن تحت <strong>إجراءات غير مثبتة</strong>. اضغط <strong>تثبيت</strong>. فلا يُسجَّل شيء حتى تثبّت.</li>\n<li>لحذف مقرر اضغط زر <strong>حذف</strong> الأحمر بجانبه في الصفحة نفسها، ثم اضغط <strong>تثبيت</strong> مرة أخرى.</li>\n<li>افتح <strong>المقررات المسجلة</strong> بعد ذلك وتأكد أن كل تغيير نُفّذ.</li>\n</ol>\n<p>وشرح الجامعة المصوَّر تجده تحت <strong>التسجيل الإلكتروني</strong>، ثم <strong>تعليمات و إرشادات</strong>.</p>\n<h2>النتائج: قيّم مقرراتك أولًا</h2>\n<p>تبقى نتائجك، ومعها درجات أعمال الفصل، مخفية حتى تُكمل تقييم كل مقرر. ويُفتح التقييم قرب نهاية الفصل ثم يُغلق، فأنجزه فور فتحه.</p>\n<ol>\n<li>افتح <strong>أكاديمي</strong>، ثم <strong>تقييم المقررات</strong>.</li>\n<li>اضغط رمز مقرر تحت <strong>رمز المقرر</strong>.</li>\n<li>أجب عن كل عبارة باختيار دائرة واحدة، من <strong>أوافق بشدة</strong> إلى <strong>لا أوافق بشدة</strong>، ثم احفظ. وإجاباتك سرية لا يُعرف صاحبها.</li>\n<li>كرر ذلك لكل مقرر.</li>\n<li>بعد أن تعتمد كليتك الدرجات افتح <strong>التسجيل الإلكتروني</strong>، ثم <strong>نتائج المقررات</strong>، واختر الفصل. يظهر لكل مقرر درجة الاختبار النهائي، ودرجة أعمال الفصل، والمجموع، والتقدير. واضغط <strong>طباعة</strong> لتحتفظ بنسخة.</li>\n</ol>\n<p>وطريقة حساب التقديرات والمعدل في <a href=\"/ar/guides/gpa-warnings-and-dismissal\">معدلك والإنذارات الأكاديمية والفصل الأكاديمي</a>.</p>\n<h2>سجلك الأكاديمي وخطتك الدراسية</h2>\n<ul>\n<li><strong>السجل الأكاديمي</strong>، تحت أكاديمي: كل مقرر بساعاته ونقاطه وتقديره، وساعاتك ومعدلك الفصلي والتراكمي. وهو للاطلاع الشخصي، وليس مستندًا رسميًا.</li>\n<li><strong>خطة الطالب</strong>: جميع مقررات درجتك في جدول واحد، مرتبة برمز المقرر.</li>\n<li><strong>المقررات المجتازة في الخطة</strong> و<strong>المقررات المتبقية في الخطة</strong>: ما أنهيته وما بقي عليك، مع ساعات كل مقرر ومستواه.</li>\n</ul>\n<p>وما تدرّسه كل كلية، مستوى بعد مستوى، في <a href=\"/ar/guides/what-you-study-by-level\">ما تدرسه في كل كلية، مستوى بعد مستوى</a>.</p>\n<h2>اختباراتك وغيابك</h2>\n<ul>\n<li><strong>جدول الاختبارات النهائية:</strong> أكاديمي، ثم <strong>الاختبارات النهائية</strong>. ويُنشر قبل فترة الاختبارات بأسابيع، ويُشار فيه إلى كل مقرر حُرمت منه أو انسحبت منه.</li>\n<li><strong>غيابك:</strong> شخصي، ثم <strong>الغياب</strong>. ترى لكل مقرر مجموع غيابك ومجموع تأخرك ونسبة غيابك. فإذا تجاوزت ٢٥٪ حُرمت من الاختبار النهائي. والسجل هنا هو المعتمد، لا الحضور الظاهر في بلاك بورد.</li>\n<li><strong>عذر عن محاضرة فائتة:</strong> أكاديمي، ثم <strong>تقديم الأعذار عن غياب المحاضرات</strong>. ارفع العذر ما دام المقرر ظاهرًا في القائمة. فإن اختفى منها فأرسل العذر إلى كليتك عبر تواصل.</li>\n<li><strong>اختبار نهائي فائت:</strong> بعد الاختبارات النهائية، أكاديمي، ثم <strong>تقديم الأعذار عن غياب الاختبار النهائي</strong>، ثم <strong>طلب اعتذار عن الاختبارات النهائية</strong>. وتابع طلبك تحت <strong>اظهار و متابعة طلبات الاعتذار</strong>. وانظر <a href=\"/ar/ask/missed-a-final-exam\">فاتني اختبار نهائي، فما الذي يترتب على ذلك؟</a></li>\n</ul>\n<p>وقواعد الحضور والاختبارات في <a href=\"/ar/guides/exams-results-and-attendance\">الاختبارات والنتائج والحضور</a>.</p>\n<h2>مكافأتك ومستنداتك ومدفوعاتك</h2>\n<ul>\n<li><strong>المكافآت</strong>، تحت شخصي: سجل مكافأتك الشهرية. وكل ما يخص المكافأة في <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة</a>.</li>\n<li><strong>المستندات الرسمية</strong>، تحت شخصي: الأوراق المختومة التي تقدّمها إلى الجهات الأخرى، مثل خطاب «تعريف بالطالب» وسجلك الأكاديمي. وهي مجانية وتصدر فورًا.</li>\n<li><strong>الدفع الإلكتروني</strong>، تحت شخصي، ثم <strong>بطاقات</strong>: لطلاب البرامج المدفوعة فقط. اكتب المبلغ المستحق في <strong>المبلغ المراد دفعه</strong> واضغط <strong>دفع</strong>. ويقبل مدى وVisa وMastercard. واحتفظ بالإيصال، ولا حاجة إلى إرساله إلى أحد.</li>\n</ul>\n<h2>مراسلة معلم أو مرشدك الأكاديمي</h2>\n<ul>\n<li><strong>المعلم:</strong> شخصي، ثم <strong>إرسال بريد إلكتروني</strong>. حدد المعلم، واكتب الموضوع ورسالتك، واضغط <strong>إرسال</strong>. ويمكنك أيضًا مراسلة المعلم داخل بلاك بورد.</li>\n<li><strong>مرشدك الأكاديمي:</strong> أكاديمي، ثم <strong>التواصل مع المرشد الأكاديمي</strong>، ثم <strong>طلب تواصل جديد</strong>. اكتب رسالتك (٥٠٠ حرف على الأكثر)، وأرفق ملفًا إن احتجت، واضغط <strong>إرسال</strong>. وتجد الردود تحت <strong>استعراض الطلبات السابقة</strong>. وإن تأخر الرد وكان الأمر عاجلًا فراجع وكيل كليتك.</li>\n</ul>\n<h2>تصحيح اسمك أو جنسيتك أو بيانات ميلادك</h2>\n<p><strong>اسمك.</strong> شخصي، ثم <strong>تحديث الاسم باللغة العربية</strong> أو <strong>تحديث الاسم باللغة الانجليزية</strong>.</p>\n<ul>\n<li>أدخل الاسم رباعيًا: الاسم الأول، واسم الأب، واسم الجد، واسم العائلة، مطابقًا لجواز سفرك تمامًا. وبالعربية استخدم الحروف العربية وحدها، بلا مسافة ولا شرطة في اسم العائلة.</li>\n<li>ارفع صورة من جواز سفرك (JPG أو PDF)، واكتب الاسم، وأكّده، واضغط <strong>حفظ</strong>.</li>\n<li>يظهر التعديل بعد أن تتحقق عمادة القبول والتسجيل من تطابق اسمك بالعربية والإنجليزية.</li>\n<li>أنجز ذلك قبل فصلك الأخير بوقت كافٍ. فبعد صدور وثيقة تخرجك لا تُضاف كتابة اسمك بالعربية ولا تُصحَّح إلا بدفع رسوم وثيقة بديلة. وانظر <a href=\"/ar/ask/graduation-certificate-name-check\">كيف أتأكد أن اسمي صحيح في شهادة تخرجي؟</a></li>\n</ul>\n<p><strong>الجنسية وتاريخ الميلاد أو مكانه.</strong> شخصي، ثم <strong>طلب تعديل الجنسية ومكان الميلاد</strong>. اختر نوع التعديل والقيمة الصحيحة، وارفع جواز سفرك وإقامتك الجديدة معًا في ملف PDF واحد، واضغط <strong>حفظ</strong>.</p>\n<p><strong>الجوال والبريد الإلكتروني.</strong> شخصي، ثم <strong>المعلومات الشخصية</strong>. عدّل رقم جوالك أو بريدك الشخصي أو بريدك الجامعي، واضغط <strong>تعديل</strong>.</p>\n<h2>الطلبات في النظام الأكاديمي</h2>\n<ul>\n<li><strong>إجازة فصل دراسي:</strong> أكاديمي، ثم <strong>إدخال حركات اكاديمية</strong>، في الفترات المحددة في التقويم. اقرأ الشروط واضغط <strong>أوافق</strong> للمتابعة. ولا يتغير شيء حتى تتغير حالتك، فواظب على الحضور حتى يحدث ذلك. والخطوات كاملة في <a href=\"/ar/guides/tajeel-and-itithaar\">أخذ فصل إجازة</a>. وطلباتك السابقة تحت <strong>حركات أكاديمية سابقة</strong>.</li>\n<li><strong>الانسحاب من مقرر واحد:</strong> أكاديمي، ثم <strong>الإعتذار عن مقرر</strong>، ثم <strong>طلب إعتذار</strong>. وتابع طلبك تحت <strong>إظهار المقررات المعتذر عنها</strong>. وخارج الفترة تظهر رسالة بأن العملية لا يمكن إتمامها في هذه الفترة. والحدود في <a href=\"/ar/guides/registering-your-courses\">تسجيل مقرراتك</a>.</li>\n<li><strong>المغادرة بعد التخرج:</strong> أكاديمي، ثم <strong>إخلاء طرف</strong>. وانظر <a href=\"/ar/guides/graduate-procedures\">مغادرة المدينة نهائيًا</a>.</li>\n</ul>\n<h2>تقديم طلب: تواصل</h2>\n<ol>\n<li>من صفحة الدخول افتح <strong>نظام تواصل / إدارة الطلبات</strong>، أو اذهب إلى <a href=\"https://helpdesk.iu.edu.sa/\">helpdesk.iu.edu.sa</a>.</li>\n<li>اضغط <strong>طلب جديد</strong> واختر الجهة من «قائمة الجهات»: عمادة القبول والتسجيل، أو كليتك، أو إدارة السفر، أو عمادة شؤون الطلاب، أو جهة أخرى.</li>\n<li>اكتب للطلب عنوانًا واضحًا في <strong>الموضوع</strong>، واشرحه في <strong>تفاصيل الطلب</strong>. وأضف صورة شاشة أو مستندًا من <strong>إضافة مرفقات</strong>.</li>\n<li>اضغط <strong>إرسال الطلب</strong>.</li>\n<li>تابع الرد تحت <strong>طلباتي</strong>. والطلبات المفتوحة تحت <strong>طلبات تحت التنفيذ</strong>.</li>\n</ol>\n<p>يُرفق رقمك الجامعي بالطلب تلقائيًا. واكتب طلبك بأسلوبك، في كل طلب موضوع واحد. وأي جهة تتولى أي أمر، وكيف تكتب طلبًا يلقى ردًا، في <a href=\"/ar/guides/university-offices-and-contacts\">من تسأل في الجامعة الإسلامية</a>.</p>\n<h2>بلاك بورد</h2>\n<ul>\n<li><strong>على الحاسوب:</strong> ادخل من iu.edu.sa واضغط مربع <strong>زدني</strong>. فيفتح بلاك بورد دون دخول ثانٍ.</li>\n<li><strong>على الجوال:</strong> في تطبيق بلاك بورد ابحث عن Islamic University of Madinah، واضغط <strong>المتابعة بتسجيل الدخول عبر الويب</strong>، وادخل برقمك الجامعي وكلمة المرور. وإن ظل التطبيق يُخرجك فاستخدم بلاك بورد من متصفح جوالك.</li>\n<li><strong>نسيت كلمة مرور بلاك بورد:</strong> في صفحة الدخول عبر الويب اضغط <strong>هل نسيت كلمة المرور؟</strong> واكتب اسمك الأول واسم عائلتك كما سُجلا تمامًا، مع رقمك الجامعي أو بريدك، فيصلك رابط إعادة التعيين بالبريد. وتبقى كلمة المرور القديمة صالحة حتى تغيّرها.</li>\n<li><strong>داخل بلاك بورد:</strong> <strong>النشاط</strong> يعرض الجديد في مقرراتك، و<strong>التقويم</strong> يعرض مواعيد تسليم الواجبات والاختبارات، و<strong>الدرجات</strong> تعرض درجاتك حتى الآن. وتفتح المحاضرة المباشرة من <strong>الانضمام إلى الجلسة</strong>، وتسجيلها تحت النقاط الثلاث، ثم <strong>عرض كل التسجيلات</strong>. وفعّل الإشعارات من إعداداتك حتى لا يفوتك موعد تسليم.</li>\n</ul>\n<p>ولمزيد من المساعدة: <a href=\"/ar/ask/blackboard-login\">كيف أدخل إلى بلاك بورد، وماذا أفعل إن تعذر الدخول؟</a> ولا تفتح أبدًا الروابط المنشورة في محادثات الشعب: انظر <a href=\"/ar/ask/blackboard-phishing\">أحدهم نشر رابطًا في محادثة شعبتي في بلاك بورد</a>.</p>\n<h2>على جوالك</h2>\n<p>تطبيق الجامعة، «الجامعة الإسلامية بالمدينة المنورة»، متاح في App Store وGoogle Play. ادخل برقمك الجامعي وكلمة المرور. ويعرض جدولك وغيابك ومعدلك وسجلك الأكاديمي وبطاقتك الجامعية. وإن لم يظهر لك مقرر في التطبيق فراجع النظام الأكاديمي في الموقع، فهو يعرض كل المقررات.</p>\n<h2>حين يتعطل شيء</h2>\n<table><thead><tr><th>المشكلة</th><th>بمن تتصل</th></tr></thead><tbody>\n<tr><td>كلمة المرور والدخول</td><td><strong>it.care@iu.edu.sa</strong>، أو عمادة تقنية المعلومات والتعلم الإلكتروني على <strong>+966 14 847 1856</strong></td></tr>\n<tr><td>بلاك بورد</td><td><strong>bb@iu.edu.sa</strong>، أو طلب عبر تواصل إلى مركز التعلم الإلكتروني</td></tr>\n<tr><td>التسجيل وسجلك واسمك</td><td>عمادة القبول والتسجيل عبر تواصل، أو <strong>admission.reg@iu.edu.sa</strong></td></tr>\n<tr><td>لا تستطيع الدخول إطلاقًا</td><td>نموذج الزائر على <a href=\"https://helpdesk.iu.edu.sa/newticket_guest\">helpdesk.iu.edu.sa/newticket_guest</a></td></tr>\n<tr><td>لا تعرف الجهة المختصة بسؤالك</td><td>رعاية الطلاب على <strong>920022042</strong> أو <strong>care@iu.edu.sa</strong></td></tr>\n</tbody></table>\n<blockquote><p>نصيحة: توقفت عند شاشة؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "university-to-the-haram": {
  "titleAr": "من الجامعة إلى الحرم: حافلات الجامعة وسيارات الأجرة المشتركة وحافلات المدينة",
  "summaryAr": "كل الطرق من الجامعة الإسلامية إلى المسجد النبوي والعودة منه: حافلات الجامعة المجانية ومواعيدها، وسيارات الأجرة المشتركة بثلاثة ريالات من البوابة ٤، وخط حافلات المدينة ١٥٠، وتطبيقات التوصيل، والعودة بعد العشاء.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. يصل طلاب الجامعة الإسلامية إلى المسجد النبوي بأربع طرق. يقارن هذا الدليل بينها، ثم يشرح كل واحدة منها، لتصلي في الحرم كلما شئت دون أن تنفق كثيرًا.</p>\n<h2>الطرق الأربع في نظرة سريعة</h2>\n<table><thead><tr><th>الطريقة</th><th>التكلفة</th><th>الوقت</th><th>تناسب</th></tr></thead><tbody>\n<tr><td>حافلة الجامعة</td><td>مجانًا</td><td>من المغرب، وصباح الجمعة لصلاة الجمعة</td><td>المغرب والعشاء والجمعة، والدروس التي بينها</td></tr>\n<tr><td>سيارة الأجرة المشتركة من البوابة ٤</td><td>٣ ريالات للمقعد، نقدًا</td><td>معظم ساعات اليوم</td><td>أي صلاة، دون ترتيب مسبق</td></tr>\n<tr><td>حافلات المدينة، الخط ١٥٠</td><td>أجرة حافلات المدينة، بالبطاقة أو التطبيق</td><td>كل ١٥ دقيقة تقريبًا</td><td>النهار، إن كان المشي لا يضايقك</td></tr>\n<tr><td>تطبيق توصيل</td><td>نحو ١٠ إلى ٣٠ ريالًا للمشوار</td><td>في أي وقت</td><td>آخر الليل، والعائلات، ومن يحمل أمتعة</td></tr>\n</tbody></table>\n<h2>حافلات الجامعة</h2>\n<ul>\n<li>تسيّر الجامعة حافلات مجانية بين الجامعة والمسجد النبوي، وبين سكن الربوة والجامعة.</li>\n<li><strong>لا توجد حافلة جامعية إلى الحرم قبل المغرب.</strong> فالحافلات تعمل للمغرب والعشاء.</li>\n<li><strong>الجمعة:</strong> في الفصل الأول من عام ١٤٤٨ انطلقت حافلات الجمعة من الجامعة نحو الساعة ٩:٣٠ و١٠:٣٠ صباحًا.</li>\n<li><strong>في العودة بعد العشاء</strong> تنتظر الحافلات حتى تنتهي صلاة الجنازة، فلا داعي للاستعجال في الخروج من المسجد.</li>\n<li>تتغير نقاط الركوب والمواعيد خلال العام، فتحقق من المواعيد الحالية قبل أن تعتمد على الحافلة.</li>\n</ul>\n<h2>سيارات الأجرة المشتركة من البوابة ٤</h2>\n<ul>\n<li>تنتظر السيارات خارج البوابة ٤ وتنقل الطلاب إلى باب السلام مقابل <strong>٣ ريالات للمقعد</strong>.</li>\n<li>تعمل معظم ساعات اليوم.</li>\n<li>الدفع نقدًا، فاحمل معك أوراقًا نقدية صغيرة وعملات معدنية.</li>\n</ul>\n<h2>حافلات المدينة: الخط ١٥٠</h2>\n<ol>\n<li>امشِ إلى محطة <strong>جامعة طيبة ب</strong>، على بعد نحو ٧٥٠ مترًا أو ١١ دقيقة مشيًا من الجامعة الإسلامية.</li>\n<li>اركب الخط ١٥٠ باتجاه مذينب. تمر الحافلات كل ١٥ دقيقة تقريبًا.</li>\n<li>انزل في محطة نفق المناخة، بعد نحو ٢٨ دقيقة.</li>\n<li>امشِ نحو كيلومتر واحد إلى المسجد النبوي.</li>\n</ol>\n<ul>\n<li>تقف حافلات المدينة أيضًا خارج البوابة ٥. فتحقق من الخط في تطبيق حافلات المدينة قبل أن تركب، لأن بعض الخطوط لا يكمل إلى الحرم.</li>\n<li>لا يُقبل النقد داخل الحافلة: ادفع بالبطاقة أو بالجوال أو بتطبيق حافلات المدينة. والأجرة والاشتراكات والتطبيق في <a href=\"/ar/guides/haramain-train-and-city-buses\">قطار الحرمين وحافلات المدينة</a>.</li>\n</ul>\n<h2>تطبيقات التوصيل</h2>\n<p>بولت وكريم وجيني وأوبر تعمل كلها بين الجامعة والحرم. وتوقّع نحو ١٠ إلى ٣٠ ريالًا، وأكثر من ذلك بعد الصلوات في الحرم مباشرة، وأكثر ما يكون بعد الجمعة، حين ترتفع الأسعار. والمزيد في <a href=\"/ar/guides/getting-around\">التنقل في المدينة، وإلى مكة</a>.</p>\n<h2>العودة ليلًا</h2>\n<ul>\n<li>بعد العشاء اركب حافلة الجامعة، فهي تنتظر حتى تنتهي صلاة الجنازة.</li>\n<li>إن فاتتك، فتطبيق التوصيل أيسر طريق للعودة. والسيارة التي تتقاسمها مع أصحابك لا تكلف كل واحد منكم إلا قليلًا.</li>\n<li>أبقِ جوالك مشحونًا، وفي تطبيق حافلات المدينة شيئًا من الرصيد، حتى لا تنقطع بك السبل.</li>\n</ul>\n<blockquote><p>نصيحة: للجمعة، بكّر في الخروج أيًّا كانت وسيلتك، فالساحات تمتلئ قبل الخطبة بوقت طويل. أول مرة تزور المسجد؟ انظر <a href=\"/ar/guides/masjid-an-nabawi-first-visit\">زيارة المسجد النبوي: دليل الزيارة الأولى</a>. وإن كنت قادمًا من المطار فانظر <a href=\"/ar/ask/airport-to-haram-and-university\">من المطار إلى الحرم أو الجامعة</a>.</p></blockquote>"
 },
 "visas-for-family-and-visitors": {
  "titleAr": "تأشيرات أفراد الأسرة والزائرين",
  "summaryAr": "التأشيرات التي يستعملها الناس لإحضار أسرهم أو للبقاء شهورًا، وخطوة البصمة في مركز التأشيرات، وتمديد تأشيرة الزيارة العائلية في أبشر برسومه وغراماته، وما تضيفه الإقامة.",
  "bodyHtmlAr": "<blockquote><p>مهم: قواعد التأشيرات تتغير كثيرًا. وكل ما هنا روجع في نوفمبر ٢٠٢٦. فتأكد على <a href=\"https://visa.mofa.gov.sa/\">visa.mofa.gov.sa</a> قبل أن تحجز شيئًا.</p></blockquote>\n<h2>البقاء على تأشيرة</h2>\n<ul>\n<li><strong>التأشيرة السياحية الإلكترونية:</strong> متاحة لمواطني عشرات الدول، ومنها بريطانيا وأمريكا وكندا ومعظم أوروبا. وأضيفت البوسنة والهرسك والمكسيك ومقدونيا الشمالية وصربيا في أوائل نوفمبر ٢٠٢٦. وتكلف نحو ٥٣٥ ريالًا إجمالًا عبر الإنترنت أو ٤٨٠ ريالًا عند الوصول في مطار دولي (تُدفع بالبطاقة في أجهزة المطار)، وتشمل تأمينًا صحيًا إلزاميًا، وهي صالحة لسنة واحدة بدخول متعدد. ويجوز لك البقاء حتى ٩٠ يومًا إجمالًا، تُحسب على مجموع دخولك. ويجب أن يكون جوازك ساريًا ستة أشهر على الأقل عند دخولك. ولا تُمدد هذه التأشيرة داخل المملكة، ولا تُصدر جديدة إلا بعد انتهاء القديمة. وتغطي العمرة بتصريح من نسك، لا الحج. راجع قواعد جوازك على <a href=\"https://visa.visitsaudi.com/\">visa.visitsaudi.com</a>، وقدّم هناك فقط، لا عبر وكلاء يضيفون رسومهم.</li>\n<li><strong>حاملو تأشيرة أمريكية أو بريطانية أو شنغن:</strong> من سبق له دخول تلك الدولة بتأشيرته الأمريكية أو البريطانية أو الشنغن، أو يقيم في أمريكا أو بريطانيا أو الاتحاد الأوروبي بتصريح إقامة ساري، يحصل على التأشيرة السياحية الإلكترونية أيًّا كانت جنسيته. ويأتي معه زوجه وأبناؤه ووالداه بالشروط نفسها، أيًّا كانت جنسياتهم كذلك. والتأشيرة عند الوصول مخصصة أساسًا لركاب شركات الطيران الوطنية السعودية، فمن يسافر على شركة أخرى يستخرج التأشيرة الإلكترونية عبر الإنترنت قبل الرحلة، وإلا عرّض نفسه لرفض صعوده إلى الطائرة.</li>\n<li><strong>تمديد تأشيرة الزيارة:</strong> يمددها المضيف (مواطن سعودي أو حامل إقامة) في أبشر ابتداءً من ٧ أيام قبل انتهائها، بـ١٠٠ ريال في كل مرة، مع تأمين طبي جديد للمدة الجديدة. ومجموع البقاء محدود بـ١٨٠ يومًا. والخطوات مذكورة أدناه.</li>\n<li><strong>تأشيرة الزيارة العائلية:</strong> يقدّم حامل الإقامة على منصة التأشيرات في وزارة الخارجية لأقاربه المقربين: الزوجة، والأبناء، والوالدين، ووالدَي الزوجة، والأجداد والجدات، والإخوة والأخوات مع أزواجهم وأولادهم، وإخوة الزوجة وأخواتها. ويجب أن يبقى على إقامة المضيف ٤ أشهر على الأقل يوم تقديم الطلب. والرسوم الحكومية ٣٠٠ ريال لدخول واحد أو ٥٠٠ ريال لدخول متعدد، إضافة إلى التأمين الطبي. وتُقرر الموافقة حالة بحالة، وأكثر أسباب الرفض شيوعًا: إقامة قاربت الانتهاء، وقريب من خارج هذه القائمة، وخطأ في إدخال أحد البيانات كرقم تأشيرة خاطئ. وقدّم قبل رمضان، فالطلبات المقدمة في موسم الحج، من ١ رمضان إلى ١ صفر، تُرفض.</li>\n<li><strong>تأشيرة العمرة:</strong> يُقدَّم لها على نسك، بعد حجز الفندق والنقل وتسجيلهما هناك أو عبر وكيل مرخص. ويجب الدخول بها خلال ٣٠ يومًا من إصدارها، وآخر يوم للدخول في موسم ١٤٤٨ هو ٢٣ مارس ٢٠٢٧. ومواعيد الموسم كاملة في <a href=\"/ar/guides/bringing-parents-to-visit\">استقدام والديك لزيارة المدينة</a>.</li>\n</ul>\n<p>على تأشيرة الزيارة تستطيع العيش هنا وحضور دورات قصيرة في مراكز اللغة. ولا يجوز لك العمل، والدراسة الجامعية تحتاج إلى تأشيرة طالب.</p>\n<h2>تأشيرة الزيارة العائلية: البصمة في مركز التأشيرات</h2>\n<p>في تأشيرة الزيارة العائلية وتأشيرة الزيارة الشخصية وتأشيرة الأعمال وتأشيرة العمل، يحضر الزائر بنفسه إلى أحد مراكز تأشير قبل إصدار التأشيرة، ويقدّم هناك بصماته وصورته. أما التأشيرة السياحية الإلكترونية وتأشيرة العمرة فلا تمران بهذه الخطوة.</p>\n<ul>\n<li>الأطفال دون السادسة لا يقدّمون بصمات.</li>\n<li>يصلح أي مركز من مراكز تأشير في العالم. وفي الطلب الإلكتروني، اكتب عاصمة الدولة التي سيسلّم فيها الزائر ملفه بوصفها مكان المعالجة.</li>\n<li>يمكن أن يستلم الجواز شخص آخر بتفويض موقّع والإيصال، أو أن يُعاد بالبريد السريع.</li>\n</ul>\n<p>يأخذ الزائر معه إلى مركز التأشيرات:</p>\n<ul>\n<li>أصل الجواز، ساريًا ستة أشهر على الأقل، وفيه صفحتان فارغتان متجاورتان؛</li>\n<li>صورة مقاس ٥١ × ٥١ ملم بخلفية بيضاء، ملتقطة خلال الأشهر الثلاثة الأخيرة؛</li>\n<li>الموافقة الصادرة من منصة التأشيرات في وزارة الخارجية؛</li>\n<li>ما يثبت صلة القرابة، كعقد الزواج أو شهادة ميلاد الطفل التي تذكر الوالدين كليهما؛</li>\n<li>نسخة من إقامة المضيف؛</li>\n<li>وللزائر المقيم خارج بلده، نسخة من تصريح إقامته هناك.</li>\n</ul>\n<h2>تمديد تأشيرة الزيارة العائلية في أبشر</h2>\n<p>يمدد المضيف التأشيرة في أبشر، ويبقى الزائر داخل البلد. ابدأ قبل انتهائها بأسبوع.</p>\n<ol>\n<li><strong>اشترِ تأمينًا صحيًا جديدًا</strong> للمدة الإضافية أولًا، فأبشر يرفض التمديد بدونه. ومواقع شركات التأمين تجد الزائر برقم التأشيرة ورقم الجواز، ثم تطلب رقم الحدود وتاريخ انتهاء التأشيرة، وكلاهما يظهر في أبشر.</li>\n<li><strong>ادفع رسوم التمديد ١٠٠ ريال</strong> عبر سداد في تطبيق بنكك: «سداد» أو «المدفوعات»، ثم «المدفوعات الحكومية»، ثم «الجوازات»، ثم خدمة «تمديد تأشيرة زيارة». وأدخل رقم حدود الزائر، لا رقم إقامتك أنت، واحتفظ بصورة للشاشة من الإيصال. أما التأمين فيُدفع على حدة.</li>\n<li><strong>ابتداءً من ٧ أيام قبل انتهاء التأشيرة،</strong> ادخل إلى absher.sa من حاسوب وافتح <strong>خدماتي</strong>، ثم <strong>الجوازات</strong>، ثم <strong>خدمات الزائرين</strong>.</li>\n<li><strong>اختر الزائر،</strong> واضغط «بدء الخدمة»، وراجع البيانات، واضغط «التالي»، ثم وافق على الشروط وأكّد.</li>\n<li><strong>تحقق من تاريخ الانتهاء الجديد</strong> بفتح بيانات الزائر مرة أخرى، قبل أن يمر التاريخ القديم.</li>\n</ol>\n<table><thead><tr><th>متى تقدّم</th><th>ما تدفعه (ريال)</th></tr></thead><tbody>\n<tr><td>من ٧ أيام قبل الانتهاء إلى تاريخ الانتهاء</td><td>١٠٠</td></tr>\n<tr><td>في الأيام الثلاثة التي تلي الانتهاء</td><td>١٠٠، إضافة إلى غرامة ٥٠٠</td></tr>\n</tbody></table>\n<p>مجموع البقاء مع كل التمديدات ١٨٠ يومًا على الأكثر. والتأشيرة السياحية الإلكترونية لا تُمدد أصلًا. ولا يعرض أبشر هل وصلت الرسوم: فإن ظهرت رسالة بتعذّر التمديد لعدم كفاية الرصيد، فمعناها أن الدفعة لم تصله. تأكد أنك دفعت برقم حدود الزائر، ثم أعد المحاولة. ولمعرفة رقم حدود الزائر أو الاستعلام عن تأشيرة دون تسجيل الدخول، انظر <a href=\"/ar/guides/check-visa-and-iqama-online\">الاستعلام إلكترونيًا عن تأشيرتك ورقم الحدود والتأمين والمخالفات</a>.</p>\n<h2>نقل الأبناء من تأشيرة الزيارة إلى الإقامة</h2>\n<p>إذا كان الوالدان كلاهما يحملان إقامة، أمكن نقل الأبناء دون ١٨ عامًا القادمين بتأشيرة زيارة عائلية إلى إقامات دون مغادرة البلد. ويُنجز ذلك في مكتب الجوازات بالمدينة المسجَّل فيها كفيل الأب، بموعد محجوز في أبشر تحت «خدمات المقيمين».</p>\n<ul>\n<li>شهادة ميلاد كل طفل وعقد زواج الوالدين، مصدقة من السفارة السعودية ووزارة الخارجية.</li>\n<li>جوازات الأطفال الأصلية، وصورة شخصية بمقاس الجواز لكل طفل.</li>\n<li>نسخ من إقامتَي الوالدين وجوازيهما.</li>\n<li>خطاب من كفيل الأب يطلب فيه من الجوازات نقل الأطفال من تأشيرة الزيارة إلى الإقامة. وإن كان الكفيل صاحب عمل خاصًا فعلى خطابه ختم الشركة وختم الغرفة التجارية.</li>\n<li>نموذج طلب التأشيرة، وتجده في الجوازات، وتعهد موقّع بتحويل تأشيرة الزيارة إلى إقامة. وفي المدينة يكفي نموذج واحد لجميع الأطفال.</li>\n</ul>\n<p>ادفع رسوم التابعين عن كل طفل حتى تاريخ انتهاء إقامة الأب، وسلّم الملف عند الشباك، فتلغي الجوازات تأشيرة الزيارة في جواز الطفل. وبعد الموافقة تظهر إقامات الأطفال في أبشر خلال ٢ إلى ٥ أيام عمل. وإن كانت إقامة الأب طلابية فالجامعة كفيله، فاسأل إدارة السفر عبر تواصل عما تحتاج إليه قبل أن تحجز الموعد.</p>\n<h2>ما تضيفه الإقامة</h2>\n<ul>\n<li>رخصة قيادة سعودية وسيارة باسمك.</li>\n<li>استقدام زوجتك وأبنائك على تأشيرات التابعين.</li>\n<li>إقامة طويلة دون الحاجة إلى الخروج والدخول لتجديد التأشيرة.</li>\n</ul>\n<p>عقد الإيجار المسجل في إيجار متاح لحاملي الإقامة وللطلاب على التأشيرة التعليمية، ويسجله لهم وسيط معتمد. انظر <a href=\"/ar/guides/finding-an-apartment\">البحث عن شقة واستئجارها</a>.</p>\n<p>العمل هو الطريق المعتاد إلى الإقامة. والإقامة المميزة طريق آخر: نحو ١٠٠٬٠٠٠ ريال في السنة، أو ٨٠٠٬٠٠٠ ريال مرة واحدة للإقامة الدائمة. وهناك خمسة منتجات أخرى للإقامة المميزة، للكفاءات المهنية والموهوبين والمستثمرين ورواد الأعمال وملاك العقار، لكل منها شروطه.</p>\n<h2>أسر طلاب الجامعة</h2>\n<p>تأشيرات الزوجة والأسرة للطلاب تمر عبر الجامعة وإجراءاتها الخاصة، وتختلف القواعد بين الطلاب حاملي الإقامة والطلاب على التأشيرة التعليمية بهوية زائر. فاسأل عمادة شؤون الطلاب أو أرسل طلبًا عبر تواصل قبل أن تخطط، وراسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a> إن احتجت عونًا في الوصول إلى المكتب الصحيح.</p>\n<blockquote><p>نصيحة: تعال على تأشيرة بضعة أشهر أولًا، وتعرّف على المدينة، ثم أنفق على الإقامة بعد ذلك.</p></blockquote>"
 },
 "visiting-the-quran-printing-complex": {
  "titleAr": "زيارة مجمع الملك فهد لطباعة المصحف الشريف",
  "summaryAr": "كيف تحجز زيارة مجانية للمجمع الذي يطبع مصحف المدينة النبوية، مع مواعيد الزيارة، وطريق الوصول، وتطبيقاته وخطوطه للدراسة، وشراء المصاحف لإرسالها إلى بلدك.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. مجمع الملك فهد لطباعة المصحف الشريف هو المكان الذي يُطبع فيه مصحف المدينة النبوية، وهو يرحب بالزوار. والدخول مجاني: تحجز موعدًا عبر الإنترنت، وتمر بمراحل إنتاج المصحف، وتخرج بنسخة هدية. ويصدر المجمع كذلك نسخًا رقمية من المصحف وترجمات وتلاوات نافعة في الدراسة.</p>\n<h2>ما هو المجمع</h2>\n<p>افتُتح المجمع عام ١٤٠٥هـ (١٩٨٤م). ويطبع مصحف المدينة النبوية برواية حفص، وطبعات بروايات أخرى مثل ورش وقالون، وترجمات معاني القرآن الكريم بأكثر من ٧٠ لغة، وكتبًا في علوم القرآن. ويسجل القرآن كاملًا بأصوات قرائه المعتمدين في استوديو خاص به. وموقعه <a href=\"https://qurancomplex.gov.sa/en/\">qurancomplex.gov.sa</a> متاح بالعربية والإنجليزية.</p>\n<h2>حجز الزيارة</h2>\n<p>الزيارة بموعد مسبق يُحجز عبر خدمة الحجز التابعة للمجمع.</p>\n<ol>\n<li>افتح <a href=\"https://visit.qurancomplex.gov.sa/\">visit.qurancomplex.gov.sa</a>، أو تطبيق المجمع للآيفون <strong>زيارة مطبعة المصحف بالمدينة</strong> (Visit Quran Press in Madinah).</li>\n<li>أنشئ حسابًا أو سجّل الدخول.</li>\n<li>اختر اليوم والوقت ضمن مواعيد الزيارة أدناه.</li>\n<li>احتفظ بالتأكيد في جوالك، واحضر قبل موعدك بقليل.</li>\n</ol>\n<p>للاستفسار عن زيارة عائلية أو زيارة مجموعة، اتصل بالمجمع على الرقم +966 14 861 5600.</p>\n<h2>مواعيد الزيارة</h2>\n<table><thead><tr><th>اليوم</th><th>الفترة الصباحية</th><th>بعد الظهر والمساء</th></tr></thead><tbody>\n<tr><td>من الأحد إلى الخميس</td><td>من ٧ صباحًا إلى ١٢ ظهرًا</td><td>من ٢ ظهرًا إلى ٧ مساءً</td></tr>\n<tr><td>الجمعة</td><td>مغلق</td><td>من ٣ عصرًا إلى ٧ مساءً</td></tr>\n<tr><td>السبت</td><td>من ٨ صباحًا إلى ١٢ ظهرًا</td><td>من ٣ عصرًا إلى ٧ مساءً</td></tr>\n</tbody></table>\n<blockquote><p>ملاحظة: لرمضان وموسم الحج مواعيد خاصة. ويعلنها المجمع قبل كل موسم، ومن ذلك عبر حسابه في منصة إكس @qurancomplex.</p></blockquote>\n<h2>يوم الزيارة</h2>\n<ul>\n<li><strong>ما تشاهده:</strong> تتبع الزيارة صناعة المصحف، من الطباعة إلى المراجعة والتدقيق اللذين تمر بهما كل نسخة قبل أن تخرج من المجمع.</li>\n<li><strong>الهدية:</strong> في نهاية الزيارة يتسلم كل زائر نسخة من المصحف، أو ترجمة لمعانيه، هدية.</li>\n<li><strong>اللباس:</strong> البس كما تلبس للمسجد.</li>\n<li><strong>التصوير:</strong> استأذن الموظفين قبل التصوير أو تسجيل الفيديو.</li>\n<li><strong>الصلاة:</strong> في المجمع مسجد خاص به.</li>\n</ul>\n<blockquote><p>نصيحة: الزيارة نزهة مناسبة لحلقة أو فصل دراسي أو لوالدين قدما من بلدك. ولترتيب إقامتهما انظر <a href=\"/ar/guides/bringing-parents-to-visit\">استقدام والديك لزيارة المدينة: التأشيرات، والحرم مع الوالدين الكبيرين، والعمرة، ومدة البقاء</a>.</p></blockquote>\n<h2>الوصول إلى المجمع</h2>\n<p>يقع المجمع على طريق تبوك في حي النخيل، في الجهة الشمالية الغربية من المدينة، على بعد نحو ١٠ كم بالطريق من المسجد النبوي. ابحث عن اسمه العربي في تطبيق الخرائط.</p>\n<ul>\n<li><strong>تطبيقات التوصيل:</strong> بولت وكريم وجيني وأوبر كلها تصل إليه. واحجز رحلة العودة بعد خروجك من الزيارة.</li>\n<li><strong>بالسيارة:</strong> اسلك طريق تبوك باتجاه الشمال الغربي خارج المدينة.</li>\n</ul>\n<p>الأجرة وطرق التنقل الأخرى في المدينة تجدها في <a href=\"/ar/guides/getting-around\">التنقل في المدينة، وإلى مكة</a>.</p>\n<h2>النسخ الرقمية للدراسة</h2>\n<p>يصدر المجمع مصحفه وأعماله الأخرى بصيغة رقمية. حمّل كل واحد منها من مواقع المجمع نفسه أو من صفحته في متجر التطبيقات.</p>\n<table><thead><tr><th>المورد</th><th>ما يقدمه</th><th>أين تجده</th></tr></thead><tbody>\n<tr><td>تطبيقات المصحف</td><td>مصحف المدينة النبوية صفحة صفحة بدقة عالية: <strong>Quran Hafs by KFGQPC</strong> (ويظهر في بعض المتاجر باسم <strong>Quran Madina</strong>) للآيفون والأندرويد والماك وويندوز، وطبعة برواية ورش</td><td><a href=\"https://qurancomplex.gov.sa/en/apps/\">qurancomplex.gov.sa/en/apps</a></td></tr>\n<tr><td>مصحف المدينة النبوية للنشر الحاسوبي</td><td>ينسخ الآيات بالسورة أو الصفحة أو الآية أو الكلمة إلى مستنداتك بالرسم العثماني، جاهزة للبحوث والمذكرات</td><td><a href=\"https://nashr.qurancomplex.gov.sa/en/\">nashr.qurancomplex.gov.sa</a></td></tr>\n<tr><td>نشر مكتبي</td><td>ملف واحد يعمل دون تثبيت. اختر الآية من عرض الصفحة وانسخها إلى أي برنامج</td><td><a href=\"https://nashrmaktabi.qurancomplex.gov.sa/en/\">nashrmaktabi.qurancomplex.gov.sa</a></td></tr>\n<tr><td>خطوط المصحف</td><td>خطوط الرسم العثماني لمصحف المدينة النبوية برواية حفص والروايات الأخرى، مثل KFGQPC Uthmanic Script HAFS</td><td>موقع المجمع</td></tr>\n<tr><td>ترجمات المعاني</td><td>ترجمات المجمع لغة لغة، مع اسم مترجم كل منها</td><td><a href=\"https://qurancomplex.gov.sa/en/kfgqpc-quran-translate/\">qurancomplex.gov.sa، الترجمات</a></td></tr>\n<tr><td>التلاوات</td><td>المصحف كاملًا بأصوات قراء المجمع المعتمدين، للاستماع المباشر سورةً سورة أو للتحميل</td><td><a href=\"https://audio.qurancomplex.gov.sa/site/\">audio.qurancomplex.gov.sa</a></td></tr>\n<tr><td>الجولة الافتراضية</td><td>جولة في المجمع بالواقع الافتراضي، مناسبة للأهل في بلدك</td><td><a href=\"https://my.gov.sa/en/services/483656\">my.gov.sa</a></td></tr>\n</tbody></table>\n<p>لتعلم التلاوة على يد معلم انظر <a href=\"/ar/ask/learn-tajweed-in-madinah\">أين أتعلم التجويد في المدينة؟</a></p>\n<h2>شراء المصاحف وإرسالها إلى بلدك</h2>\n<p>يبيع المجمع إصداراته، ومنها المصاحف برواية حفص والروايات الأخرى، والترجمات، وكتب علوم القرآن، في مركز خدمات المصحف الشريف على طريق تبوك. والإصدارات المتاحة للبيع مدرجة في الموقع تحت <a href=\"https://qurancomplex.gov.sa/kfgqpc-pub-sales/\">الإصدارات المعروضة للبيع</a>.</p>\n<ol>\n<li>راسل فريق المبيعات على واتساب على الرقم +966 53 724 1277 بالإصدارات والكميات التي تريدها، وتأكد من توفرها ومن موعد الاستلام.</li>\n<li>ادفع قيمة الطلب قبل استلامه، نقدًا أو بوسيلة دفع أخرى يقبلها المركز.</li>\n<li>استلم طلبك من المركز.</li>\n</ol>\n<p>المركز لا يرسل الطلبات بالبريد. ولإرسال المصاحف إلى خارج المملكة رتّب الشحن بنفسك مع شركة شحن، فالمركز لا يتحمل مسؤولية التلف أو الضياع في الطريق. وشركات الشحن والتغليف مشروحة في <a href=\"/ar/guides/shipping-and-receiving-parcels\">إرسال الطرود واستقبالها في المدينة: عنوانك والجمارك وشركات الشحن والصناديق إلى بلدك</a>.</p>\n<h2>أماكن أخرى للزيارة</h2>\n<p>مساجد المدينة ومواقع غزواتها وآبارها تجدها في <a href=\"/ar/guides/historic-sites-and-masjids\">المواقع التاريخية والمساجد في المدينة</a>، والنزهات الأطول في <a href=\"/ar/guides/day-trips-from-madinah\">رحلات اليوم الواحد وعطلات نهاية الأسبوع خارج المدينة</a>. ولقضاء عصر مع الأطفال الصغار انظر <a href=\"/ar/guides/kids-activities\">أماكن اللعب والترفيه للأطفال في المدينة</a>.</p>"
 },
 "volunteering-as-a-student": {
  "titleAr": "التطوع للطالب: الأندية وسجل الساعات ومواسم السنة",
  "summaryAr": "كيف يعمل التطوع في الجامعة الإسلامية: أندية العمادة ونادي عطاء، وأين تُسجل الساعات (المنصة الوطنية للعمل التطوعي والسجل المهاري في الجامعة)، وكيف تنضم إلى فرصة، وقاعدة الحضور، وأنواع العمل، ومواسم السنة المزدحمة.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. التطوع من أسهل الطرق للتعرف إلى طلاب من كليات أخرى، ولتعلّم كيف تدير الجامعة فعالياتها الكبيرة، ولتغادر المدينة بسجل ساعات وسيرة ذاتية أقوى. وهو مفتوح لكل طالب، والإعلانات تُنشر بالعربية، والعمل يتلاءم مع المحاضرات. ويغطي هذا الدليل كيف يعمل التطوع، وأين تُسجل الساعات، ومتى تأتي المواسم المزدحمة.</p>\n<h2>من يتولاه</h2>\n<ul>\n<li><strong>عمادة شؤون الطلاب</strong> تتولى الأندية الطلابية. ولكل نادٍ رئيس ونائب وأعضاء، وإعلانات التطوع تأتي من الأندية ومن العمادة.</li>\n<li><strong>نادي عطاء التطوعي</strong> نادٍ للتطوع في الجامعة. ينشر طلبات المتطوعين ويدير مجموعات التسجيل لكل فعالية. ومن ١٤٤٨ ينشر الفرص كل أسبوع.</li>\n<li><strong>الإدارة العامة لخدمة المجتمع</strong> تتولى برامج الجامعة المجتمعية، وتحتفي باليوم العالمي للتطوع في ٥ ديسمبر، حين تشكر متطوعي السنة.</li>\n</ul>\n<h2>أين تُسجل ساعاتك</h2>\n<table><thead><tr><th>السجل</th><th>ما يحفظه</th><th>أين</th></tr></thead><tbody>\n<tr><td>المنصة الوطنية للعمل التطوعي</td><td>ساعات تطوعك الرسمية. لكل فرصة صفحتها، تسجل فيها، ويعتمد المنظم الساعات بعد الفعالية</td><td><a href=\"https://nvg.gov.sa/\">nvg.gov.sa</a></td></tr>\n<tr><td>السجل المهاري في الجامعة</td><td>برامج الأندية وفعالياتها وشهاداتها. ومنذ ١٤٤٨ هو المكان الرسمي الذي تُعلن فيه فعاليات الأندية ويُسجل فيها ويُحضر وتُصدر شهاداتها</td><td><a href=\"https://services.iu.edu.sa/student-skill-record/Programs\">services.iu.edu.sa، السجل المهاري للطالب</a></td></tr>\n</tbody></table>\n<p>برامج الأندية وفعالياتها وشهاداتها في السجل المهاري، وساعات كل فرصة تطوعية في المنصة الوطنية. والمزيد في <a href=\"/ar/ask/skills-record\">ما السجل المهاري في الجامعة؟</a></p>\n<h2>كيف تنضم إلى فرصة</h2>\n<ol>\n<li><strong>سجّل في المنصة الوطنية</strong> على nvg.gov.sa مرة واحدة، وفي السجل المهاري في الجامعة، قبل بداية الموسم.</li>\n<li><strong>انضم إلى مجموعة إعلانات النادي.</strong> اطلب رابط نادي عطاء من عمادة شؤون الطلاب أو من أي عضو في النادي في بداية السنة.</li>\n<li><strong>تابع الإعلانات.</strong> كل إعلان يذكر الفعالية وعدد المقاعد ورابط مجموعة واتساب لتنظيم تلك الفعالية. والمقاعد قليلة، من ستة إلى أربعين، والأسبق أحق.</li>\n<li><strong>لا تسجل إلا إن كنت متأكدًا من الحضور.</strong> الساعات لا تُعتمد إلا لمن حضر وعمل. ومن سجّل ولم يحضر يُحذف من المجموعة ولا ساعات له.</li>\n<li><strong>سجّل في صفحة الفرصة</strong> في المنصة الوطنية. والرابط واسم الفعالية الدقيق يُرسلان داخل مجموعة التنظيم.</li>\n<li><strong>احضر في الموعد واعمل المناوبة كاملة.</strong> يعتمد المنظم ساعاتك بعد الفعالية، فتظهر في سجلك في المنصة.</li>\n</ol>\n<blockquote><p>ملاحظة: في السجل المهاري لا يُسجل الحضور إلا في أول عشر دقائق من موعد بدء الفعالية، والبرنامج يُحتسب مجتازًا حين تحضر ٧٥٪ من ساعاته على الأقل ويعتمده المنظم، وعندها فقط يُضاف إلى سجلك. فاحضر مبكرًا.</p></blockquote>\n<h2>ما العمل</h2>\n<ul>\n<li>تنظيم فعاليات الجامعة: استقبال الضيوف، والإجلاس، والإشراف على القاعات، ومساعدة الزوار من ذوي الإعاقة.</li>\n<li>تنظيم الطلاب في الأنشطة المسائية، وإدارة الحشود في البطولات الرياضية للجامعة.</li>\n<li>الأمور اللوجستية والتصوير الفوتوغرافي والمرئي.</li>\n<li>تنظيم انطلاق حافلات العمرة التي تسيّرها العمادة للطلاب في رمضان.</li>\n<li>العمل في حفل التخرج، الذي يحتاج إلى نحو أربعين متطوعًا.</li>\n<li>الأيام البيئية: غرس الأشجار ورعاية شتلات السدر في الرحلات التي تنظمها العمادة.</li>\n</ul>\n<p>المناوبات قصيرة وأكثرها خارج وقت المحاضرات: بعد المغرب إلى العشاء، أو بعد العصر، أو أمسيات في نهاية أسبوع البطولة، أو أقل من ساعة لانطلاق حافلة. وبعض الرحلات والمؤتمرات تأتي بعذر غياب رسمي عن المحاضرات التي تأخذ وقتها.</p>\n<h2>مواسم التطوع في السنة</h2>\n<table><thead><tr><th>متى</th><th>ما يحدث</th></tr></thead><tbody>\n<tr><td>من أواخر أغسطس إلى سبتمبر</td><td>تعود الأندية وتعلن برنامج السنة، وتبدأ أمسياتها. وفي ١٤٤٧ أقيمت في الخيمة الشتوية مقابل الوحدة ١٣، قرب الملعب</td></tr>\n<tr><td>منتصف نوفمبر</td><td>اليوم العالمي للتسامح واليوم العالمي للطلاب (١٦ و١٧ نوفمبر)، يُحتفى بهما معًا على مدى أمسيتين أو ثلاث، بعروض ثقافية من دول كثيرة وركن للطعام وأجنحة للأندية وكأس رياضية. والمتطوعون ينظمون الأمسيات بعد المغرب</td></tr>\n<tr><td>٥ ديسمبر</td><td>اليوم العالمي للتطوع: الجامعة تشكر متطوعيها</td></tr>\n<tr><td>١٨ ديسمبر</td><td>فعاليات اليوم العالمي للغة العربية في قاعة السلام</td></tr>\n<tr><td>الفصل الدراسي الثاني</td><td>بطولات الاتحاد الرياضي للجامعات السعودية، وأقيمت في يناير وفبراير في ١٤٤٧. والنهائيات المقامة في الجامعة تحتاج إلى منظمين ومديري حشود ومصورين واستقبال للزوار من ذوي الإعاقة، في أمسيات من ٥ إلى ١٠ مساءً</td></tr>\n<tr><td>رمضان</td><td>رحلات عمرة جماعية من الحرم الجامعي تنظمها العمادة، مع متطوعين في الحافلات.</td></tr>\n<tr><td>أي وقت في الفصل</td><td>الأيام البيئية والرحلات الترفيهية، وتنطلق من الوحدة ١٣</td></tr>\n<tr><td>قرب نهاية الفصل الدراسي الثاني</td><td>حفل التخرج وملتقى الخريجين، بعد العصر</td></tr>\n<tr><td>قبيل إجازة عيد الأضحى</td><td>الحفل الختامي لأنشطة الطلاب في السنة، في قاعة السلام</td></tr>\n</tbody></table>\n<p>الصيف وموسم الحج هادئان. وحافلات الفعاليات والرحلات تنطلق من الوحدة السكنية ١٣، ومن أمام الكليات لفعاليات قاعة السلام، عادةً قبل البدء بثلاثين إلى ستين دقيقة.</p>\n<h2>الأندية والفعاليات غير التطوع</h2>\n<p>العمادة نفسها تتولى الأندية والمحاضرات والمؤتمرات والمعارض والرحلات، وأكثرها في قاعة السلام وقاعة الملك سعود ومسرح النشاط الطلابي والقاعات الكبرى في الكليات. وفعاليات الطلاب تقدم في العادة شهادة حضور ومواصلات ووجبة وأحيانًا سحبًا على جائزة، وكل إعلان يذكر ما يشمله. وبعض الفعاليات تقبل التسجيل من قناة واحدة فقط، ممثل جنسيتك أو وحدتك السكنية أو المتطوعين، فاقرأ الإعلان وسجّل مرة واحدة. وتعقد العمادة أيضًا لقاءات مفتوحة بين عميد شؤون الطلاب والطلاب في بداية السنة.</p>\n<h2>طلاب هوية الزائر</h2>\n<p>المنصة الوطنية تسجّل دخولك بنفاذ، وحاملو هوية الزائر يفعّلونه في أسبوعهم الأول: انظر <a href=\"/ar/guides/new-student-steps\">الخطوات الأولى للطلاب الجدد</a>. وإن رفضت المنصة تسجيلك فأخبر منظم النادي قبل الفعالية، واسأل عمادة شؤون الطلاب عبر تواصل.</p>\n<p>أي مكتب يتولى الأندية والأنشطة، وكيف تكتب طلبًا، في <a href=\"/ar/guides/university-offices-and-contacts\">من تسأل في الجامعة الإسلامية</a>. والحياة في الحرم الجامعي عمومًا في <a href=\"/ar/guides/campus-life-islamic-university\">حياة الطالب في الجامعة الإسلامية</a>.</p>\n<blockquote><p>نصيحة: عندك سؤال عن التطوع لم نجب عنه؟ راسل الإدارة على واتساب على الرقم +1 234 567 9076 أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "ways-to-live-in-madinah-long-term": {
  "titleAr": "طرق العيش في المدينة على المدى الطويل",
  "summaryAr": "الطرق النظامية للعيش في المدينة سنوات، جنبًا إلى جنب: الدراسة، والعمل لدى صاحب عمل سعودي، والإقامة مرافقًا، وشركتك الخاصة، والإقامة المميزة، مع من يكفلك، وهل تلحق بك أسرتك، وهل تستطيع العمل، وكم يكلفك ذلك، وما لا تسمح به تأشيرة الزيارة أو العمرة.",
  "bodyHtmlAr": "<p>روجع في نوفمبر ٢٠٢٦. العيش في المدينة سنوات يحتاج إلى إقامة باسمك أو إلى مكان على إقامة غيرك. وهناك خمس طرق نظامية: الدراسة، والعمل لدى صاحب عمل سعودي، والإقامة مرافقًا، وشركة تملكها، والإقامة المميزة. وهذه الصفحة تقارن بينها وتدلك على تفاصيل كل طريق.</p>\n<h2>الطرق في لمحة</h2>\n<table><thead><tr><th>الطريق</th><th>لمن يناسب</th><th>من يكفلك</th><th>هل تلحق بك أسرتك؟</th><th>هل تستطيع العمل؟</th><th>التكلفة عليك</th></tr></thead><tbody>\n<tr><td><strong>المنحة الكاملة في الجامعة الإسلامية</strong></td><td>الإخوة المقيمون خارج السعودية، من ١٧ إلى ٢٥ سنة لمرحلة البكالوريوس</td><td>الجامعة</td><td>بتأشيرات الزيارة فقط. واستقدام الأسرة عن طريق الجامعة مغلق</td><td>اسأل الجامعة قبل أن تقبل أي عمل بأجر</td><td>لا شيء. فالدراسة والسكن والمكافأة الشهرية مغطاة</td></tr>\n<tr><td><strong>الدراسة وأنت مقيم أصلًا</strong></td><td>المقيمون الذين يريدون شهادة أو دراسة شرعية مع حياتهم هنا</td><td>كفيلك الحالي</td><td>كما هو على إقامتك الحالية</td><td>نعم، إذا وافق صاحب العمل على دراستك كتابةً</td><td>دراسة مجانية، بلا مكافأة ولا سكن مجاني</td></tr>\n<tr><td><strong>العمل لدى صاحب عمل سعودي</strong></td><td>كل من عنده عرض عمل</td><td>صاحب العمل</td><td>تستطيع أن تطلبهم مرافقين بعد صدور إقامتك، إذا بلغ راتبك الحد الأدنى</td><td>نعم، لدى صاحب العمل نفسه</td><td>٤٠٠ ريال شهريًا عن كل مرافق</td></tr>\n<tr><td><strong>مرافق لأحد أفراد الأسرة</strong></td><td>زوجة حامل الإقامة وأبناؤه</td><td>فرد الأسرة</td><td>عن طريق رب الأسرة نفسه</td><td>ليس بإقامة المرافق نفسها</td><td>٤٠٠ ريال شهريًا عن كل مرافق على إقامة العمل</td></tr>\n<tr><td><strong>شركتك الخاصة</strong></td><td>من عنده عملاء يدفعون ومال يغطي التكاليف السنوية</td><td>شركتك</td><td>نعم، بعد صدور إقامتك، إذا بلغ راتبك الحد الأدنى</td><td>نعم، في شركتك</td><td>رسوم التأسيس والرسوم السنوية، ومقابل مالي ٧٠٠ أو ٨٠٠ ريال شهريًا عن كل عامل أجنبي، و٤٠٠ ريال شهريًا عن كل مرافق</td></tr>\n<tr><td><strong>الإقامة المميزة</strong></td><td>من يستوفي شروط أحد منتجاتها</td><td>بلا كفيل</td><td>نعم</td><td>نعم، في القطاع الخاص، إلا المهن المقصورة على السعوديين</td><td>رسوم حكومية محددة لكل منتج</td></tr>\n</tbody></table>\n<p>للإقامة كفيل واحد في كل وقت. والانتقال من طريق إلى آخر يعني ترك الكفيل الأول، فرتّب الخطوات قبل أن تبدأ.</p>\n<h2>الدراسة</h2>\n<p><strong>الجامعة الإسلامية</strong> هي الطريق الرئيس للإخوة القادمين من الخارج. تقدّم مجانًا على «ادرس في السعودية» في فترة التقديم السنوية. والمنحة الكاملة تغطي الدراسة والسكن والمكافأة الشهرية. ويصل الطلاب الجدد على التأشيرة التعليمية ويحملون هوية زائر رقمية لا إقامة، وتُجدد التأشيرة كل سنة ما دمت تدرس. واستقدام الأسرة عن طريق الجامعة مغلق، فزوجة الطالب وأبناؤه يأتون بتأشيرات الزيارة. وطلاب المنح يلتزمون بالعودة إلى بلادهم عند انتهاء دراستهم، فالدراسة للشهادة بقاء سنوات عدة لا بقاء دائم.</p>\n<ul>\n<li>طريقة التقديم: <a href=\"/ar/guides/applying-to-the-islamic-university\">التقديم إلى الجامعة الإسلامية</a></li>\n<li>الحياة اليومية بلا إقامة: <a href=\"/ar/guides/living-on-a-visitor-id\">العيش بهوية زائر: ما يعمل وما لا يعمل</a></li>\n<li>طلاب الدفعات السابقة الذين يحملون إقامة طالب: <a href=\"/ar/ask/student-iqama-renewal\">من يجدد إقامتي الطلابية؟</a></li>\n<li>الأخوات: <a href=\"/ar/guides/sisters-studying-in-madinah\">أين تدرس الأخوات العربية والعلوم الشرعية في المدينة</a></li>\n</ul>\n<p><strong>هل تعيش هنا أصلًا؟</strong> تقدّم على المنحة الجزئية في الجامعة، وهي دراسة مجانية فقط، وتبقى على إقامتك طوال الدراسة. و<a href=\"/ar/guides/masjid-an-nabawi-institute-and-college\">معهد المسجد النبوي وكلية المسجد النبوي</a> يدرّسان الإخوة والأخوات مجانًا داخل الحرم، لكن غير السعودي يحتاج إلى إقامة سارية ليسجل، فهو مكان للدراسة بعد أن تستقر هنا لا طريق للدخول. وجامعة طيبة وغيرها في <a href=\"/ar/guides/other-universities-in-madinah\">الجامعات الأخرى في المدينة</a>.</p>\n<h2>العمل لدى صاحب عمل سعودي</h2>\n<p>العمل هو أكثر الطرق شيوعًا للحصول على إقامة. يطلب صاحب العمل تأشيرة عملك ورخصة عملك عبر قوى، منصة وزارة الموارد البشرية. وتصدر تأشيرة العمل وأنت خارج المملكة. فتدخل بها، وتُجري الفحص الطبي والبصمة هنا، ثم تستلم إقامتك. وبموجب نظام العمل يدفع صاحب العمل رسوم استقدامك وإقامتك ورخصة عملك وتجديدها.</p>\n<ul>\n<li>عقدك مسجل في قوى. فاقرأه في حسابك على قوى قبل أن تعتمد على أي وعد خارجه.</li>\n<li>بعد صدور إقامتك، وإذا بلغ راتبك المسجل الحد الأدنى لكفالة الأسرة، تستطيع طلب تأشيرات لزوجتك وأبنائك مرافقين.</li>\n<li>رسوم الإقامة والخروج والعودة والمرافقين في <a href=\"/ar/guides/iqama-and-exit-reentry-fees\">الإقامة والخروج والعودة والخروج النهائي ورسوم المرافقين: كم تكلف ومن يصدرها</a>.</li>\n</ul>\n<h2>الإقامة هنا مرافقًا</h2>\n<p>تستطيع زوجة حامل الإقامة وأبناؤه حمل إقامات مرافقين على ملفه. ويتولى رب الأسرة أوراقهم في أبشر، ويُفرض مقابل مالي قدره ٤٠٠ ريال شهريًا عن كل مرافق على إقامة العمل، يُدفع عند تجديد الإقامات. وإقامة المرافق ليست إقامة عمل. ولا يستطيع طلاب الجامعة إضافة مرافقين، لأن استقدام الأسرة عن طريق الجامعة مغلق، فزوجة الطالب وأبناؤه يأتون بتأشيرات الزيارة العائلية.</p>\n<ul>\n<li>تأشيرات الزيارة العائلية، ونقل الأبناء من تأشيرة الزيارة إلى الإقامة: <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a></li>\n<li>تجديد إقاماتهم والخروج والعودة وسائر السجلات: <a href=\"/ar/guides/family-records-on-absher\">إقامات أسرتك وسجلاتها في أبشر</a></li>\n<li>الطلاب واستقدام الأسرة المغلق في الجامعة: <a href=\"/ar/ask/istiqdam-deposit\">هل أستطيع استقدام أسرتي، وكم مبلغ التأمين؟</a></li>\n</ul>\n<h2>تأسيس شركتك الخاصة</h2>\n<p>تسجّل في وزارة الاستثمار مالكًا أجنبيًا، وتؤسس الشركة وسجلها التجاري، ثم تصدر الشركة تأشيرة عمل لك مديرًا عامًا لها. فتأتي إقامتك عن طريق شركتك، وتلحق بك أسرتك مرافقين. والرسوم السنوية والمقابل المالي تُستحق سواء ربح النشاط أم لم يربح. وإن كنت على منحة الجامعة فلا تستطيع أن تكفلك شركتك إلا بترك كفالة الجامعة.</p>\n<p>لا تدِر نشاطًا تجاريًا باسم سعودي أبدًا. فهذا هو التستر التجاري، وعقوباته تصل إلى السجن خمس سنوات، وغرامات تصل إلى ٥ ملايين ريال، وإغلاق النشاط، والترحيل مع المنع من العودة للعمل. وكل مرحلة وتكلفة وضريبة في <a href=\"/ar/guides/start-a-company-in-saudi\">أسّس شركتك الخاصة في المملكة العربية السعودية</a>.</p>\n<h2>الإقامة المميزة</h2>\n<p>الإقامة المميزة إقامة باسمك بلا كفيل، يصدرها مركز الإقامة المميزة، ويُقدَّم عليها في <a href=\"https://pr.gov.sa/\">pr.gov.sa</a>. ولها سبعة منتجات:</p>\n<ul>\n<li><strong>الكفاءة الاستثنائية:</strong> المهنيون المتخصصون وكبار القياديين.</li>\n<li><strong>الموهبة:</strong> أصحاب القدرات الاستثنائية في مجالاتهم.</li>\n<li><strong>المستثمر:</strong> من يستثمرون في الاقتصاد السعودي.</li>\n<li><strong>رائد الأعمال:</strong> مؤسسو الشركات الناشئة الممولة من جهة استثمارية معتمدة.</li>\n<li><strong>مالك العقار:</strong> تملّك عقار سكني مبني في السعودية لا تقل قيمته عن ٤ ملايين ريال، غير مرهون. ولا تُحتسب الأرض.</li>\n<li><strong>محددة المدة:</strong> إقامة قابلة للتجديد لسنة أو أكثر.</li>\n<li><strong>غير محددة المدة:</strong> إقامة دائمة.</li>\n</ul>\n<p>بالإقامة المميزة تعيش هنا مع أسرتك، وتعمل في الشركات الخاصة وتنتقل بين الوظائف (إلا المهن المقصورة على السعوديين)، وتخرج وتعود دون تأشيرة خروج وعودة. ولكل منتج شروطه ورسومه الحكومية، وكلاهما معروض على البوابة. وتستطيع التملك في المدن الأخرى. أما في المدينة ومكة فتستطيع بصفتك مسلمًا التملك داخل النطاقات المعتمدة فقط، ولا يكون لك خارجها إلا حق الانتفاع: انظر <a href=\"/ar/guides/owning-property-as-a-non-saudi\">تملّك غير السعودي مسكنًا في المدينة: الأحكام والنطاقات وطريقة التقديم</a>. وشراء مسكن عادي لا يمنح إقامة.</p>\n<h2>ما لا تسمح به تأشيرة الزيارة أو العمرة</h2>\n<ul>\n<li><strong>لا عمل.</strong> التأشيرة السياحية الإلكترونية وتأشيرة الزيارة العائلية وتأشيرة العمرة لا تسمح بأي عمل بأجر.</li>\n<li><strong>لا تحويل.</strong> لا تستطيع تحويل تأشيرة الزيارة أو السياحة أو العمرة إلى إقامة باسمك. فتأشيرة العمل تصدر وأنت في الخارج وتدخل بها. والاستثناء الوحيد للأبناء دون ١٨ سنة على تأشيرة زيارة عائلية إذا كان كلا والديهم يحمل إقامة: انظر <a href=\"/ar/guides/visas-for-family-and-visitors\">تأشيرات أفراد الأسرة والزائرين</a>.</li>\n<li><strong>مدة محدودة.</strong> تأشيرة الزيارة العائلية تبلغ ١٨٠ يومًا على الأكثر مع كل التمديدات. والتأشيرة السياحية الإلكترونية تسمح بـ ٩٠ يومًا في السنة ولا تُمدد.</li>\n</ul>\n<blockquote><p>مهم: كل من يعرض عليك تحويل تأشيرة الزيارة إلى عمل أو إقامة مقابل رسوم، أو ترتيب إقامة ضمن صفقة بيع عقار، لا يتبع الأنظمة. فلا تدفع له. وكل طريق هنا يمر عبر منصة رسمية: «ادرس في السعودية» أو قوى أو أبشر أو وزارة الاستثمار أو بوابة الإقامة المميزة.</p></blockquote>"
 },
 "what-to-bring-to-madinah": {
  "titleAr": "ماذا تحضر معك إلى المدينة: المستندات والمال والملابس والأدوية",
  "summaryAr": "قائمة للحقيبة والأوراق للطلاب والأسر قبل السفر: المستندات ونسخها، والمال والبطاقات، والقوابس والجهد الكهربائي، وملابس كل فصل، والأدوية، وما تتركه في بلدك.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. كل ما تحتاجه للحياة اليومية تقريبًا سهل الشراء في المدينة. أما المستندات والأدوية وبعض الأغراض الشخصية فليست كذلك، ولهذا تأتي أولًا. والقائمة تصلح للطلاب على التأشيرة التعليمية وللأسر القادمة على تأشيرة زيارة أو للالتحاق بحامل إقامة. وحيث يختلف الفريقان وُضعا جنبًا إلى جنب.</p>\n<h2>المستندات</h2>\n<p>احتفظ بكل أصل في حقيبة اليد، لا في الحقيبة المشحونة أبدًا.</p>\n<ol>\n<li><strong>جواز سفرك</strong>، وفيه ستة أشهر على الأقل من الصلاحية.</li>\n<li><strong>تأشيرتك.</strong> احفظ التأشيرة الإلكترونية في جوالك واطبع نسخة واحدة.</li>\n<li><strong>صور شخصية</strong> بخلفية بيضاء سادة. خذ معك عدة نسخ مطبوعة، فالمكاتب ومكتب البطاقة الجامعية تطلبها.</li>\n<li><strong>نسخ من كل شيء:</strong> مسح ضوئي واضح لكل مستند في مجلد على جوالك وفي التخزين السحابي، ونسختان ورقيتان.</li>\n<li><strong>رقم الحدود</strong>، وهو رقم الدخول المرتبط بتأشيرتك. دوّنه حين تهبط: تحتاجه للشريحة وأبشر والبنك.</li>\n</ol>\n<table><thead><tr><th>الموضوع</th><th>الطلاب على التأشيرة التعليمية</th><th>الأسر والزائرون</th></tr></thead><tbody>\n<tr><td><strong>وضعك</strong></td><td>قبولك النهائي، ورقمك الجامعي إن كان لديك، وبيانات دخولك إلى «منحتي»</td><td>تأشيرتك، سواء كانت تأشيرة سياحية إلكترونية أو زيارة عائلية أو تأشيرة مرافق</td></tr>\n<tr><td><strong>الشهادات</strong></td><td>أصل شهادتك الثانوية وكشف الدرجات، وكل مستند رفعته حين قدّمت</td><td>عقد الزواج وشهادة ميلاد كل طفل</td></tr>\n<tr><td><strong>الأطفال</strong></td><td>لا حاجة</td><td>سجلات التطعيم وآخر تقارير المدرسة، للتسجيل في مدرسة أو روضة</td></tr>\n<tr><td><strong>التغطية الصحية</strong></td><td>بيانات التأمين الطبي من طلب تأشيرتك</td><td>وثيقة التأمين المرفقة بتأشيرتك. وهي تغطي الطوارئ فقط</td></tr>\n<tr><td><strong>القيادة</strong></td><td colspan=\"2\">رخصة بلدك ورخصة قيادة دولية. والرخصة الدولية لا تُصدر إلا في بلدك، فاستخرجها قبل السفر</td></tr>\n</tbody></table>\n<blockquote><p>نصيحة: تصديق المستندات في بلدك أيسر بكثير منه من المدينة. فإن احتاجت جامعتك أو معهد أو مدرسة أطفالك إلى شهادات مصدقة فصدّقها قبل أن تغادر.</p></blockquote>\n<h2>المال والبطاقات</h2>\n<ul>\n<li>الريال السعودي مثبت عند ٣٫٧٥ ريالات للدولار الأمريكي.</li>\n<li>أحضر ما يكفيك لشهريك الأولين. ففتح الحساب البنكي واستلام أول مكافأة يأخذان وقتًا.</li>\n<li>احمل بطاقتين من بنكين مختلفين، وأخبر بنكك أنك منتقل. فالبطاقات الأجنبية يوقفها أحيانًا نظام الأمان في البنك، والبطاقة الثانية تنقذك.</li>\n<li>احتفظ ببعض النقد للأيام الأولى. حافلات المدينة لا تقبل النقد، لكن المحلات الصغيرة وبعض سيارات الأجرة تفضله.</li>\n<li>النقد والذهب والمجوهرات فوق الحد الجمركي يجب الإفصاح عنها عند وصولك. احمل ما تحتاجه لأسابيع قليلة واستعمل البطاقات للباقي.</li>\n<li>بعد أن تستقر افتح حسابًا سعوديًا. انظر <a href=\"/ar/guides/sim-internet-bank\">شريحة الجوال والإنترنت وبطاقة بنكية سعودية</a>.</li>\n</ul>\n<h2>الجوال والقوابس والكهرباء</h2>\n<ul>\n<li><strong>القوابس:</strong> من النوع G بثلاثة أسنان مستطيلة، مثل بريطانيا.</li>\n<li><strong>الكهرباء:</strong> ٢٣٠ فولتًا بتردد ٦٠ هرتز.</li>\n<li><strong>اقرأ ملصق كل شاحن.</strong> إن كان مكتوبًا عليه ١٠٠ إلى ٢٤٠ فولتًا فلا تحتاج إلا محوّل قابس. أما الأجهزة المصنوعة لجهد ١١٠ أو ١٢٠ فولتًا فقط، مثل كثير من مجففات الشعر والغلايات وماكينات الحلاقة من أمريكا الشمالية، فتحتاج محوّل جهد. والأيسر عادة شراؤها هنا.</li>\n<li><strong>المحوّلات ووصلات التمديد</strong> تباع في كل سوبرماركت ومحل إلكترونيات.</li>\n<li><strong>افتح قفل جوالك</strong> قبل السفر لتعمل فيه الشريحة السعودية. واشترِ الشريحة حين تهبط.</li>\n</ul>\n<h2>ملابس كل فصل</h2>\n<table><thead><tr><th>الأشهر</th><th>ما تحزمه</th></tr></thead><tbody>\n<tr><td>من نوفمبر إلى فبراير</td><td>نهار معتدل وليل بارد، خاصة في ساحات الحرم المكشوفة. سترة دافئة أو كنزة، وجوارب، وطبقة دافئة للفجر والعشاء.</td></tr>\n<tr><td>من مارس إلى مايو</td><td>لطيف في مارس، حار في مايو. ملابس خفيفة، وطبقة لأمسيات مارس، ووشاح للأيام المغبرة.</td></tr>\n<tr><td>من يونيو إلى سبتمبر</td><td>حار جدًا، والنهار نحو ٤٤ درجة وأكثر في أسوأ الأيام. قطن خفيف فضفاض، وصندل، وقارورة ماء تعاد تعبئتها.</td></tr>\n<tr><td>أكتوبر</td><td>حار في أوله ويبرد مع الشهر. ملابس الصيف مع طبقة أدفأ واحدة.</td></tr>\n</tbody></table>\n<ul>\n<li>الزم اللباس المحتشم دائمًا. فالمدينة أكثر محافظة من جدة والرياض.</li>\n<li><strong>الرجال:</strong> أحضر بضعة أثواب للبداية. وفي كل حي خياطون يخيطون الثوب بمئة إلى ثلاثمئة ريال في يومين إلى أربعة أيام. والثوب هو اللباس المعتاد في الحرم الجامعي وفي المحاضرات والاختبارات، وذكّرت الجامعة منسوبيها وطلابها بذلك في سبتمبر ٢٠٢٥.</li>\n<li><strong>النساء:</strong> تلبس المرأة العباءة خارج البيت. أحضري واحدة أو اثنتين للأيام الأولى. وتباع كثيرات غيرها في كل أنحاء المدينة.</li>\n<li><strong>الأحذية:</strong> اختر حذاءً يُخلع ويُلبس بسهولة. فهو يُخلع عند كل مسجد، وفي الحرم يوضع على الأرفف.</li>\n</ul>\n<p>الطقس شهرًا بشهر في <a href=\"/ar/guides/seasons-and-camping\">المدينة في فصول السنة، وأين تخيّم</a>.</p>\n<h2>الأدوية والصحة</h2>\n<ol>\n<li><strong>أحضر ما يكفي من دوائك المعتاد للأسابيع الأولى،</strong> في علبه الأصلية، في حقيبة اليد.</li>\n<li><strong>اطلب من طبيبك خطابًا</strong> يذكر كل دواء وجرعته والكمية التي تحملها. فالوصفات من البلدان الأخرى لا تُقبل هنا، وستراجع طبيبًا في المدينة لوصفة جديدة.</li>\n<li><strong>الأدوية الخاضعة للرقابة تحتاج تصريحًا قبل السفر.</strong> بعض المسكنات والمنومات وأدوية القلق والمنبهات ومضادات الاكتئاب تحتوي مواد مخدرة أو مؤثرة عقليًا. ولهذه تقدّم على تصريح المسافر من الهيئة العامة للغذاء والدواء في نظام الأدوية الخاضعة للرقابة على <a href=\"https://cds.sfda.gov.sa/\">cds.sfda.gov.sa</a>. ارفع الوصفة أو التقرير الطبي، واذكر اسم كل دواء وتركيزه وكميته، واحمل التصريح المعتمد مع الدواء.</li>\n<li><strong>النظارات:</strong> احزم نظارة احتياطية ووصفة العدسات.</li>\n<li><strong>السجلات:</strong> أحضر سجلات التطعيم لكل فرد في الأسرة، وأي تقارير طبية للحالات المزمنة.</li>\n</ol>\n<p>أين تجد الطبيب أو الصيدلية بعد وصولك: <a href=\"/ar/guides/doctors-hospitals-and-pharmacies\">الأطباء والمستشفيات والصيدليات وأرقام الطوارئ</a>.</p>\n<h2>ما تتركه في بلدك</h2>\n<ul>\n<li><strong>الخمر</strong> بكل أنواعه، ومنه زجاجات الأسواق الحرة.</li>\n<li><strong>لحم الخنزير</strong> وكل ما صُنع منه.</li>\n<li><strong>المخدرات</strong>، والأدوية الخاضعة للرقابة بغير التصريح المذكور أعلاه.</li>\n<li><strong>المواد الخادشة للحياء</strong>، وكل ما يسيء إلى الإسلام.</li>\n<li><strong>الأغراض المنزلية الثقيلة.</strong> فالأثاث وأدوات المطبخ والفرش رخيصة هنا، جديدة ومستعملة. ودع المساحة في حقيبتك لما لا تستطيع شراءه.</li>\n<li><strong>المكتبة الكبيرة.</strong> فمكتبات المدينة ودورها تحوي معظم ما ستدرسه، وستحتاج مساحة الحقيبة للكتب في طريق العودة.</li>\n</ul>\n<p>وإن حملت أغراضًا مقيدة فأفصح عنها في مكتب الجمارك في المطار حين تهبط.</p>\n<h2>قبل أن تغلق الحقيبة</h2>\n<ol>\n<li>اسمك في التذكرة والتأشيرة وكل سجل جامعي يطابق جوازك حرفًا بحرف.</li>\n<li>كل مستند ممسوح ومحفوظ في مجلد تفتحه من أي جوال.</li>\n<li>بنكك يعلم أنك مسافر، والبطاقتان تعملان في الخارج.</li>\n<li>جوالك مفتوح القفل.</li>\n<li>أدويتك محزومة مع خطاب الطبيب، ومع التصريح إن كنت تحتاجه.</li>\n<li>كل أصل في حقيبة اليد.</li>\n</ol>\n<p>ما تفعله بعد الهبوط بالترتيب: <a href=\"/ar/guides/first-30-days-in-madinah\">أيامك الثلاثون الأولى في المدينة</a>. والوصول من المطار: انظر <a href=\"/ar/ask/airport-to-haram-and-university\">كيف أصل من مطار المدينة إلى الحرم أو الجامعة؟</a></p>\n<blockquote><p>نصيحة: ينقص هذه القائمة شيء؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "what-you-study-by-level": {
  "titleAr": "ما تدرسه في كل كلية، مستوى بعد مستوى",
  "summaryAr": "مقررات الخطط الدراسية لعام ١٤٤٨ في كليات الجامعة السبع للعلوم الشرعية والعربية والأنظمة والأعمال: القرآن الكريم، والحديث الشريف، والعقيدة والدعوة، والشريعة، واللغة العربية والعلوم الإنسانية، والأعمال (الاقتصاد)، والأنظمة، مستوى بعد مستوى، بأسمائها العربية كما في النظام الأكاديمي.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. تمتد كل درجة بكالوريوس في الكليات السبع الآتية على ثمانية مستويات، مستوى في كل فصل دراسي. وفيما يلي مقررات الخطط الدراسية لعام ١٤٤٨، كلية بعد كلية، بأسمائها كما تظهر لك في النظام الأكاديمي. استعن بها لتخطط لما هو آتٍ، ولتجد كتبك في <a href=\"/ar/library#muqarrarat\">المكتبة</a>، ولتختار كليتك قبل أن تُتمّ المعهد: انظر <a href=\"/ar/guides/graduating-from-mahad\">الانتقال من المعهد إلى الكلية</a>.</p>\n<ul>\n<li><strong>خطتك أنت</strong>، برمز كل مقرر وساعاته المعتمدة ومتطلباته السابقة، تجدها في النظام الأكاديمي تحت <strong>أكاديمي</strong> ثم <strong>خطة الطالب</strong>. والخطة تختلف من دفعة إلى أخرى، فاعتمد على خطتك أنت.</li>\n<li>المقرر الذي ترسب فيه يُعاد، ويُقدَّم على المقررات المبنية عليه. انظر <a href=\"/ar/guides/registering-your-courses\">تسجيل مقرراتك</a>.</li>\n</ul>\n<blockquote><p>نصيحة: بعض المجلدات في المكتبة مرتبة على خطة دراسية سابقة، فيقع المقرر فيها أحيانًا قبل مستواه في خطتك أو بعده بمستوى أو مستويين. ابحث في المكتبة باسم المقرر بالعربية تجده حيثما كان موضعه.</p></blockquote>\n<h2>نظرة سريعة</h2>\n<table><thead><tr><th>الكلية</th><th>عدد مقررات الدرجة</th><th>ملامح الدرجة</th></tr></thead><tbody>\n<tr><td>القرآن الكريم والدراسات الإسلامية</td><td>٦٥</td><td>القراءات والتفسير من المستوى الأول. ولا مقررات للحفظ، فأنت تلتحق بالكلية حافظًا للقرآن كله</td></tr>\n<tr><td>الحديث الشريف والدراسات الإسلامية</td><td>٧٣</td><td>مقرر في القرآن الكريم في كل مستوى، وعلوم الحديث تُبنى خطوة بعد خطوة من المستوى الأول</td></tr>\n<tr><td>العقيدة والدعوة</td><td>٧٨</td><td>سنة أولى مشتركة، ثم التوحيد في كل مستوى مع الفرق والأديان والدعوة</td></tr>\n<tr><td>الشريعة</td><td>٨٧</td><td>الفقه وأصوله إلى جانب الأنظمة السعودية من المستوى الأول</td></tr>\n<tr><td>اللغة العربية والعلوم الإنسانية</td><td>٨٠</td><td>سنة أولى مشتركة، ثم النحو والصرف والبلاغة والأدب وعلم اللغة والإعلام</td></tr>\n<tr><td>الأعمال: الاقتصاد</td><td>٦٥</td><td>سنة أولى مشتركة، ثم الاقتصاد والتمويل مع فقه المعاملات</td></tr>\n<tr><td>الأنظمة والدراسات القضائية</td><td>٦٦</td><td>الأنظمة السعودية والفقه من المستوى الأول، وأصول الفقه من المستوى الثاني، مع ثلاثة مقررات اختيارية</td></tr>\n</tbody></table>\n<h2>كلية القرآن الكريم والدراسات الإسلامية</h2>\n<p>تبدأ مواد التخصص من فصلك الأول. فالقراءات السبع تمتد من المستوى الأول إلى السادس، والقراءات الثلاث في المستويين السابع والثامن. ويتدرج التفسير من مدخل في المستوى الأول إلى خمسة مستويات من التفسير التحليلي، ويأتي رسم المصحف وضبطه في المستويات من الخامس إلى السابع. ولا مقررات لحفظ القرآن، لأنك تلتحق بالكلية حافظًا له كله. الكتب: <a href=\"/ar/library/quran\">قسم القرآن الكريم في المكتبة</a>.</p>\n<table><thead><tr><th>المستوى</th><th>المقررات</th></tr></thead><tbody>\n<tr><td>١</td><td>القراءات السبع ١، توحيد ١، الفقه ١، التجويد، المدخل إلى الحديث النبوي، مدخل إلى علم القراءات، المدخل إلى علم التفسير، السيرة النبوية</td></tr>\n<tr><td>٢</td><td>القراءات السبع ٢، توحيد ٢، الفقه ٢، علوم القرآن ١، النحو ١، مقدمة في مصطلح الحديث، علم التجويد والأصوات، القيم الإسلامية</td></tr>\n<tr><td>٣</td><td>القراءات السبع ٣، توحيد ٣، المهارات اللغوية، علوم القرآن ٢، أخلاقيات حملة القرآن، التفسير التحليلي ١، أصول التفسير، حديث تحليلي</td></tr>\n<tr><td>٤</td><td>القراءات السبع ٤، توحيد ٤، عد الآي، أصول الفقه، النحو ٢، التفسير التحليلي ٢، مناهج المفسرين</td></tr>\n<tr><td>٥</td><td>القراءات السبع ٥، رسم المصحف ١، توجيه القراءات، قواعد التفسير، النحو ٣، التفسير التحليلي ٣، أصول الدعوة وطرقها، تاريخ المملكة</td></tr>\n<tr><td>٦</td><td>القراءات السبع ٦، رسم المصحف ٢، التقنيات الحديثة في الدراسات القرآنية، أحاديث الأحكام: عبادات، الأديان، التفسير التحليلي ٤، البلاغة، الفرائض، مناهج البحث</td></tr>\n<tr><td>٧</td><td>القراءات الثلاث ١، المذاهب والتيارات المعاصرة، مهارات أدائية، ضبط المصحف، الصرف، التفسير التحليلي ٥، البحث العلمي في الدراسات القرآنية، تدريب تعاوني: فسر، الفرق</td></tr>\n<tr><td>٨</td><td>القراءات الثلاث ٢، التفسير الموضوعي، إعجاز القرآن، التخريج، مهارات تفسيرية، الانتصار للقرآن، البلاغة القرآنية، تدريب تعاوني: قرأ</td></tr>\n</tbody></table>\n<h2>كلية الحديث الشريف والدراسات الإسلامية</h2>\n<p>تدرس مقررًا في القرآن الكريم في كل مستوى، من الأول إلى الثامن. وتُبنى علوم الحديث خطوة بعد خطوة: المدخل وتاريخ السنة في المستوى الأول، والحديث التحليلي من المستوى الثاني، والمصطلح من المستوى الثالث، والرواة والجرح والتعديل من المستوى الثالث إلى السادس، وكتب السنة من المستوى الرابع، والتخريج في المستويين السادس والسابع. وتُختم الدرجة بقاعتَي بحث وتدريب تعاوني. الكتب: <a href=\"/ar/library/hadith\">قسم الحديث في المكتبة</a>.</p>\n<table><thead><tr><th>المستوى</th><th>المقررات</th></tr></thead><tbody>\n<tr><td>١</td><td>القرآن الكريم ١، توحيد ١، الفقه ١، تاريخ السنة النبوية، المهارات اللغوية، السيرة النبوية، المدخل إلى الحديث النبوي، المدخل لدراسة الفقه، التجويد</td></tr>\n<tr><td>٢</td><td>القرآن الكريم ٢، توحيد ٢، الفقه ٢، النحو ١، حديث تحليلي ١، أصول الدعوة وطرقها، المقدمة في مصطلح الحديث، مدخل إلى تفسير القرآن وعلومه</td></tr>\n<tr><td>٣</td><td>القرآن الكريم ٣، توحيد ٣، رواة الحديث ١، النحو ٢، حديث تحليلي ٢، أصول الفقه ١، مصطلح الحديث ١، تاريخ المملكة</td></tr>\n<tr><td>٤</td><td>القرآن الكريم ٤، قيم إسلامية، رواة الحديث ٢، مناهج المحدثين في التصنيف، حديث تحليلي ٣، أصول الفقه ٢، مصطلح الحديث ٢، التفسير ١، كتب سنة ١، تطبيقات الذكاء الاصطناعي</td></tr>\n<tr><td>٥</td><td>القرآن الكريم ٥، توحيد ٤، الجرح والتعديل ١، النحو ٣، حديث تحليلي ٤، مكانة السنة النبوية، مصطلح الحديث ٣، القواعد الفقهية، كتب سنة ٢</td></tr>\n<tr><td>٦</td><td>القرآن الكريم ٦، تخريج الحديث ١، الجرح والتعديل ٢، مناهج البحث، حديث تحليلي ٥، المذاهب والتيارات المعاصرة، مصطلح الحديث ٤، التفسير ٢، كتب سنة ٣</td></tr>\n<tr><td>٧</td><td>القرآن الكريم ٧، تخريج الحديث ٢، الحديث الموضوعي، الفرق، حديث تحليلي ٦، الأديان، مصطلح الحديث ٥، التفسير ٣، كتب سنة ٤، قاعة بحث فقه السنة</td></tr>\n<tr><td>٨</td><td>القرآن الكريم ٨، أصول دراسة الأسانيد، التقانة في خدمة السنة النبوية، قاعة بحث علوم الحديث، الدلائل والشمائل النبوية، التدريب التعاوني، البلاغة، التفسير ٤، كتب سنة ٥، الفرائض</td></tr>\n</tbody></table>\n<h3>ما الذي تغيّر في خطة الحديث</h3>\n<p>تضيف خطة ١٤٤٨ مقرر «تطبيقات الذكاء الاصطناعي» في المستوى الرابع. وفي خطة ١٤٤٦ نقلت الكلية «تاريخ السنة النبوية» إلى المستوى الأول، وقدّمت «حديث تحليلي» مستوى واحدًا (إلى المستوى الثاني بدل الثالث)، وأضافت «التدريب التعاوني» في المستوى الثامن، وحذفت «مهارات جامعية» و«دراسة الأنظمة» و«الابتكار». وخطة الطالب في النظام الأكاديمي تبين لك الخطة التي تسير عليها.</p>\n<h2>السنة الأولى المشتركة: العقيدة والدعوة، واللغة العربية، والأعمال</h2>\n<p>تشترك هذه الكليات الثلاث في المستويين الأول والثاني، فتدرس فيهما مع طلاب الكليات الثلاث جميعًا.</p>\n<table><thead><tr><th>المستوى</th><th>المقررات</th></tr></thead><tbody>\n<tr><td>١</td><td>المهارات اللغوية، مهارات جامعية، السيرة النبوية، المدخل إلى الحديث النبوي، توحيد ١، المدخل لدراسة الفقه، الفقه ١، القرآن الكريم ١، التجويد، المدخل إلى دراسة الأنظمة</td></tr>\n<tr><td>٢</td><td>ريادة الأعمال والابتكار، أصول الدعوة وطرقها، المقدمة في مصطلح الحديث، توحيد ٢، مدخل إلى تفسير القرآن وعلومه، الفقه ٢، القرآن الكريم ٢، النحو ١</td></tr>\n</tbody></table>\n<h2>كلية العقيدة والدعوة</h2>\n<p>بعد السنة الأولى المشتركة تدرس مقررًا في التوحيد في كل مستوى حتى «توحيد ٨»، إلى جانب الفرق والأديان والمذاهب المعاصرة وتاريخ الدعوة ومناهجها والجدل والمنطق. الكتب: <a href=\"/ar/library/dawah\">قسم الدعوة في المكتبة</a>.</p>\n<table><thead><tr><th>المستوى</th><th>المقررات</th></tr></thead><tbody>\n<tr><td>١ و٢</td><td>السنة الأولى المشتركة، المذكورة أعلاه</td></tr>\n<tr><td>٣</td><td>أصول الدعوة ١، تاريخ الدعوة ١، تطبيقات التقنية الحديثة في الدعوة، توحيد ٣، الفرق ١، مناهج البحث، أحاديث الأحكام: عبادات، التفسير ١، القرآن الكريم ٣، النحو ٢</td></tr>\n<tr><td>٤</td><td>تاريخ الدعوة ٢، الحسبة، أصول الدعوة ٢، توحيد ٤، الفرق ٢، التخريج، أحاديث الأحكام: معاملات، التفسير ٢، القرآن الكريم ٤، النحو ٣</td></tr>\n<tr><td>٥</td><td>نصوص الدعوة في القرآن والسنة، أصول الدعوة ٣، الأديان ١، المذاهب والتيارات المعاصرة ١، توحيد ٥، الفرق ٣، قيم إسلامية، حديث تحليلي، التفسير ٣، القرآن الكريم ٥</td></tr>\n<tr><td>٦</td><td>أصول الدعوة ٤، فقه الدعوة ١، الأديان ٢، المذاهب والتيارات المعاصرة ٢، توحيد ٦، الفرق ٤، أصول الفقه ١، تاريخ المملكة، التفسير الموضوعي، القرآن الكريم ٦</td></tr>\n<tr><td>٧</td><td>التدريب الدعوي، فقه الدعوة ٢، البحث العلمي في الدعوة، الأديان ٣، المذاهب والتيارات المعاصرة ٣، توحيد ٧، الجدل والمنطق ١، أصول الفقه ٢، الفرائض، القرآن الكريم ٧</td></tr>\n<tr><td>٨</td><td>دراسات استشراقية، وسائل الدعوة وأساليبها، اقتصاديات الدعوة، توحيد ٨، الجدل والمنطق ٢، البحث العلمي في العقيدة، اعتقاد الأئمة الأربعة، الجماعات والحركات الإسلامية المعاصرة، القواعد الفقهية، القرآن الكريم ٨</td></tr>\n</tbody></table>\n<h2>كلية الشريعة</h2>\n<p>تدرس الفقه وأصول الفقه وآيات الأحكام وأحاديثها إلى جانب الأنظمة السعودية من فصلك الأول، مع تدريب تعاوني في المستويين السادس والسابع، وبحثين علميين. الكتب: <a href=\"/ar/library/sharia\">قسم الشريعة في المكتبة</a>.</p>\n<table><thead><tr><th>المستوى</th><th>المقررات</th></tr></thead><tbody>\n<tr><td>١</td><td>المدخل لدراسة أصول الفقه، المدخل إلى الحديث النبوي، علوم القرآن، فقه العبادات ١، التنظيم القضائي، التحرير العربي، النحو ١، توحيد ١، المدخل لدراسة الفقه، القرآن الكريم ١، المدخل إلى دراسة الأنظمة</td></tr>\n<tr><td>٢</td><td>الحكم الشرعي، المقدمة في مصطلح الحديث، أحاديث الأحكام ١، المدخل إلى علم التفسير، فقه العبادات ٢، القضاء الإداري، النظام الدستوري، تاريخ المملكة، قيم إسلامية، أصول الدعوة وطرقها، توحيد ٢، القرآن الكريم ٢</td></tr>\n<tr><td>٣</td><td>أدلة الأحكام ١، مناهج البحث ومصادر في العلوم الشرعية، أحاديث الأحكام ٢، تفسير آيات الأحكام ١، فقه العبادات ٣، النحو ٢، النظام الدولي الخاص، نظم الزكاة والضرائب، النظام الإداري، توحيد ٣، القرآن الكريم ٣</td></tr>\n<tr><td>٤</td><td>أدلة الأحكام ٢، الجدل والخلاف والمناظرة، أحاديث الأحكام ٣، تفسير آيات الأحكام ٢، فقه العبادات ٤، نظام المرافعات الشرعية، النحو ٣، النظام الدولي العام، نظام المحاكم التجارية، القرآن الكريم ٤</td></tr>\n<tr><td>٥</td><td>أدلة الأحكام ٣، تفسير آيات الأحكام ٣، الفرائض ١، فقه الأسرة، نظام الأحوال الشخصية، نظام الأوراق التجارية والإفلاس، المذاهب والتيارات المعاصرة، الأديان والفرق، التخريج، القرآن الكريم ٥</td></tr>\n<tr><td>٦</td><td>دلالات الألفاظ ١، فقه الأطعمة والأيمان والنذور، الفرائض ٢، التدريب التعاوني، فقه المعاملات ١، فقه القضاء، نظام الإثبات، العقود التجارية وعمليات البنوك، نظام العمل والتأمينات الاجتماعية، الصياغة القانونية، القرآن الكريم ٦</td></tr>\n<tr><td>٧</td><td>القواعد الفقهية ١، تخريج الفروع على الأصول، دلالات الألفاظ ٢، الفرائض ٣، بحث فقه، فقه المعاملات ٢، التدريب التعاوني ٢، نظام الشركات، نظام التنفيذ، نظام المحاماة، القرآن الكريم ٧</td></tr>\n<tr><td>٨</td><td>القواعد الفقهية ٢، الاجتهاد، مقاصد الشريعة، بحث أصول الفقه، فقه الحدود والجنايات، فقه النوازل، نظام المعاملات المدنية، النظام الجنائي، نظام الإجراءات الجزائية، تطبيقات الذكاء الاصطناعي، القرآن الكريم ٨</td></tr>\n</tbody></table>\n<h2>كلية اللغة العربية والعلوم الإنسانية</h2>\n<p>بعد السنة الأولى المشتركة تدرس النحو والصرف في كل مستوى تقريبًا، والبلاغة بفروعها الثلاثة، والأدب من العصر الجاهلي إلى يومنا، وعلم اللغة والإعلام. وتمتد مقررات القرآن الكريم إلى المستوى الرابع، وتُختم الدرجة بمشروع تخرج. الكتب: <a href=\"/ar/library/arabic\">قسم اللغة العربية في المكتبة</a>.</p>\n<table><thead><tr><th>المستوى</th><th>المقررات</th></tr></thead><tbody>\n<tr><td>١ و٢</td><td>السنة الأولى المشتركة، المذكورة أعلاه</td></tr>\n<tr><td>٣</td><td>علم المعاني ١، الأدب الجاهلي، النصوص الأدبية ١، النحو ٢، نشأة النحو، الصرف ١، المهارات اللغوية ٢، تاريخ المملكة، قيم إسلامية، الأديان والفرق، القرآن الكريم ٣</td></tr>\n<tr><td>٤</td><td>علم المعاني ٢، أدب صدر الإسلام وبني أمية، النصوص الأدبية ٢، صناعة المحتوى الإعلامي ١، علم الأصوات، النحو ٣، الصرف ٢، المهارات اللغوية ٣، علم الدلالة، علم المعاجم، القرآن الكريم ٤</td></tr>\n<tr><td>٥</td><td>علم المعاني ٣، الأدب العباسي، النصوص الأدبية ٣، مقدمة في الاتصال، النحو ٤، الصرف ٣، مناهج البحث في اللغة، فقه اللغة، اللهجات العربية</td></tr>\n<tr><td>٦</td><td>مناهج البحث في الأدب، علم البيان ١، الأدب الأندلسي، النقد القديم، النصوص الأدبية ٤، الإعلام الجديد، الاستوديوهات التلفزيونية، النحو ٥، العروض والقافية، الصرف ٤، علم اللغة العام</td></tr>\n<tr><td>٧</td><td>أدب الدول المتتابعة، النصوص الأدبية ٥، علم البيان ٢، إعجاز القرآن، النقد الحديث ١، الأدب المقارن، الترجمة الأدبية، صناعة المحتوى الإعلامي ٢، النحو ٦، الصرف ٥، علم اللغة التطبيقي</td></tr>\n<tr><td>٨</td><td>النصوص الأدبية ٦، علم البديع، تحليل الخطاب، النقد الحديث ٢، الأدب السعودي، النحو ٧، مشروع التخرج، علم اللغة الحاسوبي، علم اللغة الاجتماعي</td></tr>\n</tbody></table>\n<h2>كلية الأعمال: الاقتصاد</h2>\n<p>بعد السنة الأولى المشتركة تسير مقررات الاقتصاد والتمويل والمحاسبة والإحصاء جنبًا إلى جنب مع أصول الفقه وفقه المعاملات والزكاة. وتمتد مقررات القرآن الكريم إلى «القرآن الكريم ٤»، ويضم المستوى الأخير مقررًا في المصطلحات الاقتصادية بالإنجليزية ومقررًا في البحث والتدريب.</p>\n<table><thead><tr><th>المستوى</th><th>المقررات</th></tr></thead><tbody>\n<tr><td>١ و٢</td><td>السنة الأولى المشتركة، المذكورة أعلاه</td></tr>\n<tr><td>٣</td><td>أصول الفقه، مبادئ الاقتصاد الجزئي، الرياضيات للاقتصاديين، أصول الاقتصاد الإسلامي، فقه الزكاة والوقف، قيم إسلامية، النحو ٢</td></tr>\n<tr><td>٤</td><td>أحاديث الأحكام: معاملات، فقه المعاملات، التحليل الاقتصادي الجزئي، مبادئ الاقتصاد الكلي، مبادئ الإحصاء، مبادئ إدارة الأعمال، تاريخ المملكة، أخلاقيات المهنة، القرآن الكريم ٣</td></tr>\n<tr><td>٥</td><td>التحليل الاقتصادي الكلي، النقود والبنوك، المالية العامة، مبادئ التمويل والاستثمار، مبادئ المحاسبة المالية، تطور الفكر الاقتصادي، اقتصاديات الموارد والبيئة، القرآن الكريم ٤</td></tr>\n<tr><td>٦</td><td>القواعد الفقهية، اقتصاديات الزكاة والوقف، الإحصاء التطبيقي، الأسواق المالية، التمويل الإسلامي، مبادئ التسويق، القانون التجاري، البلاغة</td></tr>\n<tr><td>٧</td><td>مقاصد الشريعة، تحليل التقارير المالية، المخاطر والتأمين، عمليات المصارف الإسلامية، التنمية والتخطيط الاقتصادي، الاقتصاد القياسي، السياسة الشرعية، مناهج البحث</td></tr>\n<tr><td>٨</td><td>المذاهب والتيارات المعاصرة، التجارة الخارجية، دراسة الجدوى وتقييم المشروعات، مصطلحات اقتصادية بالإنجليزية، الاقتصاد السعودي، بحث وتدريب، الهندسة المالية</td></tr>\n</tbody></table>\n<h2>كلية الأنظمة والدراسات القضائية</h2>\n<p>تسير الأنظمة السعودية والفقه معًا من المستوى الأول، وينضم إليهما أصول الفقه من المستوى الثاني. وتمتد مقررات القرآن الكريم إلى المستوى الرابع، وفي كل مستوى من المستويات الثلاثة الأخيرة مقرر اختياري واحد. الكتب: <a href=\"/ar/library/law\">قسم الأنظمة والقانون في المكتبة</a>.</p>\n<table><thead><tr><th>المستوى</th><th>المقررات</th></tr></thead><tbody>\n<tr><td>١</td><td>القرآن الكريم ١، المدخل لدراسة الفقه، المدخل لدراسة الأنظمة، مبادئ علم الاقتصاد، قيم إسلامية، التحرير العربي، التوحيد ١، النحو ١، السيرة النبوية</td></tr>\n<tr><td>٢</td><td>القرآن الكريم ٢، أصول الفقه ١، تفسير آيات الأحكام، فقه العبادات، السياسة الشرعية، تاريخ المملكة، علم الإجرام والعقاب، التنظيم القضائي، النحو ٢</td></tr>\n<tr><td>٣</td><td>القرآن الكريم ٣، أصول الفقه ٢، النظام التجاري، النظام الدستوري، فقه المعاملات، مصادر الالتزام، النحو ٣، التوحيد ٢</td></tr>\n<tr><td>٤</td><td>القرآن الكريم ٤، أحاديث الأحكام، النظام الإداري، النظام الجزائي العام، أحكام الالتزام، فقه الجنايات والحدود، وسائل الإثبات، الأديان والفرق</td></tr>\n<tr><td>٥</td><td>فقه الأحوال الشخصية، العقود المدنية، العقود الإدارية، نظام الشركات، المرافعات الشرعية، النظام الجنائي الخاص، المالية العامة، مناهج البحث</td></tr>\n<tr><td>٦</td><td>فقه الأوقاف والوصايا، الأوراق التجارية والإفلاس، نظام الزكاة والضرائب، الإجراءات الجزائية، القانون الدولي العام، المحاماة والتوثيق، القضاء الإداري، المواريث، مقرر اختياري</td></tr>\n<tr><td>٧</td><td>القواعد الفقهية، العقود التجارية وعمليات البنوك، الحقوق العينية، القانون الدولي الإنساني، القانون الدولي الخاص، بحث وتدريب، مقرر اختياري</td></tr>\n<tr><td>٨</td><td>مقاصد الشريعة، نظام العمل والتأمينات الاجتماعية، الوسائل البديلة لفض المنازعات، الملكية الفكرية والتجارية، نظام التنفيذ، أصول الصياغة القانونية، تحليل الخطاب، مقرر اختياري</td></tr>\n</tbody></table>\n<blockquote><p>نصيحة: لا تعرف ما المقررات التي عليك هذا الفصل، أو أين تجد كتب مقرر ما؟ راسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "women-at-masjid-an-nabawi": {
  "titleAr": "المسجد النبوي للأخوات والأسر",
  "summaryAr": "أبواب النساء ومصلياتهن، وحجز الروضة للمرأة، ومراكز الأطفال، والكراسي المتحركة والمصاعد، والأطفال المفقودون، ومكتبة النساء، والدروس وحلقات القرآن.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. في المسجد النبوي أقسام واسعة للنساء لها أبوابها وميضآتها وموظفاتها، وعون كثير للأسر التي معها أطفال أو والدان مسنان أو من يحتاج كرسيًا متحركًا. وكثير من الأخوات يصلين فيه يوميًا ويلتحقن بحلقات القرآن ويتابعن الدروس. وهذه الملاحظات للزيارات الأولى وللاعتياد على روتين.</p>\n<h2>أبواب النساء ومصلياتهن</h2>\n<ul>\n<li>تدخل النساء من أبوابهن الخاصة. والأبواب ٢٥ و٢٩ و٤١ مداخل للنساء.</li>\n<li>مصليات النساء في الجهة الغربية، من البابين ١٣ و17D، وفي الجهة الشمالية، من الأبواب ٢٣ إلى 31B، مع مناطق للنساء في الساحات. وهي مفصولة بحواجز ومعلّمة باللوحات.</li>\n<li>تفحص الموظفات الحقائب عند الباب. ويتغير استعمال الأبواب أثناء أعمال البناء وفي المواسم المزدحمة، فاتبعي لوحات اليوم.</li>\n<li>ميضآت النساء ودورات مياههن بجوار أقسام النساء. وبعضها تحت الأرض يُنزل إليه بمنحدرات في الساحات. وفي دورات مياه النساء أرفف لتغيير حفاض الرضيع.</li>\n<li>احفظي رقم الباب الذي دخلتِ منه. فالأبواب متشابهة، والرقم أسهل طريق للعودة إلى أسرتك.</li>\n</ul>\n<blockquote><p>نصيحة: اتفقي مع زوجك أو أسرتك على باب للقاء قبل أن تفترقوا. فإشارة الجوال تضعف حين يمتلئ المسجد.</p></blockquote>\n<h2>زيارة الروضة للمرأة</h2>\n<p>تزور النساء الروضة في أوقاتهن المحددة، منفصلة عن الرجال. والدخول بتصريح مجاني من تطبيق نسك أو موقعه فقط.</p>\n<ol>\n<li>افتحي <strong>نسك</strong> وسجلي الدخول. المقيمات يستعملن نفاذ، والزائرات من الخارج رقم الجواز والبريد الإلكتروني.</li>\n<li>اذهبي إلى الخدمات، ثم تصاريح المسجد النبوي، ثم <strong>زيارة الروضة الشريفة</strong>، واختاري فئة <strong>النساء</strong>.</li>\n<li>اختاري التاريخ والموعد. مواعيد النساء في الصباح وفي آخر الليل. ويعرض التطبيق الأوقات المتاحة للنساء فقط، والوقت المطبوع في تصريحك هو المعتبر. ويصدر التصريح في الحال.</li>\n<li>ويعرض التطبيق أيضًا كم تصريحًا تستطيعين حجزه. فإن لم يكن موعد متاحًا فجربي خيار <strong>الفوري</strong>، الذي يطرح مواعيد خلال اليوم للقريبات من المسجد ممن فعّلن خدمة الموقع، أو انضمي إلى قائمة الانتظار.</li>\n<li>احضري قبل الموعد بقليل واتبعي المنظمات إلى الصف. وتوقعي انتظار نحو ٢٠ دقيقة قبل الدخول.</li>\n<li>أبقي التصريح مفتوحًا على جوالك، مع لقطة شاشة إن أبطأ التطبيق عند الباب. ويُلغى التصريح إن فاتك وقتك.</li>\n</ol>\n<p>وفي الداخل صلي ركعتين وادعي بهدوء، ثم أفسحي المكان للأخت التالية. واخفضي صوتك، ولا تزاحمي، ولا تمسحي الجدران أو التجهيزات طلبًا للبركة.</p>\n<h2>المجيء مع الأطفال</h2>\n<ul>\n<li><strong>مراكز الأطفال:</strong> يدير المسجد مراكز لضيافة الأطفال في الساحات، تعتني فيها الموظفات بالصغار وأنتِ تصلين. تستقبل الأولاد حتى ست سنوات والبنات حتى تسع، وفيها ساحات لعب وأنشطة وحلقة لحفظ قصار السور. أحضري هويتك، فهي مطلوبة لترك الطفل ولاستلامه.</li>\n<li><strong>المكتبة:</strong> في مكتبة المسجد النبوي قاعات قراءة للأطفال.</li>\n<li><strong>الأطفال المفقودون:</strong> في كل من مصليي النساء الشرقي والغربي مكتب للأطفال المفقودين، والمكتب الرئيسي عند جدار البقيع مقابل باب الساحة 34C. اكتبي رقم جوالك على بطاقة في جيب طفلك.</li>\n<li><strong>أين تجلسين:</strong> مع الأطفال الصغار يسهّل مكان قرب آخر القسم الخروج بلا إزعاج للأخريات. وحمّالة الرضيع أيسر من العربة في الزحام.</li>\n</ul>\n<h2>الوالدان المسنان والكراسي المتحركة</h2>\n<ul>\n<li>تُعار الكراسي المتحركة مجانًا من مكتب إدارة الأبواب عند الباب ٧، وتنقل العربات الكهربائية المسنين وذوي الإعاقة في الساحات الخارجية.</li>\n<li>المصاعد الكهربائية عند الباب ٩ في الجهة الشرقية والباب ٣٣ في الجهة الغربية تصعد إلى السطح، وبجوار المداخل منحدرات.</li>\n<li>دورات مياه مخصصة للمسنين وذوي الإعاقة موزعة حول المسجد.</li>\n<li>للصم غرفة على السطح الغربي تُترجم فيها خطبة الجمعة إلى لغة الإشارة.</li>\n<li>مركزان صحيان مفتوحان على مدار الساعة: عند باب جبريل (٣٥٥) وعند الصافية (٣٠٥).</li>\n</ul>\n<h2>الحقائب والأمانات والعون</h2>\n<ul>\n<li>احملي حقيبة صغيرة بسحّاب. تُفحص الحقائب عند الباب، وتوضع الأحذية على الأرفف في الداخل، فكيس الأحذية يعين.</li>\n<li>مركز حفظ الأمانات المجاني يحفظ الحقائب حتى أربع ساعات على مدار الساعة.</li>\n<li>للهيئة العامة للعناية بشؤون الحرمين رقم موحد <strong>1966</strong>. وفي الطوارئ اتصلي بالرقم 997 للإسعاف أو 911.</li>\n<li>يُدخل إلى المواقف من مدخل أبي بكر الصديق في الجهة الشمالية، ومدخل قباء وطريق الأمير عبدالمحسن في الجهة الجنوبية، ومدخل عمر بن الخطاب في الجهة الغربية، وفيها أجهزة دفع ذاتي.</li>\n</ul>\n<h2>مكتبة النساء</h2>\n<p>مكتبة المسجد النبوي مفتوحة كل يوم على مدار الساعة. ومكتبة النساء عند مصليات النساء قرب البابين ٢٤ و١٦. والحقائب والطعام غير مسموح بها، والحواسيب المحمولة تحتاج تصريحًا. انظري <a href=\"/ar/ask/library-bags-laptops\">هل يمكنني إدخال حقيبة أو حاسوب محمول إلى المكتبات؟</a></p>\n<h2>متابعة الدروس</h2>\n<ul>\n<li>دروس المشايخ في القاعة الرئيسية تُبث على مكبرات المسجد، فتستطيع الأخوات متابعتها من أقسام النساء القريبة. وكثير منها يُبث مباشرة أيضًا: انظري <a href=\"/ar/duroos/live\">البث المباشر</a>.</li>\n<li>الدروس التي تلقيها النساء للنساء، في الحرم وفي مساجد المدينة، مدرجة في <a href=\"/ar/duroos/sisters\">دروس الأخوات</a>.</li>\n<li>خذي دفترًا والكتاب الذي يُشرح. فمعظم الدروس بالعربية، ومتابعة النص أفضل طريق للتعلم.</li>\n</ul>\n<h2>حلقات القرآن والدراسة</h2>\n<p>يقيم الحرم حلقات مجانية للأخوات والفتيات: حفظ القرآن، وتصحيح التلاوة، وحفظ المتون العلمية.</p>\n<ol>\n<li>افتحي موقع الحلقات <a href=\"https://qm.edu.sa/\">qm.edu.sa</a> واختاري القسم النسائي.</li>\n<li>اختاري البرنامج: الحفظ أو تصحيح التلاوة أو المتون.</li>\n<li>سجلي على <a href=\"https://reg.qm.edu.sa/\">reg.qm.edu.sa</a> ببياناتك، ثم احضري في الأيام والأوقات التي تُعطينها.</li>\n</ol>\n<p>وللدراسة المتفرغة يقدم معهد المسجد النبوي وكليته للنساء دبلومات مجانية ودرجة في الشريعة، بفترة تسجيل واحدة في السنة في صفر. انظري <a href=\"/ar/programs/nabawi-women\">برامج المسجد النبوي للنساء</a> و<a href=\"/ar/guides/masjid-an-nabawi-institute-and-college\">معهد المسجد النبوي وكلية المسجد النبوي</a>. والخيارات الأخرى للأخوات في <a href=\"/ar/programs\">الدراسة في المدينة</a>.</p>\n<h2>الجمعة ورمضان والليالي المزدحمة</h2>\n<ul>\n<li>تمتلئ أقسام النساء مبكرًا قبل الجمعة والتراويح والصلوات الكبرى. احضري قبلها بثلاثين إلى خمس وأربعين دقيقة إن أردتِ مكانًا قرب المقدمة.</li>\n<li>تنشر الهيئة مستوى امتلاء كل مصلى مباشرة على <a href=\"https://alharamain.gov.sa/public/?module=prayers_ar\">alharamain.gov.sa</a>. راجعيه قبل أن تخرجي يوم الجمعة أو في رمضان.</li>\n<li>أحضري سجادة خفيفة للساحات. فالرخام حار في ظهيرة الصيف وبارد في ليالي الشتاء.</li>\n</ul>\n<h2>قباء والبقيع</h2>\n<ul>\n<li>مسجد قباء لا يحتاج حجزًا، وتصلي فيه الأخوات في قسمهن. انظري <a href=\"/ar/guides/umrah-rawdah-quba\">العمرة والروضة وقباء</a>.</li>\n<li>البقيع مفتوح للرجال فقط. وتستطيع النساء رؤيته من خارج السور.</li>\n</ul>\n<p>ولما في داخل المسجد والساحات انظري <a href=\"/ar/guides/masjid-an-nabawi-first-visit\">زيارة المسجد النبوي: دليل الزيارة الأولى</a>.</p>\n<blockquote><p>نصيحة: سؤال لم نجب عنه هنا؟ راسلي المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 },
 "your-first-semester-week-by-week": {
  "titleAr": "فصلك الأول في الجامعة أسبوعًا بأسبوع",
  "summaryAr": "ما يجري في الفصل الأول للطالب الجديد ومتى: التهيئة وبطاقتاك، وقراءة جدولك الثابت، وقواعد الحضور، وأول مكافأة، والاختبارات الشهرية، وتقييم المقررات، والاختبارات النهائية، مع مواعيد الفصل الأول من عام ١٤٤٨.",
  "bodyHtmlAr": "<p>روجع في ٩ نوفمبر ٢٠٢٦. كل فصل أول في الجامعة الإسلامية يسير على النمط نفسه. وهذا الدليل يمضي بك فيه أسبوعًا بأسبوع، متخذًا الفصل الأول من عام ١٤٤٨ مثالًا، لتعرف ما هو آتٍ قبل أن يأتي. ويبدأ من حيث ينتهي دليل <a href=\"/ar/guides/new-student-steps\">الخطوات الأولى للطلاب الجدد</a>: أي إنك أنهيت الشريحة وأبشر ونفاذ وهوية الزائر.</p>\n<h2>الفصل في لمحة</h2>\n<table><thead><tr><th>متى</th><th>ما يجري</th><th>الفصل الأول ١٤٤٨</th></tr></thead><tbody>\n<tr><td>الأسبوع الذي يسبق الدراسة</td><td>تُنشر الجداول. ويحذف الطلاب المستمرون المقررات ويضيفونها</td><td>الجداول يوم الاثنين ١٠ أغسطس ٢٠٢٦، ثم الحذف والإضافة في الأيام التي تسبق الدراسة، ويُفتح على دفعات بحسب الرقم الجامعي</td></tr>\n<tr><td>الأسبوع الأول</td><td>تبدأ الدراسة. وتُقام التهيئة للطلاب الجدد، وفيها تستلم بطاقتك الجامعية وبطاقة مكافأتك</td><td>الدراسة من الأحد ١٦ أغسطس، والتهيئة يوم الاثنين ١٧ أغسطس ٢٠٢٦</td></tr>\n<tr><td>من الأسبوع الثاني إلى الخامس</td><td>توصيف المقررات، والكتب، وبلاك بورد، وأول تسجيلات الحضور</td><td>من ٢٣ أغسطس إلى ١٧ سبتمبر</td></tr>\n<tr><td>الأسبوع السادس</td><td>إجازة اليوم الوطني، وهي الإجازة الوحيدة في الفصل الأول</td><td>من الأربعاء ٢٣ إلى السبت ٢٦ سبتمبر ٢٠٢٦</td></tr>\n<tr><td>الشهر الثاني</td><td>تصل أول مكافأة لك، وفيها مكافأة شهرين معًا</td><td>السبت ١٩ والأحد ٢٠ سبتمبر ٢٠٢٦</td></tr>\n<tr><td>من الأسبوع الرابع إلى الرابع عشر</td><td>الاختبارات الشهرية، وإنذارات الغياب لمن يتغيب عن المحاضرات</td><td>من سبتمبر إلى نوفمبر</td></tr>\n<tr><td>الأسبوع الثاني عشر</td><td>آخر يوم يستطيع فيه الطلاب المستمرون الانسحاب من مقرر أو الاعتذار عن الفصل</td><td>الخميس ٥ نوفمبر ٢٠٢٦</td></tr>\n<tr><td>الأسبوعان الرابع عشر والخامس عشر</td><td>يظهر جدول الاختبارات النهائية. وعليك إكمال تقييم مقرراتك</td><td>نوفمبر</td></tr>\n<tr><td>من الأسبوع السادس عشر إلى الثامن عشر</td><td>الاختبارات النهائية</td><td>من الأحد ٢٩ نوفمبر إلى الاثنين ١٤ ديسمبر ٢٠٢٦</td></tr>\n<tr><td>إجازة نهاية الفصل</td><td>إجازة قصيرة، ثم الفصل الثاني</td><td>الإجازة من ١٥ إلى ١٩ ديسمبر، والفصل الثاني من الأحد ٢٠ ديسمبر ٢٠٢٦</td></tr>\n</tbody></table>\n<p>وكل مواعيد العام في <a href=\"/ar/guides/university-calendar-1448\">التقويم الجامعي</a>.</p>\n<h2>الأسبوع الأول: التهيئة وبطاقتاك</h2>\n<ul>\n<li><strong>التهيئة</strong> للطلاب الجدد تُقام في الأسبوع الأول، ويُعلن عنها في حساب الجامعة الرسمي في إكس. وفي عام ١٤٤٨ كانت يوم الاثنين ١٧ أغسطس في قاعة السلام.</li>\n<li><strong>تستلم هناك بطاقتين:</strong> بطاقتك الجامعية، وبطاقة المكافأة البنكية. فأحضر صورة شخصية مقاس ٤×٦ مصوّرة في استوديو تصوير.</li>\n<li><strong>وهويتك الجامعية رقمية أيضًا</strong> في تطبيق توكلنا. والبطاقة المطبوعة نافعة داخل الحرم الجامعي، وإن فقدتها استُخرج لك بدلها في الوحدة ٢٢: انظر <a href=\"/ar/guides/lost-your-iqama-passport-or-card\">فقدت جوازك أو إقامتك أو جوالك أو بطاقتك الجامعية؟</a></li>\n<li><strong>بطاقة المكافأة</strong> بطاقة من مصرف الراجحي تفعّلها لك الجامعة. والرقم السري في الظرف. وطريقة استعمالها في <a href=\"/ar/guides/getting-your-stipend-off-the-university-card\">بطاقة مكافأتك الجامعية</a>.</li>\n</ul>\n<h2>الأسبوع الأول: قراءة جدولك</h2>\n<p>جدولك في النظام الأكاديمي تحت <strong>التسجيل الإلكتروني</strong>، ثم <strong>المقررات المسجلة</strong>، وفيه زر للطباعة. ويعرض تطبيق الجامعة الجدول نفسه مرتبًا بالأيام. انظر <a href=\"/ar/ask/find-my-timetable\">أين أجد جدول محاضراتي؟</a></p>\n<table><thead><tr><th>في الجدول</th><th>معناه</th></tr></thead><tbody>\n<tr><td>اليوم ١، ٢، ٣، ٤، ٥</td><td>الأحد، الاثنين، الثلاثاء، الأربعاء، الخميس</td></tr>\n<tr><td>القاعة</td><td>المبنى، باسم الكلية. فـ«الدعوة» تعني مبنى كلية الدعوة</td></tr>\n<tr><td>الشعبة</td><td>مجموعتك في ذلك المقرر، وتظهر منفصلة عن القاعة</td></tr>\n<tr><td>لم يُحدَّد الأستاذ</td><td>لم يُدخَل اسم الأستاذ بعد، ويُستكمل خلال الأسابيع الأولى</td></tr>\n</tbody></table>\n<ul>\n<li><strong>جدولك الأول ثابت.</strong> ففي الفصل الأول تعطي الجامعة كل طالب جديد جدولًا جاهزًا، ولا تستطيع إضافة مقرر ولا حذفه ولا الانسحاب منه. ومن الفصل الثاني تختار شعبك وأوقاتك بنفسك في الحذف والإضافة.</li>\n<li><strong>محاضرات ما بعد الظهر أمر عادي.</strong> فجداول كثير من الطلاب الجدد تبدأ الساعة ١ ظهرًا.</li>\n<li><strong>احضر كل محاضرة من اليوم الأول.</strong> فقليل من الأساتذة يشرح درسًا كاملًا في الأسبوع الأول، لكن بعضهم يسجل الحضور من اليوم الأول، والغياب في الأسبوع الأول يُحسب كالغياب في الأسبوع العاشر.</li>\n</ul>\n<h2>من الأسبوع الثاني إلى الخامس: الاستقرار في مقرراتك</h2>\n<ul>\n<li><strong>توصيف المقرر:</strong> يوزع الأساتذة توصيف المقرر عادةً في الأسبوع الأول. وكثير من الكليات تنشره أيضًا في قنواتها، أو في رمز QR داخل القاعة، أو على بلاك بورد. ويبين أيضًا المتطلبات السابقة لكل مقرر.</li>\n<li><strong>مجموعة شعبتك:</strong> لأكثر الشعب مجموعة على واتساب أو تيليجرام يديرها طالب هو رئيس الشعبة، ينقل إعلانات الأستاذ ومواعيد الاختبارات والدرجات. فاسأل عنها في أول محاضرة. ويبقى النظام الأكاديمي وبريدك الجامعي هما المرجع الرسمي، ولا يكون رابط منشور في مجموعة سببًا أبدًا لكتابة كلمة مرورك.</li>\n<li><strong>الكتب:</strong> انظر <a href=\"/ar/ask/muqarrarat\">ما المقررات؟</a></li>\n<li><strong>بلاك بورد:</strong> مواد المحاضرات والاختبارات الشهرية والإعلانات. وإن لم تستطع الدخول فانظر <a href=\"/ar/ask/blackboard-login\">كيف أدخل إلى بلاك بورد؟</a></li>\n<li><strong>خطتك الدراسية</strong> في النظام الأكاديمي تحت <strong>أكاديمي</strong>، ثم <strong>خطة الطالب</strong>. وتعرض كل مقرر ستدرسه، مستوى بعد مستوى، والمتطلب السابق لكل مقرر.</li>\n<li><strong>اسم مرشدك الأكاديمي</strong> تحت <strong>أكاديمي</strong>، ثم <strong>التواصل مع المرشد الأكاديمي</strong>. وللمشكلة العاجلة اذهب إلى وكيل كليتك.</li>\n<li><strong>الوجبات:</strong> احجز وجباتك في المطعم الجامعي شهرًا بشهر. انظر <a href=\"/ar/guides/campus-life-islamic-university\">حياة الطالب في الجامعة الإسلامية</a>.</li>\n</ul>\n<h2>الحضور: القاعدة التي يقع فيها الطلاب الجدد</h2>\n<p>إذا تجاوز غيابك في مقرر ٢٥٪ من ساعاته صرت محرومًا من اختباره النهائي، ويُسجَّل المقرر راسبًا بتقدير DN.</p>\n<ul>\n<li><strong>مثال محسوب:</strong> مقرر يُدرَّس ساعتين في الأسبوع على مدى ١٥ أسبوعًا، مجموع ساعاته ٣٠ ساعة. فكل محاضرة تغيب عنها ساعتان، أي ٦٫٧٪. والغياب ثلاث مرات يبلغ بك ٢٠٪. والمرة الرابعة تبلغ بك ٢٦٫٧٪، فتتجاوز الحد وتُحرم.</li>\n<li><strong>الإنذارات:</strong> ينذرك النظام الأكاديمي كلما ارتفع غيابك، عند نحو ١٠٪ و١٥٪ و٢٠٪. ويظهر الغياب في التطبيق فور تسجيل الأستاذ له.</li>\n<li><strong>الأعذار:</strong> عند تسجيل غياب يظهر لك رابط حين تدخل. فارفع تقريرك الطبي أو عذرك الرسمي في النظام الأكاديمي تحت <strong>أكاديمي</strong>، ثم <strong>تقديم الأعذار عن غياب المحاضرات</strong>، في المهلة التي تظهر لك. فإن انتهت المهلة فأرسله إلى كليتك عبر تواصل.</li>\n<li><strong>الأعذار الطبية</strong> تُقبل إذا ظهرت في صحتي، ويستطيع المركز الطبي الجامعي كتابة العذر. أما المناسبات العائلية كالأعراس فلا تُقبل.</li>\n</ul>\n<p>والقواعد كاملة في <a href=\"/ar/guides/exams-results-and-attendance\">الاختبارات والنتائج والحضور</a>.</p>\n<h2>الشهر الثاني: أول مكافأة لك</h2>\n<ul>\n<li><strong>لا يُصرف لك شيء في شهرك الأول.</strong> وفي الشهر الثاني تصل مكافأة الشهرين الأولين معًا. وفي عام ١٤٤٨ صُرفت للطلاب الجدد يومي ١٩ و٢٠ سبتمبر ٢٠٢٦.</li>\n<li>وبعد ذلك تصل المكافأة عادةً بين اليوم ٢١ واليوم ٢٥ من كل شهر، وتُصرف مبكرًا قبل اليوم الوطني ويوم التأسيس والعيد.</li>\n<li>فأحضر معك من بلدك ما يكفيك للشهرين الأولين.</li>\n<li>ونقل المال إلى حسابك الخاص، وحل مشكلات البطاقة، في <a href=\"/ar/guides/getting-your-stipend-off-the-university-card\">بطاقة مكافأتك الجامعية</a>. والبدلات التي تُصرف فوق المكافأة في <a href=\"/ar/guides/scholarship-stipend-and-allowances\">مالك من المنحة</a>.</li>\n</ul>\n<h2>من الأسبوع الرابع إلى الرابع عشر: الاختبارات الشهرية</h2>\n<ul>\n<li>في أكثر المقررات تُحسب لأعمال الفصل نحو ٤٠ درجة من ١٠٠، وللاختبار النهائي نحو ٦٠. وأعمال الفصل في الغالب اختبارات شهرية، كثير منها على بلاك بورد.</li>\n<li>ويحدد كل أستاذ اختباراته الشهرية. فإن فاتك اختبار منها لعذر وجيه فقدّم عذرك للأستاذ فورًا.</li>\n<li>ولمقررات القرآن، وللمقررات التي تُدرَّس في شعب كثيرة، اختبار نهائي موحد على مستوى الجامعة كلها. واختبارات القرآن النهائية في الغالب اختيار من متعدد على الورق: إكمال آية، أو تحديد ما قبلها أو ما بعدها.</li>\n</ul>\n<h2>الأسبوعان الرابع عشر والخامس عشر: قبل الاختبارات النهائية</h2>\n<ol>\n<li><strong>اعرف جدول اختباراتك النهائية</strong> في النظام الأكاديمي تحت <strong>أكاديمي</strong>، ثم <strong>الاختبارات النهائية</strong>. ويظهر قبل الاختبارات بأسبوع إلى أربعة أسابيع. واعتمد على هذه الشاشة وحدها، لا على الجداول المتداولة في المجموعات.</li>\n<li><strong>أكمل تقييم المقررات</strong> تحت <strong>أكاديمي</strong>، ثم <strong>تقييم المقررات</strong>، لكل مقرر. فنتائجك، ومنها درجات أعمال الفصل، تبقى مخفية حتى تفعل.</li>\n<li><strong>راجع غيابك</strong> في كل مقرر. فإن كنت محرومًا ولك عذر فقدّمه قبل بدء الاختبارات النهائية.</li>\n<li><strong>اقرأ قواعد يوم الاختبار</strong> في <a href=\"/ar/guides/exams-results-and-attendance\">الاختبارات والنتائج والحضور</a>: كن في القاعة قبل البدء بعشر دقائق، ولا يدخل أحد بعد مضي ثلاثين دقيقة على البدء.</li>\n</ol>\n<h2>من الأسبوع السادس عشر إلى الثامن عشر: الاختبارات النهائية وما بعدها</h2>\n<ul>\n<li>إن منعك مرض أو طارئ من أداء اختبار نهائي فاحصل على الإثبات في اليوم نفسه: انظر <a href=\"/ar/ask/missed-a-final-exam\">فاتني اختبار نهائي، فما الذي يترتب على ذلك؟</a></li>\n<li>وتظهر النتائج في النظام الأكاديمي تحت <strong>نتائج المقررات</strong> بعد أن تعتمدها كليتك. انظر <a href=\"/ar/ask/exam-results-where\">أين أرى نتائج اختباراتي ومعدلي؟</a></li>\n<li>ومن الفصل الثاني تسجل مقرراتك بنفسك في الحذف والإضافة. وفي عام ١٤٤٨ يُفتح في ١٧ ديسمبر ٢٠٢٦.</li>\n<li>وإن احتجت إلى تأجيل الفصل الثاني ففترة التأجيل له في ديسمبر، قبل بدء الدراسة: انظر <a href=\"/ar/guides/tajeel-and-itithaar\">أخذ فصل إجازة</a>.</li>\n</ul>\n<blockquote><p>نصيحة: سجّل المواعيد المهمة في تقويم جوالك من اليوم الأول: اليوم الوطني، وتقييم المقررات، وبداية الاختبارات النهائية، والحذف والإضافة للفصل الثاني. وإن تعثرت في أي أمر في فصلك الأول فراسل المشرف على واتساب على الرقم ‎+1 234 567 9076‎ أو بالبريد <a href=\"mailto:mesh@albaseerah.org\">mesh@albaseerah.org</a>.</p></blockquote>"
 }
};

